window.KURAN_MEALS=window.KURAN_MEALS||{};window.KURAN_MEALS["ynuri"]=[[{"n":1,"t":"Rahman ve Rahîm Allah'ın adıyla..."},{"n":2,"t":"Hamd, âlemlerin Rabbi Allah'adır."},{"n":3,"t":"Rahman'dır, Rahîm'dir O."},{"n":4,"t":"Din gününün Mâlik'i/ sultanıdır O..."},{"n":5,"t":"Yalnız sana ibadet ederiz ve yalnız senden yardım dileriz."},{"n":6,"t":"Dosdoğru giden yola ilet bizi..."},{"n":7,"t":"Kendilerine nimet verdiklerinin, üzerlerine gazap dökülmemişlerin, karanlığa / şaşkınlığa saplanmamışların yoluna..."}],[{"n":1,"t":"Elif, Lâm, Mîm."},{"n":2,"t":"İşte sana o Kitap! Kuşku/ çelişme/ tutarsızlık yok onda. Bir kılavuzdur o, sakınanlar için."},{"n":3,"t":"Ki onlar, gayba inananlar, namazı/duayı yerine getirenlerdir. Ve kendilerine rızık olarak verdiklerimizden, başkalarına pay çıkaranlardır."},{"n":4,"t":"Hem sana vahyedilene hem de senden önce vahyedilene inananlardır onlar. Âhireti gereğince kavrayıp anlayanlar da onlardır."},{"n":5,"t":"İşte bunlardır Rablerinden bir hidayet üzere olanlar, işte bunlardır gerçek anlamda kurtuluşu bulanlar."},{"n":6,"t":"Şu bir gerçek ki, o küfre batmış olanları sen uyarsan da uyarmasan da onlar için aynıdır; iman etmezler."},{"n":7,"t":"Allah onların kalpleri, kulakları üzerine mühür basmıştır. Onların kafa gözleri üstünde de bir perde vardır. Onlar için korkunç bir azap öngörülmüştür."},{"n":8,"t":"İnsanlar içinden bazıları vardır, \"Allah'a ve âhiret gününe inandık!\" derler ama onlar inanmış değillerdir."},{"n":9,"t":"Allah'ı ve inanmış olanları aldatma yoluna giderler. Gerçekte ise onlar öz benliklerinden başkasını aldatmıyorlar. Ne var ki, bunun farkında olamıyorlar."},{"n":10,"t":"Kalplerinde bir hastalık vardır da Allah onları hastalık yönünden daha ileri götürmüştür. Ve onlar için, yalancılık etmiş olmaları yüzünden acıklı bir azap öngörülmüştür."},{"n":11,"t":"Onlara, \"Yeryüzünde bozgun çıkarmayın\" dendiğinde, \"Tam tersine, bizler barış ve esenlik getirenleriz!\" demişlerdir."},{"n":12,"t":"Dikkat edin, gerçekte onlar, bozgun getirenlerin ta kendileridir de bunun bilincinde olmuyorlar."},{"n":13,"t":"Onlara, \"İnsanların inandığı gibi siz de inanın\" dendiğinde, \"Yani biz de kafası çalışmayan zavallılar gibi inanalım mı?\" derler. Haberiniz olsun ki, kafası çalışmayan düşük seviyeliler onların ta kendileridir; fakat bilmiyorlar."},{"n":14,"t":"İnananlarla yüz yüze geldiklerinde, \"İnandık!\" derler. Kendi şeytanlarıyla baş başa kaldıklarında ise, \"Biz sizinle beraberiz, biz sadece alay ediyoruz!\" derler."},{"n":15,"t":"Allah onlarla alay ediyor ve onları, kendi azgınlıkları içinde bocalar bir halde sürüklüyor."},{"n":16,"t":"İşte bunlar, doğruluk ve aydınlığı verip karanlık ve sapıklığı satın aldılar da ticaretleri hiçbir kazanç sağlamadı. Bir yol-yordama girebilmiş de değillerdir."},{"n":17,"t":"Onların durumu şu kişinin durumuna benzer: Bir ateş tutuşturmak istedi. Ateş, çevresindekileri aydınlattığında, Allah onların ışığını giderdi ve onları karanlıklar içinde bıraktı; artık görmezler."},{"n":18,"t":"Sağırdırlar, dilsizdirler, kördürler. Onlar artık dönmezler."},{"n":19,"t":"Yahut gökten boşalan bir yağmur haline benzer ki onda karanlıklar var, bir gök gürlemesi var, bir şimşek var. Yıldırımlar yüzünden ölüm korkusuyla parmaklarını kulaklarına tıkarlar. Allah Muhît'tir, küfre sapanları çepeçevre kuşatmıştır."},{"n":20,"t":"Şimşek, neredeyse gözlerini çarpıp götürüverecek. Kendilerine her aydınlık sunduğunda, orada yürürler. Üzerlerine karanlık binince çakılıp kalırlar. Eğer Allah dileseydi, işitme güçlerini de gözlerini de elbette alıp götürürdü. Çünkü Allah her şeye Kadîr'dir."},{"n":21,"t":"Ey insanlar! Sizi de sizden öncekileri de yaratan Rabbinize ibadet edin ki, korunabilesiniz."},{"n":22,"t":"O Rab ki, yeri sizin için bir döşek, göğü de bir bina yaptı. Ve gökten bir su indirdi de onunla sizin için meyvelerden/ürünlerden bir rızık çıkardı. Artık bilip durduğunuz halde Allah'a ortaklar koşmayın."},{"n":23,"t":"Kulumuza indirdiğimizden bir kuşku içindeyseniz, hadi onun benzerinden bir sure getirin! Eğer doğru sözlüler iseniz, Allah dışındaki tanıklarınızı/ destekçilerinizi de çağırın!"},{"n":24,"t":"Eğer yapamazsanız -ki asla yapamayacaksınız- korkun o ateşten ki yakıtı insanlarla taşlardır. Küfre sapanlar için hazırlanmıştır o."},{"n":25,"t":"İman edip hayra/barışa yönelik işler yapanlara şunu müjdele: Kendileri için, altlarından ırmaklar akan cennetler olacaktır. Onlardaki herhangi bir meyveden bir rızık olarak her nasiplendirildiklerinde, şöyle dileyeceklerdir: \"İşte bu, daha önce rızıklandırıldığımız şey!\" Bu rızık onlara buna benzer şekilde verilmişti. Onlar için orada tertemiz eşler de vardır. Ve onlar orada sürekli kalacaklardır."},{"n":26,"t":"Şu bir gerçek ki Allah, bir sivrisineği hatta onun da üstündeki bir varlığı örnek göstermekten sıkılmaz. Böyle bir durumda, inananlar bilirler ki o, Rablerinden bir gerçektir. Küfre sapmışlar ise şöyle derler: \"Allah, bunu örnek vermekle ne demek istedi?\" Allah onunla birçoğunu saptırır, birçoğunu da onunla doğruya ve güzele kılavuzlar. Allah onunla yoldan çıkmışlardan başkasını saptırmaz."},{"n":27,"t":"Onlar ki, Allah'a verdikleri ahdi, onunla anlaşıp bağlandıktan sonra bozar, Allah'ın birleştirilmesini emrettiği şeyi keser ve yeryüzünde bozgun çıkarırlar. İşte bunlardır hüsrana uğrayanlar."},{"n":28,"t":"Allah'a nasıl nankörlük ediyorsunuz/Allah'ı nasıl inkâr ediyorsunuz?! Siz ölülerdiniz, O sizi diriltti. Sizi yine öldürecek ve sonra diriltecektir. Nihayet O'na döndürüleceksiniz."},{"n":29,"t":"O Allah'tır ki, yeryüzündekilerin tümünü sizin için yarattı. Sonra göğe saltanat kurdu da onları yedi gök halinde düzenledi. O Alîm'dir, herşeyi çok iyi bilir."},{"n":30,"t":"Bir zamanlar Rabbin meleklere: \"Ben, yeryüzünde bir halife atayacağım.\" demişti de onlar şöyle konuşmuşlardı: \"Orada bozgunculuk etmekte olan, kan döken birini mi atayacaksın? Oysaki bizler, seni hamd ile tespih ediyoruz; seni kutsayıp yüceltiyoruz.\" Allah şöyle dedi: \"Şu bir gerçek ki ben, sizin bilmediklerinizi bilmekteyim.\""},{"n":31,"t":"Ve Âdem'e isimlerin tümünü öğretti. Sonra onları meleklere göstererek şöyle buyurdu: \"Hadi, haber verin bana şunların isimlerini, eğer doğru sözlüler iseniz.\""},{"n":32,"t":"Dediler ki: \"Yücedir şanın senin. Bize öğretmiş olduğunun dışında bilgimiz yok bizim. Sen, yalnız sen Alîm'sin, herşeyi en iyi şekilde bilirsin; Hakîm'sin, herşeyin bütün hikmetlerine sahipsin.\""},{"n":33,"t":"Allah buyurdu: \"Ey Âdem, haber ver onlara onların adlarını.\" Âdem onlara onların adlarını haber verince, Allah şöyle buyurdu: \"Dememiş miydim ben size! Ki ben, göklerin ve yerin gaybını en iyi bilenim, A'lem'im. Ve ben, sizin açığa vurduklarınızı da saklayageldiklerinizi de en iyi biçimde bilmekteyim.\""},{"n":34,"t":"O vakit biz meleklere, \"Âdem'e secde edin\" demiştik de İblis dışında tümü secde etmişti. İblis yan çizmiş, kibre sapmış ve nankörlerden olmuştu."},{"n":35,"t":"Ve Âdem'e şöyle buyurmuştuk: \"Ey Âdem, sen ve eşin cennete yerleşin ve orada dilediğiniz yerde, bol bol yiyin. Ama şu ağaca yaklaşmayın, yoksa zulme sapanlardan olursunuz.\""},{"n":36,"t":"Bunun üzerine şeytan onların ayaklarını kaydırdı da onları içinde bulundukları yerden çıkardı. Biz de şöyle buyurduk: \"Bir kısmınız bir kısmınıza düşman olarak aşağıya inin. Belli bir süre kadar yeryüzünde sizin için bir bekleme yeri, bir nimet/bir yararlanma imkânı olacaktır.\""},{"n":37,"t":"Bunun üzerine Âdem, Rabbinden bazı kelimeler öğrenip belledi de O'na yöneldi. O da onun tövbesini kabul etti. Gerçekten de O, evet O, Tevvâb'dır, tövbeleri cömertçe kabul eder; Rahîm'dir, rahmetini cömertçe yayar."},{"n":38,"t":"\"Hepiniz oradan aşağı inin.\" dedik. Benden size bir yol gösteriş ulaşır da kim bu yol gösterişime uyarsa artık böylelerine hiçbir korku yoktur. Onlar kederle de yüzyüze gelmeyeceklerdir."},{"n":39,"t":"Nankörlüğe sapıp ayetlerimizi yalanlayanlara gelince onlar, ateşin dostu olacaklardır. Onlar orada sürekli kalacaklardır."},{"n":40,"t":"Ey İsrailoğulları! Size lütfettiğim nimetimi hatırlayın; bana verdiğiniz söze vefalı olun ki, ben de size ahdimde vefalı olayım. Ve yalnız benden korkun."},{"n":41,"t":"Beraberinizdekini doğrulayıcı olarak indirmiş bulunduğuma inanın. Onu ilk inkâr eden siz olmayın. Benim ayetlerimi az bir bedel karşılığı satmayın. Ve yalnız benden sakının."},{"n":42,"t":"Hakkı bâtılla/saçmalık ve tutarsızlıkla kirletmeyin. Bilip durduğunuz halde gerçeği gizliyorsunuz."},{"n":43,"t":"Namazı/duayı yerine getirin, zekâtı verin; rükû edenlerle birlikte rükû edin."},{"n":44,"t":"İnsanlara hayırda erginliği/dürüstlüğü emredip de öz benliklerinizi unutuyor musunuz? Üstelik de Kitap'ı okuyup durmaktasınız. Hâlâ aklınızı kullanmayacak mısınız?"},{"n":45,"t":"Sabra ve namaza/duaya sarılarak yardım dileyin. Hiç kuşkusuz bu, kalbi ürperti duyanlardan başkasına çok ağır gelir."},{"n":46,"t":"O ürperti duyanlar, Rablerine kavuşacaklarını düşünürler ve bilirler ki onlar, mutlaka O'na döneceklerdir."},{"n":47,"t":"Ey İsrailoğulları! Size lütfettiğim nimetimi, sizi âlemlere üstün kıldığımı hatırlayın."},{"n":48,"t":"Ve sakının o günden ki, hiçbir benlik bir başka benliğin herhangi bir şeyi için karşılık ödemez; hiçbir benlikten şefaat kabul edilmez, hiçbir benlikten fidye alınmaz. Ve onlara yardım da edilmez."},{"n":49,"t":"Sizi Firavun hanedanından kurtardığımızı da hatırlayın. Hani, onlar size azabın en çirkiniyle kötülük ediyorlardı: Erkek çocuklarınızı boğazlıyorlar, kadınlarınıza hayasızca davranıyorlar/kadınlarınızın rahimlerini yokluyorlar/kadınlarınızı hayata salıyorlardı. İşte bunda sizin için, Rabbinizden gelen büyük bir ıstırap ve imtihan vardı."},{"n":50,"t":"Hani, önünüzde denizi yarmıştık da sizi kurtarmış, Firavun hanedanını boğmuştuk. Siz de bunu bakıp görüyordunuz."},{"n":51,"t":"Ve Mûsa ile kırk gece için sözleşmiştik de siz bunun ardından buzağıyı tanrı edinmiştiniz. Zulme sapmıştınız siz."},{"n":52,"t":"Belki şükredersiniz diye bunun ardından da sizi affetmiştik."},{"n":53,"t":"İyiye ve güzele yol bulursunuz ümidiyle Mûsa'ya Kitap'ı ve furkanı/hakla bâtılı ayıran mesajı vermiştik."},{"n":54,"t":"Hani, Mûsa, toplumuna demişti ki: \"Ey toplumum, buzağıyı tanrı edinmenizle öz benliklerinize zulmettiniz. Hadi, yaratıcınıza, Bâri'inize tövbe edin; egolarınızı öldürün. Böyle yapmanız yaratıcınız katında sizin için daha iyidir; O sizin tövbelerinizi kabul eder. Hiç kuşkusuz O, evet O, tövbeleri çok kabul edendir, rahmeti sonsuz olandır.\""},{"n":55,"t":"Siz şunu da söylemiştiniz: \"Ey Mûsa! Biz, Allah'ı apaçık görmedikçe sana asla inanmayacağız.\" Bunun üzerine sizi yıldırım çarpmıştı. Ve siz bakıp duruyordunuz."},{"n":56,"t":"Sonra, ölümünüzün ardından sizi dirilttik ki, şükredebilesiniz."},{"n":57,"t":"Ve bulutu üstünüze gölgelik yaptık ve size kudret helvasıyla bıldırcın indirdik: \"Rızık olarak size verdiklerimizin, en temizlerinden yiyin.\" dedik. Onlar zulmü bize yapmadılar, onlar kendi benliklerine zulmetmekteydiler."},{"n":58,"t":"Şöyle demiştik: \"Girin şu kente; orada, dilediğiniz yerde bol bol yiyin. Kapıdan secde ederek girin ve 'Affet bizi!' deyin ki, hatalarınızı bağışlayalım. Biz güzel davranıp, güzellik üretenlere daha fazlasını da veririz.\""},{"n":59,"t":"Ne var ki zulme sapanlar, bir sözü kendilerine söylenmiş olandan başkasıyla değiştirdiler. Bunun üzerine biz, bu zalimler üstüne, ürettikleri kötülüklere karşılık olarak gökten bir pislik indirdik."},{"n":60,"t":"Bir zamanlar Mûsa, toplumu için su istemişti de biz, \"Değneğinle şu taşa vur!\" demiştik. Taştan hemen oniki göze fışkırmıştı. Her bölük insan kendilerine özgü su kaynağını bilmişti. \"Allah'ın rızkından yiyin, için; yeryüzünde bozgunculuk yaparak şuna buna saldırmayın.\" demiştik."},{"n":61,"t":"Siz şöyle demiştiniz: \"Ey Mûsa, biz bir tek yemeğe asla dayanamayız; bizim için Rabbine dua et de bize yerin bitirdiklerinden, baklasından, acurundan, sarmısağından, mercimeğinden, soğanından çıkarıversin.\" Mûsa şöyle demişti: \"Siz daha aşağı bir nimete daha üstün bir nimeti mi değişmek istiyorsunuz? İnin bir kasabaya; istediğiniz sizin olacaktır.\" Ve üzerlerine zillet, eziklik ve yoksulluk damgası vuruldu, Allah'tan bir gazaba çarpıldılar. Bu böyle oldu, çünkü onlar Allah'ın ayetlerini inkâr ediyor ve haksız yere peygamberleri öldürüyorlardı. İsyan ettikleri için böyle oldu. Sınır tanımıyor, azgınlık yapıyorlardı."},{"n":62,"t":"Şu bir gerçek ki, iman edenlerden, Yahudilerden, Hıristiyanlardan, Sâbiîlerden Allah'a ve âhiret gününe inanıp barışa ve hayra yönelik iş yapanların, Rableri katında kendilerine has ödülleri olacaktır. Korku yoktur onlar için, tasalanmayacaklardır onlar."},{"n":63,"t":"Hani, sizden şu şekilde kesin söz almış da Tûr'u üzerinize kaldırmıştık: \"Size verdiğimizi kuvvetle tutun ve içinde olanı hatırlayıp zikredin ki, sakınabilesiniz.\""},{"n":64,"t":"Bunun ardından da yüz çevirip döndünüz. Eğer Allah'ın size lütfu ve rahmeti olmasaydı, kesinlikle hüsrana uğrayanlardan olacaktınız."},{"n":65,"t":"Yemin olsun, içinizden Cumartesi gününde azgınlık yapanları siz bilirsiniz. Onlara şöyle dedik: \"Aşağılık maymunlar oluverin.\""},{"n":66,"t":"Bu durumu, o zamankilere ve onların ardından geleceklere ibret dolu bir ceza, takva sahiplerine de bir öğüt yaptık."},{"n":67,"t":"Mûsa, toplumuna dedi ki: \"Allah size, bir inek boğazlamanızı emrediyor.\" Dediler ki: \"Sen bizimle alay mı ediyorsun?\" Dedi ki: \"Cahillerden biri olmaktan Allah'a sığınırım.\""},{"n":68,"t":"Şöyle konuştular: \"Çağır Rabbine bizim için, açıklasın bize neymiş o!\" Cevap verdi: \"O diyor ki, bahsettiğim ne yaşlıdır ne de körpe. İkisi arası bir inektir.\" Hadi size emredileni yapın!"},{"n":69,"t":"Şöyle dediler: \"Çağır Rabbine bizim için, neymiş onun rengi açıklasın bize.\" Cevap verdi: \"O diyor ki, bahsettiğim, sarı, rengi parlak bir inektir; seyredenlere mutluluk verir.\""},{"n":70,"t":"Şöyle dediler: \"Dua et Rabbine, açıklasın bize neymiş o! Çünkü bu inek, bizim gözümüzde başkalarıyla karıştı. Ve biz, Allah dilerse, doğruya ve güzele elbette kılavuzlanacağız.\""},{"n":71,"t":"Cevap verdi Mûsa: \"Allah diyor ki, bahsettiğim, boyunduruk yememiş bir inektir; toprağı sürmez, ekini sulamaz. Salma hayvandır. Alaca yoktur onda.\" Dediler ki: \"İşte şimdi gerçeği getirdin.\" Ve ardından onu boğazladılar, az kalsın yapmayacaklardı."},{"n":72,"t":"Siz bir adam öldürmüştünüz de onunla ilgili olarak çekişip duruyordunuz. Oysaki Allah, sizin sakladıklarınızı ortaya çıkaracaktı."},{"n":73,"t":"Şöyle dedik: \"Kesilen ineğin bir parçasıyla öldürülen adama vurun.\" İşte böyle diriltir Allah ölüleri. Size ayetlerini gösteriyor ki, aklınızı işletebilesiniz."},{"n":74,"t":"Sonra bunun ardından kalpleriniz yine kaskatı kesildi. Taş gibidir o. Belki daha da katıdır. Taşların bazıları var ki, ondan ırmaklar fışkırır. Bazıları var ki, çatır çatır yarılır da içinden su çıkar. Öylesi var ki, Allah korkusundan aşağılara düşer. Allah, yapıp durduklarınızdan gafil değildir."},{"n":75,"t":"Şimdi siz bunların size inanmalarını mı umuyorsunuz? Bunların içlerinden bir fırka vardır ki, Allah'ın kelamını dinliyorlar, sonra onu, akletmelerinin ardından, bilip durdukları halde tahrif ediyorlardı."},{"n":76,"t":"İnanmış olanlarla karşılaştıklarında, \"İnandık!\" derler. Başbaşa kaldıklarında ise şöyle konuşurlar: \"Allah'ın size açtığını, Rabbiniz katında sizinle tartışmada kanıt yapsınlar diye onlara söylüyor musunuz? Aklınızı işletmeyecek misiniz?\""},{"n":77,"t":"Bilmezler mi ki, Allah onların sakladıklarını da açıklarını da çok iyi bilmektedir."},{"n":78,"t":"İçlerinde ümmî olanlar da vardır ki Kitap'ı bilmezler, sadece anlamını bilmeden okuyuşlar/hurafeler/hayal ve kuruntular bilirler. Onlar yalnız sanıya saplanırlar."},{"n":79,"t":"Yazıklar olsun o kişilere ki, Kitap'ı kendi elleriyle yazarlar da sonra onunla basit bir karşılık satın alsınlar diye, \"İşte bu, Allah katındandır!\" derler. Vay haline onların, ellerinin yazdıkları yüzünden! Vay haline onların, kazanıp durdukları yüzünden!"},{"n":80,"t":"Dediler ki: \"Sayılı birkaç gün dışında ateş bize asla dokunmayacaktır.\" De ki: \"Allah'tan bir ahit mi aldınız! Allah, ahdine asla ters düşmez. Yoksa siz Allah'a isnat ederek, bilmediğiniz şeyleri mi söylüyorsunuz?\""},{"n":81,"t":"İş onların sandığı gibi değil! Kötülük ve çirkinlik kazanan, suçu kendisini kuşatmış olan kişiler, ateşin dostudurlar. Sürekli kalacaklardır onun içinde."},{"n":82,"t":"İman edip hayra ve barışa yönelik işler yapanlar ise cennetin dostudurlar. Onlar da onun içinde sürekli kalacaklardır."},{"n":83,"t":"İsrailoğullarından şöyle bir söz de almıştık: Allah'tan başkasına ibadet etmeyin, anne-babaya, akrabaya, yetimlere, yoksullara iyilik ve güzellikle davranın. İnsanlara güzeli ve güzelliği söyleyin. Namazı/duayı yerine getirin, zekâtı verin. Bütün bunlardan sonra siz, pek azınız müstesna, sırt çevirdiniz. Hâlâ da yüz çevirip duruyorsunuz."},{"n":84,"t":"Sizden şu sözü de almıştık: Birbirinizin kanlarını dökmeyeceksiniz. Birbirlerinizi yurtlarınızdan çıkarmayacaksınız. Bunu kabul etmiştiniz. Hâlâ da buna tanıklarsınız."},{"n":85,"t":"Bütün bunlardan sonra siz şu insanlarsınız: Birbirinizi öldürüyorsunuz. İçinizden bir zümreyi yurtlarından çıkarıyorsunuz. Onlar aleyhine kötülük ve düşmanlık hususunda dayanışmaya giriyorsunuz. Esasında onları yurtlarından çıkarmak size haram edildiği halde, esir olarak size geldiklerinde fidyelerini veriyorsunuz. Şimdi siz Kitap'ın bir kısmına inanıp bir kısmını inkâr mı ediyorsunuz? İçinizden bunu yapanın cezası, dünya hayatında rezillikten başka bir şey değildir. Kıyamet gününde ise böyleleri azabın en şiddetlisine itilir. Allah, yapmakta olduklarınızdan habersiz değildir."},{"n":86,"t":"İşte bunlar, âhiret karşılığında dünyayı satın alan kişilerdir. Azap, hafifletilmeyecektir onlardan. Hiçbir şekilde yardım da edilmeyecektir onlara."},{"n":87,"t":"Yemin olsun, biz Musa'ya o Kitap'ı verdik. Ve onun ardından da resulleri izlettik. Meryem oğlu İsa'ya da açık-seçik deliller verdik ve kendisini Kutsal Ruh'la destekledik. Bir resul size öz benliklerinizin hoşlanmadığı bir şey getirdiğinde, her defasında büyüklük taslamadınız mı? Bir kısmını yalanladınız, bir kısmını da öldürüyorsunuz!"},{"n":88,"t":"\"Kalplerimiz kabuk tutmuştur.\" dediler. Hayır, öyle değil! Küfürleri yüzünden Allah onları lanetlemiştir de çok az bir kısmı iman eder."},{"n":89,"t":"Yanlarındakini doğrulamak üzere kendilerine Allah katından bir kitap geldiğinde, daha önce inkâr edenlere karşı zafer isteyip durdukları halde, tanıyıp bildikleri kendilerine gelince, onu inkâr ettiler. Allah'ın laneti, küfre sapanların üstüne olsun!"},{"n":90,"t":"Allah'ın, kullarından dilediğine lütfunun eseri olarak indirdiğini zalimce kıskanarak, Allah'ın vahyettiğini inkâr etmeleri uğruna öz benliklerini sattıkları şey ne çirkindir! Bu yüzdendir ki gazap üzerine gazaba çarpıldılar. Gerçeği örtenler için rezil edici bir azap vardır."},{"n":91,"t":"Onlara, \"Allah'ın indirmiş olduğuna inanın!\" denildiğinde şöyle konuşurlar: \"Biz, bize indirilene inanırız.\" Ve ondan ötesini inkâr ederler. Oysaki o, kendilerinin yanındakini doğrulayıcı bir gerçektir. Söyle onlara: \"Madem iman sahibiydiniz, daha önce Allah'ın peygamberlerini niye öldürüyordunuz?\""},{"n":92,"t":"Yemin olsun ki, Mûsa size açık-seçik hak beyanlarla gelmişti de onun arkasından buzağıyı ilah edinmiştiniz. Zalimlersiniz sizler."},{"n":93,"t":"Hani, sizden misakınızı almış, Tur'u üzerinize kaldırmıştık: \"Size verdiğimizi kuvvetle tutun, dinleyin!\" dediler. Dediler ki: \"Dinledik, isyan ettik!\" İnkarları yüzünden gönüllerine buzağı sevgisi içirildi/ içselleştirildi. De ki: \"Eğer inanan kişiler iseniz, imanınız size ne kötü şey emrediyor!\""},{"n":94,"t":"De ki: \"Allah katındaki âhiret yurdu diğer insanların değil de yalnız ve yalnız sizin ise, eğer doğru sözlü iseniz, hadi isteyin ölümü!\""},{"n":95,"t":"Ellerinin önden gönderdiği şeyler yüzünden ölümü hiçbir zaman istemeyeceklerdir. Allah, zalimleri çok iyi bilmektedir."},{"n":96,"t":"Sen onları, insanların yaşamaya en düşkünü olarak bulursun. Şirke batanlardan bile... Her biri bin yıl ömür sürsün ister. Oysaki, uzun yaşaması onu azaptan uzaklaştıracak değildir. Allah, yapmakta olduklarını çok iyi görmektedir."},{"n":97,"t":"De ki: \"Kim Cebrail'e -ki o, Allah'ın izniyle Kur'an'ı kendinden öncekini doğrulayıcı, inananlara yol gösterici ve müjde olarak senin kalbine indirmiştir- düşman kesilirse,"},{"n":98,"t":"Kim Allah'a, O'nun meleklerine, resullerine, Cebrail'e, Mikâil'e düşman kesilirse, Allah da bu tür inkârcılara düşman kesilir."},{"n":99,"t":"Yemin olsun, biz sana açık-seçik ayetler indirdik. Onları, sapmış olanlardan başkası inkâr etmez."},{"n":100,"t":"Bir ahitle söz verdikleri her seferinde, içlerinden bir fırka ahdi kaldırıp atmadı mı? Doğrusu şu ki, onların çokları iman etmezler."},{"n":101,"t":"Allah katından kendilerine, ellerinde bulunanı tasdikleyici bir resul geldiğinde, kitap verilenlerden bir fırka, Allah'ın Kitabı'nı hiç bilmiyorlarmış gibi kaldırıp arkalarına attılar."},{"n":102,"t":"Süleyman'ın mülk ve saltanatı konusunda onlar, şeytanların okuyup durduklarına uydular. Halbuki Süleyman küfre sapmamıştı. Ancak şeytanlar küfre sapmıştı; insanlara büyüyü öğretiyorlardı. Ve Babil'de Hârût ve Mârût adlı iki melek üzerine indirileni öğretiyorlardı. Oysaki o iki melek, \"Biz bir imtihan aracıyız, sakın küfre sapma!\" demedikçe hiç kimseye bir şey öğretmiyorlardı. İnsanlar onlardan erkekle eşinin arasını açacakları şeyi öğreniyorlardı. Ne var ki, onlar onunla Allah'ın izni olmadıkça hiç kimseye zarar veremezler. Onlar kendilerine zarar vereni, yarar vermeyeni öğreniyorlardı. Yemin olsun ki, onu satın alanın âhirette hiçbir nasibi olmayacağını açıkça bilmişlerdir. Öz benliklerini sattıkları şey ne kötüdür! Bir bilebilselerdi!"},{"n":103,"t":"Eğer onlar iman edip sakınsalardı, Allah katından bir sevap elbette daha kıymetli olurdu. Keşke bilebilselerdi."},{"n":104,"t":"Ey iman edenler! \"Râina!\" demeyin, \"Unzurna!\" deyin/\"Bizi davar gibi güt!\" diye konuşmayın, \"Bize bak!\" diye konuşun ve dinleyin. Kâfirler için korkunç bir azap vardır."},{"n":105,"t":"Ehlikitap'ın küfre sapanlarıyla müşrikler, Rabbinizden size bir hayır indirilmesini istemezler. Ama Allah, rahmetini dilediğine özgüler. Allah, büyük lütfun sahibidir."},{"n":106,"t":"Biz bir ayeti siler, unutturur veya ertelersek ondan daha iyisini veya onun bir benzerini getiririz. Allah'ın her şeye gücü yeter olduğunu bilmedin mi?"},{"n":107,"t":"Bilmedin mi ki göklerin de yerin de mülk ve saltanatı yalnız Allah'ındır. Sizin için Allah'tan başka ne bir velî vardır ne de bir yardımcı."},{"n":108,"t":"Yoksa siz de resulünüzden, daha önce Mûsa'dan istekte bulunulduğu gibi isteklerde bulunmak mı diliyorsunuz?! İmanı küfürle değiştirmeye kalkan, yolun dosdoğrusunu saptırmış olur."},{"n":109,"t":"Ehl-i Kitap'tan birçoğu, hak kendilerine ayyuka çıkıp netleştikten sonra, sırf öz benliklerindeki kıskançlık/haset yüzünden sizi, imanınızdan sonra kâfirlere çevirmeyi ister. Allah, emrini getirinceye kadar affedin, hoş görün! Şüphesiz Allah, her şey üzerine Kadîr'dir."},{"n":110,"t":"Namazı/duayı yerine getirin, zekâtı verin. Öz benlikleriniz için önden gönderdiğiniz her hayrı, Allah katında bulacaksınız. Hiç kuşkusuz, Allah, yapmakta olduklarınızı iyice görmektedir."},{"n":111,"t":"\"Yahudi yahut Hıristiyan olandan başkası cennete asla giremeyecek.\" dediler. Bu, onların hurafeleri/anlamını bilmeden okuyuşları/kuruntularıdır. De ki onlara: \"Eğer doğru sözlü iseniz hadi getirin susturucu kanıtınızı!\""},{"n":112,"t":"İş onların sandığı gibi değil! Kim güzel davranışlar sergileyerek yüzünü Allah'a teslim ederse, Rabbi katında ödülü vardır onun. Korku yoktur böyleleri için; tasalanmayacaklardır onlar..."},{"n":113,"t":"Yahudiler: \"Hıristiyanlar hiçbir şey üzerinde değil.\" dediler. Hıristiyanlar da: \"Yahudiler hiçbir şey üzerinde değil.\" dediler. Ve bunlar Kitap'ı da okuyup dururlar. İlimden nasibi olmayanlar da aynen onların sözleri gibi söz etti. Tartışmaya girdikleri şey hakkında, aralarında hükmü, kıyamet günü Allah verecektir."},{"n":114,"t":"Allah'ın mescitlerini, içlerinde O'nun adı anılıyor diye engelleyen ve onların yıkımı için uğraşan kişiden daha zalim kim olabilir!... Böylelerinin, o mescitlere girmeleri ancak korka korka olacaktır. Böyleleri için dünyada bir rezillik vardır. Âhirette ise bunlara çok büyük bir azap öngörülmüştür."},{"n":115,"t":"Doğu da batı da yalnız Allah'ındır. O halde nereye dönerseniz orada Allah'ın yüzü vardır. Allah Vâsi'dir, varlığı sürekli genişletip büyütür; Alîm'dir, her şeyi en iyi biçimde bilir."},{"n":116,"t":"\"Allah çocuk edindi.\" dediler. Hâşâ! Böyle bir şeyden arınmıştır O! Tam aksine, göklerdekiler de yerdekiler de O'na aittir. Bunların tümü O'nun önünde boyun bükmektedir."},{"n":117,"t":"Gökleri ve yeri, güzelliklerle donatarak yaratan Bedî' O'dur. Bir şeyin olmasına karar verdi mi ona sadece \"Ol!\" der. Artık o, oluverir."},{"n":118,"t":"Bilgiden yoksun olanlar dedi ki: \"Allah bizimle konuşsaydı yahut bize bir mucize gelseydi ya! ...\" Onlardan öncekiler de aynen onların dediği gibi demişti. Kalpleri birbirine benzemiştir. Biz ayetleri, gerçeği apaçık bilmek isteyenler için iyiden iyiye açıklamışızdır."},{"n":119,"t":"İnan olsun ki, biz seni hak üzere bir müjdeci ve uyarıcı olarak gönderdik. Sen, cehennem ehlinden sorgu suale çekilmeyeceksin/cehennem yâranından sen sorumlu değilsin."},{"n":120,"t":"Sen onların öz milletlerine uymadıkça Yahudiler de Hıristiyanlar da senden asla hoşnut olmaz. De ki: \"Allah'ın kılavuzluğu erdirici kılavuzluğun ta kendisidir.\" İlimden sana ulaşan nasipten sonra bunların boş ve iğreti arzularına uyarsan, Allah katından ne bir dostun/destekçin olur ne de bir yardımcın."},{"n":121,"t":"Kendilerine Kitap'ı verdiklerimiz onu, okunuşunun hakkını vererek okurlar. İşte onlar ona inanırlar. Onu inkâr edenlere gelince, onlar hüsrana uğrayanların da kendileridir."},{"n":122,"t":"Ey İsrailoğulları! Size lütfettiğim nimetimi hatırlayın. Ben sizi âlemlerden daha üstün kılmıştım."},{"n":123,"t":"Kimsenin kimse yerine bir şey ödemeyeceği, kimseden fidye kabul edilmeyeceği, şefaatin hiç kimseye yarar sağlamayacağı ve onların hiçbir yardım göremeyecekleri o günden sakının!"},{"n":124,"t":"Hani Rabbi, İbrahim'i bazı kelimelerle imtihana çekmiş, o da onların hakkını vermişti de Rab şöyle demişti: \"Seni insanlara önder yapacağım.\" İbrahim, \"Soyumdan birilerini de\" deyince Allah: \"Benim ahdim zalimlere ulaşmaz.\" buyurdu."},{"n":125,"t":"Hatırla o zamanı ki, biz o evi insanlar için sevap kazanmaya yönelik bir toplantı yeri ve güvenli bir sığınak yaptık. Siz de İbrahim'in makamından bir dua/namaz yeri edinin. İbrahim ve İsmail'e şu sözü ulaştırmıştık: \"Tavaf edenler, kendini ibadete verenler, rükû-secde edenler için evimi temizleyin!\""},{"n":126,"t":"İbrahim şöyle yakarmıştı: \"Rabbim! Şu kenti güvenli bir kent yap, halkının Allah'a ve âhiret gününe inananlarını çeşitli ürünlerle rızıklandır.\" Rab dedi ki: \"Küfre sapanları az bir nimetle rızıklandırır, sonra da ateş azabına itiveririm. Ne kötü bir dönüş yeridir o!\""},{"n":127,"t":"İbrahim'in, İsmail'le birlikte, o evin ana duvarlarını yükselterek şöyle yakardıkları zamanı da an: \"Rabbimiz, bizden gelen niyazları kabul buyur; sen, evet sen, Semî'sin, her şeyi çok iyi duyarsın; Alîm'sin, her şeyi çok iyi bilirsin.\""},{"n":128,"t":"\"Rabbimiz! Bizi, sana teslim olmuş iki müslüman/Allah'a teslim olan kıl. Soyumuzdan da sana teslim olan müslüman bir ümmet oluştur. Bize ibadet yerlerimizi göster, bizim tövbemizi kabul et! Sen, evet sen, Tevvâb'sın, tövbeleri cömertçe kabul edersin; Rahîm'sin, rahmetini cömertçe yayarsın.\""},{"n":129,"t":"\"Rabbimiz! İçlerinden onlara, senin ayetlerini okuyacak, kendilerine Kitap'ı ve hikmeti öğretecek, onları temizleyip arındıracak bir resul gönder. Sen, evet sen, Azîz'sin, tüm ululuk ve onurun sahibisin; Hakîm'sin, tüm hikmetlerin kaynağısın.\""},{"n":130,"t":"Öz benliğini beyinsizliğe itenden başka kim, İbrahim'in milletinden yüz çevirir? Yemin olsun ki biz onu dünyada seçip yüceltmiştik. Ve o, âhirette de barış ve iyilik sevenlerden biri olacaktır elbette..."},{"n":131,"t":"Rabbi ona, \"Müslüman olup bana teslim ol!\" dediğinde o şu cevabı vermişti: \"Teslim oldum âlemlerin Rabbi'ne!\""},{"n":132,"t":"İbrahim de oğullarına şunu vasiyet etti, Yakub da: \"Oğullarım! Allah sizin için bu dini seçmiştir. O halde ancak müslümanlar olarak can verin.\""},{"n":133,"t":"Yoksa siz, Yakub'a ölümün gelip çatışına tanıklar mıydınız? Hani, oğullarına şunu sormuştu: \"Benden sonra neye ibadet edeceksiniz?\" Cevapları şu olmuştu: \"Senin ilahına, ataların İbrahim'in, İsmail'in, İshak'ın ilahına, tek ve biricik olan ilaha kulluk edeceğiz; biz yalnız O'na teslim olanlarız.\""},{"n":134,"t":"İşte bunlar bir ümmetti, gelip geçtiler. Kazandıkları kendilerinindir. Sizin kazandıklarınız da sizin olacaktır. Siz onların yapıp ettiklerinden sorguya çekilmeyeceksiniz."},{"n":135,"t":"\"Yahudi yahut Hıristiyan olun ki doğruya kılavuzlanasınız.\" dediler. De ki: \"Hayır, öyle değil. Şirk ve yozlaşmadan uzak bir biçimde, İbrahim milletinden olalım. O, şirke bulaşanlardan değildi.\""},{"n":136,"t":"Şöyle deyin: \"Allah'a, bize indirilene, İbrahim'e, İsmail'e, İshak'a, Yakub'a, onun torunlarına indirilene, Mûsa'ya ve İsa'ya verilene ve diğer nebilere verilene inandık. Bunlar arasından hiç kimseyi ayırmayız. Biz yalnız O'na/Allah'a teslim olanlarız.\""},{"n":137,"t":"Eğer onlar da sizin inandığınız gibi inanırlarsa, hiç kuşkusuz, iyiyi ve güzeli bulmuş olurlar; eğer sırt dönerlerse artık onlar parçalanmış olurlar. Onlara karşı sana Allah yeter. En iyi işiten, en güzel bilendir O."},{"n":138,"t":"Allah'ın boyasını esas alın. Allah'tan daha güzel kim boya vurabilir! Biz yalnız O'na kulluk ederiz."},{"n":139,"t":"De ki onlara: \"Allah hakkında bizimle tartışıyor musunuz? Oysaki Allah hem bizim Rabbimizdir hem sizin Rabbinizdir. Bizim amellerimiz bize, sizin amelleriniz size. Biz yalnız O'na/Allah'a gönül verenleriz.\""},{"n":140,"t":"Yoksa siz, \"İbrahim, İsmail, İshak, Yakub ve torunları Yahudi yahut Hıristiyanlardı\" mı diyorsunuz? Söyle onlara: \"Siz mi daha bilgilisiniz yoksa Allah mı?\" Allah'tan kendine ulaşmış bir tanıklığı gizleyenden daha zalim kim vardır! Allah, yapmakta olduklarınızdan habersiz değildir."},{"n":141,"t":"İşte bunlar bir ümmetti, gelip geçtiler. Kazandıkları kendilerine. Sizin kazandığınız da size. Onların yapıp ettiklerinden siz sorumlu olmayacaksınız."},{"n":142,"t":"İnsanlar içinden bazı beyinsizler: \"Onları, yönelmekte oldukları kıbleden ne çevirdi?\" diyecekler. De ki: \"Doğu da Allah'ın, batı da. O, dilediğini dosdoğru yola kılavuzlar.\""},{"n":143,"t":"İşte böyle! Biz sizi, insanlara tanık/ örnek olasınız, resul de size tanık/ örnek olsun diye vasat/dengeli, seçkin bir ümmet yaptık. Senin üzerinde bulunduğun kıbleyi, sadece resule uyanları, iki topuğu üstünde geriye döneceklerden ayıralım diye kıble yaptık. Bu, Allah'ın kılavuzluk ettiği kimseler dışındakilere gerçekten ağır gelir. Allah sizin imanınızı boşa çıkaracak değildir. Şüphesiz Allah, insanlara karşı çok şefkatli, çok merhametlidir."},{"n":144,"t":"Biz senin, yüzünün habire göğe doğru çevrildiğini elbette görüyoruz. Hoşlanacağın bir kıbleye seni elbette döndüreceğiz. Artık yüzünü Mescid-i Haram yönüne çevir. Nerede olsanız yüzünüzü Mescid-i Haram yönüne döndürün. Kendilerine kitap verilenler, onun, Rablerinden bir gerçek olduğunu çok iyi bilirler. Allah onların yapıp ettiklerinden habersiz değildir."},{"n":145,"t":"Yemin olsun, Ehlikitap'a sen her türlü mucizeyi getirsen de onlar senin kıblene uymazlar; sen de onların kıblesine uymayacaksın. Onlar birbirlerinin kıblesine de uymazlar. Eğer sen, ilimden nasibin sana geldikten sonra onların boş ve iğreti arzularına uyarsan, işte o zaman kesinlikle zalimlerden olursun."},{"n":146,"t":"Kendilerine kitap verdiklerimiz, onu öz oğullarını tanıdıkları gibi tanırlar. Bununla birlikte, içlerinden bir zümre, bilip durdukları halde gerçeği gizliyorlar."},{"n":147,"t":"Gerçek, Rabbinden gelir. O halde sakın kuşkuya düşenlerden olma!"},{"n":148,"t":"Herkesin bir yönü vardır, ona döner. O halde hayırlarda yarışın. Nerede olursanız olun Allah sizi bir araya getirecektir. Allah herşeye güç yetirendir."},{"n":149,"t":"Nereden çıkarsan çık, yüzünü Mescid-i Haram'a döndür. Bu, elbette Rabbinden gelen gerçektir. Allah, yaptıklarınızdan habersiz değildir."},{"n":150,"t":"Nereden çıkarsan çık, yüzünü Mescid-i Haram'a çevir. Nerede olursanız olun, yüzünüzü ona doğru çevirin ki, insanların elinde sizin aleyhinize bir delil bulunmasın. Onların zulme sapanları müstesna. Artık onlardan korkmayın, benden korkun. Yüzünüzü Mescid-i Haram'a dönün ki, üzerinizdeki nimetimi tamamlayayım. Ve bu sayede güzeli ve iyiyi bulmanız da umulmaktadır."},{"n":151,"t":"Nitekim size aranızdan bir resul göndermişiz; size ayetlerimizi okuyor, sizi temizleyip arıtıyor, size Kitap'ı ve hikmeti öğretiyor, size, daha önce bilmediklerinizi belletiyor."},{"n":152,"t":"Anın beni ki, anayım sizi. Şükredin bana, sakın nankörlük etmeyin!"},{"n":153,"t":"Ey iman sahipleri! Sabra ve namaza/duaya sarılarak yardım dileyin. Hiç kuşkunuz olmasın ki, Allah sabredenlerle beraberdir."},{"n":154,"t":"Allah yolunda öldürülenler için \"ölüler\" demeyin. Tam aksine, onlar dirilerdir ama siz farkında olmazsınız."},{"n":155,"t":"Yemin olsun ki, sizi korku, açlık; mallardan-canlardan-meyvelerden eksiltme türünden bir şeyle mutlaka imtihan edeceğiz. Sabredenlere müjdele."},{"n":156,"t":"Onlara bir ıstırap gelip çattığında şöyle derler: \"Biz Allah içiniz ve sonunda O'na dönüp gideceğiz.\""},{"n":157,"t":"İşte böyleleri üzerine Rablerinden selamlar, bereketler var, bir rahmet var. İşte bunlardır iyiye ve güzele ermiş olanlar."},{"n":158,"t":"Şu bir gerçek ki, Safâ ile Merve, Allah'ın özdeşleştirdiği simgelerdendir. Bu yüzden, Evi (Kâbe'yi) hacceden yahut onu umre amacıyla ziyaret eden birinin, bu ikisini tavaf etmesinde kendisi için bir sakınca yoktur. Kim gönülden koparak bir hayır yaparsa, hiç kuşkusuz Allah Şâkir'dir, şükran duyar/şükrün karşılığını verir; Alîm'dir, her şeyi bilir."},{"n":159,"t":"İndirdiğimiz açık-seçik delillerle, kılavuz mesajı; biz onu Kitap'ta insanlara ayan-beyan gösterdikten sonra gizleyenlere, işte onlara, hem Allah lanet eder hem de diğer lanet okuyanlar lanet eder."},{"n":160,"t":"Tövbe edip hallerini düzeltenlerle gerçeği açıklayanlar müstesna. İşte böylelerinin tövbesini kabul ederim. Doğrusu ben tövbeleri çok çok kabul edenim, rahmeti sınırsız olanım."},{"n":161,"t":"İnkâr edip kâfir olarak ölenlere gelince, işte Allah'ın, meleklerin ve bütün insanların laneti onların üzerinedir."},{"n":162,"t":"Sürekli o lanetin içindedirler. Ne azapları hafifletilir ne de yüzlerine bakılır."},{"n":163,"t":"Sizin İlah'ınız Vâhid'dir, bir tek İlah'tır. İlah yoktur O'ndan başka. Rahman'dır O, Rahîm'dir."},{"n":164,"t":"Şu bir gerçek ki göklerin ve yerin yaratılışında, gece ile gündüzün birbiri ardınca gelişinde, insanların yararı için denizde yüzüp giden gemilerde, Allah'ın gökten suyu indirip onunla, ölümünden sonra toprağı dirilterek üzerine tüm canlılardan yaymasında, rüzgârların bir düzen içinde yönden yöne çevrilmesinde, gök ve yer arasında bir hizmete memur edilen bulutlarda, aklını işleten bir topluluk için sayısız izler-işaretler-ibretler vardır."},{"n":165,"t":"İnsanlar içinde öyleleri vardır ki, Allah dışında bazılarını Allah'a eş tutarlar da onları Allah'ı sevmiş gibi severler. İman sahipleri ise Allah'a sevgide çok kararlı ve taşkındır. Zulme saplananlar, azabı gördüklerinde tüm kuvvetin Allah'ta bulunduğunu, Allah'ın azabının çok şiddetli olduğunu fark edeceklerini anlayabilseler!"},{"n":166,"t":"O zaman, izlenenler, kendilerini izleyenlerden uzaklaşıp gitmişlerdir. Azabı gördüler artık, aralarındaki bağlar parçalanıp koptu."},{"n":167,"t":"İzleyenler şöyle demiştir: \"Ne olurdu bir kez daha imkân verilse de şunların bizden uzaklaştıkları gibi biz de onlardan uzaklaşsak.\" Böylece Allah onlara, yapıp ettiklerini, kendilerine yönelmiş özleyişler olarak gösterir. Ama artık ateşten çıkamazlar."},{"n":168,"t":"Ey insanlar! Yeryüzündeki nimetlerden temiz ve helal olmak şartıyla yiyin. Şeytanın adımlarını izlemeyin. Çünkü o size açık bir düşmandır."},{"n":169,"t":"Hiç kuşkusuz o, size kötülük, çirkinlik/düzensizlik ve pislik emreder. Ve size, Allah hakkında bilmediğiniz şeyleri söylemenizi buyurur durur."},{"n":170,"t":"Onlara, \"Allah'ın indirdiğine uyun!\" dendiğinde: \"Hayır! Biz, atalarımızı üzerinde bulduğumuz şeye uyarız.\" derler. Peki, ataları bir şeye akıl erdiremiyor, doğruya ve güzele ulaşamıyor idiyseler!..."},{"n":171,"t":"O küfre sapanların durumu, bağırıp çağırma dışında bir şeyi işitmeyen varlıklara haykıranın durumuna benzer. Sağırdırlar, dilsizdirler, kördürler. Bu yüzden akıllarını işletemezler onlar."},{"n":172,"t":"Ey iman sahipleri! Size verdiğimiz rızıkların temizlerinden yiyin ve -eğer yalnız O'na kulluk/ibadet ediyorsanız- Allah'a şükredin."},{"n":173,"t":"Allah size leşi, kanı, domuz etini, Allah'tan başkası adına kesileni haram kılmıştır. Ama zorda kalanın, sınırı aşmadan, şuna-buna haksızlık ve tecavüze gitmeden yemesinde kendisi için günah yoktur. Allah çok affedici, çok merhametlidir."},{"n":174,"t":"Allah'ın kitaptan indirdiği şeyi gizleyip onu basit bir ücret karşılığı satanlar, karınlarında ateşten başka bir şey yemiş olmazlar. Kıyamet günü, Allah onlarla konuşmayacaktır, onları arındırmayacaktır. Onlar için korkunç bir azap vardır."},{"n":175,"t":"İşte bunlar hidayeti satıp şaşkınlığı, affedilmeyi satıp azabı almışlardır. Ne kadar da dayanıklıdırlar ateşe!..."},{"n":176,"t":"Bu böyledir. Çünkü Allah, Kitap'ı hak olarak indirmiştir. Kitap'ta çekişmeye girenler, bütünden uzaklaştırıcı bir kopuşun tam içindedirler."},{"n":177,"t":"Yüzlerinizi doğu ve batı yönüne çevirmeniz hayırda erginlik/dürüstlük değildir. Hayırda erginlik/dürüstlük o kişinin hakkıdır ki, Allah'a, âhiret gününe, meleklere, kitaplara, peygamberlere inanır; akrabaya, yetimlere, çaresizlere, yolda kalmışa, yoksullara, özgürlüğüne kavuşmak gayretinde olanlara malı seve seve verir, namazı/duayı yerine getirir, zekâtı öder. Böyleleri söz verdiklerinde ahitlerine vefalıdırlar; bolluk ve bereket zamanı kadar, zorluk, sıkıntı ve şiddet zamanında da sabırlıdırlar. İşte bunlardır özüyle sözü bir olanlar. İşte bunlardır takva sahipleri."},{"n":178,"t":"Ey iman edenler! Öldürülenler hakkında üzerinize kısas yazılmıştır. Hür kişiye karşılık hür, köleye karşılık köle, dişiye karşılık dişi... Kim kardeşi tarafından herhangi bir şekilde affa uğrarsa, bu durumda örfü izlemek ve affedene en güzel biçimde bir ödeme yapmak gerekir. İşte bu, Rabbinizden size bir hafifletme ve bir rahmettir. Kim bundan sonra azgınlık ve düşmanlık ederse onun için korkunç bir azap vardır."},{"n":179,"t":"Ey aklı ve gönlü işleyenler, kısasta sizin için hayat vardır. Bu sayede korunmanız umulmaktadır."},{"n":180,"t":"Sizden birine ölüm yaklaştığında, eğer geriye bir mal/hayır bırakıyorsa; anaya, babaya ve akrabaya uygun/örfi bir marufla vasiyette bulunması -sakınanlar üzerine bir hak olarak- farz kılındı."},{"n":181,"t":"Kim işittikten sonra vasiyeti değiştirirse hiç kuşkusuz bunun günahı onu değiştirenler üzerinedir. Allah her şeyi işitir, her şeyi bilir."},{"n":182,"t":"Kim vasiyet edenin haksızlığa sapmış veya günah işlemiş olmasından endişelenip de ilgililerin arasını bulursa ona günah yoktur. Allah çok affedici, çok merhamet edicidir."},{"n":183,"t":"Ey iman sahipleri! Oruç sizden öncekiler üzerine yazıldığı gibi sizin üzerinize de yazılmıştır. Bu sayede korunmanız umulmaktadır."},{"n":184,"t":"Sayılı günlerdir. Sizden kim hasta olur veya yolculuk halinde bulunursa tutamadığı gün sayısınca başka günlerde tutar. Oruca zorlukla dayananlar üzerine düşen, fidye olarak bir yoksulu doyurmaktır. Kim bir mecburiyeti olmaksızın içinden gelerek iyilik yaparsa bu onun için daha hayırlı olur. Ve oruç tutmanız, eğer bilirseniz, sizin için daha hayırlıdır."},{"n":185,"t":"Ramazan o aydır ki; insanlara kılavuz olan, iyi-kötü ayrımıyla hidayetten kanıtlar getiren Kur'an, onda indirilmiştir. O halde bu aya ulaşanınız onu oruçlu geçirsin. Hasta olan veya yolculuk halinde bulunan, tutamadığı gün sayısınca başka günlerde tutsun. Allah sizin için kolaylık ister; O sizin için zorluk istemez. Tutulmamış olan günleri tamamlamanızı, sizi doğru yola kılavuzladığı için Allah'ı yüceltmenizi ister. Ve sizin şükretmeniz umulmaktadır."},{"n":186,"t":"Kullarım sana benden sorarlarsa ben Karîb'im, gerçekten çok yakınım. Dua edenin çağrısına, bana çağırıp yakardığı anda cevap veririm. Hadi onlar da bana karşılık versinler, bana inansınlar ki doğru ve iyiyi bulabilsinler."},{"n":187,"t":"Oruç gecesi kadınlarınıza cinsel yaklaşım size helal kılınmıştır. Onlar sizin için giysidir/eştir, siz de onlar için giysisiniz/eşsiniz. Allah sizin öz benliklerinize yazık etmekte olduğunuzu bilmiş, tövbelerinizi kabul edip sizi affetmiştir. Artık şimdi onlara yaklaşın ve Allah'ın sizin için yazdığı şeyi arayın. Tan yerinin beyaz ipliği siyah ipliğinden sizce seçilinceye kadar yiyin için; sonra da orucu gece oluncaya değin tamamlayın. Mescitlerde itikâfta bulunduğunuz sırada zevcelerinizle cinsel temas kurmayın. İşte bunlar Allah'ın yasaklarıdır, bunlara yaklaşmayın. Allah, ayetlerini insanlara işte böyle açıklar ki korunabilsinler."},{"n":188,"t":"Mallarınızı aranızda haksız ve uydurma yollara baş vurarak yemeyin; bilip durduğunuz halde insanların mallarından bir kısmını günaha saparak yemek için onları yargıçlara aktarmayın."},{"n":189,"t":"Sana hilalleri/yeni doğan ayları soruyorlar. De ki: \"Onlar insanlar için de hac için de vakit ölçüleridir. Evlere arkalarından girmeniz iyilik/ erdem değildir. İyilik/erdem, korunan/sakınan kimsenin yaptığıdır. Evlere kapılarından girin ve Allah'tan sakının ki kurtuluşa erebilesiniz.\""},{"n":190,"t":"Sizinle çarpışmaya girenlerle Allah yolunda siz de çarpışın. Ama haksız yere saldırmayın/çarpışmada zulme sapmayın. Çünkü Allah, sınır tanımaz azgınları sevmiyor."},{"n":191,"t":"Onları yakaladığınız yerde öldürün; onların sizi çıkardıkları yerden siz de onları çıkarın. Fitne/baskı ve bozgunculuk, öldürmekten daha kötüdür. Mescid-i Haram'da, onlar sizinle çarpışmaya girinceye kadar siz de onlarla çarpışmaya girmeyin. Eğer sizinle çarpışmaya girerlerse siz de onları öldürün. İşte böyle verilir küfre sapanların cezası!"},{"n":192,"t":"Eğer savaşı sona erdirirlerse Allah çok affedici, çok merhametlidir."},{"n":193,"t":"Fitne kalmayıncaya ve din yalnız Allah'ın oluncaya kadar onlarla çarpışın. Eğer çarpışmaktan vazgeçerlerse artık zulme sapanlardan başkasına düşmanlık edilmez."},{"n":194,"t":"Haram ay, haram aya karşılıktır. Hürmetler ve yasaklar karşılıklıdır. O halde, azgınlık edip size saldırana, size saldırdığı şekilde ve ölçüde saldırın. Allah'tan sakının ve bilin ki Allah, sakınanlarla beraberdir."},{"n":195,"t":"Allah yolunda infak edin/harcama yapın da kendi ellerinizle kendinizi tehlikeye atmayın! Güzel düşünüp güzel işler yapın/güzellik üretin! Çünkü Allah, güzellik sergileyenleri/ güzel düşünüp güzel iş yapanları sever."},{"n":196,"t":"Haccı da umreyi de Allah için tamamlayın. Eğer engellenirseniz, esir veya köle âzatlamak, Kâbe'ye kurbanlık hayvan veya başka bir şey sunmak şeklinde bağışta bulunmanın kolayınıza geleni yeterlidir. Bağış, kendi yerine varıncaya kadar başlarınızı tıraş etmeyin. İçinizden hasta olan yahut başından rahatsızlığı bulunan oruç tutarak yahut sadaka vererek veya kurban keserek/Allah'a yakınlık için Kâbe'ye bir şey bağışlayarak fidye yoluna gitsin. Güvene kavuştuğunuzda, hacca kadar umreden yararlanmak isteyen, esir veya köle âzatlamak, Kâbe'ye kurbanlık hayvan veya başka bir şey sunmak türünden kolayına gelen bir bağışta bulunsun! Bunu bulamayan oruç tutsun: Bu, üç günü hacda, yedi günü döndüğünüzde, tam on gündür. Bu, ailesi Mescid-i Haram'da oturmayan kişi içindir. Allah'tan sakının ve bilin ki, Allah'ın azabı çok şiddetlidir."},{"n":197,"t":"Hac, bilinen aylardadır. Kim o aylarda haccı kendisine gerekli kılarsa hacda kadına yaklaşmak, kötülüğe sapmak, kavga ve çekişmeye girmek yoktur. İyilik olarak yaptığınızı Allah bilir. Azık edinin. Hiç kuşkusuz azığın en güzeli takvadır. Ey akıl ve gönül sahipleri, benden sakının!"},{"n":198,"t":"Rabbinizden bir lütuf ve bereket istemenizde hiçbir sakınca yoktur. Arafat'tan ayrılıp akın ettiğinizde Meş'a-i Haram'da Allah'ı zikredin. O'nu, O'nun size gösterdiği gibi anın. Siz bundan önce gerçekten sapıklardan idiniz."},{"n":199,"t":"Sonra, insanların akın edip döndüğü yerden siz de dönün ve Allah'tan af dileyin. Çünkü Allah çok affedicidir, çok merhametlidir."},{"n":200,"t":"Gerekli ibadetlerinizi bitirdiğinizde yine Allah'ı anın. Tıpkı atalarınızı andığınız gibi, hatta daha kuvvetli bir anışla. İnsanlardan bazısı şöyle der: \"Ey Rabbimiz, bize dünyada ver!\" Böylesi için âhirette bir nasip yoktur."},{"n":201,"t":"Onlardan kimi de şöyle yakarır: \"Ey Rabbimiz, bize dünyada da güzellik ver, âhirette de güzellik ver! Ve bizi ateş azabından koru!\""},{"n":202,"t":"İşte böyle diyenlere kazandıklarından bir nasip vardır. Allah, hesabı çok çabuk görür."},{"n":203,"t":"Allah'ı sayılı günlerde anın. Kim hemen iki gün içinde işini bitirirse ona günah yoktur. Kim de bunu geciktirir-ertelerse, sakınıp korunduğu takdirde ona da günah yoktur. Allah'tan sakının ve bilin ki, siz O'nun huzurunda haşredileceksiniz."},{"n":204,"t":"İnsanlardan öylesi vardır ki, onun dünya hayatına ilişkin sözü senin hoşuna gider ve o, kalbindekine Allah'ı tanık tutar. Oysaki o, düşmanların en yamanıdır."},{"n":205,"t":"Yanından ayrıldığında/işbaşına geçtiğinde yeryüzünde fesat çıkarmak, ekini ve nesli yok etmek için işe koyulur. Oysaki Allah, fesadı sevmez."},{"n":206,"t":"Ona, \"Allah'tan sakın!\" dendiğinde, gurur kendisini günaha götürür. Böylesine, cehennem yeter. Gerçekten ne kötü yataktır o!"},{"n":207,"t":"İnsanlardan öylesi de vardır ki, benliğini Allah'ın hoşnutluğunu elde etmeye satar. Allah, kullarına karşı Raûf'tur, çok şefkatlidir."},{"n":208,"t":"Ey iman sahipleri! Hepiniz toptan barış içine girin. Şeytanın adımlarını izlemeyin. Çünkü o, sizin için apaçık bir düşmandır."},{"n":209,"t":"Size apaçık deliller geldikten sonra yine yan çizerseniz, şunu bilin ki Allah, tüm yüceliklerin, tüm hikmetlerin sahibidir."},{"n":210,"t":"Onlar, Allah'ın ve meleklerin buluttan gölgeler içinde kendilerine gelmesini ve işin bitirilmesini mi bekliyorlar? Bütün iş ve oluşlar sonunda Allah'a döndürülür."},{"n":211,"t":"Sor İsrailoğullarına, onlara nice açık ayet verdik. Kim Allah'ın nimetini, o kendisine geldikten sonra başka kılığa sokarsa kuşku duymasın ki, Allah'ın azabı pek zorludur."},{"n":212,"t":"İğreti/sefil hayat küfre sapanlara süslü gösterilmiştir; onlar, iman sahipleriyle alay ederler. Takvaya sarılanlar, kıyamet günü onların tepelerinde olacaktır. Allah, dilediğini hesapsız bir biçimde rızıklandırır."},{"n":213,"t":"İnsanlar bir tek ümmet idi. Sonra Allah, peygamberleri müjdeleyiciler ve uyarıcılar olarak gönderdi. Onlarla beraber, anlaşmazlığa düştükleri konularda, insanlar arasında hükmetsinler diye gerçeği taşıyan kitabı hak olarak indirdi. O kitapta anlaşmazlığa düşenler, o kitap kendilerine verilmiş olanlardan başkaları değildi. Bunlar, kendilerine açık kanıtlar geldikten sonra sırf aralarındaki kıskançlık/doymazlık/azgınlık/denge noktasından sapma/yalancılık/zulüm/kibir/zinakârlık yüzünden, çekişmeye girmiştir. Sonra Allah kendi izniyle, inananları, üzerinde tartışmaya girdikleri gerçeğe tekrar ulaştırdı. Allah, dilediği kişiyi/dileyeni dosdoğru yola iletir."},{"n":214,"t":"Yoksa siz, sizden önce gelip geçmiş olanların karşılaştıklarının benzeri başınıza gelmeden cennete gireceğinizi mi sandınız? Onlara şiddetler, belalar ve zorluklar gelip çattı; sarsıldılar. Öyle ki, resul ve onunla birlikte inananlar, \"Allah'ın yardımı ne zaman?\" diye yakarıyordu. Haberiniz olsun ki, Allah'ın yardımı çok yakındır."},{"n":215,"t":"Sana, neyi infak edip vereceklerini soruyorlar. De ki: \"İnfak ettiğiniz mal ve nimet; ana-baba, yakınlar, yetimler, yoksul ve çaresizlerle yolda kalan için olmalıdır. Hayır olarak yaptığınızı Allah en iyi biçimde bilmektedir.\""},{"n":216,"t":"Hoşunuza gitmemekle birlikte, savaş üzerinize yazılmıştır. Bir şey sizin için hayırlı olduğu halde siz ondan tiksinebilirsiniz. Ve bir şey sizin için şer olduğu halde siz onu sevebilirsiniz. Allah bilir, siz bilmezsiniz."},{"n":217,"t":"Sana haram ayı, onda savaşmayı soruyorlar. De ki: \"O ayda savaş büyük bir günahtır. Ama Allah yolundan alıkoymak, O'na ve Mescid-i Haram'a nankörlük etmek, ora halkını oradan sürüp çıkarmak, Allah katında daha büyük bir günahtır.\" Fitne/baskı ve bozgunculuk, cana kıymaktan daha büyük bir kötülüktür. Eğer güçleri yetse sizi dininizden çevirinceye kadar sizinle savaşmayı sürdürürler. İçinizden kim irtidat edip dininden döner de kâfir olarak ölürse böylelerinin amelleri dünyada da âhirette de boşa gitmiştir. Ateş ehlidir onlar. Sürekli kalacaklardır orada."},{"n":218,"t":"İnanıp hicret eden ve Allah yolunda uğraşıp didinenlere gelince, onlar Allah'ın rahmetini umarlar. Allah çok affedici, çok merhametlidir."},{"n":219,"t":"Sana uyuşturucuyu/şarabı ve kumarı sorarlar. De ki: \"Bu ikisinde büyük bir günah vardır; insanlar için çıkarlar da vardır. Ama onların kötülüğü yararlarından çok daha büyüktür.\" Ve sana neyi infak edeceklerini de soruyorlar. De ki: \"Helal kazancınızın size ve bakmakla yükümlü olduklarınıza yeterli olanından artanını verin.\" Allah, ayetleri size işte böyle açıklar ki, derin derin düşünebilesiniz."},{"n":220,"t":"Dünya ve âhiret hakkında... Sana yetimlerden de soruyorlar. De ki: \"Onları, işe yarar hale getirmek kendileri için daha hayırlıdır. Eğer onlarla bir arada yaşarsanız, onlar sizin kardeşlerinizdir.\" Allah, bozguncuyu barışseverden ayırmasını bilir. Eğer Allah dileseydi, sizi zora sürerdi. Allah, tüm onurların sahibi, tüm hikmetlerin sahibidir."},{"n":221,"t":"Müşrik kadınlarla, onlar iman edinceye kadar evlenmeyin. Özgürlüğünden yoksun inanmış bir kadın, müşrik bir kadından -müşrik kadın sizin hoşunuza gitse de- çok daha hayırlıdır. Müşrik erkeklerle de onlar iman edinceye kadar nikâhlanmayın. İnanmış bir köle, müşrik bir erkekten -o hoşunuza gitse de- çok daha hayırlıdır. Bu müşrikler sizleri ateşe çağırır. Allah ise sizi, izniyle cennete ve affa çağırır. Ve ayetlerini insanlara açık açık bildirir ki, düşünüp öğüt alabilsinler."},{"n":222,"t":"Sana âdet halini de sorarlar. De ki: \"O, insana rahatsızlık veren bir haldir. Hayızlı oldukları sırada kadınlardan uzak durun ve onlar temizleninceye kadar kendilerine yaklaşmayın. İyice temizlendiklerinde, Allah'ın emrettiği yerden onlara gidin.\" Şu bir gerçek ki Allah, çok tövbe edenleri sever, iyice temizlenenleri de sever."},{"n":223,"t":"Kadınlarınız sizin tarlanızdır. O halde tarlanıza dilediğiniz şekilde varın. Öz benlikleriniz için önceden bir şeyler gönderin. Allah'tan sakının ve bilin ki, O'na mutlaka ulaşacaksınız. İman sahiplerine müjde ver."},{"n":224,"t":"İyilik etmenize, takvaya sarılmanıza, insanlar arasında barışı kurmanıza engel yapmak üzere Allah'ı yeminlerinize siper haline getirmeyin. Allah, her şeyi duyar, her şeyi bilir."},{"n":225,"t":"Allah sizi, dil sürçmesi sonucu, lağv/lakırdı olarak yaptığınız yeminlerinizden sorumlu tutmaz; ama O sizi kalplerinizin kazandığınızdan hesaba çeker. Allah Gafûr'dur, çok affeder; Halîm'dir, çok yumuşak davranır."},{"n":226,"t":"Kadınları hakkında îlâ yapanlar/yaklaşmamaya yemin edenler için dört ay bekleme vardır. Eğer o süre içinde eşlerine dönerlerse Allah bağışlayan, merhamet edendir."},{"n":227,"t":"Eğer boşanmaya kesin karar vermişlerse, şüphesiz Allah çok iyi işiten çok iyi bilendir."},{"n":228,"t":"Boşanmış kadınlar kendi başlarına üç hayız/temizlik süresi beklerler. Eğer Allah'a ve ahiret gününe inanıyorlarsa, Allah'ın rahimlerinde yarattığını gizlemeleri kendilerine helal olmaz. Kocaları da bu süre içinde barışmak/arayı düzeltmek isterlerse, onları geri almaya herkesten çok hak sahibidirler. Kadınların, örfe/makule uygun hakları, üzerlerindeki yükümlülüklere denktir. Ancak erkekler için onlar üzerinde bir derece var. Allah Azîz'dir, Hakîm'dir."},{"n":229,"t":"Boşama iki kezdir. Bunun ardından ya iyilikle tutmak ya da güzelce serbest bırakmak gerekir. Onlara verdiğinizden bir şeyi geri almanız size helal olmaz. Erkekle kadının Allah'ın sınırlarını korumada endişe etmeleri hali başka. Erkek ve kadının Allah'ın sınırlarında duramayacaklarından kaygılanırsanız, o zaman kadının verdiği fidyede ikisine de bir günah yoktur. İşte bunlar Allah'ın sınırlarıdır. Bunları aşmayın. Allah'ın sınırlarını aşanlar, işte onlar, zalimlerin ta kendileridirler."},{"n":230,"t":"Bütün bunların ardından erkek, kadını boşarsa artık bundan sonra başka bir eşle nikâhlanıncaya kadar ilk erkeğe helal olmaz. İkinci erkek kadını boşadığında, boşanan kadınla ilk erkek Allah'ın sınırlarını koruyabileceklerini düşünürlerse, birbirlerine dönmelerinde sakınca yoktur. İşte bunlar Allah'ın sınırlarıdır ki, Allah bunları bilgi sahibi bir topluluğa açıklar."},{"n":231,"t":"Kadınları boşadığınızda, bekleme sürelerini tamamladılar mı ya onları örfe uygun olarak tutun yahut da örfe uygun olarak serbest bırakın. Onları, zulmetmeniz için, zararlarına bir biçimde, tutmayın. Bunu yapan, öz benliğine zulmetmiş olur. Allah'ın ayetlerini eğlence aracı yapmayın. Allah'ın üzerinizdeki nimetini ve kendisiyle size öğüt vermek için indirdiği Kitap'ı ve hikmeti hatırlayın. Allah'tan korkun ve bilin ki, Allah herşeyi çok iyi bilmektedir."},{"n":232,"t":"Kadınları boşadığınız zaman bekleme sürelerini tamamladıklarında, kendi aralarında örfe uygun olarak anlaşmışlarsa eski kocalarıyla nikâhlanmaları hususunda onlara engel çıkarmayın. Bu, sizin Allah'a ve âhiret gününe inanmış olanınıza verilen öğüttür. Bu sizin için daha isabetli ve daha temizdir. Allah bilir ama siz bilmezsiniz."},{"n":233,"t":"Anneler çocuklarını -emzirmeyi tamamlamak isteyen kimseler için- tam iki yıl emzirirler. Annelerin yiyeceklerini ve giyeceklerini örfe uygun biçimde hazırlamak çocuğun babasına aittir. Hiçbir benlik yaratılış kapasitesi dışında birşeyle yükümlü tutulamaz. Anne çocuğu yüzünden, çocuğun babası da kendi çocuğu yüzünden zarara sokulmasın. Mirasçı için de aynı ilke uygulanır. Eğer anne-baba karşılıklı anlaşma ve danışma sonucu çocuğu sütten kesmek isterlerse, kendilerine günah yoktur. Çocuklarınızı sütanneye emzirtmek isterseniz, örfe uygun olarak belirlediğiniz ücreti güzelce teslim etmek şartıyla, bunu yapmanızda bir günah yoktur. Allah'tan korkun ve bilin ki Allah, yapmakta olduklarınızı en iyi biçimde görmektedir."},{"n":234,"t":"İçinizden ölüp de geriye zevceler bırakanların bu eşleri, dört ay on gün kendi başlarına beklerler. Sürelerini tamamladıklarında kendilerince uygun gördüklerini örfe uygun biçimde yapmalarında sizin için bir sakınca yoktur. Allah, yapmakta olduklarınızdan gereğince haberdardır."},{"n":235,"t":"İddet bekleyen kadınlara evlenme isteğinizi dolaylı yoldan anlatmanızda veya böyle birşeyi içinizde saklamanızda sizin için hiçbir günah yoktur. Allah bilmiştir ki, siz onları mutlaka anacaksınız, unutmayacaksınız. Bu sırada onlarla, örfün normal göreceği sözlerle konuşma dışında gizli bir buluşma için anlaşmayın. Ve zorunlu olan süre doluncaya kadar nikâhı bağlamaya girişmeyin. Bilin ki, Allah, benliklerinizin içindekini bilir. O'ndan sakının. Ve bilin ki, Allah çok affedicidir, çok yumuşak davranışlıdır."},{"n":236,"t":"Kendilerine dokunmadan veya onlar için herhangi bir mehir belirlemeden kadınları boşamanızda sizin için günah yoktur. Ancak onları nimetlendirin. İmkânları geniş olan kendi gücünde yapar bunu, imkânları sınırlı olan da kendi gücünde yapar. Örfe uygun bir nimetlendirme... Güzel düşünüp güzel davrananlar üzerine bir borç..."},{"n":237,"t":"Onlara dokunmadan önce, fakat kendilerine bir mehir kestiğiniz halde boşamışsanız, kestiğinizin yarısı onlarındır. Ancak kadınların bağışlaması yahut nikâh bağı elinde bulunanın bağışlaması müstesnadır. Bağışlamanız/vazgeçmeniz takvaya daha yakındır. Aranızdaki fazileti/ lütfu unutmayın. Şüphesiz Allah, yaptıklarınızı iyice görmektedir."},{"n":238,"t":"Namazları/duaları ve orta namazı/orta duayı koruyun. Tam bir saygıyla Allah'ın huzurunda kıyam edin."},{"n":239,"t":"Bir korku ve endişe duyarsanız yürüyerek veya binit üzerinde kılın. Güvene kavuştuğunuzda bilmediğiniz şeyleri size öğrettiği şekilde Allah'ı zikredin."},{"n":240,"t":"İçinizden ölüp de geriye eşler bırakan erkekler, eşlerinin evden çıkarılmaksızın bir yıla kadar geçimlerinin sağlanmasını vasiyet etsinler. Eğer kendileri çıkarlarsa, onların kendileri için yararlı gördüklerini yapmaları yüzünden size bir günah yoktur. Allah Azîz'dir, Hakîm'dir."},{"n":241,"t":"Boşanmış kadınlar için örfe uygun bir geçim imkânı sağlanması Allah'tan korkanlar üzerine bir borçtur."},{"n":242,"t":"Aklınızı işletmeniz ümidiyle Allah, ayetlerini size işte böyle açıklıyor."},{"n":243,"t":"Ölüm korkusuyla binlerce kişi halinde yurtlarından çıkanları görmedin mi? Allah onlara \"Ölün!\" dedi de sonra onları diriltti. Şu bir gerçek ki Allah, insanlara karşı çok lütufkârdır. Fakat insanların çokları şükretmezler."},{"n":244,"t":"Allah yolunda savaşın ve bilin ki Allah, herşeyi duyar, her şeyi bilir."},{"n":245,"t":"Kim var Allah'a güzel bir şekilde borç verecek? Ve Allah böyle birinin verdiğini birçok kez katlayarak artıracaktır. Allah, kabz haliyle kısar, bast haliyle açıp genişletir. Ve yalnız O'na döndürülürsünüz."},{"n":246,"t":"Mûsa'dan sonra İsrailoğullarının kodamanlar meclisini görmedin mi? Kendilerine gelen bir peygambere şöyle demişlerdi: \"Bize bir kral gönder, Allah yolunda çarpışalım.\" Peygamber dedi ki: \"Üstünüze savaş yazılır da savaşmazsanız ne olacak?\" Dediler ki: \"Nasıl olur da Allah yolunda savaşmayız? Yurtlarımızdan çıkarıldık, oğullarımızdan uzak düşürüldük.\" Nihayet, üzerlerine savaş yazıldığında pek azı hariç yüz çevirdiler. Allah, zalimleri çok iyi bilir."},{"n":247,"t":"Peygamberleri onlara dedi ki: \"Allah, Tâlût'u size kral gönderdi.\" Şöyle konuştular: \"O bizim üzerimizde nasıl saltanat kurabilir? Yönetimde biz ondan daha çok hak sahibiyiz. Ona bir mal genişliği de verilmemiştir.\" Peygamber dedi ki: \"Allah onu seçip size üst olarak gönderdi. Onu bilgi ve beden gücü yönünden üstün kıldı.\" Allah, mülkünü dilediğine verir. Allah, mülkü genişletendir, her şeyi bilendir."},{"n":248,"t":"Nebileri onlara şöyle söyledi: \"Onun mülk ve saltanatının belirtisi o Tabut'un size gelmesidir. Onun içinde Rabbinizden bir huzur, Hârun hanedanının, Mûsa hanedanının bıraktığından bir kalıntı vardır. Onu melekler taşır. Eğer iman sahipleri iseniz, bunda sizin için elbette bir ibret vardır.\""},{"n":249,"t":"Tâlût, askerleriyle yola çıkınca dedi ki: \"Allah sizi bir ırmakla imtihan edecektir. O halde, ondan içen benden değildir. Ama onu tatmayan bendendir. Eliyle bir avuç alan kişi başka.\" Bunun ardından, pek azı müstesna olmak üzere ondan içtiler. Nihayet o ve onunla beraber iman edenler ırmağı geçtiklerinde şöyle dediler: \"Bugün bizim Câlût'a ve ordusuna karşı hiçbir gücümüz yoktur.\" Allah'a kavuşacaklarını düşünenler ise şöyle konuştular: \"Sayıca az nice topluluk vardır ki, sayıca çok nice topluluğa Allah'ın izniyle galip gelmiştir. Allah sabredenlerle beraberdir.\""},{"n":250,"t":"Câlût ve ordusuyla karşılaştıklarında şöyle yakardılar: \"Ey Rabbimiz, üzerimize sabır yağdır. Ayaklarımızı yere sağlam bastır. Ve küfre sapanlara karşı bize yardım et.\""},{"n":251,"t":"Derken, Allah'ın izniyle onları bozguna uğrattılar. Davud, Câlût'u öldürdü. Ve Allah ona mülkü/ saltanatı ve hikmeti verdi, ona dilediği şeylerden öğretti. Eğer Allah'ın, insanların bir kısmını diğer bir kısmıyla savması/dengelenmesi olmasaydı, yeryüzü mutlaka fesada uğrardı. Fakat Allah, âlemlere karşı çok lütufkârdır."},{"n":252,"t":"İşte bunlar Allah'ın ayetleri. Onları sana hak olarak okuyoruz. Yemin olsun ki sen, gönderilen elçilerdensin."},{"n":253,"t":"İşte resuller! Biz onların bazısını bazısına üstün kılmışızdır. Allah, onlardan bazısıyla konuşmuştur. Bazılarını da derecelerle yüceltmiştir. Meryem oğlu İsa'ya açık ayetler verdik ve onu Ruhulkudüs'le güçlendirdik. Allah dileseydi, onların ardından gelenler, açık-seçik mesajlar kendilerine ulaştıktan sonra birbirlerini öldürmezlerdi. Ancak tartışmaya girdiler de içlerinden bazısı iman etti, bazısı küfre saptı. Allah dileseydi birbirlerini öldürmezlerdi. Ne var ki, Allah dilediğini yapıyor."},{"n":254,"t":"Ey iman edenler! Alış-verişin, dostluğun, şefaatin olmadığı o gün gelmeden önce size verdiğimiz rızıktan infak edip dağıtın. Küfre sapanlar zalimlerin ta kendileridir."},{"n":255,"t":"Allah'tan başka ilah yok. Hayy'dır O, sürekli diridir; Kayyûm'dur O, kudretin kaynağıdır. Ne gaflet yaklaşır O'na ne kendinden geçme ne de uyku. Göklerde ne var, yerde ne varsa yalnız O'nundur. O'nun huzurunda, bizzat O'nun izni olmadıkça, kim şefaat edebilir! O, insanların önden gönderdiklerini de bilir, arkada bıraktıklarını da!... İnsanlar O'nun bilgisinden, bizzat kendisinin dilediği dışında, hiçbir şeyi kavrayıp kuşatamazlar. O'nun kürsüsü, gökleri ve yeri çepeçevre kuşatmıştır. Göklerin ve yerin korunması O'na hiç de zor gelmez. Aliyy'dir O, yüceliği sınırsızdır; Azim'dir O, büyüklüğü sınırsızdır."},{"n":256,"t":"Dinde zorlama/baskı yoktur. Doğru bilgi/doğruluk, sapıklıktan/eğrilikten iyice ayrılmıştır. Artık kim Tâğut'u reddedip Allah'a inanırsa, kopması mümkün olmayan en sağlam kulpa yapışmış olur. Allah Samî'dir, Alîm'dir."},{"n":257,"t":"Allah, iman sahiplerinin Velî'sidir; onları karanlıklardan aydınlığa çıkarır. Küfre sapanlara gelince, onların dostları tâğuttur ki, kendilerini nurdan karanlıklara çıkarır. Bunlar cehennemin dostlarıdır. Orada uzun süre kalacaklardır onlar."},{"n":258,"t":"Allah'ın kendisine mülk ve saltanat verdiğini iddia ederek/Allah kendisine mülk- saltanat verdiği için, Rabbi hakkında İbrahim'le çekişeni görmedin mi? İbrahim şöyle demişti: \"Benim Rabbim odur ki, hayat verir ve öldürür.\" O da şöyle demişti: \"Ben de hayat veririm, ben de öldürürüm.\" İbrahim, \"Allah, Güneş'i doğudan getiriyor, hadi sen onu batıdan getir!\" deyince, küfre sapan o adam apışıp kalmıştı. Allah, zalimler toplumunu doğruya ve güzele kılavuzlamaz."},{"n":259,"t":"Ya şu kişi gibisini görmedin mi? Çatıları çökmüş, duvarları-damları yere inmiş bir kente uğramıştı da şöyle demişti: \"Allah şurayı ölümünden sonra nasıl hayata kavuşturacak?\" Bunun üzerine Allah, o kişiyi yüz yıllık bir süre için öldürmüş, sonra diriltmişti. \"Ne kadar bekledin?\" demişti. \"Bir gün veya günün bir kısmı kadar bekledim.\" dedi. \"Hayır, dedi, aksine sen, yüz yıl kaldın. Yiyeceğine, içeceğine bak! Henüz bozulmamış. Eşeğine bak! Seni insanlara bir ibret yapalım diyedir bu. Kemiklere bak, nasıl yerli yerince düzenliyoruz onları ve sonra et giydiriyoruz onlara.\" İş kendisi için açıklık kazanınca şöyle dedi o: \"Allah'ın her şeye kadir olduğunu biliyorum.\""},{"n":260,"t":"Hani, İbrahim de şöyle yakarmıştı: \"Rabbim, göster bana, nasıl diriltiyorsun ölüleri?\" \"İnanmadın mı?\" diye sordu. \"İnandım, dedi, ancak kalbimin tatmin olması için ...\" Allah dedi ki: \"Kuşlardan dört tane al, onları kendine ısındırıp alıştır. Sonra her dağın üstüne onlardan bir parça koy. Sonra da onları çağır. Koşarak sana geleceklerdir. Bil ki Allah Azîz'dir, Hakîm'dir."},{"n":261,"t":"Mallarını Allah yolunda infak edip harcayanların durumu, yerden, her başağında yüz dane bulunan yedi başak çıkarmış bir daneye benzer. Ve Allah, dilediği kişi için daha da arttırır. Allah Vâsi'dir, yaratışını ve yarattıklarını genişletir; Alîm'dir, her şeyi en iyi biçimde bilir."},{"n":262,"t":"Mallarını Allah yolunda harcayıp sonra bu harcadıklarına bir eziyet ve başa kakma eklemeyenlerin, Rableri katında kendilerine has ödülleri vardır. Korku yoktur onlar için; tasalanmayacaklardır onlar."},{"n":263,"t":"Güzel, yapıcı bir söz, bir bağışlama, ardından bir eziyet gelen sadakadan daha üstündür. Allah Ganî'dir, cömertliğine sınır yoktur; Halîm'dir, hoşgörüsüne sınır yoktur."},{"n":264,"t":"Ey iman sahipleri! Allah'a ve âhiret gününe inanmadığı halde, insanlara riya için malını infak eden kişi gibi, sadakalarınızı başa kakmak ve eza etmek suretiyle boşa çıkarmayın. Böylesinin durumu, üzerinde biraz toprak varken tepesine şiddetli bir yağmur inip kendisini cascavlak bırakmış yalçın bir kayanın haline benzer. Böyleleri, kazandıklarından hiçbir şey elde edemezler. Allah, küfre sapan bir topluluğu doğruya ve güzele kılavuzlamaz."},{"n":265,"t":"Allah'ın hoşnutluğunu kazanmak ve öz benliklerindekini kökleştirmek için infakta bulunanlara gelince, onların durumu kendisine bol yağmur isabet edip de ürününü iki kat veren bir bahçenin durumuna benzer. Böyle bir bahçeye bol yağmur düşmese de bir çisinti, bir nem bile yetişir. Allah, yapmakta olduklarınızı tam bir biçimde görmektedir."},{"n":266,"t":"Herhangi biriniz ister mi ki; altından ırmaklar akan, içinden her tür meyvesi olan, hurmalardan, üzümlerden oluşmuş bir bahçesi bulunsun, kendisinin güçsüz-çaresiz yavruları da olsun ve bu haldeyken üstüne ihtiyarlık çöksün, tam bu sırada o bahçeye alevli bir bora isabet etsin de bahçe, baştan başa yansın. Allah size ayetleri işte bu şekilde açıklıyor ki, inceden inceye ve derinden derine düşünebilesiniz."},{"n":267,"t":"Ey iman edenler! Kazandıklarınızın ve sizin için topraktan çıkardıklarımızın temiz/güzel olanlarından infak edin/harcayın! Kendinizin göz yumup tiksinmeden alamayacağınız aşağılık/bayağı şeyleri vermeye kalkışmayın! Bilin ki Allah Ganî'dir, Övülmeye Layık Olandır."},{"n":268,"t":"Şeytan sizi fakirlikle korkutur, size görünür görünmez çirkinliklere sürükler, Allah ise size kendisinden bir bağışlanma ve lütuf vaat eder. Allah, Vâsi'dir, Alîm'dir."},{"n":269,"t":"O, hikmeti dilediğine verir. Ve kendisine hikmet verilmiş olana çok büyük bir hayır verilmiş demektir. Gönlünü ve aklını çalıştıranlardan başkası düşünüp anlayamaz."},{"n":270,"t":"Hayır olarak harcadığınız, adak olarak adadığınız her şeyi, Allah mutlaka bilir. Zalimlerin yardımcıları olmayacaktır."},{"n":271,"t":"Sadakaları açıklarsanız bu da güzeldir. Ama onları gizler ve yoksullara bu şekilde verirseniz, bu sizin için daha hayırlıdır; günahlarınızdan bir kısmını örter. Allah, Habîr'dir, yapmakta olduklarınızdan gereğince haberi vardır."},{"n":272,"t":"Onların iyiyi ve güzeli bulmaları, senin üzerine bir borç değildir. Tam aksine, dilediğini/dileyeni iyiye ve güzele kılavuzlayan Allah'tır. Nimet ve imkândan başkalarına bağışladığınız, esasında sizin öz benlikleriniz lehinedir. Allah'ın yüzünü arzulama dışında bir şey için infak etmiyorsunuz. İnfak ettiğiniz her nimet size tam bir biçimde geri verilir. Ve siz, asla zulme uğratılmazsınız."},{"n":273,"t":"İnfak edilenler, Allah yolunda kapanıp kalmış, yeryüzünde dolaşamaz olmuş yoksullar içindir. İffet ve onurları yüzünden, cahiller bunları, zengin kişiler sanır. Sen onları yüzlerinden tanırsın. Yüzsüzlük ve yırtıklık ederek insanlardan bir şey istemezler. Nimet ve imkândan infak ettiğiniz her şeyi, Allah çok iyi bilmektedir."},{"n":274,"t":"Mallarını; gece ve gündüz, gizli ve açık infak edenler var ya, işte onlar için Rableri katında kendilerine özgü ödüller vardır. Korku yoktur onlar için; tasalanmayacaklardır onlar."},{"n":275,"t":"O ribayı yiyenler, şeytanın bir dokunuşla çarptığı kişinin kalkışından başka türlü kalkamazlar. Bu böyledir, çünkü onlar, \"Alış-veriş de riba gibidir.\" demişlerdir. Oysaki Allah, alış-verişi helal, ribayı haram kılmıştır. Kendisine Rabbinden bir öğüt gelip de yaptığından vazgeçenin geçmişi kendisine, işi Allah'a kalmıştır. Yeniden ribaya dönene gelince, böyleleri ateşin dostlarıdır. Sürekli kalacaklardır orada."},{"n":276,"t":"Allah, ribadan beklenen artışı mahveder, sadakalar karşılığında artışlar getirir. Allah, nankörlüğe batmış günahkârların hiçbirini sevmez."},{"n":277,"t":"İman edip barışa/hayra yönelik değerler üreten, namazı/duayı yerine getiren, zekâtı verenler için Rableri katında kendilerine özgü ödülleri vardır. Korku yoktur onlar için. Tasalanmayacaklardır onlar..."},{"n":278,"t":"Ey iman sahipleri, Allah'tan korkun. Ve eğer inanıyorsanız ribadan geri kalanı bırakın."},{"n":279,"t":"Eğer bunu yapmazsanız, Allah ve resulünden bir harp ilanını duymuş olun. Tövbe ederseniz, mallarınızın esasları/ana paralarınız sizindir; ne zulmeden olursunuz ne de zulme uğratılan."},{"n":280,"t":"Eğer borçlu darlık içindeyse, varlık kazanıncaya kadar beklenir. Borcu sadaka olarak bağışlamanız ise sizin için daha hayırlıdır, eğer bilirseniz."},{"n":281,"t":"Korkun o günden ki, onda Allah'a döndürüleceksiniz. Sonra her benliğe kazanmış olduğu tam bir biçimde verilecektir. Onlar hiçbir zulme uğratılmayacaklardır."},{"n":282,"t":"Ey iman sahipleri! Belirli bir süre için birbirinize borç verdiğinizde onu yazın. Aranızda bir yazıcı adaletle yazsın. Yazıcı, Allah'ın kendisine öğrettiği şekilde yazmaktan kaçınmasın, yazsın. Borç altına giren kişi de onu kayda geçirtsin ve Rabbinden korksun da borcundan hiçbir şey eksiltmesin. Borç altına giren, aklı ermez yahut zayıf-çaresiz biri ise yahut yazdırmaya gücü yetmiyorsa, velisi adaletle yazdırsın. Erkeklerinizden iki kişiyi de tanık tutun. Eğer iki erkek yoksa rızanızla kabul edeceğiniz tanıklardan bir erkek ve iki kadın gerekir. Bu kadınlardan biri şaşırırsa/unutursa ötekisi ona hatırlatsın diyedir. Tanıklar, çağırıldıklarında çekimser davranmasınlar. Küçük veya büyük, borcu, süresine kadar yazmaktan üşenmeyin. Böyle yapmanız Allah katında adalete daha yakın, tanıklık için daha sağlam, kuşkuya düşmemeniz için daha elverişlidir. Ancak aranızda döndürüp durduğunuz tamamen peşin bir ticaret sözkonusu ise onu yazmamanızda sizin için bir sakınca yoktur. Karşılıklı alış-veriş yaptığınızda da tanık bulundurun. Yazıcıya da tanığa da zarar verilmesin. Böyle bir şey yaparsanız bu, kendinize kötülük olur. Allah'tan korkun. Allah size öğretiyor. Allah, her şeyi en iyi biçimde bilendir."},{"n":283,"t":"Eğer yolculuk halinde olur da yazacak birini bulamazsanız, o takdirde, alınan rehinler yeter. Birbirinize güvenmişseniz, kendisine güvenilen kişi, emaneti ödesin; Rabbi olan Allah'tan sakınsın. Tanıklığı gizlemeyin. Onu gizleyen, kalbi günaha batmış/kendi kalbine kötülük etmiş biridir. Allah, yapmakta olduklarınızı çok iyi bilmektedir."},{"n":284,"t":"Göklerdekiler de yerdekiler de yalnız Allah'ındır. İçlerinizdekini açıklasanız da gizleseniz de Allah, ondan sizi hesaba çeker de dilediğini bağışlar, dilediğine azap eder. Allah Kadîr'dir, her şeye gücü yeter."},{"n":285,"t":"Resul, Rabbinden kendisine indirilene inanmıştır; müminler de. Hepsi; Allah'a, onun meleklerine, kitaplarına, resullerine inanmışlardır. Allah'ın resullerinden hiçbirini ötekinden ayırmayız. Şöyle demişlerdi: \"Dinledik, boyun eğdik. Affet bizi, ey Rabbimiz. Dönüş yalnız sanadır.\""},{"n":286,"t":"Allah hiçbir benliğe, yaratılış kapasitesinin üstünde bir yük yüklemez/teklifte bulunmaz. Her benliğin yaptığı iyilik kendi lehine, işlediği kötülük kendi aleyhinedir/kişinin hem kendisini hem başkaları için kazandığı onun lehine, yalnız kendi nefsi için kazandığı onun aleyhinedir/kişinin kendi emeği ile kazandığı lehine, başkalarının sırtından kazandığı aleyhinedir. \"Ey Rabbimiz! Unutur yahut hata edersek bizi hesaba çekme. Ey Rabbimiz! Bize, bizden öncekilere yüklediğin gibi ağır yük yükleme. Ey Rabbimiz! Bize, güç yetiremeyeceğimiz şeyleri de yükleme. Affet bizi, bağışla bizi, acı bize. Sen bizim Mevlâ'mızsın. Gerçeği örten nankörler/inkârcılar topluluğuna karşı yardım et bize!\""}],[{"n":1,"t":"Elif, Lâm, Mîm."},{"n":2,"t":"Allah... İlâh yok O'ndan başka... Hayy'dır O, Kayyûm'dur."},{"n":3,"t":"O, sana Kitap'ı, önündekileri tasdikleyici olarak hak bir yoldan indirdi. Tevrat'ı ve İncil'i de indirmişti."},{"n":4,"t":"Daha önce insanlara bir yol gösterici olarak Furkan'ı da indirdi. Şu bir gerçek ki, Allah'ın ayetlerini örtüp inkâr edenler için şiddetli bir azap vardır. Ve Allah hem Azîz'dir hem intikam alıcı..."},{"n":5,"t":"Allah... Gökte ve yerde hiçbir şey O'na gizli kalmaz."},{"n":6,"t":"Rahimlerde sizi dilediğince şekillendiren O'dur. İlâh yok O'ndan başka. Azîz'dir O, Hakîm'dir."},{"n":7,"t":"Kitap'ı sana indiren O'dur: Onun ayetlerinden bir kısmı muhkemlerdir ki; onlar Kitap'ın anasıdır. Diğer ayetlerse müteşâbihlerdir. Şu var ki, kalplerinde bir eğrilik ve bozukluk bulunanlar, fitne aramak, onun teviline öncelik tanımak için Kitap'ın sadece müteşâbih kısmının ardına düşerler. Onun tevilini ise bir Allah bilir, bir de ilimde derinleşmiş olanlar. Bunlar, \"Ona inandık, hepsi Rabbimizin katındandır.\" derler. Gönül ve akıl sahiplerinden başkası gereğince düşünemez."},{"n":8,"t":"Ey Rabbimiz! Bizi doğruya ve güzele yönelttikten sonra kalplerimizi bozup eğriltme ve bize katından bir rahmet bağışla! Sen, yalnız sen Vahhâb'sın, bol bol bağışta bulunansın."},{"n":9,"t":"Ey Rabbimiz! Sen Câmî'sin; insanları varlığında kuşku bulunmayan bir günde mutlaka toplayacaksın. Allah, sözünü yerine getireceği yer ve zamanı asla şaşırmaz."},{"n":10,"t":"Küfre sapanlara gelince, onların malları da çocukları da Allah'a karşı kendilerine hiçbir yarar sağlamayacaktır. Onlar, işte onlar, ateşin yakıtıdırlar."},{"n":11,"t":"Tıpkı Firavun hanedanı ve onlardan öncekilerin durumu gibi. Ayetlerimizi yalanlamışlardı da Allah, onları günahları yüzünden yakalamıştı. Allah, cezayı çok şiddetli vermektedir."},{"n":12,"t":"De o küfre sapanlara: \"Yenileceksiniz ve cehenneme sürüleceksiniz. Ne kötü döşektir o!\""},{"n":13,"t":"Yüz yüze gelen şu iki toplulukta sizin için bir ibret vardır: Biri Allah yolunda çarpışıyordu; ötekisi küfre batmıştı. Allah yolunda çarpışanları, kafa gözleriyle kendilerinin iki katı görüyorlardı. Allah, öz yardımıyla dilediğini destekler. İşte bunda, gözleri olanlar için gerçek bir ibret vardır."},{"n":14,"t":"Kadınlara, oğullara, altın ve gümüşten oluşturulmuş yığınlara, salma atlara, davarlara ve ekinlere tutkunlukların sevgisi, insanlar için süslenip püslenmiştir. Tüm bunlar geçici-iğreti hayatın nimetidir. Allah'a gelince, varılacak yerin en güzeli onun yanındadır."},{"n":15,"t":"De ki: \"Bu sayılanlardan daha iyisini size haber vereyim mi? Sakınıp korunanlar için, Rableri katında, altlarından nehirler akan, içinde sürekli kalacakları cennetler, tertemiz eşler ve Allah'tan bir hoşnutluk olacaktır. Allah, kulları en iyi biçimde görmektedir.\""},{"n":16,"t":"Kullar ki, şöyle derler: \"Ey Rabbimiz, kuşkusuz olarak sana inandık. Bağışla günahlarımızı, ateş azabından koru bizi!\""},{"n":17,"t":"Kullar ki, sabredenlerdir, özü-sözü doğru olanlardır, ilahî huzurda duranlardır, nimet ve imkânlardan başkalarını yararlandıranlardır; seherlerde, bağışlanmak için yakaranlardır."},{"n":18,"t":"Allah, kendisinden başka tanrı olmadığına tanıktır. Meleklerle ilim sahipleri de adalet ölçüsüne sarılarak tanıklık etmişlerdir ki, o Azîz ve Hakîm olandan başka hiçbir ilah yoktur."},{"n":19,"t":"Allah katında din İslam'dır/barış ve esenlik için Allah'a teslim olmaktır. Kitap verilmiş olanlar, kendilerine ilim geldikten sonra, aralarındaki kıskançlık/doymazlık/azgınlık/denge noktasından sapma/yalancılık/zulüm/kibir/zinakârlık yüzünden ihtilafa düştü. Kim Allah'ın ayetlerine nankörlük/Allah'ın ayetlerini inkâr ederse, Allah, hesabı çabucak görecektir."},{"n":20,"t":"Seninle kanıt yarıştırmaya girerlerse şöyle söyle: \"Ben yüzümü Allah'a teslim ettim. Bana uyanlar da.\" Kitap verilenlerle ümmîlere de sor: \"Siz de teslim oldunuz mu?\" Eğer teslim olurlarsa doğruya ve güzele kılavuzlanmışlardır. Yüz çevirirlerse sana düşen sadece tebliğ etmektir. Allah, kullarını görmektedir."},{"n":21,"t":"Allah'ın ayetlerini inkâr edip haksız yere peygamberleri öldürenler ve insanlar içinden adaletle emredenlerin canına kıyanlar var ya, işte onlara korkunç bir azabı muştula."},{"n":22,"t":"Çalışıp ürettikleri hem dünyada hem de âhirette boşa çıkmıştır. Hiçbir yardımcıları da yoktur onların."},{"n":23,"t":"Şu kendilerine kitaptan bir pay verilmiş olanlara bak, aralarında hüküm vermesi için Allah'ın kitabına çağırılıyorlar da içlerinden bir zümre yüz çevirerek dönüp gidiyor."},{"n":24,"t":"Bunun sebebi onların, \"Ateş bize sayılı birkaç gün dışında asla dokunmayacaktır\" demeleridir. Uydurmuş oldukları yalanlar, dinlerinde kendilerini aldatmaktadır."},{"n":25,"t":"Peki, o kendisinde kuşku bulunmayan günde, onları bir araya topladığımız vakit halleri nice olacak! O gün her benlik, kazandığının karşılığını tam almıştır. Onlar, hiçbir zulme uğratılmazlar."},{"n":26,"t":"Şöyle yakar: \"Ey mülkün/saltanatın Mâlik'i/sahibi olan Allahım! Sen mülkü/saltanatı dilediğine verir, mülkü/ saltanatı dilediğinden çekip alırsın. Dilediğini yüceltip aziz edersin, dilediğini alçaltıp zelil kılarsın. İmkân, mal ve nimet senin elindedir. Sen, her şeye kadirsin.\""},{"n":27,"t":"\"Geceyi gündüzün içine sokarsın, gündüzü de gecenin içine sokarsın. Diriyi ölüden çıkarırsın, ölüyü diriden çıkarırsın. Dilediğini hesapsızca rızıklandırırsın.\""},{"n":28,"t":"Müminler, müminleri bırakıp da küfre sapanları gönül dostu edinmesinler. Kim bunu yaparsa Allah'la ilişiği kesilir. Ancak bir sakınma ile onlardan korunmanız müstesna. Allah sizi kendisinden sakınmaya çağırır. Ve dönüş yalnız Allah'adır."},{"n":29,"t":"De ki: \"Göğüslerinizde olanı gizleseniz de açıklasanız da Allah onu bilir. Göklerdekileri, yerdekileri de bilir. Allah her şeye Kadîr'dir.\""},{"n":30,"t":"Gün gelecek, her benlik, hayırdan işlediğini önünde bulacaktır. Kötülükten işlediğini de... İsteyecektir ki, önüne getirilenle kendisi arasında uzun bir mesafe olsun. Allah sizi, kendisinden sakınmaya çağırır. Allah, kullarına karşı Raûf'tur, çok şefkatlidir."},{"n":31,"t":"De ki: \"Eğer Allah'ı seviyorsanız bana uyun ki, Allah da sizi sevsin ve günahlarınızı bağışlasın. Allah çok affedici, çok merhametlidir.\""},{"n":32,"t":"Şunu da söyle: \"Allah'a ve resule itaat edin.\" Eğer yüz çevirirlerse, Allah küfre sapanları sevmez."},{"n":33,"t":"Allah; Âdem'i, Nûh'u, İbrahim Ailesi'ni, İmran Ailesi'ni seçerek âlemlere üstün kılmıştır;"},{"n":34,"t":"Birbirinden gelen soylar halinde. Allah, hakkıyla işiten, gereğince bilendir."},{"n":35,"t":"Hani, İmran'ın karısı şöyle demişti: \"Rabbim, karnımdakini özgür bir biçimde sana adadım; onu benden kabul et! Kuşkusuz, sen, evet sen, her şeyi duyan, her şeyi bilensin!\""},{"n":36,"t":"Onu doğurunca -Allah onun ne doğurduğunu daha iyi bildiği halde- şöyle dedi: \"Rabbim, onu kız doğurdum. Erkek, kız gibi değildir. Ona Meryem adını verdim. Onu ve soyunu kovulmuş şeytandan sana sığınmaya emanet ediyorum.\""},{"n":37,"t":"Allah, onu güzel bir kabulle kabul etti ve onu güzel bir bitki gibi besleyip büyüttü. Onu, Zekeriyya'nın korumasına verdi. Zekeriyya, mihrapta onun yanına her girdiğinde, orada bir rızık bulur ve sorardı: \"Meryem, bu sana nereden?\" Meryem de \"Bu, Allah katındandır; çünkü Allah dilediğini hesapsızca rızıklandırır.\" derdi."},{"n":38,"t":"Zekeriyya orada Rabbine yakarmıştı: \"Rabbim, demişti, katından bana tertemiz bir soy bağışla! Sen yakarışı en iyi duyansın!\""},{"n":39,"t":"Zekeriyya mihrapta durmuş dua ederken/namaz kılarken, melekler ona şöyle çağırmıştı: \"Allah sana, Allah'tan bir kelimeyi doğrulayıcı bir efendi; nefsine egemen bir benlik, hayır ve barışı sevenlerden bir peygamber olarak Yahya'yı müjdeliyor.\""},{"n":40,"t":"Dedi ki: \"Rabbim, benim nasıl çocuğum olur? İhtiyarlık tam bir biçimde üstüme binmiş, karım ise kısır!\" Allah cevap verdi: \"Allah, dilediği şeyi işte böyle yapar!\""},{"n":41,"t":"Zekeriyya dedi: \"Rabbim, bana bir belirti ver!\" Allah buyurdu: \"Sana belirti şudur: \"İnsanlarla üç gün, işaretleşme dışında konuşmayacaksın. Rabbini çok an. Akşam-sabah tespih et!\""},{"n":42,"t":"Bir de melekler şöyle demişlerdi: \"Ey Meryem, Allah seni seçti. Seni tertemiz kıldı ve seni âlemlerin kadınları üstüne yüceltti.\""},{"n":43,"t":"\"Ey Meryem, Rabbinin huzurunda saygıyla el bağla. Secdeye kapan ve rükû edenlerle birlikte rükû et!\""},{"n":44,"t":"Bu, gayb haberlerindendir ki, sana vahyediyoruz. Onlar, Meryem'in bakımını kimin üstleneceğini belirlemek için kalemlerini atarlarken sen yanlarında değildin. Çekiştikleri sırada da yanlarında değildin."},{"n":45,"t":"Bir de, melekler şöyle demişti: \"Ey Meryem! Allah seni, kendisinden bir kelimeyle muştuluyor. Adı, Meryem'in oğlu İsa Mesih'tir. Dünya ve âhirette yüz akıdır. Allah'a yaklaştırılanlardandır.\""},{"n":46,"t":"\"Beşikte ve yetişkin çağında insanlarla konuşacaktır. Barışa ve hayra yönelik iş yapanlardandır.\""},{"n":47,"t":"Meryem dedi ki: \"Rabbim, çocuğum nasıl olur benim? Bana hiçbir insan dokunmadı ki!\" Allah cevap verdi: \"Allah dilediğini işte böyle yaratır! Bir iş ve oluşa karar verdiğinde sadece ona \"Ol!\" der; ve o hemen oluverir.\""},{"n":48,"t":"Ona Kitap'ı, hikmeti, Tevrat'ı ve İncil'i öğretecek."},{"n":49,"t":"Ve onu İsrailoğullarına bir resul yapacak. (O İsrailoğullarına şöyle diyecek:) \"Şu bir gerçek ki, ben size Rabbinizden bir mucize getirdim. Ben size çamurdan kuş biçiminde bir şey oluşturur, ona üflerim de Allah'ın izniyle kuş oluverir. Kör doğanı ve alacalıyı iyileştiririm. Allah'ın izniyle ölüleri diriltirim. Evlerinizde ne yediğinizi, ne biriktirdiğinizi size haber veririm. Eğer inananlarsanız, bunda sizin için tam bir mucize vardır.\""},{"n":50,"t":"\"Tevrat'tan önümde bulunanı doğrulayıcıyım. Size haram kılınmış olanın bir kısmını size helal yapacağım. Rabbinizden bir mucize getirdim size. Artık Allah'tan sakının ve bana itaat edin!\""},{"n":51,"t":"\"Allah benim de Rabbimdir, sizin de Rabbinizdir; o halde, O'na kulluk edin! İşte bu, dosdoğru bir yoldur.\""},{"n":52,"t":"İsa onlardan inkârı sezince şöyle konuştu: \"Allah'a gidişte benim yardımcılarım kim?\" Havâriler dediler ki: \"Biz Allah'ın yardımcılarıyız! Allah'a iman ettik biz! Tanık ol, biz müslümanlarız/Allah'a teslim olanlarız.\""},{"n":53,"t":"\"Ey Rabbimiz! Senin indirdiğine iman ettik, resule uyduk; artık bizi gerçeğin tanıklarıyla beraber yaz!\""},{"n":54,"t":"Onlar tuzak kurdular, Allah da tuzak kurdu. Ve Allah, tuzak kuranların en hayırlısıdır."},{"n":55,"t":"Allah şunu da demişti: \"Ey İsa, senin canını alacağım, seni kendime yükselteceğim; seni, inkâr edenlerden uzaklaştırıp arındıracağım. Ve sana uyanları, inkâr edenlerin, kıyamete kadar üstünde tutacağım. Sonra bana olacak dönüşünüz; tartışıp durduğunuz şeyler hakkında aranızda ben hüküm vereceğim.\""},{"n":56,"t":"\"Küfre sapanlar var ya, işte onlara dünyada ve âhirette şiddetle azap edeceğim. Hiçbir yardımcıları olmayacaktır onların.\""},{"n":57,"t":"İman edip hayra ve barışa yönelik işler yapanlara gelince, Allah onlara ödüllerini tam olarak verecektir. Allah zalimleri sevmez."},{"n":58,"t":"İşte bu sana ayetlerden ve hikmetlerle dolu Zikir'den okuduğumuzdur."},{"n":59,"t":"Allah katında İsa'nın durumu, Âdem'in durumu gibidir. Onu topraktan yarattı, sonra ona \"Ol!\" dedi. Artık o, olur."},{"n":60,"t":"Hak, Rabbindendir. O halde, kuşku duyanlardan olma."},{"n":61,"t":"Sana ilim geldikten sonra, artık kim seninle onun hakkında tartışmaya kalkışırsa de ki: \"Gelin, çocuklarımızı ve çocuklarınızı, kadınlarımızı ve kadınlarınızı, kendimizi ve kendinizi çağıralım; sonra da gönülden dua edelim de Allah'ın lanetini yalancıların üzerine kılalım.\""},{"n":62,"t":"İşte, gerçek kıssanın ta kendisi budur. Allah'tan başka ilah yoktur. Ve Allah, elbette Azîz'dir, elbette Hakîm'dir."},{"n":63,"t":"Eğer yüz çevirirlerse, hiç kuşkusuz Allah, bozguncuları çok iyi bilmektedir."},{"n":64,"t":"De ki: \"Ey Ehlikitap! Sizin ve bizim aramızda aynı olan şu söze gelin: \"Allah'tan başkasına kulluk etmeyelim, O'na hiçbir şeyi ortak koşmayalım. Allah'ın berisinden birbirimizi rabler edinmeyelim!\" Eğer yüz çevirirlerse şöyle söyle: \"Tanık olun, biz müslümanlarız/Allah'a teslim olanlarız!\""},{"n":65,"t":"Ey Ehlikitap! İbrahim hakkında neden çekişiyorsunuz? Tevrat da İncil de ondan sonra indirildi. Hâlâ aklınızı işletmeyecek misiniz?"},{"n":66,"t":"İşte siz böyle insanlarsınız! Hakkında biraz bilginiz olan şeyde çekişmeye girdiniz. Peki, hakkında hiçbir bilginiz olmayan şeyde neden tartışmaya giriyorsunuz? Allah bilir ama siz bilmezsiniz."},{"n":67,"t":"İbrahim ne bir Yahudi idi ne de bir Hıristiyan. O, sadece Hanîf bir müslümandı/Allah'a teslim olandı. O müşriklerden değildi."},{"n":68,"t":"Şu bir gerçek ki, insanların İbrahim'e gönülce en yakın olanları, elbette ona uyanlar, bu peygamber, bir de iman sahipleridir. Allah, müminlerin Velî'sidir."},{"n":69,"t":"Kitap ehlinden bir zümre, sizi bir saptırabilseler diye arzu ettiler. Oysaki onlar, kendilerinden başkasını saptırmazlar. Ama bunu fark etmiyorlar."},{"n":70,"t":"Ey Ehlikitap! Gerçeğe tanık olup durduğunuz halde, Allah'ın ayetlerini neden inkâr ediyorsunuz/Allah'ın ayetlerine neden nankörlük ediyorsunuz?!"},{"n":71,"t":"Ey Ehlikitap! Neden hakkı bâtılla kirletiyorsunuz ve bilip durduğunuz halde gerçeği gizliyorsunuz?"},{"n":72,"t":"Ehlikitap'tan bir zümre şöyle dedi: \"Şu iman edenlere indirilene günün başlangıcında inanın, günün sonunda karşı çıkın. Belki bu sayede geriye/eskiye dönerler."},{"n":73,"t":"Dininize uyandan başkasına inanmayın.\" Söyle onlara: \"Hidâyet, Allah'ın kılavuzlamasıdır. Size verilenin benzeri bir başkasına veriliyor yahut Rabbinizin katında tartışarak size üstün gelecekler diye mi bütün bunlar?\" De ki: \"Lütuf Allah'ın elindedir; onu dilediğine verir. Allah Vâsî'dir, varlığı sürekli genişletir; Alîm'dir, her şeyi en iyi şekilde bilir.\""},{"n":74,"t":"Rahmetini dilediğine özgüler. Allah, büyük lütfun sahibidir."},{"n":75,"t":"Ehlikitap'tan öylesi vardır ki, ona yüklerle emanet teslim etsen onu sana iade eder. Onlardan öylesi de vardır ki, ona bir dînar emanet etsen, tepesine çökmedikçe onu sana geri vermez. Bunun sebebi şudur: Onlar: \"Ümmîlerin, bizim aleyhimize yol bulmaları mümkün değildir.\" demişlerdir. Onlar, bilip durdukları halde, Allah hakkında yalan söylerler."},{"n":76,"t":"İş öyle değil! Kim ahdine vefa eder, takvaya sarılırsa hiç kuşkusuz, Allah takvaya sarılanları sever."},{"n":77,"t":"Allah'a verdikleri sözü ve yeminlerini basit bir bedel karşılığı satanlar var ya, işte onlar için âhirette hiçbir nasip yoktur. Allah onlarla konuşmayacaktır, kıyamet günü onlara bakmayacaktır, onları temizleyip arıtmayacaktır. Onlar için korkunç bir azap vardır."},{"n":78,"t":"Onlardan bir zümre vardır, aslında Kitap'tan olmayan birşeyi siz Kitap'tan sanasınız diye, dillerini Kitap'la eğip bükerler. O, Allah katında olmadığı halde, \"Bu, Allah katındandır.\" derler. Bilip durdukları halde, Allah hakkında yalan söylerler."},{"n":79,"t":"Hiçbir insana yakışmaz ki, Allah kendisine kitap, hüküm-hikmet ve peygamberlik versin de sonra o, insanlara \"Allah'ı bırakıp bana kullar olun\" desin. O ancak şöyle der: \"Öğrettiğiniz şu Kitap'a ve okuyup araştırdıklarınıza dayanarak benliklerini Allah'a adamış kullar/Rabbânîler olun!\""},{"n":80,"t":"Ve size melekleri ve peygamberleri rabler edinmenizi de emretmez. Siz, müslümanlar haline geldikten sonra inkârı mı emreder size?"},{"n":81,"t":"Ve unutma ki Allah, peygamberlerden mîsaklarını almış, şöyle demişti: \"Size Kitap'tan ve hikmetten nasip verdim. Sonra size elinizdekini doğrulayıcı bir resul geldiğinde, ona mutlaka inanacak ve ona muhakkak yardım edeceksiniz. Kabul ettiniz ve ağır yükümü üzerinize aldınız mı?\". \"Kabul ettik.\" dediler. \"O halde tanık olun, sizinle beraber ben de tanıklardanım.\" dedi."},{"n":82,"t":"Tüm bunlardan sonra yüz çevirenler, sapıkların ta kendileridir."},{"n":83,"t":"Hâlâ Allah'ın dininden gayrısını mı arıyorlar? Oysaki, göklerdeki şuurlulur da, yerdekiler de ister istemez O'na teslim olmuşlardır ve yalnız O'na döndürüleceklerdir."},{"n":84,"t":"De ki: \"Allah'a, bize indirilene, İbrahim'e, İsmail'e, İshak'a, Yakub'a, torunlarına indirilmiş olana, Mûsa'ya, İsa'ya ve diğer nebilere Rablerinden verilmiş bulunana inandık. Onlardan hiçbirini ötekinden ayırmayız. Biz O'na teslim olanlarız.\""},{"n":85,"t":"Kim İslam'dan/Allah'a teslim olmaktan gayrı bir din ararsa artık o, ondan asla kabul edilmeyecektir. Ve o, âhirette hüsrana düşenlerdendir."},{"n":86,"t":"İmanlarından, resulün hak olduğuna tanıklık ettikten ve kendilerine ayan-beyan deliller geldikten sonra küfre sapmış bir topluluğa Allah nasıl kılavuzluk eder? Allah, zalimler topluluğuna yol göstermez."},{"n":87,"t":"İşte böylelerinin cezası: Allah'ın, meleklerin ve tüm insanların laneti üzerlerine!"},{"n":88,"t":"O lanet içinde sürekli kalacaklardır. Ne azap hafifletilecektir onlardan ne de yüzlerine bakılacaktır onların."},{"n":89,"t":"Ondan sonra tövbe edip hallerini düzeltenler müstesna. Hiç şüphesiz, Allah, çok affedici, çok merhametlidir."},{"n":90,"t":"İmanlarından sonra küfre sapmış, sonra da küfürde daha da azıtmış olanların tövbeleri asla kabul edilmeyecektir. Onlar, sapıkların ta kendileridir."},{"n":91,"t":"Gerçeği örtüp de küfre sapmış olarak ölenlere gelince, onların her biri kendini kurtarmak için dünya dolusu altın verse de asla kabul edilmeyecektir. Korkunç bir azap vardır onlar için. Hiçbir yardımcıları olmayacaktır."},{"n":92,"t":"Sevdiğiniz şeylerden infak etmedikçe hayırda erginliğe/dürüstlüğe asla ulaşamazsınız. İnfak etmekte olduğunuz her şeyi, Allah çok iyi bilmektedir."},{"n":93,"t":"Tevrat indirilmeden önce İsrail'in kendi nefsine haram kıldığı şeyler dışında tüm yiyecekler İsrailoğullarına helaldi. Onlara de ki: \"Tevrat'ı ortaya getirin; doğru sözlü iseniz onu okuyun.\""},{"n":94,"t":"Artık bundan sonra kim yalan düzüp Allah'a iftira ederse böyleleri zalimlerin ta kendileridir."},{"n":95,"t":"De ki: \"Allah, doğrusunu söylemiştir/vaadinde sadıktır. Hadi artık hanîf olarak İbrahim'in milletine uyun! Müşriklerden değildi o.\""},{"n":96,"t":"Şu bir gerçek ki, âlemlere bir bereket kaynağı ve yol gösterici halinde insanlar için kurulan ilk ev Mekke'dekidir."},{"n":97,"t":"Açık-seçik deliller, İbrahim'in makamı vardır orada. Oraya giren, güvene ermiş olur. Yoluna gücü yetenin o evi ziyaret etmesi, insanlar üzerinde Allah'ın bir hakkıdır. Kim nankörlük ederse hiç kuşkusuz, Allah bütün âlemlere muhtaç olmayacak bir Ganî'dir."},{"n":98,"t":"De ki: \"Ey Ehlikitap! Allah, yaptıklarınıza tanıklık ederken, Allah'ın ayetlerini neden inkâr ediyorsunuz?\""},{"n":99,"t":"Şunu da söyle: \"Ey Ehlikitap! Neden iman edenleri Allah yolundan alıkoyuyorsunuz? Gözünüzle gördüğünüz halde, Allah yolunu neden çarpıtmak istiyorsunuz? Allah, yaptıklarınızdan habersiz değildir.\""},{"n":100,"t":"Ey iman edenler! Kendilerine kitap verilenlerden bir zümreye boyun eğerseniz sizi, imanınızdan sonra kâfirler haline getirirler."},{"n":101,"t":"Allah'ın ayetleri size okunuyor, Resulü de aranızda; peki, nasıl küfre sapıyorsunuz? Kim Allah'a sarılırsa dosdoğru yola iletilmiştir o..."},{"n":102,"t":"Ey iman edenler! Allah'tan, kendisinden korkmaya yaraşır biçimde korkun. Müslümanlar olmanın/Allah'a teslim olmanın dışında bir hal üzere sakın can vermeyin."},{"n":103,"t":"Hep birlikte Allah'ın ipine yapışın, fırkalara bölünüp parçalanmayın; Allah'ın üzerinizdeki nimetini hatırlayın. Birbirinizin düşmanı idiniz, Allah kalplerinizi uzlaştırıp kaynaştırdı da O'nun nimeti sayesinde kardeşler haline geldiniz. Ateşten bir çukurun kenarında idiniz; sizi oradan kurtardı. Allah size ayetlerini bu şekilde açıklıyor ki, doğruya ve güzele yol bulasınız."},{"n":104,"t":"İçinizden hayra çağıran, doğruluk ve güzelliği belirlenene özendiren, kötülük ve çirkinlik belirlenenden sakındıran bir topluluk olsun. Kurtuluş ve zafere erenler işte onlardır."},{"n":105,"t":"Kendilerine açık-seçik kanıtlar geldikten sonra, çekişmeye girip fırkalar halinde parçalananlar gibi olmayın. Böyle olanlar için çok büyük bir azap vardır."},{"n":106,"t":"Gün gelir bazı yüzler ağarır, bazı yüzler kararır. Yüzleri kararanlara şöyle denir: \"İmanınızdan sonra küfre mi düştünüz? Hadi, saptığınız küfür yüzünden tadın azabı!\""},{"n":107,"t":"Yüzleri ağaranlara gelince, onlar, Allah'ın rahmeti içindedirler. Sürekli ondadır onlar."},{"n":108,"t":"Bunlar sana Allah'ın ayetleri. Hak olarak okuyoruz sana onları. Allah, âlemlere zulüm istemiyor."},{"n":109,"t":"Göklerde ne var, yerde ne varsa hepsi Allah'ındır. İş ve oluşlar Allah'a döndürülür."},{"n":110,"t":"Siz, insanlar için çıkarılmış en hayırlı ümmetsiniz: İyilik ve güzelliği belirlenmiş olana özendirirsiniz, kötülük ve çirkinliği belirlenmiş olandan sakındırırsınız, Allah'a iman edersiniz. Ehlikitap da iman etseydi, kendileri için, elbette hayırlı olurdu. İçlerinde müminler vardır ama onların çoğu sapıkların ta kendileridir."},{"n":111,"t":"Biraz eziyet dışında size asla zarar veremezler. Sizinle savaşırlarsa size sırtlarını dönerler. Sonra onlara yardım da edilmez."},{"n":112,"t":"Allah'tan bir ipe ve insanlardan bir ipe tutunmaları dışında, nerede bulunsalar üzerlerine zillet damgası vurulur. Allah'ın hışmına uğramışlardır. Üzerlerine miskinlik damgası vurulmuştur. Bu böyledir. Çünkü onlar, Allah'ın ayetlerine küfrediyor, haksız yere peygamberleri öldürüyorlardı; isyan etmişlerdi, zulüm ve azgınlık sergiliyorlardı."},{"n":113,"t":"Ama hepsi bir değildir. Ehlikitap içinden Allah için baş kaldıran/Allah huzurunda el bağlayan/hak ve adaleti ayakta tutan/kalkınıp yükselen bir zümre de vardır; gece saatlerinde secdelere kapanmış olarak Allah'ın ayetlerini okurlar."},{"n":114,"t":"Allah'a ve âhiret gününe inanırlar, iyilik ve güzelliği belirlenmiş olana özendirirler, kötülük ve çirkinliği belirlenmiş olandan sakındırırlar. Hayır işlerde yarışırcasına koşarlar. İşte bunlar hayra ve barışa yönelik hizmet üretenlerdendir."},{"n":115,"t":"Yapmakta oldukları/yapacakları hiçbir hayır, nankörlükle karşılanmayacak/karşılıksız bırakılmayacaktır. Allah, takva sahiplerini çok iyi bilmektedir."},{"n":116,"t":"Küfre sapanlara gelince, onların malları da çocukları da kendilerine Allah'a karşı bir yarar asla sağlamayacaktır. Ateşin dostlarıdır onlar. Sürekli kalacaklardır onun içinde."},{"n":117,"t":"Bu dünya hayatında harcamakta olduklarının durumu, bir rüzgâr örneğine benzer: Onda kavurucu bir soğuk vardır. Öz benliklerine zulmetmiş bir toplululuğun ekinine değmiş de onu mahvetmiştir. Allah onlara zulmetmedi, onlar kendilerine zulmediyorlardı."},{"n":118,"t":"Ey iman sahipleri! Kendi dışınızdakilerden/seviyenizin altındakilerden bir kimseyi sırdaş edinmeyin. Sizi sarpa sardırıp perişan etmekten çekinmezler. Size sıkıntı verecek şeyi pek severler. Ağızlarından nefret ve öfke taşmaktadır. Göğüslerinin saklamakta olduğu ise daha büyüktür. Eğer aklınızı işletirseniz Allah size ayetlerini açık-seçik göstermiştir."},{"n":119,"t":"Siz öyle kişilersiniz ki, onlar sizi sevmedikleri halde siz onları seversiniz. Ve Kitap'ın tümüne inanırsınız. Onlar ise sizinle karşılaştıklarında \"İnandık!\" derler; başbaşa kaldıklarında ise size öfkelerinden parmak uçlarını ısırırlar. De ki onlara: \"Öfkenizle geberin!\" Allah, göğüslerin içindekini çok iyi bilmektedir."},{"n":120,"t":"Size bir iyilik dokunsa bu onları rahatsız eder. Size bir kötülük dokunsa bununla sevinir, ferahlarlar. Eğer sabreder, sakınır/korunursanız onların tuzakları size hiçbir şekilde zarar veremez. Allah Muhît'tir, yapmakta olduklarını çepeçevre kuşatmıştır."},{"n":121,"t":"Hani, sen ailenden erkenden ayrılmıştın da müminleri savaş için tutulması gereken noktalara yerleştiriyordun. Allah her şeyi çok iyi duyar, çok iyi bilir."},{"n":122,"t":"O zaman, içinizden iki takım çözülmeye, bozulmaya yüz tutmuştu. Oysaki Allah, onların dostu/yardımcısı idi. Müminler yalnız Allah'a güvenip dayansınlar!"},{"n":123,"t":"Yemin olsun ki, ezik-boynu bükük olduğunuz bir sırada Allah size Bedir'de de yardım etmişti. O halde Allah'tan korkun ki, şükredebilesiniz."},{"n":124,"t":"O sırada sen, müminlere şöyle diyordun: \"Rabbinizin, indirilmiş üçbin melekle destek vermesi, size yetmiyor mu?\""},{"n":125,"t":"İş, sanıldığı gibi değildir. Onlar, hemen şu anda üstünüze gelseler bile, eğer siz sabreder ve korunursanız, Rabbiniz sizi, üzerlerine nişan vurulmuş beş bin melekle destekler."},{"n":126,"t":"Allah bunu size bir müjde olması ve onunla kalplerinizi yatıştırması dışında hiçbir şey yapmamıştır. Yardım, Azîz ve Hakîm olan Allah katından başka hiçbir yerden gelmez."},{"n":127,"t":"Allah bunu yaptı ki, küfre sapanlardan bir kısmını bölüp ayırsın veya onları zelîl etsin de yıkık ve ürkek bir halde dönüp gitsinler."},{"n":128,"t":"İş ve hüküm konusunda sana düşen bir şey yoktur. Allah ya tövbelerini kabul ederek onları bağışlar yahut da zalim oldukları için onlara azap eder."},{"n":129,"t":"Göklerde ne var, yerde ne varsa Allah'ındır. Dilediğini/dileyeni affeder; dilediğine/dileyene azap eder. Allah çok affedici, çok merhametlidir."},{"n":130,"t":"Ey iman sahipleri! Ribayı öyle kat kat katlayarak yemeyin. Allah'tan korkun ki kurtuluşa erebilesiniz."},{"n":131,"t":"Kâfirler için hazırlanmış ateşten korkun."},{"n":132,"t":"Allah'a ve resule itaat edin ki, merhamet görebilesiniz."},{"n":133,"t":"Rabbinizden bir bağışlanmaya ve eni göklerle yer kadar olan cennete doğru yarışır gibi koşuşun. O, takva sahipleri için hazırlanmıştır."},{"n":134,"t":"Onlar bollukta ve darlıkta infak ederler. Öfkelerini yutanlardır onlar, insanları affedenlerdir. Allah, güzel düşünüp güzel davrananları sever."},{"n":135,"t":"Onlar, çirkin bir iş yaptıklarında yahut öz benliklerine zulmettiklerinde, Allah'ı hatırlar da günahları için af dilerler. Günahları Allah'tan başka kim affeder ki? Ve onlar yaptıklarında bile bile ısrar etmezler."},{"n":136,"t":"İşte bunların ödülleri Rablerinden bir bağışlanma ve altlarından ırmaklar akan cennetler olacaktır. Sürekli kalacaklardır orada. İş yapıp değer üretenlerin ücreti ne güzeldir!"},{"n":137,"t":"Sizden önce de yollar-yöntemler gelip geçmiştir. O halde yeryüzünde dolaşın da yalanlayanların sonu nice olmuştur görün."},{"n":138,"t":"Bu, insanlara bir açıklama, korunup sakınanlara da bir öğüt ve kılavuzdur."},{"n":139,"t":"Gevşemeyin, tasalanmayın. Eğer inanıyorsanız üstün olan sizsiniz."},{"n":140,"t":"Size bir yara değiyorsa, o topluma da benzeri bir yara mutlaka değmiştir. Bak işte günler! Biz onları insanlar arasında dolandırır dururuz. Allah bu sayede iman edenleri bilecek, sizden tanıklar/şehitler edinecektir. Allah zulme sapanları sevmez."},{"n":141,"t":"Tüm bunlar, Allah iman edenleri iyice seçip arındırsın ve küfre sapanları mahvetsin diyedir."},{"n":142,"t":"Yoksa siz, Allah içinizden uğraşıp didinenleri seçmeden, sabredenleri seçmeden cennete gireceğinizi mi sandınız?"},{"n":143,"t":"Yemin olsun ki siz, onunla karşılaşmadan önce ölümü arzuluyordunuz. İşte gördünüz onu ve bakıp duruyorsunuz."},{"n":144,"t":"Muhammed bir resulden başkası değildir. Ondan önce de resuller gelip geçmiştir. Şimdi o ölse yahut öldürülse ökçeleriniz üzerine gerisin geri mi döneceksiniz! İki ökçesi üzerine geri dönen, Allah'a hiçbir şekilde zarar veremez. Allah, şükredenleri ödüllendirecektir."},{"n":145,"t":"Allah'ın izni olmadıkça hiçbir kişi ölmez. Vakti belirlenmiş bir yazıdır o. Dünya çıkarını gözetene ondan veririz; âhiret yararını gözetene de ondan veririz. Şükredenleri ödüllendireceğiz biz."},{"n":146,"t":"Nice peygamber, beraberinde kendisini Rabb'e adayan birçok kişi bulunduğu halde savaşmıştır. Onlar, Allah yolunda kendilerine gelip çatan zorluklar yüzünden gevşememiş, zayıflık göstermemiş, susup pusmamışlardır. Allah sabredenleri sever."},{"n":147,"t":"Sözleri yalnız şu olmuştur: \"Ey Rabbimiz! Bağışla bizim günahlarımızı, affet işlerimizdeki taşkınlığımızı, sağlam bastır ayaklarımızı ve yardım et bize küfre sapan topluma karşı!\""},{"n":148,"t":"Allah da onlara, hem dünya nimetini verdi hem de âhiret sevabının en güzelini. Allah, güzel düşünüp güzellik sergileyenleri sever."},{"n":149,"t":"Ey iman edenler! Eğer küfre sapanlara boyun eğerseniz sizi ökçeleriniz üstüne yüz geri çevirirler de hüsrana uğrayanlar haline gelirsiniz."},{"n":150,"t":"Hayır, hayır! Sizin Mevlâ'nız Allah'tır. Ve O, yardımcıların en hayırlısıdır."},{"n":151,"t":"Allah'ın, kendileri hakkında hiçbir delil indirmediği şeyleri Allah'a ortak koştukları için, küfre sapanların kalplerine korku salacağız. Barınakları ateştir onların. Ne kötüdür o zalimlerin varacakları yer!"},{"n":152,"t":"Yemin olsun ki, siz onları Allah'ın izniyle öldürmekteyken, Allah size vaadini doğrulamıştı. Nihayet, siz korkuya kapıldınız, yapılacak iş hususunda çekiştiniz. Ve Allah, sevdiğiniz şeyi size gösterdikten sonra isyan ettiniz. İçinizden bir kısmı dünyayı istiyordu, bir kısmınız ise âhireti istiyordu. Sonra sizi imtihan etmek için onlardan uzaklaştırdı. Yemin olsun, sizi affetmişti. Allah, müminlere karşı lütuf sahibidir."},{"n":153,"t":"Siz şaşkınlıkla sağa-sola kaçıyor, hiç kimseye dönüp bakmıyordunuz. Resul ise arkanızdan sizi çağırıyordu. Böylece Allah size keder üstüne keder verdi ki, elinizden uçup gidene de size isabet edene de üzülmeyesiniz. Allah, yapmakta olduklarınızdan haberdardır."},{"n":154,"t":"Sonra bu kederin ardından üzerinize, içinizden bir grubu sarıp kuşatan, güven verici bir uyku indirdi. Bir grup da -gerçekten onlar kendi canlarının derdine düşmüştü- Allah hakkında gerçek dışı sanılara, cahiliye düşüncelerine kapılıyordu. \"Şu işten bize bir şey var mı?\" diyorlardı. De ki: \"Emir/iş ve oluş tümüyle Allah'ındır.\" Öz benliklerinde, sana açıklamaz oldukları şeyler saklıyorlar. Diyorlar ki: \"Bu işten bizim lehimize bir şey olsaydı, şuracıkta öldürülmezdik.\" Söyle onlara: \"Evlerinizde kalsaydınız bile, üzerlerine ölüm yazılmış olanlar, uzanacakları yerleri muhakkak boylayacaklardı.\" Bu, Allah, göğüslerinizdekini denesin, kalplerinizdekini ortaya çıkarsın diyedir. Allah, göğüslerin özünü çok iyi bilir."},{"n":155,"t":"İki topluluğun karşılaştığı gün geri dönüp gidenleriniz var ya, yaptıkları bazı işler yüzünden şeytan onların ayağını kaydırmak istemişti. Yemin olsun, Allah onları yine de affetti. Allah Gafûr'dur, Halîm'dir."},{"n":156,"t":"Ey iman sahipleri! Yeryüzünde dolaşan yahut gazaya çıkan kardeşleri için şöyle diyen inkârcılar gibi olmayın: \"Yanımızda olsaydılar ölmezlerdi, öldürülmezlerdi.\" Allah bunu onların kalplerinde bir özlem yapacaktır. Allah, diriltir de öldürür de. Allah, yapıp ettiklerinizi en iyi şekilde görmektedir."},{"n":157,"t":"Allah yolunda öldürülür yahut ölürseniz, Allah'tan bir bağışlanma ve bir merhamet/bir sevgi onların derleyip topladıklarından çok daha iyidir."},{"n":158,"t":"Ölür yahut öldürülürseniz elbette ki Allah'a götürüleceksiniz."},{"n":159,"t":"Allah'tan bir merhamet/bir sevgi sayesindedir ki, sen onlara yumuşak davrandın. Eğer kaba-saba, katı yürekli olsaydın senin çevrenden kesinlikle dağılır giderlerdi. O halde bağışla onları, af dile onlar için; iş ve yönetim konusunda da onlarla şûraya git. Bir kez azmettin mi de artık Allah'a güvenip dayan! Allah, tevekkül edenleri sever."},{"n":160,"t":"Allah size yardım ederse hiç kimse size galip gelemez. Eğer sizi yüzüstü bırakırsa O'ndan başka size kim yardım edebilir? Artık müminler yalnız Allah'a güvenip dayansınlar."},{"n":161,"t":"Bir peygamberin emanete hıyanet etmesi/kamu malından aşırması olacak şey değildir. Her kim hıyanet eder, kamu malından bir şey aşırırsa, aşırdığını kıyamet günü yüklenip getirir. Sonra her benliğe; kazandığı tam olarak ödenir. Hiç birine zulmedilmez."},{"n":162,"t":"Allah'ın hoşnutluğunu izleyen kişi, Allah'ın gazabına uğrayan ve barınağı cehennem olan kişiyle aynı mıdır? Ne kötü varış yeridir o!"},{"n":163,"t":"Onlar, Allah katında derece derecedirler. Allah, yapmakta olduklarını iyice görmektedir."},{"n":164,"t":"Yemin olsun ki, Allah müminlere lütufta bulunup onları minnettar bırakmıştır: Kendi içlerinde onlara öyle bir resul gönderdi ki, onlara Allah'ın ayetlerini okuyor, onları temizleyip arındırıyor, onlara Kitap'ı ve hikmeti öğretiyor. Oysaki onlar, bundan önce açık bir sapıklığın tam içindeydiler."},{"n":165,"t":"Size, başkalarına iki katını dokundurduğumuz bir musibet dokununca: \"Bu da nereden!\" mi dediniz? De ki: \"O, sizin öz benliklerinizdendir.\" Allah, her şeye Kadîr'dir."},{"n":166,"t":"İki topluluğun karşılaştığı gün sizin başınıza gelen, Allah'ın izniyledir ve Allah, müminleri bilsin diyedir."},{"n":167,"t":"Ve ikiyüzlülük yapan münafıkları bilsin diye. Onlara, \"Hadi gelin, Allah yolunda çarpışın yahut savunma yapın!\" dendiğinde: \"Savaştan haberimiz olsaydı sizi elbette izlerdik.\" dediler. O gün onlar, imandan çok küfre yakın idiler. Kalplerinde olmayanı ağızlarıyla söylüyorlar. Allah, onların gizlemekte oldukları şeyi çok iyi bilmektedir."},{"n":168,"t":"Yerlerinde oturup da kardeşleri için, \"Bizi dinlemiş olsalardı öldürülmeyeceklerdi.\" diyenlere şöyle söyle: \"Eğer doğru sözlüler iseniz, kendi benliklerinizden uzaklaştırın ölümü!\""},{"n":169,"t":"Allah yolunda öldürülmüş olanları ölüler sanma sakın. Hayır! Onlar diridirler. Rablerinin katında rızıklandırılıyorlar."},{"n":170,"t":"Allah'ın, lütfundan kendilerine verdiğiyle sevinçlidirler. Ve arkada kalıp kendilerine katılmamış olanlara şunu müjdeliyorlar: Onlar için korku yoktur; tasalanmayacaklardır onlar."},{"n":171,"t":"Allah'tan bir nimeti, bir lütfu ve Allah'ın müminlerin ödülünü vermezlik etmeyeceğini de müjdelerler."},{"n":172,"t":"O müminler ki, kendilerine yara isabet ettikten sonra bile Allah'ın ve resulün çağrısına cevap verdiler. Onlar içinden, güzel işler yapıp takvaya sarılanlara büyük bir ödül vardır."},{"n":173,"t":"O müminler ki, insanlar kendilerine, \"Halk size karşı bir araya gelmiş, korkun onlardan!\" dediklerinde, bu onların imanını artırdı da şöyle söylediler: \"Allah bize yeter. Ne güzel Vekîl'dir O!\""},{"n":174,"t":"Böyle olduğu içindir ki, Allah'tan bir nimet ve lütufla geri döndüler, hiçbir kötülük dokunmamıştı onlara. Allah'ın rızasını izlediler. Allah çok büyük bir lütfun sahibidir."},{"n":175,"t":"İşte size şeytan. O yalnız kendi dostlarını korkutur. Eğer inananlarsanız onlardan korkmayın, benden korkun."},{"n":176,"t":"Küfür içinde koşuşanlar sana üzüntü vermesin. Şu bir gerçek ki, onlar Allah'a hiçbir şekilde zarar veremezler. Allah, onlara âhirette bir nasip vermemeyi istemektedir. Onlar için çok büyük bir azap öngörülmüştür."},{"n":177,"t":"İman karşılığında küfrü satın alanlar, Allah'a herhangi bir biçimde asla zarar veremezler. Korkunç bir azap vardır onlar için."},{"n":178,"t":"Küfre sapanlar, onlara süre tanımamızın kendileri için hayırlı olduğunu asla düşünmesinler. Onlara, biraz daha günah işlesinler diye süre veriyoruz. Yere geçirecek bir azap var onlar için."},{"n":179,"t":"Allah, müminleri şu üzerinde bulunduğunuz halde bırakmayacaktır. Sonuçta pisi temizden ayıracaktır. Allah sizi gaybı bilir duruma da getirmeyecektir. Şu var ki Allah, resullerinden dilediğini seçer. O halde Allah'a ve resullerine inanın. Eğer inanır, korunursanız sizin için büyük bir ödül vardır."},{"n":180,"t":"Allah'ın, lütfundan kendilerine verdiği şeyde cimrilik edenler, bunun kendileri için hayırlı olduğunu sanmasınlar. Tam aksine bu onlar için bir şerdir. O cimrilik konusu yaptıkları şey, kıyamet günü bir tasma gibi boyunlarına dolandırılacaktır. Göklerin ve yerin mirası Allah'ındır. Allah, yapmakta olduklarınızdan haberdardır."},{"n":181,"t":"Yemin olsun ki, Allah, \"Allah yoksuldur, bizler zenginleriz!\" diyenlerin sözünü işitti. Dediklerini de yazacağız, haksız yere peygamberleri öldürmelerini de. Ve şöyle diyeceğiz: \"Tadın, yakıp pişiren azabı!\""},{"n":182,"t":"Bu, kendi, ellerinizin üretip önden gönderdiği yüzündendir. Allah, kullara asla zulmedici değildir."},{"n":183,"t":"Onlar şöyle demişlerdi: \"Allah bize ant verdi, kendisi bize ateşin yiyeceği bir kurban getirmedikçe hiçbir resule inanmayacağız.\" Söyle onlara: \"Size benden önce o dediğinizle birlikte açık deliller getiren resuller gelmişti. Peki, madem doğru sözlülerdiniz neden onları katlettiniz?\""},{"n":184,"t":"Seni yalanladılarsa, senden önce de resuller yalanlandı. Açık-seçik deliller, kutsal sayfalar ve aydınlatıcı kitabı getirmişlerdi onlar."},{"n":185,"t":"Her benlik ölümü tadacaktır. Hak ettiğiniz karşılıklar size, kıyamet günü, eksiksiz bir biçimde mutlaka verilecektir. Ateşten uzaklaştırılıp cennete sokulan kesinlikle kurtulmuş olacaktır. İğreti-sefil hayat aldatıcı bir yararlanmadan başka şey değildir."},{"n":186,"t":"Yemin olsun ki, mallarınızda da canlarınızda da imtihan edileceksiniz. Ve yemin olsun ki, sizden önce kendilerine kitap verilenlerden de şirke batanlardan da incitici çok şey dinleyeceksiniz. Sabreder, sakınıp korunursanız işte bu, iş ve oluşların en zorlularındandır."},{"n":187,"t":"Allah, kendilerine kitap verilenlerden şu yolda mîsak almıştı: \"Onu insanlara mutlaka açık-seçik bildireceksiniz, onu saklamayacaksınız.\" Ama onlar Kitap'ı sırtlarının gerisine attılar, basit bir ücret karşılığı onu sattılar. Ne kötü şey satın alıyorlar!"},{"n":188,"t":"O ettikleriyle zevklenen, yapmadıkları şeylerle övünmeyi seven kişileri bir şey sanma. Artık, onları azaptan kurtulmuş da sanma. Korkunç bir azap vardır onlar için."},{"n":189,"t":"Göklerin de yerin de mülkü/yönetimi Allah'ındır. Allah Kadîr'dir, her şeye gücü yeter."},{"n":190,"t":"Şu bir gerçek ki, göklerin ve yerin yaratılışında, geceyle gündüzün birbiri ardınca gelişinde, akıllarını/gönüllerini işletenler için çok ibretler vardır."},{"n":191,"t":"ONlar o kişilerdir ki, ayakta, otururken, yan yatarken hep Allah'ı zikrederler; göklerin ve yerin yaratılışı hakkında derin derin düşünürler: \"Ey Rabbimiz! Sen bunu boşuna yaratmadın. Şanın yücedir senin! Ateş azabından koru bizi!\""},{"n":192,"t":"\"Ey Rabbimiz! Sen birini ateşe soktun mu onu tam rezil etmişsindir. Zalimlerin, yardımcıları olmayacaktır.\""},{"n":193,"t":"\"Ey Rabbimiz! Bir çağırıcının, 'Rabbinize inanın!' diye imana çağırdığını işittik ve iman ettik. Ey Rabbimiz! Günahlarımızı bağışla bizim. Kötülüklerimizin üstünü ört ve bize iyilerle birlikte ölmek nasip et.\""},{"n":194,"t":"\"Ey Rabbimiz! Resullerin aracılığıyla bize vaat etmiş olduğunu da bize ver; kıyamet günü bizi rezil etme! Sen, vaadine asla ters düşmezsin.\""},{"n":195,"t":"Rableri onlara cevap verdi: \"Ben sizden, erkek-kadın hiçbir çalışanın ürettiğini boşa çıkarmayacağım. Hep birbirinizdensiniz. Göç edenler, yurtlarından çıkarılanlar, yolumda işkenceye uğratılanlar, çarpışıp da öldürülenler var ya, onların kötülüklerini yemin olsun örteceğim. Ve yemin olsun ki onları, Allah katından bir karşılık olarak, altlarından ırmaklar akan cennetlere koyacağım.\" Allah katındandır karşılıkların en güzeli."},{"n":196,"t":"Küfre sapanların öyle belde belde dolaşmaları seni sakın aldatmasın."},{"n":197,"t":"Azıcık bir nimetlenmedir o. Sonra onların varacağı yer cehennem olacaktır. Ne kötü yataktır o!"},{"n":198,"t":"Ama Rablerinden sakınanlar için altlarından ırmaklar akan cennetler var. Allah katından bir konukseverlikle sürekli kalıcıdırlar orada. Allah katındaki ödüller iyiler için daha hayırlıdır."},{"n":199,"t":"Ehlikitap'tan öyleleri var ki, Allah'a, size indirilene ve kendilerine indirilene inanırlar. Allah karşısında ürperirler; Allah'ın ayetlerini basit bir ücret karşılığı satmazlar. İşte bunlar için Rableri katında kendilerine özgü ödüller vardır. Allah, hesabı, çabucak görüverir."},{"n":200,"t":"Ey iman sahipleri! Sabredin, sabır yarışı yapın, nöbet tutarak savaşa hazırlıklı bulunun ve Allah'tan sakının ki, kurtuluşa erebilesiniz."}],[{"n":1,"t":"Ey insanlar! Sizi bir tek canlıdan yaratan, ondan eşini vücuda getiren ve o ikisinden birçok erkekler ve kadınlar üreten Rabbinize karşı gelmekten sakının. Adını anarak birbirinizden dilekler dilediğiniz Allah'tan korkun. Rahimlerin haklarına saygısızlıktan da sakının. Şu bir gerçek ki Allah, Rakîb'dir, sizin üzerinizde sürekli ve titiz bir gözetleyicidir."},{"n":2,"t":"Yetimlere mallarını verin. Temizi pise değişmeyin. Yetimlerin mallarını kendi mallarınıza katarak yemeyin. Bunu yapmak gerçekten büyük bir vebaldir."},{"n":3,"t":"Yetimler konusunda adaleti koruyamayacağınızdan korkarsanız, sizin için temiz kılınan kadınlardan ikişer, üçer, dörder nikâhlayın. Eğer bu durumda adaleti gözetemeyeceğinizden korkarsanız, bir tek kadınla yahut yeminlerinizin/sağ ellerinizin sahip olduklarıyla yetinin. İşte bu, haksızlığa sapmamanız için en uygun yoldur."},{"n":4,"t":"Kadınlara mehirlerini nazik ve cömert bir şekilde örf ve çevrenin kabullerine uygun olarak verin. Eğer ondan birazını kendileri kişisel istekleriyle size sunmuşlarsa artık onu içinize sine sine yiyin."},{"n":5,"t":"Allah'ın sizin için kıyam/geçim aracı yaptığı mallarınızı aklı ermezlere vermeyin; o malla onları besleyin, giydirin ve onlara tatlı, okşayıcı sözler söyleyin."},{"n":6,"t":"Yetimleri, nikâh çağına gelmelerine kadar gözetleyip deneyin. O zaman onlarda içinize sinecek bir olgunluk ve erginlik görürseniz, mallarını onlara geri verin. Büyüyecekler diye bu malları tez elden saçıp savurarak yemeyin. Zengin olan, iffetli davransın. Fakir olan ise örfün gerekli kıldığı oranda yesin. Mallarını kendilerine teslim ettiğiniz zaman yanlarında tanıklar bulundurun. Hesap sorucu olarak Allah yeter."},{"n":7,"t":"Ana-baba ve akrabanın geriye bıraktığından erkeklere bir pay vardır. Ana-baba ve akrabanın geriye bıraktığından -onun azından da çoğundan da- farz kılınmış bir nasip olarak kadınlara da bir pay vardır."},{"n":8,"t":"Mirasın paylaştırılmasında hısım-akraba, yetimler, yoksul ve çaresizler de hazır bulunurlarsa, ondan onları da rızıklandırın ve onlara güzel ve hoş bir söz de söyleyin."},{"n":9,"t":"Ürperip titresin o kimseler ki, kendi arkalarında zayıf ve çaresiz aile fertleri bırakmış olsalardı, onlar için korku ve endişe duyacaklardı. O halde, Allah'tan korksunlar ve haksızlığı önleyici sağlam bir söz söylesinler."},{"n":10,"t":"Şunda kuşkunuz olmasın ki, zulme başvurarak yetimlerin mallarını yiyenler karınlarına doldurmak üzere bir ateş yemekten başka bir şey yapmazlar. Ve onlar yakın bir zamanda, korkunç acılar veren bir azaba dalacaklardır."},{"n":11,"t":"Allah size çocuklarınızla ilgili olarak şunu öneriyor: Erkek için, iki dişinin payı kadar. İkiden fazla kadın iseler ölenin bıraktığının üçte ikisi onlarındır. Eğer çocuk sadece bir kadınsa, mirasın yarısı onundur. Ölenin çocuğu varsa, geriye bıraktığından ana-babanın her biri için altıda bir hisse olacaktır. Ölenin çocuğu yoksa ve kendisine ana-babası mirasçı olmuşsa bu durumda anasına üçte bir düşer. Eğer kardeşleri varsa, anasının payı, yapacağı vasiyetten ve borcundan arta kalanın altıda biridir. Babalarınız var, oğullarınız var. Siz bunlardan hangisinin yarar bakımından size daha yakın olduğunu bilemezsiniz. Allah'tan bir buyruğu önemseyin. Hiç kuşkusuz Allah herşeyi bilir, tüm hikmetlerin sahibidir."},{"n":12,"t":"Zevcelerinizin geriye bıraktığının yarısı sizindir, eğer onların çocuğu yoksa. Eğer onların çocuğu varsa, vasiyet ettikleri ve borçları ödendikten sonra geriye bıraktıklarının dörtte biri sizindir. Eğer sizin çocuğunuz yoksa bıraktığınızın dörtte biri zevcelerinizindir. Eğer sizin çocuğunuz varsa bu durumda, yaptığınız vasiyet ve borcunuz ödendikten sonra geriye kalanın sekizde biri zevcelerinizindir. Eğer miras bırakan erkek veya kadının ana-babası ve çocuğu yok da erkek kardeşi veya kız kardeşi varsa, bu kardeşlerden herbirine altıda bir düşer. Kardeşler bundan fazla ise bu takdirde onlar, yapılmış bulunan vasiyet ve borç ödendikten sonra üçte bire ortaktırlar. Kimseye zarar verilmemelidir. Allah'tan bir öneridir bu. Allah Alîm'dir, Halîm'dir."},{"n":13,"t":"İşte bunlar Allah'ın sınırlarıdır. Kim Allah'a ve onun resulüne itaat ederse Allah onu, altından nehirler akan cennetlere, orada sürekli kalıcılar halinde, sokar. İşte bu, en büyük başarıdır."},{"n":14,"t":"Kim de Allah'a ve onun resulüne isyan eder, Allah'ın sınırlarını da aşarsa, Allah onu, içinde sürekli kalıcı olarak ateşe sokar. Artık onun için yere batırıcı bir azap vardır."},{"n":15,"t":"Kadınlarınızdan eşcinsellik/sevicilik yapanlara karşı içinizden dört tanık getirin; eğer tanıklık ederlerse o kadınları, ölüm canlarını alıncaya ya da Allah kendileri için bir yol açıncaya kadar evlerde tutun."},{"n":16,"t":"Eşcinselliği içinizden iki erkek yaparsa onlara eziyet edin. Bu ikisi tövbe eder, durumlarını düzeltirlerse onlara eziyetten vazgeçin. Allah Tevvâb'dır, tövbeleri çok kabul eder; Rahîm'dir, merhametine sınır yoktur."},{"n":17,"t":"Allah'ın, kabulünü üstlendiği tövbe, bilgisizlikle kötülük işleyip de çok geçmeden tövbe edenler içindir. Allah, işte böylelerinin tövbesini kabul eder. Allah Alîm'dir, Hakîm'dir."},{"n":18,"t":"Yoksa, kötülükleri yapıp yapıp da her birine ölüm geldiğinde, \"işte şimdi tövbe ettim\" diyenler için tövbe yoktur. Küfre batmış olarak ölenlere de tövbe yoktur. Böylelerine biz korkunç bir azap hazırladık."},{"n":19,"t":"Ey iman edenler! Kadınlara mirasçı olmanız/onları miras gibi devralmanız size helal değildir. Açık bir fuhuş yapmadıkça, onlara verdiğinizin bir kısmını alıp götürmek için onları sıkıştırmayın. Onlarla güzellikle, hakka uygun bir şekilde geçinin. Eğer onlardan hoşlanmadıysanız, olabilir ki, hoşlanmadığınız bir şeyde Allah sizin için çok büyük bir hayır koymuştur."},{"n":20,"t":"Bir zevcenin yerine başka bir zevce almak istemişseniz onlardan birine yükler dolusu mal vermiş olsanız da o maldan hiçbir şeyi geri almayın. İftira ederek, açık bir günah işleyerek mi geri alacaksınız onu?"},{"n":21,"t":"Hem o malı nasıl alırsınız ki? Daha önce birbirinizle derinden derine kaynaşmıştınız. Ve onlar sizden çok sağlam bir söz de almışlardı."},{"n":22,"t":"Geçmişte kalanlar hariç, babalarınızın nikâhlamış olduğu kadınlarla evlenmeyin. Böyle bir şey açık bir edepsizlik, nefret gerektiren bir kötülüktür. Çirkin bir yoldur bu."},{"n":23,"t":"Analarınız, kızlarınız, kız kardeşleriniz, halalarınız, teyzeleriniz, erkek kardeşin kızları, kız kardeşin kızları, sizi emziren sütanalarınız, sütkardeşleriniz, karılarınızın anaları, kendileriyle zifafa girdiğiniz karılarınızdan olup evlerinizde bulunan üvey kızlarınız size haram kılınmıştır. Eğer analarıyla zifafa girmemişseniz, onlarla evlenmenizde bir sakınca yoktur. Öz evlatlarınızın karıları ve iki kız kardeşi bir arada almanız da size haram kılınmıştır. Eskide kalanlar müstesna. Allah Gafûr'dur, Rahîm'dir."},{"n":24,"t":"Harpte elinize geçmiş kadınlar hariç olmak üzere, nikâhlı kadınlarla evlenmeniz de haram kılınmıştır. Bu, üzerinize Allah'ın yazdığıdır. Bunlar dışındakileri, mallarınızı vererek almanız; şunu bunu dost tutmayarak iffetli yaşamanız, zina etmemeniz şartıyla size helal kılınmıştır. Kendilerinden nimetlendiğiniz kadınların mehirlerini onlara bir hak olarak verin. Mehir kesişmeden sonra karşılıklı hoşnutluğa bağlı hallerde üzerinize günah yoktur. Allah, her şeyi bilir, tüm hikmetlerin sahibidir."},{"n":25,"t":"İçinizden her kim hür, mümin kadınları nikahlayacak mali güce ulaşamazsa, ellerinizin altındaki mümin cariyelerinizden/ hizmetçilerinizden biriyle evlensin. Allah sizin imanınızı daha iyi bilir. Siz birbirinizdensiniz. O halde onları, ailelerinin izniyle nikahlayın; fuhuşta bulunmayan, gizli dost edinmeyen, iffetli kadınlar olmaları şartıyla mehirlerini de örfe uygun olarak verin. İffetli kılınıp nikahlandıktan sonra bir fuhuş yaparlarsa, üzerlerine düşecek ceza, hür kadınlara uygulanan cezanın yarısıdır. Bu durum, içinizden günaha girmekten korkan kimse içindir. Sabretmeniz sizin için daha hayırlıdır. Allah Gafûr'dur, Rahîm'dir."},{"n":26,"t":"Allah size açık-seçik bildirmek istiyor. Sizi, sizden öncekilerin yol ve yöntemlerinden haberdar ediyor. Size tövbe nasip ediyor. Allah her şeyi bilir, tüm hikmetlerin sahibidir."},{"n":27,"t":"Allah sizin tövbenizi kabul etmek istiyor. Şehvetlerine uyanlarsa sizin büyük bir sapışla sapmanızı isterler."},{"n":28,"t":"Allah size hafiflik getirmek istiyor. Çünkü insan çok zayıf yaratılmıştır."},{"n":29,"t":"Ey inananlar! Mallarınızı aranızda bâtıl bir yolla/tutarsız bahanelerle yemeyin. Kendi hoşnutluğunuzla gerçekleşmiş bir ticaret olursa başka. Kendi canlarınıza kıymayın/intihar etmeyin. Hiç kuşkusuz, Allah, size karşı çok merhametlidir."},{"n":30,"t":"Kim düşmanlık ve zulümle intihar günahını işlerse onu ateşe sokacağız. Bu, Allah için çok da kolaydır."},{"n":31,"t":"Eğer yasaklandığınız günahların büyüklerinden uzak kalırsanız, diğer kötülüklerinizi örteriz ve sizi nimet ve bereket dolu bir varış yerine ulaştırırız."},{"n":32,"t":"Allah'ın, bir kısmınıza bir kısmınızdan farklı olarak lütfettiği şeyleri isteyip durmayın. Erkeklere kendi kazandıklarından bir pay var; kadınlara da kendi kazandıklarından bir pay var. Allah'tan, O'nun lütfunu isteyin! Allah, her şeyi iyice bilmektedir."},{"n":33,"t":"Ana-babanın ve akrabanın geriye bıraktıkları malların hepsi için mirasçılar belirledik. Yeminlerinizin/anlaşmalarınızın akde bağladığı kimselere gelince, onların paylarını da kendilerine verin! Allah her şeyi dikkatli bir tanık olarak gözetlemektedir."},{"n":34,"t":"Erkekler; kadınları gözetip kollayıcıdırlar. Şundan ki, Allah, insanların bazılarını bazılarından üstün kılmıştır ve erkekler mallarından bol bol harcamışlardır. İyi ve temiz kadınlar saygılıdırlar; Allah'ın kendilerini koruduğu gibi, gizliliği gereken şeyi korurlar. Sadakatsizlik ve iffetsizliklerinden korktuğunuz kadınlara önce öğüt verin, sonra onları yataklarında yalnız bırakın ve nihayet onları evden çıkarın/bulundukları yerden başka yere gönderin! Bunun üzerine size saygılı davranırlarsa artık onlar aleyhine başka bir yol aramayın. Allah çok yücedir, sınırsızca büyüktür."},{"n":35,"t":"Eğer karı-kocanın aralarının açılmasından endişe ederseniz, bir hakem erkek tarafından, bir hakem de kadın tarafından gönderin. Bunlar, barıştırmak isterlerse Allah, kadınla erkeğin aralarını düzeltmede onları başarılı kılacaktır. Allah Alîm'dir, her şeyi bilir; Habîr'dir, her şeyden haberdardır."},{"n":36,"t":"Allah'a ibadet edin. O'na hiçbir şeyi ortak koşmayın. Ana-babaya, akrabaya, yetim ve öksüzlere, çaresizlere, yakın komşuya, uzak komşuya, yanınızdaki arkadaşa, yolda kalmışa, size bağımlı olanlara iyi ve güzel davranın. Allah, kasılıp böbürlenen şımarıkları sevmez."},{"n":37,"t":"Böyleleri cimriliğe saparlar, insanlara cimriliği emrederler ve Allah'ın lütfundan kendilerine verdiği şeyi saklarlar. Nankörler için biz, rezil edici bir azap hazırladık."},{"n":38,"t":"Bunlar, Allah'a ve âhiret gününe inanmazlar da halka gösteriş olsun diye mallarını dağıtırlar. Arkadaşı şeytan olan için ne kötü arkadaştır o."},{"n":39,"t":"Ne olurdu onlara, Allah'a ve âhiret gününe inanıp da Allah'ın kendilerine verdiği rızıktan öyle dağıtsalardı! Allah onları bilmekteydi."},{"n":40,"t":"Allah zerre kadar zulüm yapmaz. Küçücük bir iyilik olsa onu kat kat artırır ve kendi katından da büyük bir ödül verir."},{"n":41,"t":"Her ümmetten bir tanık getirip seni de şunlar üzerine bir tanık olarak diktiğimizde iş nice olacak?!"},{"n":42,"t":"Bir gündür ki o, küfre sapıp resule isyan edenler toprağa karışıp gitmeyi isteyecekler ve Allah'tan hiçbir sözü gizleyemeyecekler."},{"n":43,"t":"Ey iman edenler! Sarhoşken, ne söylediğinizi bilinceye kadar, cünüpken de -yolculuk halinde olmanız müstesna- boy abdesti alıncaya kadar namaza/duaya yaklaşmayın. Eğer hastalanırsanız yahut yolculuk halinde bulunursanız yahut biriniz tuvaletten gelmişse yahut kadınlara dokunmuşsanız, bütün bu durumlarda su da bulamamışsanız, temiz bir toprakla teyemmüm edin. Yani yüzlerinizi ve ellerinizi meshedin. Allah Afüvv'dür, günahları affeder, Gafûr'dur, hataları bağışlar."},{"n":44,"t":"Kendilerine Kitap'tan bir nasip verilenlere baksana! Sapıklığı satın alıyorlar da istiyorlar ki, siz de yolu şaşırasınız."},{"n":45,"t":"Allah sizin düşmanlarınızı daha iyi bilir. Dost olarak, Allah yeter. Yardımcı olarak da Allah yeter."},{"n":46,"t":"Yahudilerden öyleleri var ki, kelimeleri yerlerinden kaydırırlar; din içinde sövgüler üreterek, dillerini eğip-bükerek: \"Dinledik, isyan ettik; dinle, dinlenmez olası, davar güder gibi güt bizi\" derler. Eğer onlar, \"Dinledik, boyun eğdik, dinle, bak bize!\" demiş olsalardı, kendileri için daha hayırlı ve daha yerinde olurdu. Fakat Allah, küfürleri yüzünden onlara lanet etmiştir. Çok az bir kısmı hariç, iman etmezler."},{"n":47,"t":"Ey kendilerine kitap verilenler! Biz bir takım yüzleri silip arkalarına çevirmeden, yahut Cumartesi Ashabı'nı lanetlediğimiz gibi onları da lanetlemeden önce, yanınızda bulunanı tasdikleyici olarak indirdiğimize inanın. Allah'ın emri yerine getirilmiş olacaktır."},{"n":48,"t":"Şu bir gerçek ki, Allah kendisine şirk koşulmasını affetmez, bunun dışında kalanı/bundan az olanı dilediği kişi için affeder. Allah'a şirk koşan, gerçekten büyük bir günah işlemiştir."},{"n":49,"t":"Bakmaz mısın, şu benliklerini ak-berrak gösterip duranlara! Hayır! İş, sandıkları gibi değil. Ancak Allah, dilediğini temizleyip aklar. Ve bir hurma lifi kadar zulme uğratılmazlar."},{"n":50,"t":"Bir bak, nasıl yalan düzüp iftira ediyorlar Allah'a! Açık günah olarak bu yeter."},{"n":51,"t":"Görmedin mi şu kendilerine Kitap'tan bir pay verilmiş olanları? Puta, tâğuta inanıyorlar; küfre batmışlar için, \"Bunlar inananlardan daha doğru yoldadır!\" diyorlar."},{"n":52,"t":"İşte bunlardır, Allah'ın kendilerine lanet ettiği. Allah'ın lanetlediği kişi için bir yardımcı asla bulamazsın."},{"n":53,"t":"Yoksa mülkten/yönetimden bir nasipleri mi var? Eğer öyle olsa, insanlara bir çekirdek bile vermezler."},{"n":54,"t":"Yoksa insanları, Allah'ın lütfundan kendilerine verdiği nimet yüzünden kıskanıyorlar mı? Evet biz, İbrahim Ailesi'ne de kitabı ve hikmeti vermiş, onlara çok büyük bir mülk de lütfetmiştik."},{"n":55,"t":"Onlardan bir kısmı ona inanmıştır; bir kısmı da ondan alıkoymaktadır. Böylesine, çılgın alevli cehennem yeter."},{"n":56,"t":"Ayetlerimizi inkâr edenleri yakında bir ateşe yaslayacağız. Derileri piştikçe, azabı tatsınlar diye, derilerini öncekinden başka derilerle değiştireceğiz. Allah Azîz ve Hakîm'dir."},{"n":57,"t":"İman edip hayra ve barışa yönelik işler yapanlara gelince, onları altından ırmaklar akan cennetlere koyacağız. Hep orada kalacaklardır. Orada kendileri için tertemiz eşler de olacaktır. Ve onları, en güzel biçimde serinleten bir gölgeye kavuşturacağız."},{"n":58,"t":"Şu bir gerçek ki, Allah size emanetleri, onlara ehil olanlara vermenizi ve insanlar arasında hükmettiğinizde adaletle hükmetmenizi emrediyor. Allah size bu şekilde ne güzel öğüt veriyor. Allah Semî'dir, çok iyi duyar; Basîr'dir, çok iyi görür."},{"n":59,"t":"Ey iman sahipleri! Allah'a itaat edin. Resule ve sizin içinizden olan/sizin seçtiğiniz hüküm ve yetki sahiplerine de itaat edin. Sonra bir şeyde tartışmaya girdiniz mi, eğer Allah'a ve âhiret gününe inanıyorsanız, onu Allah'a ve resule arz edin. Böyle yapmanız hem daha hayırlı hem de sonuç bakımından daha güzeldir."},{"n":60,"t":"Şunları görmedin mi? Kendilerinin, sana indirilene de senden önce indirilene de inandıklarını sanarken, inkâr etmekle emrolundukları tağutu aralarında hakem yapmak istiyorlar. Zaten şeytan da onları geri dönülmez bir sapıklıkla sersem hale getirmek istiyor."},{"n":61,"t":"Kendilerine, Allah'ın indirdiğine ve resule gelin denince, o ikiyüzlülerin senden iyice yüz çevirdiklerini görürsün."},{"n":62,"t":"Peki, nasıl oluyor da ellerinin hazırladıkları yüzünden başlarına bir musibet çöktüğünde, sana gelip, \"Biz sadece iyilik yapmak, barıştırmak istedik!\" diye Allah'a yeminler ediyorlar!"},{"n":63,"t":"Allah bunların kalplerindekini biliyor. Artık aldırma onlara; öğüt ver kendilerine ve öz benlikleri hakkında etkili sözler söyle onlara."},{"n":64,"t":"Biz hiçbir resulü, Allah'ın izniyle kendisine itaat edilmesi dışında bir amaçla göndermedik. Eğer onlar, öz benliklerine zulmettiklerinde sana gelip Allah'tan af dileseler, resul de kendileri için af dileseydi, elbette ki Allah'ı tövbeleri cömertçe kabul eden bir Rahîm olarak bulacaklardı."},{"n":65,"t":"Hayır, Rabbine yemin olsun ki iş, onların sandığı gibi değil. Onlar, aralarında çıkan karmaşık işlerde seni hakem yapıp verdiğin hükümle ilgili olarak, içlerinde hiçbir burukluk duymadan tam bir teslimiyete ulaşmadıkça iman etmiş olamazlar."},{"n":66,"t":"Eğer onlar üzerine, \"Kendinizi öldürün yahut yurtlarınızdan çıkın!\" diye yazmış olsaydık, içlerinden pek azı hariç, bunu yapmazlardı. Ama onlar kendilerine öğütleneni yapsalardı, onlar için hem daha hayırlı olurdu hem de ömürlü olmaları bakımından daha yarayışlı."},{"n":67,"t":"O takdirde kendilerine katımızdan büyük bir ödül elbette verirdik."},{"n":68,"t":"Ve onları dosdoğru bir yolla elbette kılavuzlardık."},{"n":69,"t":"Allah'a ve resule itaat eden kişilere gelince, bunlar, Allah'ın kendilerine nimet verdikleriyle beraberdirler. Peygamberlerle, hak dostlarıyla, şehitlerle, hayır ve barışı sevenlerle. Ne güzel dosttur bunlar!"},{"n":70,"t":"Böylesi bir beraberlik Allah'ın lütfudur. Herşeyi bilici olarak Allah yeter."},{"n":71,"t":"Ey inananlar! Savunma tedbirlerinizi alın. Gerektiğinde de bölükler halinde hareket geçin yahut toplu halde savaşa çıkın."},{"n":72,"t":"İçinizden öylesi de var ki, ne olursa olsun ağırdan alır. Size bir musibet gelip çatarsa şöyle diyecektir: \"İyi ki onlarla birlikte şehit olmadım. Allah bana lütufta bulundu.\""},{"n":73,"t":"Eğer size Allah'tan bir lütuf erişirse o -sizinle kendisi arasında hiçbir sevgi yokmuş gibi- şöyle diyecektir: \"Keşke ben de onlarla olsaydım da büyük bir başarı kazansaydım!\""},{"n":74,"t":"İğreti hayatı âhiret hayatı karşılığında satanlar, Allah yolunda çarpışsınlar. Allah yolunda çarpışıp da öldürülen yahut galip gelene biz, yakında, büyük bir ödül vereceğiz."},{"n":75,"t":"Size ne oluyor da Allah yolunda ve \"Ey Rabbimiz bizi, halkı zulme sapmış şu kentten çıkar; katından bize bir dost gönder, katından bize bir yardımcı gönder!\" diye yakaran mazlum ve çaresiz erkekler, kadınlar, yavrular için savaşmıyorsunuz!"},{"n":76,"t":"İman edenler Allah yolunda savaşırlar; küfre sapanlarsa tağut yolunda savaşırlar. O halde, şeytanın dostlarıyla savaşın. Hiç kuşkusuz, şeytanın tuzağı çok zayıftır."},{"n":77,"t":"Kendilerine, \"Ellerinizi çekin, namazı/duayı yerine getirin, zekâtı verin!\" denilenleri görmedin mi? Üzerlerine savaş yazılınca, içlerinden bir grup, insanlardan Allah'tan korkmuş gibi, hatta daha şiddetli bir korkuyla korkar oldu. Ve şöyle dediler: \"Ey Rabbimiz! Ne diye yazdın üzerimize savaşı; yakın bir süreye kadar bizi erteleseydin ya!\" De ki: \"Dünya nimeti çok azdır. Kötülükten sakınan için âhiret daha hayırlıdır. Bir kıl kadar bile zulme uğratılmazsınız.\""},{"n":78,"t":"Nerede olursanız olun ölüm sizi yakalayacaktır. Titizlikle korunan muhteşem kulelerde olsanız bile. Onlara bir iyilik isabet ettiğinde, \"Bu, Allah katındandır!\" derler. Ama kendilerine bir kötülük dokunduğunda, \"Bu senin yüzündendir.\" derler. De ki: \"Hepsi, Allah katındandır.\" Şu topluluğa ne oluyor ki, neredeyse hiçbir sözü anlamıyorlar!"},{"n":79,"t":"İyilik ve güzellikten sana her ne ererse Allah'tandır. Kötülük ve çirkinlikten sana ulaşan şeyse kendi nefsindendir. Biz seni insanlara bir resul olarak gönderdik. Tanık olarak Allah yeter."},{"n":80,"t":"Resule itaat eden Allah'a itaat etmiş olur. Yan çizen çizsin, biz seni onlar üzerine bekçi göndermedik."},{"n":81,"t":"\"Baş üstüne\" diyorlar ama senin yanından ayrıldıklarında, içlerinden bir grup senin söylediğinin tam tersini planlıyor. Allah, onların sabahlara kadar kurup durduklarını yazıyor. Onlardan yüz çevir, Allah'ı vekil et. Vekil olarak Allah yeter."},{"n":82,"t":"Kur'an'ı, iyice okuyup düşünmüyorlar mı? Eğer o, Allah'tan başka birinin katından gelseydi, elbetteki onun içinde birçok ihtilaf bulacaklardı."},{"n":83,"t":"Onlara, güven yahut korkuya ilişkin bir haber ulaştığında onu hemen yaydılar. Oysaki, onu resule ve içlerindeki sorumluluk sahiplerine götürmüş olsalardı, aralarındaki okuyup araştırarak hüküm çıkaranlar, onu elbette bileceklerdi. Eğer Allah'ın lütuf ve rahmeti üzerinizde olmasaydı, pek azınız/pek az işiniz hariç şeytanın ardısıra giderdiniz."},{"n":84,"t":"Allah yolunda savaş. Kendinden başkasından sorumlu değilsin. İnananları da teşvik et. Umulur ki Allah, küfre sapanların gücünü kırar. Allah, kuvvetçe daha üstün, cezalandırmada daha güçlüdür."},{"n":85,"t":"Kim güzel bir işe aracı olursa ondan ona bir pay vardır. Kim kötü bir şeye aracı olursa ondan da ona bir pay vardır. Allah herşeye, herkese gıda ulaştırır, Mukît'tir."},{"n":86,"t":"Bir selam ile selamlandığınızda, onun daha güzeliyle yahut aynısıyla karşılık verin. Hiç kuşkusuz Allah Hasîb'dir, herşeyi güzelce hesaplamaktadır."},{"n":87,"t":"Allah'tır O, ilah yoktur O'ndan başka. Hakkında hiçbir kuşku bulunmayan kıyamet gününde, hepinizi muhakkak bir araya toplayacaktır. Hadis/söz bakımından, Allah'tan daha sadık kim olabilir?"},{"n":88,"t":"Size ne oluyor da münafıklar hakkında iki gruba ayrılıyorsunuz? Allah onları kazandıkları yüzünden baş aşağı etmişken, Allah'ın saptırdığını yola getirmek mi istiyorsunuz? Allah'ın şaşırttığına sen asla yol sağlayamazsın."},{"n":89,"t":"Onlarla eşitlenesiniz diye kendilerinin küfre saptığı gibi küfre sapmanızı istediler. O halde, Allah yolunda göç edecekleri vakte kadar onlardan dostlar edinmeyin. Eğer yüz çevirirlerse onları yakalayın ve bulduğunuz yerde öldürün. Bir daha da onlardan ne dost edinin ne de yardımcı."},{"n":90,"t":"Ancak sizinle aralarında antlaşma olan bir topluma sığınanlarla, kendi toplumlarıyla yahut sizinle savaşma konusunda yürekleri yetersiz kalıp da size gelenlere dokunmayın. Allah dileseydi onları elbette sizin üstünüze salardı, onlar da sizinle mutlaka savaşırlardı. O halde, sizden uzak durur, sizinle savaşmaz, size barış eli uzatırlarsa, artık Allah size, üzerlerine gitmek için bir yol vermemiştir."},{"n":91,"t":"Diğer bazılarını da bulacaksınız ki, hem sizden emin olmak hem de kendi toplumlarından emin olmak isterler. Ama fitneyle yüz yüze getirildiklerinde başaşağı içine dalarlar. Bunlar sizden uzak durmazlar, sizinle barışa gitmezler ve ellerini sizden çekmezlerse onları yakalayın, tuttuğunuz yerde öldürün. İşte böylelerinin üstüne gitmeniz için size açık bir izin ve kuvvet verilmiştir."},{"n":92,"t":"Yanlışlık hali müstesna, bir müminin bir mümini öldürmesi olacak şey değildir. Yanlışlıkla bir mümini öldürenin, özgürlüğü elinden alınmış bir mümini özgürlüğüne kavuşturması, ölenin ailesine de üzerinde anlaşmaya varılacak tatmin edici bir diyet vermesi gerekir. Vârislerin, diyeti bağışlaması hali müstesna. Eğer öldürülen, mümin olmakla birlikte size düşman bir topluluktan ise o zaman öldürenin, özgürlüğünden yoksun bir mümini özgürlüğüne kavuşturması gerekir. Öldürülen, sizinle aralarında antlaşma bulunan bir toplumdan ise o durumda, öldürülenin ailesine tatmin edici bir diyet verme yanında, hürriyetinden yoksun bir mümini hürriyetine kavuşturmak da gerekli olur. Bunlara imkân bulamayan, Allah'a tövbe olarak iki ay kesiksiz oruç tutar. Allah, gereğince bilendir, hikmeti sonsuzdur."},{"n":93,"t":"Bir mümini kasten öldürene gelince, onun cezası, içinde uzun süre kalmak üzere cehennemdir. Allah gazap etmiştir böylesine, lanetlemiştir onu; çok büyük bir azap hazırlamıştır ona."},{"n":94,"t":"Ey iman edenler! Allah yolunda gaza için dolaştığınızda, iyice anlayıp dinleyin de size selam verene/barış teklifi sunana \"Sen mümin değilsin!\" demeyin. İğreti hayatın menfaatine göz dikiyorsunuz ama Allah katında çok ganimetler vardır. Önceden siz de öyle idiniz ama Allah size lütufta bulundu. O halde, iyice araştırın, anlayın dinleyin. Çünkü Allah, yapmakta olduklarınızdan haberdardır."},{"n":95,"t":"İnananların; özür sahibi olmaksızın oturanlarıyla, Allah yolunda malları ve canlarıyla didinip gayret gösterenleri aynı değildir. Allah, malları ve canlarıyla yoğun gayret gösterenleri oturanlara derece bakımından üstün kılmıştır. Allah hepsine güzellik vaat etmiştir ama yoğun gayret gösterenleri, çok büyük bir ödülle, oturanlardan üstün kılmıştır."},{"n":96,"t":"Allah katından dereceler, bir bağışlanma, bir rahmet... Allah çok affedici çok merhametlidir."},{"n":97,"t":"Melekler, öz benliklerine zulmetmiş olanların canlarını alırken, onlara şöyle dediler: \"Neredeydiniz siz?\" Cevap verdiler: \"Yeryüzünde ezilip horlananlardandık biz.\" Melekler dediler ki: \"Allah'ın yeryüzü geniş değil miydi ki orada bir yerden bir yere göçesiniz?\" İşte böylelerinin varacağı yer cehennemdir. Ne kötü dönüş yeridir o!"},{"n":98,"t":"Kadınlardan, erkeklerden, yavrulardan hiçbiri beceri gösteremeyen, hiçbir yol bulamayanların durumu farklıdır."},{"n":99,"t":"Bunların, Allah tarafından affedilmeleri umulur. Allah affedicidir, günahları bağışlayıcıdır."},{"n":100,"t":"Kim Allah yolunda hicret ederse yeryüzünde, varıp sığınarak karşı harekete girişecek çok yer bulur; geniş bir imkân da bulur. Ve her kim, evinden Allah'a ve resulüne hicret niyetiyle çıkar da kendisine ölüm yetişirse onun ödülünü vermek Allah'a düşer. Allah Gafûr'dur, Rahîm'dir."},{"n":101,"t":"Yeryüzünde dolaştığınız zaman, küfre sapanların size tedirginlik vermesinden korkarsanız, namazı/duayı kısaltmanızda sizin için bir sakınca yoktur. Şu bir gerçek ki, inkârcı nankörler sizin için açık bir düşmandırlar."},{"n":102,"t":"Sen içlerinde olup da onlara namaz kıldırdığın vakit, içlerinden bir grup seninle namaza dursun; silahlarını da alsınlar. Bunlar secdeye varınca, diğerleri arkalarında beklesinler. Sonra namaz kılmamış/dua etmemiş olan diğer grup gelip seninle birlikte namaz kılsınlar/dua etsinler. Dikkatli olsunlar, silahlarını yanlarına alsınlar. Kâfirler isterler ki, silahlarınızdan ve teçhizatınızdan habersiz olasınız da üstünüze bir çullanışla çullanıversinler. Eğer yağmurdan gelen bir sıkıntı varsa yahut hasta-yaralı iseniz silahlarınızı bırakmanızda sizin için bir sakınca yoktur. Ama tedbirinizi alın, dikkatli olun. Allah, kâfirler için rezil edici bir azap hazırlamıştır."},{"n":103,"t":"Namazı/duayı tamamlayınca, artık Allah'ı ayakta, oturarak, yan yatmışken anın. Sükûnet bulduğunuzda, namazı/duayı tam bir biçimde yerine getirin. Namaz/dua, müminler üzerine vakti belirlenmiş bir farz olmuştur."},{"n":104,"t":"Düşman topluluğu izlemekte gevşeklik göstermeyin. Siz sıkıntıya düşüyorsanız, hiç kuşkusuz tıpkı sizin gibi onlar da sıkıntıya düşüyorlar; ama siz, Allah'tan onların umamayacağı şeyleri umuyorsunuz. Allah Alîm'dir, Hakîm'dir."},{"n":105,"t":"Kuşku yok ki, biz bu Kitap'ı sana, insanlar arasında Allah'ın sana gösterdiği ile hükmedesin diye hak olarak indirdik. Sakın hainlere yardakçı olma!"},{"n":106,"t":"Allah'tan af dile; Allah çok affedici, çok merhametlidir."},{"n":107,"t":"Öz benliklerine hainlik edenler için didinip durma. Çünkü Allah, sürekli hainlik eden günahkârı sevmez."},{"n":108,"t":"İnsanlardan gizleniyorlar/gizliyorlar da Allah'tan gizlenmiyorlar/gizlemiyorlar. Oysaki O, O'nun hoşlanmadığı sözü gece boyu sarfederlerken onlarla beraberdir. Allah, onların yapmakta olduklarını çepeçevre kuşatmıştır."},{"n":109,"t":"Diyelim, siz onlar için dünya hayatında mücadele verdiniz. Peki, kıyamet günü Allah'a karşı onlar için kim mücadele verir, onlar hakkında kim vekillik yapar?"},{"n":110,"t":"Kim bir kötülük yapar yahut öz benliğine zulmeder de sonra Allah'tan af dilerse Allah'ı çok affedici, çok merhametli bulur."},{"n":111,"t":"Günah kazanan onu kendi nefsi aleyhine kazanır. Allah Alîm ve Hakîm'dir."},{"n":112,"t":"Kim bir hata yahut günah işler de sonra onunla bir suçsuzu itham ederse hiç kuşkusuz, büyük bir iftira ve açık bir günah yüklenmiş olur."},{"n":113,"t":"Eğer Allah'ın senin üzerindeki lütfu ve rahmeti olmasaydı, onlardan bir grup seni şaşırtmaya mutlaka yeltenecekti. Ama onlar kendilerinden başkasını saptıramazlar. Ve sana hiçbir şekilde zarar veremezler. Allah sana Kitap'ı ve hikmeti indirmiş ve sana bilmediğin şeyleri öğretmiştir. Allah'ın senin üzerindeki lütfu çok büyüktür."},{"n":114,"t":"Onların fısıldaşmalarının çoğunda hayır yoktur. Ancak, bir sadakaya, bir iyiliğe ve insanlar arasında bir barıştırmaya özendiren başka. Kim böyle bir şeyi Allah'ın hoşnutluğunu kazanmak niyetiyle yaparsa biz ona yakında çok büyük bir ödül vereceğiz."},{"n":115,"t":"Erdirici kılavuzluk kendisine ayan-beyan geldikten sonra, resulden kopup müminlerin yolunun dışını izleyeni biz, yöneldiğiyle kaynaştırır, sonra da cehenneme sallarız. Ne kötü bir dönüş yeridir o!"},{"n":116,"t":"Allah, kendisine ortak koşulmasını affetmez ama bunun dışında kalanı/bundan az olanı dilediği kişi için affeder. Allah'a şirk koşan, dönüşü olmayan bir sapıklığa dalıp gitmiştir."},{"n":117,"t":"Allah'ın berisindekilere davet/dua edenler sadece dişilere/dişileşmiş halde davet/dua ederler. Ve onlar inatçı bir şeytandan başkasına çağırıp yakarmıyorlar."},{"n":118,"t":"Allah o şeytana lanet etmiştir. Demişti ki o: \"Senin kullarından belirli bir pay elbette alacağım.\""},{"n":119,"t":"\"Yemin olsun, onları saptıracağım, onları kuruntulara/hurafelere/anlamını bilmeden okumaya mutlaka iteceğim. Onlara mutlaka emir vereceğim de davarların kulaklarını yaracaklar; onlara muhakkak emredeceğim de Allah'ın yaratışını/yarattıklarını değiştirecekler.\" Kim Allah'ı bırakıp da şeytanı yandaş edinirse açık bir hüsrana kesinlikle yuvarlanmış olacaktır."},{"n":120,"t":"Şeytan, onlara söz verir, ümit verip hayal kurdurur, hurafeye/anlamını bilmeden okumaya iter. Ama o, onlara bir aldanıştan başka hiçbir şey vaat etmez."},{"n":121,"t":"Bunların varacakları yer cehennemdir. Ve cehennemden kaçıp kurtulacak bir yer bulamazlar."},{"n":122,"t":"İnanıp hayra ve barışa yönelik işler yapanları, altlarından ırmaklar akan cennetlere sokacağız. Uzun süre kalacaklardır orada. Allah'ın şaşmaz vaadidir bu. Söz söyleme bakımından Allah'tan daha doğru ve tutarlı kim olabilir?"},{"n":123,"t":"İş ne sizin kuruntularınızla/hurafelerinizle/anlamını bilmeden okuyuşlarınızla ne de Ehlikitap'ın kuruntuları/hurafeleri/anlamını bilmeden okuyuşlarıyla çözülür. Kötülük yapan onunla cezalandırılır. Ve böyle biri, kendisi için Allah dışında ne bir dost bulur ne de bir yardımcı."},{"n":124,"t":"Erkek veya kadın, inanmış olarak hayra ve barışa yönelik işler yapanlar cennete gireceklerdir. Ve zerre kadar zulme uğratılmayacaklardır."},{"n":125,"t":"Güzel düşünüp/güzellikler sergileyerek ve özü-sözü doğru bir halde İbrahim'in milletine uyarak yüzünü Allah'a teslim edenden daha güzel dinli kim olabilir! Allah İbrahim'i dost edinmişti."},{"n":126,"t":"Göklerde ne var, yerde ne varsa Allah'ındır. Allah Muhît'tir, her şeyi çepeçevre kuşatmıştır."},{"n":127,"t":"Senden kadınlar hakkında fetva soruyorlar. De ki: \"Onlar hakkında fetvayı size Allah veriyor.\" Yazılmış hakları olanı kendilerine vermeyip de kendileriyle nikâhlanmak istediğiniz kadınların yetimleri hakkında, ezilip horlanan çocuklar hakkında, yetimler için adaleti yerine getirmeniz hakkında. Kitap'ta olup da yüzünüze karşı okunan şeyler var. Hayır olarak yaptığınız her şeyi Allah, hakkıyla bilmektedir."},{"n":128,"t":"Eğer bir kadın, kocasının sadakatsızliğinden, yahut kendisine sırt çevirmesinden endişe ederse aralarını bir barış girişimiyle düzeltmelerinde kendileri için bir sakınca yoktur. Ve barış hep hayırdır. Nefisler, cimrilik ve doymazlığa hazır hale getirilmiştir. Güzel davranır, sakınıp korunursanız Allah, yapmakta olduklarınızdan haberdar olacaktır."},{"n":129,"t":"Tutkunluk derecesinde isteseniz de kadınlar arasında adaleti sağlamaya asla güç yetiremezsiniz. O halde tam bir eğilimle bir yana yönelip de öbürünü askıdaymış gibi bırakmayın. Barışı esas alıp sakınırsanız, Allah çok affedici, çok merhametli olacaktır."},{"n":130,"t":"Eğer ayrılırlarsa Allah, geniş nimetinden her birini zenginleştirir. Allah Vâsi'dir, genişler ve genişletir; Hakîm'dir, hikmeti sınırsızdır."},{"n":131,"t":"Göklerde ne var, yerde ne varsa yalnız Allah'ındır. İnan olsun, hem sizden önce kitap verilenlere hem de size, \"Allah'tan sakının!\" diye önerdik. Nankörlüğe saparsanız şu bir gerçek ki, göklerdekiler de yerdekiler de Allah'ındır. Allah Ganî'dir, zenginliğine sınır yoktur; Hamîd'dir, övülen ve övendir."},{"n":132,"t":"Hem göklerdekiler hem yerdekiler Allah içindir. Vekil olarak Allah yeter."},{"n":133,"t":"Ey insanlar! O dilerse sizi ortadan kaldırır, başkalarını getirir. Allah buna gerçekten Kadîr'dir."},{"n":134,"t":"Dünya nimeti ve bereketini isteyen bilsin ki, dünya nimeti de âhiret mutluluğu da Allah katındadır. Allah, çok iyi işitir, çok iyi görür."},{"n":135,"t":"Ey iman edenler! Öz benliğiniz, anne-babanız, yakınlarınız aleyhine de olsa, zengin veya fakir de olsalar, adaleti dimdik ayakta tutarak Allah için tanıklık edenler olun. Allah, ikisine de sizden daha yakındır. O halde, nefsinizin arzusuna uyarak adaletten sapmayın. Eğer dilinizi eğip büker yahut çekimser kalırsanız, Allah, yapmakta olduklarınızdan haberdardır."},{"n":136,"t":"Ey iman edenler! Allah'a, onun resulüne, resulüne indirmiş olduğu Kitap'a, daha önce indirmiş olduğu Kitap'a inanın. Kim Allah'ı, O'nun meleklerini, kitaplarını, resullerini ve âhiret gününü inkâr ederse geri dönüşü olmayan bir sapıklığa düşmüş olur."},{"n":137,"t":"Onlar ki inandılar, sonra küfre saptılar; yine inandılar, tekrar küfre saptılar, sonra da küfrü artırdılar; işte Allah onları affetmeyecek, onları hiçbir yola kılavuzlamayacaktır."},{"n":138,"t":"İkiyüzlülere şunu muştula: Kendileri için korkunç bir azap öngörülmüştür."},{"n":139,"t":"Öyle kişiler ki onlar, müminleri bırakıp da küfre sapanları dostlar ediniyorlar. Onların yanında onur ve yücelik mi arıyorlar? Onur ve yüceliğin tümü Allah'ındır."},{"n":140,"t":"Allah, Kitap'ta size şunu da indirmiştir: Allah'ın ayetlerinin inkâr edildiğini, bu ayetlerle alay edildiğini işittiğinizde, bir başka lakırdıya dalıp gittikleri zamana kadar, o münafıkların yanında oturmayın. Aksi halde siz de onlar gibi sayılırsınız. Hiç kuşkusuz Allah, münafıklarla kâfirleri cehennemde bir araya getirecektir."},{"n":141,"t":"Sizi gözetleyip duruyorlar. Allah'tan size fetih nasip olursa, \"sizinle birlikte değil miydik\" diyecekler. Kâfirlere bir nasip ulaşırsa şunu söyleyecekler: \"Başarınıza destek vermedik mi, müminlere karşı size siper olmadık mı?\" Artık kıyamet günü aranızda Allah hükmedecektir. Allah, müminler aleyhine kâfirlere bir yol asla nasip etmez."},{"n":142,"t":"Şu bir gerçek ki, ikiyüzlüler hileler düzerek Allah'ı aldatmaya uğraşıyorlar. Ama Allah da onları aldatıyor. Onlar namaza/duaya kalktıklarında tembel-miskin bir halde kalkarlar, insanlara gösteriş yaparlar. Onlar Allah'ı çok az hatırlarlar."},{"n":143,"t":"Arada bocalayıp dururlar. Ne şunlardan yanadırlar ne bunlardan yana. Allah'ın şaşırttığına sen asla yol sağlayamazsın."},{"n":144,"t":"Ey iman sahipleri! Müminleri bırakıp da küfre sapanları dostlar edinmeyin. Kendi aleyhinize Allah'a açık bir kanıt mı vermek istiyorsunuz?"},{"n":145,"t":"Şu da bir gerçek ki ikiyüzlüler, ateşin en alt katındadırlar. Onlar için bir yardımcı asla bulamayacaksın."},{"n":146,"t":"Ancak tövbe edip hallerini düzelterek Allah'a yapışan ve dinlerini samimiyetle Allah'a özgüleyenler müstesnadır. İşte böyleleri, müminlerle beraber olacaktır. Ve Allah, müminlere yakında çok büyük bir ödül verecektir."},{"n":147,"t":"İnanır şükrederseniz, Allah size azabı ne yapacak? Allah da teşekkür eder, O her şeyi gereğince bilir."},{"n":148,"t":"Allah çirkin sözün açıklanmasını sevmez. Zulme uğratılan kişi müstesna. Allah Semî'dir, Alîm'dir."},{"n":149,"t":"Bir hayrı açıklar yahut gizlerseniz, bir kötülüğü affederseniz, Allah da çok affedicidir, her şeye güç yetirendir."},{"n":150,"t":"Onlar ki Allah'ı ve O'nun resullerini inkâr ederler, Allah'la O'nun resulleri arasını açmak isterler de \"bir kısmına inanırız, bir kısmını inkâr ederiz\" derler; böylece imanla inkâr arasında bir yol tutmak isterler."},{"n":151,"t":"İşte bunlar gerçek kâfirlerdir. Ve biz, kâfirler için yere batırıcı bir azap hazırladık."},{"n":152,"t":"Allah'a ve O'nun resullerine iman edip onlardan birini ötekilerden ayırmayanlara gelince, Allah böylelerinin ödüllerini yakında kendilerine verecektir. Allah, Gafûr'dur, Rahîm'dir."},{"n":153,"t":"Ehlikitap, senden kendilerine gökten bir kitap indirmeni istiyor. Zaten onlar Mûsa'dan da bundan daha büyüğünü istemişlerdi. Demişlerdi ki: \"Allah'ı bize açıktan göster.\" Bunun üzerine zulümlerinden ötürü kendilerini yıldırım çarpmıştı. Sonra kendilerine açık-seçik kanıtların gelişi ardından buzağıya taptılar. Biz onların bu günahını da affettik. Biz Mûsa'ya apaçık bir kanıt/bir hükmetme gücü verdik."},{"n":154,"t":"Kesin söz vermeleri için Tûr'u üzerlerine kaldırdık ve onlara: \"Kapıdan secde ederek girin.\" dedik. Onlara şunu da söyledik: \"Cumartesi gününde azgınlık yapmayın.\" Onlardan sapasağlam bir söz almıştık."},{"n":155,"t":"Sözleşmelerini bozmaları, Allah'ın ayetlerine küfürle yaklaşmaları, peygamberleri haksız yere öldürmeleri ve \"Kalplerimiz kılıflıdır\" demeleri yüzünden... Hayır, öyle değil! Allah, küfürleri yüzünden kalplerine mühür basmıştır; bu yüzden pek azı hariç iman etmezler."},{"n":156,"t":"Küfürleri sebebiyle, Meryem aleyhinde büyük bir yalan söylemeleri yüzünden..."},{"n":157,"t":"\"Biz, Allah'ın resulü Meryem oğlu İsa Mesih'i öldürdük\" demeleri yüzünden. Oysaki onu öldürmediler, onu asmadılar da; sadece o onlara benzer gösterildi. Onun hakkında tartışmaya girenler, onunla ilgili olarak tam bir kuşku içindedirler. Onların, ona ilişkin bir bilgileri yoktur; sadece sanıya uymaktalar. Onu kesinlikle öldürmediler."},{"n":158,"t":"Tam aksine, Allah onu kendisine yükseltti. Allah Azîz'dir, Hakîm'dir."},{"n":159,"t":"Ehlikitap'tan her biri ölümünden önce ona mutlaka inanacaktır. Kıyamet günü de o, onlar aleyhine bir tanık olacaktır."},{"n":160,"t":"Yaptıkları zulümler ve birçok insanı Allah yolundan alıkoymaları yüzünden daha önce kendilerine helal kılınmış tertemiz şeyleri, Yahudilere haram kıldık."},{"n":161,"t":"Ve ribayı almaları yüzünden -oysaki ondan yasaklanmışlardı- ve haksız yollarla insanların mallarını yemeleri yüzünden onların küfre sapanlarına korkunç bir azap hazırladık."},{"n":162,"t":"Ama onların ilimde derinleşmiş olanları ve müminler, sana indirilene de senden önce indirilene de inanırlar. Namazı/duayı yerine getirirler, zekâtı vericidirler, Allah'a ve âhiret gününe inanırlar. İşte bunlara yakında büyük bir ödül vereceğiz."},{"n":163,"t":"Biz, tıpkı Nûh'a ve ondan sonraki peygamberlere vahyettiğimiz gibi sana da vahyettik. Biz İbrahim'e, İsmail'e, İshak'a, Yakub'a, torunlarına, İsa'ya, Eyyûb'e, Yûnus'a, Hârun'a, Süleyman'a da vahyettik. Dâvud'a da Zebur'u verdik."},{"n":164,"t":"Resuller var, hayat ve hatıralarını daha önce sana anlattık; resuller var, hayat ve hatıralarını sana anlatmadık. Allah, Mûsa'ya kelime kelime söz söylemişti."},{"n":165,"t":"Müjdeleyici ve uyarıcı resuller gönderdik ki, elçiler geldikten sonra insanların Allah'a karşı kanıtı olmasın. Allah Azîz'dir, Hakîm'dir."},{"n":166,"t":"Lakin Allah, sana indirdiğine tanıklık eder; onu kendi ilmiyle indirdi. Melekler de tanıklık ediyorlar. Tanık olarak Allah yeter."},{"n":167,"t":"İnkâr edip Allah yolundan geri çevirenler, dönüşü olmayan bir sapıklığa düşmüşlerdir."},{"n":168,"t":"İnkâr edip zulme sapanlar var ya, Allah onları affetmeyecek, onları hiçbir yola kılavuzlamayacaktır."},{"n":169,"t":"Cehennem yolu hariç! Uzun süre kalacaklardır orada. Allah için çok kolaydır bu."},{"n":170,"t":"Ey insanlar! Resul size Rabbinizden hakkı getirdi; artık inanın ona ki hayrınıza olsun. Nankörlük ederseniz göklerdekiler de yerdekiler de Allah'ındır. Allah Alîm'dir, Hakîm'dir."},{"n":171,"t":"Ey Ehlikitap! Dininizde aşırılığa gidip doymazlık etmeyin! Allah hakkında gerçek dışı bir şey söylemeyin! Meryem'in oğlu İsa Mesih, Allah'ın resulü ve kelimesidir. Onu, kendisinden bir ruhla beraber Meryem'e atmıştır. Artık Allah'a ve resullerine inanın. \"Üçtür!\" demeyin. Son verin, sizin için daha iyi olur. Allah Vâhid'dir, tek ve biricik ilahtır. Kendisi için bir çocuk olmasından arınmıştır O. Yalnız O'nundur göklerdekiler ve yerdekiler. Vekil olarak Allah yeter."},{"n":172,"t":"Ne Mesih Allah'ın bir kulu olmaktan çekinir ne de Allah'a yakınlaştırılmış melekler. Allah'a kulluk ve ibadetten çekinerek kibre saplanan bilsin ki, Allah onların tümünü huzurunda haşredecekir."},{"n":173,"t":"Bunun ardından da inanıp hayra ve barışa yönelik işler yapanların ödüllerini tam verecek ve lütfundan onlara fazlalıklar da bağışlayacaktır. Kulluktan çekinip büyüklük taslayanlara gelince, onlara korkunç bir azapla azap edecektir. Böyleleri, kendileri için Allah'tan başka ne bir dost bulacaklardır ne de bir yardımcı."},{"n":174,"t":"Ey insanlar! Size Rabbinizden apaçık, çok parlak ve güçlü bir kanıt gelmiştir. Biz size, herşeyi açık seçik gösteren bir ışık gönderdik."},{"n":175,"t":"Allah'a inanıp O'na sarılanları O, kendisinden bir rahmetin ve lütfun içine sokacak ve onları kendisine ulaşan dosdoğru bir yola kılavuzlayacaktır."},{"n":176,"t":"Fetva istiyorlar senden. De ki: \"Allah size, ana-babasız ve çocuksuz kişi hakkında şöyle fetva veriyor: 'Çocuğu olmayan, bir kız kardeşi bulunan kişi öldüğünde, onun terekesinin yarısı kız kardeşindir. Böyle bir kişi, çocuğu olmayan kız kardeşi öldüğünde, onun terekesinin tamamına mirasçı olur. Eğer ölenin iki kız kardeşi varsa terekenin üçte ikisi onlarındır. Eğer mirasçılar, kadın-erkek, birçok kardeşlerse bu durumda erkek kardeşe, iki kız kardeşin payı kadar verilir.' Allah size açık-seçik bildiriyor ki sapmayasınız. Allah, her şeyi gereğince bilmektedir."}],[{"n":1,"t":"Ey iman edenler! Akitlerin ve ahitlerin icaplarını yerine getirin. Siz ihramlı iken avlanmayı helal saymamak şartıyla ve ileride size okunacaklar müstesna olmak üzere, davar cinsinden hayvanlar size helal kılınmıştır. Kuşkunuz olmasın ki, Allah, iradesi yönünde hüküm verir."},{"n":2,"t":"Ey iman edenler! Allah'ın ibadet, iyilik ve güzellik alâmeti kıldığı şeylere, çarpışmanın yasak olduğu haram aya, kurbanlık hediyelere, gerdanlıklara, Rablerinden bir lütuf ve rıza niyaz ederek Mescid-i Haram'a gelmiş olanlara saygısızlık etmeyin! İhramdan çıktığınız vakit avlanın. Bir topluluğun, sizi Mescid-i Haram'dan uzak tutmak için sergilediği kötülük, sizi saldırganlık ve düşmanlığa sakın itmesin! Hayırda erginlik/dürüstlük ve takva üzere yardımlaşın! Kötülük/çirkinlik, düşmanlık/saldırganlık üzere yardımlaşmayın. Allah'tan sakının! Kuşkunuz olmasın ki, Allah'ın azabı çok şiddetlidir."},{"n":3,"t":"Şunlar size haram kılınmıştır: Boğazlanmayarak ölmüş hayvanın eti, kan, domuz eti, üzerine Allah'tan başkasının adı anılmış, boğulmuş, vurulmuş, yuvarlanmış, süsülmüş, canı üzerineyken yetişip kestikleriniz müstesna olmak üzere canavar tarafından yırtılmış ve dikili adak taşları üzerinde boğazlanmış hayvanlar ve bir de fal oklarıyla kısmet paylaşmanız... Bütün bunlar birer sapıştır. Küfre batmış olanlar bugün dininizden ümitlerini kestiler. Artık onlardan korkmayın, benden korkun! Bugün sizin için dininizi kemale erdirdim, üzerinizdeki nimetimi tamamladım ve sizin için din olarak İslam'ı/Allah'a teslim olmayı seçtim. Şu da var ki, her kim ciddi bir açlıkla yüz yüze gelir de günaha kaçmak maksadı olmaksızın onlardan yemek zorunda kalırsa, elbette Allah Gafûr ve Rahîm'dir."},{"n":4,"t":"Sana soruyorlar, onlar için helal kılınan ne? Şöyle söyle: \"Sizin için bütün temiz nimetler helal kılınmıştır. Eğittiğiniz avcı kuşların tuttukları ile eğittiğiniz av köpeklerinin tuttukları da size helal kılındı. Siz bu hayvanlara, Allah'ın size öğrettiklerinden öğretiyorsunuz. O halde onların sizin için tuttuklarından da yiyin ve üzerine Allah'ın adını anın. Allah'tan sakının! Allah gerçekten hesabı çok çabuk görür.\""},{"n":5,"t":"Bugün size bütün temiz nimetler helal kılındı. Kendilerine kitap verilmiş olanların yemekleri size helaldir. Sizin yemekleriniz de onlara helaldir. Mümin kadınların iffetlileriyle, sizden önce kendilerine kitap verilmiş olanların iffetli hanımları da mehirlerini verdiğiniz takdirde; iffetinizi korumanız, zinadan uzak kalmanız ve şunu-bunu dost tutmamanız şartıyla size helaldir. İmanı tanımayıp nankörlük edenin ameli boşa gitmiştir. Ve o, âhirette de hüsrana uğrayanlardandır."},{"n":6,"t":"Ey iman sahipleri! Namaza/duaya duracağınız zaman yüzlerinizi ve dirseklere kadar ellerinizi yıkayın; başlarınızı meshedin ve topuklara kadar ayaklarınızı meshedin/yahut yıkayın. Eğer cünüp iseniz iyice temizlenin! Hasta yahut yolculuk halinde iseniz yahut biriniz tuvaletten gelmişse yahut kadınlara dokunmuş da su bulamamışsanız temiz bir toprakla teyemmüm edin: Yüzlerinizi ve ellerinizi ondan meshedin. Allah size zorluk çıkarmak istemiyor. Ancak sizi temizlemek ve üzerinizdeki nimetini tamamlamak istiyor ki, şükredebilesiniz."},{"n":7,"t":"Allah'ın, üzerinizdeki nimetini ve sizi bağladığı mîsakını unutmayın. Hani, \"İşittik, boyun eğdik!\" demiştiniz. Allah'tan sakının. Allah, göğüslerin içindekini çok iyi bilir."},{"n":8,"t":"Ey iman edenler! Adalet ve dürüstlüğün tanıkları olarak Allah için kollayıp gözetleyenler olun! Bir topluluğun çirkinlik ve kötülüğü sizi adaletsiz davranmaya asla itmesin. Adaletli olun! Bu, takvaya/korunup sakınmaya daha uygundur. Allah'tan sakının. Allah, yapmakta olduklarınızdan haberdardır."},{"n":9,"t":"Allah, inanıp hayra ve barışa yönelik işler yapanlara vaatte bulunmuştur: Onlar için bir bağışlanma ve büyük bir ödül vardır."},{"n":10,"t":"Küfre sapıp ayetlerimizi yalanlayara gelince, bunlar cehennemin dostlarıdırlar."},{"n":11,"t":"Ey iman edenler! Allah'ın, üzerinizdeki nimetini hatırlayın! Hani bir topluluk ellerini size uzatmaya niyet etmişti de Allah onların ellerini sizden çekmişti. Allah'tan sakının! Müminler yalnız Allah'a tevekkül etsinler!"},{"n":12,"t":"Yemin olsun ki, Allah İsrailoğullarının mîsakını almıştı da içlerinden on iki temsilci/başkan göndermiştik. Allah şöyle demişti: \"Ben sizinle beraberim. Namazı/duayı yerine getirirseniz, zekâtı verirseniz, resullerime inanır, onları desteklerseniz ve Allah'a güzel bir biçimde borç verirseniz, kötülüklerinizi elbette örteceğim ve sizi, altlarından ırmaklar akan cennetlere elbette koyacağım. Artık bundan sonra küfre gideniniz yolun denge noktasından sapmış olur.\""},{"n":13,"t":"Sonunda, verdikleri mîsakı bozdukları için onları lanetledik de kalplerini kaskatı yaptık. Kelimeleri yerlerinden kaydırıyorlar. Öğütlenmek üzere çağırıldıkları şeyden nasiplenmeyi unuttular. İçlerinden çok azı hariç, sen onlardan hep hainlik görürsün. Bununla birlikte onları affet, ellerini tut. Çünkü Allah güzellik sergileyenleri sever."},{"n":14,"t":"\"Biz Hıristiyanlarız!\" diyenlerden de mîsaklarını almıştık. Onlar da öğütlenmek üzere çağırıldıkları şeyden nasiplenmeyi unuttular. Bu yüzden, aralarına kıyamete değin düşmanlık ve şiddetli nefret saldık. Sınaat/teknoloji olarak ürettikleri şeylerin ne olduğunu Allah onlara yakında haber verecektir."},{"n":15,"t":"Ey Ehlikitap! Resulümüz size geldi. Kitap'tan saklamış olduklarınızın çoğunu size ayan-beyan açıklıyor; çoğundan da geçiyor. Şu bir gerçek ki, size Allah'tan bir ışık ve apaçık bir Kitap gelmiştir."},{"n":16,"t":"Allah, rızasına uyanları o Kitap'la esenlik ve barış yollarına iletir ve onları kendi izniyle karanlıklardan aydınlığa çıkarıp şaşmayan ve sapmayan dosdoğru yola kılavuzlar."},{"n":17,"t":"Yemin olsun ki, \"Allah Meryem'in oğlu Mesih'tir\" diyenler küfre batmışlardır. De ki: \"Allah; Meryem'in oğlu Mesih'i, annesini ve yeryüzündeki insanların hepsini helâk etmek istese Allah'a karşı kimin elinde bir güç vardır!\" Hem göklerin hem yerin hem de bunlar arasındakilerin mülkü/ yönetimi Allah'ındır. Dilediğini yaratır. Allah her şeye Kadîr'dir."},{"n":18,"t":"Yahudiler ve Hıristiyanlar dediler ki, biz Allah'ın oğulları ve sevgilileriyiz. De ki: \"O halde, niçin size günahlarınız yüzünden azap ediyor?\" Hayır, siz de O'nun yarattıklarından birer insansınız. Dilediğini affeder O, dilediğine azap eder. Hem göklerin hem yerin hem de bunlar arasındakilerin mülkü/yönetimi Allah'ındır. Dönüş de O'nadır."},{"n":19,"t":"Ey Ehlikitap! Resullerin arası kesildiği bir sırada resulümüz size geldi; ayan-beyan açıklamalarda bulunuyor. \"Bize ne müjdeci geldi ne uyarıcı\" demeyesiniz. İşte müjdeci de geldi size, uyarıcı da. Allah her şeye kadirdir."},{"n":20,"t":"Mûsa, kavmine şöyle demişti: \"Ey toplumum! Allah'ın, üzerinizdeki nimetini hatırlayın. İçinizde peygamberler vücuda getirdi, sizi krallar yaptı, âlemlerden hiç kimseye vermediklerini size verdi.\""},{"n":21,"t":"\"Ey toplumum! Allah'ın sizin için yazdığı kutsal toprağa girin, arkanıza dönmeyin; yoksa hüsrana uğramışlar durumuna düşersiniz.\""},{"n":22,"t":"Şöyle dediler: \"Ey Mûsa, orada zorbalardan oluşan bir toplum var. Onlar ordan çıkıncaya kadar biz oraya asla girmeyeceğiz. Eğer oradan çıkarlarsa biz o zaman gireceğiz.\""},{"n":23,"t":"İçine ürperti düşenlerden, Allah'ın nimet verdiği iki adam dedi ki: \"Onların içine kapıdan girin. Oraya girdiğinizde galip geleceksiniz. Eğer inananlar iseniz yalnız Allah'a güvenin.\""},{"n":24,"t":"Dediler ki: \"Ey Mûsa! Onlar orada oldukça biz oraya asla girmeyeceğiz. Hadi sen git, Rabbin'le birlikte savaşın. Biz şuracıkta oturacağız.\""},{"n":25,"t":"Şöyle yakardı Mûsa: \"Rabbim! Nefsimle kardeşimden başkasına söz geçiremiyorum. Artık sapıklar topluluğu ile bizim aramızı ayır!\""},{"n":26,"t":"Allah dedi ki: \"Orası onlara kırk yıl haram kılınmıştır. Yeryüzünde sersem sersem dolaşacaklar. Sen o sapıklar topluluğu için kederlenme.\""},{"n":27,"t":"Onlara Âdem'in iki oğlunun haberini de gerçek olarak oku. Hani, ikisi birer kurban sunmuşlardı da birinden kabul edilmişti, ötekinden kabul edilmemişti. \"Seni mutlaka öldüreceğim.\" dedi. Öteki: \"Allah sadece takva sahiplerinden kabul eder.\" dedi."},{"n":28,"t":"Beni öldürmek için elini bana uzatırsan, ben seni öldürmek için elimi sana uzatmayacağım. Şu bir gerçek ki, ben, âlemlerin Rabbi olan Allah'tan korkarım.\""},{"n":29,"t":"\"Ben istiyorum ki, sen benim günahımı da senin günahını da yüklenip ateş halkından olasın. İşte budur zalimlerin cezası!\""},{"n":30,"t":"Nihayet nefsi onu kardeşini öldürmeye ısındırdı, o da onu öldürdü. Böylece hüsrana uğramışlardan oldu."},{"n":31,"t":"Derken, Allah, kardeşinin cesedini nasıl saklayacağını ona göstermek için yeri eşeleyen bir karga gönderdi. O dedi ki: \"Vay be! Şu karga kadar bile olamıyor muyum ki, kardeşimin cesedini saklayayım.\" Bu arada, pişmanlık duyanlardan olmuştu."},{"n":32,"t":"İşte bu yüzden biz, İsrailoğulları üzerine şunu yazdık: Kim bir kişiyi, bir kişiye karşılık yahut yeryüzünde bir fesat sebebiyle olmaksızın öldürürse, insanları toptan öldürmüş gibidir. Ve kim bir kişiye hayat verirse insanlara toptan hayat vermiş gibidir. Andolsun, resullerimiz onlara açık-seçik kanıtlar getirmişlerdir. Ama onlardan birçoğu bunun ardından da yeryüzünde zulüm ve azgınlığa sapmaktadır."},{"n":33,"t":"Allah ve resulüyle savaşanların ve yeryüzünde bozgunculuk yapmaya çalışanların cezası şudur: Öldürülürler yahut asılırlar yahut elleriyle ayakları çaprazlamasına kesilir yahut bulundukları yerden sürülürler. Bu onlar için dünyada bir rezilliktir. Âhirette de onlara büyük bir azap vardır."},{"n":34,"t":"Ancak onları gücünüz altına almadan önce tövbe edenler olursa biliniz ki, Allah Gafûr ve Rahîm'dir."},{"n":35,"t":"Ey iman edenler! Allah'ın buyruğuna ters düşmekten sakının; O'na varmaya vesîle arayın. O'nun yolunda gayret gösterin ki, kurtuluşa erebilesiniz."},{"n":36,"t":"O küfre sapanlar var ya, yeryüzünde bulunanların tümü ve yanında bir o kadarı daha onların olsa da kıyamet gününün azabından kurtulmak için fidyeler verseler, yine de kabul edilmez. Onlar için acıklı bir azap vardır."},{"n":37,"t":"Ateşten çıkmak isterler ama ondan çıkamayacaklardır. Onlar için tepelerinden hiç inmeyecek bir azap vardır."},{"n":38,"t":"Hırsızlık yapan erkek ve kadının, yaptıklarına karşılık Allah'tan bir ceza olarak ellerini kesin. Allah Azîz'dir, Hakîm'dir."},{"n":39,"t":"Kim zulmünden sonra tövbe eder, halini düzeltirse kuşkusuz Allah onun tövbesini kabul eder. Allah çok affedici, çok merhametlidir."},{"n":40,"t":"Göklerin de yerin de mülkünün/saltanatının Allah'ın olduğunu bilmedin mi? Dilediğine azap eder O, dilediğini affeder. Allah'ın gücü her şeye yeter."},{"n":41,"t":"Ey Resul! Kalpleri inanmamış olduğu halde ağızlarıyla \"İnandık\" diyenlerle, Yahudilerden bozgunculuğa koşuşanlar seni üzmesin. Onlar yalana kulak verirler, sana gelmeyen başka bir topluluk için dinlerler. Kelimeleri yerlerinden sıçratıp değiştirirler. \"Eğer size şu verilirse alın, verilmezse sakının\" derler. Allah birini fitneye düşürmek isterse, sen onun için Allah karşısında hiçbir şey yapamazsın. Bunlar o kimselerdir ki, Allah kalplerini temizlemek istememiştir. Onlar için dünyada bir rezillik vardır; ahirette de onlara büyük bir azap vardır."},{"n":42,"t":"Yalana iyice kulak verirler, haramı tıka-basa yerler. Sana geldiklerinde, ister aralarında hüküm ver, ister onlardan yüz çevir. Eğer onlardan yüz çevirirsen sana hiçbir şekilde zarar veremezler. Ama aralarında hükmedersen, adaletle hükmet. Allah, adaletle hükmedenleri/adaleti ayakta tutanları sever."},{"n":43,"t":"İçinde Allah'ın hükmü bulunan Tevrat yanlarında iken, nasıl oluyor da senin hakemliğine baş vuruyorlar? Daha sonra da verilen hükümden yüz çeviriyorlar. Bunlar inanan kişiler değillerdir."},{"n":44,"t":"Biz indirdik Tevrat'ı, biz! Yol gösterici var onda, ışık var. Teslim olmuş peygamberler, Yahudilere onunla hükmederlerdi. Kendilerini Rabb'e adayanlarla ilim-hikmet sahipleri de... Çünkü Allah'ın Kitabı'nı korumakla görevlendirilmişlerdi. Ve hepsi de ona tanıktılar. Artık insanlardan korkmayın, benden korkun! Ayetlerimi basit bir ücret karşılığı satmayın! Allah'ın indirdiği ile hükmetmeyenler, kafirlerin ta kendileridir."},{"n":45,"t":"O Kitap'ta onlar üzerine şöyle yazmıştık: Cana can, göze göz, buruna burun, kulağa kulak, dişe diş... Yaralamalar karşılığında da kısas. Kim kısası bağışlarsa, bu bağışlaması kendisi için günahlara bir perde olur. Allah'ın indirdiğiyle hükmetmeyenler zalimlerin ta kendileridir."},{"n":46,"t":"Ardından o peygamberlerin izleri üzere Meryem oğlu İsa'yı gönderdik. Tevrat'tan yanında bulunanı doğruluyordu. Ona İncil'i verdik. Hidayet ve ışık vardı onda. Tevrat'tan yanında olanı tasdikleyici idi. Doğruya ve güzele kılavuzdu, takvaya sarılanlara bir öğüt."},{"n":47,"t":"İncil bağlıları Allah'ın onda indirdiğiyle hükmetsinler. Allah'ın indirdiğiyle hükmetmeyenler sapıkların ta kendileridir."},{"n":48,"t":"Sana da Kitap'ı hak olarak indirdik. Kitap'tan onun yanında bulunanı tasdikleyici ve onu denetleyip güvenilirliğini sağlayıcı olarak... O halde onlar arasında Allah'ın indirdiğiyle hükmet, Hak'tan sana gelenden uzaklaşıp onların keyiflerine uyma. Sizden her biri için bir yol/şerîat ve bir yöntem belirledik. Allah dileseydi sizi elbette bir tek ümmet yapardı. Ama size vermiş olduklarıyla sizi imtihana çeksin diye öyle yapmamıştır. O halde hayırlarda yarışın. Tümünüzün dönüşü Allah'adır. O size, tartışmış olduğunuz şeylerin esasını bildirecektir."},{"n":49,"t":"Sen de aralarında, Allah'ın indirdiğiyle hükmet. Onların keyiflerine uyma. Dikkat et de Allah'ın sana indirdiğinin bir kısmından seni uzaklaştırıp fitneye düşürmesinler. Eğer yüz çevirirlerse bil ki, Allah onları bazı günahları yüzünden belaya çarptırmak istiyor. Zaten insanların birçokları doğru yoldan iyice sapmış bulunuyorlar."},{"n":50,"t":"Yoksa cahiliye devrinin hükmünü mü arıyorlar? Gerçeği görebilen bir toplum için, Allah'tan daha güzel hüküm veren kim vardır?"},{"n":51,"t":"Ey iman edenler! Yahudileri ve Hıristiyanları gönül dostları edinmeyin. Onlar birbirlerinin gönül dostlarıdır. Sizden kim onları gönül dostu edinirse o, onlardandır. Allah, zalimler toplumunu doğruya ve güzele kılavuzlamaz."},{"n":52,"t":"Kalplerinde hastalık olanların, \"Başımıza bir felaket gelmesinden korkuyoruz.\" diyerek onların içine daldıklarını görürsün. Olabilir ki Allah, bir fetih yahut katından bir buyruk getirir de bunu yapanlar, benliklerinde sakladıkları şeye pişmanlık duyar hale gelirler."},{"n":53,"t":"İman edenler derler ki: \"Şunlar mıdır o tüm güçleriyle sizinle beraber olduklarına yemin edenler?\" Bütün amelleri boşa çıkmıştır da hüsrana uğrayanlardan oluvermişlerdir."},{"n":54,"t":"Ey inananlar! İçinizden kim dininden dönerse şunu bilsin: Allah, yakında, kendilerini sevdiği ve kendisini seven, müminlere karşı boynu bükük, kâfirlere karşı başı dik bir topluluk getirecektir. Bunlar Allah yolunda tüm gayretleriyle didinirler, hiçbir kınayanın kınamasından korkmazlar. Bu, Allah'ın, dilediğine yönelttiği bir lütuftur. Allah, yaratılışı ve yarattıklarını genişletir, her şeyi bilir."},{"n":55,"t":"Sizin gönül dostunuz Allah'tır, O'nun resulüdür, bir de rükû eder bir halde namazı/duayı yerine getirip, zekâtı vererek iman edenlerdir."},{"n":56,"t":"Allah'ı, O'nun resulünü ve iman edenleri dost edinen/Allah'tan, O'nun resulünden ve iman edenlerden yüz çeviren bilsin ki, galip gelecek olanlar Allah'ın taraftarlarıdır."},{"n":57,"t":"Ey iman edenler! Sizden önce kitap verilenlerden ve küfre sapanlardan, dininizi oyun ve eğlence edinenleri dost tutmayın. Eğer inanıyorsanız Allah'tan sakının."},{"n":58,"t":"Namaza/duaya çağırdığınızda onu oyun ve eğlence edindiler. Böyle yaptılar; çünkü onlar akıllarını işletmeyen bir topluluktur."},{"n":59,"t":"De ki: \"Ey Ehlikitap! Sadece şunun için bizden hoşlanmıyorsunuz: Allah'a, bize indirilene, daha önce indirilene inanmışız. Doğrusu şu ki, sizin çoğunuz yoldan sapmış olanlardır.\""},{"n":60,"t":"De ki: \"Allah katında ceza olarak bundan daha kötüsünü size bildireyim mi? Allah'ın lanetlediği, üzerine gazap indirdiğidir o. Allah böylelerinden maymunlar, domuzlar ve tağut uşakları yapmıştır. İşte bunlardır yer bakımından daha kötü, yolun denge noktasını kaybetme bakımından daha şaşkın olanlar.\""},{"n":61,"t":"Size geldiklerinde \"İnandık!\" derler. Gerçekte ise küfürle girmiş, yine onunla çıkmışlardır. Neler saklıyor olduklarını Allah daha iyi bilir."},{"n":62,"t":"Onların birçoğunun günahta, düşmanlıkta, haram yemede yarıştıklarını görürsün. Ne kötüdür o yapmakta oldukları!"},{"n":63,"t":"Ruhbanları ve hahamları onları, günah oluşturan sözlerinden, haram yemekten alıkoysalardı olmaz mıydı? Ne kötüdür onların sınaat/teknoloji olarak üretmekte oldukları."},{"n":64,"t":"Yahudiler dediler ki: \"Allah'ın eli bağlıdır.\" Kendi elleri bağlandı/elleri bağlanasıcalar! Söylemiş oldukları yüzünden lanetlendiler. Söylediklerinin aksine, Allah'ın iki eli de alabildiğine açıktır; dilediği gibi bağışta bulunur. İnan olsun ki, Rabbinden sana indirilen, küfür ve taşkınlık yönünden onları iyice azdıracaktır. Onların arasına, ta kıyamet gününe kadar düşmanlık ve nefret atmışızdır. Ne zaman savaş için bir ateş yaksalar, Allah onu söndürür de onlar yeryüzünde yine bozgunculuğa koşarlar. Ama Allah, bozguncuları sevmez."},{"n":65,"t":"Eğer Ehlikitap, iman edip korunsaydı, onların kötülüklerini mutlaka örter ve kendilerini bol nimetli cennetlere mutlaka sokardık."},{"n":66,"t":"Eğer onlar Tevrat'ı, İncil'i ve kendilerine indirilmiş olanı gerektiği şekilde uygulasalardı elbetteki hem üstlerinden hem ayaklarının altından rızıklanacaklardı. İçlerinde orta yolu izleyen bir topluluk var. Ama onların çoğunluğunun yapmakta olduğu ne kadar da kötü!"},{"n":67,"t":"Ey resul! Rabbinden sana indirileni tebliğ et. Eğer bunu yapmazsan onun verdiği peygamberlik görevini yerine getirmemiş olursun. Allah seni insanlardan korur. Allah, küfre batmış topluluğa kılavuzluk etmez."},{"n":68,"t":"De ki: \"Ey Ehlikitap! Siz, Tevrat'ı, İncil'i ve Rabbinizden size indirileni tam uygulamadıkça hiçbir şey değilsiniz.\" Rabbinden sana indirilen, onlardan birçoğunun küfür ve azlığını elbette artıracaktır. Küfre batan topluluk için tasalanma artık."},{"n":69,"t":"Şu bir gerçek ki, iman edenler, Yahudiler, Sâbiîler ve Hıristiyanlardan Allah'a ve âhiret gününe inanıp hayra ve barışa yönelik iş yapanlar için korku yoktur. Tasalanmayacaklardır onlar."},{"n":70,"t":"Yemin olsun ki biz, İsrailoğullarının kesin sözlerini almış da onlara resuller göndermiştik. Ne zaman bir resul onlara nefislerinin hoşlanmadığı birşeyi getirdiyse bir kısmını yalanladılar; bir kısmını da öldürüyorlardı."},{"n":71,"t":"Bir fitne kopmayacak sandılar. Kör oldular, sağır kesildiler. Derken Allah tövbelerini kabul etti. Sonra yine birçokları körleştiler, sağırlaştılar. Allah, onların yaptıklarını ayan-beyan görür."},{"n":72,"t":"Yemin olsun ki, \"Allah, Meryem'in oğlu Mesih'in ta kendisidir!\" diyenler küfre batmışlardır. Mesih şöyle demişti: \"Ey İsrailoğulları, hem sizin Rabbiniz hem de benim Rabbim olan Allah'a kulluk/ibadet edin! Gerçek olan şu ki, Allah'a ortak koşana Allah, cenneti haram kılmıştır. Varacağı yer ateştir onun. Zalimlerin yardımcıları olmayacaktır.\""},{"n":73,"t":"Yemin olsun ki, \"Allah, üçün üçüncüsüdür!\" diyenler de küfre batmıştır. Bir tek Tanrı dışında hiçbir ilah yoktur. Bu söyleyegeldiklerine son vermezlerse, onların küfre sapanlarına korkunç bir azap mutlaka gelip çatacaktır."},{"n":74,"t":"Hâlâ Allah'a yönelip tövbe ederek ondan af dilemiyorlar mı? Allah Gafûr'dur, Rahîm'dir."},{"n":75,"t":"Meryem'in oğlu Mesih, bir resulden başkası değildir. Ondan önce de resuller gelip geçmiştir. Onun annesi de özü-sözü doğru biriydi. İkisi de yemek yerlerdi. Bak nasıl açıklıyoruz onlara ayetleri! Sonra bak, nasıl gerisin geri çevriliyorlar!"},{"n":76,"t":"Söyle onlara: \"Allah'ın yanında bir de, size zarar yahut yarar sağlama gücü olmayan şeylere mi kölelik/kulluk ediyorsunuz? Allah, en iyi duyan, en iyi bilenin ta kendisidir.\""},{"n":77,"t":"De ki: \"Ey Ehlikitap! Dininizde azgınlık edip hak dışına çıkarak aşırılığa gitmeyin. Daha önce sapmış, birçoğunu saptırmış ve yolun denge noktasından uzağa düşmüş bir topluluğun keyiflerine uymayın.\""},{"n":78,"t":"İsrailoğullarının küfre sapanları, Meryem'in oğlu İsa'nın ve Dâvud'un diliyle lanetlendiler. Bu böyledir; çünkü onlar sınır tanımazlık, haksızlık, düşmanlık ediyorlardı."},{"n":79,"t":"İşledikleri kötülükten birbirlerini sakındırmıyorlardı. Ne kötü şeydi yapmayı sürdürdükleri!"},{"n":80,"t":"Onlardan birçoğunun, küfre sapanlarla dostluk kurduklarını görürsün. Öz benliklerinin onlar için hazırlayıp sunduğu şey gerçekten çok kötü! Allah, üzerlerine gazap indirmiştir. Azap içinde de onlar sürekli kalacaklardır."},{"n":81,"t":"Eğer Allah'a, peygambere ve ona indirilene inanmış olsalardı, küfre sapanları dostlar edinmezlerdi. Ama onların çokları yoldan sapmışlardır."},{"n":82,"t":"Şu tartışılmaz bir gerçektir ki, insanların iman edenlere en şiddetli düşmanlık duyanlarını, Yahudilerle şirke batanlar bulursun. Şu da tartışılmaz bir gerçektir ki, insanların iman edenlere sevgide en yakın olanlarını \"Biz Hıristiyanlarız\" diyenler bulursun. Bu böyledir. Çünkü o Hıristiyanlar içinde derin araştırmalar yapan keşişler, kendini Allah'a adamış rahipler vardır. Ve onlar, kibre sapmazlar."},{"n":83,"t":"Resule indirileni dinlediklerinde farkına vardıkları gerçekten dolayı gözlerinin yaşla dolup taştığını görürsün. Şöyle derler: \"Ey Rabbimiz, iman ettik. Artık bizi de gerçeğin tanıklarıyla birlikte kaydet.\""},{"n":84,"t":"\"Rabbimizin bizi barışseverler arasına koymasını umup dururken, Allah'a ve Hak'tan bize gelene neden inanmayacakmışız?\""},{"n":85,"t":"Böyle söyledikleri için Allah onları, altlarından ırmaklar akan cennetlerle lütuflandırdı. Sürekli kalıcıdırlar orada. İşte budur güzel davrananların ödülü."},{"n":86,"t":"Küfre sapıp ayetlerimizi yalanlayanlar da cehennemin dostlarıdır."},{"n":87,"t":"Ey iman sahipleri! Allah'ın size helal kıldığı şeylerin temiz ve güzel olanlarını haramlaştırmayın; azıp sınırı aşmayın; Allah azıp sınırı aşanları sevmez."},{"n":88,"t":"Allah'ın size helal ve temiz olarak verdiği rızıklardan yiyin. Kendisine iman ettiğiniz Allah'tan sakının!"},{"n":89,"t":"Allah sizi yeminlerinizdeki boş lakırdıdan ötürü hesaba çekmez, ama bilinçli olarak gerçekleştirdiğiniz yeminlerden sizi sorumlu tutar. Böyle bir yeminin keffâreti, ailenize yedirmekte olduğunuzun orta derecesinden on yoksulu doyurmak, yahut onları giydirmek, yahut da özgürlüğünden yoksun kalmış bir benliği özgürlüğüne kavuşturmaktır. Bunlara imkân bulamayan üç gün oruç tutar. Yemin ettiğinizde yeminlerinizin keffâreti işte budur. Yeminlerinizi koruyun. Allah size ayetlerini böyle açıklar ki şükredebilesiniz."},{"n":90,"t":"Ey iman edenler! Uyuşturucu/şarap, kumar, tapılmak için dikilen taşlar, fal okları şeytan işi birer pisliktik; bunlardan uzak durun ki kurtuluşa eresiniz."},{"n":91,"t":"Şeytan; uyuşturucu ve kumara sokularak aranıza düşmanlık ve şiddetli nefret yerleştirip sizi Allah'ı anmaktan, namazdan/duadan geri çevirmek ister. Artık son veriyorsunuz değil mi?"},{"n":92,"t":"Allah'a itaat edin, resule itaat edin, sakının. Eğer yüz çevirirseniz şunu bilin: Bizim resulümüze düşen sadece apaçık bir tebliğdir."},{"n":93,"t":"İman edip hayra ve barışa yönelik işler yapanlara; bundan böyle korunup iman ederek iyi işler yaptıkları, sonra takvaya sarılıp imanda kemale erdikleri, sonra bir mertebe daha korunup güzellikler sergiledikleri takdirde, daha önce tatmış olduklarından ötürü hiçbir günah yoktur. Allah, güzel düşünüp güzel davrananları sever."},{"n":94,"t":"Ey iman sahipleri! Allah sizi, ellerinizin ve mızraklarınızın erişeceği av türünden bir şeyle mutlaka deneyecektir ki, gözün fark edemediği alanlarda O'ndan kim korkuyor bilsin. Bundan sonra azıp sınırı çiğneyen için korkunç bir azap olacaktır."},{"n":95,"t":"Ey iman sahipleri! İhramda olduğunuz zaman av öldürmeyin. Sizden kim kasten onu öldürürse cezası şudur: Öldürdüğü hayvana denk deve-sığır, davar cinsinden, Kâbe'ye varacak kurbanlık bir hediye ki, içinizden adalet sahibi iki kişi belirleyecektir. Yahut yoksullara yedirme şeklinde bir keffâret, yahut buna denk oruç. Taki yaptığının vebalini tatsın. Allah, geçmişi affetmiştir. Kim bir daha yaparsa, Allah ondan öc alacaktır. Allah çok güçlüdür, öc alıcıdır."},{"n":96,"t":"Hem size hem de yolculara bir geçimlik olarak deniz avı yapmak ve onu yemek size helal kılındı. Fakat ihramda bulunduğunuz sürece karada avlanmak size haram kılındı. Huzurunda toplanacağınız Allah'tan korkun!"},{"n":97,"t":"Allah Kâbe'yi, o saygıya layık evi, o saygıya layık \"ay\"ı, o kurbanlık hediyeleri ve gerdanlıkları insanlar için bir dayanak, bir ayağa kalkış aracı kaldı. Böyle yaptı ki, Allah'ın göklerde olanı da yerde olanı da bildiğini, Allah'ın herşeyi bilici olduğunu siz de bilesiniz."},{"n":98,"t":"Bilin ki Allah, azap ettiğinde çok şiddetli eder. Allah; Gafûr'dur, Rahîm'dir."},{"n":99,"t":"Resule düşen, tebliğden başka bir şey değildir. Allah sizin açığa vurduklarınızı da gizlediklerinizi de bilir."},{"n":100,"t":"De ki: \"Pisin çokluğu seni hayrete düşürse de pisle temiz bir olmaz. O halde, ey akıl ve gönül sahipleri! Allah'tan korkun ki kurtuluşa erebilesiniz.\""},{"n":101,"t":"Ey iman sahipleri! Size açıklandığında canınızı sıkacak şeylerle ilgili soru sormayın. Kur'an indirilmekte iken onları sorarsanız size açıklanır. Allah onlardan vazgeçmiştir. Allah Gafûr'dur, Halîm'dir."},{"n":102,"t":"Sizden önceki bir toplum da onları sormuştu; sonra tutup hepsini inkâr ettiler."},{"n":103,"t":"Allah ne bahîre yapmıştır ne sâibe ne vasîle ne de hâm. Ne var ki küfre sapanlar yalan uydurarak Allah'a iftira ediyorlar ve çokları da akıl erdiremiyorlar."},{"n":104,"t":"Onlara, Allah'ın indirdiğine ve resule gelin dendiğinde şöyle derler: \"Atalarımızı üzerinde bulduğumuz şey bize yeter.\" Peki, ataları hiçbir şey bilmiyor, doğru yolu bulamıyor idiyseler de mi?"},{"n":105,"t":"Ey iman edenler! Siz, kendinizi düzeltmeye bakın. Siz, doğru yolda oldukça sapmış olan size zarar veremez. Tümünüzün dönüşü Allah'adır. O size neler yapıyor olduğunuzu haber verecektir."},{"n":106,"t":"Ey iman edenler! Herhangi birinize ölüm gelip çattığında, vasiyet zamanı aranızdaki tanıklık şöyle olsun: Kendinizden adalet sahibi iki kişi yahut yolculuk etmekte iken ölüm musibeti başınıza geldiyse sizin dışınızdan iki kişi. Bunları namazdan/duadan sonra alıkoyarsınız; kuşkulanırsanız şöyle yemin etsinler: \"Vallahi, yakınlarımız da olsa yeminimizi hiçbir ücret karşılığı satmayacağız, Allah'ın tanıklığını saklamayacağız. Çünkü böyle yaparsak mutlaka günahkârlardan oluruz.\""},{"n":107,"t":"Eğer onların bir günah işledikleri kesinlikle anlaşılırsa o zaman, tercih edilmiş olan bu ikisinin yerine bunların aleyhinde bulundukları taraftan iki kişi geçerek şöyle yemin edeceklerdir: \"Allah şahit olsun ki, bizim tanıklığımız, onların tanıklığından daha doğrudur. Biz hiçbir haksızlık yapmadık. Aksi halde mutlaka zalimlerden olurduk.\""},{"n":108,"t":"İşte bu yol, tanıklığı gereğince yerine getirmelerine, yemin etmelerinden sonra yeminlerinin reddedileceğinden korkmalarına en yarayışlı olandır. Allah'tan sakının ve söylenene kulak verin. Allah, sapıklar topluluğunu doğruya ve güzele kılavuzlamaz."},{"n":109,"t":"Allah, resulleri bir araya getireceği gün şöyle der: \"Size ne cevap verildi?\" Şöyle derler: \"Hiçbir bilgimiz yok. Gaybları en iyi biçimde bilen sensin, sen!\""},{"n":110,"t":"Hani, Allah şöyle demişti: \"Ey Meryem'in oğlu İsa! Senin ve annenin üzerindeki nimetimi hatırla. Seni Ruhulkudüs'le desteklemiştim, beşikte iken ve erginlik çağında insanlarla konuşuyordun. Sana Kitap'ı, hikmeti, Tevrat'ı, İncil'i öğretmiştim. Benim iznimle çamurdan kuş görünümünde bir şey yaratıyor, içine üflüyordun da o benim iznimle kuş oluyordu. Doğuştan körü, abraşı benim iznimle iyileştiriyordun. Benim iznimle ölüleri çıkarıyordun. İsrailoğullarını senden uzak tutmuştum. Hani, sen onlara açık-seçik ayetleri getirdiğinde, küfre sapanları şöyle deyivermişti: \"Açık bir büyüden başka bir şey değil bu.\""},{"n":111,"t":"Havarilere şunu vahyetmiştim: \"Bana ve resulüme iman edin.\" Şöyle demişlerdi: \"İman ettik, sen de tanık ol ki biz, müslümanlarız/Allah'a teslim olanlarız!\""},{"n":112,"t":"Havariler demişlerdi ki: \"Ey Meryem'in oğlu İsa! Rabbin bize gökten bir sofra indirebilir mi?\" İsa dedi ki: \"Eğer müminlerseniz Allah'tan sakının!\""},{"n":113,"t":"Dediler: \"İstiyoruz ki ondan yiyelim, gönüllerimiz tatmin bulsun, senin bize doğruyu söylediğini bilelim ve buna tanıklık edenlerden olalım!\""},{"n":114,"t":"Meryem oğlu İsa şöyle yakardı: \"Allahım, ey Rabbimiz! Üzerimize gökten bir sofra indir de bizim hem öncekilerimize hem sonrakilerimize bir bayram olsun, senden bir mucize olsun. Rızıklandır bizi! Rızık verenlerin en hayırlısı sensin!\""},{"n":115,"t":"Allah dedi ki: \"Ben onu üzerinize indireceğim. Ama bundan sonra küfre sapanınıza öyle bir azapla azap edeceğim ki, âlemlerden hiç kimseye böyle bir azap yapmamışım.\""},{"n":116,"t":"Allah şunu da söyledi: \"Ey Meryem oğlu İsa! Allah'ın yanında beni ve annemi de iki tanrı olarak kabul edin diye insanlara sen mi söyledin?\" İsa dedi: \"Hâşâ! Tespih ederim seni. Hakkım olmayan bir şeyi söylemek benim haddime değildir. Eğer onu söylemişsem sen onu elbette bilirsin. Sen benim içimde olanı bilirsin ama ben senin zatında olanı bilmem. Çünkü sen, evet sen, gaybları çok iyi bilensin!\""},{"n":117,"t":"\"Onlara, senin bana emrettiğin şu sözden başka bir şey söylemedim: 'Benim Rabbim ve sizin de Rabbiniz olan Allah'a kulluk edin.' İçlerinde olduğum sürece üzerlerine tanıktım. Sen beni vefat ettirince üzerlerine yalnız sen gözetleyici oldun. Ve sen zaten her şey üzerinde bir Şehîdsin, bir tanıksın.\""},{"n":118,"t":"\"Onlara azap edersen, onlar senin kullarındır. Ama onları bağışlarsan hiç kuşkusuz, sen tüm gücün sahibi, tüm hikmetlerin sahibisin.\""},{"n":119,"t":"Allah buyurdu: \"Özü-sözü doğru olanlara, doğruluklarının yarar sağlayacağı gün budur. Altlarından ırmaklar akan cennetler var onlar için. Sürekli kalacaklardır orada.\" Allah onlardan razı olmuştur, onlar da Allah'tan razı olmuşlardır. İşte budur büyük kurtuluş."},{"n":120,"t":"Göklerin, yerin ve bunlarda bulunanların mülkü/yönetimi Allah'ındır. O'nun her şeye gücü yeter."}],[{"n":1,"t":"Hamd Allah'adır! O ki gökleri ve yeri yaratmış, karanlıklara ve nura vücut vermiştir. Sonra, gerçeği örtenler bunları Rablerine denk tutuyorlar."},{"n":2,"t":"Sizi bir balçıktan yaratmış olan O'dur. Sonra hüküm verip bir süre belirlemiştir. Belirlenmiş başka bir süre de onun katındadır. Bütün bunlardan sonra siz hâlâ kuşkulanıp duruyorsunuz."},{"n":3,"t":"O, göklerde de Allah'tır, yerde de. O, sizin iç dünyanızı da bilir, açığa vurduklarınızı da. Neler kazanmakta olduğunuzu da bilir O!"},{"n":4,"t":"Onlara Rablerinin ayetlerinden bir ayet gelir gelmez, ondan hemen yüz çeviriyorlardı."},{"n":5,"t":"Böylece hakkı, kendilerine geldiği anda yalanladılar. Fakat yakında onlara, alay etmekte oldukları şeyin haberleri gelecektir."},{"n":6,"t":"Kendilerinden önce nice yurt ve medeniyeti yerle bir ettiğimizi görmediler mi? Biz o yurtlara yeryüzünde size vermediğimiz imkânları vermiş, üzerlerine gök bereketini bol bol indirmiş, nehirleri altlarından akar hale getirmiştik. Derken, onları kendi günahlarıyla helâk ettik ve arkalarından başka bir nesil oluşturduk."},{"n":7,"t":"Eğer biz sana parşömen üzerine yazılı bir kitap göndermiş olsaydık, onlar da ona elleriyle dokunmuş olsalardı, o küfre batmışlar, hiç kuşkusuz şöyle deyivereceklerdi: \"Bu, apaçık bir büyüden başka şey değildir.\""},{"n":8,"t":"Şunu da söylediler: \"Bu peygambere bir melek indirilseydi ya!\" Eğer böyle bir melek indirmiş olsaydık iş mutlaka bitirilmiş olurdu da kendilerine göz bile açtırılmazdı."},{"n":9,"t":"Eğer o peygamberi bir melek kılsaydık kuşkusuz onu bir er kişi yapacaktık ve içine yuvalandıkları kuşku ve karmaşayı onların üzerlerine giydirmiş olacaktık."},{"n":10,"t":"Yemin olsun ki, senden önceki resullerle de alay edildi; fakat eğlence konusu yaptıkları şey, o maskaralığı sergileyenleri kıskıvrak sarıverdi."},{"n":11,"t":"Şunu söyle: Dolaşın yeryüzünde de bakın nasıl olmuş gerçeği yalanlayanların sonu!"},{"n":12,"t":"Sor: \"Kimindir gökler ve yer?\" Cevap ver: \"Allah'ındır.\" O Allah ki, rahmeti öz benliği üzerine yazmıştır. O sizi, varlığında hiç kuşku bulunmayan kıyamet gününde bir araya mutlaka toplayacaktır. Benliklerini hüsrana yuvarlamış kişiler var ya, onlar iman etmezler."},{"n":13,"t":"Gecenin ve gündüzün içinde yer alan her şey O'nundur. O, Semî'dir, her şeyi duyar; Alîm'dir, her şeyi bilir."},{"n":14,"t":"De ki: \"Göklerin ve yerin Fâtır'ı olan o yaratıcıdan, o yedirip doyuran ama kendisi yedirilip beslenmeyen Allah'tan başkasını mı velî edineyim?\" De ki: \"Bana, İslam'ı/Allah'a teslim olmayı seçenlerin ilki olmam emredildi.\" Ve sakın şirke sapanlardan olma!"},{"n":15,"t":"Şunu da söyle: \"Rabbime isyan edersem büyük bir günün azabından korkarım ben.\""},{"n":16,"t":"Kendisinden azap uzaklaştırılana o gün rahmet etmiştir. İşte açık kurtuluş budur."},{"n":17,"t":"Allah sana bir keder dokundurursa, onu O'ndan başka açacak yoktur. Eğer sana bir hayır dokundurursa, O, her şey üzerinde güç sahibidir."},{"n":18,"t":"Ve kulları üzerinde hüküm ve egemenlik sahibi Kaahir'dir O. Tüm hikmetlerin kaynağıdır O. Her şeyden haberdardır."},{"n":19,"t":"Sor: \"Tanıklık bakımından hangi şey daha büyüktür?\" De ki: \"Benimle sizin aranızda Allah tanıktır. Bu Kur'an bana vahyolundu ki, onunla sizi ve ulaştığı herkesi uyarayım. Siz gerçekten Allah'ın yanında başka ilahların bulunduğuna tanıklık ediyor musunuz?\" De ki: \"Ben buna tanıklık etmiyorum.\" De ki: \"O, sadece tek bir tanrıdır! Ve ben, sizin ortak tuttuğunuz şeylerden uzağım!\""},{"n":20,"t":"O kendilerine kitap verdiklerimiz var ya, onu, öz oğullarını tanıdıkları gibi tanıyıp bilirler. Ama öz benliklerini hüsrana uğratan bunlar, iman etmezler."},{"n":21,"t":"Yalan düzerek Allah'a iftira eden yahut O'nun ayetlerini yalanlayandan daha zalim kim vardır? Şu da bir gerçek ki, zalimler asla kurtulamazlar!"},{"n":22,"t":"Gün olur, onları bir araya toplayıp haşrederiz. Sonra, şirke batanlara sorarız: \"Nerededir o bir şey zannedip durduğunuz ortaklarınız?\""},{"n":23,"t":"Sonunda şunu söylemekten başka bahaneleri kalmaz: \"Rabbimiz Allah'a yemin olsun ki, biz, ortak koşanlar değildik.\""},{"n":24,"t":"Bak da gör, nasıl yalan söylediler öz benliklerine karşı! Ve iftira için kullandıkları şeyler, onları bırakıp kayboldu."},{"n":25,"t":"İçlerinden sana kulak verenler vardır; ama biz onu gereğince anlamamaları için kalplerine kılıflar geçirmiş, kulaklarına bir ağırlık koymuşuzdur. Tüm mucizeleri görseler de onlara inanmazlar. Nihayet sana gelip seninle çekişerek söyle derler küfre sapanlar: \"Bu, eskilerin masallarından başka bir şey değildir.\""},{"n":26,"t":"Hem ondan alıkoyarlar hem ondan uzaklaşırlar. Öz benliklerinden başkasını helâk etmiyorlar. Ama farkında değiller."},{"n":27,"t":"Ah bir görsen, ateşin başında durdurulup da şöyle dediklerini: \"Ne olurdu, geri gönderilsek, Rabbimizin ayetlerini yalanlamasak ve müminlerden oluversek.\""},{"n":28,"t":"İşin doğrusu şu: Önceden gizlemekte oldukları karşılarına dikildi. Geri gönderilselerdi yasaklandıkları şeyi mutlaka yineleyeceklerdi. Doğrusu, onlar, tam yalancıdırlar."},{"n":29,"t":"Dediler ki: \"Şu dünya hayatımızdan başkası yok. Biz diriltilecek de değiliz.\""},{"n":30,"t":"Rableri huzurunda durdurulduklarını bir görsen! Sordu: \"Gerçek değil miymiş bu?\" Dediler: \"Rabbimize yemin olsun ki, gerçekmiş.\" Dedi: \"O halde, küfre sapmış olmanızdan dolayı tadın azabı.\""},{"n":31,"t":"Allah'ın huzuruna varmayı yalanlayanlar, gerçekten hüsrana uğramıştır. Sonunda o saat ansızın kendilerine gelip çatınca, sırtlarında günahlarını taşır bir halde şöyle demişlerdir: \"Dünya hayatında düşdüğümüz aşırılıklardan dolayı vay hasretimize!\" Dikkat edin! Ne kötü şeylerdir taşıyıp durdukları."},{"n":32,"t":"Şu iğreti, basit hayat bir oyun ve eğlenceden başka şey değildir. Sakınıp korunanlar için âhiret yurdu elbette ki daha iyidir. Hâlâ aklınızı işletemeyecek misiniz?"},{"n":33,"t":"Söylediklerinin seni kederlendirdiğini çok iyi biliyoruz. Gerçek şu ki, onlar seni yalanlamıyorlar; o zalimler Allah'ın ayetlerine karşı direnmekteler."},{"n":34,"t":"Yemin olsun ki, senden önce de resuller yalanlanmış ama yalanlanmalarına, eziyet görmelerine sabretmişlerdi. Nihayet yardımımız onlara ulaştı. Allah'ın kelimelerini değiştirecek hiçbir kuvvet yoktur. Yemin olsun, elçi olarak gönderilenlerin haberinden bir kısmı sana da gelmiştir."},{"n":35,"t":"Eğer yüz çevirip gitmeleri sana ağır geldiyse, haydi gücün yetiyorsa, yerin içinde bir delik yahut gökte bir merdiven ara da onlara bir mucize getir. Allah dileseydi onları doğru ve güzelde birleştirirdi. Artık cahillerden olma."},{"n":36,"t":"Ancak gereğince dinleyenler çağrıya cevap verir. Ölülere gelince, Allah onları diriltecektir, sonra O'na döndürülecekler."},{"n":37,"t":"Dediler ki: \"Ona Rabbinden bir mucize indirilseydi ya!\" De ki: \"Kuşkusuz, Allah bir mucize indirmeye Kaadir'dir. Fakat çokları bilmiyorlar.\""},{"n":38,"t":"Yeryüzünde debelenen hiçbir canlı, iki kanadıyla uçan hiçbir kuş istisna olmamak üzere hepsi sizin gibi ümmetlerdir. Biz bu Kitap'ta, herhangi birşeyi ne eksik bıraktık ne fazla yaptık. Onlar, sonunda Rableri önünde haşredilirler."},{"n":39,"t":"Bizim ayetlerimizi yalanlayanlar, karanlıklara gömülmüş sağır ve dilsizlerdir. Allah, dilediği/dileyen kişiyi şaşırtır, dilediğini/dileyeni de dosdoğru yol üzerine koyar."},{"n":40,"t":"De ki: \"Bir düşünün bakalım! Allah'ın azabı yakanıza yapışsa yahut o saat gelip çatsa, Allah'tan başkasına mı yakarırsınız? Doğru sözlü iseniz söyleyin!\""},{"n":41,"t":"Hayır, yalnız O'na yakarırsınız da O dilerse yakındığınız belayı uzaklaştırır. Ve siz, ortak koştuklarınızı unutuverirsiniz."},{"n":42,"t":"Andolsun ki, senden önce de ümmetlere elçiler göndermiştik. O ümmetleri, bize yaklaşıp sığınsınlar diye zorluklar ve darlıklarla yakalamıştık."},{"n":43,"t":"Zorluğumuz kendilerine gelip çattığında bir sığınabilselerdi! Ne yazık ki kalpleri katılaştı; şeytan, yapmakta olduklarını onlara süslü-püslü gösterdi."},{"n":44,"t":"Öğütlenmeye çağırıldıkları şeyi unutunca, her şeyin kapılarını üzerlerine açıverdik. Nihayet, kendilerine verilenle sevinç şımarıklığına daldıkları bir sırada, ansızın onları yakaladık. Tüm ümitlerini bir anda yitirdiler."},{"n":45,"t":"Böylece, zulme saplanan topluluğun kökü kesilmişti; hamt olsun âlemlerin Rabbi'ne!"},{"n":46,"t":"De ki: \"Düşünün bakalım; Allah, işitme gücünüzü, gözlerinizi alsa, kalpleriniz üzerine mühür bassa, Allah'tan başka hangi ilah onları size geri verecek?\" Bak nasıl türlü türlü açıklıyoruz ayetleri, yine de yüz çeviriyorlar!"},{"n":47,"t":"Şunu da söyle: \"Düşünün bakalım; Allah'ın azabı size ansızın, açıktan geliverse, zalimler topluluğundan başkası mı helâk edilecek?\""},{"n":48,"t":"Biz o gönderilen elçileri, müjdeciler ve uyarıcılar olmaktan öte bir şey için göndermiyoruz. İman edip hayrı ve barışı yerleştirenlere korku yoktur. Tasalanmayacaklardır onlar."},{"n":49,"t":"Ayetlerimizi yalanlayanlara gelince, fenalığa bulaşmaları yüzünden kendilerine azap dokunacaktır."},{"n":50,"t":"Onlara şunu söyle: \"Ben size Allah'ın hazineleri yanımdadır demiyorum. Gaybı da bilmem ben! Size ben bir meleğim de demiyorum. Yalnız bana vahyedilene uyarım ben!\" Sor onlara: \"Körle gören bir olur mu? Hâlâ düşünmüyor musunuz?\""},{"n":51,"t":"Rablerinin huzurunda haşredileceklerinden korkanları, o vahiy ile uyar ki korunabilsinler. Onların O'ndan başka ne bir dostu vardır ne de şefaatçısı."},{"n":52,"t":"Sabah akşam, yüzünü isteyerek Rablerine yalvarıp yakaranları kovma! Onların hesabından bir şey sana ait olmadığı gibi, senin hesabından bir şey de onlara ait değildir. O halde onları kovarsan zalimlerden olursun."},{"n":53,"t":"Biz böylece onların bir kısmını diğer bir kısmıyla imtihana çektik ki, şunu söylesinler: \"Allah aramızdan şunlara mı lütufta bulundu?\" Allah şükredenleri daha iyi bilmiyor mu?"},{"n":54,"t":"Ayetlerimize iman edenler sana geldiğinde şöyle söyle: \"Selam size! Rabbiniz, benliği üzerine rahmeti yazmıştır. İçinizden her kim bilgisizlikle bir kötülük işler de ardından tövbe edip halini düzeltirse, hiç kuşkusuz, Allah çok affedici, çok merhametlidir.\""},{"n":55,"t":"İşte biz, ayetlerimizi bu şekilde ayrıntılı kılıyoruz ki, günaha sapmışların yolu açık-seçik ortaya çıksın/günaha sapmışların yolunu açık-seçik göresin!"},{"n":56,"t":"De ki: \"Ben, Allah'ı bırakıp da yakardıklarınıza kulluk etmekten yasaklandım!\" De ki: \"Sizin keyiflerinize uymam! Çünkü bunu yaparsam sapıtmış olurum, doğruyu ve güzeli bulanlardan olmam.\""},{"n":57,"t":"De ki: \"Ben Rabbimden gelen bir beyyine üzerindeyim. Ama siz onu yalanladınız. Acele istediğiniz şey benim yanımda değil. Hüküm yalnız ve yalnız Allah'ındır. Hakkı o anlatır. Ayırt edip çözüm getirenlerin en hayırlısı O'dur.\""},{"n":58,"t":"Şunu da söyle: \"Acele istediğiniz şey benim yanımda olsaydı, benimse sizin aranızdaki iş çoktan bitirilmiş olurdu. Zalimleri, Allah daha iyi bilir.\""},{"n":59,"t":"Gaybın anahtarları O'nun yanındadır; onları O'ndan başkası bilmez. O, karada ve denizde olanı da bilir. O'nun bilgisi dışında bir yaprak bile düşmez. Toprağın karanlıklarındaki bir dâne, yaş ve kuru her şey apaçık bir Kitap'ın içindedir."},{"n":60,"t":"O, odur ki, geceleyin sizi öldürür. Gün boyunca neler yapıp neler kazandığınızı bilir. Sonra, belirlenmiş süre işletilip tamamlansın diye, gün içinde sizi diriltir. Nihayet O'nadır dönüşünüz. Sonra, yapıp ettiklerinizi size haber verecektir."},{"n":61,"t":"Kulları üzerinde egemenlik sahibi Kaahir'dir O. Üzerinize koruyucular gönderir. Nihayet ölüm birinize geldiğinde, elçilerimiz onu vefat ettirirler. Ne vaktinden önce iş yaparlar onlar ne de vaktinden sonra."},{"n":62,"t":"Nihayet onlar gerçek Mevlâ'ları olan Allah'a götürülürler. Gözünüzü açın! Hüküm yalnız O'nundur. Ve hesap görenlerin en süratlisi de O'dur."},{"n":63,"t":"Şunu sor: \"Bizi bu durumdan kurtarırsa andolsun şükredenlerden olacağız' diye boyun büküp ürpererek O'na yakardığınızda, karanın ve denizin karanlıklarından sizi kim kurtarıyor?\""},{"n":64,"t":"De ki: \"Ondan da tüm sıkıntılardan da sizi Allah kurtarıyor; sonra siz O'na ortak koşuyorsunuz.\""},{"n":65,"t":"De ki: \"O size, üstünüzden yahut ayaklarınızın altından bir azap göndermeye yahut sizi fırka fırka birbirinize düşürerek/fırkalara bölüp içinden çıkılmaz durumlara düşürerek/fırkaları elbise gibi size giydirerek kiminizin şiddetini kiminize tattırmaya Kaadir'dir.\" Bak nasıl sıralıyoruz ayetleri, iyice kavrayabilsinler diye."},{"n":66,"t":"O, hak olduğu halde senin toplumun onu yalanladı. De ki: \"Ben size vekil değilim.\""},{"n":67,"t":"Her haberin gerçekleşeceği bir zaman/mekân vardır. Yakında bileceksiniz."},{"n":68,"t":"Ayetlerimiz hakkında lakırdıya dalanları gördüğünde, onlar başka bir söze dalıncaya değin onlardan yüz çevir. Eğer şeytan sana unutturursa, hatırladıktan sonra o zalimler topluluğu ile oturma."},{"n":69,"t":"Allah'tan korkanlarla onların hesabından bir şey yoktur ama yine de bir hatırlatma olmalı. Belki sakınırlar."},{"n":70,"t":"Dinlerini oyun ve eğlence haline getirmiş, dünya hayatı kendilerini aldatmış olanları bırak da o Kur'an ile şunu hatırlat: Bir kişi, kendi elinin üretip kazandığına teslim edilirse onun, Allah dışında ne bir dostu kalır ne de şefaatçısı. Her türlü fidyeyi verse de ondan kabul edilmez. İşte bunlar, kazandıklarına teslim edilmişlerdir. Nankörlük ettiklerinden ötürü onlar için kaynar sudan bir içki ve korkunç bir azap vardır."},{"n":71,"t":"De ki: \"Allah'ın berisinden, bize yarar da zarar da veremeyecek şeylere mi yakaralım? Allah bize kılavuzluk ettikten sonra ökçelerimiz üstüne geri mi döndürelim? O kişi gibi, şeytanlar kendisini ayartıp yeryüzünde şaşkın dolaşır hale getirmişlerdir. Oysaki onun, \"Bize gel!\" diye doğruya ve güzele çağıran arkadaşları vardır.\" De ki: \"Allah'ın kılavuzluğudur gerçek kılavuzluk. Âlemlerin Rabbi Allah'a teslim olmakla emrolunduk biz.\""},{"n":72,"t":"Ve \"Namazı kılın/duayı yerine getirin, O'ndan sakının!\" diye emrolunduk. Huzurunda haşrolunacağınız O'dur."},{"n":73,"t":"Gökleri ve yeri hak olarak yaratan da O'dur. \"Ol!\" dediği gün, hemen oluverir. Sözü haktır O'nun. Sûra üfleneceği gün de mülk/yönetim O'nundur. Âlim'dir, görünmeyeni de görüneni de bilen O'dur. O'dur Hakîm, O'dur Habîr."},{"n":74,"t":"İbrahim, babası Âzer'e şöyle demişti: \"Putları tanrılar mı ediniyorsun? Seni de toplumunu da açık bir sapıklık içinde görüyorum.\""},{"n":75,"t":"Böylece biz İbrahim'e göklerin ve yerin melekûtunu gösteriyorduk ki, gerçeği görüp bilerek inananlardan olsun."},{"n":76,"t":"Gece onun üstünü örtünce bir yıldız gördü de \"İşte Rabbim bu!\" dedi. Yıldız battığında ise \"Batıp gidenleri sevmem!\" diye konuştu."},{"n":77,"t":"Ay'ı doğar halde görünce, \"Rabbim bu!\" dedi. O batınca da şöyle konuştu: \"Eğer Rabbim bana kılavuzluk etmeseydi sapıtan topluluktan olurdum.\""},{"n":78,"t":"Nihayet Güneş'in doğmakta olduğunu gördüğünde, \"Benim Rabbim bu, bu daha büyük!\" dedi. O da batıp gidince şöyle seslendi: \"Ortak koştuğunuz şeylerden uzağım ben.\""},{"n":79,"t":"\"Ben bir hanîf olarak yüzümü gökleri ve yeri yaratana döndürdüm. Müşriklerden değilim ben.\""},{"n":80,"t":"Toplumu ona karşı çıkıp kanıt getirmeye kalkıştı. O dedi ki: \"Allah hakkında benimle çekişiyor musunuz? Beni doğru yola O iletti. O'na ortak koştuğunuz şeylerden korkmam. Rabbimin dilediği dışında hiçbir şey olmaz. Rabbim bilgice herşeyi çepeçevre kuşatmıştır. Hâlâ öğüt almayacak mısınız?\""},{"n":81,"t":"\"Hem siz, hakkında size hiçbir kanıt indirmediği şeyleri Allah'a ortak koştuğunuz halde korkmuyorsunuz da ben, ortak tuttuğunuz şeylerden nasıl korkarım!\" Şimdi, eğer biliyorsanız, iki gruptan hangisi güvende olmaya/güvenilmeye daha layıktır?"},{"n":82,"t":"İman edip de imanlarını herhangi bir zulümle kirletmeyenler var ya, güvende olma/güvenilir olma işte onların hakkıdır; doğruyu ve güzeli yakalayanlar da onlardır."},{"n":83,"t":"İşte bunlar, kavmine karşı İbrahim'e verdiğimiz kanıtlardır. Dilediklerimizi derece derece yükseltiriz. Senin Rabbin Hakîm'dir, Alîm'dir."},{"n":84,"t":"Biz ona İshak'ı ve Yakub'u hediye ettik. Hepsini doğruya ve güzele kılavuzladık. Daha önce Nûh'a ve onun soyundan olan Dâvud'a, Süleyman'a, Eyyûb'e, Yûsuf'a, Mûsa'ya, Hârun'a da kılavuzluk etmiştik. Güzel düşünüp güzel davrananları böyle ödüllendiririz biz."},{"n":85,"t":"Zekeriyya, Yahya, İsa ve İlyas... Hepsi iyilik ve barış için çalışanlardandı."},{"n":86,"t":"İsmail, Elysa', Yûnus ve Lût... Hepsini âlemlere üstün kıldık."},{"n":87,"t":"Atalarından, soylarından, kardeşlerinden bir kısmını da... Onları seçtik ve onları dosdoğru bir yola kılavuzladık."},{"n":88,"t":"Allah'ın yol göstermesidir bu. Kullarından dilediğini bununla iletir iyiye ve güzele. Eğer onlar şirke bulaşsalardı yapıp ettikleri kendilerine yararsız hale gelirdi."},{"n":89,"t":"İşte bunlardır kendilerine kitap, hükmetme gücü ve peygamberlik verdiklerimiz. Şimdi şu insanlar bütün bunları inkâr ederlerse biz, bunları inkâr etmeyecek bir topluluğu onlara vekil ederiz."},{"n":90,"t":"İşte böyleleri, Allah'ın yol gösterdiği kimselerdir. Sen de onların yolunu izle ve şöyle söyle: \"Ben şu yaptığıma karşılık sizden bir ücret istemiyorum. O sadece âlemlere bir öğüttür.\""},{"n":91,"t":"Allah'ı, kadrine/şanına yaraşır şekilde tanıyamadılar. Çünkü, \"Allah, insana hiçbir şey vahyetmemiştir.\" dediler. De ki \"Mûsa'nın insanlara bir ışık, bir kılavuz olarak getirdiği kitabı kim indirdi? Siz o kitabı birtakım parşömenler yapıp ortaya sürüyorsunuz, birçoğunu da saklıyorsunuz. Size, sizin de atalarınızın da bilmediği şeyler öğretildi.\" \"Allah!\" de, sonra bırak onları saplandıkları batakta oynayadursunlar."},{"n":92,"t":"Bu da bizim, kentlerin/medeniyetlerin anasını uyarman için indirdiğimiz bir kitap. Kutsal-bereketli, kendinden öncekini doğrulayıcı. Âhirete inananlar, ona da inanırlar ve onlar namazlarına/dualarına devam ederler."},{"n":93,"t":"Yalan düzüp Allah'a iftira eden veya kendine bir şey vahyedilmediği halde \"Bana vahyedildi\" diyen kişi ile, \"Allah'ın ayet indirdiği gibi ben de indireceğim\" diyen kimseden daha zalim kim vardır! Bir görsen o zalimleri ölüm dalgaları içindeyken. Melekler ellerini uzatmış, \"Çıkarın canlarınızı!\" diye! Bugün zillet azabıyla cezalandırılacaksınız; çünkü Allah'a karşı gerçek dışı şeyler söylüyorsunuz ve çünkü O'nun ayetlerine karşı büyüklük taslıyordunuz."},{"n":94,"t":"Yemin olsun, sizi ilk yarattığımızdaki gibi yapayalnız/teker teker bize geldiniz. Size verip hayaline daldırdığımız şeyleri de sırtlarınızın arkasında bıraktınız. Sizinle ilgili hususlarda ortaklar olduklarını sandığınız şefaatçılarınızı da yanınızda görmüyorsunuz. Yemin olsun, koptu aranızdaki tüm bağlar ve uzaklaşıp kayboldu yanınızdan o bir şey sandıklarınız."},{"n":95,"t":"Hiç kuşkusuz, Allah'tır Fâlık olan/dâneyi yaran, çekirdeği patlatan. Ölüden diri çıkarır O; diriden ölüyü çıkaran da O'dur! İşte budur Allah! Peki nasıl ters bir yöne çevriliyorsunuz?"},{"n":96,"t":"Şafağı yarıp sabahı ortaya çıkaran/Fâlık O'dur! Geceyi dinlenme zamanı yaptı; Güneş'i ve Ay'ı hesap aracı. İşte budur ölçülendirmesi o Azîz'in, o Alîm'in!"},{"n":97,"t":"Karanın ve denizin karanlıklarında, kendileriyle yol bulmanız için yıldızları hizmetinize veren O'dur! Bilgiden nasipli bir topluluk için ayetleri gerçekten ayrıntılı kılmışızdır."},{"n":98,"t":"Sizi bir tek canlıdan vücuda getiren O'dur! Bu oluşumda bir karar kılma yeri var, bir de emanet olarak kalma yeri. İyice araştırıp kavrayan bir topluluk için ayetleri biz tam bir biçimde ayrıntılı kıldık."},{"n":99,"t":"Size gökten su indiren de O'dur! Biz o suyla her şeyin bitkisini çıkardık. Ondan da bir yeşillik çıkardık. O yeşillikten birbiri üzerine binmiş dâneler çıkardık. Hurma ağacının da tomurcuğundan sarkan salkımlar, üzümlerden bağlar, zeytin, nar çıkardık. Birbirine benzeyeni var, benzemeyeni var. Meyve verdiğinde ve meyveler olgunlaştığında bir bakın onun ürününe! Bu size gösterilenlerde, iman eden bir topluluk için, çok ibret vardır!"},{"n":100,"t":"Allah'a bir de cinleri/gözle görülmeyen yaratıkları ortak koştular. Oysaki, onları O yaratmıştır. Bilgisizce O'na oğullar ve kızlar isnat etme saçmalığını gösterdiler. Şanı yücedir O'nun! Onların nitelemelerinin ötesindedir O!"},{"n":101,"t":"Gökleri ve yeri yaratıp donatan Bedî' O'dur! Nasıl çocuğu olur O'nun, kendisinin bir eşi olmadı ki! Her şeyi O yarattı ve her şeyi en iyi şekilde bilen de O'dur!"},{"n":102,"t":"Rabbiniz Allah işte budur! İlah yok O'ndan başka. Her şeyin yaratıcısıdır, Haalik'tir O. O'na kulluk/ibadet edin! O her şeye Vekîl'dir."},{"n":103,"t":"Gözler onu fark edip kavrayamaz. Oysaki O, gözleri görür/bilir. O Latîf'tir, lütfu çok olduğu halde kendisi görülemez; Habîr'dir, her şeyden haberdardır."},{"n":104,"t":"Gerçek şu ki, size Rabbinizden gönül gözleri gelmiştir. Kim görürse kendisi yararına, kim körlük ederse kendisi zararına... Ben sizin üzerinize bekçi değilim."},{"n":105,"t":"Ayetleri bu şekilde, çeşitli başlıklarla veriyoruz ki, \"Sen ders aldın!\" desinler, biz de ilimden nasiplenen bir toplum için onu iyice açıklayalım."},{"n":106,"t":"Rabbinden sana vahyedilene uy! O'ndan başka ilah yoktur. Müşriklerden yüz çevir!"},{"n":107,"t":"Allah dileseydi, şirke batmazlardı. Biz seni onlar üzerine bekçi yapmadık. Sen onlara vekil de değilsin."},{"n":108,"t":"Allah'ın berisinden birilerine niyazda bulunanlara/Allah dışında birileri için çağrı yapanlara/onların, Allah dışında yakardıklarına sövmeyin. Yoksa onlar da düşmanlıkla ve bilgisizce Allah'a söverler. Biz her ümmete yaptığı işi bu şekilde süslü gösterdik. Sonra hepsinin dönüşü Rablerinedir. O, onlara, yapmakta olduklarını haber verecektir."},{"n":109,"t":"Tüm yeminleriyle Allah'a yemin ettiler ki, eğer kendilerine bir mucize gelirse ona mutlaka inanacaklar. Söyle onlara: \"Mucizeler ancak Allah'ın katındadır.\" Mucize geldiğinde de iman etmeyeceklerini anlamıyor musunuz?"},{"n":110,"t":"Biz onların gönüllerini ve gözlerini ters çeviririz, ilk seferinde buna iman etmedikleri gibi bırakırız kendilerini de azgınlıkları içinde körü körüne bocalar dururlar."},{"n":111,"t":"Eğer biz onlara melekleri indirseydik, ölüler kendileriyle konuşsaydı ve herşeyi toplayıp karşılarına dikseydik, Allah'ın dilemesi dışında, yine de inanmazlardı. Ne var ki, çokları cehalet sergiliyorlar."},{"n":112,"t":"İşte böyle, biz peygambere insan ve cin şeytanlarını düşman yaptık. Bunlar aldatmak için birbirlerine lafın yaldızlısını fısıldarlar. Rabbin dileseydi onu yapamazlardı. Bırak onları, düzdükleri iftiralarla başbaşa kalsınlar;"},{"n":113,"t":"Ki âhirete inanmayanların gönülleri ona ısınsın, ondan hoşlansınlar, elde ettikleri şeylere sahip olmaya devam etsinler."},{"n":114,"t":"Allah size Kitap'ı ayrıntılı kılınmış bir halde indirmişken, Allah'ın dışında bir hakem mi arayayım? Kendilerine Kitap verdiklerimiz, onun, Rabbinden hak olarak indirildiğini biliyorlar. Sakın kuşkuya düşenlerden olma."},{"n":115,"t":"Rabbinin sözü hem doğruluk hem de adalet bakımından tamamlanmıştır. O'nun sözlerini değiştirecek hiçbir kuvvet yoktur. En iyi işiten, en iyi bilendir O."},{"n":116,"t":"Yeryüzündeki insanların çoğunluğuna uyarsan seni Allah yolundan saptırırlar. Sadece sanıya uyarlar onlar ve sadece saçmalarlar."},{"n":117,"t":"Kendi yolundan kimin saptığını en iyi senin Rabbin bilir. Hidayete ermiş olanları en iyi bilen de O'dur."},{"n":118,"t":"O halde, O'nun ayetlerine inanıyorsanız, üzerine Allah'ın adı anılmış olanlardan yiyin."},{"n":119,"t":"Size ne oluyor da üzerine Allah'ın adı anılmış olanlardan yemiyorsunuz? Zorda kalışınız dışında üzerinize haram kıldığını bizzat kendisi size ayrıntılı olarak açıklamıştır. Birçokları ilimsiz bir biçimde kendi keyiflerine uyarak halkı şaşırtıyorlar. Hiç kuşkusuz, senin Rabbin sınır tanımaz azgınları çok iyi bilmektedir."},{"n":120,"t":"Günahın açığını da bırakın, gizlisini de. Günah kazananlar yapıp ettiklerinin karşılığını yakında göreceklerdir."},{"n":121,"t":"Üzerine Allah'ın adı anılmayanlardan yemeyin. Böyle bir şey tam bir yoldan çıkıştır. Şeytanlar kendi evliyasına/dost ve destekçilerine sizinle mücadele etmeleri için elbetteki vahiy gönderirler. O şeytan evliyasına boyun eğerseniz kesinlikle müşrikler oldunuz demektir."},{"n":122,"t":"Bir ölü iken kendisine hayat verdiğimiz, insanlar içinde yürümesi için kendisine bir ışık tuttuğumuz kişinin durumu, karanlıklar içinde kalmış, bir türlü ondan çıkamayan kişininki gibi olur mu? İşte böyle! Küfre sapanlara, yapmakta oldukları süslü-püslü gösterilmiştir."},{"n":123,"t":"Biz bu şekilde her kentte/her medeniyette kodamanları, o kent ve medeniyetin suçluları yaptık ki, orada oyunlar tezgâhlayıp tuzaklar kursunlar. Aslında onlar öz benliklerinden başkasına oyun oynamıyorlar ama farkında değildir."},{"n":124,"t":"Onlara bir ayet geldiğinde şöyle demişlerdi: \"Allah resullerine verilenin tıpkısı bize de verilmedikçe asla inanmayacağız.\" Allah resullük görevini nereye vereceğini daha iyi bilir. Suç işleyenlere, oynadıkları oyunlar yüzünden Allah katında bir küçüklük ve şiddetli bir azap öngörülmüştür."},{"n":125,"t":"Allah, iyiye ve güzele götürmek istediğinin göğsünü İslam'a açar. Saptırmak dilediğinin de göğsünü öylesine daraltıp tıkar ki, o, göğe yükseliyormuş gibi olur. Allah, iman etmeyenler üzerine pisliği işte böyle atıverir."},{"n":126,"t":"Rabbinin yolu işte budur; dosdoğru, kıvamında... Biz öğüt alan bir topluluğa ayetleri ayrıntılı bir biçimde açıkladık."},{"n":127,"t":"Rableri katındaki huzur ve esenlik yurdu onlarındır. İşler oldukları ameller yüzünden O, onların Velî'si oluvermiştir."},{"n":128,"t":"Gün olur şöyle diyerek onları huzurunda toplar: \"Ey cinler/görünmez varlıklar topluluğu! Şu insanlara gerçekten çok ettiniz/insanların birçoğuna göz diktiniz.\" Onların insanlardan olan dostları şöyle derler: \"Rabbimiz, kimimiz kimimizden yararlanmıştı. Bizim için belirlediğin sürenin sonuna geldik.\" Buyurur ki: \"Barınağınız ateştir. Allah'ın dilediği zamanlar hariç orada süreklisiniz.\" Senin Rabbin Hakîm'dir, Alîm'dir."},{"n":129,"t":"İşte biz, zalimlerin bir kısmını bir kısmına, kazanır oldukları şeyler yüzünden bu şekilde dost/yardımcı/yönetici/önder yaparız."},{"n":130,"t":"Ey cinler ve insanlar topluluğu! İçinizden, size ayetlerimi anlatan ve şu gününüzle yüz yüze geleceğiniz hususunda sizi uyaran resuller gelmedi mi? \"Kendi aleyhimize tanıklık ettik.\" dediler. İğreti hayat onları aldattı da küfre saptıklarına ilişkin, öz benlikleri aleyhinde tanıklık ettiler."},{"n":131,"t":"Sebep şudur: Rabbin, halkı habersiz bir haldeyken kentleri helâk edici değildir."},{"n":132,"t":"Her birinin, yapıp ettiklerinden kaynaklanan dereceleri vardır. Rabbin onların işlediklerinden gafil değildir."},{"n":133,"t":"Senin o Ganî Rabbin rahmet sahibidir. Dilerse sizi ortadan kaldırır ve sizi bir başka topluluğun soyundan vücuda getirdiği gibi, ardınızdan da dilediğini sizin yerinize getirir."},{"n":134,"t":"Size vaat edilen şeyler kesinlikle meydana gelecektir. Siz engel olamazsınız."},{"n":135,"t":"Ey toplumum! Yapabileceğinizi yapın. Ben de yapıp ediyorum. Yakında yurdun sonunun kime ait olacağını bileceksiniz. Gerçek olan şu ki, zalimler kurtulamaycaklardır."},{"n":136,"t":"Kendi döllendirip yaydığı ekinden ve hayvanlardan Allah'a bir pay ayırdılar da kendi zanlarınca şöyle dediler: \"Bu Allah için, bu da ortaklarımız için.\" ortakları için olan Allah'a ulaşmaz. Ama Allah için olan, ortaklarına ulaşıyor. Ne kötü hüküm veriyorlar!"},{"n":137,"t":"Aynen bunun gibi, müşriklerden birçoğuna, Allah'a ortak koştukları kişiler, öz evlatlarını öldürmeyi güzel göstermiştir ki, hem onları yok etsinler hem de dinlerini onlar aleyhine karmakarışık hale getirsinler. Allah dileseydi bunu yapamazlardı. O halde onları, düzdükleri iftiralarla baş başa bırak."},{"n":138,"t":"Kendi kuruntularına uygun olarak şöyle dediler: \"Şunlar, dokunulmaz hayvanlar ve ekinlerdir. Bizim dilediğimizden başkası yiyemez bunları.\" Hayvanlar var, sırtlarına binmek yasaklanmıştır; hayvanlar var, Allah'a iftira yüzünden üzerlerine Allah'ın adını anmıyorlar. Allah onları üretmekte oldukları iftiralar yüzünden cezalandıracaktır."},{"n":139,"t":"Şunu da söylediler: \"Şu hayvanların karınlarındakiler erkeklerimize özgülenmiştir; kadınlarımıza haramdır. Yavru ölü doğarsa kadın-erkek hepsi onda hak sahibidir.\" Bu nitelendirmeleri yüzünden Allah cezalarını verecektir. Hakîm'dir O, Alîm'dir."},{"n":140,"t":"Şu bir gerçek ki, ilimsizlik yüzünden öz evlatlarını beyinsizce katledenlerle Allah'ın kendilerine verdiği rızıkları, Allah'a iftira ederek haramlaştıranlar gerçekten hüsrana uğramışlardır. İnan olsun, sapıtmışlardır onlar; hiçbir zaman doğruyu ve güzeli bulamazlar."},{"n":141,"t":"Çardaklı ve çardaksız bahçeleri, ürünleri çeşit çeşit hurmaları, sebzeleri, zeytinleri, narları, birbirine benzer ve benzemez biçimde oluşturan O'dur. Her birinin meyvesinden, olgunlaştığı zaman yiyin ve hasat gününde onun hakkını da verin. İsraf etmeyin, Allah israf edenleri sevmez."},{"n":142,"t":"Hayvanlardan yük taşıyanı da yaygı/döşek yapılanı da yaratan yine O'dur. Allah'ın size verdiği rızıklardan yiyin, şeytanın adımlarını izlemeyin! Çünkü o sizin için açık bir düşmandır."},{"n":143,"t":"Sekiz çift: Koyundan iki, keçiden de iki. De ki \"İki erkeği mi haram kıldı, iki dişiyi mi, yoksa iki dişinin rahimlerinin kuşattığını mı? Eğer doğru sözlü iseniz bana ilimle haber verin.\""},{"n":144,"t":"Ve deveden iki, sığırdan iki. De ki \"İki erkeği mi haram kıldı, iki dişiyi mi, yoksa iki dişinin rahimlerince kuşatılanı mı? Yoksa Allah size bunu önerirken siz de tanıklık mı ediyordunuz?\" İlim dışı bir şekilde insanları şaşırtmak için yalan düzüp Allah'a iftira edenden daha zalim kim olabilir? Allah, zulme sapan bir topluluğa kılavuzluk etmiyor."},{"n":145,"t":"De ki: \"Bana vahyolunanlar içinde, bu haram dediklerinizi yiyecek birine yasaklanmış bir şey bulamıyorum. Yalnız şunlardan biri olursa başka: leş, akıtılmış kan, domuz eti -ki o bir pisliktir- Allah'tan başkası adına boğazlanmış bir murdar.\" Iztırar haline düşen, başkasının hakkına dokunmamak, zorunluluk sınırını da aşmamak şartıyla bunlardan yiyebilir. Çünkü senin Rabbin çok bağışlayıcı, çok merhametlidir."},{"n":146,"t":"Yahudilere tüm tırnaklı hayvanları haram kıldık. Onlara ayrıca sığır ve koyunun yağlarını da haram kıldık. Sığır ve koyunun sırtlarının ve bağırsaklarının taşıdığı yağlarla, kemiklerle karışan yağlar bunun dışındadır. Bunu onlara azgınlıkları yüzünden bir ceza olarak yaptık. Biz elbette sözünde duranlarız."},{"n":147,"t":"Artık seni yalanlarlarsa şunu söyle: \"Rabbiniz çok geniş bir rahmetin sahibidir. Ancak, O'nun azabı günaha batmışlar topluluğundan uzak tutulamaz.\""},{"n":148,"t":"Şirke batanlar şöyle diyecekler: \"Allah dileseydi, ne biz şirke sapardık ne de atalarımız. Hiçbir şeyi haram da yapmazdık.\" Onlardan öncekiler de azabımızı tadıncaya kadar bu şekilde yalanlamışlardı. De ki: \"Yanınızda, önümüze çıkaracağınız bir ilminiz var mı? Zandan başka bir şeye uymuyorsunuz. Sadece saçmalıyorsunuz siz.\""},{"n":149,"t":"En mükemmel kanıt Allah'ındır. O dileseydi hepinizi toptan doğru yola iletirdi."},{"n":150,"t":"Şunu da söyle: \"Allah şunu haram etmiştir diye tanıklık edip duran şahitlerinizi getirin.\" Eğer tanıklık ederlerse sakın onlarla birlikte tanıklık etme! Ayetlerimizi yalanlayanlarla âhirete inanmayanların keyifleri ardınca gitme! Onlar, kendi Rablerine başkalarını denk tutuyorlar."},{"n":151,"t":"De ki onlara: \"Hadi gelin, Rabbinizin size neleri haram kıldığını yüzünüze karşı okuyayım: Hiçbir şeyi O'na ortak koşmayın. Ana-babaya çok iyi davranın. Yoksulluk endişesiyle çocuklarınızı öldürmeyin; biz sizi de onları da rızıklandırırız. Kötülüklerin görünenine de gizli kalanına da yaklaşmayın. Allah'ın saygın ve aziz kıldığı cana, bir hakkı savunmak dışında kıymayın. Allah size bunları önerdi ki, aklınızı işletebilesiniz.\""},{"n":152,"t":"\"Yetimin malına yaklaşmayın! Ancak rüştüne erişinceye kadar en güzel yolla ilgilenme hali müstesna. Ölçme ve tartmayı tam bir dürüstlükle yerine getirin. Hiç kimseye yaratılış kapasitesinin üstünde yükümlülük getirmiyoruz. Konuştuğunuz zaman, yakınlarınız/aleyhine de olsa, adaleti gözetin. Ve Allah'a verdiğiniz söze sadık kalın. Düşünüp öğüt alasınız diye O size bunları önerdi."},{"n":153,"t":"Bu benim dosdoğru yolumdur, onu izleyin, başka yolları izlemeyin! Yoksa bu hal sizi O'nun yolundan uzaklaştırıp parçalara böler. Sakınıp korunasınız diye O bunu önermiştir size."},{"n":154,"t":"Sonra, güzel davrananlara nimetimizi tamamlamak, her şeyi ayrıntılı kılmak, bir kılavuz ve rahmet olmak üzere Mûsa'ya o Kitap'ı verdik ki onlar Rablerine kavuşacaklarına inanabilsinler."},{"n":155,"t":"Bu da bizim indirdiğimiz bir kitaptır. Kutsal ve bereketli. Artık ona uyun ve sakının ki size rahmet edebilsin."},{"n":156,"t":"\"Kitap, bizden önce iki topluluğa indirildi. Biz onu okuyup araştırmaktan gerçekten habersizdik.\" demeyesiniz."},{"n":157,"t":"Şunu da söylemelisiniz: \"Eğer bize Kitap indirilmiş olsaydı, onlardan daha doğru yürüyüşlü olurduk.\" Artık size Rabbinizden bir beyyine, bir kılavuz ve bir rahmet gelmiş bulunuyor. Allah'ın ayetlerini yalanlayıp onlardan yüz çevirenden daha zalim kim var? Ayetlerimize sırt dönenleri, yüz çevirmeleri yüzünden azabın en acıklısıyla cezalandıracağız."},{"n":158,"t":"Neyi bekliyorlar? Kendilerine meleklerin gelmesini mi, Rabbinin gelmesini mi, yoksa Rabbinin bazı mucizelerinin gelmesini mi? Rabbinin bazı mucizeleri geldiği gün, daha önce iman etmemiş yahut imanında bir hayır sahibi olamamış kişiye imanı hiçbir yarar sağlamayacaktır. De ki: \"Bekleyin! Doğrusu biz de bekliyoruz.\""},{"n":159,"t":"Dinlerini parça parça edip fırkalara, hiziplere bölünenler var ya, senin onlarla hiçbir ilişiğin yoktur. Onların işi Allah'a kalmıştır. Allah onlara, yapıp ettiklerini haber verecektir."},{"n":160,"t":"Kim bir güzellikle gelirse ona, getirdiğinin on katı var. Kötülükle gelene ise yaptığının kadarından fazla ceza verilmez. Onlar, haksızlığa uğratılmayacaklardır."},{"n":161,"t":"De ki: \"Beni, dosdoğru yola Rabbim iletmiştir. Güçlü, pürüzsüz bir dine, hanîf olan İbrahim'in milletine. Müşriklerden değildi o.\""},{"n":162,"t":"De ki: \"Benim namazım/duam, kulluğum/bağışım, hayatım, ölümüm âlemlerin Rabbi olan Allah içindir.\""},{"n":163,"t":"\"Ortağı yoktur O'nun. Bununla emrolundum ben. Ve Müslümanların ilkiyim ben.\""},{"n":164,"t":"Şunu da söyle: \"Allah herşeyin Rabbi iken O'ndan başka rab mı arayayım? Her benliğin kazandığı kendi üstünde kalır. Hiçbir günahkâr bir başka günahkârın yükünü taşımaz. Nihayet dönüşünüz Rabbinizedir. Tartışmaya girdiğiniz şeyleri O size haber verecektir.\""},{"n":165,"t":"Sizi yeryüzünde öncekilere halefler yapan O'dur. Verdiği nimetlerle sizi denemek için kiminizi kiminiz üzerine derecelerle yükseltmiştir. Rabbin ceza verdiğinde çok süratli verir. Ama O, gerçekten çok affedici, çok merhametlidir."}],[{"n":1,"t":"Elif, Lâm, Mîm, Sâd."},{"n":2,"t":"Bir kitaptır bu; sana indirildi, onunla uyarıda bulunasın diye ve inananlar için bir öğüt ve düşündürme olarak... O halde, bundan dolayı göğsünde bir sıkıntı olmasın."},{"n":3,"t":"Rabbinizden size indirilene uyun; O'nun berisinden birtakım velilerin ardına düşmeyin. Siz ne kadar da az öğüt alıyorsunuz!"},{"n":4,"t":"Nice yurtları ve medeniyetleri yere batırdık biz. Öyle ki, geceleyin yahut öğlen uykusu uyumakta oldukları bir sırada azabımız tepelerine iniverdi."},{"n":5,"t":"Azabımız onlara gelip çattığında, yaptıkları, şu çığlığı yükseltmekten başka bir şey olmamıştır: Biz gerçekten zalimlerdik."},{"n":6,"t":"Yemin olsun, kendilerine elçi gönderilenleri muhakkak hesaba çekeceğiz; gönderilen elçileri de mutlaka hesaba çekeceğiz."},{"n":7,"t":"Onlara bir ilmin tanıklığında/bir ilmin aracılığıyla bütün serüveni mutlaka anlatacağız. Biz olup bitenlerden habersiz değildik."},{"n":8,"t":"O gün, iyi ve kötüyü ayıran ölçü haktır. Artık kimin ölçülüp tartılışacak şeyleri ağır basarsa kurtuluşa erenler onlar olacaktır."},{"n":9,"t":"Ölçülüp tartılacak şeyleri hafif kalanlara gelince, işte onlar, ayetlerimize karşı zalimce davranışlar sergilemiş oldukları için, öz benliklerini hüsrana itmiş olacaklar."},{"n":10,"t":"Yemin olsun, sizi yeryüzünde yerleştirdik ve sizin için orada, geçiminize yarayacak nimet ve imkânlara vücut verdik. Ne de az şükrediyorsunuz!"},{"n":11,"t":"Andolsun ki sizi yarattık, sonra sizi biçimlendirdik, sonra da meleklere \"Âdem'e secde edin\" dedik. Onlar da secde ettiler. Ama İblis etmedi, secde edenlerden olmadı o."},{"n":12,"t":"Allah buyurdu: \"Sana emrettiğimde secde etmeni engelleyen neydi?\" İblis dedi: \"Ben ondan hayırlıyım. Beni ateşten yarattın, onu çamurdan yarattın.\""},{"n":13,"t":"Buyurdu: \"O halde in oradan. Senin haddine mi orada büyüklük taslamak! Hadi çık! Sen alçaklardansın.\""},{"n":14,"t":"Dedi: \"İnsanların diriltileceği güne kadar bana süre ver.\""},{"n":15,"t":"Buyurdu: \"Süre verilenlerdensin.\""},{"n":16,"t":"Dedi: \"Beni azdırmana yemin ederim ki, onları saptırmak için senin dosdoğru yolun üzerine kurulacağım.\""},{"n":17,"t":"\"Sonra onlara; önlerinden, arkalarından, sağlarından, sollarından musallat olacağım. Birçoklarını şükreder bulamayacaksın.\""},{"n":18,"t":"Allah buyurdu: \"Çık oradan. Yenik düşmüş ve kovulmuş olarak. Onlardan sana uyan olursa yemin olsun ki, cehennemi tamamen sizden dolduracağım.\""},{"n":19,"t":"\"Ey Âdem! Sen ve eşin cennette oturun, dilediğiniz yerden yiyin ama şu ağaca yaklaşmayın. Yoksa ikiniz de zalimlerden olursunuz.\""},{"n":20,"t":"Derken, şeytan, kendilerinden gizlenmiş çirkin yerlerini onlara açmak için ikisine de vesvese verdi. Dedi: \"Rabbinizin sizi şu ağaçtan uzak tutması, iki melek olmayasınız yahut ölümsüzler arasına katılmayasınız diyedir.\""},{"n":21,"t":"Ve onlara, \"ben size öğüt verenlerdenim\" diye yemin de etti."},{"n":22,"t":"Nihayet onları kandırarak aşağı çekti. O ikisi ağaçtan tadınca çirkin yerleri kendilerine açıldı. Bahçenin yapraklarından yamalar yapıp üzerlerine örtmeye başladılar. Rableri onlara seslendi: \"Ben size bu ağacı yasaklamadım mı? Ben size, şeytan sizin için açık bir düşmandır demedim mi?\""},{"n":23,"t":"\"Ey Rabbimiz, dediler, öz benliklerimize zulmettik. Eğer bizi affetmez, bize acımazsan elbette ki hüsrana uğrayanlardan olacağız.\""},{"n":24,"t":"Buyurdu: \"Kiminiz kiminize düşman olarak inin. Yeryüzünde belirli bir süreye kadar mekân tutmanız ve nimetlendirmeniz öngörülmüştür.\""},{"n":25,"t":"Buyurdu: \"Orada hayat bulacaksınız, orada öleceksiniz ve oradan çıkarılacaksınız.\""},{"n":26,"t":"Ey âdemoğulları! Şu bir gerçek ki size, edep yerlerinizi örtecek giysi de indirdik, süs ve gösterişe yarayacak giysi de... Ama korunup sakınmaya yarayan giysi en hayırlısıdır. İşte bu, Allah'ın ayetlerindendir. Düşünüp öğüt almaları umuluyor."},{"n":27,"t":"Ey âdemoğulları! Şeytan, ana-babanızı, edep yerlerini onlara göstermek için elbiselerini soyarak cennetten çıkardığı gibi, sakın size de bir fitne musallat etmesin. Çünkü o ve kabilesi sizi, onları göremeyeceğiniz yerden görürler. Biz o şeytanları, inanmayanlara dostlar yaptık."},{"n":28,"t":"Bir iğrençlik yaptıklarında şöyle derler: \"Atalarımızı bu hal üzere bulmuştuk. Yani Allah emretti bize bunu.\" De ki: \"Allah, edepsizliği/iğrençliği emretmez. Allah hakkında, bilmediğiniz şeyleri mi söylüyorsunuz?\""},{"n":29,"t":"Şunu da söyle: \"Rabbim bana adaleti emretti. Her mescitte yüzlerinizi O'na doğrultun. Dini yalnız O'na özgüleyerek O'na yakarın. Tıpkı sizi ilk yarattığı gibi O'na döneceksiniz.\""},{"n":30,"t":"Bir kısmını iyiye ve güzele kılavuzladı, bir kısmının üzerine de sapıklık hak oldu. Onlar, Allah'ı bırakıp şeytanları dost edinmişlerdi. Bir de kendilerinin hidayet üzere olduklarını sanırlar."},{"n":31,"t":"Ey âdemoğulları! Tüm mescitlerde süslü, güzel giysilerinizi kuşanın. Yiyin, için fakat israf etmeyin. Allah israf edenleri sevmez."},{"n":32,"t":"De ki: \"Allah'ın kulları için çıkardığı süsü, güzel, temiz ve tatlı rızıkları kim haram etmiş?\" De ki: \"Dünya hayatında onlar, inananlar için de var. Kıyamet gününde ise yalnız inananlar içindir onlar.\" Bilgiden nasipli bir topluluk için biz, ayetleri böyle ayrıntılı kılıyoruz."},{"n":33,"t":"De ki: \"Rabbim, ancak şunları haram kıldı: \"İğrençlikleri-görünenini, gizli olanını-günahı, haksız yere saldırmayı, hakkında hiçbir kanıt indirmediği şeyi Allah'a ortak koşmayı, bir de Allah hakkında bilmediğiniz şeyleri söylemeyi.\""},{"n":34,"t":"Her ümmet için belirlenmiş bir süre vardır. Süreleri dolunca ne bir saat geri kalırlar ne de öne geçerler."},{"n":35,"t":"Ey âdemoğulları! İçinizden size ayetlerimi yüzünüze karşı anlatan resuller geldiğinde, korunup hallerini düzeltenlere hiçbir korku dokunmayacaktır. Onlar tasalanmayacaklardır da."},{"n":36,"t":"Ayetlerimizi yalanlayıp onlar karşısında burun kıvıranlara gelince, bunlar ateşin dostlarıdır. Sürekli kalacaklardır onun içinde."},{"n":37,"t":"Yalan düzerek Allah'a iftira eden yahut O'nun ayetlerini yalanlayandan daha zalim kim vardır? İşte bunların Kitap'tan nasipleri kendilerine ulaşır, nihayet elçilerimiz onlara gelip canlarını alırken şöyle derler: \"Allah'ın berisinden yakardıklarınız nerede?\" Şu cevabı verirler: \"Bizden uzaklaşıp kayboldular.\" Böylece, öz benlikleri aleyhine kendilerinin kâfir olduğuna tanıklık ettiler."},{"n":38,"t":"Allah buyurdu: \"Sizden önce gelip geçmiş cin ve insan topluluklarıyla iç içe girin bakalım ateşe.\" Her ümmet girdiğinde, yoldaşına/kızkardeşine lanet eder. Nihayet, hepsi orada bir araya gelince, sonrakiler öncekiler için şöyle derler: \"Rabbimiz! Bizi bunlar saptırdılar. Ateş azabını bunlara bir kat daha fazla ver.\" Allah buyurur: \"Her biri için bir kat fazlası var, fakat siz bilmezsiniz!\""},{"n":39,"t":"Öncekiler de sonrakiler için şöyle konuşurlar: \"Artık sizin, bizim üzerimizde bir üstünlüğünüz yok. O halde kazandıklarınıza karşılık azabı tadın.\""},{"n":40,"t":"Ayetlerimizi yalanlayan ve onlar karşısında büyüklük taslayanlar var ya, gök kapıları açılamayacaktır onlar için ve deve iğne deliğinden geçinceye kadar cennete giremeyeceklerdir onlar. Suçluları böyle cezalandırırız biz."},{"n":41,"t":"Onlar için cehennemden bir döşek/beşik ve üstlerinde kılıflar vardır. Zalimleri böyle cezalandırırız biz."},{"n":42,"t":"İman edip hayra ve barışa yönelik işler yapanlar -ki biz, her benliğe ancak yaratılış kapasitesi ölçüsünde görev yükleriz- ise cennetin dostlarıdır. Sürekli kalacaklardır orada."},{"n":43,"t":"Göğüslerinde düşmanlıktan ne varsa söküp atmışızdır. Irmaklar akar altlarından. Şöyle derler: \"Hamt olsun bizi buraya ulaştıran Allah'a. Eğer Allah bize kılavuzluk etmeseydi, biz buraya ulaşamazdık. Yemin olsun ki, Rabbimizin resulleri gerçeği getirmişler.\" Şöyle seslenilir: \"İşte size, yaptıklarınıza karşılık mirasçı kılındığınız cennet!\""},{"n":44,"t":"Cennet halkı ateş halkına şöyle seslenir: \"Biz, Rabbimizin bize vaat ettiğini gerçek bulduk. Peki siz, Rabbinizin size vaat ettiğini gerçek buldunuz mu?\" Onlar, \"Evet!\" derler. Aralarından bir duyurucu şunu ilan eder: \"Allah'ın laneti, zalimlerin üzerine olsun!\""},{"n":45,"t":"Onlar ki, Allah'ın yolundan geri çevirip yolun eğri-büğrüsünü isterler, onlar âhireti de inkâr edenlerdir."},{"n":46,"t":"İki taraf arasında bir perde, A'raf üzerinde de herkesi yüzlerinden tanıyan erler vardır. Cennet halkı, özleyip durdukları halde henüz ona girmemiş olanlara şöyle seslenirler: \"Selam size!\""},{"n":47,"t":"Gözleri ateş halkı tarafına çevrildiğinde de şöyle yakardılar: \"Ey Rabbimiz, bizleri, zalimler topluluğuyla birleştirme!\""},{"n":48,"t":"A'raf halkı, yüzlerinden tanıdıkları bazı erkeklere seslenip şöyle derler: \"Bir araya gelmeniz de büyüklük taslamanız da size hiçbir yarar sağlamadı.\""},{"n":49,"t":"\"Şunlar mıydı o, 'Allah kendilerini hiçbir rahmete erdirmeyecek' diye yemin ettikleriniz?\" Ey cennetliler! Siz de girin cennete. Ne bir korku var size ne de kederleneceksiniz."},{"n":50,"t":"Ateş halkı, cennet halkına seslenir: \"Şu sudan yahut Allah'ın sizi rızıklandırdığından biraz da bize akıtın.\" Şu cevabı verirler: \"Allah, o ikisini de, küfre sapanlara haram kılmıştır.\""},{"n":51,"t":"Onlar kendi dinlerini eğlence ve oyun haline getirdiler, iğreti hayat onları aldattı. Onlar bugüne kavuşacaklarını unutmuşlardı. Ayetlerimize karşı direniyorlardı. Bugün de biz onları unutuyoruz."},{"n":52,"t":"Yemin olsun ki, biz onlara, ilme uygun biçimde, ayrıntılı kıldığımız bir Kitap getirdik. İnanan bir topluluk için bir kılavuz, bir rahmettir o."},{"n":53,"t":"Onun yalnız tevilini gözetirler. Onun tevili geldiği gün, daha önce onu unutanlar şöyle derler: \"İnan olsun, Rabbimizin resulleri gerçeği getirmişler! Acaba bizim için şefaatçılar var mı ki, bize şefaat etsinler; yahut daha önce yaptıklarımızdan başkasını yapalım diye geri gönderilebilir miyiz?\" Öz benliklerini hüsrana ittiler. İftiralarına âlet ettikleri, onlardan uzaklaşıp kayboldu."},{"n":54,"t":"Rabbiniz o Allah'tır ki, gökleri ve yeri altı günde yaratmış, sonra da arş üzerinde egemenlik kurmuştur. Geceyi gündüze bürüyüp örter. O bunu, bu da onu aralıksız ve titiz bir biçimde kovalar durur. Güneş, Ay, yıldızlar O'nun emrine boyun eğmiş. Gözünüzü açın; yaratış da O'nundur, emir veriş de/yaratış da O'nun içindir, emir veriş de. Âlemlerin Rabbi olan Allah çok yücedir."},{"n":55,"t":"Rabbinize; boyun bükerek, gizlice/ürpererek yakarın. O, haddi aşanları/azmışları sevmez."},{"n":56,"t":"Yeryüzünde, orası barışa kavuştuktan sonra bozgun çıkarmayın. Ürpererek ve ümit ederek dua edin O'na. Hiç kuşkusuz, Allah'ın rahmeti, güzel düşünüp güzel iş yapanlara çok yakındır."},{"n":57,"t":"Rüzgârları, rahmetinin önünden müjdeci gönderen O'dur. Nihayet onlar, yüklerle ağırlaşmış bulutları yüklenince onu ölü bir beldeye göndeririz; onunla su indiririz de o suyla her türlü meyveyi çıkarırız. İşte biz, ölüleri de böyle çıkarırız. Düşünüp ibret almanız umuluyor."},{"n":58,"t":"Güzel ve temiz beldenin bitkisi Rabbinin izniyle çıkar. Pis ve çorak beldeden ise zararlı bitkiden başkası çıkmaz. Şükreden bir topluluk için ayetleri işte böyle çeşitli şekillerde sergiliyoruz."},{"n":59,"t":"Yemin olsun ki biz, Nûh'u toplumuna gönderdik de o şöyle dedi: \"Ey toplumum! Allah'a kulluk ve ibadet edin. Sizin ondan başka tanrınız yok. Üstünüze çok büyük bir azabın inmesinden korkuyorum.\""},{"n":60,"t":"Toplumunun kodamanları dediler ki: \"Vallahi biz seni açık bir sapıklık içinde görüyoruz.\""},{"n":61,"t":"Nûh dedi: \"Ey toplumum! Sapıklık falan yok bende. Tam aksine ben, âlemlerin Rabbi'nden bir resulüm.\""},{"n":62,"t":"\"Size Rabbimin vahiylerini tebliğ ediyorum, size öğüt veriyorum. Allah'ın yardımıyla, sizin bilmediğiniz şeyleri biliyorum.\""},{"n":63,"t":"\"Korunmanız, rahmet bulmanız için sizi uyarmak üzere bir adam aracılığıyla Rabbinizden size bir öğüt gelmesine şaştınız mı?\""},{"n":64,"t":"Onu yalanladılar. Bunun üzerine biz onu ve beraberindekileri gemi içinde kurtardık, ayetlerimizi yalanlayanları boğduk. Gözleri görmez bir topluluktu onlar."},{"n":65,"t":"Âd'a da kardeşleri Hûd'u gönderdik. Dedi ki: \"Ey toplumum! Allah'a kulluk edin. Sizin O'ndan başka ilahınız yok. Hâlâ sakınmıyor musunuz?\""},{"n":66,"t":"Toplumunun inkârcı kodamanları dediler ki: \"Biz seni bir beyinsizliğe düşmüş görüyoruz ve kesinlikle yalancılardan olduğunu düşünüyoruz.\""},{"n":67,"t":"Hûd dedi: \"Ey toplumum! Bende beyinsizlik yok, ben âlemlerin Rabbi'nden bir resulüm.\""},{"n":68,"t":"\"Rabbimin mesajlarını size tebliğ ediyorum. Ben sizin için güvenilir bir öğütçüyüm.\""},{"n":69,"t":"\"Sizi uyarmak için içinizden bir adam aracılığıyla size Rabbinizden bir ihtar gelmesine şaştınız mı? Hatırlayın ki, O sizi Nûh toplumundan sonra halefler yaptı ve yaratılışta size daha fazla bir boy-bos verdi. Allah'ın nimetlerini anın ki kurtulabilesiniz.\""},{"n":70,"t":"Dediler ki: \"Sen, yalnız Allah'a ibadet edelim de atalarımızın kulluk etmekte olduklarını terk edelim diye mi bize geldin? Eğer doğru sözlü isen hadi bizi tehdit ettiğini bize getir.\""},{"n":71,"t":"Hûd dedi: \"Rabbinizden bir azap ve gazap indi ya! Haklarında Allah'ın hiçbir kanıt indirmediği, sadece atalarınızın ve sizin uydurduğunuz birtakım isimler hakkında mı benimle çekişiyorsunuz? Bekleyin bakalım, sizinle beraber ben de bekleyenlerdenim.\""},{"n":72,"t":"Nihayet onu ve beraberindekileri bizden bir rahmetle kurtardık; ayetlerimizi yalanlayanların da kökünü kestik. İnanan kişiler değillerdi onlar."},{"n":73,"t":"Semûd'a da kardeşleri Sâlih'i gönderdik. Dedi ki: \"Ey toplumum! Allah'a kulluk edin. Sizin O'ndan başka ilahınız yok. Size Rabbinizden bir beyyine/açık bir kanıt gelmiştir. İşte şu; Allah'ın devesi. Sizin için bir mucize. Rahat bırakın onu, Allah'ın toprağında otlasın. Kötü bir niyetle dokunmayın ona. Yoksa korkunç bir azap yakalar sizi.\""},{"n":74,"t":"\"Hatırlayın ki, Allah sizi Âd'dan sonra halefler yaptı ve yeryüzünde sizi yerleştirdi. O'nun düzlüklerinde saraylar kuruyorsunuz, dağlarını yontup ev yapıyorsunuz. Artık Allah'ın nimetlerini anın da fesat çıkararak yeryüzünü berbat etmeyin.\""},{"n":75,"t":"Toplumunun kibre saplanmış kodamanları, içlerinden inanıp da baskı altında tutularak ezilenlere şöyle dediler: \"Siz Sâlih'in, gerçekten Rabbi tarafından gönderildiğini biliyor musunuz?\" Onlar: \"Onun aracılığıyla gönderilene gerçekten inanıyoruz.\" dediler."},{"n":76,"t":"Kibre sapanlar şöyle konuştu: \"Biz sizin inandığınızı inkâr edenleriz.\""},{"n":77,"t":"Bu arada dişi deveyi boğazladılar. Ve Rablerinin emrinden dışarı çıkıp şöyle dediler: \"Ey Sâlih! Eğer Allah tarafından gönderilenlerdensen, bizi tehdit ettiğin şeyi önümüze getiriver.\""},{"n":78,"t":"Bunun üzerine onları, o şiddetli sarsıntı/o korkunç titreşim yakaladı da öz yurtlarında yere çökmüş bir hale geldiler."},{"n":79,"t":"Nihayet, Sâlih onlardan yüzünü döndürüp şöyle dedi: \"Ey toplumum! Andolsun ki, Rabbimin mesajını size tebliğ ettim, size öğüt verdim; ama siz öğüt verenleri sevmiyorsunuz.\""},{"n":80,"t":"Ve Lût... Toplumuna şöyle demişti: \"Sizden önce âlemlerden hiçbirinin yapmadığı bir iğrençliğe mi girişiyorsunuz?\""},{"n":81,"t":"\"Siz, kadınları bırakıp şehvetiniz yüzünden erkeklere gidiyorsunuz. Doğrusu siz sınır tanımayan bir topluluksunuz.\""},{"n":82,"t":"Toplumunun cevabı sadece şunu söylemeleri oldu: \"Çıkarın şunları kentimizden. Çünkü onlar, temizlik tutkunu insanlardır.\""},{"n":83,"t":"Biz de onu ve ailesini kurtardık. Karısı müstesna. O, geriye kalıp yere geçenlerden oldu."},{"n":84,"t":"Üzerlerine bir de yağmur indirdik. Bak nasıl oldu suçluların sonu!"},{"n":85,"t":"Medyen'e de kardeşleri Şuayb'ı gönderdik. Şöyle dedi: \"Ey toplumum! Allah'a kulluk edin. Size O'ndan başka ilah yok! Size Rabbinizden açık bir kanıt gelmiştir. Ölçü ve tartıda dürüst davranın. İnsanların eşyasına el koymaya tenezzül etmeyin. Yeryüzünde, orası barışa kavuştuktan sonra bozgun çıkarmayın. Eğer inanan insanlarsanız bu sizin için daha hayırlıdır.\""},{"n":86,"t":"\"Her yol üstünde oturup da tehdit savurarak Allah yolundan O'na inananları çevirmeyin. Yolun çarpığını isteyip durmayın. Hatırlayın ki, siz az idiniz, O sizi çoğalttı. Bir bakın, nasılmış bozguncuların sonu!\""},{"n":87,"t":"\"İçinizden bir grup, benimle gönderilene inanmış, bir başka grup da inanmamışsa, Allah aranızda hükmedinceye kadar sabırlı olun. O, yargıçların en hayırlısıdır."},{"n":88,"t":"Toplumunun büyüklük taslayan kodamanları dediler ki: \"Ey Şuayb! Ya kesinlikle milletinize dönersiniz yahut da seni ve seninle birlikte inananları kentimizden mutlaka çıkarırız.\" Dedi ki: \"Ya istemiyorsak; zor ve baskıyla mı?\""},{"n":89,"t":"\"Allah bizi, milletinizden kurtardıktan sonra tekrar o millete dönersek yalan düzüp Allah'a iftira etmiş oluruz. Rabbimiz Allah istemediği sürece, sizin milletinize dönmemiz söz konusu edilemez. Rabbimiz, bilgice her şeyi kuşatmıştır. Allah'a dayanıp güvendik biz! Ey Rabbimiz! Toplumumuzla bizim aramızda hak ile hükmet. Sen, çözüm getirenlerin en hayırlısısın.\""},{"n":90,"t":"Toplumunun küfre sapan kodamanları dedi ki: \"Eğer Şuayb'ın ardı sıra giderseniz hüsrana gömülenler olursunuz.\""},{"n":91,"t":"Bunun üzerine o şiddetli sarsıntı/o korkunç titreşim onları yakalayıverdi de öz yurtlarında yere çökmüş hale geldiler."},{"n":92,"t":"Şuaybı yalanlayanlar sanki o yerde hiç şenlik kurmamışlardı. Şuayb'ı yalanlayanlar hüsrana saplananların ta kendileriydi."},{"n":93,"t":"Şuayb onlardan yüzünü döndürdü de şöyle dedi: \"Yemin olsun, ben size Rabbimin gönderdiklerini ilettim. Size öğüt verdim. Artık küfre batmış bir topluluğa nasıl acırım?\""},{"n":94,"t":"Biz bir ülkeye bir peygamber gönderdiğimizde, onun halkını zorluk ve darlıkla mutlaka sıktık ki, sığınıp yakarsınlar."},{"n":95,"t":"Sonra zorluk ve sıkıntının yerine mutluluk ve güzelliği getirmişiz de çoğalmışlar ve şöyle demişlerdir: \"Atalarımız da zorluk ve sevinçle yüzyüze gelmişlerdi.\" Nihayet biz onları farkında olmadıkları bir sırada ansızın yakalayıverdik."},{"n":96,"t":"O medeniyetlerin halkı inanıp korunsalardı, elbette ki üzerlerine gökten ve yerden bereketler saçardık. Ama yalanladılar, biz de onları, kazanır olduklarıyla yakalayıverdik."},{"n":97,"t":"O kentlerin halkı, uyudukları bir sırada, şiddetimizin bir gece kendilerine gelmeyeceğinden emin mi idiler?"},{"n":98,"t":"Yoksa o kentler halkının, bir kuşluk vakti oynayıp eğlenirken azabımızın yakalarına yapışmayacağına ilişkin bir garantileri mi vardı?"},{"n":99,"t":"Allah'ın tuzağından emin miydiler? Hüsrana uğrayan topluluktan başkası Allah'ın tuzağından emin olamaz."},{"n":100,"t":"Tüm bu olanlar, eski sahiplerinden sona yeryüzüne mirasçı olanlara şunu göstermedi mi: Dilersek onları günahları yüzünden belaya çarptırırız, kalpleri üzerine mühür basarız da artık söz dinleyemez olurlar."},{"n":101,"t":"İşte o kentler/medeniyetler! Haberlerinden bir kısmını anlatıyoruz sana. Yemin olsun, resulleri onlara açık-seçik deliller getirmişti. Ama daha önce yalanlamış oldukları için inanamadılar. Küfre sapanların kalplerini Allah işte böyle mühürler."},{"n":102,"t":"Onların birçoğunda ahde vefadan eser bulmadık. Onların birçoğunu tam sapıklar olarak bulduk."},{"n":103,"t":"Onların ardından Mûsa'yı, ayetlerimizle Firavun'a ve kodamanlarına gönderdik de ayetlerimiz karşısında zulme saptılar. Bir bak, nasıl olmuştur bozguncuların sonu!"},{"n":104,"t":"Mûsa dedi ki: \"Ey Firavun! Kuşkun olmasın ki ben, âlemlerin Rabbi'nin bir resulüyüm.\""},{"n":105,"t":"\"Allah hakkında gerçek dışında bir şey söylememek benim üzerimde bir varoluş borcudur. Ben size Rabbinizden bir beyyine getirdim. Artık İsrailoğullarını benimle gönder.\""},{"n":106,"t":"Firavun dedi: \"Bir mucize getirdinse, doğru sözlülerden isen onu ortaya çıkar!\""},{"n":107,"t":"Bunun üzerine Mûsa, asasını yere attı; birden korkunç bir ejderha oluverdi o."},{"n":108,"t":"Elini çekip çıkardı; birden o el, bakanların önünde bembeyaz kesildi."},{"n":109,"t":"Firavun toplumunun kodamanları şöyle konuştular: \"Bu adam gerçekten çok bilgili bir büyücü.\""},{"n":110,"t":"\"Sizi toprağınızdan çıkarmak istiyor. Ne diyorsunuz?\""},{"n":111,"t":"Dediler ki: \"Onu kardeşiyle birlikte alıkoy. Ve şehirlere, toplayıcılar gönder.\""},{"n":112,"t":"\"Her bilgin büyücüyü sana getirsinler.\""},{"n":113,"t":"Büyücüler Firavun'a gelip dediler ki: \"Eğer galip gelen biz olursak bize iyi bir ödül var mı?\""},{"n":114,"t":"\"Evet, dedi, ayrıca siz benim en yakınlarımdan olacaksınız.\""},{"n":115,"t":"Sihirbazlar şöyle dediler: \"Ey Mûsa! Sen mi hünerini ortaya atacaksın yoksa biz mi hünerlerimizi sergileyelim?\""},{"n":116,"t":"\"Siz sergileyin.\" dedi. Hünerlerini ortaya atınca, halkın gözlerini büyülediler, onları dehşete düşürdüler. Çok büyük bir büyü sergilediler."},{"n":117,"t":"Biz de Mûsa'ya şöyle vahyettik: \"Hadi at asanı!\" Bir ne görsünler, asa, onların ortaya getirdikleri şeyleri yalayıp yutuyor."},{"n":118,"t":"Böylece hak ortaya çıktı, onların yapıp ettikleri, işe yaramaz hale geldi."},{"n":119,"t":"Orada mağlup oldular, küçük düştüler."},{"n":120,"t":"Ve büyücüler secdeye kapandılar."},{"n":121,"t":"\"Âlemlerin Rabbi'ne iman ettik, dediler;"},{"n":122,"t":"Mûsa'nın ve Hârun'un Rabbi'ne!\""},{"n":123,"t":"Firavun dedi ki: \"Demek ben size izin vermeden ona inandınız ha! Bu, şehirde tezgâhladığınız bir tuzaktır ki, bununla şehir halkını oradan çıkarmak peşindesiniz. Yakında anlarsınız.\""},{"n":124,"t":"\"Ellerinizi ve ayaklarınızı çaprazlama keseceğim, sonra da hepinizi asacağım.\""},{"n":125,"t":"\"Biz, dediler, doğruca Rabbimize varacağız.\""},{"n":126,"t":"\"Sen bizden, sırf Rabbimizin ayetleri bize gelince, onlara iman ettiğimizden ötürü intikam alıyorsan. Ey Rabbimiz! Üzerimize sabır yağdır. Canımızı müslümanlar olarak al.\""},{"n":127,"t":"Firavun kavminin kodamanları dediler ki: \"Mûsa'yı ve toplumunu, yeryüzünü fesada verip seni ve ilahlarını terk etsinler diye mi bırakıyorsun?\" Dedi ki Firavun: \"Biz onların oğullarını öldürüp kadınlarını diri bırakacağız/kadınlarının rahimlerini yoklayıp çocuk alacağız/kadınlarına utanç duyulacak şeyler yapacağız. Üstlerine sürekli kahır yağdıracağız.\""},{"n":128,"t":"Mûsa kendi toplumuna şöyle dedi: \"Allah'tan yardım dileyin, sabırlı olun. Yeryüzü Allah'ındır, Allah ona, kullarından dilediğini mirasçı kılar. Sonuç, takvaya sarılanlarındır.\""},{"n":129,"t":"Dediler ki: \"Senin bize gelişinden önce de işkenceye uğratıldık, gelişinden sonra da.\" Mûsa dedi: \"Rabbinizin, düşmanınızı yok etmesi ve nasıl davranacağınıza bakmak üzere yeryüzünde sizi yöneticiler yapması umulabilir.\""},{"n":130,"t":"Yemin olsun ki biz, Firavun hanedanını yakalayıp ürün eksikliğiyle senelerce sıktık ki, düşünüp öğüt alabilsinler."},{"n":131,"t":"Onlara bir iyilik geldiğinde, \"Bu bizimdir!\" derlerdi. Kendilerine bir kötülük dokunduğunda ise Mûsa ve beraberindekilerin uğursuzluğuna yorarlardı. Gözünüzü açın! Onların uğursuzluk kuşu, Allah katındadır, fakat çokları bilmiyorlar."},{"n":132,"t":"Şunu da söylediler: \"Bizi büyülemek için, bize istediğin kadar ayet getir. Sana inanmayacağız.\""},{"n":133,"t":"Biz de onlar üzerine, açık açık mucizeler olarak tufan, çekirge, haşarat, kurbağalar ve kan gönderdik; yine de kibre saptılar ve günahkâr bir topluluk oluverdiler."},{"n":134,"t":"Pislik üzerlerine çökünce şöyle dediler: \"Ey Mûsa! Sana verdiği söze dayanarak Rabbine bizim için dua et! Şu pisliği üzerimizden kaldırırsa, sana kesinlikle inanacağız ve İsrailoğullarını seninle birlikte mutlaka göndereceğiz.\""},{"n":135,"t":"Dolduracakları bir süreye kadar kendilerinden azabı kaldırdığımızda, hemen yeminlerini bozdular."},{"n":136,"t":"Bunun üzerine biz de onlardan öc aldık: Ayetlerimizi yalanladıkları, onlara aldırmazlık ettikleri için hepsini suda boğduk."},{"n":137,"t":"Ezilip itilmekte olan topluluğu da içine bereketler doldurduğumuz toprağın doğularına ve batılarına mirasçı kıldık. Rabbinin, İsrailoğullarına verdiği güzel söz, sabretmeleri yüzünden hedefine vardı. Firavun ve toplumunun sanayi olarak meydana getirdiklerini de dikip yükselttikleri sarayları da yere geçirdik."},{"n":138,"t":"İsrailoğullarına denizi geçirttik. Özel putlarına tapan bir topluluğa rastladılar. Bunun üzerine: \"Ey Mûsa, dediler, bunların ilahları olduğu gibi sen de bize bir ilah belirle!\" Mûsa dedi: \"Siz cahilliği sürdürmekte olan bir toplumsunuz.\""},{"n":139,"t":"\"Şu gördüklerinizin, içinde bulundukları din çökmüştür. Yapmakta oldukları da boşa çıkacaktır.\""},{"n":140,"t":"Şunu da söyledi: \"Size Allah'tan başa bir ilah mı arayayım? O sizi âlemlere üstün kılmıştır.\""},{"n":141,"t":"Şunu da hatırlayın: Sizi Firavun hanedanından kurtarmıştık. Size azabın en kötüsü ile işkence ediyorlardı: Oğlanlarınızı katlediyorlar, kadınlarınıza hayasızca davranıyorlar/kadınlarınızın rahimlerini yokluyorlar/kadınlarınızı hayata salıyorlardı. Bunda sizin için Rabbinizden gelmiş büyük bir imtihan vardı."},{"n":142,"t":"Mûsa ile otuz gece için vaatleştik. Ve bunu, bir on ekleyerek tamamladık. Böylece Rabbinin belirlediği süre kırk geceye ulaştı. Mûsa, kardeşi Hârun'a dedi ki: \"Toplumum içinde benim yerime sen geç, barışçı ol, bozguncuların yolunu izleme!\""},{"n":143,"t":"Mûsa, bizimle sözleştiği yere gelip Rabbi de kendisiyle konuşunca şöyle yakardı: \"Rabbim, göster bana kendini, göreyim seni!\" Dedi: \"Asla göremezsin beni! Ama şu dağa bak! Eğer o yerinde durabilirse, sen de beni göreceksin!\" Rabbi, dağa tecelli edince onu parça parça etti. Ve Mûsa baygın vaziyette yere yığıldı. Kendine gelince şöyle yakardı: \"Tespih ederim seni. Tövbe edip sana yöneldim! İman edenlerin ilkiyim ben.\""},{"n":144,"t":"Allah buyurdu: \"Ey Mûsa! Ben, gönderdiğim vahiylerle, konuşmamla seni seçip yücelttim. Sana verdiğimi al ve şükredenlerden ol!\""},{"n":145,"t":"Biz Mûsa için levhalarda her şeyi yazdık: Öğüt olarak, her şeyin ayrıntısı olarak. \"Kuvvetle tut bunları ve emret toplumuna da onları en güzel şekliyle tutsunlar. Sapıklar yurdunu göstereceğim size.\""},{"n":146,"t":"Yeryüzünde haksız yere büyüklük taslayanları ayetlerimden uzak tutacağım: Onlar hangi mucizeyi görseler ona inanmazlar. Doğruya varan yolu görseler, onu yol edinmezler. Ama azgınlık yolunu görseler onu yol edinirler. Bu böyledir. Çünkü onlar ayetlerimizi yalanladılar ve onlara karşı kayıtsız kaldılar."},{"n":147,"t":"Ayetlerimizi ve âhirete varılacağını yalan sayanların tüm yaptıkları boşa gitmiştir. Bulacakları karşılık, yapıp ürettiklerinden başkası olmayacaktır."},{"n":148,"t":"Mûsa'nın kavmi, onun Allah'la konuşmaya gidişinden sonra, süs eşyalarından oluşmuş, böğürebilen bir buzağı heykelini ilah edinmişti. Görmediler mi ki, o onlarla ne konuşabiliyor ne de kendilerine yol gösterebiliyor? Onu benimsediler ve zalimler haline geldiler."},{"n":149,"t":"Başları avuçları arasına düşürülüp de sapmış olduklarını fark ettiklerinde şöyle yakardılar: \"Rabbimiz bize merhamet etmez, bizi affetmezse mutlaka hüsrana düşenlerden olacağız.\""},{"n":150,"t":"Mûsa, kızgın ve üzgün bir halde kavmine döndüğünde şöyle dedi: \"Benden sonra arkamdan ne kötü şeyler yaptınız! Rabbinizin emrini bekleyemediniz mi?\" Levhaları yere attı, kardeşinin başını tuttu, kendisine doğru çekiyordu. Kardeşi dedi ki: \"Ey annem oğlu! Bu topluluk beni horlayıp hırpaladı. Nerdeyse canımı alıyorlardı. Bir de sen düşmanları bana güldürme. Beni şu zalim toplulukla bir tutma.\""},{"n":151,"t":"Mûsa şöyle yakardı: \"Rabbim! Beni ve kardeşimi bağışla. Rahmetine sok bizi. Sen, rahmet edenlerin en merhametlisisin.\""},{"n":152,"t":"Buzağıyı ilah edinenler var ya, yakında onlara Rablerinden bir öfke ve dünya hayatında bir zillet ulaşacaktır. İftiracıları böyle cezalandırırız biz!"},{"n":153,"t":"Günahlar işledikten sonra tövbe ile iman edenlere gelince, o tövbe ve imandan sonra Allah çok affedici, çok merhametli olacaktır."},{"n":154,"t":"Öfke, Mûsa'yı rahat bırakınca, levhaları aldı. Onlardaki yazıda, yalnız Rableri karşısında ürperenler için bir rahmet ve bir kılavuz vardı."},{"n":155,"t":"Mûsa, bizimle buluşma vakti için toplumundan yetmiş adam seçti. O şiddetli sarsıntı/korkunç titreşim onları yakalayınca Mûsa şöyle dedi: \"Rabbim, dileseydin, onları da beni de daha önce helâk ederdin. İçimizdeki beyinsizlerin yaptıkları yüzünden bizi helâk mı edeceksin? Bu iş senin imtihanından başka bir şey değildir. Onunla dilediğini şaşırtır, dilediğine yol gösterirsin. Sen bizim Velî'mizsin! O halde affet bizi, acı bize! Sen affedenlerin en hayırlısısın!\""},{"n":156,"t":"\"Bize hem bu dünyada güzellik yaz hem de âhirette! Dönüp dolaşıp sana geldik.\" Buyurdu ki: \"Azabıma dilediğimi çarptırırım. Rahmetime gelince, o her şeyi çepeçevre kuşatmıştır. Ben onu; sakınıp korunanlara, zekâtı verenlere, ayetlerimize inananlara yazacağım.\""},{"n":157,"t":"Onlar ki, yanlarındaki Tevrat ve İncil'de yazılmış bulacakları ümmî peygambere uyarlar; o onlara iyiliği emreder, kötü ve çirkinden onları alıkoyar. Güzel şeyleri onlara helal kılar, pis şeyleri onlara yasaklar. Sırtlarından ağırlıklarını indirir, üzerlerindeki zincirleri, bağları söküp atar. Ona inanan, onu destekleyen, ona yardım eden, onunla indirilen ışığa uyan kişiler, kurtuluşa erenlerin ta kendileridir."},{"n":158,"t":"De ki: \"Ey insanlar! Ben sizin tümünüze Allah'ın resulüyüm! Göklerin ve yerin mülkü o Allah'ındır! İlah yoktur O'ndan başka! O diriltir, O öldürür. O halde Allah'a ve resulüne iman edin; Allah'a ve onun sözlerine inanan o ümmî peygambere iman edip uyun ki, doğruya ve güzele ulaşabilesiniz.\""},{"n":159,"t":"Mûsa kavminden bir topluluk vardır ki, hakka kılavuzluk/hak ile kılavuzluk eder ve yalnız hakka dayanarak adaleti gözetir."},{"n":160,"t":"Biz onları, on iki torun kabileye ayırdık. Toplumu kendisinden su istediğinde de Mûsa'ya, \"Asanı taşa vur!\" diye vahyettik. Taştan, on iki göze fışkırdı. Her oymak, su içeceği yeri belledi. Onların üzerlerine bulutları gölgelik yaptık, kendilerine kudret helvası ve bıldırcın indirdik. \"Yiyiniz size verdiğimiz rızıkların temizlerinden.\" Onlar bize zulmetmediler, ama öz benliklerine zulmediyorlardı."},{"n":161,"t":"Onlara şöyle denildi: Şu kentte oturun, orada istediğiniz yerden yiyin. 'Affet!' diye yalvarın; kapıdan da secde ederek girin ki, hatalarınızı bağışlayalım. Güzel düşünüp güzel iş yapanlara daha fazlasını da vereceğiz."},{"n":162,"t":"Onların zulme sapanları, bir sözü, kendilerine söylenenin dışında bir sözle değiştirdiler. Bunun üzerine biz de üzerlerine gökten bir pislik azabı saldık; çünkü zulmediyorlardı."},{"n":163,"t":"Sor onlara o deniz kıyısındaki kentin durumunu. Cumartesi günü azıp sınır tanımazlık ediyorlardı. Sebt yaptıkları gün balıkları onlara akın akın gelindi; sebt yapmadıklarında ise onlara gelmezdi. Yoldan sapmaları yüzünden onları böyle imtihan ediyorduk."},{"n":164,"t":"İçlerinden bir topluluk şöyle dedi: \"Allah'ın helâk edeceği yahut şiddetli bir azapla azaplandıracağı bir topluma ne diye öğüt verip duruyorsunuz?\" Dediler ki: \"Rabbinize karşı bir mazeret olsun diye ve bir de korunup sakınırlar ümidiyle.\""},{"n":165,"t":"Kendilerine verilen öğüdü unuttuklarında, kötülükten alıkoyanları kurtarıp zulme sapanları, yoldan çıkmalarından ötürü, acı bir azapla yakalayıverdik."},{"n":166,"t":"Ne zaman ki, yasaklandıkları şeylerden ötürü öfkelendiler, onlara şöyle dedik: \"Aşağılık, maskara maymunlar olun!\""},{"n":167,"t":"Rabbin, kıyamet gününe kadar, kendilerine azabın en kötüsünü yapacak kimseleri üzerlerine göndereceğini bildirmişti. Senin Rabbin cezayı vermede çok süratli davranır; ama çok affedici, çok merhametlidir de."},{"n":168,"t":"Ve onları yeryüzünde birçok ümmetlere böldük. İçlerinde barışsever iyiler vardı ama böyle olmayan aşağılıklar dı vardı. Belki dönerler ümidiyle onları güzeliklerle de kötülüklerle de imtihana çektik."},{"n":169,"t":"Arkalarından, yerlerini alan halefler geldi. Bunlar, kitaba vâris olmuşlardı. Şu basit dünyanın geçici menfaatini esas alıyorlar ve şöyle diyorlardı: \"Biz zaten bağışlanacağız!\" Kendilerine, bir menfaat daha gelse onu da alıyorlardı. Bunlardan, Allah hakkında, gerçek dışında bir şey söymemelerine ilişkin kitap mîsakı alınmamış mıydı? O kitabın içindekileri okuyup incelemediler mi? Âhiret yurdu, takvaya sarılanlar için daha hayırlıdır. Hâlâ aklınızı işletmeyecek misiniz?"},{"n":170,"t":"Kitaba sarılanlar ve namazı/duayı yerine getirenlere gelince, biz, barışsever iyilerin ödülünü zayi etmeyiz."},{"n":171,"t":"Bir zaman, dağı tepelerine bir gölgelik gibi çekmiştik de onu üstlerine düşüyor sanmışlardı. \"Size verdiğimizi kuvvetle tutun ve içindekini hatırınızdan çıkarmayın ki korunabilesiniz.\""},{"n":172,"t":"Hani, Rabbin, âdemoğullarından, bellerinden zürriyetlerini alıp onları öz benliklerine şahit tutarak sormuştu: \"Rabbiniz değil miyim?\" Onlar: \"Rabbimizsin, buna tanıklık ederiz.\" demişlerdi. Kıyamet günü, \"Biz bundan habersizdik\" demeyesiniz."},{"n":173,"t":"Şöyle de demeyesiniz: \"Daha önce atalarımız şirke batmıştı. Biz de onların ardından gelen bir soyuz. Gerçeği çiğneyenler yüzünden bizi helâk mı edeceksin?\""},{"n":174,"t":"Biz, ayetleri işte bu şekilde ayrıntılı kılıyoruz ki, hakka dönebilsinler."},{"n":175,"t":"Onlara, şu adamın haberini de oku: Kendisine ayetlerimizi vermiştik; onlardan sıyrılıp çıktı, şeytan da onu peşine taktı; nihayet o, azgınlardan oluverdi."},{"n":176,"t":"Dileseydik onu, o ayetlerle yüceltirdik. Ama o, sonsuza dek kalacakmış gibi, yerküreye bağlandı; iğreti arzularına uydu. Onun durumu şu köpeğin durumuna benzer: Üstüne varsan dilini sarkıtarak solur, kendi haline bıraksan dilini sarkıtarak solur. Ayetlerimizi yalanlayan toplumun örneği işte budur. Bu hikâyeyi anlat ki düşünüp taşınabilsinler."},{"n":177,"t":"Ayetlerimizi yalanlayan topluluğun vücut verdiği örnek ne kötüdür! Onlar öz benliklerine zulmediyorlardı."},{"n":178,"t":"Allah'ın yol gösterdiği, gerçeğe varmıştır; saptırdıkları ise hüsrana batıp kalmıştır."},{"n":179,"t":"Yemin olsun ki, biz, cehennem için, cinlerden ve insanlardan, birçok kişiye vücut verdik/birçoğunu döllendirip yaydık. Kalpleri var bunların, onlarla anlamazlar; gözleri var bunların, onlarla görmezler; kulakları var bunların, onlarla işitmezler. Davarlar gibidir bunlar. Belki daha da şaşkın. Gafillerin ta kendileridir bunlar."},{"n":180,"t":"En güzel isimler/Esmâül Hüsna Allah'ındır; O'na onlarla dua edin. O'nun isimlerinde ters bir tutum izleyenleri bırakın. Yapıp ettiklerinin cezasını çekeceklerdir."},{"n":181,"t":"Bizim yarattıklarımızdan bir topluluk vardır ki, hak ile kılavuzlar ve yalnız onunla adalet sunarlar."},{"n":182,"t":"Ayetlerimizi yalanlayanları, hiç bilemeyecekleri bir yerden ağır ağır çöküşe götüreceğiz."},{"n":183,"t":"Süre tanıyorum onlara. Çünkü benim tuzağım pek yamandır."},{"n":184,"t":"Düşünmediler mi ki, o arkadaşlarında cinnetten eser yok. Apaçık bir uyarıcıdan başkası değildir o."},{"n":185,"t":"Göklerin ve yerin melekûtuna, Allah'ın yarattığı herhangi bir şeye bakmadılar mı; ecellerinin gerçekten yaklaşmış olabileceğini düşünmediler mi? Peki, bu Kur'an'dan sonra hangi hadise/söze iman ediyorlar?"},{"n":186,"t":"Allah'ın şaşırttığına kimse kılavuzluk edemez. O bırakır onları ki, kudurganlıkları içinde bocalayıp dursunlar."},{"n":187,"t":"Ne zaman gelip çatacak diye kıyamet saatini soruyorlar sana. De ki: \"Ona ilişkin bilgi Rabbim katındadır. Onu, vakti geldiğinde belirginleştirecek olan yalnız O'dur. Göklere de yere de ağır gelmiştir o. O, size ansızın gelecektir, başka değil.\" Sen onu iyice biliyormuşsun gibi sana soruyorlar. De ki: \"O'na ilişkin bilgi Allah katındadır, fakat insanların çokları bilmiyorlar.\""},{"n":188,"t":"De ki: \"Ben kendi nefsime, Allah'ın dilediğinden başka ne bir yarar sağlayabilirim ne de bir zarar verebilirim. Eğer gaybı biliyor olsaydım iyilik ve güzelliği elbette çoğaltırdım. Bana kötülük dokunmamıştır bile. Ben, inanan bir topluluk için bir uyarıcı ve müjdeciden başkası değilim.\""},{"n":189,"t":"O, odur ki, sizi bir tek canlıdan yarattı, eşini de ondan vücuda getirdi ki, gönlü buna ısınsın. Eşini sarıp kucaklayınca o, hafif bir yük yüklendi de bir süre onu gezdirdi. Ağırlaştığında ikisi birden Rablerine şöyle dua ettiler: \"Bize iyi huylu, yakışıklı bir çocuk verirsen yemin ederiz, şükredenlerden olacağız.\""},{"n":190,"t":"Allah onlara iyi huylu, barışçıl bir çocuk verince, kendilerine verdiği nimette ikisi birden Allah'a ortak koşmaya başladılar. Allah onların ortak koştuğu şeylerden arınmıştır."},{"n":191,"t":"Hiçbir şey yaratmayan, bizzat kendileri yaratılmış olan şeyleri/kişileri mi ortak koşuyorlar?"},{"n":192,"t":"Onlar, ne bunlara bir yardım sağlayabilirler ne de kendi benliklerine yardımcı olabilirler."},{"n":193,"t":"Onları, iyiye ve güzele çağırsanız sizi izlemezler. Ha onlara dua etmişsiniz ha sus-pus oturmuşsunuz; sizin için aynıdır."},{"n":194,"t":"Allah dışındaki yakardıklarınız sizin gibi kullardır. Eğer iddianızda haklıysanız, hadi çağırın onları da size cevap versinler."},{"n":195,"t":"Ayakları mı var onların ki, onlarla yürüsünler; elleri mi var onların ki onlarla tutsunlar; gözleri mi var onların ki, onlarla görsünler; kulaklarımı var onların ki, onlarla işitsinler!? De ki: \"Ortaklarınızı çağırıp bana tuzak kurun. Hadi, göz açtırmayın bana!\""},{"n":196,"t":"\"Benim Velî'm, o Kitap'ı indiren Allah'tır. O, hayır ve barışı seven kulları koruyup gözetir.\""},{"n":197,"t":"O'nun dışında yakardıklarınız, size yardım edemezler. Kendilerine de yardımcı olamazlar."},{"n":198,"t":"Onları, hidayete çağırsanız, duymazlar. Onların sana baktıklarını sanırsın. Oysaki, onlar görmezler."},{"n":199,"t":"Affetmeyi esas al! İyiyi ve güzeli emret, cahillerden yüz çevir!"},{"n":200,"t":"Şeytandan bir dürtük seni dürtüklediğinde, Allah'a sığın. Çünkü O, her şeyi işitir, her şeyi bilir."},{"n":201,"t":"Korunup sakınanlar, kendilerine şeytandan bir görüntü/dürtü gelip dokunduğunda, hemen Allah'ı hatırlarlar. İşte o anda görülmesi gerekeni görürler."},{"n":202,"t":"Yoldaşları ise onları sürekli azgınlığa iterler, sonra da yakalarını bırakmazlar."},{"n":203,"t":"Onlara bir ayet getirmediğinde, \"Onu da şuradan buradan derleseydin ya!\" diye konuşurlar. De ki: \"Ben sadece Rabbimden bana vahyedilene uyuyorum. Bu, Rabbinizden gelen gönül gözleridir, doğruya kılavuzdur, iman eden bir toplum için rahmettir.\""},{"n":204,"t":"Kur'an okunduğu zaman onu dinleyin ve susun ki, size rahmet edilsin."},{"n":205,"t":"Rabbini, öz benliğinin içinde yalvarıp ürpererek, bağırtılı olmayan bir sesle sabah-akşam zikret. Sakın gafillerden olma!"},{"n":206,"t":"Rabbinin katında olanlar, büyüklük taslayıp O'na ibadetten yüz çevirmezler; O'nu tespih ederler ve yalnız O'na secde ederler."}],[{"n":1,"t":"Sana harp ganimetlerini sorarlar. De ki: \"Onlar Allah ve Resul içindir. O halde Allah'tan korkun ve aranızda barış ve esenliği kurun. Ve eğer müminler iseniz Allah'a ve O'nun Resulü'ne itaat edin!\""},{"n":2,"t":"İnanmış olanlar ancak o kişilerdir ki, Allah anıldığında yürekleri ürperip titrer ve onlara Allah'ın ayetleri okunduğunda, bu onların imanlarını artırır. Ve onlar yalnız Rablerine güvenip dayanırlar."},{"n":3,"t":"Namazı/duayı yerine getirirler onlar. Ve kendilerine rızık olarak verdiklerimizden dağıtırlar."},{"n":4,"t":"Gerçek anlamda müminler, işte bunlardır. Rableri katında dereceler, bağışlanma ve bol bir rızık var onlar için."},{"n":5,"t":"Bildiğin gibi, Rabbin seni hak uğruna, öz yurdundan çıkarmıştı. Ve müminlerden bir grup tamamen isteksizdi."},{"n":6,"t":"İş apaçık ortaya çıktıktan sonra bile, hak konusunda seninle çekişiyorlardı. Sanki onlar gözleri baka baka ölüme sürülüyorlardı."},{"n":7,"t":"O sırada Allah, iki gruptan birinin kesinlikle sizin olacağını vaat ediyordu. Ve siz, güçsüz ve silahsız olanın size düşmesini arzu ediyordunuz. Allah ise hakkı kendi kelimeleriyle tam bir biçimde ortaya koymayı ve küfre batmışların ardını-arkasını kesmeyi istiyordu."},{"n":8,"t":"Diliyordu ki, kötülüğü temsil edenler istemese de hakkı ayan-beyan gözler önüne koysun, saçma ve tutarsız olanı hükümsüz kılsın."},{"n":9,"t":"Hani siz, Rabbinizden yardım ve destek diliyordunuz; O, sizin dileğinize şöyle cevap vermişti: \"Hiç kuşkunuz olmasın, ben size, meleklerden birbiri ardınca bin tanesiyle yardım ulaştıracağım.\""},{"n":10,"t":"Allah bunu, sadece bir müjde olsun ve o sayede kalpleriniz huzur ve rahatlık bulsun diye yaptı. Yardım yalnız ve yalnız Allah katındandır. Hiç şüphesiz Allah Azîz'dir, Hakîm'dir."},{"n":11,"t":"O zaman sizi, Allah'tan bir güven olmak üzere hafif bir uyku bürüyordu; sizi onunla temizlemek, şeytanın pisliğini sizden gidermek, kalplerinizi birbirine bağlamak, ayaklarınızı sağlam bastırmak için üzerinize gökten bir su indiriyordu."},{"n":12,"t":"Rabbin, meleklere şöyle vahyediyordu: \"Ben sizinle beraberim. İmanı olanları sağlamlaştırın. İnkâr edenlerin kalpleri içine korku salacağım; vurun boyunların üstüne, vurun onların her parmağına.\""},{"n":13,"t":"Bu böyledir. Çünkü onlar Allah'a ve resulüne kafa tuttular. Kim Allah'a ve resulüne kafa tutarsa kuşkusuz ki, Allah'ın azabı şiddetli olur."},{"n":14,"t":"İşte gördünüz! Hadi tadın onu! Küfre sapanlar için ateş azabı da var."},{"n":15,"t":"Ey iman edenler! İnkâr edenlerle savaşmak üzere karşılaştığınızda, sakın onlara arkalarınızı dönmeyin!"},{"n":16,"t":"Her kim böyle bir günde, savaşmak için başka bir yer tutmak yahut başka bir birliğe katılmaya gitmek dışında onlara arkasını dönerse, Allah'tan bir gazaba çarpılmış olur. Varacağı yer cehennemdir onun. Ne kötü varış yeridir o!"},{"n":17,"t":"Siz öldürmediniz onları, Allah öldürdü onları. Attığın zaman da sen atmadın, Allah attı. İnananları kendisinden güzel bir imtihanla denemek için yaptı bunu. Allah; işitendir, bilendir."},{"n":18,"t":"Gördünüz ya, Allah küfre sapanların tuzağını fersiz bırakır."},{"n":19,"t":"Fetih istiyorsanız, fetih size geldi. Eğer vazgeçerseniz hakkınızda daha hayırlı olur. Eğer dönerseniz biz de döneriz. Cemaatiniz çok da olsa sizi her hangi bir şeyden asla müstağni kılamaz! Allah, inananlarla beraberdir."},{"n":20,"t":"Ey iman edenler! Allah'a ve resulüne itaat edin. İşitip durduğunuz halde ondan yüzünüzü çevirmeyin."},{"n":21,"t":"Hiç işitmedikleri halde, \"İşittik!\" diyenler gibi olmayın."},{"n":22,"t":"Çünkü yeryüzünde debelenenlerin Allah katında en kötüsü, akıllarını işletmeyen sağır-dilsizlerdir."},{"n":23,"t":"Allah kendilerinde bir hayır olduğunu bilseydi elbette onlara işittirirdi. Onlara işittirseydi bile mutlaka yüz çevirir, döner giderlerdi."},{"n":24,"t":"Ey iman sahipleri! Sizi, size hayat verecek şeye çağırdığında, Allah'a da resule de \"Buyur deyin!\" Şunu da bilin ki, Allah kişi ile kalbinin arasına girer. Ve bilin ki, en son O'nun huzurunda haşredileceksiniz."},{"n":25,"t":"İçinizden sadece zulmedenlere çatmakla kalmayacak bir fitneden korkun. Bilin ki Allah'ın gazabı çok şiddetlidir."},{"n":26,"t":"Düşünün ki, siz bir zamanlar yeryüzünde ezilip horlanan bir azınlıktınız. İnsanların sizi çarpıvereceğinden korkuyordunuz. Bu haldeyken Allah sizi barındırdı, yardımıyla sizi destekledi ve şükredersiniz ümidiyle sizi tertemiz nimetlerle rızıklandırdı."},{"n":27,"t":"Ey inananlar! Allah'a ve resule hıyanet etmeyin! Bilip durduğunuz halde, öz emanetlerinize hıyanet mi ediyorsunuz?"},{"n":28,"t":"Bilin ki, mallarınız ve çocuklarınız sizin için bir imtihan aracıdır. Allah'a gelince, büyük ödül O'nun katındadır."},{"n":29,"t":"Ey iman sahipleri! Eğer Allah'tan korkarsanız, Allah size hakla bâtılı/iyiyle kötüyü ayırma gücü verir, kötülüklerinizi örter. Allah, o büyük lütfun sahibidir."},{"n":30,"t":"Küfre sapanlar, seni tutup bağlamaları yahut öldürmeleri ya da yurdundan çıkarmaları için sana tuzak kuruyorlardı. Onlar tuzak kurarlar, Allah da tuzak kurar. Ama Allah, tuzak kuranların en hayırlısıdır."},{"n":31,"t":"Ayetlerimiz onlara okunduğunda şöyle derler: \"Tamam, işittik. İstersek bunun gibisini elbette ki söyleriz; öncekilerin masallarından başka şey değil ki bu!\""},{"n":32,"t":"Şunu da söylemişlerdi: \"Allahımız! Eğer bu, senin katından gelmiş gerçeğin kendisiyse, gökten üstümüze taş yağdır. Yahut bize korkunç bir azap musallat et.\""},{"n":33,"t":"Oysaki, sen onların içinde iken Allah onlara azap etmeyecekti. Onlar, af dileyip dururken de Allah onlara azap etmezdi."},{"n":34,"t":"Onlar Mescid-i Haram'dan geri çevirip dururken, Allah onlara neden azap etmeyecekmiş? Onlar onun dostları/koruyucuları da değillerdir. Onun dostları/koruyucuları takva sahiplerinden başkası değildir. Ama onların çokları bunu bilmezler."},{"n":35,"t":"Onların o evdeki namazı/duası; ıslık çalmak, el çırpmak/engel olmaktan başka bir şey değildir. O halde, inkâr etmekte olduğunuz için tadın azabı."},{"n":36,"t":"O küfre sapanlar mallarını Allah yolundan alıkoymak için harcarlar, harcayacaklardır da. Sonunda bu kendileri için bir hasret olacak, sonra da mağlup edilecekler. Küfre sapanlar doğruca cehenneme sürülecekler."},{"n":37,"t":"Böylece Allah, pisi temizden ayıracak, pis kısmı birbirleri üstüne yığıp hepsini bir yerde toplayarak tümünü cehenneme sokacak. Hüsrana uğrayanların da kendileridir bunlar."},{"n":38,"t":"Küfre sapanlara söyle: \"Eğer son verirlerse eskide kalmış olan, kendileri için affedilir. Eğer yeniden başlarlarsa, daha öncekilere uygulanan yol ve yöntem, eskisi gibi devam etmiş olacaktır.\""},{"n":39,"t":"Fitne kalmayıncaya ve din tümüyle Allah'ın oluncaya kadar onlarla savaşın! Vazgeçerlerse kuşkusuz ki Allah, ne yaptıklarını iyice görecektir."},{"n":40,"t":"Eğer yüz çevirirlerse bilin ki, Allah sizin Mevlâ'nızdır. Ne güzel Mevlâ'dır O, ne güzel destekler; ne güzel Nasîr'dir O, ne güzel yardım eder."},{"n":41,"t":"Doğru ile yanlışın ayrılış günü, iki topluluğun karşılaştığı gün, kulumuza indirmiş olduğumuza inanıyorsanız şunu bilin: Ganimet/kazanç olarak elde ettiğiniz şeylerin beşte biri Allah'a, resule, yakınlara, yetimlere, yoksullara ve yolda kalmışa aittir. Allah herşeye kadirdir."},{"n":42,"t":"O vakit siz, vadinin beri yamacında idiniz, onlarsa öte yamacında idiler. Kervan sizden daha aşağıda idi. Sözleşmiş olsaydınız buluşma yer ve saatinde ayrılığa düşerdiniz. Ama Allah, olması kararlaştırılan işi yerine getirmek istiyordu. Ta ki, ölen beyyine üzerine ölsün, yaşayan da beyyine üzerine yaşasın. Allah elbette ki çok iyi işitir, çok iyi bilir."},{"n":43,"t":"Allah onları sana uykunda az gösteriyordu. Eğer onları sana çok gösterseydi, yılgınlığa düşer, işi kotarmada çekişmeye başlardınız. Ama Allah, sizi selamete çıkardı. O, göğüslerin içindekini çok iyi bilir."},{"n":44,"t":"Karşılaştığınızda onları sizin gözlerinize az gösteriyordu. Sizi de onların gözünde azaltıyordu ki, yapılmasına karar verilen işi yürürlüğü koysun. Zaten bütün işler Allah'a döndürülür."},{"n":45,"t":"Ey inananlar! Bir düşman topluluğu ile karşılaştığınızda sebat edin. Allah'ı çok anın ki zafere ulaşabilesiniz."},{"n":46,"t":"Allah'a ve resulüne itaat edin, birbirinizle çekişmeyin; yoksa korkuya kapılırsınız, rüzgârınız kesilir. Sabredin; Allah sabredenlerle beraberdir."},{"n":47,"t":"İnsanlara çalım satarak, gösteriş yaparak yurtlarından çıkan ve Allah yolundan alıkoyanlar gibi olmayın. Allah, onların yapmakta olduklarını çepeçevre kuşatmıştır."},{"n":48,"t":"Şeytan onlara, yaptıklarını süslü gösterip şöyle demişti: \"Bugün size galip gelecek kimse yok, ben yanınızdayım.\" Fakat iki topluluk yanyana gelince iki topuğu üstüne çark edip şöyle dedi: \"Ben sizden uzağım. Ben sizin görmediklerinizi görüyorum, ben Allah'tan korkarım. Allah'ın cezası çok şiddetlidir.\""},{"n":49,"t":"İkiyüzlülerle kalplerinde hastalık olanlar şöyle diyorlardı: \"Bunları, dinleri aldatmış.\" Oysa Allah'a güvenip dayanan bilir ki, Allah Azîz ve Hakîm'dir."},{"n":50,"t":"Bir görseydin o küfre sapanları! Melekler canlarını alırken onların yüzlerine ve arkalarına vuruyorlardı: \"Yangın azabını tadın.\""},{"n":51,"t":"\"İşte bu, ellerinizin önden gönderdiği şeyler yüzündendir. Allah, kullara asla zulmetmez.\""},{"n":52,"t":"Tıpkı Firavun hanedanı ve onlardan öncekilerin gidişi gibi. Allah'ın ayetlerini inkâr ettiler de Allah onları günahları yüzünden yakalayıverdi. Allah Kavîdir, çok güçlüdür; azabı çok şiddetli yapandır O."},{"n":53,"t":"Bu böyledir. Çünkü Allah bir topluma lütfettiği nimeti, o toplum birey olarak içlerindekini/birey olarak kendilerine ilişkin olanı değiştirmedikçe, değiştirmemiştir. Ve Allah, iyice işiten, gereğince bilendir."},{"n":54,"t":"Tıpkı Firavun hanedanı ve onlardan öncekilerin tavırları gibi. Rablerinin ayetlerini yalanlamışlardı. Biz de onları günahları yüzünden mahvettik. Firavun hanedanını da boğmuştuk. Bunların tümü zulme sapanlardı."},{"n":55,"t":"Allah katında canlıların en kötüsü, gerçeği örten nankörler/inkârcılardır. Bunlar iman etmezler."},{"n":56,"t":"Bunlar, kendileriyle antlaşma yaptığın kişilerdir. Ama her defasında antlaşmalarını bozarlar. Hiç çekinmez ki bunlar..."},{"n":57,"t":"Eğer onları harpte ele geçirirsen, onlarla birlikte arkalarındakileri de ürkütüp dağıt ki, ders alabilsinler."},{"n":58,"t":"Eğer bir topluluktan hıyanet kuşkusu duyarsan, antlaşmaya bağlı kalmayacağını aynı şekilde sen de onlara bildir. Allah, hainlik edenleri sevmez."},{"n":59,"t":"Küfre sapanlar sakın öne geçtiklerini düşünmesinler. Onlar bizi âciz bırakamazlar."},{"n":60,"t":"Onlara karşı, gücünüz yettiğince kuvvet hazırlayın. Ordugâhlarda atlar besleyin. Böylece hem Allah'ın düşmanını hem kendi düşmanınızı hem de bunlardan başkalarını korkutabilirsiniz. Siz onları bilmezsiniz ama Allah hepsini bilir. Allah yolunda harcadığınız herşey size tam olarak ödenir; hiçbir haksızlığa uğratılmazsınız."},{"n":61,"t":"Eğer barışa eğilim gösterirlerse sen de buna yanaş ve Allah'a tevekkül et. Çünkü O, en iyi işitenin, en iyi bilenin ta kendisidir."},{"n":62,"t":"Eğer sana hile-oyun yapmak isterlerse Allah sana yeter. Yardımıyla ve müminlerle seni destekleyen O'dur."},{"n":63,"t":"Onların kalplerini kaynaştıran da O'dur. Sen, yeryüzündeki herşeyi bağışlasaydın, onların kalplerini yine de kaynaştıramazdın; ama Allah onları birbirine ısıtıp yaklaştırmıştır. O'dur Azîz ve Hakîm."},{"n":64,"t":"Ey Peygamber! Allah ve inanananlardan seni izleyenler sana yeter/Allah, sana da seni izleyen müminlere de yeter!"},{"n":65,"t":"Ey Peygamber! Müminleri savaşa teşvik et/coştur. Sizin sabırlı yirmi kişiniz onlardan iki yüz kişiyi yener. Sizin yüz kişiniz, inkâr edenlerden bin kişiyi yener; çünkü onlar anlayışsız bir güruhtur."},{"n":66,"t":"Şimdi Allah yükünüzü hafifletti; bildi ki sizde bir zayıflık var. Bu durumda sizin sabırlı yüz kişiniz iki yüz kişiyi yener. Sizin bir bin kişiniz, Allah'ın izniyle iki bin kişiyi yener. Allah, sabredenlerle beraberdir."},{"n":67,"t":"Hiçbir peygamber için, yeryüzünde ağır basmadıkça, esirlere sahip olmak uygun değildir. Siz şu iğreti dünyanın nimetini istiyorsunuz; Allah ise âhireti istiyor. Allah Azîz'dir, Hakîm'dir."},{"n":68,"t":"Eğer Allah'tan bir yazı önden gelmemiş olsaydı, aldığınız fidyeden ötürü size büyük bir azap dokunurdu."},{"n":69,"t":"Artık kazanç olarak elde ettiklerinizden/ elde ettiğiniz ganimetlerden helal ve temiz olarak yiyin; Allah'tan sakının! Allah çok affedici, çok merhametlidir."},{"n":70,"t":"Ey Peygamber! Elinizde esir olarak bulunanlara de ki: \"Eğer Allah, kalplerinizde bir hayır olduğunu bilirse size, sizden alınandan daha değerlisini verir ve sizi affeder. Allah çok affedici, çok esirgeyicidir.\""},{"n":71,"t":"Sana hıyanet etmek isterlerse kesin olan şu ki, daha önce Allah'a hıyanet ettiler de Allah, aleyhlerine bir imkân yarattı. Allah herşeyi bilen, her hikmete sahip olandır."},{"n":72,"t":"İman edip hicret edenler, Allah yolunda mallarıyla, canlarıyla cihad edenler ve bunları barındırıp yardım edenler; işte bunlar birbirlerinin dostları/velileridir. İman edip de hicret etmeyenlere gelince, hicret edinceye kadar onların velayetinden size bir şey yoktur. Ama din hususunda sizden yardım isterlerse, aranızda antlaşma bulunan bir topluma karşı olmamak şartıyla, yardım etmek üzerinize borçtur. Allah, yapmakta olduklarınızı iyice görmektedir."},{"n":73,"t":"Küfre sapanlar da birbirlerinin dostlarıdır. Eğer şu dikkat çekilenleri yapmazsanız yeryüzünde bir fitne, büyük bir bozgun çıkar."},{"n":74,"t":"O inanıp hicret edenler, Allah yolunda cihat edenler, o barındırıp yardımcı olanlar var ya, gerçek müminler işte onlardır! Bir bağışlanma var onlar için, bol bir rızık var."},{"n":75,"t":"Sonradan inanarak hicret edip de sizinle birlikte cihada katılanlar da sizdendir. Kan akrabaları ise, Allah'ın Kitabı'na göre birbirlerine daha yakın dostturlar. Allah herşeyi bilir."}],[{"n":1,"t":"Allah ve resulünden, kendileriyle antlaşma yapmış bulunduğunuz müşriklere bir ültimatomdur bu;"},{"n":2,"t":"Yeryüzünde dört ay daha dolaşın ve bilin ki siz, Allah'ı âciz bırakamazsınız. Şu da bir gerçek ki, Allah inkârcı nankörleri rezil eder."},{"n":3,"t":"Büyük hac günü Allah ve resulünden insanlara bir duyurudur: Allah da müşriklerden uzaktır, onun resulü de... Eğer tövbe ederseniz bu sizin için daha hayırlı olur. Yok yüz çevirirseniz bilin ki, siz Allah'ı aciz bırakamazsınız. Kâfirlere korkunç bir azabı müjdele!"},{"n":4,"t":"Antlaşma yapmış olduğunuz müşriklerden size karşı bir eksiklik sergilemeyen ve aleyhinizde başka birine yardım etmeyenler müstesnadır. Artık, onlara verdiğiniz sözü belirlenen süreye kadar tam bir şekilde koruyun. Şu bir gerçek ki Allah, sakınanları sever."},{"n":5,"t":"O haram aylar çıktığında artık müşrikleri, kendilerini bulduğunuz yerde öldürün. Yakalayın onları, kuşatın onları, tüm geçit noktalarını tıkayın onların. Bunun ardından tövbe eder, namazı/duayı yerine getirir, zekâtı verirlerse, yollarını açın onların. Kesin olan şu ki, Allah Gafûr'dur, Rahîm'dir."},{"n":6,"t":"Eğer müşriklerden biri senden güvence dilerse/senin yakınına gelmek, sana komşu olmak isterse, ona güvence ver/onu yakınlaşma isteğini kabul et ki, Allah'ın kelamını dinleyebilsin. Sonra da onu, güvenli gördüğü yere kadar götür. Böyle yapmanın gerekçesi şudur: Bunlar bilmeyen bir topluluktur."},{"n":7,"t":"Müşriklerin Allah katında, onun resulü katında ahitleri nasıl olabilir! Mescid-i Haram yanında antlaşma yaptıklarınız müstesna. Bu şekilde antlaşması olanlara, onlar size doğru-dürüst davrandıkça, siz de doğru-dürüst davranın. Allah, sakınanları sever."},{"n":8,"t":"Onların ahdine nasıl güvenilebilir! Eğer üzerinizde egemenlik kurarlarsa, sizinle ilgili ne bir antlaşmaya saygı duyarlar ne de bir yemine. Ağızlarıyla size hoşnutluk sunarlar, fakat kalpleri inat eder durur. Ve onların çoğu gerçeğe uzak düşmüş sapıklardır."},{"n":9,"t":"Allah'ın ayetlerini nasıl basit bir ücret karşılığı sattılar da Allah'ın yolundan alıkoydular. Gerçekten ne fena şeylerdir onların yapmakta oldukları."},{"n":10,"t":"Bir mümin hakkında onlar ne bir yemine saygı gösterirler ne de bir antlaşma şartına. Onlar düşmanlık dolu, azmış kişilerin ta kendileridir."},{"n":11,"t":"Bununla birlikte tövbe eder, namazı/duayı yerine getirir, zekâtı verirlerse, artık sizin, dinde kardeşlerinizdirler. Biz ayetlerimizi, bilen bir topluluk için böyle açık seçik ortaya koyarız."},{"n":12,"t":"Eğer verdikleri ahitten sonra yeminlerini bozar, dininize saldırırlarsa, o zaman küfrün elebaşlarını öldürün. Çünkü onların yeminleri yoktur. Böyle yaparsanız hal ve gidişlerine son verebilirler."},{"n":13,"t":"Yeminlerini bozan, resulü yurdundan çıkarmaya gayret eden bir topluluğa karşı savaşmayacak mısınız? Üstelik size saldırıyı ilkin onlar başlattı. Korkuyor musunuz onlardan? Eğer mümin kişilerseniz, kendisinden korkmanıza en layık olan, Allah'tır."},{"n":14,"t":"Savaşın onlarla ki, sizin elinizle Allah onlara azap etsin, onları rezil etsin. Onlara karşı size yardım etsin. Ve inananlar toplumunun göğüslerine şifa ulaştırsın."},{"n":15,"t":"Ve yüreklerinin öfkesini gidersin. Allah dilediğine tövbe nasip eder. Allah Alîm'dir, Hakîm'dir."},{"n":16,"t":"Allah; içinizden cihat edenleri, Allah'tan, resulünden ve müminlerden başkasını kendisine sırdaş edinmeyenleri belirlemedikçe bırakılacağınızı mı sandınız? Allah, yapmakta olduklarınızdan haberdardır."},{"n":17,"t":"Müşrikler, öz benliklerinin küfre sapışına tanık olup dururlarken, Allah'ın mescitlerini onarmaya girişemezler. Tüm amelleri boşa çıkmıştır onların. Ateşte uzun süre kalacaklardır onlar."},{"n":18,"t":"Allah'ın mescitlerini; ancak Allah'a, âhiret gününe inanan, namazı/duayı yerine getiren, zekâtı veren ve Allah'tan başka kimseden korkmayan kişiler onarır. İşte bunların, hidayete erenlerden olmaları beklenir."},{"n":19,"t":"Siz hacılara su vermeyi, Mescid-i Haram'ın bakım ve onarımını; Allah'a, ahiret gününe inanan, Allah yolunda cihat eden kimsenin yaptığıyla bir mi tuttunuz? Bunlar Allah katında eşit olmazlar. Allah, zalimler topluluğuna kılavuzluk etmez."},{"n":20,"t":"İman edip hicret eden, Allah yolunda mallarıyla, canlarıyla cihat edenler, derece bakımından Allah katında daha yücedir. Kurtuluşa erenler de işte bunlardır."},{"n":21,"t":"Rableri onlara kendisinden bir rahmet, bir hoşnutluk ve içinde çok değerli/kalıcı nimetlerin bulunduğu cennetler müjdeliyor."},{"n":22,"t":"Onlar orada sürekli kalacaklardır. Hiç kuşkusuz, Allah'ın katında büyük bir ödül daha vardır."},{"n":23,"t":"Ey iman edenler! Babalarınız ve kardeşleriniz, eğer imana karşı inkârı seviyorlarsa, onları dostlar edinmeyin. İçinizden onları dost edinenler zalimlerin ta kendileridirler."},{"n":24,"t":"De ki: \"Eğer babalarınız, oğullarınız, kardeşleriniz, eşleriniz, kabileniz/menfaat çevreniz, elde ettiğiniz mallar, kesadından korktuğunuz ticaret, hoşunuza giden konutlar sizin için Allah'tan, resulünden ve Allah yolunda cihattan daha sevimli ise artık Allah, emrini getirinceye kadar bekleyin. Allah, yoldan ayrılmış bir topluluğu doğruya ve güzele kılavuzlamaz.\""},{"n":25,"t":"Yemin olsun ki, Allah size birçok yerde yardım etti. Huneyn gününde de. Hani, çokluğunuz sizi böbürlendirmişti de bu hiçbir işinize yaramamıştı. Tüm genişliğine rağmen, yeryüzü size dar gelmişti. Sonra da sırtınızı dönüp kaçmıştınız."},{"n":26,"t":"Sonra Allah, resulünün üzerine de müminlerin üzerine de sükûnetini indirmiş, ayrıca sizin görmediğiniz orduları göndermiş de küfre sapanlara azap etmişti. Kâfirlerin cezası işte budur."},{"n":27,"t":"Sonra Allah, bunun ardından da dilediğinin tövbesini kabul eder. Allah Gafûr'dur, Rahîm'dir."},{"n":28,"t":"Ey inananlar! Müşrikler bir pisliktir. Artık bu yıllarından sonra Mescid-i Haram'a yaklaşmasınlar! Eğer yoksulluktan korkarsanız bilin ki, Allah dilediği taktirde sizi yakında lütfundan zengin edecektir. Allah herşeyi bilir, tüm hikmetlerin sahibidir."},{"n":29,"t":"Kendilerine kitap verilenlerden Allah'a ve âhiret gününe inanmayan, Allah'ın ve resulünün yasakladığını haram saymayan ve hak dini din edinmeyenlerle, boyun eğerek kendi elleriyle cizye verecekleri zamana kadar savaşın."},{"n":30,"t":"Yahudiler: \"Üzeyir Allah'ın oğludur\" dediler. Hristiyanlar da: \"Mesih Allah'ın oğludur\" dediler. Bu, onların ağızlarıyla uydurdukları sözdür. Daha önceki kâfirlerin sözlerine benzetiyorlar. Allah onları kahretsin! Nasıl da saptırılıyorlar!"},{"n":31,"t":"Allah'ın yanında hahamlarını ve ruhbanlarını da rabler edindiler. Meryem'in oğlu Mesih'i de öyle. Oysa kendilerine, tek olan Allah'tan başkasına ibadet/kulluk etmemeleri emredilmişti. İlah yok o tek Allah'tan başka. Onların ortak koştuklarından arınmıştır O."},{"n":32,"t":"Allah'ın nurunu ağızlarıyla söndürmek istiyorlar. Allah ise kâfirler hoşlanmasa da nurunu tamamlamaktan başka bir şey istemiyor."},{"n":33,"t":"O, resulünü hidayet ve hak dinle gönderdi ki, o dini, ortak koşanlar hoşlanmasa da diğer bütün dinlere üstün kılsın."},{"n":34,"t":"Ey iman sahipleri! Şu bir gerçek ki, hahamlardan ve rahiplerden birçoğu halkın mallarını uydurma yollarla tıkabasa yerler ve Allah'ın yolundan geri çevirirler. Altını ve gümüşü depolayıp da onları Allah yolunda harcamayanlara korkunç bir azap muştula!"},{"n":35,"t":"Gün olur, cehennem ateşinde onların üzerine lav dökülür de bununla onların alınları, böğürleri, sırtları dağlanır: \"İşte egolarınız için yığdıklarınız. Hadi, tadın biriktirmiş olduklarınızı!\""},{"n":36,"t":"Gökleri ve yeri yarattığı gündeki yazısına göre, Allah katında ayların sayısı on ikidir. Bunlardan dördü haram aylardır. Eskimez din işte budur. Artık o aylar içinde benliklerinize zulmetmeyin. Müşrikler sizinle nasıl topyekün savaşıyorlarsa siz de onlarla topyekün savaşın. Şunu bilin ki, Allah, takva sahipleriyle beraberdir."},{"n":37,"t":"Haram ayları ertelemek, küfürde bir artırmadır ki, onunla inkâr edenler saptırılır. Onu bir yıl helal sayarlar, bir yıl haramlaştırırlar ki, Allah'ın yasakladığının sayısını denkleştirip Allah'ın haram kıldığını helalleştirsinler. Amellerinin kötülüğü kendilerine süslü gösterilmiştir. Allah, küfre batan bir topluluğu iyiye ve güzele kılavuzlamaz."},{"n":38,"t":"Ey iman sahipleri! Size ne oldu ki, \"Allah yolunda seferber olun\" denilince yere çakılıp kaldınız. Âhiretten vazgeçip iğreti hayata mı razı oldunuz? O iğreti hayatın nimeti âhiret yanında pek azdır."},{"n":39,"t":"Eğer seferber olmazsanız Allah size korkunç bir azapla azap eder ve yerinize sizden başka bir topluluk getirir. Allah'a hiçbir şekilde zarar veremezsiniz. Allah her şeye Kadîr'dir."},{"n":40,"t":"Eğer siz ona yardım etmezseniz bilin ki, Allah ona zaten yardım etmişti. Hani, küfredenler onu iki kişinin ikincisi olarak yurdundan çıkardıklarında, mağarada bulundukları bir sırada arkadaşına şöyle diyordu: \"Tasalanma, Allah bizimle!\" Bunun üzerine Allah ona sükûnet indirmiş ve kendisini sizin görmediğiniz ordularla desteklemişti de küfre sapanların sözünü sefil kılıp alçaltmıştı. Allah'ın sözü ise yüce olanın ta kendisidir. Allah Azîz'dir, Hakîm'dir."},{"n":41,"t":"Gerek hafif, gerek ağırlıklı olarak mutlaka seferber olun ve Allah yolunda mallarınızla, canlarınızla cihat edin. Eğer bilirseniz bu sizin için daha hayırlıdır."},{"n":42,"t":"Eğer o, yakın bir dünya menfaati yahut orta bir yolculuk olsa idi, elbette seni izleyeceklerdi. Ama o zorluklarla dolu yolculuk kendilerine uzak geldi. \"Gücümüz yetseydi sizinle çıkacaktık\" diye Allah'a yemin de ederler. Kendilerini mahvediyorlar. Allah biliyor ki onlar, kesinlikle yalancıdırlar."},{"n":43,"t":"Allah seni affetsin; neden onlara izin verdin de beklemedin ki, doğru söyleyenler sana açık-seçik belli olsun da yalancıları bilesin."},{"n":44,"t":"Allah'a ve âhiret gününe iman edenler; mallarıyla, canlarıyla cihat edecekleri için senden izin istemezler. Allah, takva sahiplerini iyice bilmektedir."},{"n":45,"t":"Ancak Allah'a ve âhiret gününe inanmayanlar, kalpleri kuşkuyla karışmış olup da işkilleri içinde çalkanıp duranlar, sefere katılmak için senden izin isterler."},{"n":46,"t":"Sefere çıkmak isteselerdi elbette ki, bir sefer hazırlığına girişirlerdi. Ama Allah, harekete geçmelerini istemedi de onları yerlerine çiviledi ve \"oturun, oturanlarla beraber\" denildi."},{"n":47,"t":"Aranızda sefere çıkmış olsalardı, size bozgunculuktan başka bir katkıları olmayacaktı; sizi fitneye uğratmak isteğiyle aranıza sokulacaklardı. İçinizde onlara gerçekten kulak verecekler de vardı. Alah, zalimleri iyice biliyor."},{"n":48,"t":"Yemin olsun ki, onlar önceden de fitne çıkarmak istemiş ve nice işleri sana, olduğundan başka türlü göstermişlerdi. Nihayet hak geldi, onların istememesine rağmen Allah'ın emri galebe çaldı."},{"n":49,"t":"İçlerinden bazısı: \"Bana izin ver, beni fitneye düşürme.\" der. Dikkat edin, fitnenin ta içine kendileri düşmüşlerdir. Ve cehennem o nankörleri elbete çepeçevre kuşatacaktır."},{"n":50,"t":"Sana bir iyilik isabet etse bu onları üzer. Sana bir musibet dokunsa: \"İşimizi önceden sağlam tutmuşuz.\" derler ve kibirli bir sevinçle dönüp giderler."},{"n":51,"t":"De ki onlara: \"Hakkımızda Allah'ın yazdığından başkası bize asla ulaşmaz. O'dur bizim Mevlâ'mız. Yalnız Allah'a güvenip dayansın inananlar.\""},{"n":52,"t":"De ki: \"Bizim için iki güzelliğin birinden başkasını mı bekliyorsunuz? Biz de size Allah'ın, kendi katından veya bizim ellerimizle bir azap çarptırmasını bekliyoruz. Artık bekleyin, sizinle beraber biz de bekliyoruz.\""},{"n":53,"t":"Şunu da söyle: \"İster kendi arzunuzla ister baskı ve zorla infak edin; sizden asla kabul edilmeyecektir. Çünkü siz, yoldan çıkan bir topluluk oldunuz.\""},{"n":54,"t":"İnfaklarının onlardan kabul edilmesini engelleyen sadece şudur: Onlar, Allah'a ve resulüne nankörlük ettiler. Namaza/duaya ancak üşene üşene gelirler, infak edip dağıttıklarını da içlerinden gelmeyerek verirler."},{"n":55,"t":"Onların malları da evlatları da seni imrendirmesin. İş sadece şudur: Allah onlara şu iğreti hayatta azap etmeyi ve canlarının küfre sapmış bir halde çıkmasını istiyor."},{"n":56,"t":"Kesinlikle sizden oldukları yolunda Allah'a yemin ederler. Gerçekte onlar sizden değillerdir. Doğrusu şu ki onlar, ödleri patlayasıya korkan bir topluluktur."},{"n":57,"t":"Eğer bir sığınak yahut bazı mağaralar veya girilecek bir delik bulsalar, yüzlerini döner o tarafa koşarlardı."},{"n":58,"t":"İçlerinden bir kısmı da sadakalar konusunda sana laf dokundurur. Ondan kendilerine verilmişse memnun olurlar. Verilmemişse hemen öfkelenirler."},{"n":59,"t":"Ne olurdu, bunlar, Allah ve resulünün kendilerine verdiklerine razı olsalardı da şöyle deselerdi: \"Allah bize yeter. Allah bize lütfundan verecektir; resulü de. Zaten biz, gönlümüzü yalnız Allah'a bağlamışız.\""},{"n":60,"t":"Sadakalar/zekât malları Allah'tan bir farz olarak sadece şunlar içindir: Fakirler, düşkünler, sadakalarla ilgilenmeye memur edilenler, kalpleri yakınlaştırılıp ısındırılacak olanlar, özgürlüğünü yitirmiş olanlar, borçlular, Allah yolundakiler, yolda kalmış kişi. Allah Alîm'dir, Hakîm'dir."},{"n":61,"t":"İçlerinden bazıları da o Peygamber'i incitirler ve şöyle derler: \"O, her şeye kulak kesilir.\" De ki: \"Hayır kulağıdır sizin için o; Allah'a iman eder, müminlere güvenir. İnananlarınız için de bir rahmettir o.\" Allah'ın resulüne eza edenler için korkunç bir azap öngörülmüştür."},{"n":62,"t":"Sizin gönlünüzü hoş etmek için Allah'a yemin ederler. Eğer bunlar inanmış iseler Allah'ın ve resulünün hoşnutluğunu öne almaları daha uygun düşer."},{"n":63,"t":"Bilmediler mi ki, her kim Allah'a ve resulüne kafa tutarsa ona, içinde uzun süre kalacağı cehennem ateşi vardır. Büyük utanç işte budur."},{"n":64,"t":"İkiyüzlüler, kalplerinde olanı kendilerine haber verecek bir surenin tepelerine inmesinden çekinir dururlar. De ki: \"Siz alay edin! Allah, o çekinip durduklarınızı ortaya çıkaracaktır.\""},{"n":65,"t":"Onlara sorarsan elbette şöyle diyeceklerdir: \"Lakırdıya dalmış, şakalaşıyorduk, hepsi bu!\" De ki: \"Allah ile, O'nun ayetleriyle, O'nun resulüyle mi eğleniyordunuz?\""},{"n":66,"t":"Özür beyan etmeyin; imanınızdan sona küfre saptınız. İçinizden bir grubu affetsek bile diğer bir grubu, günaha batmış kişiler oldukları için azaba uğratacağız."},{"n":67,"t":"İkiyüzlülerin erkekleri de kadınları da birbirinin aynıdır: Kötülüğe özendirirler, iyilikten alıkoyarlar, harcamamak için ellerini sıkarlar. Onlar Allah'ı unuttular, Allah da onları unuttu. İkiyüzlüler, yoldan sapmışların ta kendileridir."},{"n":68,"t":"Allah, erkek münafıklara da kadın münafıklara da küfre sapanlara da içinde uzun süre kalacakları cehennem ateşini vaat etmiştir. O yeter onlara. Allah lanet etmiştir onlara. Köklü bir azap var onlar için."},{"n":69,"t":"Tıpkı sizden öncekiler gibi. Onlar kuvvetçe sizden daha zorlu, mallar ve çocuklar bakımından daha zengindiler. Kendi nasipleriyle zevk sürdüler. Siz de kendi payınıza düşenle zevk sürdünüz. Tıpkı sizden öncekilerin kendi nasipleriyle zevklendikleri gibi. Tıpkı onların dalıp gittiği gibi siz de dalıp gittiniz. İşte böylelerinin amelleri dünyada da âhirette de boşa çıkmıştır. İşte böyleleri hüsrana batmıştır."},{"n":70,"t":"Gelmedi mi onlara kendilerinden öncekilerin haberi: Nûh kavminin, Âd'ın, Semûd'un, İbrahim kavminin, Medyen halkının ve altı üstüne gelmiş kentlerin. Resulleri onlara açık-seçik ayetler getirmişti. Allah onlara zulmediyor değildi; aksine, öz benliklerine onlar zulmediyorlardı."},{"n":71,"t":"Mümin erkeklerle mümin kadınlar birbirlerinin dostlarıdır. İyilik ve güzelliği belirlenene özendirirler, kötülük ve çirkinliği belirlenenden sakındırırlar. Namazı/duayı yerine getirirler, zekâtı verirler. Allah'a ve resulüne itaat ederler. Allah bunlara rahmet edecektir. Allah Azîz'dir, Hakîm'dir."},{"n":72,"t":"Allah, mümin erkeklerle mümin kadınlara, altından ırmaklar akan cennetler vaat etmiştir. Sürekli kalacaklardır orada. Adn cennetlerinde de tertemiz barınaklar vaat etmiştir. Allah'ın bir hoşnutluğu ise hepsinden büyüktür. İşte budur o büyük başarı/o büyük kurtuluş."},{"n":73,"t":"Ey Peygamber! Küfre sapanlarla, ikiyüzlülerle cihat et! Onlara sert davran! Onların varacakları yer cehennemdir. Ne kötü dönüş yeridir o!"},{"n":74,"t":"Söylemediklerine ilişkin Allah'a yemin ediyorlar. Yemin olsun ki, o küfür sözünü söylediler. İslam'a girmeleri ardından küfre saptılar. Başaramadıkları bir şeyi tasarladılar. Oysaki intikal almaları için, Allah'ın ve resulünün, Allah'ın lütfuyla kendilerini zengin etmiş olmasından başka bir sebep de yoktu. Eğer tövbe ederlerse kendileri için hayırlı olur. Eğer yan çizerlerse Allah onlara dünyada da âhirette de acıklı bir azapla azap edecektir. Ve yeryüzünde onların ne bir dostu olacaktır ne de bir yardımcısı."},{"n":75,"t":"İçlerinden bazıları da Allah'a şöyle ant içti: \"Eğer Allah, lütfundan bize verirse, elbette sadaka dağıtacağız ve elbette iyilik ve barış için çalışanlardan olacağız.\""},{"n":76,"t":"Lütfundan kendilerine verdiği zaman ise o lütfa cimrilik ederek yüz çevirmiş bir halde dönüp gittiler."},{"n":77,"t":"Nihayet, Allah, kendisine verdikleri söze ters düştüklerinden, yalana sapıp durduklarından, huzuruna çıkacakları güne kadar onların kalplerine ikiyüzlülük yerleştirdi."},{"n":78,"t":"Bilmediler mi ki, Allah onların sırrını da fısıldaşmalarını da bilir; Allah gaybları çok iyi bilendir."},{"n":79,"t":"Sadakalar hususunda içten bir cömertlik göstermiş müminlere laf atanlarla, öz gayretlerinden başkasını bulamayanları alay konusu edenlere gelince, Allah onları maskaraya çevirecektir. Onlar için acıklı bir azap da vardır."},{"n":80,"t":"İster af dile onlar için, ister dileme. Yetmiş kez af dilesen de onlar için, Allah onları affetmeyecektir. Çünkü onlar Allah'ı da resulünü de inkâr ettiler. Allah, yoldan çıkmış böyle bir topluluğa kılavuzluk etmez."},{"n":81,"t":"Allah'ın resulüne ters düşmek için arkada kalanlar, çöküp oturdukları için sevindiler; Allah yolunda, mallarıyla canlarıyla cihadı tiksindirici bulup şöyle dediler: \"Bu sıcakta seferber olmayın!\" De ki: \"Hararet bakımından cehennem daha zorludur.\" Bir anlayabilselerdi!"},{"n":82,"t":"Kazanır oldukları yüzünden artık az gülsünler, çok ağlasınlar."},{"n":83,"t":"Bundan böyle Allah, seni onlardan bir zümrenin yanına döndürür de savaşa çıkmak için senden izin isterlerse şöyle söyle: \"Benimle birlikte asla çıkmayacaksınız, benimle birlikte herhangi bir düşmanla savaşmayacaksınız. İlk defasında oturup kalmayı yeğlemiştiniz. O halde geri kalanlarla birlikte oturadurun.\""},{"n":84,"t":"Onlardan ölen biri üzerine asla dua etme; böyle birinin mezarı başında da durma. Bunlar Allah'a ve resulüne nankörlük ettiler ve yoldan sapmış olarak ölüp gittiler."},{"n":85,"t":"Malları da evlatları da seni imrendirmesin. Allah bunlarla, dünyada onlara azap etmek istiyor. Kâfir olarak çıkaracaktır canları."},{"n":86,"t":"\"Allah'a inanın, O'nun resulüyle yan yana cihat edin!\" anlamında bir sure indirildiği zaman, onların imkân ve servet sahibi olanları, senden izin isteyerek şöyle demişlerdi: \"Bırak bizi, oturanlarla beraber olalım!\""},{"n":87,"t":"Geride kalan kadınlarla beraber olmayı yeğlediler. Kalpleri üzerine mühür basılmıştır. Artık anlayıp kavrayamazlar."},{"n":88,"t":"Fakat resul ve onunla birlikte iman edenler, mallarıyla, canlarıyla cihat ettiler. İşte bunlarındır tüm hayırlar. İşte bunlardır tam kurtulanlar."},{"n":89,"t":"Allah onlar için, altlarından ırmaklar akan cennetler hazırlamıştır. Sürekli kalacaklardır orada. İşte budur büyük başarı."},{"n":90,"t":"Göçebe Arapların özür bahane edenleri kendilerine izin verilmesi için geldiler; Allah'a ve resulüne yalan söyleyenler oturdular. Onların küfre sapanlarına korkunç bir azap erişecektir."},{"n":91,"t":"Güçsüzlere, hastalara, infak edecek bir şey bulamayanlara, Allah ve resulü için öğüt verdikleri takdirde bir günah yoktur. Güzel davrananlar aleyhine bir yol yok. Allah Gafûr'dur, Rahîm'dir."},{"n":92,"t":"Kendilerini bindirmen için sana geldiklerinde sen, \"Sizi bindirecek bir şey bulamam\" deyince, harcayacak bir şey bulamadıklarından, üzüntüyle gözlerinden yaşlar boşalarak geri dönen kimseler için de herhangi bir günah yoktur."},{"n":93,"t":"Ancak şu kimseler aleyhine yol vardır: Zengin oldukları halde senden izin isterler. Arkada kalan kadınlarla beraber oturmaya razı olmuştur bunlar. Ve Allah, kalplerine mühür basmıştır, artık bilemezler."},{"n":94,"t":"Dönüp yanlarına geldiğinizde sizden özür dilerler. De ki: \"Özür dilemeyin. Size asla inanmayacağız! Allah bize sizin hallerinizden birçoğunu haber vermiştir. Yapıp ettiğinizi Allah da resulü de görecektir. Sonra görünmeyen ve görünen âlemleri bilenin huzuruna çıkarılacaksınız da O size yapmakta olduklarınızı haber verecektir."},{"n":95,"t":"Yanlarına döndüğünüzde kendilerini paylamaktan vazgeçesiniz diye Allah'a yemin edecekler. Vazgeçin onlardan, çünkü hepsi pisliktir! Kazandıklarının karşılığı olarak, varacakları yer cehennemdir."},{"n":96,"t":"Kendilerinden hoşnut olasınız diye karşınızda yemin ediyorlar. Siz onlardan razı olsanız da Allah, yoldan sapmış bir topluluktan razı olmaz."},{"n":97,"t":"Çöl Arapları; küfür, parçalanma/ikiyüzlülük yönünden daha şiddetli; Allah'ın resulüne indirdiği şeylerin sınırlarını tanımamaya daha yatkındırlar. Allah Alîm'dir, Hakîm'dir."},{"n":98,"t":"Çöl Araplarından öylesi vardır ki, infak ettiğini bir angarya/bir ceza ödeme sayar ve sizin başınıza belaların gelmesini bekler durur. En kötü bela onların başına olsun! Allah çok iyi işitir, çok iyi bilir."},{"n":99,"t":"Çöl Araplarından bazıları da Allah'a ve âhiret gününe inanır, harcadığını Allah yanında yakınlıklara ve resulün dualarına vesîle edinir. Dikkat edin! O harcadıkları gerçekten kendileri için bir yakınlık vesîlesidir. Allah onları rahmetinin içine sokacaktır. Allah çok affedici, çok esirgeyicidir."},{"n":100,"t":"Muhacirlerden ve Ensar'dan ilklerle, güzel düşünüp güzel davranmada onları izleyenler var ya, Allah onlardan razı olmuştur; onlar da O'ndan razıdırlar. Onlara altlarından ırmaklar akan cennetler hazırlamıştır. Sürekli orada kalacaklardır. Büyük kurtuluş işte budur!"},{"n":101,"t":"Çevrenizdeki Bedevî Araplardan münafıklar var. Medine halkından da münafıklığa iyice alışmış olanlar var. Sen bilmezsin onları. Ama biz biliriz onları. İki kez azap edeceğiz onlara, sonra da çok büyük bir azaba itilecekler."},{"n":102,"t":"Diğer bazıları da günahlarını itiraf ettiler. Bunlar, iyi bir işle kötü olan diğer bir işi birbirine karıştırdılar. Belki Allah tövbelerini kabul eder. Çünkü Allah Gafûr'dur, Rahîm'dir."},{"n":103,"t":"Bunların mallarından bir sadaka al ki, onunla kendilerini iyice temizleyip arıtasın. Onlar için dua et/onlara destek ol; çünkü senin duan/desteğin onlar için bir sükûnettir. Allah Semî'dir, Alîm'dir."},{"n":104,"t":"Bilmediler mi ki, Allah'tır kullarından o tövbeyi kabul eden, o sadakaları alan. Ve Allah'tır, O Tevvâb, O Rahîm..."},{"n":105,"t":"De ki: \"İş yapıp değer üretin; yapıp ürettiğinizi Allah da resulü de müminler de görecektir. Ve siz, görülmeyen âlemi de görülen âlemi de bilenin huzuruna döndürüleceksiniz, O size, yapıp ettiklerinizi bir bir haber verecektir.\""},{"n":106,"t":"Bir kısmı da umutları Allah'ın emrine bağlı, beklemektedir. Allah onlara ya azap edecektir ya tövbe edecektir. Allah, Alîm'dir, Hakîm'dir."},{"n":107,"t":"Bir de şunlar var: Tutup bir mescit yapmışlardır: Zarar vermek için, nankörlük/gerçeği örtmek için, inananları fırkalara bölmek için, daha önceden Allah ve resulüyle savaşmış kişiye gözetleme yeri kurmak için. \"İyilik ve güzellikten başka bir şey istemiş değiliz!\" diye gerile gerile yemin de edecekler. Allah şahittir ki, onlar kesinlikle yalancıdırlar."},{"n":108,"t":"Böyle bir mescitte sakın namaza durma! Daha ilk gününde takva üzerine kurulan bir mescit, içinde namaz kılman için çok daha uygundur. Temizlenmek arzusu taşıyan erler vardır o mescitte. Allah, temizlenenleri sever."},{"n":109,"t":"Peki, binasını Allah'tan gelen bir sakınma duygusu ve hoşnutluk üzerine kuran mı hayırlıdır yoksa binasını sel artıklarının ucundaki yarın kenarına kurup da onunla birlikte cehenneme yuvarlanan mı? Allah, zalimler topluluğuna kılavuzluk etmez."},{"n":110,"t":"Kurdukları bina, kalpleri parçalanıncaya kadar yüreklerinde bir kuşku olmaya devam edecektir. Allah Alîm'dir, Hakîm'dir."},{"n":111,"t":"Allah, müminlerin canlarını ve mallarını, karşılığında kendilerine cennet vermek üzere satın almıştır. Allah yolunda çarpışırlar da öldürürler, öldürülürler. Allah'ın; Tevrat'ta, İncil'de ve Kur'an'da kendi üzerine hak olarak yazdığı bir vaattır bu. Ahdine, Allah'tan daha vefalı kim var? Perçinlediğiniz bu antlaşmanızdan ötürü müjdeler olsun size. İşte budur o büyük başarının ta kendisi."},{"n":112,"t":"Tövbe edenler, ibadet edenler, hamd edenler, seyahat ederken oruç tutanlar, rükû edenler, secdeye kapananlar, iyiliğe özendirip kötülükten sakındıranlar, Allah'ın sınırlarını koruyanlar... Müjdele o müminleri!"},{"n":113,"t":"Akraba bile olsalar, cehennem halkı oldukları açıkça belli olduktan sonra müşrikler için af dilemek ne peygambere yakışır ne de iman edenlere."},{"n":114,"t":"İbrahim'in, babası için af dilemesi, sadece ona verdiği bir söz yüzündendi. Onun Allah düşmanı olduğu kendisi için açıklık kazanınca, ondan uzaklaştı. Şu bir gerçek ki, İbrahim başkaları için gamlanıp ah eden ince yürekli, yumuşak bir insandı/tam bir evvâhtı."},{"n":115,"t":"Allah bir topluluğa kılavuzluk ettikten sonra, sakınacakları şeyleri kendilerine ayan-beyan bildirinceye kadar, onların sapıklığına hükmetmez. Allah her şeyi hakkıyla bilendir."},{"n":116,"t":"Göklerin de yerin de mülk ve yönetimi Allah'ındır. Diriltir de öldürür de. Sizin için Allah dışında ne bir dost vardır ne de bir yardımcı."},{"n":117,"t":"Yemin olsun ki, Allah, içlerinden bir grubun kalpleri kaymaya yüz tuttuktan sonra, peygambere ve o güçlük saatinde ona uymuş olan Muhacirlerle Ensar'a tövbe nasip etmiş, sonra da onların tövbelerini kabul buyurmuştur. Çünkü onlara karşı Raûf ve Rahîm'dir."},{"n":118,"t":"Geride bırakılan üç kişinin de tövbesini kabul etmiştir. Bütün genişliğine rağmen yeryüzü onlara dar gelmiş, öz benlikleri kendilerini sıkıştırmıştı; Allah'ın öfkesinden kurtulmak için yine Allah'a sığınmaktan başka çare olmadığını fark etmişlerdi. Sonra onlara tövbe nasip etti ki, eski hallerine dönsünler. Hiç kuşkusuz, Allah, tövbeleri çok çok kabul eden, rahmeti sınırsız olandır."},{"n":119,"t":"Ey iman edenler! Allah'tan korkun ve özü-sözü bir kişilerle beraber olun."},{"n":120,"t":"Medine halkına ve çevrelerindeki Bedevî Araplara, Allah resulünden geri kalmaları ve onu bırakıp da kendi canlarının derdine düşmeleri yakışmaz. Çünkü Allah yolunda uğrayacakları bir susuzluk, bir yorgunluk, bir açlık, kâfirleri öfkelendirmek üzere bir yere ayak basmaları, düşmana karşı herhangi bir başarı kazanmaları durumunda kendileri için, barışa yönelik iyi bir amel mutlaka yazılacaktır. Allah, güzel düşünüp güzel davrananların ödülünü yitirmez."},{"n":121,"t":"Küçük-büyük bir infakta bulunmaları, bir vadiyi geçmeleri, kendileri lehine mutlaka yazılır ki, Allah onlara yapıp ettiklerinden daha güzeliyle karşılık versin."},{"n":122,"t":"Müminlerin hepsinin birden savaşa çıkmaları doğru olmaz. İçlerinden her gruptan bir topluluğun din hususunda derin bilgi edinmek ve kavimleri kendilerine döndüğünde onları uyarmak için geride kalmaları gerekmez miydi? Umulur ki sakınırlar."},{"n":123,"t":"Ey iman sahipleri! Küfre sapanların yakınınızda bulunanlarıyla savaşın. Sizde bir sertlik bulsunlar. Şunu bilin ki Allah, sakınanlarla beraberdir."},{"n":124,"t":"Ne zaman bir sure indirilse içlerinden biri, \"Bu hanginizin imanını artırdı?\" diye konuşur. İmanı olanların imanını artırmıştır. İşte sevinip duruyorlar!"},{"n":125,"t":"Kalplerinde maraz olanlara gelince, inen sure onların pisliğine pislik ekler. Kâfir olarak ölüp gittiler onlar."},{"n":126,"t":"Görmüyorlar mı ki, her yıl bir veya iki kez imtihan ediliyorlar. Hâlâ ne tövbeye yelteniyorlar ne de öğüt alıyorlar."},{"n":127,"t":"Bir sure indirildi mi \"Sizi birisi görüyor mu?\" diye birbirlerine bakar, sonra da sıvışıp giderler. Allah, kalplerini yamultmuştur. Çünkü gereğince anlamayan bir topluluktur bunlar."},{"n":128,"t":"Yemin olsun, içinizden size onurlu bir resul gelmiştir. Sizi rahatsız eden şey onu da üzer. Çok düşkündür size. Müminlere ise daha şefkatli, daha merhametlidir."},{"n":129,"t":"Eğer çekip giderlerse de ki: \"Allah bana yeter. İlah yok O'ndan başka. Yalnız O'na dayandım ben; büyük arşın sahibi O'dur.\""}],[{"n":1,"t":"Elif, Lâm, Râ. İşte sana hikmetlerle dolu Kitap'ın ayetleri."},{"n":2,"t":"\"İnsanları uyar, iman edenlere de kendileri için Allah katında yüksek bir doğruluk derecesi bulunduğunu müjdele\" diye içlerinden bir er kişiye vahiy göndermemiz, insanlara şaşırtıcı mı geldi? Küfre batanlar: \"Bu adam açık bir büyücüdür.\" dediler."},{"n":3,"t":"Şu bir gerçek ki, sizin Rabbiniz gökleri ve yeri altı günde yaratan, sonra arş üzerine egemenlik kurup iş ve oluşu çekip çeviren Allah'tır. O'nun izni olmadıkça hiçbir şefaatçı devreye giremez. İşte bu Allah'tır sizin Rabbiniz. Artık O'na kulluk/ibadet edin. Düşünüp anlamıyor musunuz?"},{"n":4,"t":"Allah'tan hak bir vaat olarak hepinizin dönüşü yalnız O'nadır. Yaratılışı başlatır, sonra yarattıklarını varlık alanına ardarda çıkarır ki, iman edip hayra ve barışa yönelik amelleri yerli yerince sergileyenleri ödüllendirsin. Küfre dalanlara gelince, onlar için, nankörlük edip gerçeği örtmeleri yüzünden, kaynar sudan bir içki ve acıklı bir azap öngörülmüştür."},{"n":5,"t":"Güneş'i ısı ve ışık kaynağı; Ay'ı, hesabı ve yılların sayısını bilesiniz diye bir nur yapıp ona evreler takdir eden O'dur. Allah bütün bunları rastgele değil, şaşmaz ölçülere bağlı olarak yaratmıştır. Bilgiyle donanmış bir topluluk için ayetleri ayrıntılı kılıyor."},{"n":6,"t":"Şu bir gerçek ki, geceyle gündüzün birbiri ardınca değişip durmasında, Allah'ın göklerde ve yerde vücut verdiği şeylerde, sakınan bir topluluk için sayısız ayetler vardır."},{"n":7,"t":"Şu bir gerçek ki, bize kavuşmayı ummayanlar, iğreti hayatla tatmin bulup onunla rahatlayanlar ve ayetlerimizden uzaklaşıp gaflete dalanlar,"},{"n":8,"t":"Kazandıkları şeyler yüzünden varış yerleri ateş olacakların ta kendileridir."},{"n":9,"t":"İman edip haya ve barışa yönelik amel sergileyenlere gelince, Rableri onları imanlarıyla doğruya ve güzele iletir. Nimetlerle dolu cennetlerde onların altlarından ırmaklar akacaktır."},{"n":10,"t":"Orada onların yakarışı, \"Tespih ederiz seni ey Allahımız!\" ve birbirlerine esenlik dilemeleri, \"Selam!\" şeklindedir. Ve onların son çağırışları şudur: Bütün övgüler âlemlerin Rabbi Allah'adır."},{"n":11,"t":"Allah, insanlara şerri, onların hayrı acele istedikleri gibi çabucak verseydi, ecellerinin onlara ulaşmasına çoktan hükmedilmiş olurdu. Ama biz, bize kavuşmayı ummayanları kendi azgınlıkları içinde körü körüne bocalamaya bırakırız."},{"n":12,"t":"İnsanlara zorluk dokunduğu zaman; yan yatarken, otururken, ayaktayken bize yalvarır. Ama sıkıntısını çözdüğümüzde, kendisine dokunan bir zorluk yüzünden bize hiç yalvarmamış gibi çekip gider. Haksızlığa/aşırılığa sapanlara, yapmakta oldukları, işte böyle süslü gösterilmiştir."},{"n":13,"t":"Yemin olsun ki, biz sizden önceki kuşakları, zulmettikleri ve resulleri kendilerine açık kanıtlar getirdiği halde inanmadıkları için, helâk ettik. Günaha batanlar topluluğunu biz böyle cezalandırırız."},{"n":14,"t":"Sonra onların ardından yeryüzünde sizi halefler kıldık ki, nasıl iş yapacağınızı görelim."},{"n":15,"t":"Ayetlerimiz onlara açık-seçik parçalar halinde okunduğu zaman, bize ulaşmayı ummayanlar şöyle dediler: \"Bundan başka bir Kur'an getir yahut bunu değiştir.\" De ki: \"Onu kendiliğimden değiştirmem benim için söz konusu olamaz. Ben sadece bana vahyolunana uyuyorum. Rabbime isyan edersem, büyük bir günün azabından korkuya düşerim.\""},{"n":16,"t":"De ki: \"Allah dileseydi, onu size okumazdım, onu size bildirmezdi de. Ondan önce içinizde bir ömür kalmıştım. Hâlâ aklınızı kullanmayacak mısınız?\""},{"n":17,"t":"Yalan düzerek Allah'a iftira eden yahut onun ayetlerini yalanlayan kişiden daha zalim kim var? Şu bir gerçek ki, suçlular iflah etmezler."},{"n":18,"t":"Allah'ın yanında bir de kendilerine zarar veremeyen, yarar sağlayamayan şeylere kulluk ediyorlar ve şöyle diyorlar: \"Bunlar bizim Allah katındaki şefaatçılarımızdır.\" De onlara: \"Allah'a, göklerde ve yerde bilmediği şeyleri mi haber veriyorsunuz?\" Şanı yücedir O'nun, ortak koştuklarından arınmıştır O."},{"n":19,"t":"İnsanlar bir tek ümmetten başka değilken ihtilafa düştüler. Eğer Rabbinden bir söz öne geçmemiş olsaydı, tartışıp durdukları konuda aralarında hüküm verilir/iş mutlaka bitirilirdi."},{"n":20,"t":"Şöyle derler: \"Ona Rabbinden bir mucize indirilseydi ya!\" De ki: \"Gayb, Allah'ın tekelinde. Hadi bekleyin; sizinle birlikte ben de bekleyenlerdenim.\""},{"n":21,"t":"İnsanlara, kendilerine dokunan bir darlıktan sonra bir rahat tattırdığımızda, ayetlerimiz hakkında hemen bir tuzak sergilerler. De ki: \"Tuzak kurma bakımından Allah daha hızlıdır.\" Zaten, resullerimiz, kurmakta oldukları tuzakları kaydediyorlar."},{"n":22,"t":"O yürütüyor sizi karada ve denizde. Diyelim, gemidesiniz: Gemiler, içindekileri latîf bir rüzgârla götürüyorlar. İçerdekiler ferah ve sevinç duymaktalar. Birden korkunç bir kasırga geliverdi. Her taraftan dalgalar üzerlerine çullandı. Çepeçevre kuşatıldıklarını düşünüp dini yalnız Allah'a özgüleyerek duaya koyuldular: \"Eğer bizi şu durumdan kurtarırsan, yemin olsun, sana şükredenlerden olacağız.\""},{"n":23,"t":"Ama Allah onları kurtarınca, hiç vakit geçirmeden yeryüzünde haksızlığa sapıp azgınlaşırlar. Ey insanlar! Şu iğreti hayatın menfaati için yaptığınız azgınlık ve taşkınlık yalnız sizin aleyhinizedir. Bir süre sonra bize döndürüleceksiniz ve yapmakta olduklarınızı size haber vereceğiz."},{"n":24,"t":"Şu iğreti hayatın durumu gökten indirdiğimiz bir suya benzer: İnsanların ve davarların yedikleri yeryüzü bitkisi onunla karışmıştır. Nihayet toprak, takılarını kuşanmış, süslenmiştir. Toprağın sahipleri onun üzerinde egemen olduklarını sanmaktadırlar. Tam bu sırada emrimiz ona gece veya gündüz ulaşmıştır. Ve onu, sanki dün yerinde yokmuş gibi biçip atmışızdır. Derin derin düşünen bir topluluk için ayetleri böyle ayrıntılı olarak veriyoruz."},{"n":25,"t":"Allah, esenlik yurduna çağırır ve dilediğini dosdoğru bir yola kılavuzlar."},{"n":26,"t":"Güzel düşünüp güzel davrananlara güzellik var. Dahası da var. Onların yüzlerine kara da bulaşmaz, zillet de... Cennetin dostlarıdır onlar; sürekli kalıcıdırlar orada."},{"n":27,"t":"Kötülük kazananlara ise kötülüğün miktarınca karşılık vardır. Ama yüzlerini bir zillet de kaplar. Onları Allah'tan kurtaracak kimse yoktur. Yüzleri gece parçalarından karanlıklarla kaplanmış gibidir. Ateşin dostlarıdır bunlar. Sürekli kalıcıdırlar içinde."},{"n":28,"t":"Gün olur, onları bir araya toplarız; sonra şirke batmışlara sesleniriz: \"Siz ve ortak yaptıklarınız, yerlerinize!\" Aralarını ayırmışızdır. Allah'a ortak tuttukları şöyle haykırır: \"Siz sadece bize kulluk/ibadet etmiyordunuz.\""},{"n":29,"t":"\"Sizinle bizim aramızda tanık olarak Allah yeter. Doğrusu, biz sizin ibadetinizden tamamen habersizdik.\""},{"n":30,"t":"İşte orada, her benlik önceden gönderdiği şeyi kendisi deneyecektir. Hepsi gerçek Mevlâ'larına döndürülmüş, iftira aracı yaptıkları şeyler kendilerini koyup gitmiştir."},{"n":31,"t":"Sor: \"Sizi gökten ve yerden kim rızıklandırıyor? Ya o işitme gücünün ve gözlerin sahibi kim? Kim çıkarıyor ölüden diriyi ve kim çıkarıyor diriden ölüyü? Kim çekip çeviriyor iş ve oluşu?\" Hemen, \"Allah!\" diyecekler. De ki: \"Hâlâ kendinize gelmiyor musunuz?\""},{"n":32,"t":"İşte bu Allah'tır sizin Hak Rabbiniz. Hak'tan sonra, sapıklıktan başka ne kalır ki? Peki, nasıl oluyor da yüz geri döndürülüyorsunuz?"},{"n":33,"t":"Bu, budur! Rabbinin yoldan çıkanlar hakkındaki, \"Onlar iman etmezler!\" sözü gerçekleşmiştir."},{"n":34,"t":"De ki: \"Ortak tuttuklarınız içinde, yaratışa başlayan, sonra, yarattığını çevirip bir daha yaratan kim var?\" De ki: \"Allah! Yaratışı başlatır, sonra onu çevirip yeniden yaratır. O halde nasıl oluyor da başka bir yöne döndürülüyorsunuz?\""},{"n":35,"t":"Şunu da söyle: \"Ortak tuttuklarınızdan kim var hakka götüren?\" De ki: \"Allah götürür hakka. Hakka götürebilen mi izlenmeye daha layıktır yoksa kılavuzlanmadıkça yolu bulamayan mı? Peki, ne oluyor size? Nasıl hüküm veriyorsunuz siz?\""},{"n":36,"t":"Onların çoğu sanıdan başka bir şeyin ardınca gitmiyor. Doğrusu da şu ki sanı, haktan hiçbir şey ifade etmez. Allah, onların yaptıklarını iyice bilmektedir."},{"n":37,"t":"Bu Kur'an, Allah'ın berisinden birilerince yalan isnatlarla oluşturulmuş değildir. O, kendinden öncekinin tasdiki ve Kitap'ın ayrıntılı kılınmasıdır. Kuşku ve çelişme yoktur onda. Âlemlerin Rabbi'ndendir o."},{"n":38,"t":"Yoksa, \"onu uydurdu\" mu diyorlar! De ki: \"Eğer doğru sözlüler iseniz Allah dışında, elinizin yettiklerini de çağırın da onun benzeri bir sure ortaya çıkarın.\""},{"n":39,"t":"Hayır, düşündükleri gibi değil. Onlar, ilmini kuşatamadıkları ve yorumu kendilerine hiç gelmemiş bir şeyi yalanladılar. Onlardan öncekiler de böyle yalanlamıştı. Bak da gör nasıl olmuştur zalimlerin sonu!"},{"n":40,"t":"İçlerinden buna inanacak var, inanmayacak var. Bozguncuları Rabbin daha iyi bilir."},{"n":41,"t":"Seni yalanladılarsa şöyle söyle: \"Benim yaptığım bana, sizin yaptığınız size. Siz benim yaptığımdan uzaksınız, ben de sizin yaptığınızdan uzağım.\""},{"n":42,"t":"İçlerinde sana kulak verenler de vardır. Peki, sağırlara sen mi işittireceksin? Hele bir de akıllarını kullanmıyorlarsa!"},{"n":43,"t":"Onlardan sana bakanlar da vardır. Peki, körlere sen mi kılavuzluk edeceksin? Hele, kalp gözleriyle de görmüyorlarsa!"},{"n":44,"t":"Allah, insanlara hiçbir şekilde zulmetmez. Ama insanlar öz benliklerine zulmediyorlar."},{"n":45,"t":"Onları huzuruna toplayacağı gün, gündüzün bir saatinden başka, dünyada durmamış gibidirler; aralarında tanışırlar. Allah'a kavuşmayı yalanlayıp da doğru yolu tutmamış bulunanlar, hüsrana uğramışlardır."},{"n":46,"t":"Onların vaat ettiğimizin bazısını sana göstersek de seni vefat ettirsek de dönüşleri bizedir. Sonunda Allah, işlemiş olduklarına tanıklık edecektir."},{"n":47,"t":"Her ümmet için bir resul öngörülmüştür. Resulleri gelince, aralarında adaletle hüküm verilir. Hiçbir zulme uğratılmazlar."},{"n":48,"t":"Diyorlar ki: \"Doğru sözlülerseniz bu vaat ne zaman?\""},{"n":49,"t":"De ki: \"Ben kendime bile Allah'ın istediği dışında bir zarar verme yahut yarar sağlama gücünde değilim. Her ümmetin bir eceli var. Ecelleri geldiğinde bir saat geri de kalamazlar, ileri de gidemezler.\""},{"n":50,"t":"Şöyle söyle: \"Diyelim O'nun azabı size gündüzün veya geceleyin gelecektir. Suçlular bunlardan hangisini aceleyle ister?\""},{"n":51,"t":"O azap başınıza patladıktan sonra mı iman ettiniz! Şimdi mi? Hani onu aceleden isteyip duruyordunuz?"},{"n":52,"t":"Sonra, zulmedenlere şöyle denecek: \" O uzun süreli azabı tadın! Kazandığınız şeyler dışında bir şeyle cezalandırılmayacaksınız!\""},{"n":53,"t":"Soruyorlar sana: \"Doğru mu bu?\" De ki: \"Evet! Rabbime yemin ederim, o doğrunun ta kendisidir! Ve siz ondan yakayı kurtaramayacaksınız.\""},{"n":54,"t":"Zulmetmiş her benlik, yeryüzündekiler kendinin olsa, kurtulmak için tümünü fidye verecektir. Azabı gördüklerinde pişmanlığı ta içlerinde duyarlar. Aralarında adaletle hükmedilmiştir. Asla zulme uğratılmazlar!"},{"n":55,"t":"Gözünüzü açın, göklerde ve yerde ne varsa Allah'ındır! Gözünüzü açın, Allah'ın vaadi haktır! Ama onların çokları bilmiyorlar."},{"n":56,"t":"O, hayat verir, O öldürür. O'na döndürüleceksiniz.!"},{"n":57,"t":"Ey insanlar! İşte, size Rabbinizden bir öğüt, gönüller derdine bir şifa, inananlara bir kılavuz ve bir rahmet geldi."},{"n":58,"t":"De ki: \"Allah'ın lütfuyla, O'nun rahmetiyle, sadece onunla sevinip ferahlasınlar! O, onların toplayıp yığdıklarından hayırlıdır.\""},{"n":59,"t":"De ki: \"Ne oldu size de Allah'ın size rızık olarak indirdiği şeylerden bir haram yaptınız bir de helal?\" De ki: \"Allah mı size izin verdi, yoksa Allah'a iftira mı ediyorsunuz?\""},{"n":60,"t":"Yalanı Allah'a yakıştıranlar, kıyamet günü hakkında ne düşünüyorlar? Allah, insanlara karşı elbette lütuf sahibidir, fakat onların çokları şükretmiyorlar."},{"n":61,"t":"Bir iş ve oluşta bulunsan, Kur'an'dan bir şey okusan; herhangi bir iş yapsanız, siz ona dalıp gitmişken biz üstünüzde mutlaka tanıklarız. Ne yerde ne gökte zerre ağırlığınca bir şey, ondan daha küçüğü de daha büyüğü de Rabbinden uzakta/gizli kalmaz; tümü apaçık bir kitaptadır."},{"n":62,"t":"Gözünüzü açın! Allah'ın velîleri için hiçbir korku yoktur. Tasaya da düşmezler onlar."},{"n":63,"t":"Onlar inanmış, takvaya sarılmışlardır."},{"n":64,"t":"Dünya hayatında da âhirette de müjde vardır onlara. Allah'ın kelimelerinde değişme/değiştirme olmaz. İşte budur o büyük kurtuluş."},{"n":65,"t":"Onların sözü seni üzmesin. Tüm onur ve kudret Allah'ındır. O her şeyi işitir, her şeyi bilir."},{"n":66,"t":"Gözünüzü açın! Göklerde kim var yerde kim varsa Allah'ındır! Allah'ın yanında başka şeylere yalvaranlar, ortak koştuklarına uymuyorlar/Allah'ın yanında ortaklara yalvaranlar neyin ardı sıra gidiyorlar? Onlar sadece sanıya uyuyorlar ve onlar sadece saçmalıyorlar."},{"n":67,"t":"O, odur ki, içinde durup dinlenesiniz diye sizin için geceye vücut verdi, gündüzü de aydınlık kıldı. Hiç kuşkusuz, bunda, dinleyecek bir topluluk için ibretler vardır."},{"n":68,"t":"\"Allah çocuk edindi!\" dediler. Hâşâ! Allah bundan arınmıştır! O Ganî'dir, hiçbir şeye muhtaç olmaz! Göklerdekiler de yerdekiler de O'nundur. Elinizde, söylediğinize ilişkin hiçbir kanıt yok. Allah hakkında bilmediğiniz şeyi mi söylüyorsunuz?"},{"n":69,"t":"De ki: \"Allah hakkında yalan düzüp iftira edenler iflah etmeyeceklerdir!\""},{"n":70,"t":"Dünyada biraz nimetlenme, ardından dönüşleri bize! Sonra biz, inkâr ettiklerinden ötürü şiddetli azabı onlara tattıracağız."},{"n":71,"t":"Onlara Nûh'un haberini de oku! Hani, toplumuna şöyle demişti: \"Eğer benim konumum ve Allah'ın ayetlerini hatırlatmam size ağır geliyorsa artık ben, Allah'a dayandım. Siz de ortaklarınızla bir araya gelip işinize bakın. Yapacağınız şey size bir kaygı da vermesin, hükmünüzü bana uygulayın. Ve bana fırsat da vermeyin.\""},{"n":72,"t":"\"Yüz çevirdiyseniz çevirin. Ben sizden bir ücret istemedim. Benim ücretim, Allah'tan gelecektir. Bana, müslümanlardan/Allah'a teslim olanlardan olmam emredildi.\""},{"n":73,"t":"Bunun üzerine, onu yalanladılar. Biz de onu ve gemide onunla beraber bulunanları kurtardık, onları yöneticiler yaptık; ayetlerimizi yalanlayanları da batırıp boğduk. Bak da gör, önceden uyarılanların sonu nice oluyor!"},{"n":74,"t":"Nûh'un ardından birçok resulleri daha toplumlarına gönderdik. Onlara açık-seçik kanıtlar getirdiler. Ama onlar daha önceden yalanladıkları şeye bir türlü inanmadılar. Azgınlığa sapanların kalplerini biz, işte böyle mühürleriz."},{"n":75,"t":"Onların ardından da Mûsa ile Hârun'u ayetlerimiz eşliğinde Firavun ve kurmaylarına gönderdik. Kibre saptılar ve günahkâr bir topluluk oldular."},{"n":76,"t":"Gerçek, katımızdan onlara geldiğinde şöyle demişlerdi: \"Hiç kuşkusuz, bu, apaçık bir büyüdür.\""},{"n":77,"t":"Mûsa dedi ki: \"Gerçek size ulaştığında böyle mi konuşuyorsunuz? Büyü müdür bu? Büyücülerin kurtuluşu yoktur.\""},{"n":78,"t":"Dediler ki: \"Sen bize, atalarımızı üzerinde bulduğumuz şeyden bizi çeviresin de bu toprakta devlet ve ululuk ikinizin olsun diye mi geldin? Biz, ikinize de inanmıyoruz.\""},{"n":79,"t":"Firavun seslendi: \"Tüm bilgin büyücüleri huzuruma getirin!\""},{"n":80,"t":"Büyücüler gelince, Mûsa onlara şöyle dedi: \"Ortaya koyma gücünde olduğunuz şöyleri sergileyin.\""},{"n":81,"t":"Onlar hünerlerini ortaya koyunca Mûsa dedi ki: \"Sergilediğiniz şey büyüdür. Allah onu mutlaka hükümsüz kılacaktır. Çünkü Allah, bozguncuların işini düzgün yürütmez.\""},{"n":82,"t":"\"Ve suçlular hoş görmese de Allah, hakkı, kelimeleriyle ortaya çıkarıp kanıtlayacaktır.\""},{"n":83,"t":"Firavun ve kodamanlarının kendilerine kötülük etmelerinden korktukları için, kavmi arasından bir gençlik grubu dışında hiç kimse Mûsa'ya inanmadı. Çünkü Firavun, o toprakta gerçekten çok üstündü ve gerçekten sınır tanımaz azgınlardan biriydi."},{"n":84,"t":"Mûsa dedi ki: \"Ey toplumum! Eğer Allah'a inanmışsanız, müslümanlarsanız/Allah'a teslim olanlarsanız yalnız Allah'a dayanıp güvenin!\""},{"n":85,"t":"Şöyle yakardılar: \"Yalnız Allah'a dayandık. Rabbimiz! Bizleri, zulmedenler toplumu için bir imtihan aracı yapma!\""},{"n":86,"t":"\"O küfre sapmış toplumdan rahmetinle bizi kurtar!\""},{"n":87,"t":"Mûsa'ya ve kardeşine şunu vahyettik: Kavminiz için kendilerini yerleştirmek üzere Mısır'da evler hazırlayın. Evlerinizi kıble yapın/karşılıklı yapın ve namazı/duayı yerine getirin! İnananlara müjde ver."},{"n":88,"t":"Mûsa şöyle dedi: \"Rabbimiz! Sen, Firavun ve kodamanlarına şu geçici hayatta debdebe verdin, mallar verdin. Rabbimiz! Senin yolundan saptırsınlar diye mi? Rabbimiz! Onların mallarını sil-süpür, kalplerini şiddetle sık ki, acıklı azabı görünceye kadar inanmasınlar!\""},{"n":89,"t":"Allah cevap verdi: \"İkinizin duası kabul edildi. Doğruluktan şaşmayın! İlimden nasipsizlerin yolunu izlemeyin!\""},{"n":90,"t":"Ve İsrailoğullarını denizden geçirdik. Firavun ve ordusu, azgınlık ve düşmanlıkla onları izlemekteydi. Nihayet, boğulma ümüğüne çökünce şöyle dedi: \"İman ettim. İsrailoğullarının inanmış olduğu dışında ilah yok. Ben de O'na teslim olanlardanım.\""},{"n":91,"t":"\"Şimdi mi? Daha önce isyan etmiş, bozgunculardan olmuştun.\""},{"n":92,"t":"\"Bugün senin bedenini kurtaracağız ki, arkandan gelenlere bir ibret olasın. Ama insanların çoğu bizim ayetlerimizden gerçekten habersiz bulunuyor.\""},{"n":93,"t":"Yemin olsun, biz, İsrailoğullarını çok güzel bir yurda yerleştirdik ve kendilerine temiz yiyeceklerden rızık verdik. Kendilerine ilim gelinceye kadar ihtilafa düşmediler. Hiç kuşkusuz, Rabbin, tartışmakta oldukları şey hakkında kıyamet günü aralarında hüküm verecektir."},{"n":94,"t":"Şayet sen, sana indirdiğimizden kuşkulanmakta isen, senden önce kitabı okuyanlara sor. Yemin olsun, hak sana Rabbinden gelmiştir. O halde, sakın kuşkulananlardan olma!"},{"n":95,"t":"Ve sakın ayetlerimizi yalanlayanlardan olma, yoksa hüsrana düşenlerden olursun."},{"n":96,"t":"Aleyhlerine Rabbinin kelimesi hak olanlar iman etmezler;"},{"n":97,"t":"Tüm ayetler onlara gelse bile. Ta, o korkunç azabı görünceye kadar."},{"n":98,"t":"Bir kent inansa da imanı kendisine yarar sağlasa ya! Yûnus'un kavmi müstesna. Onlar inanınca, dünya hayatında rezillik azabını üstlerinden kaldırmış ve kendilerini belirli bir süreye kadar nimetlendirmiştik."},{"n":99,"t":"Eğer Rabbin dileseydi, yeryüzündeki insanların tümü toplu halde mutlaka iman ederlerdi. Hal böyle iken, mümin olmaları için insanları sen mi zorlayacaksın!"},{"n":100,"t":"Allah'ın izni olmadıkça hiçbir benlik iman edemez. Allah, pisliği, aklını kullanmayanlar üzerine bırakır."},{"n":101,"t":"De ki: \"Göklerde ve yerde neler var/neler oluyor, bir bakın!\" O ayetler ve uyarılar iman etmeyen bir toplumun hiçbir işine yaramaz."},{"n":102,"t":"Onlar, sırf kendilerinden önce gelip geçenlerin günleri gibisini bekliyorlar. De ki: \"Bekleyin! Sizinle beraber ben de bekleyenlerdenim.\""},{"n":103,"t":"Sonunda biz, resullerimizi ve iman edenleri kurtarıyoruz. İşte böyledir. Üzerimize bir borç olarak, inananları kurtarırız."},{"n":104,"t":"De ki: \"Ey insanlar, benim dinimden kuşkuda iseniz, ben sizin Allah'ın berisinden kulluk ettiklerinize kulluk etmeyeceğim. Tam aksine ben, sizin canınızı alacak olan Allah'a kulluk edeceğim. Bana, müminlerden olmam emredildi.\""},{"n":105,"t":"Şu da emredildi: \"Yüzünü, bir hanîf olarak dine çevir. Sakın müşriklerden olma!\""},{"n":106,"t":"\"Allah'ın berisinden, sana yarar sağlamayacak ve zarar veremeyecek şeylere yakarma! Eğer bunu yaparsan mutlaka zalimlerden olursun.\""},{"n":107,"t":"Allah sana bir zarar dokundurursa, onu kaldıracak olan başkası değil, yine O'dur. O sana bir hayır dilerse, O'nun lütfunu reddedecek yoktur. Kullarından dilediğini lütfuyla nasiplendirir. Gafûr'dur O, Rahîm'dir."},{"n":108,"t":"De ki: \"Ey insanlar! Şu bir gerçek ki hak size Rabbinizden gelmiştir. Artık doğruya yönelen kendi benliği için yönelir; sapan da kendi benliği aleyhine sapar. Ben sizin üzerinize vekil değilim.\""},{"n":109,"t":"Sana vahyedilene uy ve Allah hüküm verinceye kadar sabret. O, hâkimlerin en hayırlısıdır."}],[{"n":1,"t":"Elif, Lâm, Râ. Hakîm ve Habîr olandan bir kitaptır ki bu, ayetleri önce muhkem kılınmış, sonra ayrıntılı hale getirilmiştir."},{"n":2,"t":"Ki başkasına değil, yalnız Allah'a ibadet edesiniz! Kuşkusuz, ben size O'ndan gelen bir uyarıcı ve müjdeciyim."},{"n":3,"t":"Af dileyin Rabbinizden; sonra da tövbe ile O'na yönelin ki, belirlenmiş bir süreye kadar sizi güzel bir nimetle nimetlendirsin ve her farklı derece sahibine hak ettiği ödülü versin. Eğer yüz çevirirseniz, o takdirde sizi büyük bir günün azabıyla korkuturum."},{"n":4,"t":"Yalnız Allah'adır dönüşünüz. Ve O, herşeye Kadîr'dir."},{"n":5,"t":"Dikkatle bakın! Onlar O'ndan gizlenmek için göğüslerini bükerler. Dikkat edin! Onlar giysileriyle sarılıp sarmaladıkları zaman da O, onların gizlemekte olduklarını da açığa vurduklarını da bilmektedir. Çünkü O, göğüslerin içini çok iyi bilendir."},{"n":6,"t":"Yerde hiçbir debelenen yoktur ki, rızkı Allah'ın üzerinde olmasın. O, onun karar kıldığı noktayı da bilir, emanet edildiği yeri de. Herşey, apaçık bir Kitap'tadır."},{"n":7,"t":"O, odur ki, gökleri ve yeri altı günde yaratmıştır. O'nun arşı da su üzerinde idi. Böyle yapması, iş ve davranış yönünden hanginizin daha güzel olduğunu belirlemek için sizi denemeye yöneliktir. Sen, \"Kuşkusuz, sizler ölümden sonra diriltileceksiniz!\" dediğinde, küfre batanlar hemen ve kesinlikle şöyle derler: \"Bu apaçık bir büyüden başka şey değildir.\""},{"n":8,"t":"Ve eğer onlardan azabı, belirlenmiş bir süreye kadar ertelesek, mutlaka şöyle diyeceklerdir: \"Onu erteleyen de ne?\" Gözünüzü açın, azap onlara geldiği gün, kendilerinden geri çevrilecek değildir. Ve alay edip durdukları şey, kendilerini sarmış olacaktır."},{"n":9,"t":"İnsana bizden bir rahmet tattırıp sonra onu ondan çekip alsak, insan elbette çok ümitsiz, çok nankör bir hale düşer."},{"n":10,"t":"Ve eğer ona, kendisine gelip çatan bir zorluk ve kederden sonra bolluk ve nimet tattırırsak, hiç kuşkusuz şöyle diyecektir: \"Tüm sıkıntı ve kötülükler benden uzaklaşmıştır.\" Bu durumda o, bir sevinç şımarığı, bir kendini beğenmiş olur."},{"n":11,"t":"Sabredip hayra ve barışa yönelik amel sergileyenler böyle yapmazlar. Bunlar kendileri için bir yarlıgama ve büyük bir ödül öngörülen kişilerdir."},{"n":12,"t":"Belki de sen; onlar, \"Ona bir hazine indirilseydi, yahut beraberinde bir melek gelseydi ya!\" diyorlar diye göğsün sıkışıp daralarak, sana vahyedilmekte olanının bir kısmını terk etmeye kalkarsın. Gerçek olan şu ki, sen sadece bir uyarıcısın. Allah ise her şey üzerinde bir Vekîl'dir."},{"n":13,"t":"Yoksa, \"Onu uydurdu\" mu diyorlar! De ki: \"Öyleyse hadi, onun benzeri, uydurma on sure de siz getirin; eğer doğru sözlüler iseniz, Allah'tan başka çağırabildiklerinizi de çağırın.\""},{"n":14,"t":"Eğer size cevap veremedilerse artık bilin ki o, ancak Allah'ın ilmiyle indirilmiştir. Ve O'ndan başka da ilah yoktur. Artık müslüman oluyor/Allah'a teslim oluyor musunuz?"},{"n":15,"t":"Her kim iğreti hayatı ve onun süsünü isterse böylelerinin yapıp ettiklerinin karşılığını kendilerine bu hayatta tam olarak veririz. Onlar dünyada hiçbir eksiltmeye uğratılmazlar."},{"n":16,"t":"Öyleleridir ki bunlar, âhirette kendileri için ateşten başkası yoktur. Sanayi olarak ürettikleri, orada işe yaramaz olmuştur. Yapıp ettikleri de bâtıl hale gelmiştir."},{"n":17,"t":"Böyleleri şu kimse gibi olur mu: Rabbinden bir beyyine üzerinedir, O'ndan bir tanık da kendisini izler. Tanıktan önce de bir kılavuz ve rahmet olarak Mûsa'nın kitabı var. Onlar ona inanırlar. Hiziplerden onu inkâr edenin varış yeri ateştir. Ondan asla kuşkuya düşme; o Rabbinden bir haktır ama insanların çokları inanmıyorlar."},{"n":18,"t":"Yalan düzerek Allah'a iftira edenden daha zalim kim var? Onlar Rablerine arz edilecekler. Tanıklar diyecekler ki: \"İşte bunlardır Rableri hakkında yalan uyduranlar.\" Herkes duysun ki, Allah'ın laneti zalimler üstünedir."},{"n":19,"t":"O zalimler ki, Allah'ın yolundan alıkoyar, o yolu yamultmak isterler. Onlar, âhireti de inkâr ederler."},{"n":20,"t":"Bunlar yeryüzünde kimseyi âciz bırakamazlar. Allah'tan başka hiçbir dostları da yoktur. Onlara azap kat kat verilecektir. Hem işitmeye güçleri yetmiyordu hem de göremiyorlardı."},{"n":21,"t":"İşte bunlardır öz benliklerini hüsrana uğratanlar. İftira için kullandıkları şeyler de kendilerini bırakıp kaybolmuştur."},{"n":22,"t":"Hiç kuşku yok ki bunlar, âhirette de hüsranın en beterine uğrayanlar olacaklardır."},{"n":23,"t":"İman edip hayra ve barışa yönelik işler yaparak Rablerine içten bir bağlılıkla boyun eğenlere gelince, onlar cennet halkıdırlar. Sürekli kalacaklardır orada."},{"n":24,"t":"Bu iki topluluğun durumu körle sağır, görenle işiten farkına benzer. Örnek olarak bu ikisi bir olur mu? Hâlâ düşünüp taşınıyor musunuz?"},{"n":25,"t":"Yemin olsun biz, Nûh'u da toplumuna resul olarak göndermiştik. \"Ben sizin için açık bir uyarıcıyım.\""},{"n":26,"t":"\"Allah'tan başkasına kulluk etmeyin. Korkunç bir gününün azabına uğramanızdan korkuyorum.\" demişti de,"},{"n":27,"t":"Toplumunun küfre sapanlarından bir grup kodaman şöyle konuşmuştu: \"Bize göre sen, bizim gibi bir insandan başkası değilsin. Bakıyoruz sana, ayak takımımızın basit görüşlü insanlarından başkası ardına düşmüyor. Sizin bize hiçbir üstünlüğünüzün olduğuna inanmıyoruz. Aksine, sizi yalancılar sayıyoruz.\""},{"n":28,"t":"Nûh dedi ki: \"Ey toplumum! Bir düşünün! Ya ben Rabbimden gelen bir beyyine üzerindeysem; katından bana bir rahmet vermiş de o rahmet sizin gözlerinizden saklanmışsa! Siz ona tiksintiyle bakarken, biz sizi ona zorla mı ulaştıracağız?\""},{"n":29,"t":"\"Hem ben sizden buna karşı bir mal da istemiyorum. Benim ücretim Allah'tandır. Ama ben iman edenleri paylayıp kovamam. Çünkü onlar Rablerine varacaklar. Ama sizin cehalete batmış bir toplum olduğunuzu görüyorum.\""},{"n":30,"t":"\"Ey toplumum! Eğer ben onları paylayıp kovarsam, Allah'a karşı bana kim yardım edebilir? Hâlâ düşünmüyor musunuz?\""},{"n":31,"t":"\"Ben size demiyorum ki, Allah'ın hazineleri benim yanımdadır. Ben gaybı bilmem. Ben bir meleğim de demiyorum. Ama gözlerinizin horlayarak baktığı kişiler için, 'Allah bunlara hiçbir hayır vermeyecek' diyemem. Onların benliklerinde neyin saklı olduğunu Allah daha iyi bilir. Başka türlü davranırsam kesinlikle zalimlerden olurum.\""},{"n":32,"t":"Dediler ki: \"Ey Nûh! Sen bizimle uğraştın, bizimle mücadelede çok da ileri gittin. Eğer doğru sözlülerden isen bizi tehdit ettiğin şeyi ortaya getir.\""},{"n":33,"t":"Nûh dedi: \"Onu size, dilediği takdirde ancak Allah getirir, siz de hiçbir engel çıkaramazsınız.\""},{"n":34,"t":"\"Eğer Allah sizi azdırmak istiyorsa, ben size öğüt vermeyi gaye edinsem de öğüdüm size hiçbir yarar sağlamaz. O'dur sizin Rabbiniz ve O'na döndürüleceksiniz.\""},{"n":35,"t":"Yoksa, \"Onu kendisi mi uydurdu\" diyorlar? De ki: \"Eğer onu uydurmuşsam işlediğim suç benim aleyhimedir. Ama ben, sizin işlemekte olduğunuz suçlardan sorumlu değilim.\""},{"n":36,"t":"Nûh'a şöyle vahyolundu: \"Toplumundan, daha önce inanmış olanlar dışında hiç kimse iman etmeyecektir. Artık onların yaptıkları yüzünden tasalanıp durma.\""},{"n":37,"t":"Vahyimize bağlı olarak gözlerimizin önünde gemiyi yap. Ve zulmedenler hakkında benimle karşılıklı laf edip durma. Onlar, mutlaka boğulacaklardır."},{"n":38,"t":"Gemiyi yapıyordu. Toplumundan herhangi bir grup yanından geçtikçe onunla alay ediyorlardı. Dedi ki Nûh \"Bizimle alay ediyorsanız, biz de sizinle alay edeceğiz. Tıpkı sizin eğlendiğiniz gibi.\""},{"n":39,"t":"\"Rezil eden azabın kime geleceğini, sürekli azabın kimin başına ineceğini yakında bileceksiniz.\""},{"n":40,"t":"Nihayet emrimiz gelip de tandır kaynayınca şöyle seslendik: \"Yükle içine her birinden ikişer çift ve aleyhinde hüküm verilen hariç olmak üzere aileni, bir de iman etmiş olanları.\" Ama Nûh'la birlikte çok az bir kısmı iman etmişti."},{"n":41,"t":"Nûh dedi: \"Binin içine! Onun akıp gitmesi de demir atması da Allah'ın adıyladır. Benim Rabbim elbette ki Gafûr'dur, Rahîm'dir.\""},{"n":42,"t":"Gemi onları, dağlar gibi dalgalar üstünden yürütüp götürüyordu. Nûh onlardan ayrı bir yerde duran oğluna seslendi: \"Oğulcuğum, bizimle beraber bin, kâfirlerle beraber olma.\""},{"n":43,"t":"Oğlu cevap verdi: \"Bir dağa sığınacağım, beni sudan korur.\" Nûh dedi: \"Allah'ın merhamet ettiği dışında bugün hiç kimse için Allah'ın kararından kurtaracak yoktur.\" Ve ikisi arasına dalga girdi de o, boğulanlar arasına katıldı."},{"n":44,"t":"Ve denildi: \"Ey yer! Suyunu yut ve ey gök, sen de tut.\" Ve su çekildi. İş bitirilmişti. Gemi, Cûdi üzerine oturdu ve haykırıldı: \"O zalimler topluluğu geri gelmez olsun!\""},{"n":45,"t":"Bu arada Nûh, Rabbine yakardı da dedi ki: \"Rabbim, oğlum benim ailemdendi! Senin vaadin elbette haktır. Sen hâkimlerin, hükmü en güzel verenisin.\""},{"n":46,"t":"Allah buyurdu: \"Ey Nûh! O, senin ailenden değildi. Yaptığı, iyi olmayan bir işti. Hakkında bilgin olmayan şeyi benden isteme. Cahillerden olmaman hususunda seni uyarırım.\""},{"n":47,"t":"Nûh dedi: \"Rabbim! Hakkında bilgim olmayan şeyi senden istemekten sana sığınırım. Eğer beni affetmez, bana acımazsan hüsrana uğrayanlardan olurum.\""},{"n":48,"t":"Şöyle denildi: \"Ey Nûh! Sana ve seninle beraber olanlardan diğer gruplara bizden bereketler ve bir selamla aşağıya in. Bazı ümmetler de var, kendilerini önce nimetlendireceğiz sonra bizden acıklı bir azap hepsini kucaklayacak.\""},{"n":49,"t":"İşte bunlar, sana vahyetmekte olduğumuz gayb haberlerindendir. Bundan önce onları sen de bilmiyordun, toplumun da... Artık sabırlı ol! Sonuç, takvaya sarılanlarındır."},{"n":50,"t":"Âd'a da kardeşleri Hûd'u gönderdik. Dedi ki: \"Ey toplumum! Allah'a kulluk edin. Sizin O'ndan başka ilahınız yok. Siz sadece uydurmalara bel bağlamışsınız.\""},{"n":51,"t":"\"Ey toplumum! Bu tebliğime karşılık sizden bir ücret istemiyorum. Benim ücretim, beni yaratandan başkasına düşmez. Hâlâ aklınızı çalıştırmayacak mısınız?\""},{"n":52,"t":"\"Ey toplumum! Rabbinizden af dileyin, sonra O'na yönelin ki üzerinize göğü bol bol göndersin, kuvvetinize kuvvet katsın. Günahkârlar olup da Allah'tan yüz çevirmeyin.\""},{"n":53,"t":"Dediler ki: \"Ey Hûd! Bize hiçbir kanıt getirmedin. Senin sözünle ilahlarımızı terk edecek değiliz. Zaten biz sana inanmıyoruz.\""},{"n":54,"t":"\"Sadece şunu söylüyoruz: 'İlahlarımızdan biri seni kötü çarpmış.\" Hûd dedi: \"Ben Allah'ı tanık tutuyorum, siz de tanık olun ki, ben sizin Allah'a ortak yaptıklarınızdan uzağım.\""},{"n":55,"t":"\"Allah dışındaki tanrılarınızdan uzağım. Hadi, hep birlikte bana tuzak kurun, bana hiç göz açtırmayın.\""},{"n":56,"t":"\"Ben, benim de Rabbim, sizin de Rabbiniz olan Allah'a dayanıp güvendim. Hiçbir canlı yoktur ki O, onu perçeminden yakalamış olmasın. Hiç kuşkusuz benim Rabbim dosdoğru bir yol üzerindedir.\""},{"n":57,"t":"\"Eğer yüz çevirirseniz ben, bana gönderilen şeyi size tebliğ etmiş bulunuyorum. Rabbim, yerinize başka bir topluluk getirir ve siz O'na hiçbir şekilde zarar veremezsiniz. Kuşkusuz benim Rabbim herşey üzerinde bir Hafîz'dir; kollar, gözetir.\""},{"n":58,"t":"Emrimiz gelince, Hûd'u ve onunla birlikte iman etmiş olanları bizden bir rahmetle kurtardık. Biz onları çok ağır bir azaptan kurtardık."},{"n":59,"t":"İşte buydu Âd. Rablerinin ayetlerine kafa tuttular, O'nun resullerine isyan ettiler. Ve her inatçı zorbanın emrine uydular."},{"n":60,"t":"Bu dünyada ve kıyamet gününde arkalarına lanet takıldı. Dikkat edin; Âd, Rablerine nankörlük etmişti. Dikkat edin, Hûd'un kavmi olan Âd geri gelmez oldu."},{"n":61,"t":"Semûd'a da kardeşleri Sâlih'i gönderdik. Dedi ki: \"Ey toplumum! Allah'a kulluk edin. Sizin O'ndan başka ilahınız yok. Sizi topraktan oluşturan ve size orada ömür geçirten O'dur. Artık O'ndan af dileyin, O'na dönün. Rabbim Karîb'dir, bize çok yakındır; Mucîb'dir, bize cevap verir.\""},{"n":62,"t":"Dediler ki: \"Ey Sâlih! Sen bundan önce, aramızda aranan/ümit beslenen bir kişi idin. Şimdi kalkmış, atalarımızın kulluk ettiklerine kulluk etmemizi mi yasaklıyorsun? Gerçek şu ki biz, bizi çağırdığın şey hakkında kafaları karıştıran bir kuşku içindeyiz.\""},{"n":63,"t":"Dedi ki: \"Ey kavmim! Hiç düşündünüz mü? Ya ben Rabbimden bir beyyine üzerindeysem, bana kendisinden bir rahmet sunmuşsa! Bu durumda ben O'na isyan edersem, bana Allah'a karşı kim yardım eder? Sizin bana, yıkım ve hüsranı artırmak dışında bir katkınız olamaz.\""},{"n":64,"t":"\"Ey toplumum! İşte şu size, Allah'ın bir mucize olan devesi. Rahat bırakın onu. Allah'ın toprağında karnını doyursun. Bir kötülük dokundurmayın ona. Yoksa sizi çok yakın bir azap yakalayıverir.\""},{"n":65,"t":"Ama deveyi yere yıkıp kestiler. Sâlih dedi ki: \"Yurdunuzda üç gün daha nimetlenin. Bu, yalanlanamayacak bir tehdittir.\""},{"n":66,"t":"Emrimiz gelince Sâlih'i ve onunla birlikte iman edenleri bizden bir rahmetle kurtardık. O günün rezilliğinden kurtardık. Senin Rabbin, evet O, Kavî'dir, Azîz'dir."},{"n":67,"t":"Zulme sapmış olanları o korkunç titreşimli ses yakaladı da öz yurtlarında yere çökmüş hale getirdiler."},{"n":68,"t":"Sanki hiç hayat sürmemişlerdi orada. Dikkat edin! Semûd kavmi, Rablerine nankörlük etmişti. Dikkat edin, Semûd geri dönmez olmuştur."},{"n":69,"t":"Yemin olsun, resullerimiz İbrahim'e muştu getirip \"Selam!\" demişlerdi. O da \"Selam!\" demiş, fazla beklemeden kızartılmış bir buzağı getirmişti."},{"n":70,"t":"Ellerinin ona ulaşmadığını görünce onlardan işkillendi. Ve kendilerinden ürpermeye başladı. \"Korkma, dediler, biz Lût kavmine gönderildik.\""},{"n":71,"t":"Orada dikilmekte olan karısı güldü. Bunun üzerine ona İshak'ı müjdeledik, İshak'ın arkasından da Yakub'u."},{"n":72,"t":"\"Vay başıma, dedi. Doğuracak mıyım ben? Kendim bir kocakarı, kocam bir ihtiyar. Gerçekten şaşılacak şey bu.\""},{"n":73,"t":"Dediler ki: \"Allah'ın emrine mi şaşıyorsun? Allah'ın rahmeti ve bereketleri üzerinizdedir ey ev halkı! O Hamîd'dir, Mecîd'dir.\""},{"n":74,"t":"İbrahim'den korku gidip yerine müjde gelince, Lût kavmi hakkında bizimle tartışır oldu."},{"n":75,"t":"İbrahim, gerçekten yufka yürekli bir insandı; herkes için ah eder, içini çekerdi, yalvarıp yakarırdı."},{"n":76,"t":"\"Ey İbrahim! Bu halinden vazgeç. Rabbinin emri gelmiştir. Geri çevrilemez bir azap onların enselerine binecektir.\""},{"n":77,"t":"Elçilerimiz Lût'a geldiğinde onlar için kaygılanmış, göğsü daralmış da şöyle demişti: \"Bu, zorlu bir gün!\""},{"n":78,"t":"Lût'un kavmi koşarak onun yanına geldi. Bunlar daha önce de kötülükler yapmışlardı. Lût dedi ki: \"Ey toplumum! İşte şunlar kızlarım. Onlar sizin için daha temiz. Allah'tan korkun da misafirlerim önünde beni rezil etmeyin. İçinizde olgun bir adam yok mu?\""},{"n":79,"t":"Dediler ki: \"Senin kızlarında hakkımız olmadığını çok iyi biliyorsun. Ne istediğimizi de çok iyi biliyorsun.\""},{"n":80,"t":"Dedi: \"Ah, size karşı koyacak bir gücüm olsaydı yahut sağlam bir kaleye sığınabilseydim.\""},{"n":81,"t":"Melekler dediler: \"Biz senin Rabbinin elçileriyiz. Sana asla el süremezler. Gecenin bir yerinde aileni götür. İçinizden hiç kimse geri kalmasın; karın müstesna. O, ötekilere çatan belaya çarptırılacaktır. Onların azap vakti, sabah vaktidir. Sabah da ne kadar yakın, değil mi?\""},{"n":82,"t":"Nihayet emrimiz gelince oranın üstünü altına getirdik. Ve üzerlerine, pişirilmiş çamurdan yapılıp istif edilmiş taş yağdırdık."},{"n":83,"t":"Rabbin katında damgalanmış taşlar. Zalimlerden çok uzak değildir bu."},{"n":84,"t":"Medyen'e, kardeşleri Şuayb'ı göndermiştik. Dedi ki: \"Ey toplumum! Allah'a kulluk edin. O'ndan başka tanrınız yok sizin. Eksik ölçüp yanlış tartmayın. Sizi nimet-bereket içinde görüyorum, ama sizin için sarıp kuşatan bir günün azabından da korkuyorum.\""},{"n":85,"t":"\"Ey toplumum! Ölçüyü ve tartıyı tam bir dürüstlükle yapın. İnsanların eşyalarını tırtıklamayın. Yeryüzünde bozgunculuk yaparak dolaşmayın.\""},{"n":86,"t":"\"Eğer inananlar iseniz, Allah'ın bıraktığı kâr sizin için daha hayırlıdır. Ben sizin üzerinizde bir bekçi değilim.\""},{"n":87,"t":"Dediler ki: \"Ey Şuayb! Namazın/duan mı emrediyor sana, atalarımızın tapar olduğunu terk etmemizi yahut mallarımızda dilediğimiz gibi davranmaktan vazgeçmemizi? Esasında sen; gerçekten yumuşak huylu, olgun bir insansın.\""},{"n":88,"t":"Dedi: \"Ey toplumum! Ya ben Rabbimden bir beyyine üzerindeysem, bana, lütfundan güzel bir rızık vermişse!... Size yasakladığım şeylerde, size söylediğimin aksine davranmak istemiyorum. Gücüm ölçüsünde barış ve iyilikten başka bir şey de istemiyorum. Başarım ancak Allah'ın desteğiyledir. Yalnız O'na güvendim ben, yalnız O'na yöneliyorum.\""},{"n":89,"t":"\"Ey toplumum! Bana kafa tutmanız, sakın sizi Nûh kavminin yahut Hûd kavminin yahut Sâlih kavminin başlarına gelen musibetle yüz yüze getirmesin. Lût kavmi de sizden pek uzak değil.\""},{"n":90,"t":"\"Rabbinizden af dileyip O'na yönelin. Rabbim Rahîm'dir, rahmeti sınırsızdır; Vedûd'dur, çok sevgilidir.\""},{"n":91,"t":"Dediler ki: \"Ey Şuayb! Söylediklerinin birçoğunu anlamıyoruz. Ve biz seni aramızda zayıf bir adam olarak görüyoruz. Hani, kabilen olmasa, kafanı taşla ezivereceğiz. Senin bize karşı hiçbir üstünlüğün yok.\""},{"n":92,"t":"Dedi: \"Ey toplumum! Sizce kabilem Allah'tan daha mı güçlü ve onurlu! Allah'ı arkanıza atıp dışlanmış hale getirdiniz. Rabbim, yapıp ettiklerinizi çepeçevre kuşatmıştır.\""},{"n":93,"t":"\"Ey toplumum! Elinizden geleni yapın, ben görevimi yapıyorum. Yakında bileceksiniz rezil edici bir azabın kime geleceğini, yalancının kim olduğunu! Gözetleyin, ben de sizinle beraber gözetliyorum.\""},{"n":94,"t":"Emrimiz gelince Şuayb'ı ve onunla birlikte iman edenleri bizden bir rahmetle kurtardık. Zulmedenleri o yüksek titreşimli sayha yakaladı da öz yurtlarında yere çömelmiş hale geldiler."},{"n":95,"t":"Sanki hiç yurt tutmamışlardı orada. Bakıp görün ki, Medyen de tıpkı Semûd gibi, dönüşü olmayan bir gidişle gitti."},{"n":96,"t":"Yemin olsun, Mûsa'yı ayetlerimizle ve açık bir kanıtla gönderdik;"},{"n":97,"t":"Firavun'a ve kodamanlarına. Ama onlar Firavun'un emrine uydular. Oysaki, Firavun'un emri doğruya ve güzele ulaştırmıyordu."},{"n":98,"t":"Kıyamet günü kavmine önderlik eder. İşte onları suya götürür gibi ateşe götürdü. Ne kötü varış yeridir o götürüldükleri yer!"},{"n":99,"t":"Peşlerine lanet takılmıştır: Hem burada hem kıyamet gününde ne kötü destektir o arkalarına takılmış olan!"},{"n":100,"t":"İşte bunlar o kentlerin/medeniyetlerin haberlerinden bir kısmı, anlatıyoruz sana. Kimi hâlâ ayakta onların, kimi kökünden biçilip gitmiştir."},{"n":101,"t":"Onlara biz zulmetmedik. Ama onlar kendilerine zulmettiler. Rabbinin emri geldiğinde, Allah'ı bırakıp da yakardıkları ilahları kendilerine hiçbir yarar sağlamadı. İlahları onların sadece hasar ve hüsranlarını artırdı."},{"n":102,"t":"Rabbin zulme sapan kentleri/medeniyetleri çarptığı zaman, işte böyle çarpar. O'nun çarpması gerçekten korkunçtur, şiddetlidir."},{"n":103,"t":"Âhiret azabından korkan için bunda elbette ki bir ibret vardır. O, insanları bir araya getiren bir gündür. Görülesi bir gündür o!"},{"n":104,"t":"Biz onu, sadece belirli bir süre için erteliyoruz."},{"n":105,"t":"O geldiği gün hiçbir benlik, O'nun izni olmadan söz söyleyemez. Onların bir kısmı bahtsız, bir kısmı mutludur."},{"n":106,"t":"Bahtsızlığa düşenler ateş içindedir. Çok ıstıraplı bir soluyuş ve hıçkırışları vardır orada."},{"n":107,"t":"Rabbinin dilemesi hariç, gökler ve yer durdukça onlar orada hep kalacaklardır. Rabbin, dilediğini öyle bir yerine getirir ki!..."},{"n":108,"t":"Mutluluğa erdirilenlere gelince, onlar cennettedirler. Rabbinin dilemesi hariç, gökler ve yer durdukça onlar, hep orada kalacaklardır. Kesintisiz bir lütuf olarak..."},{"n":109,"t":"Şunların kulluk etmekte oldukları şeyler yüzünden bir kuşku içine girme. Daha önce atalarının kulluk ettikleri gibi kulluk ediyorlar, hepsi bu. Biz onların da nasiplerini hiç eksiltmeden elbette vereceğiz."},{"n":110,"t":"Yemin olsun, Mûsa'ya Kitap'ı verdik de onda da ihtilafa düşüldü. Rabbinden bir kelime, önceden gelmiş olmasaydı, aralarında iş mutlaka bitirilirdi. Onlar bunun hakkında, kafaları karıştıran bir kuşku içindedirler."},{"n":111,"t":"Hiç kuşkusuz, Rabbin hepsinin amellerinin karşılığını tam tamına kendilerine verecektir. O, onların yapmakta olduklarından haberdardır."},{"n":112,"t":"O halde sen, emrolunduğun gibi dosdoğru yürü! Seninle birlikte tövbe edenler de... Sakın aşırılık edip azmayın! O, yapmakta olduklarınızı görüyor."},{"n":113,"t":"Zulmedenlere eğilim göstermeyin! Yoksa ateş sizi sarmalar. Allah'tan başka dostlarınız kalmaz, size yardım de edilmez."},{"n":114,"t":"Gündüzün iki tarafında ve geceye yakın saatlerde namazı/duayı yerine getir. Güzellikler kötülükleri silip süpürür. İşte bu, Allah'ı ananlara bir öğüttür."},{"n":115,"t":"Sabret! Allah, güzel düşünüp güzel davrananların ödülünü yitirmez."},{"n":116,"t":"Sizden önceki kuşakların söz ve eser sahibi olanları, yeryüzünde bozgunculuktan alıkoymalı değiller miydi? Ama içlerinden kurtarmış olduklarımızın az bir kısmı dışında hiçbiri bunu yapmadı. Zulme sapanlar ise içine gömüldükleri servet şımarıklığının ardına düşüp suçlular haline geldiler."},{"n":117,"t":"Halkı iyilik ve barış sevenler olsaydı, Rabbin o kentleri/medeniyetleri zulümle helâk edecek değildi ya!"},{"n":118,"t":"Eğer Rabbin dileseydi insanları elbette ki bir tek ümmet yapardı. Ama birbirleriyle çekişmeye devam edeceklerdir."},{"n":119,"t":"Rabbinin rahmet ettikleri müstesna. O, onları işte bunun için yaratmıştır. Rabbinin, \"Yemin olsun ben cehennemi, tümden insanlar ve cinlerle dolduracağım!\" sözü tamamlanacaktır."},{"n":120,"t":"Resullerin haberlerinden, kendisiyle kalbini destekleyip sağlamlaştıracağımız her şeyi sana anlatıyoruz. Bunun içinde sana hak gelmiştir. Bunda, inananlar için bir öğüt ve hatırlatma da vardır."},{"n":121,"t":"İnanmayanlara de ki: \"Yapabildiğinizi yapın, biz de işimizi yapıyoruz.\""},{"n":122,"t":"\"Bekleyin, biz de bekliyoruz!\""},{"n":123,"t":"Göklerin ve yerin gizli bilgileri Allah'a aittir. Tüm iş ve oluş O'na döndürülür. O halde O'na kulluk et, O'na dayanıp güven! Rabbin, yapmakta olduklarınızdan habersiz değildir."}],[{"n":1,"t":"Elif, Lâm, Râ. O apaçık, apaydınlık Kitap'ın ayetleridir bunlar."},{"n":2,"t":"Biz onu sana, aklınızı çalıştırasınız diye, Arapça bir Kur'an olarak indirdik."},{"n":3,"t":"Biz bu Kur'an'ı sana vahyederek, hikâyelerin en güzelini anlatıyoruz. Oysaki sen, bundan önce bunlardan tamamen habersiz olanlardandın."},{"n":4,"t":"Bir vakit Yûsuf babasına şöyle demişti: \"Babacığım, ben rüyada on bir yıldızla, Güneş'i ve Ay'ı gördüm; onları bana secde ediyorlar gördüm.\""},{"n":5,"t":"\"Yavrucuğum, dedi, rüyanı kardeşlerine anlatma; sonra sana bir oyun oynarlar. Hiç kuşkusuz şeytan, insan için açık bir düşmandır.\""},{"n":6,"t":"İşte böyle! Rabbin seni seçip yüceltecek, olayların ve sözlerin tevilinden, sana birşeyler öğretecek, hem senin hem Yakub soyunun üzerinde nimetini tamamlayacaktır. Tıpkı bundan önce ataların İbrahim ve İshak üzerine o nimeti tamamladığı gibi. Şu kesin ki, senin Rabbin Alîm'dir, Hakîm'dir."},{"n":7,"t":"Yemin olsun ki, Yûsuf ve kardeşlerinde istek ve arayış içinde olanlar için ibretler/işaretler vardır."},{"n":8,"t":"O vakit onlar şöyle demişlerdi: \"Yûsuf ve kardeşi, babamıza bizden daha sevimli, bu bir gerçek. Ama biz de birbirini her hal ve şartta destekleyen bir ekibiz. Şu da kuşkusuz ki, bizim babamız, inkâr edilemez bir şaşkınlık içindedir.\""},{"n":9,"t":"\"Yûsuf'u öldürün yahut bir yere götürüp atın ki, babanızın ilgisi yalnız size yönelsin ve bunun ardından barışcıl ve hayırsever bir topluluk haline gelesiniz.\""},{"n":10,"t":"İçlerinden söz alan biri şöyle konuştu: \"Yûsuf'u öldürmeyin. Onu bir kuyunun dibine bırakın; gelip geçen kafilelerden biri onu bulup alır. Yapacaksanız böyle yapın!\""},{"n":11,"t":"Dediler ki: \"Ey babamız, ne oluyor da Yûsuf konusunda bize güvenmiyorsun. Oysaki biz ona hep öğüt vermekteyiz.\""},{"n":12,"t":"\"Yarın onu bizimle gönder, gezip oynasın. Kuşkun olmasın biz onu çok güzel korur, gözetiriz.\""},{"n":13,"t":"Dedi ki: \"Onu götürmeniz beni çok çok üzer. Ve korkarım ki siz ondan habersiz bir haldeyken onu kurt yer.\""},{"n":14,"t":"Dediler ki: \"Vallahi biz böylesine dayanışma içinde bir ekipken onu kurt yerse, o takdirde biz hüsrana uğrayan kişiler oluruz.\""},{"n":15,"t":"Onu götürüp kuyunun dibine koymaya karar verdiklerinde biz de ona şöyle vahyettik: Yemin olsun ki sen onlara, şu yaptıklarını hiç farkında olmayacakları bir sırada haber vereceksin.\""},{"n":16,"t":"Akşamdan sonra babalarına geldiler; ağlıyorlardı."},{"n":17,"t":"\"Ey babamız, dediler, gittik, yarışıyorduk; Yûsuf'u eşyamızın yanında bırakmıştık, kurt onu yemiş. Şimdi biz doğru da söylesek sen bize inanmayacaksın.\""},{"n":18,"t":"Yûsuf'un gömleği üstüne sahte bir kan çalmışlardı, getirdiler. Babaları dedi ki: \"İş, söylediğiniz gibi değil. Nefisleriniz sizi aldatıp bir işe itmiş. Artık bana düşen, güzelce sabretmek. Anlattıklarınıza karşı yalnız Müsteân olan Allah'tan yardım istenir.\""},{"n":19,"t":"Bir yolcu kafilesi gelmişti. Sucularını gönderdiler. O da kovasını sarkıttı. \"Müjde! Bu bir oğlan!\" diye haykırdı. Ticaret maksadıyla onu sakladılar. Allah ne yaptıklarını çok iyi biliyordu."},{"n":20,"t":"Onu basit bir karşılıkla, birkaç paraya sattılar. Onlar, ona değer vermeyen kişilerdi."},{"n":21,"t":"Onu satın alan Mısırlı, karısına şöyle dedi: \"Ona iyi bak, kendisine güzel bir yer hazırla. Bize yararı dokunabilir. Belki de evlat ediniriz onu.\" İşte bu şekilde biz Yûsuf'a yeryüzünde imkân verip o toprağa yerleştirdik ki, ona olayların/haberlerin yorumunu öğretelim. Allah, kendi emrine Gâlib'dir/kendi emrine hükmeder. Ama insanların çokları bilmiyorlar."},{"n":22,"t":"Yûsuf gerekli olgunluğa ulaşınca ona hükmetme yeteneği ve ilim verdik. Güzel düşünüp güzel davrananları biz işte böyle ödüllendiririz."},{"n":23,"t":"Yûsuf'un, evinde kaldığı kadın, onun nefsinden gönlünü tatmin etmek istedi. Kapıları kilitledi, \"Hadi gel!\" dedi. Yûsuf: \"Allah'a sığınırım, Rabbim beni güzel bir barınağa kavuşturmuştur. Zalimler iflah etmez.\" dedi."},{"n":24,"t":"Yemin olsun, kadın onu arzulamıştı. Eğer Rabbinin gerçeğe dikkat çeken delilini görmeseydi, o da onu arzulamıştı. Biz böylece ondan, kötülüğü ve fuhşu uzak tutuyorduk. Çünkü o, bizim samimi/seçkin kullarımızdandı."},{"n":25,"t":"İkisi birden kapıya koştular. Kadın onun gömleğini arkadan yırttı. Kapının yanında kadının beyi ile yüzyüze geldiler. Kadın seslendi: \"Senin ailene kötülük düşünenin cezası nedir; hapsedilmek mi, acıklı bir işkence mi?\""},{"n":26,"t":"Yûsuf dedi ki: \"O, gönlünü eğlendirmek için beni kullanmak istedi.\" Kadının ailesinden bir tanık da şu yolda tanıklık etti: \"Eğer erkeğin gömleği önden yırtılmışsa kadın doğru söylüyor, bu durumda erkek yalancılardandır."},{"n":27,"t":"Eğer erkeğin gömleği arkadan yırtılmışsa kadın yalan söylemiştir. Bu durumda erkek, doğru sözlülerdendir.\""},{"n":28,"t":"Gömleğin arkadan yırtılmış olduğunu görünce şöyle konuştu: \"Bu sizin tuzaklarınızdandır. Sizin tuzaklarınız gerçekten çok yamandır.\""},{"n":29,"t":"\"Yûsuf, sakın bundan bahsetme! Kadın, sen de günahının affını dile! Sen, gerçekten günahkârlardan oldun.\""},{"n":30,"t":"Şehirde bazı kadınlar şöyle konuştular: \"Azîz'in karısı, genç uşağının nefsinden gönlünü eğlendirmek istemiş. Aşktan yüreğinin zarı delinmiş. Öyle anlıyoruz ki, kadın tam bir çılgınlığa düşmüş.\""},{"n":31,"t":"Kadın onların oyunlarını işitince, onlarla haber gönderdi. Kendilerine, yaslanarak yiyebilecekleri bir sofra hazırladı ve her birine bir bıçak verdi. Yûsuf'a: \"Karşılarına çık!\" dedi. Nihayet Yûsuf'u görünce onu öylesine yücelttiler ki, kendilerinin ellerini kestiler. Şöyle dediler: \"Aman Allahım! Bu bir insan değil; asil bir melek bu!\""},{"n":32,"t":"Kadın dedi ki: \"İşte budur o, hakkında beni kınadığınız. Vallahi, ben onunla gönlümü eğlendirmek istedim de o masum bir tavırla bundan çekindi. Ama, eğer kendisine emrettiğimi yapmazsa yemin ediyorum hapse tıkılacak ve horlananlardan olacaktır.\""},{"n":33,"t":"Yûsuf dedi: \"Rabbim! Zından benim için bunların beni çağırdığı şeyden daha sevimlidir. Eğer onların oyununu benden uzak tutmazsan onlara meyleder de cahillerden olurum.\""},{"n":34,"t":"Rabbi onun duasını kabul etti de kadınların tuzaklarını ondan uzaklaştırdı. Her şeyi duyar O, her şeyi bilir."},{"n":35,"t":"Bunca delili gördükten sonra bile Yûsuf'u bir süreye kadar zındana tıkmaları kararı onlara egemen oldu."},{"n":36,"t":"Onunla birlikte zındana iki genç daha girmişti. Bir tanesi dedi ki: \"Rüyada gördüm, şarap sıkıyordum.\" Öteki de şöyle dedi: \"Ben de gördüm ki, başımın üstünde ekmek taşıyorum, kuşlar ondan yiyor. Bunun yorumunu bize bildir. Biz senin, güzel düşünüp güzel davrananlardan olduğun kanısındayız.\""},{"n":37,"t":"Yûsuf dedi ki: \"Rızıklanacağınız herhangi bir yemek size gelmeden önce onun yorumunu ikinize mutlaka bildiririm.\" Bu, Rabbimin bana öğrettiği şeylerdendir. Ben, Allah'a inanmayan ve âhireti de tamamen inkâr eden bir toplumun milletini terk ettim.\""},{"n":38,"t":"\"Ve atalarım İbrahim'in, İshak'ın Yakub'un milletine uydum. Bizim herhangi birşeyi Allah'a ortak tutmamız söz konusu olamaz. İşte bu, Allah'ın bize ve diğer insanlara bir lütfudur. Ama insanların çokları şükretmiyorlar.\""},{"n":39,"t":"\"Ey benim zından arkadaşlarım! Parçalara bölünüp fırkalaşmış rabler mi daha hayırlıdır, Vâhid ve Kahhâr olan Allah mı?\""},{"n":40,"t":"\"O'nun yanında nelere kulluk ediyorsunuz? Sadece bir takım isimlere ki, adlarını siz ve atalarınız koymuştur. Onlar hakkında Allah, hiçbir kanıt indirmemiştir. Hüküm yalnız Allah'ındır. O, yalnız ve yalnız kendisine kulluk etmenizi emretti. Eskimez ve pörsümez din işte budur. Ama insanların çokları bilmiyorlar.\""},{"n":41,"t":"\"Ey benim zından arkadaşlarım! Rüyanıza gelince: Bir taneniz rab edindiği kişiye şarap sunacak. Ötekiniz ise asılacak da kuşlar başından yiyecek. Hakkında fetva sorduğunuz iş, böyle hükme bağlanmıştır.\""},{"n":42,"t":"Yûsuf o iki kişiden, kurtulacağını düşündüğüne şöyle dedi: \"Rab edindiğin kişi yanında beni an.\" Ama şeytan o adama, rab edindiği kişiye hatırlatmayı unutturdu. Böylece Yûsuf yıllarca zındanda kaldı."},{"n":43,"t":"Kral dedi ki: \"Düşümde yedi semiz inek görüyorum. Bunları yedi cılız inek yiyor. Ayrıca yedi yeşil başak, yedi de kuru başak görüyorum. Ey bendelerim! Eğer rüya tabir ediyorsanız, bu rüyam hakkında bana bir fetva verin.\""},{"n":44,"t":"Dediler ki: \"Bunlar, demet demet hayallerden ibarettir. Biz, hayal ve kuruntuların yorumunu bilenler değiliz.\""},{"n":45,"t":"Zındandaki iki adamdan kurtulanı, uzun bir zamandan sonra eskiyi hatırladı da şöyle dedi: \"Onun yorumunu size ben haber veririm. Siz beni zındana gönderin.\""},{"n":46,"t":"\"Yûsuf, ey özü-sözü doğru insan! Şu rüyayı yorumla bize. Yedi semiz inek var, yedi cılız inek bunları yiyor; yedi yeşil başak, bir yedi tane de kuru başak. Umarım buradan insanların yanına giderim, onlar da öğrenirler.\""},{"n":47,"t":"Yûsuf dedi: \"Alışılageldiği şekliyle yedi yıl ekin ekeceksiniz. Biçtiklerinizden yiyecek kadar az bir miktar alır, gerisini başağında bırakırsınız.\""},{"n":48,"t":"\"Bunun ardından yedi kurak yıl gelecek. Bu yıllar, saklayabileceğiniz bir miktar ekin hariç, önceden biriktirdiklerinizi yiyip tüketecek.\""},{"n":49,"t":"\"Bunun arkasından bir yıl gelecek ki, halk onda bol yağmura kavuşup rahat edecek; meyve suyu sıkıp süt sağacaklar.\""},{"n":50,"t":"Kral: \"Bu yorumu yapanı bana getirin!\" dedi. Elçi kendisine gelince, Yûsuf dedi ki: \" Rab edindiğin kişiye dön de sor bakalım, o ellerini kesen kadınların derdi neydi? Rabbim, o kadınların hilelerini çok iyi bilmektedir.\""},{"n":51,"t":"Kral dedi: \"Yûsuf'un nefsinden murat almak istediğinizde, derdiniz ne idi?\" Dediler ki: \"Allah şahit, biz onun hiçbir kötülüğünü bilmiyoruz.\" Aziz'in karısı dedi ki: \"İşte şimdi gerçek ortaya çıktı. Ben onunla gönül eğlendirmek istemiştim. O, özü-sözü doğru insanlardandı.\""},{"n":52,"t":"\"Gerçeği söylüyorum ki, Yûsuf, gıyabında ona hainlik etmediğimi, Allah'ın, hainlerin tuzağını başarıya ulaştırmayacağını bilsin.\""},{"n":53,"t":"\"Nefsimi ak-pak gösteremem. Çünkü nefs, Rabbimin merhamet ettiği durumlar hariç, olanca gücüyle kötülüğü emreder. Ama Rabbim çok affedici, çok esirgeyicidir."},{"n":54,"t":"Kral dedi ki: \"Onu bana getirin, kendime özel dost edineyim.\" Yusuf'la konuşunca da şöyle dedi: \"Artık bugün yanımızda mevkii olan, güvenilir bir dostsun.\""},{"n":55,"t":"Yûsuf dedi ki: \"Beni ülke hazinelerine bakan yap. Ben iyi bir koruyucuyum; bilgiliyim.\""},{"n":56,"t":"İşte böylece biz Yûsuf'a yeryüzünde imkân ve mevki verdik. Ülkede, istediği yerde konaklayabiliyordu. Biz dilediğimiz kimseye rahmetimizi ulaştırırız; güzel düşünüp güzel davrananların ödülünü yitirmeyiz."},{"n":57,"t":"İman edip takvaya sarılanlar için âhiretteki ödül elbette daha değerlidir."},{"n":58,"t":"Nihayet Yûsuf'un kardeşleri çıkageldiler; Yûsuf'un yanına girdiler, o onları tanıdı. Ama onlar onu tanımıyamıyorlardı."},{"n":59,"t":"Onların yüklerini hazırlatıp bağlatınca şöyle konuştu: \"Sizin, aynı babadan bir kardeşiniz var, onu bana getirin. Görüyorsunuz, ben ölçüyü titizlikle yerine getiriyorum. Ben, konukseverlerin de en hayırlısıyım.\""},{"n":60,"t":"\"Eğer onu bana getirmezseniz, artık yanımda sizin için ölçülecek birşey yok, bir daha bana yaklaşmayın.\""},{"n":61,"t":"Dediler: \"Onu babasından isteyip getirmeye çalışacağız, herhalde bunu yapacağız da.\""},{"n":62,"t":"Yûsuf muhafızlarına dedi ki: \"Onların sermayelerini yüklerinin içine koyun. Bakarsın ailelerine döndüklerinde onu fark eder de tekrar gelirler.\""},{"n":63,"t":"Babalarına döndüklerinde dediler ki: \"Ey babamız! Ölçü bizden yasaklandı. Şimdi kardeşimizi bizimle gönder ki, ölçüp alabilelim. Biz onu gerçekten iyi koruyacağız.\""},{"n":64,"t":"Dedi: \" Daha önce kardeşi için güvendiğim gibi yine güveneyim size, değil mi? Hâfız, koruyucu olarak Allah'tır en hayırlı olan. Merhamet edenlerin en merhametlisi de O'dur.\""},{"n":65,"t":"Yüklerini açtıklarında sermayelerini buldular; onlara geri verilmişti. \"Ey babamız, dediler, daha ne istiyoruz! İşte sermayemiz, bize geri verilmiş. Ailemize yeniden yiyecek alırız. Kardeşimizi koruruz. Bir deve yükü zahire de ilave ederiz. Zaten şu aldığımız az bir miktardır.\""},{"n":66,"t":"Yakub dedi: \"Hepinizin çepeçevre kuşatılması müstesna, onu bana mutlaka getireceğinize dair Allah'tan bir garanti vermedikçe, onu sizinle asla göndermem.\" Kardeşler ona garanti verince şöyle dedi: \"Şu söylediğinize Allah Vekîl'dir.\""},{"n":67,"t":"Yakub şunu da söyledi: \"Oğullarım, birtek kapıdan girmeyin, ayrı ayrı kapılardan girin. Gerçi ben, Allah'ın takdir ettiği birşeyi sizden savamam, hüküm yalnız Allah'ındır. Yalnız O'na dayandım ben, yalnız O'na güvenip dayansın tevekkül sahipleri.\""},{"n":68,"t":"Babalarının emrettiği yerlerden kente girdiklerinde, bu onlardan Allah'ın herhangi bir takdirini uzak tutmamıştı; sadece Yakub'un içindeki bir isteği gerçekleştirmişti. Yakub, bizim ona öğretmemizden dolayı bilgi sahibi idi. Ama halkın çoğu bunu bilmezdi."},{"n":69,"t":"Kardeşler Yûsuf'un yanına girdiklerinde, Yûsuf öz kardeşini yanına çekip dedi: \"Şu bir gerçek ki, ben senin kardeşinim. Onların yapıp ettiklerine üzülme.\""},{"n":70,"t":"Yûsuf, kardeşlerinin yüklerini hazırlatırken su kabını öz kardeşinin yükü içinde koydu. Sonra bir ünleyici şöyle haykırdı: \"Ey kafile, siz herhalde hırsızlık ettiniz!\""},{"n":71,"t":"Onlara dönüp şöyle dediler: \"Ne kaybettiniz?\""},{"n":72,"t":"Dediler: \"Kralın su tasını kaybettik. Onu getirene bir deve yükü ödül var. Kefili benim.\""},{"n":73,"t":"Kardeşler dediler: \"Vallahi, siz de iyi biliyorsunuz ki, biz bu toprağa bozgunculuk yapmak için gelmedik, hırsız da değiliz biz.\""},{"n":74,"t":"Sordular: \"Eğer yalan söylüyorsanız, hırsızlığı yapanın cezası nedir?\""},{"n":75,"t":"Kardeşler dedi: \"Cezası şu: Çalınan mal kimin yükünde çıkarsa yükün sahibi çalınan mala karşılık olacaktır. Biz zalimleri böyle cezalandırıyoruz.\""},{"n":76,"t":"Bunun üzerine Yûsuf öz kardeşinin heybesinden önce, öteki kardeşlerin heybelerini aramaya başladı. Nihayet su kabını, öz kardeşinin heybesinden çıkardı. Yûsuf'a böyle bir tuzak öğretmiştik. Yoksa Yûsuf, Allah'ın dilemesi dışında, kralın dinine göre öz kardeşini alamazdı. Dilediklerimizi derece derece yükseltiriz biz. Her bilgi sahibinin üstünde bir başka bilen vardır."},{"n":77,"t":"Kardeşler dediler ki: \"Bu çaldı ya, bundan önce de onun kardeşi çalmıştı.\" Yûsuf bunu içinde sakladı, onlara açıklamadı. Şöyle diyordu: \"Kötü bir konumdasınız. O sizin dilinize doladığınız şeyi Allah daha iyi biliyor.\""},{"n":78,"t":"Kardeşler dediler ki: \"Ey vezir! Bunun ihtiyar bir babası var. Onun yerine bizden birini alıkoy. Senin iyilikseverlerden olduğuna inanıyoruz.\""},{"n":79,"t":"\"Ne, dedi Yûsuf, Allah korusun. Eşyamızı yükünde bulduğumuz adamdan başkasını tutamayız. Öyle birşey yaparsak zalimlerden oluruz.\""},{"n":80,"t":"Yûsuf'tan ümidi kesince bir kenara çekilip tartışmaya başladılar. Büyükleri dedi ki: \"Babanızın sizden Allah adına garanti aldığını, daha önce Yûsuf'a yaptığınız haksızlığı bilmez misiniz? Babam bana izin verinceye, yahut da Allah hakkımda hükmedinceye kadar bu ülkeden ayrılmayacağım. Yargıçların en hayırlısıdır O.\""},{"n":81,"t":"Babanıza dönüp şöyle deyin: \"Ey babamız, oğlun hırsızlık etti. Biz sadece bildiğimize tanıklık ettik. Biz gaybı bilenler değiliz.\""},{"n":82,"t":"\"İçinde bulunduğumuz kente, beraberinde döndüğümüz kervana sor. Biz gerçeğin ta kendisini söylüyoruz.\""},{"n":83,"t":"Yakub dedi ki: \"Hayır, öyle değil, nefisleriniz sizi yine bir işe itmiş. Bana düşen yine güzel bir sabra sarılmak. Bakarsın Allah onların hepsini bana getirir. Çünkü Alîm olan O, Hakîm olan O'dur.\""},{"n":84,"t":"Ve yüzünü onlardan öteye döndürdü de şöyle inledi: \"Ey Yûsuf'a duyduğum gam, neredesin!\" Ve kederden gözlerine ak düştü. Durmadan yutkunuyordu."},{"n":85,"t":"Dediler ki: \"Hâlâ Yûsuf'u anıp duruyorsun. Sonunda ya kederinden eriyeceksin yahut da helâk olup gideceksin.\""},{"n":86,"t":"Dedi ki: \"Ben, içimi doldurup taşan özlemimi, kederimi Allah'a arz ederim. Ve Allah'ın yardımıyla sizin bilmediğiniz şeyleri bilirim.\""},{"n":87,"t":"\"Ey oğullarım! Gidin, artık Yûsuf'u ve kardeşini bulmak için dikkat kesilin. Allah'ın rahmetinden ümit kesmeyin; çünkü, Allah'ın rahmetinden de, küfre sapanlar topluluğundan başkası ümit kesmez.\""},{"n":88,"t":"Tekrar Yûsuf'un yanına girdiklerinde şöyle dediler: \"Ey Vezir! Bize de ailemize de zorluk dokundu. Önemsiz bir sermaye ile geldik. Sen bize tam ölçü zahire ver, bize sadaka vermiş ol. Allah, karşılıksız verenleri ödüllendirir.\""},{"n":89,"t":"Dedi: \"O cahil zamanınızda Yûsuf'a ve kardeşine ne yaptığınızı biliyorsunuz, değil mi?\""},{"n":90,"t":"Dediler ki: \"Sen, yoksa sen Yûsuf musun?\" \"Evet, dedi, ben Yûsuf'um. İşte şu da kardeşim. Allah bize lütufta bulundu. Kim Allah'tan korkar, sabrederse Allah güzel düşünüp güzel davrananların ödülünü yitirmez.\""},{"n":91,"t":"Dediler: \"Vallahi, Allah seni bizden üstün kıldı/seni bize tercih etti. Doğrusu biz de büyük suç işlemiştik.\""},{"n":92,"t":"Yûsuf dedi: \"Bugün azarlanmayacaksınız. Allah sizi affeder. O, rahmet edenlerin en merhametlisidir.\""},{"n":93,"t":"\"Şu gömleğimi götürün, babamın yüzü üstüne koyun ki, gözü görür hale gelsin. Ve sonra da bütün ailenizle toplanıp bana gelin.\""},{"n":94,"t":"Kervan oradan ayrılanca, öte yandan babaları şöyle seslendi: \"Yemin olsun, ben Yûsuf'un kokusunu duyuyorum! Umarım bana bunaklık isnat etmezsiniz.\""},{"n":95,"t":"Dediler: \"Vallahi, sen hâlâ o eski sapıklığında diretiyorsun!\""},{"n":96,"t":"Müjdeci gelip gömleği yüzünün üstüne bırakınca, gözü derhal görür hale geldi. Yakub: \"Ben size demedim mi? Allah'ın izniyle sizin bilmediklerinizi bilirim.\" diye konuştu."},{"n":97,"t":"Oğulları dediler: \"Ey babamız! Günahlarımızın affını dile. Gerçekten biz hata işledik.\""},{"n":98,"t":"Dedi: \"Rabbimden sizin için af dileyeceğim. Çok affedicidir O, çok merhametlidir!\""},{"n":99,"t":"Nihayet, Yûsuf'un huzuruna vardıklarında Yûsuf, ana-babasına sarılıp kucakladı. Ve şöyle dedi: \"Girin Mısır'a, Allah dilerse emniyet ve güven içinde olacaksınız.\""},{"n":100,"t":"Ana-babasını tahtın üstüne çıkardı. Hepsi, Yûsuf'un önünde secde eder gibi eğildiler. Yûsuf dedi: \"Babacığım, işte bu, benim önceden gördüğüm rüyanın yorumudur. Rabbim onu gerçekleştirdi. O, bana çok güzel lütuflarda bulundu, şeytan, benimle kardeşlerim arasına yakumluk soktuktan sora, O beni zındandan çıkardı. Sizi de çölden getirdi. Rabbim, dilediği şeyde çok ince lütuflar sergiliyor. Alîm olan O'dur, Hakîm olan O'dur.\""},{"n":101,"t":"\"Rabbim, sen bana mülk ve saltanattan bir nasip verdin. Olayların ve düşlerin yorumundan bana bir ilim öğrettin/olayların ve düşlerin yorumu konusunda beni eğittin. Ey gökleri ve yeri yaratan! Benim dünyada da âhirette de Velî'm sensin! Beni müslüman/sana teslim olmuş olarak öldür ve beni barışsever hayırlı kullar arasına kat!\""},{"n":102,"t":"İşte bunlar, sana vahyettiğimiz gayb haberlerindendir. Onlar birlikte karar verip tuzak kurarlarken sen yanlarında değildin."},{"n":103,"t":"Sen hırslanasıya istesen de, insanların çoğu inanmayacaktır."},{"n":104,"t":"Sen, bu tebliğin için onlardan bir ücret istemiyorsun. O, bütün âlemler için bir hatırlatmadan başka şey değildir."},{"n":105,"t":"Göklerde ve yerde nice mucizeler var ki, yanlarından geçerler de dönüp bakmazlar bile."},{"n":106,"t":"Onların çoğu şirke bulaşmış olmadan Allah'a iman etmez."},{"n":107,"t":"Peki onlar, Allah'ın azabından bir sarıp sarmalayanın gelmesinden yahut hiç farkında olmadıkları bir sırada kıyametin ansızın tepelerine inmesinden emin mi bulunuyorlar?"},{"n":108,"t":"De ki: \"İşte benim yolum budur. Ben, Allah'a basîret üzere çağırırım/dua ederim. Beni izleyenler de... Şanı yücedir Allah'ın! Ben müşriklerden değilim.\""},{"n":109,"t":"Senden önce gönderdiklerimiz de kentler halkından kendilerine vahyettiğimiz bazı erlerden başkası değildi. Yeryüzünde dolaşmadılar mı ki, onlardan öncekilerin akıbeti nasıl oldu görsünler. Elbette ki âhiret yurdu sakınanlar için daha hayırlıdır. Hâlâ akıllarınızı kullanmayacak mısınız?\""},{"n":110,"t":"Ne zaman ki resuller ümitsizliğe düşüp yalanlandıkları kanısına vardılar, işte o zaman yardımımız kendilerine ulaştı da dilediklerimiz kurtarıldı. Azabımız suçlular topluluğundan geri çevrilemez."},{"n":111,"t":"Yemin olsun ki, resullerin hikâyelerinde, aklını ve gönlünü çalıştıranlar için bir ibret vardır. Bu Kur'an, uydurulacak bir söz değildir; bilakis o, kendinden öncekileri tasdik eden, her şeyi ayrıntısıyla açıklayan, inanan bir topluluk için de bir kılavuz ve bir rahmettir."}],[{"n":1,"t":"Elif, Lâm, Mîm, Râ. O Kitap'ın ayetleridir bunlar. Ve sana Rabbinden indirilen, haktır. Ne var ki, insanların çokları iman etmezler."},{"n":2,"t":"Allah odur ki, gökleri direksiz yükseltmiştir; görüyorsunuz onları... Sonra arş üzerine egemen olmuştur. Güneş'i ve Ay'ı da boyun eğdirmiştir. Bunların tümü belirlenmiş bir vakte kadar akar dururlar. Oluşu yönlendirir, çekip çevirir O... Ayetleri birer birer gözler önüne serer ki, Rabbinize kavuşacağınıza açık-seçik inanasınız."},{"n":3,"t":"Yeri uzatıp döşeyen ve onda oturaklı dağlar ve nehirler vücuda getiren O'dur. Bütün meyvelerden kendi içlerinde ikişer çift yaratmıştır O. Geceyi gündüze sarıp bürümektedir O. Bütün bunlarda derin derin düşünecek bir topluluk için elbette ayetler vardır."},{"n":4,"t":"Yeryüzünde birbirine sırt vermiş komşu kıtalar, üzümlerden bahçeler, ekinler, çatallı ve çatalsız hurmalıklar vardır ki, bir tek suyla sulanırlar. Biz bunların, yemişlerde bir kısmını diğer bir kısmına üstün kıldık. Bütün bunlarda aklını çalıştıran bir topluluk için elbette ki ibretler vardır."},{"n":5,"t":"Eğer şaşıyorsan, esas şaşılacak olan onların şu sözüdür: \"Biz toprak olunca mı ve gerçekten mi yeni bir yaratılış içinde bulunacağız?\" Bunlar Rablerini inkâr edenlerdir. Ve bunlar boyunlarına bukağılar vurulanlardır. Bunlar ateşe dost onların ta kendileridir; orada uzun süre kalacaklardır."},{"n":6,"t":"Senden, güzellikten önce kötülük istemede acele ediyorlar. Halbuki önlerinden pek çok örnek gelip geçti. Şu da bir gerçek ki, Rabbin insanlara karşı, zulümlerine rağmen af sahibidir. Ve Rabbinin azabı elbette çok şiddetlidir."},{"n":7,"t":"Küfre sapmış olanlar şöyle derler: \"Ona Rabbinden bir mucize indirilseydi ya!\" Sen sadece bir uyarıcısın ve her topluluk için doğruyu ve iyiyi gösteren bir önder vardır."},{"n":8,"t":"Allah, her dişinin neye gebe kaldığını, rahimlerin neyi eksiltip neyi artırdığını bilir. O'nun katında her şey bir ölçü/ölçüye bağlıdır."},{"n":9,"t":"Gaybı da görünen âlemi de bilendir/Âlim'dir O... Kebîr, sınırsızca büyük O'dur; Müteâl, sonsuzca yüce O'dur."},{"n":10,"t":"Sizden, sözü saklayan da açıklayan da geceye sığınıp gizlenen de gündüz yol alan da onun için birdir."},{"n":11,"t":"Her biri için onu önünden ve arkasından izleyen gözcüler vardır ki, kendisini Allah'ın emrine bağlı olarak koruyup denetlerler. Gerçek şu ki Allah, bir toplumun mâruz kaldığı şeyleri, onlar, birey olarak içlerindekini/birey olarak kendilerine ilişkin olanı değiştirmedikçe, değiştirmez. Allah bir topluma bir perişanlık dileyince de artık onu geri çevirecek bir güç yoktur. Ve onlar için Allah'ın berisinden koruyucu bir dost da olamaz."},{"n":12,"t":"Size, hem korku hem ümit olsun diye şimşeği gösteren O'dur. Yüklü yüklü bulutları da O oluşturuyor."},{"n":13,"t":"Gök gürültüsü O'nu hamd ile tespih eder; melekler de O'ndan ürpererek... Yıldırımlar gönderir de onlarla dilediğini çarpar. Allah, tuzak kuranların hilelerini başlarına geçirmede çok güçlü olduğu halde, onlar O'na karşı mücadele edip duruyorlar."},{"n":14,"t":"Gerçek dua yalnız O'na/hak davet yalnız O'nun için yapılır. O'nun dışında yalvarıp davet ettikleri ise onlara hiçbir şekilde cevap veremezler. Onlar, ağzına ulaşsın diye iki avucunu suya doğru açan ama suya ulaşamayan birinden başkasına benzemiyorlar. Küfre sapanların dua ve davetleri, şaşkınlığa dalmaktan başka bir işe yaramaz."},{"n":15,"t":"Göklerde ve yerde kim varsa gölgeleriyle birlikte ister istemez ve sabah-akşam Allah'a secde eder."},{"n":16,"t":"De ki: \"Göklerin ve yerin Rabbi kim?\" De ki: \"Allah.\" De ki: \"O'nun yanında başka evliya mı/destekçiler mi edindiniz? Bunlar kendilerine bile yarar sağlayıp zarar verme gücünde değiller.\" De ki: \"Körle gören yahut karanlıklarla ışık bir olur mu? Yoksa Allah'a, tıpkı O'nun yarattığı gibi yaratan ortaklar buldular da yaratış/yaratılanlar kendileri için benzeşir hale mi geldi?\" De ki: \"Allah'tır her şeyi yaratan, O'dur Vâhid ve Kahhâr olan.\""},{"n":17,"t":"Gökten bir su indirdi de vadiler, kendi ölçülerince/kaderlerine göre sel oldu, ardından da sel, üste çıkan köpüğü taşır hale geldi. Bir süs eşyası veya âlet yapmak isteğiyle ateşte körükledikleri şeylerde de benzeri bir köpük vardır. Allah hakla bâtılı işte böyle örneklendiriyor: Köpük, atılır gider; insanlara yararlı olansa toprakta kalır. Allah, işte bu şekilde örnekler verir."},{"n":18,"t":"Rablerinin çağrısına olumlu cevap verenler için güzellik vardır. O'na olumlu cevap vermeyenlere gelince, yeryüzündekilerin tamamı onların olsa, bir o kadar da ilave edilse, kurtulmak için bunların tümünü fidye verirlerdi. Böylelerinin hesabı kötü olacaktır; varacakları yer de cehennemdir. Ne kötü yataktır o!"},{"n":19,"t":"Rabbinden sana indirilenin hak olduğunu bilen kişi, kör olan biriyle aynı mıdır? Sadece aklı ve gönlü işleyenler düşünüp ibret alır."},{"n":20,"t":"İşte bunlardır, Allah'a verdikleri söze sadık kalanlar ve antlaşmayı bozmayanlar."},{"n":21,"t":"Onlar, Allah'ın ulaştırılmasını emrettiği şeyi ulaştırırlar, Rablerinden korkarlar ve hesabın kötüsünden ürperti duyarlar."},{"n":22,"t":"Onlar, Rablerinin yüzünü arzulayarak sabrederler, namazı/duayı yerine getirirler, kendilerine verdiğimiz rızıklardan gizli ve açık dağıtırlar ve kötülüğü güzellikle savarlar. İşte bunlar içindir sürekli yurt."},{"n":23,"t":"Adn cennetleri bunlar içindir. Atalarından, eşlerinden, zürriyetlerinden hayra ve barışa hizmet etmiş olanlarla birlikte girerler oraya. Meleklerse her kapıdan yanlarına sokulurlar."},{"n":24,"t":"\"Selam size, sabrettiğiniz için! Ne güzeldir şu sonsuzluk yurdu!\" derler."},{"n":25,"t":"Allah'a verdikleri sözü, onu antlaşma haline getirdikten sonra bozanlar, Allah'ın birleştirilmesini emrettiği şeyi parçalayanlar ve yeryüzünde bozgun çıkaranlara gelince, böyleleri için lanet var. Yurdun en kötüsü de onların olacak."},{"n":26,"t":"Allah, dilediği kimse için rızkı alabildiğine açar da sınırlayıp kısar da. İğreti dünya hayatıyla sevinip şımardılar. Oysaki dünya hayatı, âhirete oranla sadece küçük bir nimetlenme."},{"n":27,"t":"Küfre sapanlar derler ki: \"Rabbinden ona bir mucize indirilseydi ya!\" De ki: \"Allah dilediğini/dileyeni saptırır. Doğruya yöneleni de kendisine iletir.\""},{"n":28,"t":"Böyleleri, inanan ve gönülleri Allah'ın zikriyle/Kur'an'ıyla tatmin bulan kişilerdir. Gözünüzü açın! Gönüller yalnız Allah'ın zikriyle/Kur'an'la tatmin bulur."},{"n":29,"t":"İman edip hak ve barış uğruna iyi işler yapanlara mutluluk ve müjde var, güzel bir gelecek var."},{"n":30,"t":"İşte seni böylece, kendilerinden önce nice ümmetlerin gelip geçtiği bir ümmet içinde resul kıldık ki, onlar Rahman'a küfrederlerken sen kendilerine, sana vahyettiğimizi okuyasın. De ki: \"O'dur benim Rabbim, ilah yok O'ndan başka, O'na dayanmışım ben! Yalnız O'nadır tövbem!\""},{"n":31,"t":"Kendisiyle, dağların yürütüldüğü yahut yerkürenin parçalandığı yahut ölülerin konuşturulduğu bir Kur'an mı olsaydı! Hayır, iş ve oluşun tümü Allah'ındır. İman edenler hâlâ ümidi kesip anlamadılar mı ki, Allah dileseydi elbette insanlara tümden hidayet verirdi. O küfre sapanlara gelince, sanayi olarak ürettiklerinin sonucu halinde başlarına gülle-tokmak türünden belalar inmeye devam edecek yahut o belalar onların yurtlarının yakınına konacak. Ta, Allah'ın vaadi gelinceye değin. Allah, vaadine asla ters düşmez."},{"n":32,"t":"Yemin olsun, senden önceki resullerle de alay edildi. İnkâr edenlere biraz süre verdim ama sonunda hepsini yakaladım. Gördüler nasılmış azap!"},{"n":33,"t":"Allah'a ortaklar tanıdılar. Peki, her benliğin yaptığı işin başında duranla bunlar bir mi? De ki: \"Onları isimlendirin. Yoksa siz Allah'a, yeryüzünde bilmediği birşey mi haber veriyorsunuz? Yoksa, anlamsız bir laf mı ediyorsunuz?\" Hayır, küfre sapanlara, tuzakları süslü gösterildi de yoldan döndürüldüler. Allah'ın şaşırttığına kılavuzluk edecek yok."},{"n":34,"t":"Dünya hayatında bir azap var onlar için; âhiret azabı ise çok daha şiddetlidir. Onları Allah'a karşı koruyacak kimse de yoktur."},{"n":35,"t":"Sakınıp korunanlara vaat edilen cennetin temsilî anlatımı şu: Altından ırmaklar akar, yemişleri de sürekli, gölgesi de. İşte korunup sakınanların son yurdu. Kâfirlerin son yordu ise ateş..."},{"n":36,"t":"Kendilerine kitap verdiklerimiz, sana indirilenle ferahlarlar. Ama hiziplerden bazıları onun bir kısmını inkâr ederler. De ki: \"Bana, yalnız Allah'a kulluk etmem, O'na ortak koşmamam emredildi. Ben O'na yakarır, O'na davet ederim. Dönüşüm de O'nadır.\""},{"n":37,"t":"İşte biz o Kur'an'ı Arapça bir hüküm kaynağı olarak indirdik. Eğer sana gelen ilimden sonra onların keyiflerine uyarsan, Allah'tan sana ne bir dost nasip olur ne de bir koruyucu."},{"n":38,"t":"Yemin olsun, biz senden önce de resuller gönderdik, onlara da eşler ve evlatlar verdik. Hiçbir resul, Allah'ın izni olmadıkça herhangi bir mucize getiremez. Her süre/süreç için bir kitap vardır."},{"n":39,"t":"Allah dilediğini silip yok eder, dilediğini sâbit tutar. Kitap'ın anası/ana Kitap O'nun katındadır."},{"n":40,"t":"Ya onlara vaat ettiğimiz şeylerin bir kısmını sana gösteririz yahut da seni vefat ettiririz. O halde tebliğ etmek sana, hesap sormak bize düşer."},{"n":41,"t":"Görmüyorlar mı ki biz o yerküreye geliyor, onu uçlarından eksiltiyoruz. Allah hükmeder; O'nun hükmünü denetleyecek de yoktur. Hesabı çok çabuk görür O."},{"n":42,"t":"Onlardan öncekiler de tuzak kurmuştu, ama tüm tuzaklar Allah'ındır. Her benliğin ne kazandığını O bilir. Kâfirler de bilecek sonsuzluk yurdu kimindir!"},{"n":43,"t":"Küfre sapanlar: \"Sen gönderilmiş bir elçi değilsin.\" diyorlar. De ki: \"Benimle sizin aranızda tanık olarak Allah, bir de yanında kitap bilgisi bulunanlar yeter.\""}],[{"n":1,"t":"Elif, Lâm, Râ. Bir kitaptır bu. Ki indirdik sana, çıkarasın diye insanları Rablerinin izniyle karanlıklardan nura; Hamîd, Azîz olanın yoluna..."},{"n":2,"t":"O Allah'a ki yalnız O'nundur göklerdekiler ve yerdekiler. Hüsran haberi şiddetli bir azaptan, o küfre batmışlara..."},{"n":3,"t":"Onlar ki sefil ve iğreti hayatı âhirete tercih ederler ve Allah yolundan alıkoyup o yolu eğri-büğrü yapmayı isterler. İşte bunlar, dönüşü olmayan bir sapıklık içindedirler."},{"n":4,"t":"Biz, görevlendirdiğimiz her resulü ancak kendi toplumunun diliyle gönderdik ki, onlara açık-seçik beyanda bulunsun. Bunun ardından, Allah dilediğini saptırır, dilediğini de iyiye ve güzele kılavuzlar. Azîz'dir, Hakîm'dir O!"},{"n":5,"t":"Yemin olsun ki, biz Mûsa'yı, \"Toplumunu karanlıklardan aydınlığa çıkar ve onlara Allah'ın günlerini hatırlatıp bellet!\" diye ayetlerimizle gönderdik. Şu bir gerçek ki, bunda iyice sabreden, çokça şükreden herkes için sayısız ayetler vardır."},{"n":6,"t":"Mûsa'nın, kendi toplumuna şöyle dediği zamanı da hatırla: \"Allah'ın üzerinizdeki nimetini anın! Hatırlayın ki, sizi Firavun'un hanedanından kurtarmıştı. Onlar size azabın en kötüsüyle acı çektiriyorlar, erkek çocuklarınızı boğazlıyorlar, kadınlarınıza hayasızca davranıyorlar/kadınlarınızın rahimlerini yokluyorlar/kadınlarınızı hayata salıyorlardı. İşte bunda sizin için Rabbinizden gelen çok büyük bir deneme ve ıstırap vardır.\""},{"n":7,"t":"Rabbinizin şunu duyurduğunu da hatırda tutun: Eğer şükrederseniz, ben de sizin için mutlaka artıracağım. Ve eğer nankörlük ederseniz hiç kuşkusuz benim azabım çok çok şiddetlidir."},{"n":8,"t":"Şöyle demişti Mûsa: \"Siz de yeryüzünde bulunanların tümü de küfre saplansanız, hiç kuşkusuz Allah mutlak Ganî, mutlak Hamîd'dir."},{"n":9,"t":"Sizden öncekilerin, Nûh kavminin, Âd'ın, Semûd'un ve onlardan sonrakilerin haberleri ulaşmadı mı size? Allah'tan başkası bilmez onları. Peygamberleri onlara açık deliller getirmişti de onlar ellerini ağızlarına itip şöyle demişlerdi: \"Biz size gönderileni kesinlikle tanımıyoruz ve biz sizin çağırdığınız şey konusunda karmaşa ve çıkmaza iten bir kuşku içindeyiz.\""},{"n":10,"t":"Resulleri dediler ki: \"Gökleri ve yeri yaratan Allah hakkında mı kuşku? O sizi, günahlarınızı affetsin, belirli bir süreye kadar size zaman tanısın diye çağırıyor.\" Şöyle cevap verdiler: \"Siz de bizim gibi birer insandan başka şey değilsiniz. Atalarımızın kulluk ettiklerinden bizi yüz geri çevirmek istiyorsunuz. Hadi açık bir kanıt getirin bize!\""},{"n":11,"t":"Resulleri onlara dediler ki: \"Biz de sadece sizin gibi birer insanız, fakat Allah, kullarından dilediğine lütufta bulunur. Allah'ın izni olmadan bizim size bir kanıt getirmemiz haddimize değil. İnananlar yalnız Allah'a dayanıp güvensinler.\""},{"n":12,"t":"\"O, bize yollarımızı göstermişken neden Allah'a tevekkül etmeyecekmişiz? Bize yaptığınız eziyetlere elbette sabredeceğiz. Tevekkül edenler yalnız Allah'a tevekkül etsinler.\""},{"n":13,"t":"Küfre sapanlar kendi resullerine şöyle dediler: \"Ya tam bir biçimde bizim milletimize dönersiniz yahut da sizi yurdumuzdan mutlaka çıkarırız.\" Rableri de onlara şunu vahyetti: \"Zalimleri muhakkak helâk edeceğiz.\""},{"n":14,"t":"\"Ve onların ardından o toprağa mutlaka sizi yerleştireceğiz. Bu, makamımdan korkan, tehdidimden korkan için böyledir.\""},{"n":15,"t":"Ve Allah'tan fetih istediler. Ve her inatçı zorba perişan oldu."},{"n":16,"t":"Ardından da cehennem. İrinli bir sudan içirilecekler."},{"n":17,"t":"Onu yutmaya çalışacak ama boğazından geçiremeyecek. Ölüm her yandan üstüne gelecek de bir türlü ölmeyecek. Arkasından da dehşetli bir azap."},{"n":18,"t":"Rablerne küfredenlerin/inkâr edenlerin amellerinin durumu şöyledir: Onların yapıp ettikleri, fırtınalı bir günde rüzgârın şiddetle savurduğu bir küle benzer. Kazandıklarından hiçbir şeyi kontrol edip ellerinde tutamazlar. İşte bu, dönüşü olmayan derin/uzak bir sapıklıktır."},{"n":19,"t":"Allah'ın gökleri ve yeri hak olarak yarattığını görmedin mi? Dilerse sizi yok eder, yepyeni bir halk getirir."},{"n":20,"t":"Bu, Allah'a hiç de zor gelmez."},{"n":21,"t":"Hepsi toplu halde, Allah'ın huzuruna çıkmış olacaklar. Ezilip horlananlar, büyüklük taslayanlara diyecekler ki: \"Biz sizin birer uydunuzduk. Şimdi siz Allah'ın azabından bir kısmını bizden uzaklaştırabilir misiniz?\" Cevap verecekler: \"Allah bize kılavuzluk etseydi elbette biz de size kılavuzluk ederdik. Şimdi inleyip feryat etsek de sabretsek de bir. Sığınacak hiçbir yerimiz yok.\""},{"n":22,"t":"İş bitirilince şeytan şöyle der: \"Allah size hak bir vaatle vaatte bulundu, ben de size vaat ettim ama vaadimden caydım. Benim sizin üzerinizde bir zorlayıcı gücüm/ yaptırımım yoktu. Seni çağırdım, sen de bana uydun. O halde beni kınamayın, kendinizi kınayın! Ne ben sizin imdadınıza yetişebilirim ne de siz benim imdadıma yetişebilirsiniz. Zaten ben, önceden beni Allah'a ortak koşmanızı da tanımamıştım.\" Zalimler için acıklı bir azap vardır."},{"n":23,"t":"İman edip barışa/hayra yönelik işler yapanlar ise rablerinin izniyle altlarından ırmaklar akan cennetlere sokulmuşlardır. Sürekli kalıcıdırlar orada. Birbirlerine esenlik dilemeleri, \"Selam!\" şeklindedir."},{"n":24,"t":"Görmedin mi Allah nasıl bir örnekleme yaptı: Güzel söz; kökü yerde, dalları gökte olan güzel bir ağaca benzer."},{"n":25,"t":"O ağaç, Rabbinin izniyle yemişlerini her zaman verir. Allah, insanlara böyle örnekler verir ki, düşünüp ibret alabilsinler."},{"n":26,"t":"Pis bir söz de gövdesi toprağın üstünde destek bulmuş bir ağaca benzer, dayanağı yoktur onun."},{"n":27,"t":"Allah, inananları dünya hayatında da âhirette de tutarlı sözle sağlamlaştırır. Allah, zalimleri şaşırtır. Allah, dilediğini yapar."},{"n":28,"t":"Bakmadın mı şunlara ki, Allah'ın nimetini inkârla/nankörlükle değiştirdiler ve toplumlarını helâk yurduna kondurdular."},{"n":29,"t":"Yaslanacakları cehenneme kondurdular. Ne kötü bir duruş yeridir o!"},{"n":30,"t":"Yolundan saptırmak için Allah'a eşler uydurdular. De ki: \"Hadi, nimetlenin! Sonunda varacağınız yer ateştir.\""},{"n":31,"t":"İnanan kullarıma söyle: Namazı/duayı yerine getirsinler, kendilerine verdiğimiz rızıklardan, hiçbir alışverişin, hiçbir dostluğun olmadığı o gün gelmeden önce, gizli ve açık infak etsinler."},{"n":32,"t":"Allah odur ki, gökleri ve yeri yarattı. Gökten bir su indirdi de onunla size rızık olarak türlü meyveler çıkardı. Emriyle denizde akıp gitmeleri için gemileri hizmetinize verdi. Irmakları da emrinize verdi."},{"n":33,"t":"Görevlerini şaşmadan yapmak üzere Güneş'i ve Ay'ı da size boyun eğdirdi. Geceyi ve gündüzü de hizmetinize verdi."},{"n":34,"t":"Kendisinden istediğiniz her şeyden size bir parça verdi. Allah'ın nimetini saymaya kalksanız, sayıp bitiremezsiniz. Doğrusu şu ki insan, gerçekten çok zalim, çok nankördür."},{"n":35,"t":"Bir zaman, İbrahim şöyle demişti: \"Rabbim, bu beldeyi güvenli kıl. Beni ve oğullarımı putlara kulluktan uzak tut!\""},{"n":36,"t":"\"Rabbim, onlar insanlardan birçoğunu saptırdılar. Artık beni izleyen bendendir. Bana isyan edene gelince, onun hakkında sen Gafûr ve Rahîm'sin."},{"n":37,"t":"\"Ey Rabbimiz! Ben, çocuklarımdan bir kısmını senin kutsal evinin yanındaki, ziraata elverişsiz vadiye yerleştirdim ki, namazı/duayı yerine getirsinler, ey Rabbimiz! Sen de insanlardan bazı gönülleri, onlardan hoşlanır yap. Çeşitli meyvelerle onları rızıklandır ki, şükredebilsinler!\""},{"n":38,"t":"\"Rabbimiz, hiç kuşkusuz sen bizim gizlediğimizi de bilirsin, açığa vurduğumuzu da. Yerde de gökte de hiçbir şey Allah'a gizli kalmaz.\""},{"n":39,"t":"\"İhtiyar yaşımda bana, İsmail ve İshak'ı bağışlayan Allah'a hamt olsun! Benim Rabbim, duayı gerçekten çok iyi duyar.\""},{"n":40,"t":"\"Rabbim! Beni, namazı/duayı yerine getiren bir insan yap. Soyumdan bir kısmını da. Rabbimiz, duamı kabul et!\""},{"n":41,"t":"\"Rabbimiz, hesabın ortaya geleceği gün; beni, anne-babamı ve inananları affet!\""},{"n":42,"t":"Sakın, Allah'ı, zalimlerin yapmakta olduğundan habersiz sanma. O, onları, gözlerin korkudan donup kalacağı bir güne erteliyor, hepsi bu..."},{"n":43,"t":"Başlarını dikerek koşuşurlar. Bakışları kendilerine dönmez. Yürekleri tamamen boşalmıştır."},{"n":44,"t":"İnsanları, azabın kendilerine ulaşacağı gün konusunda uyar. O gün, zalimler şöyle derler: \"Ey Rabbimiz! Bizi yakın bir süreye kadar geri bırak da çağrına cevap verip resullere uyalım.\" Daha önce siz, kendiniz için çöküş ve bitiş yoktur diye yemin etmediniz mi?"},{"n":45,"t":"Siz de öz benliklerine zulmetmiş olanların yurtlarında oturdunuz. Onlara ne yaptığımız size açıkça belirdi. Ve size örnekler de verdik."},{"n":46,"t":"Gerçekten onlar tuzaklarını kurmuşlardı. Onların tuzakları dağları yerinden oynatacak nitelikte olsa bile, tuzakları Allah katındadır/ Allah'ın kontrolündedir."},{"n":47,"t":"Sakın Allah'ı, resullerine verdiği söze ters düşer sanma. Allah Azîz'dir, intikam da alır."},{"n":48,"t":"O gün yerküre başka bir yerküreye dönüştürülür. Gökler de öyle. Hepsi o Vâhid ve Kahhâr olan Allah'ın huzurunda dikilir."},{"n":49,"t":"O gün suçluların, birbirine perçinlenmiş bukağılarla çengellendiklerini görürsün."},{"n":50,"t":"Gömlekleri katrandandır. Yüzlerini ateş bürümüştür."},{"n":51,"t":"Çünkü Allah, her benliği kendi kazandığıyla karşı karşıya getirecektir. Allah, hesabı çok çabuk görür."},{"n":52,"t":"İşte bu, onunla uyarılsınlar, Allah'ın tek ilah olduğunu bilsinler, aklı ve gönlü işleyenler de ibret alsınlar diye, insanlara yöneltilmiş bir tebliğdir."}],[{"n":1,"t":"Elif, Lâm, Râ. İşte sana o Kitap'ın ve açık anlatımlı Kur'an'ın ayetleri."},{"n":2,"t":"O küfre batmış olanlar zaman zaman, keşke Müslüman olsaydık diye derin bir özlem duyarlar."},{"n":3,"t":"Bırak onları yesinler, nimetlenip zevk etsinler ve sonu gelmez arzu kendilerini oyalasın. Ama yakında bilecekler."},{"n":4,"t":"Biz hiçbir yurt ve medeniyeti, belirlenmiş bir yazgısı olmaksızın ortadan kaldırmadık."},{"n":5,"t":"Hiçbir ümmet kendisi için belirlenen sürenin ne önüne geçebilir ne de o süreyi geriletebilir."},{"n":6,"t":"Şöyle haykırdılar: \"Hey! Kendisine o zikir/Kur'an indirilen! Sen gerçekten tam bir delisin.\""},{"n":7,"t":"\"Hadi getirsene bize o melekleri, eğer doğru sözlülerdensen!\""},{"n":8,"t":"Biz o melekleri ancak ve ancak hak üzere, hak bir yolla indiririz. Ve o zaman inkârcılara göz açtırılmaz."},{"n":9,"t":"Hiç kuşkusuz, o zikiri/Kur'an'ı biz indirdik, biz; her hal ve şartta onu muhakkak koruyacak olan da biziz."},{"n":10,"t":"Yemin olsun ki, senden öncekilerin o ilk kümeleri içine de nebiler gönderdik biz!"},{"n":11,"t":"Onlara bir Tanrı elçisi gelir gelmez, onunla mutlaka alay ederlerdi."},{"n":12,"t":"Biz ona, günaha batmışların gönüllerinde böyle bir yol veririz."},{"n":13,"t":"Ona inanmazlar. Oysaki, öncekilerin yol ve yöntemleri gözlerinin önünden geçmiştir."},{"n":14,"t":"Üzerlerine gökten bir kapı açsak da oradan yükseliyor olsalardı."},{"n":15,"t":"Kesinlikle şöyle diyeceklerdi: \"Bizim gözlerimiz döndürüldü, bakışlarımız sarhoş edildi. Belki de biz büyüye çarptırılmış bir toplumuz.\""},{"n":16,"t":"Yemin olsun, biz gökte burçlar oluşturduk ve onu/onları, seyredenler için süsledik."},{"n":17,"t":"Ve onu/onları, her kovulup taşlanmış şeytandan koruduk."},{"n":18,"t":"Ancak kulak hırsızlığı eden olur; onun peşine de parlak bir ateş alevi düşer."},{"n":19,"t":"Yeri yayıp döşedik, ona kuvvetli dağlar diktik ve içinde ölçülü/ahenkli her şeyden bitirdik."},{"n":20,"t":"Orada sizin için ve rızıklandırıcısı siz olmadığınız kimse için geçimlikler yarattık."},{"n":21,"t":"Hiçbir şey yoktur ki, hazineleri bizim yanımızda olmasın. Ama biz onu ancak belirli bir ölçüde/bir kaderle indiririz."},{"n":22,"t":"Rüzgârları dölleyiciler olarak gönderdik; gökten bir su indirdik de onunla sizi suvardık. Onun depolayıcıları siz değilsiniz."},{"n":23,"t":"Biz, elbette biz, hayat veriyoruz; biz öldürüyoruz. Ve biziz Vâris olanlar/mirasçı kalanlar."},{"n":24,"t":"Yemin olsun, sizin önden gidenlerinizi bilmişizdir; yemin olsun, geriye kalanları da bilmişizdir."},{"n":25,"t":"Hiç kuşkusuz, Rabbindir, evet O'dur onları haşredecek olan. Hakîmdir O, Alîm'dir."},{"n":26,"t":"Yemin olsun, biz insanı; kuru çamurdan, değişken-cıvık bir balçıktan yarattık."},{"n":27,"t":"Cini/İblis'i de daha önce kavurucu ateşten yaratmıştık."},{"n":28,"t":"Hatırla o zamanı ki Rabbin meleklere, \"Ben, kupkuru bir çamurdan, değişken, cıvık balçıktan bir insan yaratacağım.\" demişti."},{"n":29,"t":"\"Onu, amaçlanan düzgünlüğe ulaştırıp öz ruhumdan içine üflediğim zaman, önünde hemen secdeye kapanın.\""},{"n":30,"t":"Meleklerin tümü, toplu halde secde ettiler."},{"n":31,"t":"İblis müstesna. O, secde edenlerle beraber olmaya karşı çıktı."},{"n":32,"t":"Allah dedi: \"Ey İblis! Sana ne oluyor da secde edenlerle beraber olmuyorsun?\""},{"n":33,"t":"Dedi: \"Kuru bir çamurdan, değişken-cıvık bir balçıktan yarattığın bir insana secde etmek için var olmadım.\""},{"n":34,"t":"Buyurdu: \"Öyleyse çık oradan, çünkü kovuldun.\""},{"n":35,"t":"\"Din gününe kadar üzerinde lanet var.\""},{"n":36,"t":"Dedi: \"Rabbim, onların diriltileceği güne kadar bana süre ver.\""},{"n":37,"t":"Buyurdu: \"Hadi, süre verilenlerdensin.\""},{"n":38,"t":"\"Bilinen vaktin gününe kadar...\""},{"n":39,"t":"Dedi: \"Rabbim! Beni azdırmana yemin ederim ki, yeryüzünde onlar için mutlaka süslemeler yapacağım ve onların tümünü kesinlikle azdıracağım.\""},{"n":40,"t":"\"İçlerinden riyaya sapmamış, samimi kulların müstesna.\""},{"n":41,"t":"Buyurdu: \"İşte bana varan dosdoğru yol budur.\""},{"n":42,"t":"\"Benim kullarım aleyhine senin elinde hiçbir güç/kanıt olmayacak. Azgınların seni izleyenleri müstesna.\""},{"n":43,"t":"Cehennem onların tümünün şaşmaz buluşma yeridir."},{"n":44,"t":"Yedi kapısı vardır onun. Her kapıya onlardan bir bölük ayrılmıştır."},{"n":45,"t":"Sakınılması gereken şeylerden sakınanlar ise cennetlerde pınarlar içindedir."},{"n":46,"t":"\"Güvene kavuşmuş olarak selamla girin oraya.\""},{"n":47,"t":"Göğüslerindeki düşmanlığı çekip almışızdır. Köşkler/divanlar üzerinde karşı karşıya oturan kardeşler olmuşlardır."},{"n":48,"t":"Orada kendilerine zahmet/yorgunluk dokunmaz. Oradan çıkarılmazlar da."},{"n":49,"t":"Haber ver kullarıma: Hiç kuşkusuz benim, evet benim, Gafûr ve Rahîm."},{"n":50,"t":"Ama acıklı azabın ta kendisidir benim azabım."},{"n":51,"t":"Onlara İbrahim'in misafirlerinden bahset."},{"n":52,"t":"Hani onun yanına girmişlerdi de \"Selam!\" demişlerdi. O da \"Biz sizden korkuyoruz.\" diye konuşmuştu."},{"n":53,"t":"\"Korkma! Biz sana bilgin bir oğlan müjdeliyoruz.\" dediler."},{"n":54,"t":"Dedi: \"İhtiyarlık yakama yapıştıktan sonra mı bana müjde veriyorsunuz! Neye dayanarak müjde veriyorsunuz?\""},{"n":55,"t":"Dediler: \"Hakk'a dayanarak müjdeledik sana, sakın ümitsizliğe düşenlerden olma.\""},{"n":56,"t":"Dedi: \"Sapıtmışlardan başka kim ümit keser Rabbin rahmetinden!\""},{"n":57,"t":"\"Amacınız nedir ey elçiler?\" diye sordu."},{"n":58,"t":"Dediler: \"Biz günahkâr bir topluluğa gönderildik.\""},{"n":59,"t":"\"Yalnız Lût'un ailesi suçlu değildir. Biz onların hepsini kurtaracağız.\""},{"n":60,"t":"\"Lût'un karısı hariç. O günahkârla geriye kalacaktır. Öyle takdir ettik.\""},{"n":61,"t":"Elçiler Lût ailesine geldiklerinde,"},{"n":62,"t":"Lût: \"Siz tanınmayan kimlersiniz.\" dedi."},{"n":63,"t":"Dediler: \"Sana öyle bir şey getirdik ki, onun hakkında kuşkulanıp duruyorlardı.\""},{"n":64,"t":"\"Sana gerçeği getirdik. Biz, özü-sözü doğru olanlarız.\""},{"n":65,"t":"\"Gecenin bir yerinde aileni yola çıkar. Sen de arkalarından onları izle. Hiçbiriniz geri dönüp bakmasın. Emredildiğiniz yere kadar gidin.\""},{"n":66,"t":"Ona şu emri bir hüküm olarak ilettik: Şunlar, kökleri kesilmiş olarak sabahlayacaklardır."},{"n":67,"t":"Şehir halkı geldi. Muştulanmış olmanın sevincini yaşıyorlardı."},{"n":68,"t":"Lût dedi: \"Bunlar benim konuklarımdır, aman beni utandırmayın!\""},{"n":69,"t":"\"Allah'tan korkun, beni rezil etmeyin.\""},{"n":70,"t":"Dediler: \"Seni elâlemin işiyle uğraşmaktan men etmemiş miydik?\""},{"n":71,"t":"Lût dedi: \"Eğer bir şey yapacaksanız, işte kızlarım!\""},{"n":72,"t":"Senin ömrüne yemin olsun ki onlar, kendi sersemlikleri içinde bocalıyorlardı."},{"n":73,"t":"Nihayet o korkunç titreşimli ses, onları güneş doğarken yakaladı."},{"n":74,"t":"O kentin üstünü altına getirdik/üst düzeydekileri alt düzeye indirdik. Ve üzerlerine pişmiş çamurdan taşlar yağdırdık."},{"n":75,"t":"Hiç kuşkusuz, bunda, işaretlerden anlam çıkaranlar için ibretler vardır."},{"n":76,"t":"O kentin izleri/işaretleri, hâlâ işleyen bir yol üzerindedir."},{"n":77,"t":"İnananlar için bunda elbette bir ibret vardır."},{"n":78,"t":"Eyke halkı da gerçekten zalim insanlardı."},{"n":79,"t":"Onlardan intikam aldık. Her ikisi önde, belirgin bir biçimde durmaktadır."},{"n":80,"t":"Yemin olsun, Hicr halkı da gönderilen elçileri yalanladı."},{"n":81,"t":"Ayetlerimizi onlara verdik ama onlardan yüz çeviriyorlardı."},{"n":82,"t":"Dağlardan güvenli güvenli evler yontuyorlardı."},{"n":83,"t":"Korkunç titreşimli ses onları da sabaha girecekleri sırada yakaladı."},{"n":84,"t":"Kazanıp durdukları şeylerin kendilerine hiçbir yararı olmadı."},{"n":85,"t":"Biz gökleri, yeri ve bunların arasındakileri hak olarak yarattık. O saat elbette gelecektir. Şimdi sen, uzanan elleri tut, güzel davran."},{"n":86,"t":"Kuşkusuz senin Rabbin, evet o, Hallâk'tır, hiç durmadan yaratır; en iyi şekilde bilir."},{"n":87,"t":"Yemin olsun ki, biz sana ikişerlerden/ikililerden/iç içe kıvrımlar halindeki çift mânalılardan yedi taneyi ve şu büyük Kur'an'ı verdik."},{"n":88,"t":"Sakın, onlardan bazı çiftlere verdiğimiz nimet ve zevklere gözlerini dikme. Onlar için tasalanma da. Müminler için kanadını indir sen!"},{"n":89,"t":"Ve de ki: \"Ben, evet ben, apaçık konuşan bir uyarıcıyım!\""},{"n":90,"t":"Aynı şekilde, o bölücülere/yemin edip duranlara da beyyineler indirmiştik."},{"n":91,"t":"Onlar ki Kur'an'ı parça parça/bölük bölük/falcılık aracı yaptılar."},{"n":92,"t":"Rabbine yemin olsun ki, biz onları toplu halde sorgu suale çekeceğiz/hepsinden mutlaka hesap soracağız;"},{"n":93,"t":"Yapıp ettiklerinden..."},{"n":94,"t":"Emrolunduğun şeyi, kafalarını çatlatırcasına tebliğ et; şirke bulaşmışlara aldırma."},{"n":95,"t":"Alay edip eğlenenlere karşı biz sana yeteriz."},{"n":96,"t":"Allah ile beraber başka tanrılar benimseyenler yakında bilecekler."},{"n":97,"t":"Yemin olsun ki, onların söyledikleri yüzünden senin göğsünün daraldığını biliyoruz."},{"n":98,"t":"Şimdi sen, Rabbine hamd ile tespih et ve secde edenlerden ol!"},{"n":99,"t":"Sana şaşmaz ve kesin bilgi gelinceye kadar Rabbine ibadet et!"}],[{"n":1,"t":"Allah'ın emri geldi. Onunla yüzyüze gelmekte acele etmeyin. Tüm varlığın tespih ettiğidir o Allah. Arınmıştır onların şirk koştuklarından."},{"n":2,"t":"Kullarından dilediğine melekleri, emrinden olan ruh ile şöyle diyerek indirir: \"Gerçek şu: Benden başka ilah yok, o halde benden sakının!\""},{"n":3,"t":"Gökleri ve yeri hak olarak yarattı. Arınmıştır onların ortak tuttukları şeylerden."},{"n":4,"t":"İnsanı bir spermden yarattı. Bir de bakmışsın insan, açıkça kafa tutan bir hasım oluvermiştir."},{"n":5,"t":"Davarları da O yaratmıştır. Onlarda sizin için bir ısıtıcı-koruyucu ve nice nice yararlar vardır. Onlardan bazı şeyleri/onlardan bazılarını yersiniz."},{"n":6,"t":"Bir güzellik de vardır onlarda sizin için: Sabah saldığınız sırada, akşam topladığınız sırada."},{"n":7,"t":"Ve ağırlıklarınızı yüklenir, canlarınızın yarısını tüketmeden varamayacağınız beldelere kadar taşırlar. Hiç kuşkusuz, Rabbiniz gerçekten Raûf'tur, çok acıyıp esirger; Rahîm'dir, sınırsızca merhamet eder."},{"n":8,"t":"Hem binesiniz diye hem de bir süs olarak atları, katırları, eşekleri de yarattı. Ve bilemeyeceğiniz daha neler yaratır O..."},{"n":9,"t":"Yolu doğrultup denge noktasını bulmak Allah'ın işidir. Ondan sapan da var. Allah dileseydi, sizi toptan hidayete erdirirdi."},{"n":10,"t":"O sizin için gökten bir su indirdi; ondan bir içecek var. Kendisinden hayvanlarınıza yedirdiğiniz bir ağaç da ondan oluşmaktadır."},{"n":11,"t":"O suyla sizin için ekin, zeytin, hurmalıklar, üzümler ve her çeşitten meyvalar bitirir. Hiç kuşkusuz, bunda, derin derin düşünen bir toplum için gerçek bir mucize vardır."},{"n":12,"t":"Geceyi, gündüzü, Güneş'i ve Ay'ı sizin emrinize vermiştir. Yıldızlar da O'nun emriyle bir hizmete boyun eğmiştir. Bütün bunlarda, aklını çalıştıran bir topluluk için elbette ibretler vardır."},{"n":13,"t":"Ve sizin için yeryüzünde, çeşit çeşit renklerde başka şeylere de vücut vermiştir. Bütün bunlarda, düşünüp ibret alacak bir toplum için elbette bir mucize vardır."},{"n":14,"t":"Ve O'dur ki, içinden taze bir et yemeniz ve kuşanacağınız bir süs çıkarmanız için denizi emrinize vermiştir. Gemileri onda yara yara gider görürsün. Böyle yapmıştır ki, O'nun kereminden nasip arayasınız ve şükredebilesiniz."},{"n":15,"t":"Sizi çalkayıp sarsar diye yerküreye ağır dağlar, ırmaklar, yollar koydu. İyiye ve doğruya ulaşmanız umulmaktadır."},{"n":16,"t":"Ve nice işaretler! Yıldızla da onlar, yol ve yön doğrulturlar."},{"n":17,"t":"Yaratan, yaratmayana benzer mi? Hiç düşünmüyor musunuz?"},{"n":18,"t":"Allah'ın nimetlerini saymaya kalkarsanız, onların sonunu getiremezsiniz. Allah, gerçekten Gafûr ve Rahîm'dir."},{"n":19,"t":"Allah, sizin gizlediğinizi de açığa vurduğunuzu da bilir."},{"n":20,"t":"Allah dışında yakardıklarınız hiçbir şey yaratamazlar; onların kendileri yaratılmaktadır."},{"n":21,"t":"Hayat bulmaz ölülerdir onlar. Ne zaman dirilteceklerini bile bilmezler."},{"n":22,"t":"Tanrınız bir tek tanrıdır. Böyle iken, âhirete inanmayanlar, kibre saplandıkları için kalpleri inkârcı olmuştur."},{"n":23,"t":"Hiç kuşkusuz Allah, onların sakladıklarını da açığa vurduklarını da biliyor. Hiç kuşkusuz, O, büyüklük taslayanları sevmiyor."},{"n":24,"t":"Onlara, \"Rabbiniz ne indirdi\" dendiğinde şöyle dediler: \"Öncekilerin masallarını.\""},{"n":25,"t":"Şunun için ki, onlar, kıyamet günü kendi günahlarını tamamen yüklendikten başka, ilimsizlik yüzünden saptırdıkları kişilerin günahlarının bir kısmını da yüklenecekler. Bakın, ne kötü şey yükleniyorlar!"},{"n":26,"t":"Onlardan öncekiler tuzak kurmuşlardı. Bunun üzerine Allah, binalarına temellerinden çarpmış da üstlerindeki tavan tepelerine çökmüştü. Azap onlara hiç fark edemedikleri yerden gelmişti."},{"n":27,"t":"Sonra, kıyamet günü onları rezil edecek ve diyecek: \"Kendileri için kavga çıkarıp ayrılığa düştüğünüz ortaklarım nerede?\" Kendilerine ilim verilmiş olanlar diyecekler ki: \"Bugün rezillik ve kötülük, gerçeği inkâr edenleredir.\""},{"n":28,"t":"Öz benliklerine zulmedip durdukları bir sırada, meleklerin vefat ettirdikleri kişiler şöyle diyerek teslim bayrağını çekerler: \"Biz hiçbir kötülük yapmıyorduk.\" İş hiç de öyle değil. Allah, sizin yapmakta olduklarınızı çok iyi bilmektedir."},{"n":29,"t":"Hadi, girin cehennem kapılarından; sürekli kalacaksınız orada. Gerçekten kötü yermiş kibre sapanların barınağı."},{"n":30,"t":"Korunup sakınanlara, \"Rabbiniz ne indirdi\" dendiğinde şöyle dediler: \"Hayır indirdi.\" Bu dünyada güzel düşünüp güzel davrananlara güzellik vardır. Âhiret yurdu elbette ki daha hayırlıdır. Gerçekten ne güzelmiş takva sahiplerinin yurdu!"},{"n":31,"t":"Adn cennetleri... Girecekler içlerine. Altlarından ırmaklar akacak. Orada diledikleri şey kendilerinin olacak. Allah, korunup sakınanları işte böyle ödüllendirir."},{"n":32,"t":"Melekler, canlarını temiz insanlar olarak aldıklarına şöyle derler: \"Selam size, yapıp ettiklerinize karşılık olarak girin cennete!\""},{"n":33,"t":"Neyi bekliyorlar? Kendilerine meleklerin gelmesini mi, yoksa Allah'ın emrinin gelmesini mi? Onlardan öncekiler de aynen böyle yapmışlardı. Allah onlara zulüm etmemişti. Tam aksine, onlar kendi kendilerine zulüm ediyorlardı."},{"n":34,"t":"Sonunda, yapıp ettiklerinin kötülükleri başlarına musibet olmuş, alay edip durdukları şey kendilerini sarıvermiştir."},{"n":35,"t":"Ortak koşanlar dediler ki: \"Eğer Allah isteseydi biz de atalarımız da Allah dışında bir şeye kulluk/ibadet etmez, O'na rağmen hiçbir şeyi haram kılmazdık.\" Onlardan öncekiler de aynen böyle yaptılar. Resullere düşen, açık bir tebliğden başkası değildir."},{"n":36,"t":"Yemin olsun, biz her ümmette şöyle tebliğ yapan bir resul görevlendirdik: \"Allah'a kulluk/ibadet edin, tâğuttan kaçının. Sonra bunlardan kimine Allah kılavuzluk etti, kimine de sapıklık hak oldu. Şimdi, yeryüzünde gezip dolaşın da yalanlayanların sonu nasıl olmuş görün."},{"n":37,"t":"Sen onların iyiye ve doğruya ulaşmalarını tutkuyla istesen de Allah, saptırdığına yol göstermez. Hiçbir yardımcıları da olmaz onların."},{"n":38,"t":"Yeminlerinin tüm gücüyle, \"Allah ölen kimseyi diriltmez!\" diye Allah'a yemin ettiler. Hayır, öyle değil! Öleni diriltmek O'nun üzerinde hak bir vaattır, fakat insanların çokları bilmezler."},{"n":39,"t":"Diriltecek ki, onlara, ihtilafa düştükleri şeyi açık-seçik göstersin ve küfre sapanlar kendilerinin yalancılar olduğunu bilsinler."},{"n":40,"t":"Biz bir şeyi dilediğimizde, onun hakkında söyleyeceğimiz söz, \"Ol!\" demekten ibarettir; o hemen oluverir."},{"n":41,"t":"Zulme uğratıldıktan sonra Allah uğrunda hicret edenlere biz, dünyada elbette güzelce mekân tutturacağız. Âhiretin ödülü mutlaka daha büyüktür. Bir bilselerdi!"},{"n":42,"t":"O Allah yolunda hicret edenler, sabrederler ve yalnız Rablerine tevekkül ederler."},{"n":43,"t":"Biz senden önce de elçi olarak kendilerine vahyettiğimiz erkeklerden başkasını göndermedik. Eğer bilmiyorsanız, zikir/Kur'an ehline sorun."},{"n":44,"t":"Açık delillerle, kitaplarla gönderdik. Sana da bu zikiri/Kur'an'ı vahyettik ki, kendilerine indirileni insanlara açık-seçik bildiresin de derin derin düşünebilsinler."},{"n":45,"t":"Kötülükleri yapmak için tuzak kuranlar, Allah'ın kendilerini yere geçirmeyeceğinden yahut hiç fark edemeyecekleri bir yerden azabın kendilerine gelmeyeceğinden emin mi oldular?"},{"n":46,"t":"Yahut dönüp dolaşmaları sırasında kendilerini yakalamayacağından... Onlar buna engel de olamazlar."},{"n":47,"t":"Yoksa kendilerini korkuta korkuta, sindire sindire yakalamayacağından emin midirler? Kuşkusuz ki, sizin Rabbiniz gerçekten Raûf'tur, Rahîm'dir."},{"n":48,"t":"Bakıp görmediler mi, Allah'ın yarattığı şeylerin gölgeleri bile, sağ ve sollarından boyunları bükük bir halde, Allah için secdelere kapanarak dönüyor."},{"n":49,"t":"Göklerdeki ve yerdeki canlı şeyler de melekler de yalnız Allah'a secde ederler ve hiç de büyüklük taslamazlar."},{"n":50,"t":"Üstlerinde egemen olan Rablerinden ürperirler ve emredildikleri şeyi yaparlar."},{"n":51,"t":"Allah buyurdu ki: \"İki ilah edinmeyin; O sadece bir tek ilahtır. Yalnız benden korkun.\""},{"n":52,"t":"Göklerde ve yerde ne varsa O'nundur. Din de sürekli olarak yalnız O'nundur. Hâlâ, Allah'tan başkasından mı sakınıyorsunuz!"},{"n":53,"t":"Sahip olduğunuz her nimet Allah'tandır. Sonra size bir zorluk/keder dokunduğu zaman yalnız O'na yakarırsınız."},{"n":54,"t":"Sonra da zorluk ve kederi sizden kaldırdığında, içinizden bir zümre kendi Rablerine hemen ortak koşuverir,"},{"n":55,"t":"Kendilerine verdiklerimize nankörlük etmek için böyle yaparlar. Şimdi zevklenin bakalım; yakında bileceksiniz!"},{"n":56,"t":"Tutuyor, kendilerine verdiğimiz rızıklardan, hiçbir şeyin farkında olmayanlara pay çıkarıyorlar. Allah'a yemin olsun ki, iftira edip durduğunuz şeylerden kesinlikle hesaba çekileceksiniz."},{"n":57,"t":"Tutuyor, Allah'a kızları nispet ediyorlar. Hâşâ! O, bunlardan arınmıştır. İştah duydukları şeyler de kendilerinin mi?"},{"n":58,"t":"Onlardan birine kız çocuk müjdelendiğinde yüzü simsiyah kesilir. Öfkeden yutkunur da yutkunur o!"},{"n":59,"t":"Kendisine muştulananın utancından ötürü toplumdan gizlenir. Hakaret/eziklik üzere tutsun mu onu yoksa toprağın bağrına mı gömsün onu. Bakın ne kötü hüküm veriyorlar!"},{"n":60,"t":"Âhirete inanmayanlar için kötülük örneği var. En yüce örnekse Allah içindir. O'dur Azîz, O'dur Hakîm."},{"n":61,"t":"Eğer Allah, insanları zulümlerine karşı cezalandırsaydı, yeryüzünde debelenen bir şey bırakmazdı. Ama öyle yapmıyor, onları belirli bir süreye kadar erteliyor. Süreleri geldiğinde ise ne bir saat geri kalırlar ne de öne geçebilirler."},{"n":62,"t":"Kendilerinin bile çirkin bulacağı şeyleri Allah'a isnat ediyorlar. Dilleri de yalan düzüp donatıyor: En ileri güzellik onlarınmış! Kuşkusuz olan şu: Onlar için ateş vardır. Ve ona en önden gideceklerdir."},{"n":63,"t":"Yemin olsun Allah'a ki, senden önceki ümmetlere de elçiler gönderdik de şeytan onlara amellerini süslü gösterdi. O, bugün de onların dostudur/ o gün de onların dostu idi. Onlar için acıklı bir azap var."},{"n":64,"t":"Bu Kitap'ı sana yalnız şunun için indirdik: Hakkında ayrılığa düştükleri şeyi onlara iyice açıklayasın ve Kitap, iman eden bir topluluk için kılavuz ve rahmet olsun."},{"n":65,"t":"Allah, gökten bir su indirdi de onunla, ölümünden sonra yeryüzüne hayat verdi. Kuşkusuz, bunda kulak verip dinleyen bir topluluk için mutlaka bir mucize vardır."},{"n":66,"t":"Hayvanlarda da sizin için kesin bir ibret vardır. Size onların karınlarından, fışkı ile kan arasından halis bir süt içiriyoruz ki, içenlerin boğazlarından kayar gider."},{"n":67,"t":"Hurmalıkların meyvalarından, üzümlerden de sarhoş edici bir içecek ve güzel bir rızık elde edersiniz. İşte bunda, aklını işleten bir topluluk için kesin bir mucize vardır."},{"n":68,"t":"Rabbin, balarısına şöyle vahyetti: \"Dağlardan evler edin, ağaçlardan ve insanların kurdukları çardaklardan da...\""},{"n":69,"t":"\"Sonra, meyvaların her türünden ye de boyun bükerek Rabbinin yollarına koyul.\" Onun karıncıklarından, renkleri çeşit çeşit bir içecek çıkar ki, insanlar için onda şifa vardır. Derin derin düşünen bir topluluk için, bunda kesin bir mucize var."},{"n":70,"t":"Allah sizi yarattı, sonra sizi vefat ettirecek. İçinizden bazıları, ömrün en basit ve düşük noktasına geri çevirilir ki, bir ilimden sonra hiçbir şey bilmez olsun. Allah Alîm'dir, Kadîr'dir."},{"n":71,"t":"Allah, rızıkta kiminizi kiminize üstün kılmıştır. Fazla verilenler, rızıklarını ellerinin altındakilere aktarıp da hepsi onda eşit hale gelmiyor. Allah'ın nimetini mi inkâr ediyor bunlar?"},{"n":72,"t":"Allah size, kendi benliklerinizden eşler nasip etti. Eşlerinizden de sizin için oğullar ve torunlar oluşturdu. Ve sizleri güzel ve temiz nimetlerle rızıklandırdı. Şimdi bunlar, bâtıla mı inanıyorlar? Ve bunlar, evet bunlar, Allah'ın nimetine nankörlük mü ediyorlar?"},{"n":73,"t":"Allah'ı bırakıp da kendilerine, göklerden ve yerden bir parçacık rızık veremeyen, buna güç yetiremeyen şeylere mi tapıyorlar?"},{"n":74,"t":"Artık Allah'a örnekler verip durmayın. Allah bilir, siz bilmezsiniz."},{"n":75,"t":"Allah şöyle bir örnekleme yaptı: Hiçbir şeye gücü yetmeyen, başkasının eşyası durumunda bir kul/köle ile bizden bir güzel rızıkla rızıklandırdığımız ve ondan gizli-açık dağıtan bir kişi. Bunlar aynı olur mu?! Bütün övgüler Allah'adır ama onların çokları bilmiyorlar."},{"n":76,"t":"Allah şöyle bir örnekleme de yaptı: İki adam; birisi dilsiz; hiçbir şeye gücü yetmez, efendisi/yöneticisi üstüne sadece bir yük. Efendi onu nereye gönderse hiçbir hayır getiremez. Şimdi bu adam, dosdoğru bir yol üzerinde bulunup adaletle emreden kişi ile aynı olur mu?"},{"n":77,"t":"Göklerin ve yerin gaybı Allah'ındır. O saate/dünyanın sonuna ilişkin emirse bir göz açıp yummak gibi, hatta ondan da yakındır. Allah her şeye kadirdir."},{"n":78,"t":"Allah sizi annelerinizin karınlarından çıkardı, hiçbir şey bilmiyordunuz; şükredebilesiniz diye size işitme gücü, gözler ve gönüller verdi."},{"n":79,"t":"Gök boşluğunda, bir emre boyun eğdirilmiş olan kuşlara bakmadılar mı? Onları Allah'tan başkası tutmuyor. Bunda, inanan bir topluluk için elbette ki izler-işaretler vardır."},{"n":80,"t":"Allah size evlerinizi bir huzur ve dinlenme yeri yaptı. Ve sizin için hayvanların derilerinden, göç gününüzde ve ikamet gününüzde kolayca taşıyacağınız barınaklar; onların yünlerinden, yapağılarından ve kıllarından bir süreye kadar yararlanacağınız bir giyimlik/eşya ve bir imkân sağladı."},{"n":81,"t":"Allah, yarattıklarından sizin için gölgeler oluşturdu. Dağlardan sizin için sığınak evler yaptı. Sizin için, sıcaktan koruyacak elbiselerle savaşta koruyacak elbiseler de yaptı. İşte nimetini üzerinizde böyle tamamlıyor ki, O'na teslim olup esenliğe ulaşabilesiniz."},{"n":82,"t":"Yine de yüz çevirirlerse artık sana düşen, açık bir tebliğden başka şey değildir."},{"n":83,"t":"Allah'ın nimetini biliyorlar, sonra da onu inkâr ediyorlar. Çoğu nankördür bunların."},{"n":84,"t":"Her ümmetten bir tanığı ortaya sürdüğümüz gün, küfre sapanlara ne izin verilir ne de özür dilemelerine imkân sağlanır."},{"n":85,"t":"Zulme sapanlar azapla yüzyüze geldiklerinde, ne azapları hafifletilir ne de yüzlerine bakılır."},{"n":86,"t":"Şirke sapanlar, ortak tuttuklarını gördüklerinde şöyle derler: \"Rabbimiz, işte bunlar seni bırakıp da yalvarıp yakardığımız ortaklarımız.\" Bunun üzerine ortakları onlara şöyle söz dokundururlar: \"Siz, yalancılarsınız, yalancılar!\""},{"n":87,"t":"O gün hepsi Allah huzurunda teslim bayrağı çekmiş, iftira aracı olarak kullandıklarının tümü onları ortada bırakıp kaybolmuştur."},{"n":88,"t":"İnkâra sapıp Allah yolundan geri çevirenler var ya, bozgunculuk edip durmalarından ötürü onların azaplarına azap katmışızdır."},{"n":89,"t":"Gün olur, her ümmet için kendi aleyhlerine kendi içlerinden bir tanık çıkarırız. Seni de şu insanlar hakkında tanık olarak getireceğiz. Sana bu Kitap'ı indirdik ki herşey için ayrıntılı bir açıklayıcı, bir kılavuz, bir rahmet, Müslümanlara da bir müjde olsun."},{"n":90,"t":"Şu bir gerçek ki Allah; adaleti, iyi ve güzel davranmayı, akrabaya vermeyi emreder. Tüm pisliklerden/edepsizliklerden, kötülükten, azgınlık-doymazlık ve kıskançlıktan yasaklar. Düşünüp ibret alırsınız ümidiyle size öğüt veriyor."},{"n":91,"t":"Antlaşma yaptığınızda, Allah'a verdiğiniz söze vefa gösterin. Bağlayıp pekiştirdikten sonra yeminlerinizi bozmayın. Çünkü, kendinize Allah'ı kefil yapmış durumdasınız. Allah, yaptıklarınızı biliyor."},{"n":92,"t":"Yeminleri bozmada, ipliğini kuvvetle büktükten sonra bozup parçalayan karı gibi olmayın. Bir topluluk ötekinden daha zengin ve kalabalık çıktığı için yeminlerinizi aranızda bir hile aracı yapıyorsunuz. Allah sizi bununla imtihan ediyor; ihtilafa düştüğünüz şeyleri kıyamet günü size açık bir biçimde elbette gösterecektir."},{"n":93,"t":"Allah dileseydi, elbette ki sizi birtek ümmet yapardı. Ama O, dilediğini saptırıyor, dilediğini de iyiye ve güzele kılavuzluyor. Yapıp ettiklerinizden mutlaka sorgu-suale çekileceksiniz."},{"n":94,"t":"Yeminlerinizi aranızda hile ve aldatma aracı yapmayın; aksi halde, ayak sağlam bastıktan sonra kayar ve Allah yolundan alıkoyduğunuz için acıyı tadarsınız. Üstelik büyük bir azaba da uğrarsınız."},{"n":95,"t":"Allah'a verdiğiniz sözü basit bir ücret karşılığı satmayın. Eğer bilirseniz, Allah katında olan, sizin için daha hayırlıdır."},{"n":96,"t":"Sizin yanınızdaki tükenir ama Allah'ın yanındaki sonsuza dek kalıcıdır. Sabredenlere ödüllerini biz, işleyip ürettiklerinin en güzeliyle mutlaka vereceğiz."},{"n":97,"t":"Erkek yahut kadın, her kim inanmış olarak hayra ve barışa yönelik bir iş yaparsa, onu tertemiz bir hayatla yaşatırız. Ve böylelerinin ücretlerini, işleyip ürettiklerinin en güzelleriyle karşılarız."},{"n":98,"t":"Kur'an'ı okuduğun zaman, o kovulup taşlanmış şeytandan Allah'a sığın!"},{"n":99,"t":"Gerçek şu ki, inananlar ve yalnız Rablerine güvenip dayananlar üzerinde onun hiçbir nüfuzu/ yaptırım gücü yoktur."},{"n":100,"t":"Onun sultası, sadece onu dost edinenlerle Allah'a ortak koşanlar üstündedir."},{"n":101,"t":"Biz bir ayeti, bir başka ayetin yerine koyduğumuzda -ki Allah neyi indirmekte olduğunu daha iyi bilir- şöyle derler: \"Sen düpedüz bir iftiracısın.\" Hayır, öyle değil. Bunların çokları bilmiyorlar."},{"n":102,"t":"De ki: \"O'nu, kutsal ruh (Rûhülkudüs), inananları sağlamlaştırmak/sabit kılmak ve Müslümanlara bir hidayet, bir müjde olsun diye Rabbinizden hak olarak indirdi.\""},{"n":103,"t":"Yemin olsun ki, biz, onların, \"Kur'an'ı ona bir insan öğretiyor\" demekte olduklarını biliyoruz. Nispet etmeye uğraştıkları adamın dili yabancıdır. Oysaki bu, apaçık Arapça bir dildir."},{"n":104,"t":"Allah'ın ayetlerine inanmayanlara Allah kılavuzluk etmez. Onlar için acıklı bir azap öngörülmüştür."},{"n":105,"t":"Yalanı ancak, Allah'ın ayetlerine inanmayanlar uydururlar. Yalancılık edenler onların ta kendileridir."},{"n":106,"t":"Her kim imanından sonra Allah'a küfür eder, kalbi iman ile yatışmış halde iken baskıyla zorlanan hariç olmak üzere, inkâra göğüs açarsa, böylelerinin üzerine Allah'tan bir gazap iner. Bunlar için büyük bir azap da öngörülmüştür."},{"n":107,"t":"Bu böyledir, çünkü, onlar şu iğreti hayatı âhirete tercih etmişlerdir. Ve Allah, küfre sapanlar topluluğunu doğruya kılavuzlamaz."},{"n":108,"t":"Bunlar, Allah'ın; kalpleri, kulakları ve gözleri üstüne mühür bastığı insanlardır. Gaflete saplananlar da bunların ta kendileridir."},{"n":109,"t":"Hiç kuşkusuz, âhirette hüsrana uğrayacaklar da bunlardır."},{"n":110,"t":"Kuşkusuz, Rabbin; işkenceye uğratıldıktan sonra hicret eden, ardından da cihat edip sabreden kişiler yanındadır. Bütün bunlardan sonra senin Rabbin elbette cömertçe affedecek, cömertçe merhamet edecektir!"},{"n":111,"t":"Gün olur, herkes kendi nefsi için mücadele eder ve herkese, yaptığının karşılığı tam tamına ödenir; onlar asla zulme uğratılmazlar."},{"n":112,"t":"Allah, şu ülkeyi/medeniyeti de örnek vermiştir: Güvenli, mutlu-huzurlu idi; rızkı her yandan bol bol gelirdi. Sonra onlar Allah'ın nimetlerine nankörlük ettiler de Allah kendilerine, sanayi olarak ürettikleri şeyler yüzünden açlık ve korku elbisesini/birlikteliğini/karmaşasını tattırdı."},{"n":113,"t":"Yemin olsun ki, onlara içlerinden bir resul geldi de onu yalanladılar. Bunun üzerine, onlar zulümlerine devam edip dururken azap kendilerini yakaladı."},{"n":114,"t":"Allah'ın sizi rızıklandırdığı şeylerden helal ve temiz olarak yiyin! Eğer yalnız O'na ibadet ediyorsanız, Allah'ın nimetlerine şükredin!"},{"n":115,"t":"O size ancak şunları haram kılmıştır: Ölü/hayvan/leş, kan, domuz eti, Allah'tan başkası adına kesilen hayvan. Bununla birlikte, zorda kalan, başkasının hakkına tecavüz etmemek, sınırı da aşmamak şartıyla bunlardan yerse, Allah bağışlayacak, merhamet edecektir."},{"n":116,"t":"Yalan düzerek Allah'a iftira etmek için, dillerinizin uydurma nitelendirmeleriyle \"Şu helaldir, şu da haramdır!\" demeyin. Yalan düzerek Allah'a iftira edenler kurtulamazlar."},{"n":117,"t":"Az bir nimetlenme ardından, acıklı bir azap var onlara."},{"n":118,"t":"Sana anlattıklarımızı daha önce, Yahudilere haram kılmıştık. Biz onlara haksızlık etmedik; aksine, onlar kendi benliklerine zulmediyorlardı."},{"n":119,"t":"Şu da var: Rabbin, bilgisizlik yüzünden kötülük işleyip de bunun ardından tövbe edip hallerini düzeltenler lehindedir. Sonra senin Rabbin gerçekten Gafûr ve Rahîm'dir."},{"n":120,"t":"Şu da kuşkusuz ki, İbrahim başlı başına bir ümmet idi; bir hanîf olarak Allah'ın önünde eğiliyordu, müşriklerden değildi."},{"n":121,"t":"O'nun nimetlerine şükrediyordu. Allah onu seçip yüceltti ve dosdoğru bir yola kılavuzladı."},{"n":122,"t":"Dünyada ona güzellik verdik, âhirette de o mutlaka barışsever iyiler arasında yer alacaktır."},{"n":123,"t":"Daha sonra sana şunu vahyettik: Bir hanîf olarak İbrahim'in milletine uy! O, müşriklerden değildi."},{"n":124,"t":"Cumartesi tatili, sadece onda ihtilaf edenlere farz kılındı. Rabbin, tartışmakta oldukları şey hakkında, onlar arasında kıyamet günü hüküm verecektir."},{"n":125,"t":"Rabbinin yoluna hikmetle, güzel öğütle davet et ve onlarla, en güzel olan neyse o yolla mücadele et. Şüphe yok ki Rabbin, kendi yolundan sapanları en iyi bilendir. Ve O, gerçeğe kılavuzlananları da en iyi bilendir."},{"n":126,"t":"Eğer ceza ile karşılık verecekseniz, ancak size yapılan kötülüğün türü ve miktarı ile karşılık verin. Eğer sabrederseniz, elbette ki bu, sabredenler için daha hayırlıdır."},{"n":127,"t":"Sabret! Senin sabrın da Allah'ın yardımıyladır. Onlar için tasalanma! Kurmakta oldukları tuzaklar yüzünden de telaşlanma!"},{"n":128,"t":"Hiç kuşkusuz, Allah, sakınanlar ve güzel düşünüp güzel iş yapanlarla beraberdir."}],[{"n":1,"t":"Bütün varlıkların tespihi o kudrettir ki, ayetlerimizden bazılarını kendisine gösterelim/kendisini ayetlerimizden bir parça olarak gösterelim diye kulunu, gecenin birinde Mescit-i Haram'dan, çevresini bereketlendirdiğimiz Mescid-i Aksa'ya/o en uzak secdegâha yürütmüştür. Hiç kuşkusuz, O'dur Semî' ve Basîr."},{"n":2,"t":"Mûsa'ya Kitap'ı verdik ve onu, \"Benden başka bir vekil tutmayın!\" buyruğuyla Beniisrail'e bir kılavuz kıldık."},{"n":3,"t":"Ey Nûh ile beraber taşıdığımız kişilerin soyu! Gerçek şu ki, Nûh çok şükreden bir kuldu."},{"n":4,"t":"Biz, Beniisrail'e Kitap'ta şu yolda bir yargıda bulunduk: Siz yeryüzünde muhakkak iki kez bozgun vücuda getireceksiniz ve muhakkak büyük bir kibirle böbürleneceksiniz."},{"n":5,"t":"Nihayet, o ikiden birincinin vadesi geldiğinde, üzerinize aşılmaz bir güce sahip kullarımızı gönderdik de onlar, barınakların aralarına girip araştırdılar. Ve bu, yerine getirilmiş bir vaat idi."},{"n":6,"t":"Sonra onlar üzerinde size tekrar egemenlik verdik, mallar ve oğullarla sizi güçlendirdik ve sizi toplum olarak çoğalttık."},{"n":7,"t":"Eğer güzel davranırsanız, kendi benlikleriniz için güzellik sergilemiş olursunuz. Ve eğer kötülük yaparsanız o da benlikleriniz aleyhine olur. Bu sırada, yüzlerinizi çirkinleştirsinler, ilk kez girdikleri gibi mabede girsinler ve egemenlik altına aldıklarını yerle bir etsinler diye ikinci vaat geldi."},{"n":8,"t":"Rabbiniz size belki rahmet eder. Ve eğer yine eski duruma dönerseniz, biz de döneriz. Ve biz, cehennemi, küfre batanlar için çepeçevre kuşatan bir zından yapmışızdır."},{"n":9,"t":"Şüpheniz olmasın ki bu Kur'an en kalıcı, en doğru olana kılavuzlar ve müminlere şu yolda müjde verir: Barışa/hayra yönelik işler yapanlar için büyük bir ödül vardır."},{"n":10,"t":"Âhirete inanmayanlar var ya, onlar için biz korkunç bir azap hazırlamışızdır."},{"n":11,"t":"İnsan, hayra davet eder gibi şerri çağırıyor/insan, hayra duasıyla şerri davet ediyor. İnsan çok acelecidir."},{"n":12,"t":"Biz, geceyi ve gündüzü iki ayet yaptık; sonra gecenin ayetini silip gündüzün ayetini gösterici yaptık ki, Rabbinizden bir lütuf isteyesiniz, yılların sayısını ve hesabı bilesiniz. Biz her şeyi ayrıntılı bir biçimde açıkladık."},{"n":13,"t":"Her insanın uğursuzluk kuşunu onun boynuna takmışızdır. Kıyamet günü kendisine, önünde açılmış olarak bulacağı bir kitap çıkaracağız:"},{"n":14,"t":"\"Oku kitabını! Bugün sana hesap sorucu olarak öz benliğin yeter.\""},{"n":15,"t":"Kim yola gelirse kendisi için yola gelmiş olur. Sapıtan da kendi aleyhine sapıtmış olur. Hiçbir günahkâr, bir başka günahkârın yükünü taşımaz. Ve biz, bir resul göndermedikçe azap edici değiliz."},{"n":16,"t":"Biz bir ülkeyi/medeniyeti mahvetmek istediğimizde, onun servet ve nimetle şımarmış elebaşlarına emirler yöneltiriz/onları yöneticiler yaparız da onlar, orada bozuk gidişler sergilerler. Böylece o ülke/medeniyet aleyhine hüküm hak olur; biz de onun altını üstüne getiririz."},{"n":17,"t":"Nûh'tan sonra da nice kuşakları helak ettik. Kullarının günahlarını haber alıcı ve görücü olarak Rabbin yeter."},{"n":18,"t":"Peşin isteyene dünyada peşin veririz: Dilediğimize dilediğimiz kadar. Sonra da ona cehennemi veririz; yaslanır ona, kınanmış ve kovulmuş olarak."},{"n":19,"t":"Kim de âhireti ister ve inanmış olarak ona yaraşır bir gayretle çalışırsa, böylelerinin gayretleri teşekkürle karşılanır."},{"n":20,"t":"Rabbinin lütfundan nimetlerle hepsine uzanırız: Onlara da bunlara da. Rabbinin lütfu, kimse tarafından engellenemez/kısıtlanamaz."},{"n":21,"t":"Bak nasıl, kimini kimine üstün kıldık! Ama âhiret, dereceler bakımından elbette daha büyük, lütuflandırma bakımından daha yücedir."},{"n":22,"t":"Allah'ın yanına başka bir ilah koyma ki, yapayalnız ve horlanmış olarak oturup kalmayasın!"},{"n":23,"t":"Rabbin şöyle hükmetti: O'ndan başkasına kulluk/ibadet etmeyin, anaya-babaya çok güzel davranın: Onlardan birisi yahut her ikisi senin yanında ihtiyarlık çağına gelirse sakın onlara \"Öf!\" bile deme; onları azarlama, onlara tatlı-iltifatlı söz söyle."},{"n":24,"t":"Rahmetten yerlere eğilme kanadını onlar için indir ve de ki: \"Rabbim, merhametli davran onlara, tıpkı küçüklüğümde beni koruyup büyüttükleri gibi.\""},{"n":25,"t":"Benliklerinizin içindekini Rabbiniz daha iyi bilir. Eğer siz barışsever/iyi kişiler olursanız O, tövbeye sarılanları affeder."},{"n":26,"t":"Akrabaya hakkını ver! Çaresize, yolda kalana da. Fakat saçıp savurma!"},{"n":27,"t":"Çünkü saçıp savuranlar şeytanların kardeşleri olurlar. Ve şeytan, kendi Rabbine nankörlük etmiştir."},{"n":28,"t":"Eğer onlardan, Rabbinden ümit ettiğin bir rahmeti bekleme yüzünden yüz çevirecek olursan, o zaman onlara yumuşak/tatlı bir söz söyle."},{"n":29,"t":"Elini bağlayıp boynuna asma. Ama onu büsbütün de salıverme. Sonra kınanır, hasret içinde bir köşede büzülür kalırsın."},{"n":30,"t":"Hiç kuşkusuz Rabbin, dilediğine rızkı açar da kısar da. O, kullarını görüyor, onlardan haber alıyor."},{"n":31,"t":"Yoksulluk korkusuyla çocuklarınızı öldürmeyin. Onları da sizi de biz rızıklandırıyoruz. Kuşkusuz, onları öldürmek büyük bir günahtır."},{"n":32,"t":"Zinaya yaklaşmayın. Çünkü o iğrenç bir iştir; yol olarak da çok kötüdür."},{"n":33,"t":"Allah'ın saygıya layık kıldığı cana haklı bir sebep yokken kıymayın. Kim haksızlıkla öldürülürse, onun velisine yetki/söz hakkı vermişizdir. Ama o da öldürmede sınır tanımazlık etmesin. Çünkü kendisine yardım edilmiştir."},{"n":34,"t":"Yetimin malına yaklaşmayın. Ancak rüştüne erişinceye kadar, güzel bir yolla ilgilenebilirsiniz. Ahdinize vefalı olun çünkü verilen söz sorumluluk gerektirir."},{"n":35,"t":"Ölçtüğünüz zaman tam ve dürüst ölçün. Hilesiz teraziyle tartın. Bu, hem hayırlı hem de sonuç bakımından güzeldir."},{"n":36,"t":"Hakkında bilgin olmayan şeyin ardına düşme! Çünkü kulak, göz ve gönlün hepsi bundan sorumlu tutulacaktır."},{"n":37,"t":"Yeryüzünde kasılıp kabararak yürüme! Çünkü sen, yeri asla yırtamazsın, uzunlukça da dağlara ulaşamazsın."},{"n":38,"t":"Bütün bu sayılanların kötü olanları, Rabbin katında çirkin görülmüştür."},{"n":39,"t":"Bunlar, Rabbinin sana, hikmetten vahyetmiş olduklarıdır. Allah'ın yanına başka tanrı koyma ki, kınanmış ve kovulmuş bir halde cehenneme atılmayasın."},{"n":40,"t":"Rabbiniz, oğulları seçip size özgüledi de kendisi meleklerden kızlar mı edindi? Gerçekten siz çok dehşet verici bir söz söylüyorsunuz!"},{"n":41,"t":"Biz, gerçeği, Kur'an'da türlü biçimlerde ifade ettik ki, düşünüp anlayabilsinler. Fakat bu onların sadece kaçışlarını artırıyor."},{"n":42,"t":"De ki: \"Eğer onların dediği gibi Allah'la beraber ilahlar olsaydı, o zaman onlar arşın sahibine varmak için elbette bir yol ararlardı.\""},{"n":43,"t":"O hep tespih edilen, onların söylediklerinden çok uzak ve çok yüksek; hem de ölçüye sığmayacak kadar yüksek..."},{"n":44,"t":"Yedi gök, yerküre ve bunların içindekiler O'nu tespih ederler. Hiçbir şey yoktur ki, O'nu överek tespih etmesin; fakat siz onların tespihlerini fark edemezsiniz. O Halîm'dir, Gafûr'dur."},{"n":45,"t":"Kur'an okuduğunda, seninle, âhirete inanmayanlar arasına gizli bir perde çekeriz."},{"n":46,"t":"Kalpleri üzerine, onu anlamamaları için kabuklar geçiririz, kulaklarına da bir ağırlık koyarız. Rabbini yalnız Kur'an'da andığın zaman/Kur'an'da yalnız O'nu andığın zaman, nefretle geriye dönüp kaçarlar."},{"n":47,"t":"Onların seni dinlerken, neye kulak verdiklerini biz daha iyi biliriz. Aralarında fısıldaşırlarken de şöyle konuşur o zalimler: \"Büyülenmiş bir adamdan başkasının ardı sıra gitmiyorsunuz!\""},{"n":48,"t":"Bak nasıl örnekler verdiler sana, nasıl sapıttılar. Artık hiçbir yola varamazlar."},{"n":49,"t":"Dediler ki: \"Biz, bir yığın kemik olduğumuz, un-ufak hale geldiğimiz zaman mı, gerçekten biz o zaman mı yeni bir yaratılışla diriltileceğiz.\""},{"n":50,"t":"De ki: \"İster taş olun ister demir!\""},{"n":51,"t":"\"İsterseniz gönlünüzde büyüyen herhangi bir yaratık olun.\" Diyecekler ki: \"Peki bizi yeniden kim yaratacak?\" De ki: \"Sizi ilk kez yaratan kimse, o!\" Bunun üzerine başlarını sana doğru alaylı bir biçimde sallayarak şöyle konuşacaklar: \"Ne zaman o?\" De ki: \"Çok yakın olabilir!\""},{"n":52,"t":"Sizi çağıracağı gün, onu hamt ederek çağrısına derhal uyacaksınız. Ve sadece az bir süre kaldığınızı düşüneceksiniz."},{"n":53,"t":"Kullarıma de ki: En güzel olan neyse onu söylesinler. Çünkü şeytan, aralarına yamukluk sokar. Şeytan, insan için apaçık bir düşmandır."},{"n":54,"t":"Rabbiniz sizi daha iyi bilir. Dilerse size rahmet eder, dilerse size azap eder. Biz seni onlar üzerine vekil göndermedik."},{"n":55,"t":"Rabbin, göklerdeki ve yerdeki kimseleri de daha iyi bilir. Yemin olsun, biz, peygamberlerin bir kısmını bir kısmına üstün kılmışızdır. Davûd'a da Zebur'u verdik."},{"n":56,"t":"De ki: \"O'nun berisinden bel bağladıklarınızı çağırın; onlar, başınızdaki zorluk ve sıkıntıyı ne kaldırabilirler ne de değiştirebilirler.\""},{"n":57,"t":"O yakarıp durduklarının kendileri, en çok yakınlık kazanmışları da dahil, Rablerine varmaya vesîle ararlar; O'nun rahmetini umarlar, O'nun azabından korkarlar. Çünkü Rabbinin azabı gerçekten korkulasıdır."},{"n":58,"t":"Hiçbir kent/medeniyet dışta kalmamak üzere, kıyamet gününden önce hepsini ya helâk edeceğiz yahut da şiddetli bir azapla azaplandıracağız. İşte bu, Kitap'ta satır satır yazılmış bulunuyor."},{"n":59,"t":"Bizi, mucizeler göstermekten alıkoyan, daha öncekilerin onları yalanlamış olmasından başka bir şey değildir. Semûd kavmine o dişi deveyi açık bir mucize olarak verdik de onunla kendilerine zulmettiler. Biz, mucizeleri yalnız korkutup sindirmek için göndeririz."},{"n":60,"t":"Hani, sana: \"Rabbin, insanları çepeçevre kuşatmıştır.\" demiştik. Sana gösterdiğimiz o rüyayı da Kur'an'da lanetlenmiş bulunan o ağacı/soyu da insanları sınamak dışında bir sebeple göndermedik. Biz onları korkutuyoruz ama bu onların kudurganlığını artırmaktan başka bir katkı sağlamıyor."},{"n":61,"t":"Hani, meleklere: \"Âdem'e secde edin!\" demiştik; onlar da secde etmişlerdi. Ama İblis secde etmemiş, şöyle demişti: \"Çamur olarak yarattığın kişiye secde mi ederim?\""},{"n":62,"t":"Yine dedi: \"Şu benden üstün kıldığına bir baksana! Yemin olsun, eğer beni kıyamet gününe kadar ertelersen, onun soyunu, pek azı hariç, hükmüm altına alacağım.\""},{"n":63,"t":"Allah buyurdu: \"Defol git! Onlardan kim sana uyarsa, cezanız cehennem olacaktır. Ne de mükemmel ceza.\""},{"n":64,"t":"\"Onlardan güç yetirdiğini sesinle yerinden oynat. Atlıların ve yayalarınla yaygara çıkarıp üzerlerine çullan. Mallarda, evlatlarda onlara ortak ol, onlara ha bire vaatte bulun.\" Şeytan onlara bir aldanıştan başka ne vaat eder ki?!"},{"n":65,"t":"\"Kuşkusuz, benim kullarım üzerinde senin hiçbir sultan olmayacaktır.\" Vekil olarak Rabbin yeter."},{"n":66,"t":"Rabbiniz odur ki, lütfundan nasip arayasınız diye sizin için denizde gemiler yürütüyor. O, size karşı gerçekten çok merhametlidir."},{"n":67,"t":"Denizde size bir zorluk dokunduğunda, O'nun dışındaki tüm yalvardıklarınız ortadan kaybolur. Fakat O, sizi kurtarıp karaya çıkarınca yüz çevirirsiniz. İnsan çok nankördür."},{"n":68,"t":"Peki, kara tarafında sizi yere geçirivermesinden yahut üstünüze çakıl savuran bir kasırga göndermesinden emin misiniz? Sonra kendinize hiçbir vekil bulamazsınız."},{"n":69,"t":"Yoksa sizi bir kez daha oraya gönderip üstünüze kırıp geçiren bir fırtına salarak, inkâr ettiğinizden dolayı sizi boğmayacağından emin misiniz? Sizin adınıza, bizden bunun öcünü alacak birini de bulamazsınız."},{"n":70,"t":"Yemin olsun, biz, âdemoğullarını onur ve üstünlükle donattık, onları karada ve denizde binitlerle yükledik. Onları, güzel ve temiz rızıklarla besledik. Ve onları, yarattıklarımızın birçoğundan üstün kıldık."},{"n":71,"t":"Gün olur, insan gruplarından herbirini kendi önderiyle çağırırız. O gün kitabı kendisine sağdan verilenler, kitaplarını okuyacaklar ve bir kıl kadar haksızlığa uğratılmayacaklar."},{"n":72,"t":"Bu dünyada kör olan, âhirette de kördür. Yolca da daha sapıktır o."},{"n":73,"t":"Az kalsın seni, sana vahyettiğimizden uzaklaştırarak ondan gayrısını uydurup bize isnat edesin diye fitneye düşüreceklerdi. İşte o takdirde seni dost edinirlerdi."},{"n":74,"t":"Eğer biz seni sağlamlaştırmamış olsaydık, yemin olsun, onlara birazcık meylediverecektin."},{"n":75,"t":"İşte o zaman sana, hayatın da ölümün de katmerli acılarını tattırdık. Ve bize karşı hiçbir yardımcı da bulamazdın."},{"n":76,"t":"Az kalsın bu topraktan çıkarmak için seni sıkıştıracaklardı. Böyle bir durumda onlar orada senin arkandan çok az bir süre kalacaklardı."},{"n":77,"t":"Senden önce gönderdiğimiz resullerimize uygulanan yöntem de buydu. Sen bizim yol ve yöntemimizde değişme bulamazsın."},{"n":78,"t":"Güneşin kaymasından/aşağı sarkmasından, gecenin kararmasına kadar namazı/duayı yerine getir. Sabah Kur'an'ını da gözet. Çünkü sabah Kur'an'ı tanıklarca izlenmektedir."},{"n":79,"t":"Sana özgü bir davranış olarak, gecenin bir kısmında, o Kur'an'la meşgul olmak üzere uyanık ol/uykudan uyan. Böylece Rabbinin seni övgüye layık bir konuma ulaştırması umulur."},{"n":80,"t":"Şöyle yakar: \"Rabbim! Beni, gireceğim yere doğruluk-dürüstlükle sok, çıkacağım yerden doğruluk-dürüstlükle çıkar. Katından bana yardımcı bir güç/kanıt ver.\""},{"n":81,"t":"Ve de ki: \"Hak geldi bâtıl yıkılıp gitti. Bâtıl, yok olmaya zaten mahkûmdu.\""},{"n":82,"t":"Biz Kur'an'dan, inananlar için şifa ve rahmet olacak şeyler indiriyoruz. Ama bu, zalimlerin yıkımını artırmaktan başka katkı sağlamıyor."},{"n":83,"t":"İnsana nimet verdiğimizde yüz çevirip yan çizer. Kendisine şer dokununca da hemen ümitsiz oluverir."},{"n":84,"t":"De ki: \"Herkes, kendi varlık yapısına uygun iş görür. Yolca daha doğru gidenin kim olduğunu Rabbiniz daha iyi bilir.\""},{"n":85,"t":"Ve sana ruhtan sorarlar. De ki: \"Ruh, Rabbimin emrindendir. Ve size, ilimden sadece az bir şey verilmiştir.\""},{"n":86,"t":"Yemin olsun, biz dilesek sana vahyetmiş olduğumuzu tamamen gideriveririz, sonra onu elde etmek için bizim katımızda kendine bir vekil de bulamazsın."},{"n":87,"t":"Ancak, Rabbinden bir rahmet müstesna. Kuşkusuz, O'nun sana lütfu pek büyüktür."},{"n":88,"t":"De ki: \"Yemin olsun, eğer insanlar ve cinler şu Kur'an'ın bir benzerini getirmek üzere bir araya toplansalar, birbirlerine de destek olsalar, onun bir benzerini yine de ortaya getiremezler.\""},{"n":89,"t":"Yemin olsun, biz bu Kur'an'da, insanlar için her benzetmeden nice örnekler sıraladık. Ama insanların çoğu inkâr ve nankörlükten başka bir şeyde diretmediler."},{"n":90,"t":"Dediler ki: \"Bizim için yerden bir pınar fışkırtmadığın sürece sana asla inanmayacağız!\""},{"n":91,"t":"\"Yahut senin, hurmalardan, üzümlerden oluşan bir bahçen olmalı. Onların aralarından şarıl şarıl ırmaklar akıtmalısın.\""},{"n":92,"t":"\"Yahut iddia ettiğin gibi göğü, parçalar halinde üzerimize düşürmelisin, yahut Allah'ı ve melekleri karşımıza dikmelisin.\""},{"n":93,"t":"\"Yahut altından bir evin olmalı, yahut göğe yükselmelisin. Ancak senin göğe çıktığına, okuyacağımız bir kitabı bize indireceğin zamana kadar, asla inanmayız!\" De ki: \"Rabbimin şanı yücedir. Ben, insan bir resulden başka neyim ki?\""},{"n":94,"t":"Kendilerine hak kılavuzcusu geldiğinde, insanların iman etmelerine, şöyle demelerinden başka bir şey engel olmadı: \"Allah, bir insan mı resul gönderdi?\""},{"n":95,"t":"De ki: \"Eğer yeryüzünde doygunluğa ulaşmış melekler dolaşır olsaydı, elbette gökten onlara bir melek-resul gönderirdik.\""},{"n":96,"t":"De ki: \"Benimle sizin aranızda tanık olarak Allah yeter. O, kullarından haberdardır, onları görmektedir.\""},{"n":97,"t":"Allah kime hidayet verirse doğru olan yolu bulan odur. Kimi de şaşırtırsa, böyleleri için O'nun dışında dostlar bulamazsın. Kıyamet günü böylelerini kör, dilsiz ve sağır bir halde yüzleri üstüne sürerek haşrederiz. Varacakları yer cehennemdir ki, alevi dindikçe kızgın ateşini körükleyiveririz."},{"n":98,"t":"Cezaları işte budur. Çünkü ayetlerimizi inkâr ettiler ve şöyle dediler: \"Biz, bir kemik yığını olduktan, un-ufak hale geldikten sonra mı, sahi bundan sonra mı, yeni bir yaratılışla diriltileceğiz?\""},{"n":99,"t":"Görmediler mi ki, o, gökleri ve yeri yaratan Allah, kendilerinin benzerlerini yaratmaya da Kaadir'dir. Onlar için bir süre belirlemiştir, bunda kuşku yok. Ama zalimler, inkârdan başka bir şeyde direnmiyorlar."},{"n":100,"t":"De ki: \"Eğer Rabbimin rahmet hazinelerine sahip olsaydınız, o zaman da harcanır-biter korkusuyla cimri davranırdınız.\" İnsan çok cimridir."},{"n":101,"t":"Yemin olsun, biz, Mûsa'ya açık-seçik dokuz mucize verdik. İsrailoğullarına sor: Hani, Mûsa onlara geldiğinde Firavun ona şöyle demişti: \"Ben senin kesinlikle büyülendiğini düşünüyorum, ey Mûsa!\""},{"n":102,"t":"Mûsa dedi: \"Yemin olsun, sen bilmektesin ki, bunları, basîretle görülebilecek ibretler halinde/basîretler olarak o, göklerin ve yerin Rabbinden başkası indirmedi. Vallahi ben seni mahvolmuş görüyorum, ey Firavun!\""},{"n":103,"t":"Firavun onları o topraktan sürüp çıkarmak istedi de biz onu ve yanındakilerin tümünü boğduk."},{"n":104,"t":"Bunun ardından, İsrailoğullarına şöyle dedik: \"Şu toprakta oturun. Âhiret vaadi/ikinci vaat gelince, sizi toplayıp bir araya getireceğiz.\""},{"n":105,"t":"Biz onu hak ile indirdik ve o hak ile indi. Seni de ancak müjdeci ve uyarıcı olarak gönderdik."},{"n":106,"t":"Onu, okunacak şeyleri toplayan bir kitap/ bir Kur'an olarak, insanlara dura dura okuyasın diye kısımlara ayırıp ağır ağır indirdik."},{"n":107,"t":"De ki: \"İster inanın ona, ister inanmayın. O, kendilerine daha önce ilim verilmiş olanlara okunduğunda, onlar, çeneleri üstü secdelere kapanıyorlar.\""},{"n":108,"t":"Ve diyorlar: \"Rabbimizin şanı yücedir, Rabbimizin vaadi mutlaka gerçekleşecektir!\""},{"n":109,"t":"Ağlayarak çeneleri üstü kapanıyorlar; o onların huşûunu artırıyor."},{"n":110,"t":"De ki: \"İster Allah diye yakarın, ister Rahman diye yakarın. Hangisiyle yakarırsanız yakarın, en güzel isimler/Esmâül Hüsna O'nundur. Namazında/duanda sesini yükseltme, kısma da. İkisi ortası bir yol tut.\""},{"n":111,"t":"Şöyle de: \"Hamt, o Allah'a özgüdür ki, çocuk edinmemiştir; mülk ve yönetiminde ortağı yoktur; âcizlik yüzünden dost edinmemiştir.\" Ve tekbir edip yücelt O'nu!"}],[{"n":1,"t":"Hamt o Allah'a ki, kuluna Kitap'ı, kendisinde hiçbir eğiklik ve çelişme yapmaksızın indirdi."},{"n":2,"t":"Katından dosdoğru gelen açık bir söz olarak indirdi onu. Ki, zorlu bir iş ve oluş konusunda uyarsın ve barışa yönelik hayırlı ameller sergileyen müminlere, kendileri için güzel bir ödül öngörüldüğünü muştulasın..."},{"n":3,"t":"Onlar, o hal üzere sonsuza dek kalıcıdırlar."},{"n":4,"t":"Ve \"Allah bir çocuk edindi\" diyenleri uyarsın diye indirdi onu."},{"n":5,"t":"Ona ilişkin ne kendilerinin bir ilmi vardır ne de atalarının. Söz olarak ne büyüktür ağızlarından çıkıveren! Onlar bir yalandan başka şey söylemiyorlar."},{"n":6,"t":"Şimdi sen, bu söze inanmazlarsa, belki de arkalarından kendini eritircesine üzüleceksin."},{"n":7,"t":"Biz, yeryüzündeki şeyleri ona bir süs yaptık ki, insanları, içlerinden hangisi amel yönünden daha güzeldir diye imtihan edelim."},{"n":8,"t":"Ve şu da bir gerçek ki biz, yeryüzündeki her şeyi, bitki bitirmeyen/kıtlık ve ölüme yol açan kupkuru bir toprak haline elbette getireceğiz."},{"n":9,"t":"Yoksa sen o Ashab-ı Kehf'i, mağara ve kitabe yâranını, bizim ayetlerimizden, hayrete düşüren bir tanesi mi sandın?"},{"n":10,"t":"Hani, o yiğit gençler o mağaraya sığındılar da şöyle dediler: \"Ey Rabbimiz, katından bir rahmet ver bize ve bizim için bir çıkış yolu lütfet işimize.\""},{"n":11,"t":"Bunun üzerine birçok yıl boyunca mağarada onların kulakları üzerine ağırlık vurduk."},{"n":12,"t":"Sonra onları dirilttik ki, iki zümreden hangisinin kaldıkları süreyi daha iyi hesap edebileceğini bilelim."},{"n":13,"t":"Biz onların haberlerini sana doğru bir şekilde anlatacağız. Şu bir gerçek ki onlar, Rablerine iman etmiş bir yiğitler grubuydu. Ve biz de onların hidayetini artırdık."},{"n":14,"t":"Kalpleriyle aramızda bir bağ kurduk/kalplerini dayanıklı kıldık. Kalkıp şöyle dediler: \"Rabbimiz, göklerin ve yerin rabbidir. O'ndan başka hiçbir ilaha yakarmayız. Aksini yaparsak saçma söz söylemiş oluruz.\""},{"n":15,"t":"\"Şunlar, şu kavmimiz O'ndan başka ilahlar edindiler. Onlar hakkında açık bir kanıt getirselerdi ya! Yalan düzerek Allah'a iftira edenden daha zalim kim olabilir?!\""},{"n":16,"t":"\"Madem ki onlardan ve Allah dışındaki taptıklarınızdan yüz çevirip kenara çekildiniz, hadi mağaraya sığının ki, Rabbiniz size rahmetinden bir nasip yaysın ve işinizde size kolaylık ve başarı sağlasın.\""},{"n":17,"t":"Güneş'i görüyorsun: Doğduğu vakit mağaralarından sağ tarafa kayar, battığı vakit ise onları sol tarafa doğru makaslayıp geçer. Böylece onlar mağaranın geniş boşluğu içindedirler. Bu, Allah'ın mucizelerindendir. Allah'ın kılavuzluk ettiği, doğruyu bulmuştur. Şaşırttığına gelince, sen ona yol gösteren bir velî asla bulamazsın."},{"n":18,"t":"Sen onları uyanıktırlar sanırsın; oysaki onlar uykudadırlar. Onları sağ tarafa da sol tarafa da çeviririz. Köpekleri de iki kolunu girişe uzatıp yaymıştır. Onların durumunu görseydin kesinlikle onlardan yüz çevirip kaçırdın. Ve onlardan içinde mutlaka korku doldurulurdu."},{"n":19,"t":"İşte böyle! Onları dirilttik ki, birbirlerine sorup dursunlar. İçlerinden biri şöyle konuştu: \"Ne kadar durdunuz?\" Dediler: \"Bir gün yahut günün bir parçası kadar.\" Dediler: \"Ne kadar kaldığınızı Rabbiniz daha iyi bilir. Siz şimdi birinizi şu gümüş para ile kente gönderin de baksın; kentin hangi yiyeceği daha temizse ondan size bir rızık getirsin. Ama nazik ve kurnaz davransın ki, sizi kimseye fark ettirmesin.\""},{"n":20,"t":"\"Çünkü onlar sizi ellerine geçirirlerse ya taşlayarak öldürürler yahut da sizi kendilerinin milletine döndürürler. O takdirde bir daha asla kurtulamazsınız.\""},{"n":21,"t":"Böylece insanları onlar hakkında bilgilendirdik ki, Allah'ın vaadinin hak, kıyamet saatinin de kuşkusuz olduğunu bilsinler. Çünkü onlar, aralarında mağara yararının durumunu tartışıyorlardı. \"Onların üstüne bir bina kurun.\" dediler. Rableri onları daha iyi bilir. Onlar hakkında görüşleri galip gelenlerse şöyle dediler: \"Üzerlerine mutlaka bir mescit edineceğiz.\""},{"n":22,"t":"\"Üç kişiydiler, dördüncüleri köpekleriydi.\" diyecekler. Şunu da diyecekler: \"Beş kişiydiler, altıncıları köpekleriydi.\" Gaybı taşlamaktır/bilinmeyen şey hakkında atıp tutmaktır bu. Şöyle de derler: \"Yedi kişidirler, sekizincileri de köpekleridir.\" De ki: \"Onların sayısını Rabbim daha iyi bilir. Onlar hakkında bilgisi olan, çok azdır.\" O halde, onlar hakkında yüzeysel bir tartışma dışında hiçbir çekişmeye girme. Onlar hakkında, konuşup duranlardan hiç kimseye bir şey sorma."},{"n":23,"t":"Hiçbir şey için, \"Ben bunu yarın kesinlikle yapacağım.\" deme."},{"n":24,"t":"\"Allah dilerse\" şeklinde söyleyebilirsin. Unuttuğunda, Rabbini an. Ve de: \"Umarım ki Rabbim beni, bundan daha yakın bir zamanda başarıya/aydınlığa ulaştırır.\""},{"n":25,"t":"Onlar, mağaralarında üçyüz yıl kaldılar; dokuz da ilave ettiler."},{"n":26,"t":"De ki: \"Onların ne kadar kaldıklarını Allah daha iyi bilir. O'nun elindedir göklerin ve yerin gaybı. Ne güzel görendir O, ne güzel işitendir. Onların, O'ndan başka bir dostları da yoktur. Ve O, hükmüne hiç kimseyi ortak etmez.\""},{"n":27,"t":"Rabbinin kitabından sana vahyedileni oku. O'nun kelimelerini değiştirecek hiçbir kudret yoktur. O'nun dışında bir sığınak/bir dayanak asla bulamazsın."},{"n":28,"t":"Benliğini, sabah-akşam yüzünü isteyerek rablerine yalvaranlarla beraber tut. İğreti dünya hayatının süsünü isteyerek gözlerini onlardan kaydırıp uzaklaştırma. Ve sakın, kalbinin bizim zikrimizden/Kur'anımızdan gafil koyduğumuz, boş arzularına uymuş kişiye boyun eğme. Böylesinin işi hep aşırılıktır."},{"n":29,"t":"Ve de ki: \"Hak, Rabbinizdendir. Artık dileyen inansın, dileyen inkâr etsin.\" Biz, zalimler için öyle bir ateş hazırladık ki, çadırı/duvarı/dumanı onları çepeçevre kuşatmıştır. Eğer yardım dileseler, erimiş maden gibi yüzleri pişiren bir su ile yardımlarına koşulur. O ne kötü içecek, o ne kötü sığınak/dayanak!"},{"n":30,"t":"İman edip hayra ve barışa yönelik ameller sergileyenlere gelince, kuşkusuz ki biz, güzel iş yapanların ödülünü yitirmeyeceğiz."},{"n":31,"t":"Bunlar için, altlarından ırmaklar akan Adn cennetleri vardır. Orada altın bileziklerle süslenecekler, ince ve kalın ipekten yeşil giysiler giyip koltuklar üzerine kurulacaklar. O ne güzel karşılık, o ne güzel dayanak!"},{"n":32,"t":"Onlara örnek olarak şu iki adamı ver: Bunlardan birine, üzümlerden oluşan iki bağlık vermiş, bağların çevresini hurmalarla donatmış, aralarına da ekinler serpiştirmiştik."},{"n":33,"t":"İki bağ da yemişlerini vermiş o adamdan hiçbir şeyi eksik bırakmamıştı. İkisinin ortasından bir de nehir fışkırtmışız."},{"n":34,"t":"Adamın başka bir geliri de vardı. Bu yüzden, arkadaşlarıyla konuştuğu bir sırada ona şöyle demişti: \"Ben, malca senden zengin, insan unsuru bakımından da güçlü ve onurluyum.\""},{"n":35,"t":"Ve böylece, öz benliğine zulüm ede ede bağlığına girdi. Şöyle konuştu: \"Bunun sonsuza değin yok olacağını sanmıyorum.\""},{"n":36,"t":"\"Kıyametin kopacağını da sanmıyorum. Ama eğer Rabbime döndürülüp götürülürsem, bundan daha iyisini bulacağımdan eminim.\""},{"n":37,"t":"Kendisiyle konuşan arkadaşı ona dedi ki: \"Sen, seni topraktan, sonra meniden yaratıp sonra da bir adam olarak biçimlendiren kudrete nankörlük mü ettin?\""},{"n":38,"t":"\"Lâkin, o Allah benim Rabbimdir. Ve ben, Rabbime hiç kimseyi ortak koşmam.\""},{"n":39,"t":"\"Bağına girdiğinde, 'Mâşallah, kuvvet yalnız Allah'tandır!' desen olmaz mıydı? Gerçi sen beni, malca ve evlatça senden basit görüyorsun ama,"},{"n":40,"t":"Olabilir ki, Rabbim bana senin bağından daha değerlisini verir; seninkinin üzerine de gökten bir âfet gönderir de bağlığın yalçın bir toprak kesilir.\""},{"n":41,"t":"Yahut suyu dibe çekilir de bir daha onu isteyemezsin bile.\""},{"n":42,"t":"Derken bütün ürününe el kondu. Bağ sahibi, çardakları üzerine çökmüş bulunan bağ için harcadıklarına vahlanarak avuçlarını ovuşturuyor ve şöyle diyordu: \"Ne olurdu, Rabbime hiç kimseyi ortak koşmasaydım!\""},{"n":43,"t":"Allah dışında kendisine yardım edecek bir topluluğu da çıkmadı. Kendi kendini de kurtaramadı."},{"n":44,"t":"İşte böyle bir durumda, dostluk ve koruma, hak olan Allah'tandır. O, karşılık verme bakımından da hayırlıdır, iş sonuçlandırma bakımından da hayırlıdır."},{"n":45,"t":"Dünya hayatının şu su örneği gibi olduğunu onlara anlat: \"O suyu gökten indirdik. Yerin bitkisi onunla karıştı. Derken o bitki, rüzgârların savurup döllediği parçacıklara dönüştü. Allah her şey üzerinde Muktedir'dir, gücü her şeye yeter."},{"n":46,"t":"Mal ve oğullar, şu iğreti dünya hayatının süsüdür. Barışa ve hayra yönelik kalıcı eylemlerse, Rabbin katında sevapça da üstündür, beklenti bakımından da."},{"n":47,"t":"Gün olur, dağları yürütürüz de yeryüzünü çırılçıplak görürsün. İnsanları huzurumuzda toplamış, içlerinden hiçbirisini hesap dışı bırakmamışızdır."},{"n":48,"t":"Hepsi, saflar halinde Rabbine arz edilmiştir. Yemin olsun, sizi ilk kez yarattığımız gibi yine bize geldiniz. Ama siz, sizin için hesabın görüleceği bir zaman belirlemeyeceğimizi sanmıştınız."},{"n":49,"t":"Kitap ortaya konulmuştur. Günahkârların, onun içindekilerden korkup ürpererek şöyle dediklerini görürsün: \"Vay başımıza! Ne biçim kitap bu! Ne küçük bırakmış ne büyük. Hepsini sayıp dökmüş!\" Yapıp ettiklerini hazır bulmuşlardır. Rabbin hiç kimseye zulmetmiyor."},{"n":50,"t":"Hani, biz meleklere \"Âdem'e secde edin\" demiştik de İblis dışında hepsi secde etmişti. İblis, cinlerdendi. Kendi Rabbinin emrine ters düştü. Şimdi siz, benim beri yanımdan, onu ve onun soyunu dostlar mı ediniyorsunuz? Hem de onlar sizin düşmanınızken. Zalimler için ne kötü bir değiştirmedir bu!"},{"n":51,"t":"Ben onları ne göklerle yerin yaratılmasına, hatta ne kendilerinin yaratılmasına tanık tuttum. Ben, sapıp gitmişleri yardımcı edinecek değilim."},{"n":52,"t":"Bir gün Allah şöyle diyecektir: \"O bir şey zannettiğiniz ortaklarımı çağırın!\" Hemen çağırdılar ama onlar kendilerine cevap vermedi. Biz onların aralarına tehlikeli bir uçurum/yıkıcı bir düşmanlık koyduk."},{"n":53,"t":"Suçlular, ateşi gördüler de onun içine düşeceklerini anladılar; fakat ondan kaçıp kurtulmaya bir yol bulamadılar."},{"n":54,"t":"Yemin olsun, biz bu Kur'an'da, insanlar için her örnekten türlüsünü verdik. Fakat insan, tartışmaya her şeyden çok düşkündür."},{"n":55,"t":"Kendilerine hidayet geldikten sonra, insanları iman etmekten, Rablerinden af dilemekten alıkoyan şey şundan başkası değildir: Evvelkilerin yol ve yöntemlerinin kendilerine de gelmesini yahut bizzat azabın karşılarına dikilivermesini beklemek."},{"n":56,"t":"Biz, elçileri sadece müjdeleyiciler ve uyarıcılar olarak göndeririz. Küfre sapanlar ise hakkı batılla iptal etmek için mücadele veriyorlar. Ayetlerimizi ve uyarıldıkları şeyleri eğlence konusu edindiler."},{"n":57,"t":"Kendisine Rabbinin ayetleri hatırlatıldığı halde, onlardan yüz çeviren ve iki elinin hazırlayıp önden gönderdiği şeyleri unutandan daha zalim kim olabilir? Şu bir gerçek ki, biz onların kalpleri üzerine onu anlamamaları için kabuklar geçirdik, kulakları içine de ağırlıklar koyduk. Onları hidayete çağırsan da bu durumda hidayete asla ulaşamazlar."},{"n":58,"t":"O affedici, o rahmet sahibi Rabbin, onları, kazandıkları yüzünden hesaba çekseydi, kendileri için azabı mutlaka çabuklaştırırdı. Böyle olmamıştır, ama onlar için, hiçbir kaçıp kurtulma imkânı bulamayacakları bir hesap sorma zamanı öngörülmüştür."},{"n":59,"t":"İşte sana bir yığın kent/medeniyet. Zulme saptıklarında onları helâk ettik. Onları helâk etmek için de bir süre belirlemiştik."},{"n":60,"t":"Bir zaman Mûsa, genç arkadaşına şöyle demişti: \"İki denizin birleştiği yere kadar durup dinlenmeksizin yürüyeceğim yahut da senelerce akıp gideceğim.\""},{"n":61,"t":"Bu ikisi, iki denizin birleştiği yere vardıklarında, balıklarını unuttular. Bunun üzerine balık da denizde bir deliğe doğru yola koyuldu."},{"n":62,"t":"Orayı geçtiklerinde Mûsa, genç arkadaşına dedi ki: \"Hadi, getir şu sabah yemeğimizi. Vallahi bu yolculuğumuz yüzünden epey çektik.\""},{"n":63,"t":"Genç adam dedi: \"Bak sen şu işe, hani kayaya sığınmıştık ya, işte o sırada balığı unuttum. Onu hatırlamamı bana unutturan, şeytandan başkası değildi. Balık, denizin içinde acaip bir biçimde yolunu tuttu.\""},{"n":64,"t":"Mûsa: \"Arayıp durduğumuz işte o idi.\" dedi. Bunun üzerine kendi izlerini sürerek gerisingeri döndüler."},{"n":65,"t":"Orada, kullarımızdan öyle bir kul buldular ki, biz ona katımızdan bir rahmet vermiş, lütfumuzdan bir ilim öğretmiştik."},{"n":66,"t":"Mûsa ona dedi ki: \"Sana öğretilenden bana da bir olgunluk/bir bilgi öğretmen şartıyla sana tâbi olayım mı?\""},{"n":67,"t":"Dedi: \"Doğrusu sen benimle beraberliğe dayanamazsın.\""},{"n":68,"t":"\"Havsalanın almadığı bir şeye nasıl dayanacaksın?\""},{"n":69,"t":"Mûsa dedi ki: \"Allah dilerse beni sabırlı bulacaksın; hiçbir işte sana karşı gelmeyeceğim.\""},{"n":70,"t":"Dedi: \"Bak, eğer bana uyarsan, ben sana kendisinden bahis açıncaya değin hiçbir şey hakkında bana soru sorma!\""},{"n":71,"t":"İkisi birlikte yola koyudular. Bir süre sonra gemiye bindiklerinde, tuttu gemiyi deliverdi. Mûsa dedi: \"İçindekileri boğmak için mi deldin onu? Vallahi korkunç bir iş yaptın!\""},{"n":72,"t":"Dedi: \"Ben söylemedim mi, sen benimle beraberliğe asla dayanamazsın!\""},{"n":73,"t":"Mûsa dedi: \"Unuttuğum için beni azarlama; bu yaptığımdan dolayı da bana zorluk çıkarma.\""},{"n":74,"t":"Yine yola koyuldular. Bir süre sonra bir oğlana rastgeldiler; tuttu onu öldürdü. Mûsa dedi: \"Tertemiz bir insanı, bir cana karşılık olmaksızın öldürdün ha!? Vallahi çok kötü bir iş yaptın!\""},{"n":75,"t":"Dedi: \"Ben sana söylemedim mi, sen benimle beraberliğe asla dayanamazsın.\""},{"n":76,"t":"Mûsa dedi ki: \"Eğer bundan sonra sana bir şey sorarsam artık bana arkadaşlık etme. Vallahi, öyle bir durumda benden ayrılmakta mazur sayılacaksın.\""},{"n":77,"t":"Yine yola koyuldular. Biraz sonra bir kente geldiler. Kent halkından yemek istediler, ama onlar bu ikisini konuk etmekten çekindiler. Orada, yıkılmayı bekleyen bir duvara rastladılar; genç adam tuttu onu onardı. Mûsa \"İsteseydin buna karşılık bir ücret elbette alırdın.\" dedi."},{"n":78,"t":"Dedi: \"İşte bu, seninle benim aramızın ayrılmasıdır. Şimdi sana, sabretmeye güç yetiremediğin şeylerin içyüzünü haber vereceğim.\""},{"n":79,"t":"\"Gemiden başlayayım: O gemi, denizde işçilik yapan bir grup yoksulundu. Ben onu kusurlu hale getirmek istedim. Çünkü biraz ötelerinde bir kral vardı; tüm gemilere zorla el koyuyordu.\""},{"n":80,"t":"\"Oğlan çocuğa gelince: Onun anası-babası inanmış kişilerdi. Çocuğun onları azgınlık ve inkâra sürüklemesinden korktuk.\""},{"n":81,"t":"\"Diledik ki, Rableri onlara o çocuktan temizlikçe daha üstün, merhametçe daha gelişmişini versin.\""},{"n":82,"t":"\"Ve duvar. Duvar, o kentte yaşayan iki yetim oğlanındı. Altında, oğlanlara ait bir define vardı. Oğlanların babası da hayır ve barış seven bir kimse olarak yaşamıştı. Rabbin istedi ki, o çocuklar ergenliklerine ulaşsınlar da Rabbinden bir rahmet olarak definelerini çıkarsınlar. Ben bunları kendi buyruğumun sonucu olarak yapmadım. İşte senin sabretmeye güç yetiremediğin şeylerin içyüzü budur.\""},{"n":83,"t":"Sana Zülkarneyn'den de sorarlar: De ki: \"Size ondan bir hatıra okuyacağım.\""},{"n":84,"t":"Biz onun için yeryüzünde güç ve saltanat hazırladık ve ona herşeyden bir sebep verdik."},{"n":85,"t":"O da bir sebebi izledi."},{"n":86,"t":"Nihayet, Güneş'in battığı yere varınca onu kara balçıklı bir gözede batar buldu. Onun yanında bir de kavim buldu. Dedik ki: \"Ey Zülkarneyn, ya bunlara azap edersin ya da haklarında güzel bir tavrı esas alırsın.\""},{"n":87,"t":"Dedi: \"Zulmedene azap edeceğiz; sonra Rabbine döndürülecek; O da onu görülmedik bir azaba çeker.\""},{"n":88,"t":"\"İman edip hayra ve barışa yönelik iş yapana gelince, onun için ödül olarak en güzeli var. Ve ona, buyruğumuzdan, kolay olanı söyleyeceğiz.\""},{"n":89,"t":"Sonra bir sebebi daha izledi."},{"n":90,"t":"Bir süre sonra, Güneş'in doğduğu yere varınca onu, ona karşı kendilerine bir siper yapmadığımız bir topluluğun üzerine doğar buldu."},{"n":91,"t":"İşte böyle! Biz onun yanında olan her şeyi bilgimizle kuşatmıştık."},{"n":92,"t":"Sonra yine bir sebebi izledi."},{"n":93,"t":"Nihayet, iki seddin arasına ulaştığında, onların önünde neredeyse hiç söz anlamayan/söz söylenmeyen bir halk buldu."},{"n":94,"t":"Dediler: \"Ey Zülkarneyn! Ye'cûc ve Me'cûc bu yerde bozgunculuk yapıyorlar. Onlarla bizim aramızda bir set yapman şartıyla sana vergi verelim mi?\""},{"n":95,"t":"Dedi: \"Rabbimin beni içinde tuttuğu imkân ve güç daha üstündür. Siz bana bedensel gücünüzle destek verin de onlarla sizin aranıza çok muhkem bir engel çekeyim.\""},{"n":96,"t":"\"Bana demir kütleleri getirin!\" İki ucu tam denkleştirince, \"Körükleyin!\" dedi. Onu ateş haline koyunca da \"Getirin bana, üzerine erimiş bakır/katran dökeyim!\" diye seslendi."},{"n":97,"t":"Artık onu ne aşabildiler ne delebildiler."},{"n":98,"t":"Dedi: \"Bu, Rabbimden bir rahmettir. Rabbimin vaadi gelince onu yerle bir eder. Ve Rabbimin vaadi haktır.\""},{"n":99,"t":"O gün onları bırakmışızdır, birbirleri içinde dalgalanırlar. Sûra da üflenmiştir; hepsini bir araya toplamışızdır."},{"n":100,"t":"O gün, cehennemi, inkârcılara öyle bir sunmuşuzdur ki!..."},{"n":101,"t":"Onlar, gözleri benim zikrim/Kur'anım karşısında perde içinde olan insanlardı. Dinlemeye dayanamıyorlardı."},{"n":102,"t":"Küfre sapanlar, beni bırakıp da kullarımı veliler edineceklerini mi sandılar. Biz cehennemi bir konuk evi olarak inkârcılar için hazırladık."},{"n":103,"t":"De ki: \"Amelleri bakımından hüsrana en çok batanları size haber vereyim mi?\""},{"n":104,"t":"O kimselerdir ki, dünya hayatındaki çabaları boşa gitmiştir de onlar sanayileşmeyi/işi hâlâ güzel yaptıklarını sanırlar."},{"n":105,"t":"Bunlar, Rablerinin ayetlerini ve O'na ulaşmayı inkâr etmişler de bütün amelleri boşa çıkmıştır. Bu yüzden kıyamet günü onlar için hiçbir ölçü tutturmayız/onlara hiçbir değer vermeyiz."},{"n":106,"t":"İşte böyle! Ayetlerimi ve elçilerimi eğlence konusu yaptıkları için cezaları cehennem olacaktır."},{"n":107,"t":"İman edip hayra ve barışa yönelik işler yapanlara gelince, onların konuk evleri Firdevs cennetleri olacaktır."},{"n":108,"t":"Sürekli kalacaklardır orada. Çıkmak istemeyeceklerdir oradan."},{"n":109,"t":"De ki: \"Rabbimin kelimeleri için deniz mürekkep olsa, Rabbimin kelimeleri tükenmeden önce deniz mutlaka biter. Bir o kadarını daha getirsek de yetmez.\""},{"n":110,"t":"De ki: \"Ben de sizin gibi bir insanım. Ancak, tanrınızın bir tek tanrı olduğu bana vahyediliyor. O halde, Rabbine kavuşmayı uman, hayra ve barışa yönelik iş yapsın ve Rabbine ibadette hiç kimseyi O'na ortak koşmasın.\""}],[{"n":1,"t":"Kâf, Hâ, Yâ, Ayn, Sâd."},{"n":2,"t":"Rabbinin rahmetinin, Zekeriyya kuluna anılışıdır bu..."},{"n":3,"t":"Hani o, Rabbine gizli bir sesle seslenmişti de,"},{"n":4,"t":"Şöyle demişti: \"Rabbim, işte karşındayım. Kemik gevşedi bende. İhtiyarlıktan başım beyaz alevle tutuştu. Sana yakarma/senin için çağrı yapma konusunda ise Rabbim, hiç bedbaht/zorluk ve şiddet yanlısı olmadım.\""},{"n":5,"t":"\"Ben, arkamdan gelecek yakınlarımdan endişe ediyorum. Karımsa kısır. O halde, katından bana bir dost bağışla;"},{"n":6,"t":"Ki hem bana mirasçı olsun hem de Yakub hanedanına mirasçı olsun. Ve onu hoşnutluğunu kazanmış bir kul eyle, Rabbim.\""},{"n":7,"t":"Ey Zekeriyya! Biz sana bir oğul müjdeliyoruz; adı Yahya, daha önce ona hiç kimseyi adaş yapmadık."},{"n":8,"t":"Dedi: \"Rabbim, benim için oğul nasıl söz konusu olur? Karım, doğurganlığını yitirmiştir, bense yaşlılığın gerçekten en ileri basamağına ulaştım.\""},{"n":9,"t":"\"Bu budur.\" dedi. Rabbin şöyle buyurdu: \"Onu yapmak benim için çok kolaydır. Nitekim daha önce de sen hiçbir şey değilken seni yaratmıştım.\""},{"n":10,"t":"Dedi: \"Rabbim, bana bir işaret ver.\" Cevap verdi: \"İşaretin, sapasağlam olduğun halde üç gece insanlarla konuşmamandır.\""},{"n":11,"t":"Bunun üzerine Zekeriyya, yakarış yerinden ayrılıp halkının karşısına geçti ve onlara \"sabah-akşam tespih edin\" diye işaret verdi."},{"n":12,"t":"\"Ey Yahya! Kitap'ı kuvvetle tut.\" Biz ona daha sabi iken hikmet verdik."},{"n":13,"t":"Katımızdan bir kalp yumuşaklığı, bir temizlik verdik. Korunan biriydi o."},{"n":14,"t":"Ana-babasına iyilik eden biriydi; zorba, isyancı biri değil."},{"n":15,"t":"Selam olsun ona, doğduğu gün, öleceği gün ve diri olarak kaldırılacağı gün."},{"n":16,"t":"Kitap'ta Meryem'i de an. Hani o, ailesinden ayrılıp doğu tarafında bir mekâna çekilmişti."},{"n":17,"t":"Onlarla arasına bir perde çekmişti. Biz de ruhumuzu ona göndermiştik de o kendisine sapasağlam bir insan şeklinde görünmüştü."},{"n":18,"t":"Meryem demişti: \"Ben senden, Rahman'a sığınıyorum. Takva sahibi biriysen dikkatli ol.\""},{"n":19,"t":"Ruh dedi: \"Ben, sadece Rabbinin elçisiyim. Sana tertemiz bir oğlan bağışlamak için buradayım.\""},{"n":20,"t":"Dedi: \"Benim nasıl oğlum olur; bana herhangi bir insan dokunmadı. Ben bir kahpe de değilim.\""},{"n":21,"t":"Dedi: \"İşte böyle! Rabbin buyurdu ki: 'O benim için çok kolaydır. Böyle olması onu, insanlara bir mucize ve bizden bir rahmet yapmamız içindir. Hükme bağlanmış bir iştir bu.\""},{"n":22,"t":"Ona gebe kaldı. Ardından da onunla uzak bir mekâna çekildi."},{"n":23,"t":"Nihayet doğum sancısı onu, bir hurma ağacının kütüğüne götürdü. \"Ah dedi, keşke daha önce ölseydim, keşke unutulup gitseydim.\""},{"n":24,"t":"Altından ona şöyle seslendi: \"Tasalanma, Rabbin senin alt yanında bir su arkı vücuda getirdi.\""},{"n":25,"t":"\"Hurma ağacının kütüğünü kendine doğru salla, üzerine olgun, taze hurma dökülecektir.\""},{"n":26,"t":"\"Artık ye, iç. Gözün aydın olsun. Eğer insanlardan birini görürsen şöyle söyle: 'Ben Rahman için oruç adadım. Onun için bugün, insan cinsinden hiç kimseyle konuşmayacağım.\""},{"n":27,"t":"Meryem, onu taşıyarak toplumuna getirdi. \"Ey Meryem, dediler, şaşılacak bir iş yaptın!\""},{"n":28,"t":"\"Ey Harun'un kızkardeşi! Baban kötü bir adam değildi. Annen de bir kahpe değildi.\""},{"n":29,"t":"Meryem, çocuğa işaret etti. Dediler: \"Beşikteki bir sabiyle nasıl konuşuruz?\""},{"n":30,"t":"Sabi dedi: \"Ben Allah'ın kuluyum. O bana kitap verdi, beni peygamber yaptı.\""},{"n":31,"t":"\"Beni, bulunduğum her yerde kutsal ve bereketli kıldı. Yaşadığım sürece bana namazı/duayı, zekâtı önerdi.\""},{"n":32,"t":"\"Anneme iyilik etmemi önerdi. Beni zorba bir eşkıya yapmadı.\""},{"n":33,"t":"\"Selam bana doğduğum gün, öleceğim gün ve diri olarak kaldırılacağım gün.\""},{"n":34,"t":"İşte Meryem'in oğlu İsa budur! Hakkında kuşku ve çelişmeye düştükleri şeyin doğrusu bu sözdür."},{"n":35,"t":"Bir oğul edinmek Allah'a asla yakışmaz. O'nun şanı yücedir. Bir iş ve oluşa karar verdi mi, ona sadece \"Ol!\" der, o hemen oluverir."},{"n":36,"t":"Şüphesiz, Allah, benim de Rabbimdir, sizin de Rabbinizdir. O halde O'na ibadet edin. Dosdoğru yol budur."},{"n":37,"t":"Kendi aralarından çıkan hizipler ihtilafa düştüler. Büyük bir günün tanıklığından ötürü vay o inkârcıların haline!"},{"n":38,"t":"Bize gelecekleri gün neler işitecekler, neler görecekler! Fakat o zalimler bugün, açık bir sapıklık içindedirler."},{"n":39,"t":"Sen onları, o hasret günü ile ilgili olarak uyar. Çünkü onlar gaflet içindeyken, iman da etmemişken iş bitirilmiş olacaktır."},{"n":40,"t":"Yeryüzüne ve üzerindekilere biz mirasçı olacağız, biz! Ve bize döndürülecekler."},{"n":41,"t":"Kitap'ta İbrahim'i de an. O, özü-sözü doğru bir peygamberdi."},{"n":42,"t":"Hani, babasına demişti ki: \"Babacığım; işitmeyen, görmeyen, sana hiçbir yarar sağlamayan şeylere niçin kulluk ediyorsun?\""},{"n":43,"t":"\"Babacığım, bana ilimden, sana ulaşmayan bir nasip geldi. O halde bana uy ki, seni düzgün bir yola ileteyim!\""},{"n":44,"t":"\"Babacığım, şeytana kulluk etme! Çünkü şeytan Rahman'a isyan etmişti.\""},{"n":45,"t":"\"Babacığım, ben sana Rahman'dan bir azap dokunmasından, böylece şeytanın dostu haline gelmenden korkuyorum!\""},{"n":46,"t":"Babası dedi: \"Sen benim ilahlarımdan yüz mü çeviriyorsun ey İbrahim! Eğer bu işe son vermezsen, vallahi seni taşlarım! Uzun bir süre uzak kal benden!\""},{"n":47,"t":"Dedi: \"Selam sana! Senin için Rabbimden af dileyeceğim. Çünkü O, bana karşı çok lütufkârdır.\""},{"n":48,"t":"\"Sizden de Allah dışındaki yakardıklarınızdan da ayrılıyorum; Rabbime dua edeceğim. Umarım, Rabbime yakarışımla/Rabbim için çağrımda bahtsızlığa/eşkıyalığa düşmem.\""},{"n":49,"t":"İbrahim, onlardan ve Allah dışında kulluk ettiklerinden uzaklaşınca, ona İshak'ı ve Yakub'u bağışladık ve hepsini peygamber yaptık."},{"n":50,"t":"Onlara, rahmetimizden nimetler bağışladık. Ve kendileri için yüksek bir doğruluk dili oluşturduk."},{"n":51,"t":"Kitap'ta Mûsa'yı da an. Çünkü o, içtenlik ve dürüstlüğe erdirilmişti ve o bir resul, bir peygamberdi."},{"n":52,"t":"Ona Tûr'un sağ tarafından seslendik. Onu, fısıldaşan kimse kadar yaklaştırdık."},{"n":53,"t":"Rahmetimizden ona kardeşi Hârun'u bir peygamber olarak armağan ettik."},{"n":54,"t":"Kitap'ta İsmail'i de an. Çünkü o, vaadinde sadıktı; bir resuldü, bir peygamberdi."},{"n":55,"t":"Ailesine namazı/duayı, zekâtı emrederdi. Rabbi katında hoşnutluk kazanmış bir kişiydi."},{"n":56,"t":"Kitap'ta İdris'i de an. Çünkü o, özü-sözü tam uyuşan bir kişiydi, bir peygamberdi."},{"n":57,"t":"Onu yüce bir mekâna yükselttik."},{"n":58,"t":"İşte bunlar, Allah'ın kendilerine nimet lütfettiği peygamberlerdendir: Âdem'in soyundan, Nûh'la birlikte taşıdıklarımızdan, İbrahim ve İsrail'in soyundan, kılavuzluk edip seçtiğimiz kimselerden. Kendilerine Rahman'ın ayetleri okunduğunda, ağlayarak secdelere kapanırlardı."},{"n":59,"t":"Ama arkalarından öyle bir nesil geldi ki; namazı/duayı yitirdiler, şehvetlere uydular. Bunlar, azgınlıklarının cezasını bulacaklardır."},{"n":60,"t":"Tövbe eden, iman edip hayra ve barışa yönelik iyi iş yapan müstesna. Böyleleri cennete girecekler ve hiçbir şekilde haksızlığa uğratılmayacaklar."},{"n":61,"t":"Rahman'ın, kullarına gaybda vaat ettiği Adn cennetlerine girecekler. Kuşkusuz, O'nun vaadi yerine gelir."},{"n":62,"t":"Orada boş lakırdı değil, yalnızca \"selam\" işitirler. Orada kendilerinin sabah, akşam, rızıkları da hazırdır."},{"n":63,"t":"Kullarımızdan takva sahibi olanları mirasçı yapacağımız cennet işte budur."},{"n":64,"t":"Biz sadece Rabbinin emrini indiririz/biz ancak Rabbinin emriyle ineriz. Önümüzdeki, arkamızdaki ve bunlar arasındaki herşey O'nundur. Rabbin asla unutkan değildir."},{"n":65,"t":"Göklerin, yerin ve bunlar arasındaki şeylerin Rabbidir o. O'na ibadet et ve O'na ibadette sabırlı ol. O'na adaş olacak birini biliyor musun?"},{"n":66,"t":"Diyor ki insan: \"Öldüğüm zaman diri olarak tekrar çıkarılacak mıyım?\""},{"n":67,"t":"Hatırlamıyor mu insan; o daha önce hiçbir şey değilken, onu biz yarattık."},{"n":68,"t":"Rabbine yemin olsun ki; onları da, şeytanları da mutlaka haşredeceğiz, sonra hepsini diz çökmüş halde cehennemin çevresinde hazır bulunduracağız."},{"n":69,"t":"Sonra her gruptan, Rahman'a karşı kafa tutmada daha şiddetli davrananlar kimlerse, onları ayıracağız."},{"n":70,"t":"Elbette ki biz, oraya girmeye daha layık olanların kimler olduğunu herkesten iyi biliriz."},{"n":71,"t":"İçinizden oraya uğramayacak hiç kimse yoktur. Bu, Rabbin üzerinde kesinleşmiş bir hükümdür."},{"n":72,"t":"Sonra biz, korunup sakınanları kurtaracağız. Zalimleri de orada dizleri üzerinde çökmüş bırakacağız."},{"n":73,"t":"Onlara ayetlerimiz açık-seçik okunduğunda, inkâr edenler inananlara şöyle derler: \"İki zümreden hangisi makamca daha üstün, meclisce daha güzel?\""},{"n":74,"t":"Onlardan önce nice kuşaklar helak ettik ki, malca ve manzaraca daha alımlıydılar."},{"n":75,"t":"De ki: \"Her kim sapıklıkta ise Rahman ona iyice süre versin. Nihayet, kendilerine vaat edileni, azabı veya kıyametin kopuşunu gördüklerinde mekânca daha kötü, taraflarca daha zayıf olanın kim olduğunu bilecekler.\""},{"n":76,"t":"Allah, doğru yolda olanların hidayetini artırır. Barışa ve hayra yönelik kalıcı işler, Rabbin katında sevapça daha üstün, sonuç bakımından daha hayırlıdır."},{"n":77,"t":"Ayetlerimizi inkâr edip, \"Bana mal da evlat da kesinlikle verilecek.\" diyeni gördün mü?"},{"n":78,"t":"Bu adam gaybı mı öğrendi, yoksa Rahman katında bir söz mü aldı?"},{"n":79,"t":"Hayır, hayır! Biz onun söylediğini yazacağız ve onun için azabı uzattıkça uzatacağız."},{"n":80,"t":"O dediklerine biz vâris olacağız. Kendisi bir başına bize gelecek."},{"n":81,"t":"Kendilerine onur ve destek olsunlar diye Allah dışında ilahlar edindiler."},{"n":82,"t":"Hayır, hayır! Onlar, onların ibadetlerini inkâr edecekler ve onların aleyhinde düşman kesilecekler."},{"n":83,"t":"Görmedin mi biz, şeytanları inkârcıların üzerine salmışız da onları oynatıp kıvırttırıyorlar."},{"n":84,"t":"Onlar için acele etme. Biz onlar için günleri teker teker sayıyoruz."},{"n":85,"t":"Gün olur, o sakınanları biz, Rahman'ın huzurunda heyet halinde toplarız."},{"n":86,"t":"Suçluları da susuz ve yaya olarak cehenneme sevk ederiz."},{"n":87,"t":"Rahman katında söz almış olandan başkaları şefaat imkânı bulamazlar."},{"n":88,"t":"\"Rahman çocuk edindi.\" dediler."},{"n":89,"t":"Yemin olsun ki siz, çok çirkin bir iddiada bulundunuz."},{"n":90,"t":"Bu söz yüzünden neredeyse gökler çatlayacak, yer parçalanacak, dağlar yıkılıp çökecek;"},{"n":91,"t":"Rahman için çocuk iddia ettiklerinden ötürü."},{"n":92,"t":"Rahman'a çocuk edinmek yakışmaz."},{"n":93,"t":"Göklerde ve yerde bulunan herkes, Rahman'a kul olarak gelecektir."},{"n":94,"t":"Yemin olsun, O onların hepsini kuşatmış ve tamamını tek tek saymıştır."},{"n":95,"t":"Ve onların hepsi kıyamet günü O'na tek tek gelecektir."},{"n":96,"t":"İman edip hayra ve barışa yönelik işler yapanlara gelince, Rahman onlar için bir sevgi oluşturacaktır."},{"n":97,"t":"Biz onu; senin dilinle kolaylaştırdık ki, sakınanları onunla müjdeleyesin, inatçı bir kavmi de onunla uyarasın."},{"n":98,"t":"Biz onlardan önce de nice kuşaklar helâk ettik. Onlardan herhangi birini hissediyor musun, yahut onların bir iniltisini duyuyor musun?"}],[{"n":1,"t":"Tâ, Hâ."},{"n":2,"t":"Biz bu Kur'an'ı sana, zahmet çekesin, bedbaht olasın diye indirmedik;"},{"n":3,"t":"Saygıyla ürperene bir hatırlatma/düşündürme/öğüt verme olsun diye indirdik."},{"n":4,"t":"Yeri ve o yüce mi yüce gökleri yaratandan bir vahiy olarak indirdik."},{"n":5,"t":"O Rahman, arş üzerine egemenlik kurmuştur."},{"n":6,"t":"Göklerde, yerde, onların arasında, toprağın bağrında ne varsa O'nundur."},{"n":7,"t":"Sen bu sözü açıkça duyuracaksan da O, gizliyi de bilir, gizliden daha gizliyi de..."},{"n":8,"t":"Allah'tır O. İlah yok O'ndan başka. Esmaül Hüsna, en güzel isimler O'nundur."},{"n":9,"t":"Ulaştı mı sana Mûsa'nın haberi?"},{"n":10,"t":"Hani, bir ateş görmüştü de ailesine şöyle demişti: \"Bekleyin! Gözüme bir ateş ilişti. Olabilir ki, ondan size bir kor parçası getiririm, yahut onun üzerinde bir kılavuz bulurum.\""},{"n":11,"t":"Onun yanına geldiğinde kendisine \"Mûsa!\" diye seslenildi."},{"n":12,"t":"\"Benim ben, senin Rabbin! Hadi, pabuçlarını çıkar; sen kutsal vadide, Tuva'dasın.\""},{"n":13,"t":"\"Ve ben seni seçtim; o halde vahyedilecek olanı dinle!\""},{"n":14,"t":"\"Hiç kuşkulanma ki ben Allah'ım! İlah yoktur benden başka! O halde bana ibadet et ve namazını/duanı, beni hatırlayıp anmak için yerine getir.\""},{"n":15,"t":"\"Kuşku duyma ki o saat gelecektir. Onu neredeyse gizliyorum ki, her benlik gayretinin karşılığını elde etsin.\""},{"n":16,"t":"\"O halde ona inanmayıp keyfi peşinde giden, seni ondan yüz geri etmesin. Yoksa perişan olursun.\""},{"n":17,"t":"\"Nedir o sağ elindeki ey Mûsa?\""},{"n":18,"t":"Cevap verdi: \"O, benim asamdır. Ona dayanırım, onunla koyunlarıma ağaçtan yaprak indiririm. Onda, işime yarayan başka özellikler de vardır.\""},{"n":19,"t":"Buyurdu: \"Yere at onu ey Mûsa!\""},{"n":20,"t":"O da onu attı. Bir de ne görsün, bir yılan olmuş o, koşuyor..."},{"n":21,"t":"Buyurdu: \"Al onu, korkma! Biz onu ilk görünümüne döndüreceğiz.\""},{"n":22,"t":"\"Bir de elini koynuna sok! Bir başka mucize olarak lekesiz, bembeyaz bir halde çıksın.\""},{"n":23,"t":"\"Böylece sana en büyük mucizelerimizden bazılarını göstereceğiz.\""},{"n":24,"t":"\"Firavun'a git; çünkü o, azdı.\""},{"n":25,"t":"Mûsa dedi: \"Rabbim, göğsümü açıp genişlet;"},{"n":26,"t":"İşimi bana kolaylaştır.\""},{"n":27,"t":"\"Dilimden düğümü çöz,"},{"n":28,"t":"Ki sözümü iyi anlasınlar.\""},{"n":29,"t":"\"Bana ailemden bir yardımcı ver,"},{"n":30,"t":"Kardeşim Hârun'u.\""},{"n":31,"t":"\"Onunla sırtımı kuvvetlendir!\""},{"n":32,"t":"\"Onu işime ortak kıl!\""},{"n":33,"t":"\"Taki seni çokça tespih edelim!\""},{"n":34,"t":"\"Seni çokça analım!\""},{"n":35,"t":"\"Kuşkusuz sen, bizi görmektesin.\""},{"n":36,"t":"Buyurdu: \"İstediğin sana verildi, ey Mûsa!\""},{"n":37,"t":"\"Yemin olsun, sana bir kez daha lütufta bulunmuştuk.\""},{"n":38,"t":"Hani, annene vahyedileni şöyle vahyetmiştik:"},{"n":39,"t":"\"Onu tabuta koyup ırmağa bırak! Irmak onu sahile götürsün ki, benim de düşmanım, onun da düşmanı olan biri onu alsın. Üzerine kendimden bir sevgi bıraktım ki, gözümün önünde yetiştirilesin.\""},{"n":40,"t":"\"Hani, kızkardeşin gidiyor, şöyle diyordu: 'Onun bakımını üstlenecek kişiyi size göstereyim mi?' Nihayet, seni annene geri döndürdük ki, gözü aydın olsun, tasalanmasın. Sen bir de adam öldürmüştün. O zaman seni gamdan kurtarmıştık. Seni iyice bir imtihana çekmiştik. Bunun ardından sen Medyen halkı arasında yıllarca kaldın. Sonra, belirlenen bir vakitte/bir kadere göre geliverdin, ey Mûsa!\""},{"n":41,"t":"\"Seni kendim için seçip yetiştirdim.\""},{"n":42,"t":"\"Sen ve kardeşin, ayetlerimi götürün; beni anmakta gevşeklik etmeyin.\""},{"n":43,"t":"\"Firavun'a gidin, çünkü o azdı.\""},{"n":44,"t":"\"Ona yumuşak ve tatlı bir sözle hitap edin; belki öğüt alır, yahut ürperir.\""},{"n":45,"t":"Dediler ki: \"Rabbimiz, onun aleyhimizde bir taşkınlık yapmasından yahut yine azmasından korkuyoruz.\""},{"n":46,"t":"Buyurdu: \"Korkmayın! Ben sizinle beraberim; işitiyorum, görüyorum.\""},{"n":47,"t":"\"Hadi gidin ona! Deyin ki; \"Biz senin Rabbinin iki resulüyüz. İsrailoğullarını bizimle gönder, onlara işkence etme! Rabbinden sana bir mucize getirdik. Selam, hidayete uyanlaradır.\""},{"n":48,"t":"\"Azabın, yalanlayıp yüz çevirenler üzerine olacağı bize vahyedildi.\""},{"n":49,"t":"Firavun dedi: \"Sizin Rabbiniz kim, ey Mûsa?\""},{"n":50,"t":"Mûsa dedi: \"Rabbimiz, herşeye yaratılışını lütfeden, sonra da yol-yordam gösteren kudrettir.\""},{"n":51,"t":"Dedi: \"Peki, ilk nesillerin hali ne olacak?\""},{"n":52,"t":"\"Onlara ilişkin bilgi, Rabbim katında bir Kitap'tadır. Rabbim ne şaşırır ne de unutur.\""},{"n":53,"t":"Yeryüzünü size beşik yapan, onda sizin için yollar açan, gökten su indiren O'dur. Biz o suyla çeşitli bitkilerden çiftler çıkardık."},{"n":54,"t":"Yiyin, hayvanlarınızı yayıp otlatın. Kuşkusuz bunda, aklı başında insanlar için ibretler vardır."},{"n":55,"t":"Sizi yerden yarattık. Tekrar oraya göndereceğiz. Ve oradan sizi bir kez daha çıkaracağız."},{"n":56,"t":"Yemin olsun, o Firavun'a ayetlerimizin tamamını gösterdik ama yalanlayıp inadını sürdürdü."},{"n":57,"t":"Şöyle dedi: \"Büyünle bizi, toprağımızdan çıkarasın diye mi geldin, ey Mûsa!\""},{"n":58,"t":"\"Seninki gibi bir büyü, biz de mutlaka sana getireceğiz. Seninle bizim aramızda öyle bir buluşma yeri ve zamanı belirle ki, ne biz cayalım ne de sen. Herkese uygun bir yer olsun.\""},{"n":59,"t":"Mûsa dedi: \"Bizimle buluşacağınız zaman, süs günü olsun. İnsanlar kuşluk vakti bir araya getirilsin.\""},{"n":60,"t":"Bunun üzerine Firavun oradan ayrıldı, tüm kurnazlığını topladı, sonra geldi."},{"n":61,"t":"Mûsa onlara dedi ki: \"Yazıklar olsun size, yalan düzerek Allah'a iftira etmeyin! Yoksa bir azap ile kökünüzü kurutur. İftira eden, perişan olmuştur.\""},{"n":62,"t":"Bunun üzerine işlerini aralarında tartıştılar, fısıltıyı koyulaştırdılar."},{"n":63,"t":"Dediler ki: \"Şunlar, iki büyücüden başka birşey değillerdir. Büyüleriyle sizi toprağınızdan çıkarmak ve sizin örnek yolunuzu silip yok etmek istiyorlar.\""},{"n":64,"t":"\"Hemen hünerlerinizi birleştirin; sonra saf bağlamış olarak gelin! Bugün, üstün gelen kurtulmuş olacaktır.\""},{"n":65,"t":"Dediler: \"Ey Mûsa, ya hünerini ortaya at yahut da ilk hüner sergileyen biz olacağız.\""},{"n":66,"t":"Mûsa dedi: \"Hayır, siz atın!\" Bir de ne görsün! Onların ipleri, sopaları, yaptıkları büyüler yüzünden, kendisine gerçekten koşuyorlarmış hayaline verdi."},{"n":67,"t":"Mûsa birdenbire içinde bir korku duydu."},{"n":68,"t":"Şöyle dedik: \"Korkma, üstün gelecek olan sensin!\""},{"n":69,"t":"\"Sağ elindekini yere bırak! Onların, sanayi olarak ortaya çıkardıklarını yalayıp yutsun. Onların sanayi olarak ürettikleri sadece bir büyücünün hilesidir. Büyücü ise nereye gitse iflah etmez.\""},{"n":70,"t":"Bunun üzerine büyücüler secdelere kapanıp şöyle seslendiler: \"Hârun'un ve Mûsa'nın Rabbine inandık!\""},{"n":71,"t":"Firavun dedi: \"Ben izin vermeden ona inandınız öyle mi? O size, büyüyü öğreten büyüğünüzdür. Yemin olsun, ellerinizi, ayaklarınızı çaprazlama keseceğim ve yemin olsun sizi hurma ağaçlarına asacağım. O zaman iyice bileceksiniz, hangimizin azabı daha şiddetli ve sürekli.\""},{"n":72,"t":"Dediler: \"Biz seni, bize gelen açık-seçik kanıtlara ve bizi yaratmış olana asla tercih etmeyeceğiz. Verdiğin hükmü uygula. Senin hükmün olsa olsa bu dünya hayatında geçer.\""},{"n":73,"t":"\"Biz Rabbimize inandık ki, günahlarımızı ve senin bizi zorladığın büyüyü affetsin. Allah daha hayırlı, daha süreklidir.\""},{"n":74,"t":"Şu bir gerçek ki, Rabbinin huzuruna suçlu olarak gelen için cehennem vardır. Orada ne ölür ne de hayat bulur."},{"n":75,"t":"O'nun huzuruna, hayra ve barışa yönelik iyilikler üretmiş bir mümin olarak varana gelince, işte böyleleri için çok yüksek dereceler öngörülmüştür."},{"n":76,"t":"Adn cennetleri ki, altlarından ırmaklar akar; sürekli kalacaklar içlerinde. Arınıp temizlenenlerin ödülü işte budur."},{"n":77,"t":"Yemin olsun, Mûsa'ya şöyle vahyetmiştik: \"Kullarımı geceleyin yürüt! Denizde onlar için kuru bir yol aç! Size yetişecekler diye korkma, endişelenme.!\""},{"n":78,"t":"Derken, Firavun, ordusuyla birlikte onların arkasına düştü. Ama denizden onları sarıp kuşatan, sarıp kuşattı."},{"n":79,"t":"Firavun kendi toplumunu saptırmıştı; kılavuzluk edemedi."},{"n":80,"t":"Ey İsrailoğulları, şu bir gerçek ki, biz sizi düşmanınızdan kurtardık. Tûr'un sağ yanında size vaatte bulunduk. Ve üstünüze kudret helvasıyla bıldırcın indirdik."},{"n":81,"t":"Size verdiğimiz rızkın temizlerinden yiyin! Bu konuda azgınlık etmeyin! Yoksa öfkem üzerinize çöker. Ve kimin üstüne öfkem inerse o uçuruma gider."},{"n":82,"t":"Ve ben, tövbe eden, inanan, hayra ve barışa yönelik iş yapıp sonra da düzgün bir biçimde yol alan kimseye karşı, gerçekten çok affediciyim, Gaffâr'ım."},{"n":83,"t":"Seni toplumundan çabucak uzaklaştıran neydi, ey Mûsa?"},{"n":84,"t":"Dedi: \"Onlar, benim eserim üzerindeler. Ben sana gelmede acele davrandım ki, benden hoşnut olasın, ey Rabbim!\""},{"n":85,"t":"Buyurdu: \"Biz senden sonra toplumunu tam bir biçimde imtihan ettik. Sâmirî onları saptırdı.\""},{"n":86,"t":"Bunun üzerine Mûsa, öfkeli ve ümidi kırık bir halde kavmine döndü. Dedi: \"Ey toplumum! Rabbiniz size güzel bir vaatte bulunmadı mı? Süre mi size uzun geldi yoksa Rabbinizden üzerinize bir gazabın inmesini mi istediniz de bana verdiğiniz söze ters davrandınız?\""},{"n":87,"t":"Dediler ki: \"Biz sana kendi irademizle/malımızla karşı çıkmadık. Olay şu: Bize o topluluğun süs eşyalarından bazıları yükletilmişti, onları kaldırıp attık; aynı şekilde Sâmirî de attı.\""},{"n":88,"t":"Sâmirî onlar için, böğürmesi olan bir buzağı heykeli çıkardı. Dediler ki: \"Bu, hem sizin hem de Mûsa'nın tanrısıdır. Ama Mûsa unuttu.\""},{"n":89,"t":"Görmüyorlar mı ki; o buzağı onlara bir sözü geri çeviremiyor; kendilerine bir zarar veremiyor, bir yarar sağlayamıyor."},{"n":90,"t":"Yemin olsun, Hârun daha önce onlara şunu söylemişti: \"Ey kavmim, siz bununla imtihan edildiniz. Sizin Rabbiniz o Rahman'dır. Artık bana uyun, emrime itaat edin!\""},{"n":91,"t":"Onlar şöyle demişlerdi: \"Mûsa bize dönünceye kadar ona tapıcılar olmakta devam edeceğiz.\""},{"n":92,"t":"Mûsa dedi: \"Ey Hârun, onların saptıklarını gördüğün zaman seni ne engelledi de,"},{"n":93,"t":"Benim ardım sıra gelmedin. Emrime isyan mı ettin?\""},{"n":94,"t":"Hârun dedi: \"Ey annemin oğlu! Sakalımı, başımı tutma! Ben senin şöyle diyeceğinden korkmuştum: 'Beniisrail arasına ayrılık soktun, sözüme bağlı kalmadın!\""},{"n":95,"t":"Mûsa dedi: \"Senin derdin neydi, ey Sâmirî?\""},{"n":96,"t":"Sâmirî dedi: \"Onların görmediklerini gördüm. Resulün izinden bir avuç avuçladım da onu attım. Nefsim bana böylesini hoş gösterdi.\""},{"n":97,"t":"Mûsa dedi: \"Defol, çünkü sen, hayatın boyunca 'Bana dokunmayın!' diyeceksin! Ve senin için asla kurtulamayacağın bir hesap zamanı da var. O başını bekleyip durduğun tanrına bir bak! Onu kesinlikle yakacağız, sonra da un-ufak edip denize dökeceğiz.\""},{"n":98,"t":"Gerçek olan şu ki, sizin ilahınız kendisinden başka hiçbir tanrı olmayan Allah'tır. O, ilim bakımından her şeyi çepeçevre kuşatmıştır."},{"n":99,"t":"İşte böylece, geçip gitmişlerin haberlerinden bir kısmını sana anlatıyoruz. Biz sana katımızdan da bir Zikir/Kur'an vermişizdir."},{"n":100,"t":"Kim ondan yüz çevirirse, kıyamet günü bir günah yüklenecektir."},{"n":101,"t":"Uzun süre o yükün altındadır; kıyamet gününde bu onlar için ne kötü yüktür!"},{"n":102,"t":"O gün sûra üfürülür ve günahkârları o gün gözleri gömgök bir halde haşrederiz."},{"n":103,"t":"Aralarında fısıldaşır gibi konuşurlar: \"Ancak on gün filan kaldınız.\""},{"n":104,"t":"Onların söylemekte olduklarını biz daha iyi biliriz. Yolca en seçkinleri olan şöyle diyordu: \"Eni-sonu, bir gün kaldınız.\""},{"n":105,"t":"Sana dağlardan soruyorlar. De ki: \"Rabbim onları un-ufak edecektir.\""},{"n":106,"t":"\"Yerlerini bomboş, dümdüz bırakacaktır.\""},{"n":107,"t":"\"Yerlerinde bir eğrilik de bir yumruluk da görmeyeceksin.\""},{"n":108,"t":"O gün, eğip bükmesi olmayan davetçiye uyarlar. Rahman'ın huzurunda sesler kısılır, artık bir hışıltıdan başka şey işitmezsiniz."},{"n":109,"t":"O gün şefaat yarar sağlamaz. Ancak Rahman'ın izin verdiği ve sözünden hoşnut olduğu kimse müstesna..."},{"n":110,"t":"Onların önden gönderdiklerini de arkada bıraktıklarını da bilir, ama onlar O'nu ilimle kuşatamazlar."},{"n":111,"t":"Bütün yüzler o Hayy ve Kayyûm önünde yere inmiştir. Zulüm taşıyan perişan olup gitmiştir."},{"n":112,"t":"Mümin olarak hayra ve barışa yönelik iyilikler yapan ise ne haksızlığa uğratılmaktan korkar ne de ezilip horlanmaktan."},{"n":113,"t":"Biz onu işte böyle, Arapça bir Kur'an olarak indirdik ve onun içinde tehditleri türlü ifadelerle sıraladık ki sakınabilsinler, yahut da Kur'an onlara yeni bir hatırlatıcı/hatırlatma sunsun."},{"n":114,"t":"O Melik/o hak hükümdar olan Allah, yüceler yücesidir. Sana vahyi tamamlanmadan önce, Kur'an hakkında aceleci olma. Şöyle de: \"Rabbim, ilmimi artır!\""},{"n":115,"t":"Yemin olsun, biz daha önce Âdem'e ahit verdik de unuttu; biz onda bir kararlılık bulamadık."},{"n":116,"t":"Hani meleklere \"Âdem'e secde edin!\" demiştik de İblis müstesna hepsi secde etmişti. İblis dayatmıştı."},{"n":117,"t":"Bunun üzerine biz şöyle demiştik: \"Ey Âdem! Şu, senin de eşinin de düşmanıdır, dikkat et de sizi cennetten çıkarmasın; sonra bedbaht olursun.\""},{"n":118,"t":"\"Senin burada ne acıkman söz konusudur ne de çıplak kalman.\""},{"n":119,"t":"\"Ve sen burada ne susayacaksın ne de güneşten yanacaksın.\""},{"n":120,"t":"Derken, şeytan ona şöyle diyerek vesvese verdi: \"Ey Âdem! Sana, sonsuzluk ağacıyla eskimez-çökmez mülk ve saltanatı göstereyim mi?\""},{"n":121,"t":"Nihayet, ikisi de ondan yediler. Bunun üzerine, çirkin yerleri kendilerine açıldı; üzerlerine cennet yapraklarından örtmeye başladılar. Âdem, Rabbine isyan etmiş, azmış, ziyana uğramıştı."},{"n":122,"t":"Sonra, Rabbi onu arıtıp temizledi, onun tövbesini kabul edip kendisini iyiye ve doğruya kılavuzladı."},{"n":123,"t":"Allah dedi: \"İkiniz birlikte inin oradan! Birbirinize düşmansınız. Benden size bir hidayet geldiğinde, benim o hidayetime uyan artık ne sapar ne de bedbaht olur.\""},{"n":124,"t":"Kim benim zikrimden/Kur'anımdan yüz çevirirse onun için zor, sıkıcı bir hayat şekli/dar bir geçim vardır; kıyamet günü de onu kör olarak haşrederiz."},{"n":125,"t":"O der ki: \"Rabbim, beni neden kör haşrettin, ben gören biri idim?\""},{"n":126,"t":"Allah buyurur: \"Ayetlerimiz sana geldiğinde sen böyle unutmuştun; bugün de sen aynı şekilde unutuluyorsun.\""},{"n":127,"t":"İsraf eden/haddi aşan ve Rabbinin ayetlerine inanmayan kimseleri biz böyle cezalandırırız. Ve âhiretin azabı çok daha şiddetli, çok daha kalıcıdır."},{"n":128,"t":"Kendilerinden önceki nesillerden nicelerini helâk etmemiz onları yola getirmedi mi? Onların yurtlarında/barınaklarında dolaşıp duruyorlar. Akıl sahipleri için bunda elbette ibretler vardır!"},{"n":129,"t":"Eğer Rabbin tarafından daha önce söylenmiş bir söz, belirlenmiş bir süre olmasaydı, bunlar için de helâk kaçınılmaz olurdu."},{"n":130,"t":"Artık, onların söylediklerine sabret; Güneş'in doğuşundan önce de batışından önce de Rabbini överek tespih et! Gecenin bazı saatleriyle gündüzün iki ucunda da tespit et ki, hoşnutluğa erebilesin."},{"n":131,"t":"Onlardan bazı çiftlere, kendilerini imtihan etmek için iğreti hayatın süsü olarak verdiğimiz nimetlere gözlerini dikme! Rabbinin rızkı hem daha hayırlı hem daha süreklidir."},{"n":132,"t":"Aileni namaza/duaya özendir kendin de ona sabırla devam et! Biz senden rızık istemiyoruz. Seni biz rızıklandırıyoruz. Sonuç takvanındır!"},{"n":133,"t":"Dediler ki: \"Rabbinden bize bir mucize getirseydi ya!\" Peki, önceki sayfalardaki açık kanıt onlara gelmedi mi?"},{"n":134,"t":"Eğer biz onları, ondan önce bir azapla helâk etseydik mutlaka şöyle diyeceklerdi: \"Rabbimiz, ne olurdu bize bir resul gönderseydin de zelil ve rezil olmadan önce senin ayetlerine uysaydık!\""},{"n":135,"t":"De ki: \"Herkes bekleyip gözetlemede; hadi siz de bekleyip gözetleyin! Yakında bileceksiniz dosdoğru yolu izleyenler kimlermiş, hidayete eren kimmiş!\""}],[{"n":1,"t":"Yaklaştı insanlara hesapları! Ve onlar hâlâ gaflet içinde yüz çevirip durmadalar."},{"n":2,"t":"Rablerinden kendilerine ulaşan, söze bürünmüş her yeni öğüt ve hatırlatmayı ancak eğlenerek dinliyorlar."},{"n":3,"t":"Kalpleri hep oyun ve oyalanmada. O zulüm sergileyenler, şu yolda bir fısıldaşmayı iyice koyulaştırdılar: \"Bu adam, sizin gibi bir insandan başkası değil. Gözünüz baka baka büyüye mi gidiyorsunuz!\""},{"n":4,"t":"Dedi: \"Rabbim, gökteki sözü de yerdeki sözü de bilir. O, herşeyi duyan, her şeyi bilendir!\""},{"n":5,"t":"Şöyle de dediler: \"Saçma sapan rüyalar bunlar! Belki de uydurduğu bir yalandır. Belki de bir şairdir o. Hadi bir mucize getirsin bize, öncekilere gönderildiği gibi...\""},{"n":6,"t":"Onlardan önce yere batırdığımız hiçbir yurt ve uygarlık iman etmemiştir. Onlar mı iman edecekler!..."},{"n":7,"t":"Senden önce de ancak kendilerine vahyettiğimiz erler gönderdik. Hadi, sorun zikir/Kur'an ehline, eğer bilmiyorsanız..."},{"n":8,"t":"Biz onları yemek yemez bir ceset olarak yaratmadık. Onlar sonsuza dek kalıcı da değillerdi."},{"n":9,"t":"Sonra onlara verilen söze sadık kaldık da onları ve dilediklerimizi kurtardık. Ve israfa saplanıp haddi aşanları helâk ettik."},{"n":10,"t":"Yemin olsun, size bir Kitap gönderdik ki, öğüt ve uyarınız/zikriniz/şerefiniz yalnız ondadır. Hâlâ aklınızı çalıştırmayacak mısınız?"},{"n":11,"t":"Zulmetmiş nice kenti/medeniyeti biz kırıp geçirdik ve arkalarından başka bir topluluk oluşturduk."},{"n":12,"t":"Şiddetimizi hissettiklerinde hiç vakit geçirmeksizin oradan dört nala kaçıyorlardı."},{"n":13,"t":"Kaçmayın, içinde servet şımarıklığına düştüğünüz yere, meskenlerinize dönün ki, hesaba çekilebilesiniz."},{"n":14,"t":"Dediler: \"Eyvah bize! Biz gerçekten zalimlermişiz.\""},{"n":15,"t":"Bu davaları sürüp giderken biz onları kökten biçiverdik, sönüp silindiler."},{"n":16,"t":"Biz, gökleri de yeri de bunlar arasındakileri de eğlenip eğlendirelim diye yaratmadık."},{"n":17,"t":"Eğer bir eğlence edinmek isteseydik onu kendi katımızdan edinirdik. Ama böyle yapanlar değildik/yapsaydık öyle yapardık."},{"n":18,"t":"Hayır, biz hakkı, bâtılın üzerine fırlatırız da o, onun beynini parçalar. Bir de bakarsın o yok olup gitmiştir. Yakıştırdığınız niteliklerden ötürü yazıklar olsun size!"},{"n":19,"t":"Göklerde ve yerde kim varsa O'na aittir. Ve O'nun katındakiler, O'na ibadet etmekten ne çekinirler ne de yorulurlar."},{"n":20,"t":"Gece ve gündüz tespih ederler, bıkıp usanmazlar."},{"n":21,"t":"Yoksa yerden bazı ilahlar edindiler de topraktan çıkarıp diriltme işini onlar mı yapacak?"},{"n":22,"t":"Eğer yerde-gökte Allah'tan başka tanrılar olsaydı, o ikisi de mutlaka fesada uğrardı. Arşın Rabbi o Allah, onların nitelendirmelerinden yücedir, uzaktır."},{"n":23,"t":"O, yaptığından hesaba çekilmez ama onlar hesaba çekilirler."},{"n":24,"t":"Yoksa O'nun dışında bazı ilahlar mı edindiler? De ki: \"Susturucu delilinizi getirin! Benimle beraber olanların da benden öncekilerin de Zikir'i budur. Ne yazık ki onların çokları hakkı bilmezler; bu yüzden de yüz çevirirler.\""},{"n":25,"t":"Senden önce hiçbir resul göndermedik ki ona şöyle vahyetmiş olmayalım: \"Gerçek şu: İlah yok benden başka, artık bana kulluk/ibadet edin.\""},{"n":26,"t":"\"Rahmân çocuk edindi\" dediler. Tenzih ederiz O'nu! Hayır, onların çocuk dedikleri, lütfandırılmış/ onurlandırılmış kullardır."},{"n":27,"t":"Onlar O'nun sözünün önüne geçmezler; onlar yalnız O'nun emriyle iş yaparlar."},{"n":28,"t":"O, onların önlerindekini de arkalarındakini de bilir. Onlar, O'nun hoşnutluk verdiklerinden başkasına da şefaat etmezler. Ve onlar O'nun korkusundan titrerler."},{"n":29,"t":"İçlerinden her kim, \"Ben O'nun berisinden/alt mertebesinden bir ilahım!\" derse böylesini cehennemle cezalandırırız. Zalimleri işte böyle cezalandırırız biz."},{"n":30,"t":"O küfre sapanlar görmediler mi ki gökler ve yer bitişik idi, biz onları ayırdık. Her canlı şeyi sudan oluşturduk. Hâlâ iman etmeyecekler mi?"},{"n":31,"t":"Yerküreye, onları çalkalamasın diye bir takım dağlar diktik. Ve orada geniş geniş yollar açtık ki, doğru gidebilsinler."},{"n":32,"t":"Göğü, korunmuş bir tavan yaptık. Ama onlar göğün ayetlerinden hâlâ yüz çeviriyorlar."},{"n":33,"t":"O odur ki, geceyi, gündüzü, Güneş'i ve Ay'ı yarattı. Her biri bir yörüngede yüzmektedir."},{"n":34,"t":"Senden önce hiçbir insana ölümsüzlük vermedik. Şimdi sen ölürsen, onlar ölümsüz mü olacaklar?\""},{"n":35,"t":"Her canlı, ölümü tadacaktır. Biz bir imtihan olarak sizi şer ile de hayır ile de deniyoruz. Sonunda bize döndürüleceksiniz."},{"n":36,"t":"O küfredenler seni gördüklerinde, seni şu şekilde alaya almaktan başka birşey yapmazlar: \"İlahlarınızı diline dolayan bu mu?\" Ama Rahman'ın zikrini/Kur'an'ı bizzat onlar örtüp inkâr ediyorlar."},{"n":37,"t":"İnsan, aceleden yaratılmıştır. Ayetlerimi size göstereceğim. Benden acele istemeyin!"},{"n":38,"t":"Diyorlar ki: \"Eğer doğru sözlüler iseniz bu vaat ne zaman?\""},{"n":39,"t":"O inkâr edenler, ne yüzlerinden ne sırtlarından azabı uzak tutamayacakları ve hiçbir yardım da göremeyecekleri zamanı bir bilselerdi!"},{"n":40,"t":"Doğrusu şu ki, o onlara ansızın gelecek de onları şaşkınlıktan donduracak. Artık ne onu geri çevirmeye güçleri yetecek ne de yüzlerine bakılacak."},{"n":41,"t":"Yemin olsun, senden önceki resullerle de alay edilmiştir. Sonunda, onlarla eğlenenleri, alay konusu yaptıkları şey kuşatıverdi."},{"n":42,"t":"De ki: \"Sizi gece ve gündüz Rahman'dan kim koruyabilir?\" Hayır, hayır! Onlar, Rablerinin zikrinden/Kur'an'ından yüz çeviriyorlar."},{"n":43,"t":"Yoksa onların; kendilerini bize karşı siperleyecek tanrıları mı var? Ne kendilerine yardıma güç yetirebilirler ne de bizden bir dostluğa muhatap olurlar."},{"n":44,"t":"Gerçek şu ki, biz onları ve atalarını, ömür kendilerine uzun gelecek kadar nimetlendirdik. Hâlâ görmüyorlar mı ki, biz yerküreye geliyor, onu uçlarından eksiltiyoruz. Galip gelenler onlar mı?"},{"n":45,"t":"De ki: \"Ben sizi ancak vahiyle uyarıyorum.\" Ama sağırlar, uyarıldıklarında çağrıyı işitmezler ki!"},{"n":46,"t":"Rabbinin azabından onlara bir esinti dokunsa, yemin olsun şöyle diyecekler: \"Vay bizlere, biz zalimlermişiz!\""},{"n":47,"t":"Kıyamet günü için adalet terazilerini kuracağız/adaleti terazilere koyacağız. Hiç kimseye zerre kadar zulüm edilmeyecek. Hardal tanesi kadar birşey olsa onu ortaya getiririz. Hesapçılar olarak biz yeteriz!"},{"n":48,"t":"Yemin olsun, biz, Mûsa'ya ve Hârun'a hak ile bâtılı ayıran, korunanlar için bir ışık ve öğüt olan furkanı verdik."},{"n":49,"t":"O korunanlar ki, hiç görmeden Rablerinden korkarlar. Kıyamet saatinden de ürperirler onlar."},{"n":50,"t":"Bu, bereketli bir Zikir'dir ki, onu indirdik. Yoksa siz onu inkâr mı ediyorsunuz?"},{"n":51,"t":"Yemin olsun, İbrahim'e daha önceden, doğruyu bulma gücünü vermiştik. Onu bilmekteydik biz."},{"n":52,"t":"Babasına ve toplumuna şöyle demişti: \"Şu başına toplanıp durduğunuz heykeller de ne?\""},{"n":53,"t":"Dediler: \"Atalarımızı onlara kulluk/ibadet eder bulduk.\""},{"n":54,"t":"Dedi: \"Vallahi, siz de atalarınız da açık bir sapıklık içine düşmüşsünüz.\""},{"n":55,"t":"Dediler: \"Sen gerçeği mi getirdin yoksa oynayıp eğlenenlerden biri misin?\""},{"n":56,"t":"Dedi: \"Hiç de değil! Sizin Rabbiniz, göklerin ve yerin Rabbidir ki, onları yaratmıştır. Ben de bunlara tanıklık edenlerdenim.\""},{"n":57,"t":"\"Allah'a yemin ederim, sırtınızı dönüp gidişinizden sonra, putlarınıza bir oyun çevireceğim.\""},{"n":58,"t":"Sonunda onları parça parça etti. Yalnız en büyüklerini bıraktı ki, dönüp ona başvurabilsinler."},{"n":59,"t":"Dediler: \"Tanrılarımıza bunu yapan kesinlikle zalimlerdendir.\""},{"n":60,"t":"Dediler: \"Onları diline dolayan bir genç duymuştuk. Kendisine 'İbrahim' deniyor.\""},{"n":61,"t":"Dediler: \"Halkın gözleri önüne getirin onu ki, açıkça görebilsinler.\""},{"n":62,"t":"Dediler: \"Tanrılarımıza bunu sen mi yaptın, ey İbrahim?\""},{"n":63,"t":"Dedi: \"Hayır, ben değil. Şu büyükleri yapmıştır onu. Hadi, sorun onlara eğer konuşabiliyorlarsa!\""},{"n":64,"t":"Bunun üzerine kendi benliklerine döndüler de şöyle dediler: \"Siz, zalimlerin ta kendilerisiniz.\""},{"n":65,"t":"Sonra, yine kendi kafalarına döndürüldüler: \"Vallahi, sen de bilirsin ki, bunlar konuşamazlar.\""},{"n":66,"t":"İbrahim dedi: \"Siz, Allah'ın berisinden, size hiçbir şekilde yarar sağlamayan, zarar veremeyen şeylere mi tapıyorsunuz?\""},{"n":67,"t":"\"Yazıklar olsun size ve Allah'ın berisinden taptıklarınıza! Siz hâlâ aklınızı kullanmayacak mısınız?\""},{"n":68,"t":"Dediler: \"Yakın bunu! Eğer birşey yapacak kişilerseniz, ilahlarınıza yardım edin.\""},{"n":69,"t":"Biz de şöyle dedik: \"Ey ateş, İbrahim'e bir serinlik ol, bir selam ol!\""},{"n":70,"t":"Ona tuzak kurmak istediler de biz onları hüsranın en beterine uğrayanlar yaptık."},{"n":71,"t":"Biz onu da Lût'u da kurtarıp içinde âlemlere bereketler sakladığımız toprağa ulaştırdık."},{"n":72,"t":"Ona İshak'ı bağışladık, ayrıca Yakub'u da hediye ettik. Hepsini hak ve barış için çalışan insanlar yaptık."},{"n":73,"t":"Onları, bizim buyruğumuzla yol alan önderler yaptık. Onlara iyilikler yapmayı, duayı/namazı yerine getirmeyi, zekât vermeyi vahyettik. Onlar, yalnız bize kulluk ediyorlardı."},{"n":74,"t":"Lût'a da hükümranlık ve ilim verdik. Onu, pislikler üretip duran bir kentten kurtardık. O kent halkı yoldan çıkmış kötü bir kavimdi."},{"n":75,"t":"Onu rahmetimizin içine soktuk. O, hak ve barış için çalışanlardandı."},{"n":76,"t":"Nûh'a gelince, o da daha önce bize yakarmıştı. Yakarışına cevap verdik de onu ve ailesini, o büyük sıkıntıdan kurtardık."},{"n":77,"t":"Ona, ayetlerimizi yalanlayan topluluğa karşı yardım ettik. Kötülüğün toplumuydu onlar. Hepsini birden batırıp boğduk."},{"n":78,"t":"Ve Dâvud ile Süleyman... Hani, halkın davarının yayıldığı ekinler hakkında hüküm veriyorlardı da biz hükümlerine tanıklar olmuştuk."},{"n":79,"t":"Onu Süleyman'a derhal kavrattık. Her birine hükümdarlık ve bilgi verdik. Dâvud'a dağları boyun eğdirdik. Kuşlarla beraber tespih ediyorlardı. Yapmak isteyince yapanlarız biz!"},{"n":80,"t":"Ve ona, sizi savaşınızın şiddetinden korusun diye zırh yapma sanatını öğrettik. Peki, siz şükrediyor musunuz?"},{"n":81,"t":"Ve Süleyman'a kasırgayı boyun eğdirdik. İçini bereketlerle doldurduğumuz toprağa doğru onun emriyle akıp giderdi. Her şeyi bilenleriz biz!"},{"n":82,"t":"Kendisi için dalgıçlık eden, daha başka iş de yapan bazı şeytanları da onun emrine verdik. Biz onları koruyup gözetiyorduk."},{"n":83,"t":"Ve Eyyûb... Rabbine şöyle yakarmıştı: \"Dert/zorluk gelip çattı bana; sen, rahmet edenlerin en merhametlisisin!\""},{"n":84,"t":"Hemen cevap verdik ona, kendisindeki derdi kaldırdık. Tarafımızdan bir rahmet ve ibadet edenler için bir hatırlatma olarak, ona ailesini ve beraberinde, benzerlerini de verdik."},{"n":85,"t":"İsmail, İdris, Zülkifl, hepsi sabredenlerdendi."},{"n":86,"t":"Hepsini rahmetimize soktuk. Onlar hak ve barış için çalışanlardandı."},{"n":87,"t":"Ve Zünnûn. Hani, kızarak gitmişti de ona asla güç yetiremeyeceğimizi/ölçüyü kendisine uygulamayacağımızı sanmıştı. Sonra, karanlıkların bağrında şöyle yakardı: \"Senden başka ilah yok, tespih ederim seni! Kuşkusuz, ben zalimlerden oldum.\""},{"n":88,"t":"Hemen imdadına yetiştik. Gamdan kurtardık onu. İnananları işte böyle kurtarırız biz!"},{"n":89,"t":"Ve Zekeriyya. Hani, Rabbine yakarmıştı: \"Rabbim, beni yapayalnız, bir başıma bırakma! Sen, Vâris olanların/mirasçıların en hayırlısısın!\""},{"n":90,"t":"Kendisine hemen cevap vermiş. Yahya'yı ona hediye etmiş, karısını kendisi için doğurmaya elverişli hale getirmiştik. Onlar, hayırlarda yarışırlar, umarak ve korkarak bize yalvarırlardı. Onlar, bize ürpererek saygı gösterirlerdi."},{"n":91,"t":"Ve o, cinsiyet organını/ırzını titizlikle koruyan kadın. Onun bağrına ruhumuzdan üfledik de kendisini ve oğlunu âlemler için bir mucize yaptık."},{"n":92,"t":"İşte şu sizin ümmetiniz bir tek ümmettir. Ben de Rabbinimiz. O halde bana ibadet edin."},{"n":93,"t":"İşlerini aralarında parçaladılar. Hepsi bize dönecekler."},{"n":94,"t":"Kim inanmış olarak hayra ve barışa yönelik işlerden bir şey yaparsa, onun gayretine nankörlük edilmez. Biz böylesi lehine kâtiplik ederiz."},{"n":95,"t":"Helâk ettiğimiz bir kente/medeniyete yaşamak haram edilmiştir. Onlar bir daha geri dönemezler."},{"n":96,"t":"Ye'cûc ve Me'cûc'ün önü açıldığı zaman onlar, her tepeden akın ederler."},{"n":97,"t":"Hak olan vaat yaklaşmıştır. İnkâr edenlerin gözleri birden donup kalmıştır. \"Vay başımıza! Biz bundan gafil bulunuyorduk. Hayır, biz zalimlerdik!\" derler."},{"n":98,"t":"Siz ve Allah'ın berisinden, kulluk/kölelik ettikleriniz, cehennem odunusunuz. Hepiniz oraya gireceksiniz."},{"n":99,"t":"Eğer onlar ilah olsalardı, oraya girmezlerdi. Oysaki, hepsi orada uzun süre kalacaklardır."},{"n":100,"t":"Onlar için orada derin bir iç çekiş var. Ve onlar orada hiçbir şey işitmezler."},{"n":101,"t":"Tarafımızdan kendilerine güzellik hazırlananlara gelince, bunlar cehennemden uzaklaştırılmışlardır."},{"n":102,"t":"Onun uğultusunu duymazlar. Onlar, gönüllerinin istediği şeyler içinde sürekli yaşayacaklardır."},{"n":103,"t":"O en büyük korku onları tasalandırmaz. Melekler onları şöyle karşılarlar: \"Bu size o vaat edilen gününüzdür!\""},{"n":104,"t":"Gün olur, göğü, yazı tomarlarını dürer gibi düreriz. İlk yaratılışta başladığımız gibi onu baştan yaparız. Üzerimizde bir vaat olarak biz bunu mutlaka yapacağız."},{"n":105,"t":"Yemin olsun, zikirden sonra Zebur'da şunu yazmıştık: Yeryüzüne benim iyilik ve barış seven kullarım vâris olacaktır."},{"n":106,"t":"Kuşkusuz, bunda, ibadet eden/iş yapıp değer üreten bir topluluk için kesin bir tebliğ vardır."},{"n":107,"t":"Ve biz seni ancak âlemlere bir merhamet/bir sevgi olman dışında bir şey için göndermedik."},{"n":108,"t":"De ki: \"Bana şu vahyediliyor: \"Tanrınız ancak bir tek tanrıdır. Peki, siz, müslümanlar/Allah'a teslim olanlar mısınız?\""},{"n":109,"t":"Eğer yüz çevirirlerse de ki: \"Hepinize aynı şekilde, aynı düzeyde açıkladım. Artık bilmiyorum, tehdit edildiğiniz şey yakın mıdır, uzak mıdır?\""},{"n":110,"t":"Kuşkusuz O, sözün açığa vurulanını da bilir; saklamakta olduklarımızı da bilir."},{"n":111,"t":"Bilmiyorum, belki de o, sizin için bir fitnedir. Belirli bir süreye kadar bir nimetlendirmedir."},{"n":112,"t":"Resul şöyle yakardı: \"Rabbim, hak ile hükmet! Bizim Rabbimiz Rahman'dır. Sizin nitelendirmelerinize karşı yardımına başvurulandır, Müsteân'dır.\""}],[{"n":1,"t":"Ey insanlar! Rabbinizden korkun! Çünkü kıyamet saatinin zelzelesi gerçekten çok büyük bir şeydir."},{"n":2,"t":"Onu göreceğiniz gün, her emzikli kadın, emzirdiğinden vazgeçer ve her gebe kadın, taşıdığını düşürür. Sen o gün insanları sarhoşlar halinde görürsün; oysaki onlar sarhoş değillerdir, ama Allah'ın azabı çok şiddetlidir."},{"n":3,"t":"İnsanlardan bazıları vardır, hiçbir ilme sahip olmadan Allah konusunda mücadele eder ve her inatçı-kaypak şeytanın ardı sıra gider."},{"n":4,"t":"O şeytan üzerine şöyle yazılmıştır: Kim buna dost olursa muhakkak o onu saptırır ve onu, alevi zorlu ateşin azabına götürür."},{"n":5,"t":"Ey insanlar! Ölümden sonra dirilme konusunda kuşku içinde olabilirsiniz. Ama şu bir gerçek ki, biz sizi bir topraktan, sonra bir spermden, sonra bir embriyodan/döllenmiş bir karışımdan, sonra ne olduğu kısmen belirli, kısmen belirsiz bir et parçasından yarattık ki, size açık-seçik beyanda bulunalım. Ve sizi rahimlerde, belirlenen bir süreye kadar dilediğimiz şekilde bekletiyoruz. Sonra sizi bir çocuk olarak çıkarıyoruz. Daha sonra da tam kuvvetinize ulaşmanızı sağlıyoruz. Bununla birlikte içinizden bir kısmı öldürülüyor, yine içinizden bir kısmı ilimden sonra bir şey bilmesin diye ömrün en basit ve düşük noktasına geri gönderiliyor. Yeryüzünü de sönmüş kül halinde görürsün. Nihayet onun üzerine suyu indirdiğimizde titrer, kabarır ve her güzel/bereketli çiftten bir şeyler bitirir."},{"n":6,"t":"Bu böyledir, çünkü Allah hakkın ta kendisidir. O, ölüleri diriltiyor ve O, herşey üzerinde kudretiyle egemendir."},{"n":7,"t":"Ve saat mutlaka gelecektir. Kuşku yok onda. Ve Allah kabirlerdeki şuurlu varlıkları diriltecektir."},{"n":8,"t":"İnsanlar içinde öylesi vardır ki, Allah konusunda ilimsiz, kılavuzsuz ve aydınlık getiren bir kitaba sahip olmaksızın mücadele edip durur."},{"n":9,"t":"Yanını eğip bükerek uğraşır ki, Allah yolundan saptırıversin. Böyle kişiye dünyada bir yüz karası öngörülmüştür. Ve kıyamet günü biz ona, o kasıp kavuran yangının azabını tattıracağız."},{"n":10,"t":"\"Al, işte bu, iki elinin önden gönderdiğidir. Şu bir gerçek ki, Allah, kullara asla zulmedici değildir.\""},{"n":11,"t":"İnsanlardan bazısı da Allah'a kıyıdan kıyıya ibadet eder. Kendisine bir hayır isabet ettiğinde, onunla tatmin bulup yatışır; kendisine bir fitne, bir deneme gelip çattığında yüzüstü geri dönüverir. Dünyada da kayba uğramıştır böylesi, âhirette de. Apaçık hüsranın ta kendisi işte budur."},{"n":12,"t":"Allah'ın berisinden, kendisine zarar veremeyecek, yarar sağlamayacak şeye dua/davet eder. Dönüşü olmayan sapıklığın ta kendisidir bu."},{"n":13,"t":"Zararı yararından daha yakın olan kişiye yalvarır/davet eder. Ne kötü bir destekçidir o, ne kötü bir efendidir!"},{"n":14,"t":"Allah, iman edip hayra ve barışa yönelik işler yapanları altlarından ırmaklar akan cennetlere koyacaktır. Allah, dilediğini yapar."},{"n":15,"t":"Kim Allah'ın dünyada ve âhirette kendisine yardım etmeyeceğini sanıyorsa; bir sebeple göğe uzansın, sonra öteki ilişkilerini kessin de bakıversin: Oyunu, öfkelendirdiği şeyleri gerçekten giderecek mi?\""},{"n":16,"t":"Biz onu, böylece açık-seçik ayetler halinde indirdik. Kuşkusuz, Allah, dilediğine/dileyene kılavuzluk eder."},{"n":17,"t":"İman edenler, Yahudiler, Sâbiîler, Hıristiyanlar, Mecusîler ve şirke sapanlar arasında Allah, kıyamet günü ayrım yapacaktır. Allah, her şey üzerine Şehîd'dir, tanıktır."},{"n":18,"t":"Görmedin mi göklerdeki kimseler, yerdeki kimseler, Güneş, Ay, yıldızlar, dağlar, ağaçlar, hayvanlar ve insanlardan birçoğu hep Allah'a secde ediyor. Birçoğunun da üzerine azap hak olmuştur. Allah'ın hakir kıldığına ikramda bulunan olmaz. Allah, dilediğini yapar."},{"n":19,"t":"İşte şu iki hasım, Rableri hakkında çekişip durmuşlardır. Sonuçta küfre sapanlar için ateşten giysiler biçilmiştir. Başlarının üstünden de kaynar su dökülmektedir."},{"n":20,"t":"Bu suyla, karınlarının içindekiler ve derileri eritilir."},{"n":21,"t":"Bunlar için bir de demirden kamçılar var."},{"n":22,"t":"Istırap yüzünden oradan her çıkmak istediklerinde, oraya geri döndürülürler: \"Tadın şu yangın azabını!\""},{"n":23,"t":"Allah, iman edip hayra ve barışa yönelik işler yapanları, altlarından ırmaklar akan cennetlere koyacaktır. Orada, altından bilezikler ve inciyle süsleneceklerdir. Ve orada giysileri ipektir."},{"n":24,"t":"Sözün güzeline ve tatlısına ulaştırılmışlardır; Hamîd olan Allah'ın yoluna ulaştırılmışlardır."},{"n":25,"t":"Küfre sapanlar, Allah'ın yolundan alıkoyarlar. Hem sürekli içinde kalan hem dışarıdan gelen tüm insanlar için oluşturduğumuz Mescid-i Haram'dan da geri çeviriyorlar. Kim orada zulmederek haktan sapmak isterse, biz ona acıklı bir azabı tattıracağız."},{"n":26,"t":"Bir zamanlar İbrahim için, o evin yerini, şöyle diyerek hazırlamıştık: Bana hiçbir şeyi ortak koşma, evimi; tavaf edenler, kıyamda duranlar, rükû-secde edenler için temizle."},{"n":27,"t":"İnsanlar içinde haccı ilan et ki, gerek yaya olarak gerekse derin vadilerden gelerek, yorgunluktan incelmiş binitler üzerinde sana ulaşsınlar."},{"n":28,"t":"Kendilerine ait bir takım yararlara tanık olsunlar. Kendilerine rızık olarak verdiği kurbanlık hayvanlar üzerinde belirli günlerde Allah'ın adını ansınlar. İşte bunlardan yiyin, sıkıntı içindeki fakiri de doyurun."},{"n":29,"t":"Sonra, kirlerini atsınlar, adaklarını yerine getirsinler, saldırılardan korunmuş/tarihî/yüce evi tavaf etsinler."},{"n":30,"t":"İşte böyle. Kim Allah'ın yasaklarına saygılı olursa bu, Rabbi katında kendisi için çok hayırlı olur. Karşınızda okunarak açıklananlar hariç, tüm hayvanlar size helal kılınmıştır. Artık putların pisliğinden, yalan sözden uzak durun."},{"n":31,"t":"Allah'a ortak koşmadan, hanîfler olarak... Allah'a ortak koşan kişi, gökten düşmüş de kendisini kuşlar kapışıyor veya rüzgâr onu uzak bir yere fırlatıp atıyor gibidir."},{"n":32,"t":"İşte böyle. Kim Allah'ın kutsallık nişanı yaptığı şeyleri yüceltirse bu yaptığı, gönüllerin takvasındandır."},{"n":33,"t":"Onlarda sizin için, belirli bir süreye kadar yararlar vardır. Sonunda onların varacakları yer saldırılardan korunmuş/tarihî/yüce evdir."},{"n":34,"t":"Biz her ümmet için bir kurbanlık hayvan kesme zamanı/kurbanlık hayvan kesme yeri/kurbanlık hayvan kesme tarzı belirledik ki, kendilerine rızık olarak verdiği kurbanlık hayvanların üstüne Allah'ın ismini ansınlar. Sizin tanrınız bir tek tanrıdır; o halde yalnız O'na teslim olun. Alçak gönüllü, saygılı kişileri muştula."},{"n":35,"t":"Onlar öyle insanlardır ki, Allah anıldığında kalpleri titrer; başlarına gelene sabrederler, namazı/duayı yerine getirirler, kendilerine verdiğimiz rızıklardan infak ederler."},{"n":36,"t":"Biz o büyükbaş hayvanları da sizin için Allah'ın kutsallık nişanları arasına koyduk. Sizin için onlarda hayır vardır. Onlar sıralanmış halde ayakları üzerine dururken, üzerlerine Allah'ın ismini anın. Yanları yere yaslandığı zaman da onlardan yiyin; isteyen yoksulu da istemeyen yoksulu da doyurun. Allah o hayvanları sizin hizmetinize verdi ki, şükredebilesiniz."},{"n":37,"t":"Onların etleri de kanları da Allah'a asla ulaşmaz; fakat sizin takvanız O'na ulaşır. Onları size bu şekilde boyun eğdirdir ki, sizi hidayete erdirdiği için Allah'ı yücelterek anasınız. Güzel düşünüp güzel davrananlara müjde ver."},{"n":38,"t":"Allah, iman edenleri savunur. Şu da kuşkusuz ki, Allah hiçbir haini, hiçbir nankörü sevmez."},{"n":39,"t":"Kendilerine savaş açılanlara savaşma izni verilmiştir. Çünkü onlar zulme uğratıldılar. Allah onlara yardıma elbette kadirdir."},{"n":40,"t":"Onlar sırf, \"Rabbimiz Allah'tır\" dedikleri için haksız yere yurtlarından çıkarıldılar. Eğer Allah'ın, insanların bir kısmını bir kısmıyla defetmesi olmasaydı, içlerinde Allah'ın adı çokça anılan manastırlar, kiliseler, havralar ve mescitler her halde yerle bir edilirdi. Allah, kendisine yardım edene elbette yardım eder. Allah elbette Kavî, Azîz'dir."},{"n":41,"t":"Onlar o kişilerdir ki eğer kendilerini yeryüzünde imkân ve güç sahibi yapsak namazı/duayı yerine getirirler, zekâtı verirler, iyiliğe özendirirler, kötülükten sakındırırlar. Tüm iş ve oluşlar Allah'a varır."},{"n":42,"t":"Eğer seni yalanlıyorlarsa bilesin ki, senden önce Nûh kavmi de Âd da, Semûd da yalanladı."},{"n":43,"t":"İbrahim'in kavmi de Lût'un kavmi de..."},{"n":44,"t":"Medyen halkı da (yalanlamıştı). Mûsâ da yalanlanmıştı. Ben o kâfirlere süre tanıdım, sonra hepsini yakalayıverdim. Tarafımdan reddediliş/ceza nasılmış, bir bak!"},{"n":45,"t":"Zalim olduğu için helâk ettiğimiz nice kent/medeniyet var ki, duvarları, tavanları üzerine çökmüş halde. Nice kullanılmaz halde bırakılmış su kuyusu, nice görkemli/süslü/bakımlı köşk var."},{"n":46,"t":"Yeryüzünde hiç dolaşmadılar mı ki, kalpleri olsun da onunla akıllarını çalıştırsınlar, kulakları olsun da onlarla duysunlar. Şu bir gerçek ki, kafadaki gözler kör olmaz ama göğüslerin içindeki gönüller körleşir."},{"n":47,"t":"Senden aceleyle azabı istiyorlar: Allah, vaadine asla ters düşmez. Şu da bir gerçek ki Rabbinin katındaki bir gün, sizin saymakta olduğunuzun bin yılı gibidir."},{"n":48,"t":"Nice kent/medeniyet var ki, zulme saptığı halde, ona süre tanıdım. Ama sonra kendisini yakalayıverdim. Dönüş yalnız banadır."},{"n":49,"t":"De ki: \"Ey insanlar, ben sizin için, açıklayıcı bir uyarıcıdan başkası değilim.\""},{"n":50,"t":"İman edip hayra ve barışa yönelik işler yapanlar için bir bağışlanma ve bol bir rızık vardır."},{"n":51,"t":"Ayetlerimizi işe yaramaz kılmak için gayret gösterenlere gelince, onlar cehennemin dostlarıdır."},{"n":52,"t":"Biz senden önce hiçbir resul ve nebi göndermedik ki, o bir şey tasarladığında/okuduğunda, şeytan onun düşünce ve dileği içine bir şey atmış olmasın. Ama Allah, şeytanın attığını siler, sonra kendi ayetlerini muhkemleştirir. Allah Alîm'dir, Hakîm'dir."},{"n":53,"t":"Bu, Allah'ın; şeytanın attığını, kalplerinde hastalık olanlara, gönülleri katılaşanlara bir fitne yapması içindir. Zalimler, geri dönülmez bir ayrılık ve kopuş içindedirler."},{"n":54,"t":"Kendilerine ilim verilenler onun, senin Rabbinden bir hak olduğunu bilsinler, ona inansınlar da kalpleri ona saygı duysun diye böyle yapılmıştır. Şu bir gerçek ki Allah Hâdî'dir, iman edenleri dosdoğru yola mutlaka ulaştıracaktır."},{"n":55,"t":"İnkâr edenler ise kıyamet ansızın başlarına patlayıncaya kadar, yahut kısır bir günün azabı kendilerine gelip çatıncaya kadar, o Kur'an'dan yana kuşku içinde olmaya devam edecekler."},{"n":56,"t":"O gün mülk ve yönetim Allah'ındır. Aralarında O, hüküm verecektir. İman edip hayra ve barışa yönelik işler yapanlar, nimetlerle dolu cennetlerde olacaklardır."},{"n":57,"t":"İnkâr edip ayetlerimizi yalanlayanlara gelince, onlar için aşağılayıcı bir azap öngörülmüştür."},{"n":58,"t":"Allah yolunda hicret edip sonra da öldürülen yahut ölenleri, Allah güzel bir rızıkla mutlaka rızıklandıracaktır. Alah, rızık verenlerin elbette ki en hayırlısıdır."},{"n":59,"t":"Onları, razı olacakları bir yere elbette sokacaktır. Allah elbette ki, Alîm'dir, Halîm'dir."},{"n":60,"t":"İşte böyle. Kim uğratıldığı cezanın aynısıyla ceza edip de zulüm ve saldırganlığa uğrarsa, Allah ona mutlaka yardım edecektir. Allah, elbette ki Afüvv'dür, Gafûr'dur."},{"n":61,"t":"İşte böyle. Allah geceyi gündüzün içine sokar, gündüzü de gecenin içine sokar. Allah Semî'dir, Basîr'dir."},{"n":62,"t":"Evet böyledir! Çünkü Allah Hakk'ın ta kendisidir. O'nun berisinden yalvarıp çağırdıkları ise bâtılın ta kendisidir. Hiç kuşkusuz, Allah Aliyy'dir, Kebîr'dir."},{"n":63,"t":"Görmedin mi, Allah gökten bir su indirdi de, onun sayesinde yer, yemyeşil hale geliyor. Allah Latîf'tir, Habîr'dir."},{"n":64,"t":"Göklerde ne var yerde ne varsa O'nundur. Allah, Ganî olanın da Hamîd olanın da ta kendisidir."},{"n":65,"t":"Görmedin mi, Allah yeryüzündekileri ve denizde O'nun emriyle akıp gidip gemileri sizin hizmetinize verdi. O'nun izni olmaksızın yerkürenin üstüne düşmemesi için göğü O tutuyor. Allah, insanlara karşı elbette Raûf, Rahîm'dir,"},{"n":66,"t":"Size hayat veren O'dur. Sonra sizi öldürüyor; sonra diriltecektir sizi. Gerçek olan şu ki, insan tam bir nankördür."},{"n":67,"t":"Her ümmet için biz, bir ibadet şekli/bir ibadet yeri belirledik; onlar, onu izlerler. Artık bu iş konusunda seninle çekişmesinler. Sen de Rabbine davet et/dua et. Sen, elbette ki şaşırtmadan yol aldıran bir kılavuzun ardındasın."},{"n":68,"t":"Seninle mücadele ederlerse şöyle de: \"Yapmakta olduklarınızı Allah daha iyi bilir.\""},{"n":69,"t":"Allah, tartışmakta olduğunuz konuda kıyamet günü aranızda hüküm verecektir."},{"n":70,"t":"Bilmedin mi ki; Allah gökte ne var, yerde ne varsa hepsini bilir. Bunların tümü bir kitaptadır. Bütün bunlar Allah için çok kolaydır."},{"n":71,"t":"Allah'tan ayrı olarak, hakkında O'nun hiçbir kanıt indirmediği şeye kulluk ediyorlar. Kendilerinin de onunla ilgili bir ilmi yoktur. O zalimlerin yardımcısı olmayacaktır."},{"n":72,"t":"Onlara açık-seçik ayetlerimiz okunduğunda, o küfre sapanların yüzlerinde bir hoşnutsuzluk/yadsıma görürsün. Kendilerine ayetlerimizi okuyanlara saldıracak olurlar. De ki: \"Size şu yaptığınızdan daha kötü bir şey haber vereyim mi: Ateş! Allah onu inkârcılara vaat etmiştir. Ne kötü dönüş yeridir o!\""},{"n":73,"t":"Ey insanlar! Size bir örnek verildi; onu dinleyin. O Allah'ın yanında yakarıp durduklarınız var ya, hepsi bir araya toplansalar bir sinek bile yaratamazlar. Sinek onlardan bir şey kapacak olsa, bunu bile ondan geri alamazlar. İsteyen de âciz, istenen de..."},{"n":74,"t":"Allah'ı, şanına yaraşır biçimde takdir edemediler. Allah elbette Kavî'dir, Azîz'dir."},{"n":75,"t":"Allah, meleklerden de resuller seçer, insanlardan da. Şüphesiz ki, Allah Semî' ve Basîr'dir."},{"n":76,"t":"Onların önden gönderdiklerini de bilir, arkaya bıraktıklarını da. İş ve oluşlar Allah'a döndürülür."},{"n":77,"t":"Ey iman edenler! Rükû edin, secde edin; Rabbinize ibadet edin, hayır işleyin ki kurtulabilesiniz."},{"n":78,"t":"Allah uğrunda O'na yaraşır bir gayretle didinin. O sizi seçmiş ve dinde size hiçbir güçlük çıkarmamıştır. Babanız İbrahim'in milletini esas alın. Allah sizi, önceden de şu Kitap'ta da \"Müslümanlar/Allah'a teslim olanlar\" diye adlandırdı ki, resul sizin üzerinize bir tanık olsun, siz de insanlar üzerine tanıklar olasınız. O halde namazı/duayı yerine getirin, zekâtı verin ve Allah'a sarılın. O'dur sizin Mevlâ'nız. Ne güzel Mevlâ'dır O, ne güzel yardımcıdır O!"}],[{"n":1,"t":"Hiç kuşku yok, kurtulmuştur müminler."},{"n":2,"t":"Namazlarında/dualarında huşû sahipleridir onlar."},{"n":3,"t":"Boş ve lüzumsuz sözden yüz çevirmişlerdir onlar."},{"n":4,"t":"Zekâtı vermek için faaliyettedir onlar."},{"n":5,"t":"Cinsiyet organlarını/ırzlarını koruyanlardır onlar."},{"n":6,"t":"Eşleri yahut akitleri aracılığıyla sahip bulundukları müstesnadır. Bu durumda kınanmış değillerdir onlar."},{"n":7,"t":"Kim bundan ötesini isterse, işte onlar, sınırı aşanlardır."},{"n":8,"t":"O müminler, emanetlerine, ahitlerine saygı duyup sahip çıkanlardır."},{"n":9,"t":"Namazlarını/dualarını korumaya devam ederler onlar."},{"n":10,"t":"İşte bunlardır mirasçı olanlar;"},{"n":11,"t":"Ki, Firdevs cennetine mirasçı olurlar, onda sürekli kalırlar."},{"n":12,"t":"Yemin olsun ki, biz insanı topraktan oluşan bir özden yarattık."},{"n":13,"t":"Sonra onu çok dayanaklı bir karargâhta bir damlacık yaptık."},{"n":14,"t":"Sonra o damlacığı bir embriyo halinde yarattık, sonra o embriyoyu bir et parçası halinde yarattık, sonra o et parçasını bir kemik halinde yarattık ve nihayet o kemiğe de bir et giydirdik. Sonra onu bir başka yaratılışta yeniden kurduk. Yaratıcıların en güzeli Allah'ın kudret ve sanatı ne yücedir!"},{"n":15,"t":"Sonra, siz bütün bunların ardından mutlaka öleceksiniz."},{"n":16,"t":"Sonra, siz kıyamet gününde yeniden diriltileceksiniz."},{"n":17,"t":"Yemin olsun, biz sizin üstünüzde yedi yol yarattık! Ve biz yaratılıştan/yaratılmışlardan gafil de değiliz."},{"n":18,"t":"Gökten bir kaderle/belli ölçüde bir su indirdik de onu yeryüzünde durdurduk. Elbette ki biz, onu gidermeye de gücü yetenleriz!"},{"n":19,"t":"Onunla size hurmalardan ve üzümlerden bahçeler yetiştirdik, onlarda sizin için birçok meyveler vardır; onlardan yiyorsunuz."},{"n":20,"t":"Ve bir ağaç da yetiştirdik ki, Tûr-i Sina'dan çıkar, yağlı olarak biter; yiyenlere katıktır."},{"n":21,"t":"Davarlarda da sizin için elbette bir ibret vardır! Onların karınlarındakilerden size içiriyoruz. Onlarda sizin için birçok yarar var. Onlardan yiyorsunuz da."},{"n":22,"t":"Hem onlar üzerinde hem de gemiler üzerinde taşınıyorsunuz."},{"n":23,"t":"Yemin olsun, Nûh'u toplumuna resul olarak gönderdik de o şöyle dedi: \"Ey toplumum! Allah'a kulluk/ibadet edin! O'ndan başka tanrınız yok sizin. Hâlâ sakınmayacak mısınız?\""},{"n":24,"t":"Toplumu içinden inkârcı kodaman grup şöyle dedi: \"Bu adam, sizin gibi bir insandan başka şey değil; size üstünlük taslamak istiyor. Eğer Allah dileseydi, melekler indirirdi. Biz ilk atalarımız arasında böyle bir şey duymadık.\""},{"n":25,"t":"\"Cinnet getirmiş bir adamdan başkası değildir o. Belli bir süreye kadar göz altında tutun onu.\""},{"n":26,"t":"Nûh şöyle yakardı: \"Rabbim, beni yalanlamaları karşısında yardım et bana!\""},{"n":27,"t":"Bunun üzerine biz, Nûh'a şöyle vahyettik: \"Gözlerimizin önünde ve vahyimize uygun olarak gemiyi yap. Emrimiz gelip tandır kaynayınca, ailenle birlikte her türden iki çifti gemiye sok. İçlerinden, haklarında daha önce hüküm verilmiş olanları dışta bırak. Zulmetmiş olanlar hakkında bana yakarıp durma. Onlar kesinlikle boğulacaklardır.\""},{"n":28,"t":"Sen, yanındakilerle birlikte geminin üzerine çıktığında şöyle de: \"Zalimler topluluğundan bizi kurtaran Allah'a hamt olsun!\""},{"n":29,"t":"Şunu da söyle: \"Rabbim, beni bereketli bir yere indir! Sen, konuk ağırlayanların en hayırlısısın.\""},{"n":30,"t":"Biz onları imtihan ediyor idiysek de bunda elbette ibretler vardır!"},{"n":31,"t":"Sonra onların ardından başka bir nesil oluşturduk."},{"n":32,"t":"Onlara da içlerinden şu yolda tebliğde bulunan bir resul gönderdik: Allah'a kulluk/ibadet edin. O'ndan başka tanrınız yok sizin. Hâlâ ürpermiyor musunuz?"},{"n":33,"t":"Toplumunun, dünya hayatında servet ve refaha ulaştırdığımız halde inkâra sapıp âhiretteki buluşmayı yalanlayan kodaman takımı şöyle dedi: \"Bu adam, sadece sizin gibi bir insan; yemekte olduğunuzdan yiyor, içmekte olduğunuzdan içiyor.\""},{"n":34,"t":"\"Kendiniz gibi bir insana itaat ederseniz, o takdirde mutlaka hüsrana uğrayanlar olursunuz.\""},{"n":35,"t":"\"Size, ölüp toprak ve kemik haline geldikten sonra tekrar meydana çıkarılacağınızı mı vaat ediyor?\""},{"n":36,"t":"\"Heyhat! Size vaat edilen o şey ne kadar uzak!\""},{"n":37,"t":"\"Hayat, şu dünya hayatımızdan başkası değildir. Ölürüz, yaşarız ama biz tekrar diriltilecek değiliz.\""},{"n":38,"t":"\"O, yalan düzüp Allah'a iftira eden bir adamdan başkası değil. Biz ona inanmıyoruz.\""},{"n":39,"t":"O peygamber şöyle yakardı: \"Rabbim, beni yalanlamaları karşısında yardım et bana!\""},{"n":40,"t":"Allah buyurdu: \"Biraz sonra kesinlikle pişman olacaklar.\""},{"n":41,"t":"Nihayet, o korkunç titreşimli ses onları tam bir biçimde yakaladı da hepsini sel süprüntüsü haline getirdik. Dönmeze gitsin o zalimler topluluğu!"},{"n":42,"t":"Sonra onların arkasından başka nesiller oluşturduk."},{"n":43,"t":"Hiçbir ümmet ne süresinden ileri geçebilir ne de geri kalır."},{"n":44,"t":"Sonra, resullerimizi art arda gönderdik. Hangi ümmete resulü geldiyse onu yalanladılar. Biz de onları birbiri ardınca yuvarladık ve hepsini birer efsane yaptık. Dönmeze gitsin iman etmeyen bir topluluk!"},{"n":45,"t":"Sonra, Mûsa ile kardeşi Hârun'u mucizelerimizle, açık bir kanıtla gönderdik;"},{"n":46,"t":"Firavun'a ve kodamanlarına. Ancak kibre saptılar, çünkü kendilerini büyük gören bir topluluktu onlar."},{"n":47,"t":"Şöyle dediler: \"Kendilerine bağlı toplum bize kulluk-kölelik ederken, biz kalkıp bizim gibi iki insan olan şu adamlara mı inanacağız?\""},{"n":48,"t":"İkisini de yalanladılar, böylece helâk edilenler arasına katıldılar."},{"n":49,"t":"Yemin olsun, Mûsa'ya o Kitap'ı vermiştik ki, hidayete erebilsinler."},{"n":50,"t":"Meryem'in oğluyla annesini birer ayet kıldık ve onları oturmaya uygun pınarlı bir tepeye yerleştirdik."},{"n":51,"t":"Ey resuller! Temiz ve helal olanlardan yeyin ve barışa/hayra yönelik iş yapın! Şüphesiz ben, yapmakta olduklarınızı iyice bilmekteyim."},{"n":52,"t":"İşte sizin bu ümmetiniz bir tek ümmettir. Ve ben de sizin Rabbinizim; o halde benden sakının!"},{"n":53,"t":"Fakat onlar işlerini aralarında parçalayıp çeşitli zübürlere/kutsallaştırmış hizip kitaplarına ayırdılar. Her hizip, yalnız kendi yanındakiyle sevinip övünmektedir."},{"n":54,"t":"Artık sen onları bir süreye kadar kendi gafletleri içinde bırak."},{"n":55,"t":"Sanıyorlar mı ki, kendilerine verdiğimiz mal ve oğullarla güçlendiriyoruz onları,"},{"n":56,"t":"Ve iyiliklerine koşuyoruz. Hayır, farkında olmuyorlar."},{"n":57,"t":"Onlar ki, Rablerine saygıdan titrerler,"},{"n":58,"t":"Onlar ki, Rablerinin ayetlerine iman ederler,"},{"n":59,"t":"Onlar ki, Rablerine ortak koşmazlar,"},{"n":60,"t":"Onlar ki, verdiklerini, Rablerine dönecekleri için kalpleri ürpererek verirler;"},{"n":61,"t":"İşte bunlar, hayırlarda yarışırlar. Ve hayırlarda önde gidenler de onlardır."},{"n":62,"t":"Biz, hiçbir benliğe gücünün yeteceğinden daha azını yüklemenin dışında bir teklifte bulunmayız. Bizim katımızda, hakkı söyleyen bir kitap vardır. Onlara haksızlık edilmez."},{"n":63,"t":"Fakat onların kalpleri bundan gaflet içindedir. Onların bundan başka da işleri vardır ki, hep o işler için çalışmaktadırlar."},{"n":64,"t":"Sonunda, servet ve refahla şımarmışlarını azapla yakaladığımızda, hemen bağırıp dövünmeye başlarlar."},{"n":65,"t":"\"Bağırıp dövünmeyin bugün, bizim karşımızda kimseden yardım göremezsiniz.\""},{"n":66,"t":"\"Ayetlerimiz size okunuyordu da siz ökçeleriniz üzerine gerisin geri dönüyordunuz.\""},{"n":67,"t":"\"Ona karşı büyüklük taslayarak, gece boyunca hezeyanlar savuruyordunuz.\""},{"n":68,"t":"Sözü gereğince düşünmediler de ondan mı, yoksa kendilerine ilk atalarına gelmeyen bir şey geldi diye mi?"},{"n":69,"t":"Yoksa resullerini tanımadılar da bu yüzden mi onu inkâr ediyorlar?"},{"n":70,"t":"Yoksa, \"Onda bir cinnet mi var\" diyorlar! Hayır, o kendilerine hakkı getirdi ama onların çoğu haktan tiksinen kişilerdir."},{"n":71,"t":"Eğer hak onların keyiflerine uysaydı, gökler de yer de bunların içindekiler de kesinlikle fesada uğrardı. Hayır, biz onlara zikirlerini/Kur'anlarını getirdik ama onlar zikirlerinden/Kur'anlarından yüz çeviriyorlar."},{"n":72,"t":"Yoksa onlardan bir vergi mi istiyorsun? Rabbinin vereceği daha hayırlıdır. Rızık verenlerin en hayırlısıdır O."},{"n":73,"t":"Şu bir gerçek ki, sen onları dosdoğru bir yola çağırıyorsun."},{"n":74,"t":"Ama âhirete inanmayanlar, o yoldan hep yan çiziyorlar."},{"n":75,"t":"Eğer biz onlara acıyıp da üstlerindeki sıkıntıyı kaldırsaydık, azgınlıkları içinde sersem sersem bocalamaya devam edeceklerdi."},{"n":76,"t":"Yemin olsun, biz onları azapla yakaladık. Ama yine de Rablerine boyun eğmediler. Sığınıp yakarmıyorlar."},{"n":77,"t":"Nihayet, üzerlerine şiddetli bir azabın kapasını açtığımızda hemencecik ümitsizliğe düşüverecekler."},{"n":78,"t":"Allah odur ki; sizin için işitme gücü, gözler ve gönüller oluşturdu. Ne kadar da az şükrediyorsunuz!"},{"n":79,"t":"Sizi yeryüzünde yaratıp yayan da O'dur. O'nun huzurunda haşredileceksiniz."},{"n":80,"t":"O hayat veriyor, O öldürüyor. Gece ile gündüzün birbiri ardınca gelişi O'nun için. Hâlâ aklınızı kullanmayacak mısınız?"},{"n":81,"t":"İşin doğrusu şu: Onlar da öncekilerin söylediği gibi söylediler."},{"n":82,"t":"Dediler ki: \"Ölüp, toprak ve kemik haline geldiğimiz zaman mı, gerçekten o zaman mı diriltileceğiz?\""},{"n":83,"t":"\"Yemin olsun, biz de bizden önce atalarımız da bununla tehdit edildik. Öncekilerin masallarından başka bir şey değil bu!\""},{"n":84,"t":"De ki: \"Eğer biliyorsanız, yeryüzü ve içindekiler kimindir?\""},{"n":85,"t":"\"Allah'ındır!\" diyecekler. De ki: \"Hâlâ düşünüp ibret almıyor musunuz?\""},{"n":86,"t":"Sor: \"Yedi göklerin Rabbi ve o büyük arşın Rabbi kimdir?\""},{"n":87,"t":"\"Allah'tır!\" diyecekler. De ki: \"Hâlâ benden sakınmıyor musunuz?\""},{"n":88,"t":"Şunu da sor: \"Eğer biliyorsanız söyleyin. Kimdir o, her şeyin melekûtu/aslı-esası elinde olan? O koruyup gözeten ama korunup gözetilmeyen?\""},{"n":89,"t":"\"Allah'tır!\" diyecekler. De ki: \"Nasıl oluyor da büyüleniyorsunuz?\""},{"n":90,"t":"Hayır, hayır! Biz onlara hakkı getirdik ama onlar tam anlamıyla yalancıdırlar."},{"n":91,"t":"Allah hiçbir çocuk edinmemiştir. O'nunla beraber herhangi bir ilah da yoktur. Eğer böyle olsaydı, her ilah kendi yarattığını yanına alır götürürdü ve mutlaka biri ötekine üstün gelmeye çalışırdı. Şanı yücedir Allah'ın onların nitelendirmelerinden!"},{"n":92,"t":"Gözle görülmeyeni de görüleni de bilendir O. Uzaktır onların ortak koştuklarından."},{"n":93,"t":"De ki: \"Rabbim, tehdit edildikleri şeyi bana mutlaka göstereceksin."},{"n":94,"t":"Beni o zalimler topluluğunun içinde tutma Rabbim!\""},{"n":95,"t":"Biz, onları tehdit ettiğimiz şeyi sana göstermeye elbette kadiriz."},{"n":96,"t":"En güzel olan neyse onunla sav kötülüğü. Onların nasıl nitelendirme yaptıklarını biz daha iyi biliriz."},{"n":97,"t":"Ve de ki: \"Rabbim, şeytanların dürtüklemelerinden sana sığınırım!\""},{"n":98,"t":"\"Onların, başıma üşüşmelerinden de sana sığınırım Rabbim!\""},{"n":99,"t":"Sonunda onlardan birine ölüm geldiğinde şöyle der: \"Rabbim, beni geri döndürün;"},{"n":100,"t":"Döndürün ki, o arkada bıraktığım yerde iyi bir iş yapayım.\" Hayır, bir kelime ki bu, o söyler onu. Ötelerinde, dirilecekleri güne kadar bir berzah vardır."},{"n":101,"t":"Sûra üfürüldüğünde, aralarında artık soy-sop/şuna-buna mensup olmalar söz konusu edilemez. Birbirlerini soruşturamazlar da."},{"n":102,"t":"Artık kimin tartıları ağır gelirse onlar kurtulmuş olacaklardır."},{"n":103,"t":"Tartıları hafif gelenler ise kendilerini kayba uğratanlar, uzun süre cehennemde kalanlar olacaklardır."},{"n":104,"t":"Ateş, yüzlerini yalar. Ve onlar da içinde sırıtıp kalacaklar."},{"n":105,"t":"\"Ayetlerim size okunmadı mı?\" Ve siz onları yalanlamıyor muydunuz?\""},{"n":106,"t":"Derler ki: \"Rabbimiz, bahtsızlığımız bize baskın çıktı. Sapıp gitmiş bir topluluk olduk biz.\""},{"n":107,"t":"\"Rabbimiz, çıkar bizi oradan. Eğer bir daha aynısını yaparsak, gerçekten zalimler olacağız.\""},{"n":108,"t":"Buyurur: \"Yıkılıp gidin oraya, konuşmayın benimle!\""},{"n":109,"t":"Kullarımdan bir zümre \"Rabbimiz, inandık; affet bizi, acı bize, sen merhametlilerin en hayırlısısın\" diyorken,"},{"n":110,"t":"Siz onları alaya aldınız. Öyle ki, zikrimi/Kur'anımı size unutturdular. Siz onlara hep gülüyordunuz."},{"n":111,"t":"Bugün onlara ben, sabretmiş olmalarının karşılığını verdim. Başarıya erip kurtulanlar, onlardır."},{"n":112,"t":"Buyurur: \"Yeryüzünde yıllar sayısıyla ne kadar kaldınız?\""},{"n":113,"t":"Derler: \"Bir gün yahut günün bir kısmı kadar; sayanlara sor.\""},{"n":114,"t":"Buyurdu: \"Sadece birazcık kaldınız. Keşke biliyor olsaydınız.\""},{"n":115,"t":"\"Sizi, boş yere yarattığımızı ve bize döndürülmeyeceğinizi mi sandınız?\""},{"n":116,"t":"Yücelerden yücedir, o hak padişah olan Allah! İlah yok O'ndan başka. O şanlı arşın Rabbidir O!"},{"n":117,"t":"Kim Allah'ın yanında, hakkında hiçbir kanıt olmayan bir başka ilaha yakarır/davet ederse, onun hesabı rabbi katındadır. Hiç kuşkusuz, küfre sapanlar iflah etmezler."},{"n":118,"t":"Şöyle yakar: \"Rabbim! Affet, merhamet et! Sen merhametlilerin en hayırlısısın!\""}],[{"n":1,"t":"Bir suredir, indirdik onu; farz kıldık onu... Ve içinde açık-seçik ayetler indirdik ki, düşünüp ders alabilesiniz."},{"n":2,"t":"Zina eden kadınla zina eden erkek... Yüz vuruş vurun herbirinin ciltlerine... Allah'a ve âhiret gününe inanıyorsanız, Allah'ın dini konusunda bunlara acıma duygusu sizi yakalamasın. Müminlerden bir grup da bunların cezalarına tanık olsun."},{"n":3,"t":"Zina eden erkeği zina eden bir kadın veya putperest bir kadından başkası nikâhlamaz. Zina eden kadına gelince, onu da zina eden bir erkek veya putperest bir erkekten başkası nikâhlamaz. Müminlere bu, haram kılınmıştır."},{"n":4,"t":"İffetli kadınlara iftira atıp da dört tanık getirmeyenlere gelince, onlara hemen seksen vuruş vurun. Ve onların tanıklıklarını asla kabul etmeyin. Onlar, sapmışların ta kendileridir."},{"n":5,"t":"Bu suçtan sonra tövbe edip iyi hal sergileyenler müstesna. Şu bir gerçek ki, Allah Gafûr'dur, Rahîm'dir."},{"n":6,"t":"Kendi eşlerine bir zina isnat edip de kendilerinden başka tanıkları olmayanların herbirinin tanıklığı, kendisinin kesinlikle doğru sözlülerden olduğu hususunda Allah'a yeminden ibaret dört kez tanıklık ikrarıdır."},{"n":7,"t":"Beşincide, eğer yalancılardansa, Allah'ın laneti üzerine olsun diye söz söyler."},{"n":8,"t":"İtham edilen eşin, itham eden kocanın kesinlikle yalancılardan olduğuna ilişkin, Allah adına dört kez yemin şeklindeki tanıklığı, ondan cezayı düşürür."},{"n":9,"t":"Bu durumda kadının beşinci sözü, suçlayan erkek doğru söyleyenlerdense, \"Allah'ın gazabının kendisi üzerine olması\"nı söylemekten ibarettir."},{"n":10,"t":"Allah'ın lütuf ve rahmeti üzerinizde olmasaydı neylerdiniz! Ve hiç kuşku yok, Allah Tevvâb'dır, Hakîm'dir."},{"n":11,"t":"O ifki/yalan haberi/iftirayı getirenler, içinizden bir gruptur. Onu sizin için şer sanmayın. Aksine, o, sizin için bir hayırdır. Onlardan her kişiye o günahtan kazandığı vardır. Onların, günahın büyüğünü yönetenine de büyük bir azap vardır."},{"n":12,"t":"Onu işittiğinizde, erkek ve kadın müminlerin birbirleri için iyi zanda bulunup \"Bu apaçık bir iftiradır\" demeleri gerekmez miydi?\""},{"n":13,"t":"Ona dört tanık getirselerdi ya! Mademki, tanıkları getiremediler, o halde, Allah katında onlar yalancılardır."},{"n":14,"t":"Eğer dünya ve âhirette Allah'ın lütfu üzerinizde olmasaydı, içine daldığınız o yaygarada size mutlaka büyük bir azap dokunurdu."},{"n":15,"t":"O zaman siz, onu dillerinizle birbirinize yetiştiriyordunuz ve ağızlarınızla, hakkında hiçbir bilginiz olmayan şeyi söylüyor, üstelik bunu önemsiz sanıyordunuz. Oysaki Allah katında o, çok büyük bir günahtı."},{"n":16,"t":"Onu duyduğunuzda, \"Bu konuda söz söylememiz bize yakışmaz; hâşâ, bu büyük bir iftiradır\" demeniz gerekmez miydi?"},{"n":17,"t":"Eğer iman sahipleri iseniz, Allah sizi böyle bir şeye bir daha asla dönmemeniz hususunda uyarıyor."},{"n":18,"t":"Allah size ayetleri iyice açıklıyor. Allah Alîm'dir, Hakîm'dir."},{"n":19,"t":"İman edenler içinde edepsizliğin yayılmasını arzu edenler var ya, onlar için dünyada da âhirette de korkunç bir azap öngörülmüştür. Allah bilir ama siz bilmezsiniz."},{"n":20,"t":"Ya Allah'ın lütfu ve rahmeti üzerinizde olmasaydı! Allah Raûf'tur, Rahîm'dir."},{"n":21,"t":"Ey iman edenler! Şeytanın adımlarını izlemeyin. Kim şeytanın adımlarını izlerse, şeytan ona iğrençlikleri ve kötülüğü emreder. Allah'ın lütuf ve rahmeti üzerinizde olmasaydı, içinizden tek kişi bile asla temize çıkamazdı. Ama Allah dilediğini artırıp temizliyor. Allah her şeyi işitiyor, her şeyi biliyor."},{"n":22,"t":"Sizin lütuf ve imkân sahibi olanlarınız; akrabaya, çaresizlere, Allah yolunda hicret edenlere birşey vermemeye yemin etmesinler, affetsinler, hoş görsünler. Allah'ın sizi affetmesini istemez misiniz? Allah Gafûr'dur, Rahîm'dir."},{"n":23,"t":"O bir şeyden habersiz iffetli mümin kadınlara iftira atanlar, dünyada da âhirette de lanete çarptırılmışlardır. Büyük bir azap vardır onlar için."},{"n":24,"t":"Gün gelecek onların kendi dilleri, kendi elleri, kendi ayakları, yapıp ettikleri işler hakkında kendi aleyhlerine tanıklık edecektir."},{"n":25,"t":"O gün Allah, onlara hak ettikleri cezayı tam verecek ve Allah'ın apaçık Hak olduğunu bilecekler."},{"n":26,"t":"Murdar karılar murdar erkeklere, murdar erkekler de murdar karılara... Temiz kadınlar temiz erkeklere, temiz erkekler de temiz kadınlara... Bunlar, ötekilerin söylediklerinden arınmışlardır. Bunlar için bir bağışlanma ve bol bir rızık vardır."},{"n":27,"t":"Ey iman edenler! Kendi evleriniz dışındaki evlere, sahipleriyle kaynaşıp izin almadan, bir de ev sakinlerine selam vermeden girmeyin! Düşünüp taşınmanızı sağlamada bu sizin için daha hayırlıdır."},{"n":28,"t":"Eğer orada kimseyi bulamazsanız, size izin verilinceye kadar oraya girmeyin. Eğer size \"Geri dönün!\" denirse, dönün; bu sizin için daha iyi ve temizdir. Allah, yaptıklarınızı çok iyi biliyor."},{"n":29,"t":"Oturanı bulunmayan ve içinde size ait eşya olan evlere girmenizde bir sakınca yoktur. Allah, sizin açıkladıklarınızı da sakladıklarınızı da bilir."},{"n":30,"t":"Mümin erkeklere söyle: Bakışlarını yere indirsinler. Cinsel organlarını/ırzlarını korusunlar. Bu onlar için daha arındırıcıdır. Kuşkusuz, Allah, yapmakta olduklarınızdan haberdardır."},{"n":31,"t":"Mümin kadınlara da söyle: Bakışlarını yere indirsinler. Cinsel organlarını/ırzlarını korusunlar. Süslerini/zînetlerini, görünen kısımlar müstesna, açmasınlar. Örtülerini/başörtülerini göğüs yırtmaçlarının üzerine vursunlar. Süslerini şu kişilerden başkasına göstermesinler: Kocaları yahut babaları yahut kocalarının babaları yahut oğulları yahut kocalarının oğulları yahut kardeşleri yahut erkek kardeşlerinin oğulları yahut kız kardeşlerinin oğulları yahut kendi kadınları yahut ellerinin altında bulunanlar yahut ihtiyaç içinde olmayan erkeklerden kendilerinin hizmetinde bulunanlar yahut kadınların kaygı duyulacak yerlerini henüz anlayacak yaşa gelmemiş çocuklar. Süslerinden, gizlemiş olduklarının bilinmesi için ayaklarını yere vurmasınlar. Ey müminler, Allah'a topluca tövbe edin ki kurtuluşa erebilesiniz!"},{"n":32,"t":"İçinizden bekârları/dulları, bir de erkek hizmetçilerinizden ve halayıklarınızdan durumu uygun olanları evlendirin. Eğer yoksul iseler, Allah onları lütfundan zenginleştirir. Allah Vâsi'dir, Alîm'dir."},{"n":33,"t":"Evlenmeye imkân bulamayanlar, Allah kendilerini lütfundan zenginleştirinceye kadar iffetlerini korusunlar. Ellerinizin altında bulunanlardan hürriyetini satın almak isteyenlerin, eğer kendilerinde bir hayır görürseniz, yazılı anlaşmasını yapın. Ve Allah'ın size verdiği malından onlara verin. İffetli kalmak isteyen cariyerinizi, iğreti dünya hayatının menfaatini elde etmek için fuhşa zorlamayın. Kim onları zorlarsa, hiç şüphesiz Allah, zorlanmalarından sonra onları bağışlar, merhamet eder."},{"n":34,"t":"Yemin olsun ki, size, gerçeği açık-seçik anlatan ayetler, sizden önce gelip geçmiş olanlardan örnekler, korunanlar için de bir öğüt indirdik."},{"n":35,"t":"Allah, göklerin ve yerin Nur'udur. Onun nurunun örneği, içinde çerağ bulunan bir kandile benzer. Kandil, bir sırça içerisindedir. Sırça, inciden bir yıldız gibidir ki, doğuya da batıya da nispeti olmayan bereketli bir zeytin ağacından yakılır. Bu ağacın yağı, neredeyse ateş dokunmasa bile ışık saçar. Nur üzerine nurdur o. Allah, dilediğini kendi nuruna kılavuzlar. Allah, insanlara örnekler verir. Allah herşeyi bilmektedir."},{"n":36,"t":"Kandil, Allah'ın yükseltilmesine ve içinde adının anılmasına izin verdiği evlerdedir. Orada sabah-akşam O'nu tespih eder."},{"n":37,"t":"Öyle erler vardır ki, bir ticaret de bir alış-veriş de onları Allah'ın zikrinden/Kur'an'ından, namazı/duayı yerine getirmekten, zekât vermekten alıkoyamaz. Onlar, kalplerle gözlerin döneceği/yer değiştireceği günden korkarlar."},{"n":38,"t":"Ki Allah kendilerine, yapıp işlediklerinin en güzelini versin ve lütfundan onlara artışlar sağlasın. Allah dilediğini hesapsızca rızıklandırır."},{"n":39,"t":"Küfre sapanlara gelince, onların amelleri çöldeki serap gibidir ki, susuzluktan bunalan onu su sanır. Ama ona yaklaşınca hiçbir şey bulamaz; yanında Allah'ı bulur; O da onun hesabını eksiksiz bir biçimde görür. Allah, hesabı çok çabuk görendir."},{"n":40,"t":"Engin denizdeki karanlıklara da benzerlik var. Üst üste dalgaların kapladığı bir deniz. Daha üstünde de bulutlar var. Birbiri üstüne karanlıklar... Elini çıkarsa göremeyecek halde. Allah'ın ışık vermediği kişiye hiçbir ışık bulunamaz."},{"n":41,"t":"Görmedin mi, göklerdeki ve yerdeki şuurlular da bölük bölük olmuş kuşlar da Allah'ı tespih etmektedir. Her biri kendine özgü duasını, kendine özgü tespihini bilmiştir. Allah, onların yapmakta olduklarını çok iyi bilmektedir."},{"n":42,"t":"Göklerin ve yerin mülkü/yönetimi Allah'ındır. Dönüş Allah'adır."},{"n":43,"t":"Görmedin mi, Allah, bulutları sürüyor, sonra onları kaynaştırıp iç içe sokuyor, sonra onları birbiri üstüne yığıyor. Nihayet, onların arasından yağmurun çıktığını görüyorsun. Gökten, ondaki dağlardan bir dolu indiriyor da onunla dilediğini çarpıyor, dilediğinden de onu yan geçiriyor. Onun şimşeğinin parıltısı, neredeyse gözleri alıp götürecek."},{"n":44,"t":"Allah, gece ile gündüzü evirip çeviriyor. Gözleri olanlar için bunda elbette bir ibret vardır."},{"n":45,"t":"Allah, tüm canlıları sudan yarattı. Onlardan kimileri karnı üzerinde yürür, kimileri iki ayak üstünde yürür, kimileri de dört ayak üstünde... Allah dilediğini yaratıyor, Allah her şeye kadirdir."},{"n":46,"t":"Yemin olsun, biz açık-seçik bilgiler veren ayetler indirdik. Allah, dilediğini/dileyeni dosdoğru yola iletiyor."},{"n":47,"t":"\"Allah'a ve o resule inandık, boyun eğdik.\" diyorlar, sonra da içlerinden bir fırka bunun hemen ardından yüz çeviriyor. Bunlar, inanmış insanlar değiller."},{"n":48,"t":"Allah'a ve aralarında hüküm versin diye elçiye çağrıldıklarında, içlerinden bir fırka hemen yüz çevirenler oluveriyor."},{"n":49,"t":"Eğer gerçek, kendi lehlerine olursa boyun bükerek ona gelirler."},{"n":50,"t":"Kalplerinde maraz mı var bunların, yoksa kuşkuya mı düştüler, yoksa Allah'ın ve resulünün kendilerine haksızlık yapacağından mı korkuyorlar? Hayır, hayır! Bunlar zalimlerin ta kendileri..."},{"n":51,"t":"Allah'a ve aralarında hüküm vermek üzere O'nun resulüne çağrıldıklarında, müminlerin sözleri sadece şunu söylemeleridir: \"İşittik, itaat ettik.\" İşte bunlardır kurtuluşa erenler."},{"n":52,"t":"Allah'a ve O'nun resulüne itaat eden, Allah'a saygı duyan ve O'ndan korkan kişiler, zafere ulaşanların ta kendileridir."},{"n":53,"t":"Yeminlerinin olanca gücüyle Allah'a ant içtiler ki, sen onlara emredersen mutlaka savaşa çıkacaklar. De ki: \"Ant içmeyin! Örfe uygun bir itaat yeterli! Allah, yapmakta olduklarınızdan haberdardır.\""},{"n":54,"t":"De ki: \"Allah'a da itaat edin, resule de. Eğer yüz çevirirseniz/yüz çevirirlerse, onun görevi ona yükletilen, sizin göreviniz de size yükletilendir. Eğer ona itaat ederseniz yolu bulursunuz. Resule düşen, açık bir tebliğden başkası değildir.\""},{"n":55,"t":"Allah; sizin, iman edip hayra ve barışa yönelik iyilikler yapanlarınıza şu vaatte bulunmuştur: Onlardan öncekileri halef kıldığı gibi onları da yeryüzünde mutlaka halef kılacak. Onlar için beğenip seçtiği dinlerini yine onlar için güç kaynağı yapacak, onları korkularının arkasından mutlaka güvene ulaştıracak. Bana kulluk/ibadet edecekler, hiçbir şeyi bana ortak koşmayacaklar. Bundan sonra nankörlük edenlerse, yoldan sapanların ta kendileridir."},{"n":56,"t":"Namazı/duayı yerine getirin, zekâtı verin, resule itaat edin ki, rahmete erdirilesiniz."},{"n":57,"t":"Sakın o küfre sapanların, yeryüzünde âciz bırakıcı güçler olduklarını zannetme. Varacakları yer ateştir onların. Ne kötü dönüş yeridir o, ne kötü!"},{"n":58,"t":"Ey iman edenler! Ellerinizin altında bulunanlarla, ergenlik yaşına gelmemiş olanlarınız sizden üç vakitte izin istesin: Sabah namazından/duasından önce, öğlen vaktinde elbiselerinizi çıkardığınızda, gün battıktan sonra yerine getirilen namazdan/duadan sonra... Kaygılanacağınız üç vakittir bunlar. Bunlar dışında size de onlara da bir günah yoktur. Aranızda dolaşırlar, birbirinize bakabilirsiniz. Allah, ayetleri size işte böyle açıklıyor. Allah Alîm'dir, Hakîm'dir."},{"n":59,"t":"Çocuklarınız ergenlik çağına ulaştığında, kendilerinden öncekilerin izin istediği gibi izin istesinler. Allah size ayetleri işte böyle açıklıyor. Allah her şeyi bilir, hikmeti sınırsızdır."},{"n":60,"t":"Artık nikâh arzuları kalmamış, hayızdan ve evlattan kesilen kadınların, süslerini göstermek için ortalıkta dolaşmamaları şartıyla dış giysilerini bırakmalarında kendileri için bir günah yoktur. Ama sakınmak için titiz davranmaları, onlar için daha hayırlıdır. Allah, her şeyi işitir, her şeyi bilir."},{"n":61,"t":"Köre güçlük yoktur; topala güçlük yoktur, hastaya güçlük yoktur. Sizin için de gerek kendi evlerinizden gerekse şu kişilerin evlerinden yemek yemenizde bir sakınca yoktur: Babalarınızın evleri yahut annelerinizin evleri yahut erkek kardeşlerinizin evleri yahut kız kardeşlerinizin evleri yahut amcalarınızın evleri yahut halalarınızın evleri yahut teyzelerinizin evleri yahut anahtarı size teslim edilmiş olan evler yahut arkadaşlarınızın evleri. Hep birlikte yahut ayrı ayrı yemenizde sizin için hiçbir sakınca yoktur. Evlere girdiğinizde, Allah katından bir esenlik, bir bereketlilik, bir temizlik dileği olarak kendinize de selam verin. Allah size ayetleri işte böyle ayan-beyan bildiriyor ki, aklınızı çalıştırabilesiniz."},{"n":62,"t":"Müminler o insanlardır ki, Allah'a ve O'nun resulüne inanırlar. Resulle beraber, ortaklaşa bir iş üzerinde bulundukları zaman, ondan izin almadan çekip gitmezler. O senden izin isteyenler var ya, onlar Allah'a ve O'nun resulüne iman edenlerdir. Bazı uğraşları için senden izin istediklerinde, onlardan dilediğine izin ver ve kendileri için af dile. Allah Gafûr'dur, Rahîm'dir."},{"n":63,"t":"Aranızda peygamberi çağırmayı, sizin birbirinizi çağırmanıza eş tutmayın. Allah sizin, birbirini siper ederek sıvışıp gidenlerinizi bilir. Resulün emrine aykırı davrananlar, kendilerine bir fitnenin gelip çatmasından yahut acıklı bir azabın yakalarına yapışmasından çekinsinler."},{"n":64,"t":"Gözünüzü açın! Göklerde ne var, yerde ne varsa yalnız Allah'ındır. O sizin ne hal üzere olduğunuzu bilir. Bir gün O'na döndürülecekler de O onlara, yapıp ettiklerini haber verecektir. Allah her şeyi iyice bilmektedir."}],[{"n":1,"t":"Şanı yücedir o kudretin ki, hakla bâtılı ayıran o Furkan'ı, bütün âlemler için bir uyarıcı olsun diye kuluna indirdi."},{"n":2,"t":"Göklerin ve yerin mülk ve saltanatı yalnız O'nundur. Çocuk edinmemiştir O. Mülk ve saltanatında ortak yoktur O'na. Herşeyi yaratmış ve herşeye bir ölçü ve oluş tarzı takdir etmiştir."},{"n":3,"t":"Böyleyken O'nun dışında bir takım ilahlar edindiler. Hiçbir şey yaratamaz bunlar. Kendileri yaratılmışlardır zaten... Kendi benlikleri için bile ne bir zarara güç yetirebilirler ne bir yarara. Ne bir ölüme güçleri yeter ne bir dirime ne de kabirden çıkarıp hesap sormaya."},{"n":4,"t":"Küfre batanlar dediler ki: \"Bu, onun uydurduğu bir düzmeceden başka şey değildir. Ve bu düzmecede ona, başka bir topluluk da yardım etmiştir.\" Yemin olsun ki, bunu söyleyenler bir zulüm, günah ve iftira sergilemişlerdir."},{"n":5,"t":"Dediler ki: \"Öncekilerin masallarıdır bu. Birilerine yazdırdı onu. O ona sabah-akşam birileri tarafından yazdırılıyor.\""},{"n":6,"t":"Şöyle söyle: \"Onu göklerde ve yerdeki sırrı bilen indirmiştir. Kuşkusuz O, Gafûr'dur, Rahîm'dir.\""},{"n":7,"t":"Şunu da söylemişlerdir: \"Ne biçim resuldür bu; yemek yiyor, sokaklarda yürüyor. Üzerine bir melek indirilmeli, beraberinde özel bir uyarıcı olmalı değil miydi?\""},{"n":8,"t":"\"Yahut ona bir hazine gönderilmeli, yahut ürününden yediği bir bahçesi olmalı değil miydi?\" O zalimler şunu da söylediler: \"Sizler büyülenmiş bir adamdan başkasının ardı sıra gitmiyorsunuz.\""},{"n":9,"t":"Bak da gör! Nasıl da örnekler sunuyorlar sana. Sapıttılar, artık bir daha yol bulamazlar."},{"n":10,"t":"Şanı yücedir o kudretin ki, dilerse sana ondan daha hayırlısını, altından nehirler akan bahçeleri verir ve senin için köşkler de yapar."},{"n":11,"t":"İş onların söyledikleri gibi değil. Onlar o kıyamet saatini yalanladılar. Ve biz, kıyamet saatini yalanlayanlara alevli bir ateş hazırlamışızdır."},{"n":12,"t":"O, onları uzak bir yerden gördüğünde, onlar onun kaynayan öfkesini ve uğultusunu işitirler."},{"n":13,"t":"Elleri boyunlarına bağlı olarak onun dar bir yerine atıldıklarında, orada haykırırlar: \"Nerdesin ey ölüm!\""},{"n":14,"t":"Bugün bir ölüm çağırmayın, birçok ölümü davet edin."},{"n":15,"t":"De ki: \"Bu mu daha iyi, yoksa korunanlara vaat edilen o sürekli cennet mi? O cennet de bu korunanların ödülü ve dönüş yeridir.\""},{"n":16,"t":"Onlar için orada, diledikleri herşey sürekli vardır. Bu, Rabbin üzerinde sorumluluğu üstlenilen bir vaattir."},{"n":17,"t":"Onları ve Allah dışındaki taptıklarını haşredeceği gün şöyle sorar: \"Şu kullarımı siz mi saptırdınız yoksa onlar mı yoldan çıktılar?\""},{"n":18,"t":"Derler ki: \"Tespih ederiz seni; seni bırakıp da başka dostlar edinmek bize yaraşmazdı. Ama sen onları ve atalarını öylesine nimetlendirdin ki, zikiri/Kur'an'ı unuttular ve helâke giden bir topluluk oldular.\""},{"n":19,"t":"İşte, haklarında söz söyledikleriniz de sizi yalanladılar. Artık ne azabı savabilirsiniz ne de yardımcı bulabilirsiniz. Zulmedenlerinize zorlu bir azap tattıracağız."},{"n":20,"t":"Senden önce gönderdiğimiz peygamberler de mutlaka yemek yiyorlar, sokaklarda yürüyorlardı. Biz sizi birbiriniz için imtihan aracı yaptık. Sabrediyor musunuz? Rabbin her şeyi görmektedir."},{"n":21,"t":"Bize kavuşmayı ummayanlar dediler ki: \"Üstümüze melekler inse, yahut Rabbimizi görsek olmaz mı?\" Yemin olsun ki, kendi benliklerinde büyüklük kuruntusuna düştüler ve korkunç bir biçimde azdılar."},{"n":22,"t":"Melekleri görecekleri günde, o günahkârlara hiçbir müjde yoktur. Şöyle diyecekler: \"Yasaktır, yasaklanmıştır!\""},{"n":23,"t":"Yaptıkları her işin önüne geçmiş, onu un-ufak hale getirip silmişizdir."},{"n":24,"t":"O gün, konakladıkları yer çok hayırlı, dinlenip eğlendikleri yer çok güzel olanlar, cennet halkıdır."},{"n":25,"t":"Gün olur, gök, bulutlarla yarılır ve melekler ardarda indirilir."},{"n":26,"t":"O gün gerçek mülk/yönetim Rahman'ındır. Ve o, kâfirler için çok zorlu bir gündür."},{"n":27,"t":"O gün, zalim, ellerini ısırarak diyecek ki: \"Ne olurdu, resulle birlikte bir yol tutsaydım!\""},{"n":28,"t":"\"Ah, ne olurdu, falancayı dost edinmeseydim!\""},{"n":29,"t":"\"Zikir/Kur'an bana geldikten sonra, o saptırdı beni ondan. Şeytan, insan için bir rezil edicidir.\""},{"n":30,"t":"Resul de şöyle der: \"Ey Rabbim, benim toplumum, bu Kur'an'ı terk edilmiş/dışlanmış halde tuttular.\""},{"n":31,"t":"Biz böylece her peygambere, suçlulardan bir düşman musallat ettik. Kılavuz ve yardımcı olarak Rabbin yeter."},{"n":32,"t":"Gerçeği örten nankörler/inkârcılar dediler ki: \"Kur'an ona toptan, bir kerede indirilseydi ya!\" Biz böyle yaptık ki, onunla senin kalbini dayanıklı kılalım. Biz onu parça parça/ayet ayet okuduk."},{"n":33,"t":"Onlar sana bir mesel getirdikçe, biz sana hakkı ve en güzel yorumu getiririz."},{"n":34,"t":"O yüzleri üstü cehenneme sevk edilecek olanlar, mekân bakımından en şerli, yol bakımından en sapık kişilerdir."},{"n":35,"t":"Yemin olsun ki, biz Mûsa'ya Kitap verdik. Kardeşi Hârun'u da onun yanında vezir yaptık."},{"n":36,"t":"Ardından şöyle dedik: \"Ayetlerimizi yalanlayan topluluğa gidin.\" Biraz sonra da o topluluğu yerle bir ettik."},{"n":37,"t":"Ve Nûh kavmi... Resulleri yalanladıklarında hepsini boğup, insanlara bir ibret yaptık. Zalimler için acıklı bir azap hazırladık."},{"n":38,"t":"Âd'ı, Semûd'u, Ress, halkını ve bunlar arasında birçok nesilleri yere batırdık."},{"n":39,"t":"Bunların her birine türlü türlü örnekler verdik. Ve bunların hepsini perişan edip batırdık."},{"n":40,"t":"Yemin olsun, onlar o kötülük yağmuruna tutulan kente vardılar. Peki onu görmüyorlar mıydı? Hayır, onlar dirilip hesap vermeyi ummuyorlardı."},{"n":41,"t":"Seni gördüklerinde, şu şekilde alaya almaktan başka şey yapmazlar: \"Allah, resul olarak şunu mu gönderdi?!\""},{"n":42,"t":"\"Eğer biz kendilerine bağlılıkta sabırlı olmasaydık, bu bizi ilahlarımızdan saptıracaktı.\" Azabı gördüklerinde, yolca kimin daha sapık olduğunu bilecekler."},{"n":43,"t":"İğreti arzusunu ilah edinen kişiyi gördün mü? Şimdi ona sen mi vekil olacaksın?"},{"n":44,"t":"Yoksa sen bunların çoğunun işittiklerini, aklettiklerini mi sanıyorsun? Onlar hayvanlar gibidirler, hatta yolca, hayvanlardan da şaşkındırlar."},{"n":45,"t":"Görmedin mi Rabbini, nasıl uzatmıştır gölgeyi? Eğer dileseydi, onu elbette hareketsiz kılardı. Sonra nasıl Güneş'i ona delil yapmışız!"},{"n":46,"t":"Sonra nasıl tutup onu ağır ağır kendimize çekmişiz!"},{"n":47,"t":"O'dur sizin için geceyi elbise, uykuyu dinlence yapan. Gündüzü, dağılıp yayılma zamanı yapan da O'dur."},{"n":48,"t":"O gönderdi rüzgârı bir müjde olarak rahmetinin önünden. Biz indirdik gökten tertemiz bir su."},{"n":49,"t":"Ki onunla ölü bir beldeyi diriltelim ve onunla, yarattıklarımızdan bir takım hayvanları ve birçok insanları suvaralım."},{"n":50,"t":"Yemin olsun, onu aralarında çeşitli biçimlerde ifade ettik ki öğüt alabilsinler. Ama insanların çoğu sadece nankörlükte ısrar etmektedir."},{"n":51,"t":"Eğer dileseydik, her kente bir uyarıcı gönderirdik."},{"n":52,"t":"Artık inkârcılara boyun eğme, onlara karşı Kur'an ile zorlu bir cihat aç."},{"n":53,"t":"İki denizi birbiri üstüne salan O'dur. Bu, tatlı ve yürek ferahlatıcı; şu, tuzlu ve acı. Ve ikisinin arasında bir berzah, geçişi engelleyen bir perde koymuştur."},{"n":54,"t":"Sudan bir insan yaratıp, onu nesep ve sıhriyet akrabaları halinde oluşturan O'dur. Rabbin çok güçlüdür."},{"n":55,"t":"Allah'ın berisinden, kendisine yarar sağlamayacak, zarar da veremeyecek şeylere ibadet/kulluk ediyorlar. İnkârcı, Rabbi aleyhine başkalarına arka çıkar."},{"n":56,"t":"Biz seni sadece müjdeci ve uyarıcı olarak gönderdik."},{"n":57,"t":"De ki: \"Onun karşılığında sizden bir ücret istemiyorum; ancak Rabbine varmak için bir yol tutmayı dileyenler istiyorum.\""},{"n":58,"t":"O hiç ölmeyecek diriye, o Hayy olana dayanıp güven, O'nu överek tespih et! Kullarının günahlarından O'nun haberdar olması yeter!"},{"n":59,"t":"Gökleri, yeri ve bunlar arasındakileri altı günde yaratıp sonra arş üzerinde egemenlik kuran O'dur. Rahman'dır O. Haberdar olana sor O'nu."},{"n":60,"t":"Onlara, \"Rahman'a secde edin!\" dendiğinde şöyle derler: \"Rahman da neymiş? Senin emrettiğin şeye secde eder miyiz hiç?\" Ve bu söz onların nefretini artırdı."},{"n":61,"t":"Şanı yücedir o kudretin ki; gökte burçlar yarattı, orada bir kandil ve ışık yansıtıcı bir ay oluşturdu."},{"n":62,"t":"Geceyle gündüzü, öğüt almak isteyenlerle şükretmek isteyenler için, birbirini izler hale getiren O'dur."},{"n":63,"t":"Rahman'ın kulları, yeryüzünde böbürlenmeden/rahatsız etmeden yürüyen kişilerdir. Cahiller onlara hitap edince, \"Selam!\" derler."},{"n":64,"t":"Geceleri, Rableri huzurunda secde ederek, ayakta durarak geçirirler."},{"n":65,"t":"Ve şöyle yakarırlar: \"Rabbimiz, cehennem azabını bizden uzak tut! Doğrusu, onun azabı inatçı ve yapışkandır.\""},{"n":66,"t":"Ne kötü bir durak yeridir o, ne kötü bir dinlenme yeri!"},{"n":67,"t":"Onlar harcama yaptıkları zaman ne savurganlığa saparlar ne de cimrilik ederler. O ikisi arasında bir dengededir bu!"},{"n":68,"t":"Onlar Allah'ın yanında bir başka ilaha yakarmazlar/davet etmezler. Allah'ın saygıya layık kaldığı canı haksız yere almazlar. Zina etmezler. Bunları yapan, cezaya çarpılır."},{"n":69,"t":"Kıyamet günü azap kendisi için kat kat artırılır da hor ve ezik halde onun içinde uzun süre kalır."},{"n":70,"t":"Tövbe ederek inanan ve hayra/barışa yönelik bir iş yapan müstesna. Allah, böylelerinin kötülüklerini güzelliğe dönüştürür. Allah Gafûr'dur, Rahîm'dir."},{"n":71,"t":"Kim tövbe edip hayra ve barışa yönelik iş yaparsa, hiç kuşkusuz tövbesi kabul edilmiş olarak Allah'a döner."},{"n":72,"t":"Onlar yalana tanıklık etmezler/yalan söze kulak vermezler. Boş lakırdıya rastladıklarında soylu bir tavırla geçip giderler."},{"n":73,"t":"Rablerinin ayetleri kendilerine hatırlatıldığında, kör ve sağırlar gibi onlar üzerine kapanmazlar."},{"n":74,"t":"Onlar şöyle yakarırlar: \"Rabbimiz, eşlerimizden ve çocuklarımızdan bize göz aydınlığı bağışla. Bizi takvaya sarılanlara önder kıl.\""},{"n":75,"t":"İşte bunlar, sabretmiş olmalarına karşılık yüksek konaklarla ödüllendirilirler. Ve o konaklarda sağlık dileğiyle ve selamla karşılanırlar."},{"n":76,"t":"Orada sürekli kalacaklardır. Ne güzel konak yeri, ne güzel dinlenme yeri!\""},{"n":77,"t":"De ki: \"Duanız/davetiniz yoksa, Rabbim sizi ne yapsın? Yalanladınız; bu yüzden azap kaçınılmaz olacaktır.\""}],[{"n":1,"t":"Tâ, Sîn, Mîm."},{"n":2,"t":"İşte sana gerçeği apaçık gösteren Kitap'ın ayetleri..."},{"n":3,"t":"Onlar iman etmiyorlar diye kendini üzüntüden tüketir gibisin."},{"n":4,"t":"Eğer istersek gökten üzerlerine bir mucize indiririz de boyunları onun önünde perişanlıkla eğilip kalır."},{"n":5,"t":"O Rahman'dan kendilerine söze bürünmüş yeni bir hatırlatma gelmeye dursun, ondan mutlaka yüz çevirirler."},{"n":6,"t":"Yemin olsun, yalanladılar ama yakında gelecektir onlara alaya alıp durdukları şeyin haberleri."},{"n":7,"t":"Bakmadılar mı yere, neler fışkırtmışız onda cömert ve bereketli her çiftten."},{"n":8,"t":"Bunda elbette bir mucize var, fakat onların çoğu mümin değiller."},{"n":9,"t":"Ve hiç kuşku yok, senin Rabbin gerçekten mutlak Azîz, mutlak Rahîm'dir."},{"n":10,"t":"Rabbinin Mûsa'ya, \"Zulüm sergileyenler topluluğuna git\" diye seslenişini hatırla."},{"n":11,"t":"\"Firavun'un toplumuna git! Hâlâ sakınmayacaklar mı?\""},{"n":12,"t":"Demişti ki Mûsa: \"Rabbim, doğrusu ben, beni yalanlamalarından korkuyorum.\""},{"n":13,"t":"\"Göğsüm daralıyor, dilim açılmıyor. Görev emrini Hârun'a gönder.\""},{"n":14,"t":"\"Hem, benim üzerimde onlar aleyhine işlenmiş bir suç var; bu yüzden beni öldürmelerinden korkuyorum.\""},{"n":15,"t":"\"Hayır, olmaz!\" dediler. \"Ayetlerimizi götürün. Biz sizinleyiz, herşeyi dinlemekteyiz.\""},{"n":16,"t":"\"Hemen Firavun'a gidin, şöyle deyin: 'Âlemlerin Rabbi'nin resulleriyiz biz.\""},{"n":17,"t":"\"İsrailoğullarını bizimle birlikte gönder.\""},{"n":18,"t":"Firavun dedi: \"Biz seni aramızda, bir çocuk olarak koruyup beslemedik mi? Ömrünün nice yıllarını aramızda geçirdin.\""},{"n":19,"t":"\"Ve sonunda o yaptığını da yaptın. Nankörlerden birisin sen.\""},{"n":20,"t":"Mûsa dedi: \"Onu yaptığım zaman şaşkınlardandım.\""},{"n":21,"t":"\"Sizden korkunca aranızdan kaçtım. Daha sonra Rabbim bana hükmetme gücü bağışladı ve beni peygamberlerden biri yaptı.\""},{"n":22,"t":"\"O başıma kaktığın nimet, İsrailoğullarını köle yapmana karşılıktı.\""},{"n":23,"t":"Firavun dedi: \"Peki, âlemlerin Rabbi kim?\""},{"n":24,"t":"Dedi: \"Göklerin, yerin ve bunlar arasındakilerin Rabbi. Eğer iyice anlayıp inanıyorsanız.\""},{"n":25,"t":"Firavun, çevresindekilere dedi: \"Duyuyor musunuz?\""},{"n":26,"t":"Mûsa dedi: \"O hem sizin Rabbinizdir hem de önceki atalarınızın Rabbidir.\""},{"n":27,"t":"Firavun dedi: \"Şu size gönderilmiş bulunan resulünüz gerçekten tam bir deli.\""},{"n":28,"t":"Mûsa dedi: \"Eğer aklınızı işletirseniz O, doğunun, batının ve bunlar arasındakilerin de Rabbidir.\""},{"n":29,"t":"Dedi: \"Benden başka ilah edinirsen, yemin olsun seni zındanlıklar arasına atarım.\""},{"n":30,"t":"Mûsa dedi: \"Ya sana gerçeği gösteren birşey getirmişsem!\""},{"n":31,"t":"Dedi: \"Hadi getir onu ortaya, eğer doğru sözlülerden isen!\""},{"n":32,"t":"O da asasını attı. Bir de ne görsünler, asa korkunç bir ejderha oluvermiş."},{"n":33,"t":"Elini çıkardı, o da anında seyredenler önünde bembeyaz kesildi."},{"n":34,"t":"Firavun, çevresindeki kodamanlar konseyine şöyle dedi: \"Bu adam gerçekten bilgin bir büyücü;"},{"n":35,"t":"Büyüsüyle sizi toprağınızdan çıkarmak istiyor. Ne diyorsunuz?\""},{"n":36,"t":"Dediler: \"Onu kardeşiyle birlikte alıkoy ve kentlere toplayıcılar gönder,"},{"n":37,"t":"Ki, tüm bilgili büyücüleri huzuruna getirsinler.\""},{"n":38,"t":"Nihayet büyücüler belirlenen bir günün, belirlenen bir vaktinde bir araya getirildi."},{"n":39,"t":"Halka da: \"Siz de toplanır mısınız?\" denildi."},{"n":40,"t":"\"Sanıyoruz ki, büyücülere uyacağız, eğer galip gelirlerse.\""},{"n":41,"t":"Büyücüler geldiklerinde, Firavun'a dediler ki: \"Eğer biz galip gelirsek bize gerçekten ödül var, değil mi?\""},{"n":42,"t":"\"Evet, dedi, siz o zaman benim yakınlarımdan olacaksınız.\""},{"n":43,"t":"Mûsa onlara dedi ki: \"Atacağınız şeyi atın!\""},{"n":44,"t":"Bunun üzerine onlar, iplerini ve değneklerini ortaya attılar ve dediler: \"Firavun'un onur ve yüceliği aşkına biz, evet biz galip geleceğiz.\""},{"n":45,"t":"Mûsa da asasını attı. Bir de ne görsünler, o onların hüner olarak ortaya getirdikleri şeyleri yalayıp yutuyor."},{"n":46,"t":"Bunun üzerine büyücüler, secdelere kapandılar."},{"n":47,"t":"Dediler: \"İnandık âlemlerin Rabbi'ne.\""},{"n":48,"t":"\"Mûsa'nın ve Hârun'un Rabbine.\""},{"n":49,"t":"Firavun haykırdı: \"Ben size izin vermeden ona inandınız ha! Anlaşıldı, o sizin hepinize sihirbazlığı öğreten büyüğünüz. Yakında bileceksiniz. Yemin olsun, ellerinizi, ayaklarınızı çaprazlamasına keseceğim ve yemin olsun sizi toptan asacağım.\""},{"n":50,"t":"Dediler: \"Zararı yok, biz nasıl olsa Rabbimize döneceğiz,"},{"n":51,"t":"Ümidimiz odur ku, Rabbimiz hatalarımızı bağışlar çünkü biz ilk inananlar olduk.\""},{"n":52,"t":"Mûsa'ya şunu vahyettik: Kullarımı geceleyin yola çıkar. Mutlaka peşinize takılacaklar."},{"n":53,"t":"Bunun üzerine Firavun, kentlere toplayıcılar gönderdi:"},{"n":54,"t":"\"Kuşkusuz bunlar, küçücük bir topluluktur.\""},{"n":55,"t":"\"Fakat bize gerçekten öfke püskürüyolar.\""},{"n":56,"t":"\"Biz ise dikkatli davranan koca bir kitleyiz.\""},{"n":57,"t":"Bunun üzerine biz onları bahçelerinden, pınarlarından çıkardık."},{"n":58,"t":"Hazinelerinden, mutlu-kutlu yerlerinden ettik."},{"n":59,"t":"Böylece oralara İsrailoğullarını vâris kıldık."},{"n":60,"t":"Firavun ve adamları, gün doğarken onları izlemeye başladılar."},{"n":61,"t":"İki topluluk birbirini görecek hale gelince, Mûsa'nın adamları seslendi: \"İşte şimdi yakalandık!\""},{"n":62,"t":"Mûsa dedi: \"Hayır, asla! Rabbim benimledir, bana kılavuzluk edecektir.\""},{"n":63,"t":"Bunun üzerine Mûsa'ya, \"Asanla denize vur!\" diye vahyettik. Deniz hemen yarıldı, her dalga kümesi kocaman bir dağ gibi oldu."},{"n":64,"t":"Ötekileri de oraya yaklaştırdık."},{"n":65,"t":"Mûsa'yı ve beraberindekileri toptan kurtardık."},{"n":66,"t":"Sonra ötekileri boğduk."},{"n":67,"t":"Bunda elbette bir ibret vardır ama onların çoğu inanmış kimseler değildi."},{"n":68,"t":"Ve şüphesiz, senin Rabbindir O mutlak Azîz, mutlak Rahîm."},{"n":69,"t":"İbrahim'in haberini de oku onlara."},{"n":70,"t":"Hani babasına ve toplumuna şöyle demişti: \"Siz neye ibadet ediyorsunuz?\""},{"n":71,"t":"Dediler: \"Birtakım putlara tapıyoruz. Onların önünde toplanıp tapınmaya devam edeceğiz.\""},{"n":72,"t":"Dedi: \"Yalvarıp yakardığınızda sizi duyuyorlar mı?\""},{"n":73,"t":"\"Size yarar sağlıyor yahut zarar veriyorlar mı?\""},{"n":74,"t":"Dediler: \"Hayır! Ancak atalarımızı böyle yapar halde bulduk.\""},{"n":75,"t":"Dedi: \"Gördünüz mü neye ibadet ediyormuşsunuz!\""},{"n":76,"t":"\"Siz ve o eski atalarınız!\""},{"n":77,"t":"\"Şüphesiz onlar benim düşmanım. Ama âlemlerin Rabbi dostum.\""},{"n":78,"t":"\"O yarattı beni, O yol gösteriyor bana.\""},{"n":79,"t":"\"O'dur beni doyuran, suvaran.\""},{"n":80,"t":"\"Hastalandığında O'dur bana şifa ulaştıran.\""},{"n":81,"t":"\"Beni öldürecek, sonra diriltecek O'dur.\""},{"n":82,"t":"\"Din gününde hatalarımı affetmesini umup durduğum da O'dur.\""},{"n":83,"t":"\"Rabbim, bana hükmetme gücü/hikmet bağışla, beni hak ve barış seven iyiler arasına kat!\""},{"n":84,"t":"\"Sonradan gelecekler arasında benimle ilgili doğru/isabetli bir dil oluştur.\""},{"n":85,"t":"\"Beni, nimetlerle dolu cennetin mirasçılarından kıl.\""},{"n":86,"t":"\"Babamı da affet. Çünkü o, sapmışlardandır.\""},{"n":87,"t":"\"Herkesin diriltileceği gün beni utandırma.\""},{"n":88,"t":"\"Bir gündür ki o, ne mal fayda verir ne oğullar.\""},{"n":89,"t":"\"Yalnız temiz bir kalple Allah'a varan kurtulur.\""},{"n":90,"t":"Cennet takva sahiplerine yaklaştırılır."},{"n":91,"t":"Cehennem de şımarıp azanların karşısına getirilir."},{"n":92,"t":"Denir ki onlara: \"O ibadet ettikleriniz nerede?\""},{"n":93,"t":"\"Allah'ın dışındakiler, size yardım ediyorlar mı? Peki, kendilerine yardımları dokunuyor mu?\""},{"n":94,"t":"Ardından onlar ve öteki azgınlar cehennemin içinde tıkılmıştır."},{"n":95,"t":"İblis orduları toplu haldedir."},{"n":96,"t":"Onun içinde birbiriyle çekişirlerken şöyle derler:"},{"n":97,"t":"\"Vallahi, biz açık bir sapıklığın ta içindeymişiz.\""},{"n":98,"t":"\"Çünkü sizi âlemlerin Rabbi'yle aynı düzeyde tutuyorduk.\""},{"n":99,"t":"\"Bizi saptıran, o suçlulardan başkası değildi.\""},{"n":100,"t":"\"Artık ne şefaatçilerimiz var,"},{"n":101,"t":"Ne sıcak-samimi bir dostumuz.\""},{"n":102,"t":"\"Keşke bir dönüşünüz daha olsaydı da müminlerden olabilseydik.\""},{"n":103,"t":"Kuşkusuz, bütün bunlarda mutlaka bir ibret vardır. Ama onların çoğu müminler değil."},{"n":104,"t":"Ve kuşkusuz senin Rabbindir o mutlak Azîz, mutlak Rahîm."},{"n":105,"t":"Nûh kavmi de hak elçileri yalanladı."},{"n":106,"t":"Kardeşleri Nûh onlara şöyle demişti: \"Siz hiç sakınmıyor musunuz/\""},{"n":107,"t":"\"Ben sizin için gelmiş, güvenilir bir resulüm.\""},{"n":108,"t":"\"Artık Allah'tan sakının da bana itaat edin.\""},{"n":109,"t":"\"Ben bunun için sizden bir ücret istemiyorum. Benim ödülüm sadece âlemlerin Rabbi'ndedir."},{"n":110,"t":"\"Artık Allah'tan sakının da bana itaat edin.\""},{"n":111,"t":"Dediler: \"Biz sana inanır mıyız? Seni, o bayağı zavallılar izliyor.\""},{"n":112,"t":"Nûh dedi: \"Onların yaptıklarına ilişkin bir ilmim yok.\""},{"n":113,"t":"\"Onların hesabı Rabbimden başkasına ait değildir. Bir düşünebilseniz!\""},{"n":114,"t":"\"Ben iman etmiş insanları kovamam.\""},{"n":115,"t":"\"Ben sadece açık bir biçimde uyarmaktayım.\""},{"n":116,"t":"Dediler: \"Ey Nûh! Eğer bu işe son vermezsen, vallahi taşlananlardan olacaksın.\""},{"n":117,"t":"Nûh şöyle yakardı: \"Rabbim, toplumun beni yalanladı.\""},{"n":118,"t":"\"Artık benimle onlar arasını iyice aç; beni ve beraberimdeki müminleri kurtar.\""},{"n":119,"t":"Bunun üzerine biz, onu da beraberindekileri de o yüklü gemide kurtardık."},{"n":120,"t":"Sonra dışta kalanları boğduk."},{"n":121,"t":"Bunda elbette bir ibret var. Ama onların çoğu müminler değildi."},{"n":122,"t":"Kuşkusuz, senin Rabbindir o mutlak Azîz, mutlak Rahîm."},{"n":123,"t":"Âd da peygamberleri yalanladı."},{"n":124,"t":"Kardeşleri Hûd onlara: \"Siz hiç sakınmıyor musunuz?\" demişti."},{"n":125,"t":"\"Ben sizin için, güvenilir bir resulüm.\""},{"n":126,"t":"\"Artık Allah'tan sakının da bana itaat edin.\""},{"n":127,"t":"\"Ben sizden bu iş için bir ücret istemiyorum. Benim ödülüm âlemlerin Rabbi'ndendir.\""},{"n":128,"t":"\"Her yüksek tepeye/yola şaşılacak bir bina kurarak/bir işaret dikerek mi eğleniyorsunuz!\""},{"n":129,"t":"\"Sanayi üreten yerler edinerek sonsuzlaşmak ümidine mi düşüyorsunuz?\""},{"n":130,"t":"\"Yakaladığınız vakit zorbaca yakalıyorsunuz?\""},{"n":131,"t":"\"Artık Allah'tan sakının da bana itaat edin.\""},{"n":132,"t":"\"O bildiğiniz nimetleri önünüze yayandan korkun.\""},{"n":133,"t":"\"Size bir yığın nimet lütfetti: Davarlar, oğullar,"},{"n":134,"t":"Bahçeler, pınarlar.\""},{"n":135,"t":"\"Büyük bir günün azabı üstünüzedir diye korkuyorum.\""},{"n":136,"t":"Dediler: \"Sen ha öğüt vermişsin ha öğüt verenlerden olmamışsın. Bizim için fark etmez.\""},{"n":137,"t":"\"Bu, öncekilerin uydurmalarından başka şey değil.\""},{"n":138,"t":"\"Biz azaba uğratılacak değiliz.\""},{"n":139,"t":"Onu bu şekilde yalanladılar, biz de onları helâk ettik. Bunda elbette bir ibret var. Ama onların çoğu müminlerden değildi."},{"n":140,"t":"Kuşkusuz, senin Rabbin mutlak Azîz, mutlak Rahîm'dir."},{"n":141,"t":"Semûd da peygamberleri yalanladı."},{"n":142,"t":"Kardeşleri Sâlih onlara demişti ki: \"Siz hiç sakınmıyor musunuz?\""},{"n":143,"t":"\"Ben sizin için emin bir resulüm.\""},{"n":144,"t":"\"Artık Allah'tan sakının ve bana itaat edin.\""},{"n":145,"t":"\"Ben bu iş için sizden bir ücret istemiyorum. Benim ücretim yalnız âlemlerin Rabbi'ndendir.\""},{"n":146,"t":"\"Siz burada güven içinde bırakılacak mısınız?\""},{"n":147,"t":"\"Bahçelerde, pınarlarda.\""},{"n":148,"t":"\"Ekinler, salkımları sarkmış hurmalıklar içinde.\""},{"n":149,"t":"\"Keyif içinde, dağlardan evler yontuyorsunuz.\""},{"n":150,"t":"\"Artık Allah'tan sakının da bana itaat edin.\""},{"n":151,"t":"\"Savurganlık edenlerin/haddi aşanların buyruğuna uymayın.\""},{"n":152,"t":"\"Onlar yeryüzünde bozgun çıkarırlar, barış için çalışmazlar.\""},{"n":153,"t":"Dediler: \"Sen, adamakıllı büyülenmişsin.\""},{"n":154,"t":"\"Sen de bizim gibi bir insansın. Eğer doğru sözlülerden isen, hadi bir mucize getir.\""},{"n":155,"t":"Dedi: \"Şu bir dişi devedir. Onun su içme hakkı var. Belli bir günde su içme hakkı da sizin.\""},{"n":156,"t":"\"Ona kötülükle ilişmeyin. Yoksa büyük bir günün azabı sizi yakalar.\""},{"n":157,"t":"Onu yere yatırıp kestiler. Sonra da pişman oldular."},{"n":158,"t":"Sonunda azap onları yakaladı. Bunda elbette bir ibret var. Ama onların çoğu inanan kişiler değildi."},{"n":159,"t":"Ve senin Rabbin mutlak Azîz, mutlak Rahîm'dir."},{"n":160,"t":"Lût kavmi de hak elçilerini yalanladı."},{"n":161,"t":"Kardeşler Lût onlara şöyle demişti: \"Hâlâ sakınmıyor musunuz?\""},{"n":162,"t":"\"Ben size gelen emin bir elçiyim.\""},{"n":163,"t":"\"Artık Allah'tan sakının da bana itaat edin.\""},{"n":164,"t":"\"Ben bu iş için sizden bir ücret istemiyorum. Benim ücret yalnız âlemlerin Rabbi'ndendir.\""},{"n":165,"t":"\"Âlemlerin içinden erkeklere gidiyor da,"},{"n":166,"t":"Rabbinizin sizin için yarattığı eşlerinizi bırakıyor musunuz? Doğrusu siz haddi aşmış bir kavimsiniz.\""},{"n":167,"t":"Dediler: \"Eğer bu tavrını sona erdirmezsen, ey Lût, yemin olsun bu topraktan sürülenlerden olacaksın.\""},{"n":168,"t":"Lût dedi: \"Ben sizin şu yaptığınıza öfkelenenlerdenim.\""},{"n":169,"t":"\"Rabbim, beni ve ailemi bunların yaptıklarından koru.\""},{"n":170,"t":"Bunun üzerine biz onu ve ailesini toplu halde kurtardık."},{"n":171,"t":"Ancak geridekiler arasında bir kocakarı kaldı."},{"n":172,"t":"Sonra ötekileri mahvedip batırdık."},{"n":173,"t":"Üzerlerine bir de yağmur yağdırdık. Ne de kötüymüş uyarılanların yağmuru!"},{"n":174,"t":"Elbette bunda bir ayet var ama onların çoğu müminler değildi."},{"n":175,"t":"Ve senin Rabbin mutlak Azîz, mutlak Rahîm..."},{"n":176,"t":"Eyke halkı da elçileri yalanladı."},{"n":177,"t":"Şuayb onlara demişti ki: \"Hâlâ sakınmıyor musunuz?\""},{"n":178,"t":"\"Kuşkusuz, ben sizin için güvenilir bir resulüm.\""},{"n":179,"t":"\"Artık Allah'tan sakının da bana itaat edin.\""},{"n":180,"t":"\"Ben bu iş için sizden herhangi bir ödül de istemiyorum; benim ödülüm âlemlerin Rabbi'nden başkasında değil.\""},{"n":181,"t":"\"Ölçüyü tam yapın; şunun-bunun hakkını çarpanlardan olmayın;"},{"n":182,"t":"\"Doğru-düzgün terazi ile tartın.\""},{"n":183,"t":"\"Halkın eşyasını, değerlerini düşürerek almayın. Yeryüzünde, bozguncular olarak fesat çıkarmayın!\""},{"n":184,"t":"\"Sizi ve önceki nesilleri yaratandan sakının!\""},{"n":185,"t":"Dediler: \"Sen fena halde büyülenmişsin.\""},{"n":186,"t":"\"Sen bizim gibi bir insandan başka şey değilsin. Biz senin yalancılardan olduğunu düşünüyoruz.\""},{"n":187,"t":"\"Eğer doğru sözlülerdensen, hadi üzerimize gökten parçalar düşür!\""},{"n":188,"t":"Şuayb dedi: \"Yapmakta olduğunuzu Rabbim daha iyi bilir.\""},{"n":189,"t":"Onu yalanladılar; bunun üzerine o gölgelik gününün azabı onları yakalayıverdi. O, gerçekten büyük bir günün azabıydı."},{"n":190,"t":"Bunda elbette bir ibret var ama onların çoğu inanan kişiler değildi."},{"n":191,"t":"Ve senin Rabbin mutlak Azîz, mutlak Rahîm'dir."},{"n":192,"t":"Kesin olan şu ki, o âlemlerin Rabbi'nden indirilmiştir."},{"n":193,"t":"O güvenilir Rûh indirdi onu,"},{"n":194,"t":"Senin kalbine ki, uyarıcılardan olasın."},{"n":195,"t":"Açık-seçik Arapça bir dille indirdi."},{"n":196,"t":"O, elbette ki öncekilerin kitaplarında da var."},{"n":197,"t":"Beniisrail bilginlerinin de onu bilmesi bunlar için bir belirti/kanıt değil mi?"},{"n":198,"t":"Biz onu Arapça konuşmayanlardan birine indirseydik de,"},{"n":199,"t":"O onu onlara okusaydı, yine de ona inanmayacaklardı."},{"n":200,"t":"Biz onu suçluların kalplerine işte böyle yolladık."},{"n":201,"t":"Acıklı azabı görünceye değin ona inanmazlar."},{"n":202,"t":"O azap onlara ansızın gelecek, farkında bile olmayacaklar."},{"n":203,"t":"O zaman şöyle derler: \"Acaba bize süre verilir mi?\""},{"n":204,"t":"Bizim azabımızı acele mi istiyorlar?"},{"n":205,"t":"Görmedin mi ki, biz onları yıllarca nimetlendirsek de,"},{"n":206,"t":"Sonra, tehdit edildikleri şey kendilerine ulaşsa,"},{"n":207,"t":"O yararlandıkları nimetler onların hiçbir işine yaramaz."},{"n":208,"t":"Biz, uyarıcıları olmayan hiçbir kenti/uygarlığı helâk etmemişizdir."},{"n":209,"t":"Uyarı/hatırlatma olacak! Biz zalimler değiliz."},{"n":210,"t":"Onu şeytanlar indirmedi."},{"n":211,"t":"Onlara yaraşmaz, zaten güçleri de yetmez."},{"n":212,"t":"Çünkü onlar, dinleyişten azledilmişlerdir."},{"n":213,"t":"O halde, Allah'ın yanında bir başka ilaha daha yalvarma/davet etme. Yoksa azaba uğratılanlardan olursun."},{"n":214,"t":"En yakın akraba ve hısımlarını uyar."},{"n":215,"t":"Müminlerin sana uyanlara kanadını indir."},{"n":216,"t":"Eğer sana isyan ederlerse şöyle de: \"Ben, sizin yapmakta olduklarınızdan uzağım.\""},{"n":217,"t":"O Azîz, o Rahîm olana güvenip dayan."},{"n":218,"t":"O ki görüyor seni kıyam ettiğin zaman."},{"n":219,"t":"Görüyor nasıldır secde edenler içinde dolaşman."},{"n":220,"t":"Kuşkusuz, O'dur iyice bilen, iyice duyan."},{"n":221,"t":"Haber vereyim mi size şeytanların kime iner olduğundan?"},{"n":222,"t":"Her bir dönek/iftiracı günahkâr üzerine iner onlar."},{"n":223,"t":"Kulak kabartırlar ama çoğu yalancılardır onların."},{"n":224,"t":"Şairlere gelince, onlara da çapkınlar-sapkınlar uyar."},{"n":225,"t":"Görmez misin onları ki, her vadide tutkun-şaşkın dolaşırlar."},{"n":226,"t":"Ve onlar, yapmayacakları şeyleri söyleyip dururlar."},{"n":227,"t":"İman edip barışa/hayra yönelik işler yapanlar, Allah'ı çok ananlar ve zulme uğratıldıktan sonra başarıya ulaşanlar böyle değillerdir. Zulmedenler, hangi devrime uğrayıp baş aşağı döneceklerini yakında bilecekler."}],[{"n":1,"t":"Tâ, Sîn. İşte bunlar Kur'an'ın ve açık-seçik beyanda bulunan Kitap'ın ayetleridir."},{"n":2,"t":"Müminlere bir kılavuz ve muştudur o."},{"n":3,"t":"O müminler ki, namazı/duayı yerine getirirler, zekâtı verirler. Ve âhirete tam bir biçimde inananlar da onlardır."},{"n":4,"t":"Şu bir gerçek ki, âhirete inanmayanların amellerini biz, kendileri için süsleyip püsledik. Bu yüzden onlar kalpleri körelmiş olarak şaşkınlık içinde bocalar dururlar."},{"n":5,"t":"İşte bunlardır kendilerine azabın korkuncu öngörülen. Âhirette hüsrana uğrayacaklar da onlardır."},{"n":6,"t":"Emin ol ki, sen bu Kur'an'a Hakîm ve Alîm bir kudret tarafından muhatap kılınıyorsun."},{"n":7,"t":"Hatırla o zamanı; Mûsa, ailesine şöyle demişti: \"Ben bir ateş fark ettim. Ondan size bir haber getireceğim, yahut parlak bir kor getireceğim ki ateş yakıp ısınabilesiniz.\""},{"n":8,"t":"Mûsa ateşe vardığında şöyle çağrıldı. \"Ateşteki kimse de ateşin çevresindekiler de kutsal ve bereketli kılınmıştır. Ve âlemlerin Rabbi olan Allah, bütün eksiklik ve iğretiliklerden arınmıştır.\""},{"n":9,"t":"\"Ey Mûsa! Kuşkun olmasın ki ben, Allah'ım; Azîz olan, Hakîm olanım...\""},{"n":10,"t":"\"Asanı bırak!\" Bunun üzerine Mûsa, asayı çevik bir yılan gibi titreyip kıvrılır görünce gerisin geri kaçtı ve arkasına bakmadı. \"Korkma ey Mûsa, benim. Benim huzurumda, elçi olarak gönderilenler korkmaz.\""},{"n":11,"t":"\"Zulme bulaşan müstesna. O da bunu kötülüğün arkasından güzelliğe çevirirse hiç kuşkusuz ben Gafûr'um, Rahîm'im.\""},{"n":12,"t":"\"Elini koynuna sok; Firavun ve toplumuna yönelik dokuz mucizeden biri olarak pürüzsüz ve lekesiz, bembeyaz bir biçimde çıkacaktır. O Firavun ve yandaşları sapmış bir topluluk haline geldiler.\""},{"n":13,"t":"İşte bu şekilde ayetlerimiz göz ve gönül açar bir biçimde onlara geldiğinde şunu deyiverdiler: \"Açık bir büyüdür bu...\""},{"n":14,"t":"Zulüm ve böbürlenmeyle, ona karşı çıktılar. Oysaki öz benlikleri, onun gerçekliğine kanaat getirmişti. Bak da gör, nasıl olmuştur o bozguncuların sonu!"},{"n":15,"t":"Yemin olsun, biz, Davûd'a da Süleyman'a da bir ilim verdik. Onlar şöyle dediler: \"Bizi, mümin kullarının bir çoğundan üstün kılan Allah'a hamd olsun.\""},{"n":16,"t":"Süleyman, Davûd'a mirasçı oldu ve şöyle dedi: \"Ey insanlar, bize kuşların dili öğretildi ve bize herşeyden biraz verildi. Kuşkusuz bu, apaçık lütfun ta kendisidir.\""},{"n":17,"t":"Cinlerden, insanlardan ve kuşlardan orduları, Süleyman'ın huzurunda bir araya getirildi. Onlar, düzenli bir biçimde sevk ediliyorlardı."},{"n":18,"t":"Karınca vadisine geldiklerinde bir karınca şöyle seslendi: \"Ey karıncalar! Yuvalarınıza girin ki, Süleyman ve orduları farkında olmayarak sizi ezmesinler.\""},{"n":19,"t":"Bunun üzerine Süleyman, karıncanın sözüne güldü ve dedi: \"Rabbim, bana ve ebeveynime lütfettiğin nimetine şükretmeme, hoşnut olacağın hayırlı ve barışçıl bir iş yapmama imkân ver. Ve rahmetinle beni iyilik ve barışı seven kullarının arasına sok.\""},{"n":20,"t":"Kuşları teftiş etti de dedi ki: \"Hüdhüd'ü neden göremiyorum, yoksa kayıplara mı karıştı?\""},{"n":21,"t":"\"Ona acımasızca azap edeceğim, belki de onu boğazlayacağım; yahut da bana mutlaka açık bir kanıt getirecek.\""},{"n":22,"t":"Az sonra Hüdhüd gelip şöyle dedi: \"Senin fark edemeyeceğin bir şeyi fark ettim ve sana Sabâ'dan parlak bir haber getirdim.\""},{"n":23,"t":"\"Sabâlılara hükmeden bir kadın buldum. Kendisine herşeyden bir pay verilmiş, kocaman bir tahtı var.\""},{"n":24,"t":"\"Onu ve toplumunu, Allah'ı bırakıp Güneş'e secde eder buldum. Şeytan onlara, yapıp ettiklerini süslü gösterip onları yoldan saptırmış. Artık doğruyu bulamazlar.\""},{"n":25,"t":"\"Göklerde ve yerdeki sırrı açığa çıkaran, onların gizlediklerini de açıkladıklarını da bilen Allah'a secde etmemek gayretindeler.\""},{"n":26,"t":"\"O Allah ki, tanrı yok kendinden başka, o büyük arşın rabbidir O.\""},{"n":27,"t":"Süleyman dedi: \"Doğru mu söyledin yoksa yalancılardan mısın, göreceğiz!\""},{"n":28,"t":"\"Şu yazımı götürüp onlara at. Sonra onlardan uzaklaş da bak bakalım, nasıl davranacaklar.\""},{"n":29,"t":"Melike dedi ki: \"Ey ileri gelenler, bana önemli bir mektup bırakıldı.\""},{"n":30,"t":"\"Süleyman'dan bir mektup. Rahman ve Rahîm Allah'ın adıyla başlıyor.\""},{"n":31,"t":"\"Söylediği şu: Bana büyüklük taslamaya kalkmayın. Teslim olarak huzuruma gelin.\""},{"n":32,"t":"Melike dedi: \"Ey danışmanlarım, bu meselem konusunda bana fikir verin. Siz onaylamadıkça, hiçbir işe kesin karar vermem.\""},{"n":33,"t":"Dediler ki: \"Biz çok güçlüyüz, çok yaman savaşırız. Buyruk senin. Ne karar vereceğini sen bilirsin.\""},{"n":34,"t":"Melike dedi: \"Şu bir gerçek ki krallar bir kente/bir memlekete girdiler mi, orada bozgun çıkarırlar; oranın onurlu insanlarını zelil-sefil ederler. İşte böyle yaparlar.\""},{"n":35,"t":"\"Şimdi ben onlara bir hediye göndereceğim ve bakacağım elçiler neyle geri dönecekler.\""},{"n":36,"t":"Elçi, Süleyman'a geldiğinde, o dedi ki: \"Siz bana bir mal ile mi destek veriyorsunuz? Allah'ın bana verdiği, size verdiğinden daha kıymetlidir. Sizin hediyenizle, benden çok siz ferahlarsınız.\""},{"n":37,"t":"\"Seni gönderenlere dön. Vallahi, karşı koyamayacakları ordularla üstlerine gelirim ve onları oradan, başları eğik, aşağılanmış bir halde sürer çıkarırım.\""},{"n":38,"t":"Süleyman, kurmaylarına dedi ki: \"Onlar teslim olup huzuruma gelmeden önce, o kadının tahtını hanginiz bana getirebilir?\""},{"n":39,"t":"Cinlerden bir ifrit şöyle dedi: \"Sen daha makamından kalkmadan, onu sana getirebilirim. Ben bunu yapacak güçteyim ve gerçekten güvenilir biriyim.\""},{"n":40,"t":"Kendinde Kitap'tan bir ilim olan kişi de şöyle dedi: \"Ben onu sana, gözünü açıp yumuncaya kadar getiririm.\" Derken Süleyman, tahtı, yanında kurulmuş görünce şöyle konuştu: \"Rabbimin lütfundandır bu. Şükür mü edeceğim, nankörlük mü diye beni denemek istiyor. Esasında, şükreden, kendisi lehine şükretmiş olur. Kim de nankörlük ederse bilsin ki, Rabbim Ganî'dir, cömerttir.\""},{"n":41,"t":"Emir verdi: \"Onun tahtını başkalaştırın, bakalım tanıyacak mı, tanıyamayanların arasına mı girecek?\""},{"n":42,"t":"Melike gelince şöyle denildi: \"Senin tahtın da böyle mi?\" Dedi: \"Bu sanki o. Zaten daha önce bize bilgi verilmişti ve biz müslüman olmuştuk.\""},{"n":43,"t":"Daha önce Allah dışında ibadet ettikleri, onu engellemişti. Çünkü o, küfre sapmış bir topluluktandı."},{"n":44,"t":"Ona denildi: \"Köşke gir!\" Melike onu görünce su sandı ve baldırlarını açtı. Süleyman dedi ki: \"O, cilalı sırçadan yapılmış bir parlak avlu/zemindir.\" Melike dedi: \"Rabbim, doğrusu ben öz benliğime zulmetmişim. Artık Süleyman'la birlikte, âlemlerin Rabbi olan Allah'a teslim oluyorum.\""},{"n":45,"t":"Yemin olsun, Semûd'a da kardeşleri Sâlih'i, şunu tebliğ etmek üzere gönderdik: \"Allah'a kulluk/ibadet edin.\" Bir de ne görelim, onlar birbiriyle boğuşan iki fırka oluvermişler."},{"n":46,"t":"Sâlih dedi: \"Ey toplumum! İyilikten önce kötülüğü istemede aceleniz niye? Merhamet görebilmeniz için Allah'tan af dileseniz olmaz mı?\""},{"n":47,"t":"Dediler: \"Sen ve beraberindekiler yüzünden başımıza uğursuzluk geldi/sen ve beraberindekileri uğursuzluk belirtisi sayıyoruz.\" Dedi: \"Uğursuzluk kuşunuz Allah katındadır. Daha doğrusu siz, imtihana çekilen bir topluluksunuz."},{"n":48,"t":"O kentte, hep bozgun çıkarıp barışa hiç yanaşmayan dokuz çete vardı."},{"n":49,"t":"Allah adına yeminleşerek şöyle dediler: \"Ona ve ailesine bir gece baskını yapalım, sonra da velisine şöyle diyelim: Biz onların ailesinin öldürülüşüne tanık olmadık. Vallahi, doğru söyleyenleriz.\""},{"n":50,"t":"Onlar bir tuzak kurdular, biz de bir tuzak kurduk, ama şuursuzluk eden onlardı."},{"n":51,"t":"Bir baksana nasıl oldu tuzaklarının sonu! İşte, onları da topluluklarını da hep birlikte yere geçirdik."},{"n":52,"t":"İşte sana onların, işledikleri zulümler yüzünden çöküp ıpıssız kalmış evleri. Hiç kuşkusuz bunda, ilmi kullanan bir topluluk için kesin bir ibret vardır."},{"n":53,"t":"Biz inananları, korunup sakınanları kurtardık."},{"n":54,"t":"Lût'u da resul olarak gönderdik. Toplumuna şöyle dedi: \"Gözünüz göre göre şu iğrençliği yapıyorsunuz ha!\""},{"n":55,"t":"\"Siz, şehvetinizi tatmin için kadınları bırakıp da erkeklere mi gidiyorsunuz? Doğrusu siz cehalete saplanmış bir topluluksunuz.\""},{"n":56,"t":"Toplumunun cevabı sadece şunu söylemek oldu: \"Çıkarın şu Lût ailesini kentinizden; bunlar temizlik tutkunu olmuş kişilerdir.\""},{"n":57,"t":"Bunun üzerine onu ve ailesini kurtardık. Karısı hariç. Onu, arkada kalanlardan biri olarak takdir etmiştik."},{"n":58,"t":"Üzerlerine bir de yağmur yağdırdık. Uyarılmış olanlar üzerine inen yağmur da ne kötüdür!\""},{"n":59,"t":"De ki: \"Hamd Allah'a, selam O'nun seçip yücellitiği kullarına! Allah mı hayırlı, yoksa onların ortak tuttukları mı?\""},{"n":60,"t":"Yoksa gökleri ve yeri yaratan, gökten size bir su indiren mi hayırlı? Biz o suyla sizin için gözler-gönüller açan bahçeler bitirdik. Sizin, onların bir tek ağacını bitirmeniz mümkün değildi. Allah'ın yanında bir ilah mı var? Hayır! Ama onlar döneklik eden bir topluluktur."},{"n":61,"t":"Yoksa yeri bir karargâh yapıp şurasına-burasına nehirler serpiştiren, üzerine dayanaklı dağlar konduran ve iki deniz arasına bir engel yerleştiren mi hayırlı? İlah mı var Allah'ın yanında!? Hayır! Ama onların çokları ilimden nasipsizliği sürdürüyorlar."},{"n":62,"t":"Yoksa zorda kalan yalvardığında, onun imdadına yetişip sıkıntı ve kaderi kaldıran, sizi yeryüzünün hükmedenleri kılan mı hayırlı? Allah'ın yanında bir ilah daha var mı!? Ne kadar da az ibret alıyorsunuz!"},{"n":63,"t":"Yoksa size karanın ve denizin karanlıkları içinde yol gösteren ve rahmetini önünde rüzgârları müjdeci gönderen mi hayırlı? Allah'ın beraberinde bir ilah daha mı var?! Allah, onların ortak tuttuklarından uzaktır, arınmıştır."},{"n":64,"t":"Yoksa yaratmaya başlayıp sonra tekrar tekrar yaratan ve sizi gözeten ve yerden rızıklandıran mı hayırlı? Allah'ın yanında bir ilah mı var? De ki: \"Getirin susturucu kanıtınızı, eğer doğru sözlüler iseniz.\""},{"n":65,"t":"De ki: \"Göklerde ve yerde, Allah'tan başka hiç kimse gaybı bilmez. Ne zaman dirileceklerini de bilmezler.\""},{"n":66,"t":"Hayır, onların bilgileri âhiret konusunda yetersiz kalmıştı. Daha doğrusu onlar ondan kuşku duymaktadırlar. Hayır, hayır! Onlar, onu göremeyecek kadar kördürler."},{"n":67,"t":"İnkârcılar dediler ki: \"Biz ve atalarımız toprak olduktan sonra, gerçekten biz bundan sonra ortaya mı çıkarılacağız?\""},{"n":68,"t":"\"Yemin olsun, bununla şimdi biz, önceden de atalarımız tehdit edildi. Bu, öncekilerin masallarından başka bir şey değil.\""},{"n":69,"t":"De ki: \"Yeryüzünde dolaşın da bir bakın nice olmuştur günahkârların sonu!\""},{"n":70,"t":"Onlar yüzünden tasalanma. Kurmakta oldukları tuzaklardan ötürü de sıkıntıya düşme."},{"n":71,"t":"\"Eğer doğru sözlülerseniz, bu vaat ne zaman?\" derler."},{"n":72,"t":"De ki: \"Acele isteyip durduğunuzun bir kısmı belki de arkanıza takılmıştır.\""},{"n":73,"t":"Senin Rabbin, insanlara karşı gerçekten lütufkârdır; fakat çokları şükretmezler."},{"n":74,"t":"Ve senin Rabbin, onların göğüslerinin sakladığını da açığa vurduğunu da çok iyi bilir."},{"n":75,"t":"Yerde ve gökte hiçbir gayb yoktur ki, açıklayıcı bir Kitap'ta olmasın."},{"n":76,"t":"Hiç kuşkunuz olmasın ki bu Kur'an, İsrailoğullarına, ihtilafa düştükleri şeylerin birçoğunu anlatıyor."},{"n":77,"t":"Ve elbette o, inananlara bir kılavuz ve rahmettir."},{"n":78,"t":"Rabbin, o İsrailoğulları arasında hükmünü verip gereğini yapacaktır. Azîz'dir, Alîm'dir O."},{"n":79,"t":"Allah'a dayanıp güven, çünkü sen apaçık gerçeğin üzerindesin."},{"n":80,"t":"Sen, ölülere işittiremezsin. Eğer dönüp giderlerse, sağırlara da çağrıyı duyuramazsın."},{"n":81,"t":"Ve sen, düştükleri sapıklıktan körleri de çıkaramazsın. Teslim olmuş kişiler halinde ayetlerimize inananlardan başkasına sesini duyuramazsın."},{"n":82,"t":"O söz tepelerine indiğinde, yeryüzünden onlar için bir dâbbe/debelenir gibi yürüyen bir canlı çıkarırız da o onlara, insanların bizim ayetlerimize gereğince inanmadıklarını söyler."},{"n":83,"t":"O gün her ümmetin içinden ayetlerimizi yalanlayanlardan bir zümre derleriz de onlar, toplu halde ortaya sürülürler."},{"n":84,"t":"Geldiklerinde Allah onlara: \"Ayetlerimizi, ilminiz onları kuşatmadığı halde inkâr mı ettiniz yoksa ne yapıyordunuz?\" der."},{"n":85,"t":"İşledikleri zulümler yüzünden o söz tepelerine inmiştir; artık tek kelime söyleyemezler."},{"n":86,"t":"Görmedin mi; biz geceyi, içinde dinlensinler diye, gündüzü de gösterici bir ışık olsun diye oluşturduk. İşte bunda, inanan bir topluluk için elbette ibretler vardır."},{"n":87,"t":"Sûra üfürüleceği gün, Allah'ın dilediği dışında herkes, göklerdekiler, yerdekiler dehşet içinde kalacaktır. Hepsi boynunu bükmüş bir halde O'nun huzuruna gelir."},{"n":88,"t":"Sen dağlara bakar da onları donuk-durgun görürsün. Oysaki onlar, bulutların dolaştığı gibi dolaşmaktadır. Her şeyi güzel ve yerli yerinde yapan Allah'ın sanatıdır bu! Yaptıklarınızdan gereğince haberdardır O!"},{"n":89,"t":"İyilik ve güzellik getirene, getirdiğinden daha hayırlısı vardır. Onlar o gün korkudan güvene çıkmışlardır."},{"n":90,"t":"Kötülük getirenlerin ise yüzleri ateşte sürtülür. Sadece yapıp ettiklerinizle cezalandırılırsınız."},{"n":91,"t":"\"Ben sadece, bu beldenin Rabbine kulluk etmekle emrolundum. Orayı saygıya layık kılmıştır O. Her şey O'nundur. Ben, müslümanlardan/Allah'a teslim olanlardan olmakla emrolundum.\""},{"n":92,"t":"\"Ve Kur'an okumakla emrolundum. Artık kim yola gelirse kendi nefsi için gelir. Sapmışa gelince, böylesine de ki: 'Ben uyarıcılardan biriyim. Hepsi bu!\""},{"n":93,"t":"Ve şöyle yakar: \"Hamt olsun Allah'a! O size ayetlerini gösterecek de siz onları tanıyacaksınız. Senin Rabbin, yapmakta olduklarınızdan habersiz değildir.\""}],[{"n":1,"t":"Tâ, Sîn, Mîm."},{"n":2,"t":"İşte sana, açık-seçik beyanda bulunan Kitap'ın ayetleri."},{"n":3,"t":"İman edecek bir toplum için, Mûsa ve Firavun'un haberinden bir kısmını sana hak olarak okuyacağız."},{"n":4,"t":"Gerçek şu: Firavun o yerde egemenlik kurmuş ve ora halkını gruplara ayırmıştı. Onlardan bir topluluğu horlayıp eziyordu: Bu topluluğun erkek çocuklarını boğazlıyor, kadınlarına hayasızca davranıyor/kadınların rahimlerini yokluyor/kadınlarını hayata salıyordu. O gerçekten fesadı yayanlardandı."},{"n":5,"t":"Ve biz istiyoruz ki, yeryüzünde ezilip horlananlara bağışta bulunalım, onları önderler yapalım, onları mirasçılar haline getirelim."},{"n":6,"t":"Ve yeryüzünde onlara imkân ve kudret verelim. Firavun'a, Hâman'a ve onların ordularına da korkmakta oldukları şeyleri gösterelim."},{"n":7,"t":"Mûsa'nın annesine şunu vahyettik: \"Emzir onu! Onun aleyhinde bir korku hissedince de nehire bırakıver onu. Korkma, üzülme! Kuşkun olmasın ki, biz onu sana geri döndüreceğiz ve onu resullerden biri yapacağız.\""},{"n":8,"t":"Nihayet, Firavun ailesi onu kayıp bir şey olarak bulup aldı. O, kendileri için bir düşman ve tasa olacaktı. Gerçek olan şu ki Firavun, Hâman ve bunların orduları yanlış yoldaydılar."},{"n":9,"t":"Firavun'un karısı şöyle dedi: \"Benim için de senin için de bir göz aydınlığıdır bu. Öldürmeyin onu, bize yararı olabilir, yahut onu çocuk ediniriz.\" Onlar işin farkında olmuyorlardı."},{"n":10,"t":"Mûsa'nın annesinin kalbi ise bomboş bir halde sabahladı. Eğer inananlardan olması için kalbine bir bağ vermeseydik, onu açığa vuracak bir durumdaydı."},{"n":11,"t":"Annesi, Mûsa'nın kızkardeşine, \"onu izle\" dedi. O da onu kenardan gözledi. Onlarsa işin farkında olmuyorlardı."},{"n":12,"t":"Biz daha önce ona, süt emziren kadınları haram kılmıştık. Bu sırada kızkardeşi dedi ki: \"Onun bakımını sizin için üstlenecek, onu eğitip öğretmeyi yüklenecek bir ev halkını size tanıtayım mı?\""},{"n":13,"t":"Nihayet Mûsa'yı öz anasına geri çevirdik ki, o ananın göze aydın olsun, kederlenmesin ve Allah'ın vaadinin hak olduğunu bilsin. Fakat çokları bunu bilmezler."},{"n":14,"t":"Mûsa, yiğitlik çağına ulaşıp olgunlaşınca ona hikmet ve ilim verdik. Biz, güzel düşünüp güzel davrananları böyle ödüllendiririz."},{"n":15,"t":"Halkının habersiz olduğu bir sırada kente girdi. Orada iki adam buldu, dövüşüyorlardı. Bu, Mûsa'nın halkından, şu da düşmanlarındandı. Kendi halkından olan, düşmanından olana karşı Mûsa'dan yardım istedi. Mûsa ona bir yumruk indirdirip işini bitirdi. Dedi: \"Bu yaptığım, şeytanın amellerindendir. İnsanı saptıran açık bir düşmandır o.\""},{"n":16,"t":"\"Rabbim, öz benliğime zulmettim, beni affet\" diye yakardı da Allah onu affetti. Gafûr O'dur, Rahîm O'dur."},{"n":17,"t":"Dedi: \"Rabbim, bana lütfettiğin nimete yemin ederim ki, bir daha suçlulara asla arka çıkmayacağım.\""},{"n":18,"t":"Kentte, korku içinde sabahladı, göz-kulak kesiliyordu. Bir de baktı ki, dün ondan yardım isteyen adam yine onu yardıma çağırıyor. Mûsa ona dedi ki: \"Anlaşıldı, sen, tam azmış bir adamsın.\""},{"n":19,"t":"Mûsa, ikisinin de düşmanı olan adamı yakalamak isteyince o şöyle dedi: \"Dün bir adamı öldürdüğün gibi, bugün de beni mi öldürmek istiyorsun? Sen yeryüzünde zorba olmaktan başka bir şey istemiyorsun. Barışseverlerden olmak gibi bir niyetin yok.\""},{"n":20,"t":"Şehrin öbür ucundan bir adam koşarak geldi. Dedi: \"Ey Mûsa, kentin ileri gelenleri seni öldürmeyi planlıyorlar. Çık buradan! Ben sana öğüt verenlerdenim.\""},{"n":21,"t":"Bunun üzerine Mûsa, oradan korka korka çıktı. Her yanı gözlüyordu. Şöyle yakardı: \"Rabbim, beni şu zalimler topluluğundan kurtar!\""},{"n":22,"t":"Medyen tarafına yönelince şöyle dedi: \"Umarım Rabbim beni isabetli bir yola kılavuzlar.\""},{"n":23,"t":"Medyen suyuna ulaştığında, su başında halktan bir grup gördü. Hayvanlarını suluyorlardı. Biraz ötelerinde çekingen bir halde duran iki kadın fark etti. \"Derdiniz nedir?\" dedi. \"Şu çobanlar çekilip gidinceye kadar biz hayvanlarımızı sulamayız. Üstelik babamız da ileri yaşta bir ihtiyardır.\" dediler."},{"n":24,"t":"Bunun üzerine Mûsa, onların sulama işini yaptı. Sonra gölgeye çekilip şöyle dedi: \"Rabbim, bana indireceğin her nimeti bekleyen bir çaresizim.\""},{"n":25,"t":"Tam o sırada kadınlardan biri, utangaç bir tavırla yürüyerek ona geldi. Dedi: \"Babam, bizim için yaptığın sulamaya karşılık sana birşeyler vermek üzere seni çağırıyor.\" Mûsa gelip ihtiyara hikâyeyi anlatınca, o dedi ki: \"Korkma, artık zalimler topluluğundan kurtuldun.\""},{"n":26,"t":"Kadınlardan biri şöyle dedi: \"Babacağım, ücretle tut onu. Her halde ücretle çalıştırdıklarının en hayırlısı olacak; güçlü, güvenilir biri.\""},{"n":27,"t":"İhtiyar dedi ki: \"Bana sekiz yıl çalışman şartıyla şu iki kızımdan birini sana nikâhlamak istiyorum. Eğer on yıla tamamlarsan, o da senden. Seni zora sürmek gibi bir niyetim yok. Allah dilerse beni, barış ve iyilik sever insanlardan bulacaksın.\""},{"n":28,"t":"Mûsa dedi: \"Bu seninle benim aramda. İki süreden hangisini tamamlasam bana kızıp darılmak yok. Allah, bizim şu konuştuğumuza Vekîl'dir.\""},{"n":29,"t":"Mûsa süreyi bitirip ailesiyle yola çıkınca, Tûr tarafından bir ateş fark etti. Ailesine dedi ki: \"Bekleyin, bir ateş fark ettim. Belki ondan size bir haber getiririm, belki bir ateş koru getiririm de ısınırsınız.\""},{"n":30,"t":"Oraya vardığında o bereketli toprak parçasındaki vadinin sağ tarafından, bir ağaçtan şöyle seslenildi: \"Ey Mûsa! Âlemlerin Rabbi Allah benim, ben!\""},{"n":31,"t":"\"Asanı at!\" Asanın çevik bir yılan gibi titreyip kıvrıldığını görünce gerisin geri döndü; arkaya bile bakmadı. \"Geri dön ey Mûsa, korkma! Güven içinde olanlardansın.\""},{"n":32,"t":"\"Elini koynuna sok, lekesiz bembeyaz çıkıversin. Korkudan açılan kollarını kendine çek. İşte bunlar, Firavun ve kodamanlarına karşı Rabbinden sana güçlü iki kanıttır. Firavun ve yardakçıları yoldan çıkmış bir güruhtur.\""},{"n":33,"t":"Mûsa dedi: \"Rabbim, ben onlardan birini katlettim, bu yüzden beni öldürürler diye korkuyorum.\""},{"n":34,"t":"\"Kardeşim Hârun var ya, o benden lisanca daha etkilidir/benden daha güzel konuşur. Onu da benimle yardımcı olarak gönder ki beni tasdiklesin; beni yalanlamalarından korkuyorum.\""},{"n":35,"t":"Allah buyurdu: \"Pazunu kardeşinle kuvvetlendireceğiz; size öyle bir güç/kanıt vereceğiz ki size ulaşamayacaklar. Ayetlerimize yemin olsun ki, siz ve size uyanlar, galip gelenler olacaksınız.\""},{"n":36,"t":"Bunun ardından Musa onlara açık-seçik ayetlerimizi getirdiğinde onlar şöyle dediler: \"Uydurulmuş bir büyüden bakası değil bu. İlk atalarımız arasında bunu hiç duymadık.\""},{"n":37,"t":"Mûsa dedi ki: \"Katından kimin hidayet getirdiğini ve bu yurdun, sonunda kimin olacağını Rabbim daha iyi bilir. Şu bir gerçek ki zalimler iflah etmezler.\""},{"n":38,"t":"Firavun dedi: \"Ey seçkinler topluluğu! Ben sizin için benden başka bir tanrı tanımıyorum. Ey Hâmân! Benim için çamurun üzerinde ocağı yakıp bana bir kule yap ki Mûsa'nın tanrısına ulaşayım. Aslında ben onun yalancılardan olduğunu sanıyorum.\""},{"n":39,"t":"O ve orduları yeryüzünde haksız yere büyüklük tasladılar ve sandılar ki, bize döndürülmeyecekler."},{"n":40,"t":"Biz de onu ve askerlerini yakalayıp hepsini suyun içine fırlattık. Bak, nasıl oldu zalimlerin sonu!"},{"n":41,"t":"Biz onları, ateşe çağıran önderler yapmıştık. Kıyamet günü yardım göremeyeceklerdir."},{"n":42,"t":"Bu dünya hayatında da arkalarına bir lanet taktık. Kıyamet günü onlar, çirkinleştirilenler arasında olacaklar."},{"n":43,"t":"Yemin olsun biz, ilk nesilleri helak ettikten sonra Mûsa'ya Kitap'ı; insanlar için basîretler, kılavuz ve rahmet olarak verdik ki, düşünüp öğüt alabilsinler."},{"n":44,"t":"Biz Mûsa'ya o emri vahyettiğimizde, sen batı tarafında değildin; olayı izleyenlerden de değildin."},{"n":45,"t":"Ancak biz, birçok nesil oluşturduk da bunlar üzerinden ömürler akıp gitti. Sen Medyen halkı içinde oturarak onlara ayetlerimizi okuyor değildin. Biz, peygamberler gönderiyoruz, hepsi bu."},{"n":46,"t":"Ve sen, biz seslendiğimizde, Tûr tarafında da değildin. Sen, senden önce kendilerine uyarıcı gelmemiş bir toplumu uyarmak için Rabbinden bir rahmetsin. Bu sayede onların düşünüp öğüt almaları umuluyor."},{"n":47,"t":"Kendi ellerinin önden hazırladıkları yüzünden başlarına bir musibet geldiğinde hemen şöyle diyorlar: \"Rabbimiz, bize bir resul gönderseydin de senin ayetlerine uyup müminlerden olsaydık ne olurdu!\""},{"n":48,"t":"Fakat hak, katımızdan kendilerine geldiğinde şöyle dediler: \"Mûsa'ya verilenin aynısı buna da verilseydi ya!\" Bunlar daha önce Mûsa'ya verileni inkâr etmemişler miydi? Şöyle demişlerdi: \"Birbirini destekleyen iki büyü/sırt sırta iki büyücü.\" Ve dediler: \"Biz bunların ikisine de inanmıyoruz.\""},{"n":49,"t":"De ki: \"Eğer doğru sözlü iseniz, Allah katından, bu ikisinden daha aydınlık bir kitap getirin, ben ona uyayım.\""},{"n":50,"t":"Bunun üzerine sana cevap veremezlerse bil ki, onlar sadece iğreti arzularına uyuyorlar. Allah'tan bir kılavuzluk olmaksızın, kendi arzularına uyandan daha sapık kim vardır! Allah, zalimler topluluğunu hidayete erdirmez."},{"n":51,"t":"Yemin olsun, biz onlar için sözü ardarda getirdik ki, düşünüp öğüt alabilsinler."},{"n":52,"t":"Ondan önce kendilerine kitap verdiklerimiz, ona da iman ederler."},{"n":53,"t":"O, onlara okunduğu zaman şöyle derler: \"İnandık buna, Rabbimizden gelmiş haktır o. Biz, ondan önce de müslümanlardık.\""},{"n":54,"t":"İşte böylelerine ödülleri, sabrettikleri için iki kez verilir. Onlar, kötülüğü güzellikle karşılayıp savarlar. Ve onlar, kendilerine verdiğimiz rızıktan infak ederler."},{"n":55,"t":"Boş lakırdıyı duyduklarında, ondan yüz çevirir şöyle derler: \"Bizim amellerimiz bize, sizin amelleriniz size. Selam olsun hepinize. Biz cahilleri önemsemeyiz.\""},{"n":56,"t":"Şu bir gerçek ki, sen istediğin kişiyi doğru yola iletemezsin. Ama Allah, dilediğine kılavuzluk eder. Hidayete erecekleri O daha iyi bilir."},{"n":57,"t":"Dediler ki: \"Eğer seninle birlikte yol alırsak, yerimizden, yurdumuzdan oluruz.\" Biz onları, katımızdan rızık olarak gelen tüm ürünlerin derlenip toplandığı güvenli, saygıdeğer bir mekâna yerleştirmedik mi? Ama onların çokları bilmiyorlar."},{"n":58,"t":"Yaşayışı şımarıklık ve gösterişe yol açmış nice kenti helâk ettik biz. İşte yerleri yurtları! Onlardan sonra oralarda çok az oturuldu. Biziz Vâris olanlar/mirasçılar, biz!"},{"n":59,"t":"Senin Rabbin, memleketleri/medeniyetleri, ana merkezlerinde kendilerine ayetlerimizi okuyan bir resul göndermedikçe helâk etmez. Biz; ülkeleri/medeniyetleri, halkları zulme sapmadıkları sürece helâk etmeyiz."},{"n":60,"t":"Nasiplendirildiğiniz şeyler şu iğreti hayatın yararından ve süsünden ibarettir. Allah'ın katındaki ise daha hayırlı ve daha süreklidir. Hâlâ aklınızı işletmeyecek misiniz?"},{"n":61,"t":"Kendisine güzel bir vaatte bulunduğumuz, ardından da ona kavuşan kimse, şu iğreti hayatın yararıyla nimetlendirdiğimiz, sonra kıyamet gününde huzurumuza dikilecekler arasına giren kimse gibi midir?"},{"n":62,"t":"O gün onlara seslenerek şöyle diyecek: \"O kendilerini bir şey sandığınız ortaklarım nerede?\""},{"n":63,"t":"Üzerlerine hüküm hak olanlar şöyle diyecekler: \"Rabbimiz, azdırdıklarımız işte şunlar! Kendimiz azdığımız gibi onları da azdırdık. Onlardan uzak olduğumuzu sana arz ediyoruz. Zaten onlar sadece bize kulluk/ibadet etmiyorlardı ki!..\""},{"n":64,"t":"Şöyle denilir: \"Çağırın ortak koştuklarınızı!\" Onlar da çağırırlar. Fakat ötekiler bunlara cevap veremezler; azabı görmüşlerdir. Önceden yola gelselerdi ne olurdu!"},{"n":65,"t":"Allah o gün onlara seslenir de şöyle der: \"Hak elçilerine ne cevap verdiniz?\""},{"n":66,"t":"Artık o gün onlara karşı tüm haberler kör olmuştur. Birbirlerine de bir şey soramazlar."},{"n":67,"t":"Ama tövbe eden, inanıp hayra ve barışa yönelik iş yapan kişinin, kurtuluşa erenlerden olması ümidi vardır."},{"n":68,"t":"Rabbin dilediğini yaratır ve seçer. Seçim onların değil/onların seçme hakkı yok. Allah, onların ortak koştuklarından yücedir, arınmıştır."},{"n":69,"t":"Ve Rabbin onların göğüslerinin neyi sakladığını, neyi açığa vurduğunu da bilir."},{"n":70,"t":"O, Allah'tır! Tanrı yoktur O'ndan başka. İlkte de sonda da hamt yalnız O'nadır. Hüküm de yalnız O'nundur/O'nun içindir. Ve siz yalnız O'na döndürüleceksiniz."},{"n":71,"t":"De ki: \"Söyleyin bakalım, Allah geceyi, kıyamet gününe kadar üzerinizde sürekli kılsa, Allah'tan başka hangi ilah size ışık getirebilir? Hâlâ dinlemeyecek misiniz?\""},{"n":72,"t":"De ki: \"Söyleyin bakalım, eğer Allah kıyamet gününe kadar, gündüzü üzerinizde sürekli tutsa, Allah'tan başka hangi tanrı, içinde sükûnet bulacağınız bir gece verebilir size? Hâlâ görmeyecek misiniz?\""},{"n":73,"t":"Rahmetinin bir eseri olarak geceyi ve gündüzü sizin için oluşturdu ki, onda sükûnet bulasınız, O'nun lütfundan bir şeyler dileyesiniz ve şükredebilesiniz."},{"n":74,"t":"Gün olur, seslenir onlara da şöyle der: \"O, bir şey zannettiğiniz ortaklarım nerede?\""},{"n":75,"t":"Her ümmetten bir tanık çıkarmış da şöyle demişizdir: \"Getirin susturucu kanıtınızı!\" Bunun üzerine onlar hakkın Allah'a ait olduğunu bilmişlerdir. O iftira aracı yaptıkları şeyler de onları yüzüstü koyup kaybolmuşlardır."},{"n":76,"t":"Şu da bir gerçek ki Karun, Mûsa kavmindendi. Onlara karşı şımarıklık/azgınlık yaptı. Ona öyle hazineler vermiştik ki, anahtarlarını taşımak, kuvvetli bir grubu bile zorluyordu. Kavmi ona şöyle demişti: \"Şımarma, çünkü Allah, şımaranları sevmez.\""},{"n":77,"t":"\"Allah'ın sana verdikleri içinde âhiret yurdunu ara, dünyadan da nasibini unutma. Allah'ın sana güzel davrandığı gibi sen de güzel davran/Allah'ın sana lütufta bulunduğu gibi sen de lütufta bulun. Yeryüzünde fesat isteyip durma, çünkü Allah fesat peşinde koşanları sevmez.\""},{"n":78,"t":"O dedi: \"Bu servet bana, bendeki bir ilim sayesinde verildi.\" Peki o bilmedi mi ki Allah, önceki nesiller içinden ondan kuvvetçe daha zorlu, sayıca daha çok olanları bile helâk etmiştir. Günahlarının ne olduğu, günahkârlardan sorulmaz."},{"n":79,"t":"Karun, süsü-püsü içinde toplumunun karşısına çıktı. Şu iğreti dünya hayatını amaçlayanlar dediler ki: \"Ah, Karun'a verilenin bir benzeri bize de verilseydi. Gerçekten o, çok nasipli bir adam!\""},{"n":80,"t":"Kendilerine ilim verilmiş olanlar şöyle demişti: \"Yazıklar olsun size! İman edip hayra ve barışa yönelik iş yapan kişi için Allah'ın vereceği karşılık daha üstündür. Ama buna, sadece sabredenler ulaştırılır.\""},{"n":81,"t":"Nihayet, Karun'u da sarayını da yere geçirdik. Allah'a karşı kendisine yardım edecek yandaşları da yoktu. Kendi kendisine yardım edebileceklerden de değildi."},{"n":82,"t":"Akşam onun mevkiine/konumuna imrenenler sabah şöyle diyorlardı: \"Vay be! Allah, kullarından dilediğine rızkı açıp yayıyor, dilediğine de ölçüyle veriyor/kısıyor. Allah bize lütufta bulunmasaydı, vallahi bizi de batırmıştı. Demek ki, inkârcılar asla iflah etmiyorlar.\""},{"n":83,"t":"İşte âhiret yurdu! Biz onu, yeryüzünde üstünlük taslamayanlarla bozgunculuk peşinde koşmayanlara veririz. Sonuç, takva sahiplerinindir."},{"n":84,"t":"İyilik/güzellik getirene ondan daha hayırlısı var. Kötülük getirenlere gelince, kötülükleri yapanlar yapmış olduklarından fazlasıyla cezalandırılmayacaklardır."},{"n":85,"t":"Bu Kur'an'ı sana farz kılan, elbette ki seni vaat edilen yere/belirlenen sona götürecektir. De ki: \"Hidayeti getireni de açık bir sapıklık içinde olanı da en iyi Rabbin bilir.\""},{"n":86,"t":"Sen bu Kitap'ın sana indirileceği ummuyordun; Rabbinden bir rahmet olarak geldi. O halde, gerçeği örten nankörlere/inkârcılara sakın destekçi olma."},{"n":87,"t":"Allah'ın ayetleri sana indirildikten sonra sakın seni geri çevirmesinler. Rabbine yakar/Rabbine çağır. Sakın şirke bulaşanlardan olma."},{"n":88,"t":"Allah'ın yanında diğer bir tanrıya daha kulluk etme. İlah yok O'ndan başka. O'nun yüzü dışında her şey helâk olacaktır. Hüküm yalnız O'nundur ve O'na döndürüleceksiniz."}],[{"n":1,"t":"Elif, Lâm, Mîm."},{"n":2,"t":"İnsanlar, inandık demeleriyle kendi hallerine bırakılacaklarını ve hiçbir imtihana çekilmeyeceklerini mi sandılar!"},{"n":3,"t":"Yemin olsun ki biz, onlardan öncekileri de fitne yoluyla denemişizdir. Allah, özüyle sözü bir olanları elbette bilecektir. Ve O, yalancıları da elbette bilecektir."},{"n":4,"t":"Yoksa o kötülükleri sergileyenler bizi geçeceklerini mi sandılar! Ne kötü hüküm veriyorlar!"},{"n":5,"t":"Allah'a kavuşmayı umanlara gelince, şu bir gerçek ki, Allah'ın belirlediği vakit mutlaka gelecektir. O, Semî'dir, Alîm'dir."},{"n":6,"t":"Ve kim didinir, gayret sarfederse hiç kuşkusuz, kendi benliği lehine gayret sarfetmiş olur. Gerçek olan şu ki, Allah, âlemlere muhtaç olmaktan uzak, mutlak bir Ganî'dir."},{"n":7,"t":"İman edip hayra/barışa yönelik hareketler sergileyenlere gelince, biz onların çirkinliklerini elbette ki örteceğiz! Ve biz onları, yapmakta oldukları işlerin en güzeliyle elbette ödüllendireceğiz!"},{"n":8,"t":"Biz insana, anne-babasına en güzel bir biçimde davranmasını, şunu söyleyerek önerdik: \"Eğer onlar, hakkında hiçbir bilgin olmayan bir şeyle bana ortak koşman için seninle çekişirlerse, o takdirde onlara itaat etme. Yalnız banadır dönüşünüz. Nihayet, ben size yapıp-ettiğiniz şeylerin haberini bildireceğim.\""},{"n":9,"t":"İman edip hayra/barışa yönelik eylemler sergileyenlere gelince, biz onları elbette ki iyilik/barış severler arasına koyacağız."},{"n":10,"t":"İnsanlar içinden öylesi vardır ki, \"Allah'a inandık\" der fakat Allah uğrunda bir eziyete uğratılınca, insanlardan gelen fitneyi Allah'ın azabı gibi tutar. Ve eğer Rabbinden bir yardım gelirse kesinlikle şöyle diyeceklerdir: \"Biz sizinle beraberdik.\" Allah, âlemlerin göğüslerindekini en iyi şekilde bilmiyor mu?"},{"n":11,"t":"Allah iman edenleri elbette bilecektir. Ve münafık olanları da elbette bilecektir."},{"n":12,"t":"İnkâr edenler, iman edenlere dediler ki: \"Bizim yolumuzu izleyin, sizin günahlarınızı biz taşırız.\" Oysa onlar, iman edenlerin günahlarından hiçbir şeyin taşıyıcısı değillerdir. Gerçek şu ki, onlar tamamen yalancıdırlar."},{"n":13,"t":"Onlar hem kendi yüklerini hem de kendi yükleriyle beraber başkalarının yüklerini taşıyacaklar. Bunda kuşku yok. Kıyamet günü de iftira edip durdukları şeylerden zorlu bir sorguya mutlaka çekileceklerdir."},{"n":14,"t":"Yemin olsun, biz Nûh'u toplumuna gönderdik de o onların arasında bin yıldan elli yıl eksik kaldı. Sonunda onları tufan yakaladı. Çünkü zalimlerdi onlar."},{"n":15,"t":"Biz, Nûh'u ve gemi halkını kurtardık ve o gemiyi âlemlere ibret yaptık."},{"n":16,"t":"İbrahim'i de gönderdik. Toplumuna şöyle demişti: \"Allah'a kulluk/ibadet edin, O'ndan sakının. Eğer bilirseniz bu sizin için daha hayırlıdır.\""},{"n":17,"t":"\"Allah'ın berisinden; bir takım putlara tapıyorsunuz, yalan/iftira üretiyorsunuz. Sizin Allah dışında kulluk/kölelik ettikleriniz size hiçbir rızık veremezler. Rızkı Allah katında arayın; O'na kulluk edin, O'na şükredin. O'na döndürüleceksiniz.\""},{"n":18,"t":"\"Eğer yalanlarsanız bilin ki, sizden önceki ümmetler de yalanlamıştı. Resule de düşen, açık bir tebliğden başka şey değildir.\""},{"n":19,"t":"Hiç görmediler mi, Allah, yaratmayı nasıl başlatıyor, sonra onu tekrarlıyor/yeni baştan yapıyor. Kuşkusuz bu, Allah için çok kolaydır."},{"n":20,"t":"De ki: \"Yeryüzünde dolaşın da yaratılışın nasıl başladığına bir bakın. İleride Allah öteki oluşmaya da vücut verecektir. Allah, her şeye Kadîr'dir."},{"n":21,"t":"Dilediğine/dileyene azap eder, dilediğine/dileyene rahmet eder. O'na döndürüleceksiniz."},{"n":22,"t":"Siz ne yerde ne de gökte kimseyi âciz bırakamazsınız. Ve sizin, Allah'tan başka ne bir dostunuz vardır ne de bir yardımcınız."},{"n":23,"t":"Allah'ın ayetlerini ve Allah'a varmayı inkâr edenler, işte onlar, rahmetimden ümidi kesmişlerdir. Ve bunlar için acıklı bir azap öngörülmüştür."},{"n":24,"t":"Toplumunun İbrahim'e cevabı sadece şunu söylemeleri oldu: \"Bunu öldürün, yahut yakın!\" Ama Allah onu ateşten kurtardı. İnanan bir toplum için bunda elbette ibretler vardır."},{"n":25,"t":"İbrahim dedi: \"Şu bir gerçek ki, siz dünya hayatında aranızda sevgi oluşturmak için Allah'ın berisinden putlar edindiniz. Sonra, kıyamet gününde birbirinizi tanımaz olacaksınız, bazınız bazınıza lanet edecek. Hepinizin varacağı yer cehennemdir; hiçbir yardımcınız da olmayacaktır.\""},{"n":26,"t":"O'na Lût iman etti. Ve dedi: \"Ben Rabbime hicret edeceğim. Kuşkusuz, O, mutlak Azîz, mutlak Hakîm'dir.\""},{"n":27,"t":"Biz, İbrahim'e İshak'ı ve Yakub'u armağan ettik. Onun soyu içine peygamberliği ve Kitap'ı yerleştirdik ve onun ödülünü dünyada verdik. Âhirette de o, elbetteki iyilik ve barış sevenler arasında olacaktır."},{"n":28,"t":"Lût'u da gönderdik. Toplumuna şöyle demişti o: \"Öyle bir iğrençliğe bulaşıyorsunuz ki, sizden önce âlemlerden bir tek kişi bunu yapmamıştır.\""},{"n":29,"t":"\"Erkeklere gidiyorsunuz, yol kesiyorsunuz, toplantılarınızda çirkinlikler sergiliyorsunuz, öyle mi?\" Toplumunun cevabı sadece şunu söylemek oldu: \"Eğer doğru sözlülerdensen, hadi getir bize Allah'ın azabını!\""},{"n":30,"t":"Lût dedi: \"Rabbim, şu bozguncular topluluğuna karşı bana yardım et.\""},{"n":31,"t":"Elçilerimiz, İbrahim'e müjdeyi getirdiklerinde şöyle dediler: \"Biz şu kentin halkını helâk edeceğiz. Çünkü ora halkı zalim oldular.\""},{"n":32,"t":"İbrahim dedi: \"Ama orada Lût var.\" Dediler: \"Orada kim olduğunu biz daha iyi biliyoruz. Elbette ki onu ve ailesini kurtaracağız. Karısı hariç. O, geride kalanlardan olacak.\""},{"n":33,"t":"Elçilerimiz Lût'a gelince, onlar yüzünden fenalaştı, eli-kolu birbirine dolandı. \"Korkma, tasalanma dediler, biz seni de aileni de kurtaracağız. Ama karın, azaba terk edilenlerden olacaktır.\""},{"n":34,"t":"\"Şu kent halkı üstüne, yaptıkları fenalıklardan ötürü gökten bir felaket indireceğiz.\""},{"n":35,"t":"Yemin olsun, biz o kentten, aklını işleten bir topluluk için geriye apaçık bir işaret bıraktık."},{"n":36,"t":"Medyen'e de kardeşleri Şuayb'ı gönderdik. Şöyle dedi: \"Ey toplumum, Allah'a ibadet edin. Âhiret gününe umut bağlayın. Bozgunculuk yaparak ülkenin huzurunu kaçırmayın.\""},{"n":37,"t":"Onu hemen yalanladılar. Bunun üzerine kendilerini o korkunç sarsıntı/korkunç titreşim yakaladı da öz yurtlarında diz üstü çömelenler haline geldiler."},{"n":38,"t":"Âd'ı, Semûd'u da böyle yaptık. Bu, onların yurtlarından/meskenlerinden açıkça belli olmaktadır. Şeytan onlara amellerini süsleyip püslemişti de kendilerini yoldan çıkarmıştı. Oysaki, bakıp görebilen insanlardı."},{"n":39,"t":"Karun'u, Firavun'u, Hâmân'ı da öyle yaptık. Yemin olsun, Mûsa onlara açık-seçik kanıtlarla geldiği halde, yeryüzünde büyüklük tasladılar. Ama öne geçemezlerdi."},{"n":40,"t":"Her birini kendi günahı ile yakaladık. Bazılarının üstüne taş yağdıran bir kasırga gönderdik. Bir kısmını, o korkunç titreşimli ses yakaladı. Onlardan, yere batırdıklarımız da oldu. Bazılarını da boğduk. Allah onlara zulmedecek değildi. Fakat onlar kendi benliklerine zulmediyorlardı."},{"n":41,"t":"Allah'ın berisinden veliler edinenlerin durumu, bir ev edinen dişi örümceğin durumuna benzer. Ve evlerin en güvensizi/en zayıfı elbette ki, dişi örümceğin evidir. Keşke bilselerdi!"},{"n":42,"t":"Allah, onların, kendisinden başka ne gibi bir şeye yalvardıklarını/nasıl bir şey için çağrı yaptıklarını bilir. O'dur Azîz, O'dur, Hakîm."},{"n":43,"t":"Bunlar bizim, insanlara vermekte olduğumuz örneklerdir ki ilim sahiplerinden başkası onlara akıl erdiremez."},{"n":44,"t":"Allah gökleri de yeri de hak olarak yaratmıştır. Kuşkusuz, bunda, iman sahipleri için mutlak bir mucize vardır."},{"n":45,"t":"Kitap'tan sana vahyedileni oku! Namazı/duayı yerine getir! Çünkü namaz/dua, çirkinliklerden ve kötülüklerden alıkoyar. Elbette ki, Allah'ın zikri/Kur'an'ı daha büyüktür! Allah, neler yaptığınızı biliyor."},{"n":46,"t":"Ehlikitap'la, en güzel olan yöntem dışında bir yolla mücadele etmeyin! Onların zulme sapanları müstesna. Şöyle deyin: \"Bize indirilene de size indirilene de iman ettik; tanrımız ve tanrınız bir. Ve biz O'na teslim olanlarız.\""},{"n":47,"t":"Kitap'ı sana işte böyle indirdik. Kendilerine kitap verdiklerimiz ona inanırlar. Şunlar içinden de ona inananlar vardır. Bizim ayetlerimize, gerçeği örtenlerden başkası kafa tutmaz."},{"n":48,"t":"Sen bundan önce herhangi bir kitap okumuyordun; onu sağ elinle de yazmıyorsun. Eğer öyle olsaydı bâtıla saplananlar mutlaka kuşku duyacaklardı."},{"n":49,"t":"Hayır, o, kendilerine ilim verilenlerin göğüsleri içinde ayan-beyan ayetlerdir. Bizim ayetlerimizi, zalimlerden başka kimse inkâr etmez."},{"n":50,"t":"Dediler ki: \"Ona Rabbinden mucizeler indirilseydi ya!\" De ki: \"Mucizeler Allah katındadır. Bana gelince, ben açıkça uyaran biriyim. Hepsi bu.\""},{"n":51,"t":"Karşılarında okunup duran bir kitabı sana indirmiş olmamız onlara yetmiyor mu? Bunda, inanan bir toplum için elbette ki bir rahmet ve bir öğüt vardır."},{"n":52,"t":"De ki: \"Sizinle benim aramda tanık olarak Allah yeter. Göklerde ne var, yerde ne var biliyor O. Bâtıla iman edip Allah'ı inkâr edenlere gelince, işte onlar hüsrana uğramışların ta kendileridir.\""},{"n":53,"t":"Azabı senden çarçabuk istiyorlar. Eğer belirlenmiş bir süre olmasaydı, azap onlara elbette gelmiş olacaktı. Fakat o, hiç farkında olmadıkları bir sırada kendilerine ansızın geliverecektir. Bunda kuşku yok."},{"n":54,"t":"Azabı senden acele istiyorlar. Oysa cehennem, o küfre sapanları çepeçevre kuşatmış bulunuyor."},{"n":55,"t":"Gün olur, azap onları tepelerinden, ayaklarının altından sarıverir ve der: \"Tadın bakalım, yapıp ettiklerinizi.\""},{"n":56,"t":"Ey benim iman eden kullarım! Hiç kuşkusuz, benim yerkürem geniştir. O halde, yalnız bana kuluk/ibadet edin."},{"n":57,"t":"Her can, ölümü tadacaktır; sonra bize döndürüleceksiniz."},{"n":58,"t":"İman edip hayra ve barışa yönelik işler yapanları, altlarından ırmaklar akan cennetin görkemli odalarına yerleştireceğiz. Sürekli kalacaklardır orada. Ne güzeldir iş yapıp değer üretenlerin ödülü!"},{"n":59,"t":"Onlar ki sabrettiler ve yalnız Rablerine dayanıp güvenmektedirler."},{"n":60,"t":"Nice hayvanlar var, kendi rızkını taşıyamaz. Allah onları da rızıklandırıyor, sizi de. Semî'dir O, Alîm'dir."},{"n":61,"t":"Onlara \"Gökleri ve yeri kim yarattı, Güneş'i ve Ay'ı kim boyun eğdirdi?\" diye sorarsan, mutlaka şöyle diyecekler: \"Allah!\" Peki nasıl döndürülüyorlar?"},{"n":62,"t":"Allah, kullarından dilediğine rızkı açıp yayar da ölçülü verip kısar da. Allah herşeyi çok iyi bilir."},{"n":63,"t":"Onlara, \"Gökten suyu kim indirdi de onunla toprağı ölümünden sonra canlandırdı?\" diye sorsan, mutlaka \"Allah!\" derler. De ki: \"Hamt Allah'adır. Fakat onların çokları akletmiyorlar.\""},{"n":64,"t":"Şu iğreti dünya hayatı, bir eğlence ve oyundan başka şey değil. Âhiret yurduna gelince, asıl hayat işte odur. Ah, bilebilselerdi!"},{"n":65,"t":"Gemiye bindiklerinde, dini Allah'a özgüleyerek yalvarıp yakarırlar. Fakat Allah onları kurtarıp karaya çıkardığında, bir bakmışsın ortak koşuyorlar;"},{"n":66,"t":"Verdiklerimize karşı nankörlük etsinler ve birazcık zevklensinler diye... Yakında bilecekler."},{"n":67,"t":"Görmediler mi ki, çevrelerinde insanlar çarpılıp götürülürken Harem'i güven içinde tuttuk. Hâlâ bâtıla inanıp Allah'ın nimetine nankörlük mü ediyorlar?"},{"n":68,"t":"Yalan düzüp Allah'a iftira eden, yahut kendisine geldiği zaman hakkı yalanlayan kişiden daha zalim kim vardır? Cehennemde değil midir kâfirlerin barınağı?"},{"n":69,"t":"Bizim uğrumuzda didinenleri biz, yollarımıza elbette ulaştıracağız. Allah, güzel düşünüp güzel davrananlarla mutlaka beraberdir."}],[{"n":1,"t":"Elif, Lâm, Mîm."},{"n":2,"t":"Yenilgiye uğratıldı Rûm."},{"n":3,"t":"Yeryüzünün en yakın/en alçak bir yerinde. Ama onlar yengilerinin ardından galip duruma geçecekler,"},{"n":4,"t":"Birkaç yıl içinde. İş/oluş/hüküm, önünde de sonunda da Allah'ındır. Onların galibiyet gününde müminler ferahlayacaklar,"},{"n":5,"t":"Allah'ın yardımıyla. Dilediğine yardım eder O! Azîz'dir, Rahîm'dir O."},{"n":6,"t":"Allah'ın vaadi bu! Allah kendi vaadine ters düşmez. Ne var ki, insanların çokları bilmiyorlar."},{"n":7,"t":"Onlar basit ve iğreti hayattan, bir dış görünüşü bilirler. Ama âhiretten tam bir gaflet içindedirler onlar!"},{"n":8,"t":"Kendi benliklerinin içinde olup bitenleri de mi düşünmediler! Allah gökleri, yeri ve bu ikisi arasındakileri ancak hak üzere ve belirlenmiş bir süreye bağlı olarak yaratmıştır. Şu da bir gerçek ki, insanlardan çokları Rablerine kavuşmayı gerçekten inkâr ediyorlar."},{"n":9,"t":"Yeryüzünde dolaşıp bir bakmıyorlar mı ki, nasıl oldu kendilerinden öncekilerin sonu? Onlar kuvvet yönünden bunlardan daha ağır ve baskındılar. Toprağı eşip deşip didik didik etmişlerdi. Ve yeryüzünü, bunların imar ettiklerinden çok daha fazla imar etmişlerdi. Ve resulleri onlara açık-seçik deliller getirmişti. O halde, Allah onlara zulmediyor değildi. Doğrusu, onlardı öz benliklerine zulmedip duranlar."},{"n":10,"t":"Sonra, o kötülük edenlerin sonu, kötülüklerin en kötüsü oldu. Çünkü onlar, Allah'ın ayetlerini yalanladılar ve onlarla alay ediyorlardı."},{"n":11,"t":"Allah yaratışa başlar, sonra onu varlık alanından çekip tekrar yaratır. En sonunda O'na döndürülürsünüz."},{"n":12,"t":"Kıyametin kopacağı gün, günahkârlar sus-pus olacaklardır."},{"n":13,"t":"Allah'a ortak tuttukları arasından, kendileri için şefaatçılar çıkmayacaktır. Kendi yandaşlarına nankörlük etmektedir onlar."},{"n":14,"t":"Saat gelip çattığı gün, o gün, hepsi birbirinden ayrılacaktır."},{"n":15,"t":"İman edip hayra ve barışa yönelik işler yapanlara gelince, onlar bir bahçe içinde mutlu kılınırlar."},{"n":16,"t":"İnkâr edip ayetlerimizi ve âhiret buluşmasını yalanlayanlara gelince, onlar azabın içinde hazır bulundurulurlar."},{"n":17,"t":"O halde, akşama girdiğinizde de sabaha erdiğinizde de tespih Allah içindir/Allah'ı tespih edin!"},{"n":18,"t":"Göklerde ve yerde hamt da O'na; gün sonunda da öğleye erdiğinizde de."},{"n":19,"t":"Diriyi ölüden çıkarır O, ölüyü diriden çıkarır. Ölümünün ardından toprağa hayat verir. Siz de işte böyle çıkarılacaksınız."},{"n":20,"t":"Onun ayetlerinden biri de sizi, topraktan yaratmış olmasıdır. Sonra siz bir insan türü oldunuz, her tarafa yayılıyorsunuz."},{"n":21,"t":"Onun ayetlerinden biri de sizin için, kendilerine ısınasınız ve aranızda sevgi ve rahmet koysun diye nefislerinizden eşler yaratmasıdır. Bunda, iyice düşünen bir toplum için elbette ayetler vardır."},{"n":22,"t":"Göklerin ve yerin yaratılmasıyla dillerinizin ve renklerinizin farklı olması da O'nun ayetlerindendir. Bunda, ilim sahipleri için elbette ibretler vardır."},{"n":23,"t":"Gece ve gündüz uyumanız, onun lütfundan nasip aramanız da O'nun ayetlerindendir. Bunda, işitebilen bir toplum için elbette ibretler vardır."},{"n":24,"t":"Yine O'nun ayetlerindendir ki O size, korku ve ümit olmak üzere şimşeği gösteriyor; gökten bir su indiriyor da ölümünden sonra toprağı onunla canlandırıyor. Bunda, aklını işleten bir topluluk için elbette mucizeler vardır."},{"n":25,"t":"Göğün ve yerin O'nun emriyle ayakta durması da O'nun ayetlerindendir. Sonra sizi bir çağrıyla davet ettiğinde siz yerden hemen çıkacaksınız."},{"n":26,"t":"Göklerde ve yerde kim varsa O'nundur. Hepsi O'na boyun eğmektedir."},{"n":27,"t":"Yaratmaya ilk başlayan/yaratılanları ilk yaratan O'dur. Sonra onları çevirip yeniden yaratacaktır. Bu O'nun için çok da kolaydır. Göklerde ve yerde en yüce örnekler/en yüce sıfatlar O'nundur. O'dur Azîz, O'dur Hakîm..."},{"n":28,"t":"Size öz benliklerinizden bir örnek verdi: Ellerinizin altında bulunanlarda, size verdiğimiz rızıklarda, sizinle aynı haklara sahip, birbirinizden çekindiğiniz gibi kendilerinden çekineceğiniz ortaklarınız var mı? İşte biz, aklını işletecek bir topluluk için ayetleri böyle açık açık sıralıyoruz."},{"n":29,"t":"Zulme sapanlarsa ilimsiz bir biçimde keyiflerine uymuşlardır. Allah'ın saptırdığına kim yol gösterecek? Böylelerinin yardımcıları yoktur."},{"n":30,"t":"O halde sen yüzünü, bir hanîf olarak dine, Allah'ın insanları üzerinde yarattığı fıtrata çevir. Allah'ın yaratışında değiştirme olamaz. Doğru ve eskimez din işte budur. Fakat insanların çokları bilmiyorlar."},{"n":31,"t":"O'a yönelmiş kişiler olarak O'ndan sakının! Namazı/duayı yerine getirin ve sakın şirke sapanlardan olmayın;"},{"n":32,"t":"Onlardan ki, dinlerini parçalayıp hizipler/fırkalar haline geldiler. Her hizip kendi elindekiyle sevinip övünür."},{"n":33,"t":"İnsanlara bir zorluk dokunduğunda, Rablerine yönelerek O'na yakarırlar. Sonra onlara bir rahmet tattırınca bakarsın ki, içlerinden bir grup Rablerine ortak koşuyor."},{"n":34,"t":"Kendilerine verdiklerimize nankörlük etmek için yaparlar bunu. De ki: \"Eğlenip zevk çatın! Yakında bileceksiniz!\""},{"n":35,"t":"Yoksa onlara kesin bir kanıt mı indirdik de onlara Allah'a ortak koşmalarını söylüyor!"},{"n":36,"t":"İnsanlara bir rahmet tattırdığımızda, onunla ferahlar, şımarırlar. Kendi ellerinin hazırladıkları yüzünden kendilerine bir kötülük gelip çatsa, hemencecik ümitsizliğe düşerler."},{"n":37,"t":"Görmediler mi Allah, dilediğine rızkı genişçe veriyor, dilediğine kısıyor. İnanan bir topluluk için bunda elbette ibretler vardır."},{"n":38,"t":"O halde, akrabaya hakkını ver. Yoksula, yolda kalmışa da. Allah'ın yüzünü isteyenler için bu daha hayırlıdır. İşte böyleleridir, kurtuluşa erenler."},{"n":39,"t":"İnsanların malları içinde artsın diye faizden/riba olarak verdiğiniz şey, Allah katında artmaz. Allah'ın yüzünü/rızasını dileyerek verdiğiniz zekâta gelince, işte onu verenler, kat kat artıranların ta kendileridir."},{"n":40,"t":"Allah'tır ki sizi yaratmış, sonra rızıklandırmıştır. Sonra sizi öldürüyor, sonra diriltiyor. Peki, ortak koştuklarınızdan biri var mı, bunlardan birşeyi yapabilecek! Yücedir, arınmıştır onların ortak koştuklarından O."},{"n":41,"t":"İnsanların ellerinin kazanmış oldukları yüzünden denizde ve karada bozgun çıktı. Allah onlara, yaptıklarının bir kısmını tattırıyor ki geri dönebilsinler."},{"n":42,"t":"De ki: \"Yeryüzünde dolaşın da öncekilerin sonunun nasıl olduğuna bir bakın! Onların çoğu şirke sapan insanlardı.\""},{"n":43,"t":"Allah tarafından ertelenmesi söz konusu olmayan bir günden önce, yüzünü güçlü ve eskimez dine döndür! O gün herkes bölük bölük ayrılacaktır."},{"n":44,"t":"Kim küfre saparsa inkârı kendisi aleyhinedir. Barışa ve hayra yönelik bir iş yapanlarsa, kendi benlikleri için yer hazırlarlar."},{"n":45,"t":"Çünkü Allah, iman edip hayra ve barışa yönelik işler yapanları, öz lütfundan ödüllendirecektir. O, nankörlükleri sevmez."},{"n":46,"t":"O'nun ayetlerindendir ki, size rahmetinden tattırsın; gemiler, buyruğu ile akıp gitsin. Lütfundan nasip arayasınız ve şükredebilesiniz diye, rüzgârları müjdeciler olarak gönderir."},{"n":47,"t":"Yemin olsun biz, senden önce de resulleri toplumlarına gönderdik, onlara açık kanıtlar getirdiler. Nihayet, günah işleyenlerden öc aldık. İnananlara yardım etmek bizim üzerimizde bir haktı."},{"n":48,"t":"O Allah'tır ki, rüzgârları gönderir de onlar, bulutu savurur. Sonra Allah o bulutu gökte dilediği gibi yayıp döşer, onu parça parça eder. Nihayet sen onun arasından yağmurun çıktığını görürsün. Sonra onu kullarından dilediğine ulaştırdığında onlar, müjde almış gibi sevinirler."},{"n":49,"t":"Oysaki onlar, yağmur kendilerine indirilmeden önce iyice suskun ve ümitsiz idiler."},{"n":50,"t":"Artık Allah'ın rahmetinin eserlerine bak, nasıl diriltiyor toprağı ölümü ardından! İşte bu Muhyî, ölüleri elbette diriltir. O, herşeye Kadîr'dir."},{"n":51,"t":"Yemin olsun, bir rüzgâr göndersek de o yeri sararmış görseler, arkasından hiç şaşmadan nankörlük etmeye başlarlar."},{"n":52,"t":"Artık sen, ölülere işittiremezsin. Dönüp gittikleri takdirde sağırlara da çağrıyı duyuramazsın."},{"n":53,"t":"Ve sen körleri de sapıklıklarından aydınlığa çıkaramazsın. Sen ancak, ayetlerimize iman edenlere dinletirsin de onlar müslümanlar/Allah'a teslim olanlar haline geliverirler."},{"n":54,"t":"Allah O'dur ki, sizi bir güçsüzlükten yarattı. Sonra o güçsüzlüğün arkasından bir kuvvet oluşturdu. Sonra o kuvvetin arkasından bir güçsüzlük ve ihtiyarlığa vücut verdi. Dilediğini yaratır. Alîm'dir O, Kadîr'dir."},{"n":55,"t":"Saat gelip kıyamet koptuğu gün, günahkârlar dünyada bir saatten başka kalmadıklarına yemin ederler. Onlar işte böyle çevriliyorlardı."},{"n":56,"t":"İlim ve iman verilenler ise şöyle dediler: \"Yemin olsun, siz, Allah'ın Kitabı gereğince yeniden dirilme gününe kadar kaldınız. İşte bu, yeniden dirilme günüdür. Fakat siz daha önceden bilmiyordunuz.\""},{"n":57,"t":"Zulmetmiş olanlara, özür bildirmeleri o gün yarar sağlamayacak. Onlardan Allah'ı hoşnut etmeleri de istenmez."},{"n":58,"t":"Yemin olsun, biz bu Kur'an'da insanlar için her türlü örneği verdik. Ama onlara bir ayet/mucize getirsen, o inkârcılar mutlaka şöyle diyeceklerdir: \"Siz, batılı savunanlardan başkası değilsiniz!\""},{"n":59,"t":"İlimden nasipsizlerin kalpleri üzerine Allah işte böyle mühür basıyor."},{"n":60,"t":"O halde, sabret! Kuşkun olmasın ki, Allah'ın vaadi haktır. İmanı kemale ermemişler seni hafifliğe sevk etmesinler/seni küçümseyemeyeceklerdir."}],[{"n":1,"t":"Elif, Lâm, Mîm."},{"n":2,"t":"İşte sana, o hikmetlerle dolu Kitap'ın ayetleri."},{"n":3,"t":"İyilik ve güzellik sergileyenlere bir rahmet ve bir kılavuz olarak;"},{"n":4,"t":"Ki onlar namazı/duayı yerine getirirler, zekâtı verirler. Ve onlar âhirete de gözle görmüşçesine inanırlar."},{"n":5,"t":"İşte onlardır Rablerinden bir kılavuzlanma üzere olanlar; işte onlardır gerçek kurtuluşu bulanlar."},{"n":6,"t":"İnsanlardan öylesi vardır ki, Allah yolundan bilgisizce saptırmak için hadis/laf eğlencesi satın alır ve onu alay konusu edinir. İşte böylelerine rezil edici bir azap vardır."},{"n":7,"t":"Ayetlerimiz ona okunduğunda, sanki onları hiç işitmemiş, sanki kulaklarında bir ağırlık var da gururlanmış olarak yüzünü çevirir. Artık ona korkunç bir azabı müjdele!"},{"n":8,"t":"İman edip hayra ve barışa yönelik fiiller sergileyenlere gelince, onlar için nimetlerle dolu cennetler vardır."},{"n":9,"t":"Sürekli kalacaklardır orada. Allah'ın hak vaadidir bu. Azîz'dir, Hakîm'dir O."},{"n":10,"t":"Gökleri direksiz-desteksiz yarattı; görüyorsunuz onları. Ve yeryüzüne, sizi çalkalayıp sendeletmesin diye ağırlıklar, dayanaklar bıraktı ve orada her çeşit hayvanı yaydı. Gökten bir su indirdik de orada her türlü cömert ve bereketli çifti filizlendirdik."},{"n":11,"t":"İşte Allah'ın yaratışı/yarattıkları! Hadi, gösterin bana onun dışındakiler ne yaratmıştır? Hayır, hayır, zalimler açık bir sapıklık içindedirler."},{"n":12,"t":"Yemin osun, biz, Lukman'a şu yolda hikmet verdik: \"Allah'a şükret!\" Şükreden kendisi lehine şükreder. Kim nankörlük ederse Allah Ganî'dir, Hamîd'dir."},{"n":13,"t":"Hani, Lukman, oğluna öğüt vererek şöyle demişti: \"Oğulcuğum, Allah'a ortak koşma! Çünkü Allah'a ortak koşmak, gerçekten büyük bir zulümdür.\""},{"n":14,"t":"Biz, insana anne-babasını önerdik: Annesi onu güçsüzlükle taşımıştır. Sütten kesilmesi de iki yılda olmuştur. O halde bana ve ana-babana şükret. Dönüş banadır."},{"n":15,"t":"Eğer onlar, hakkında hiçbir bilgin olmayan şeyi bana ortak koşman için seni zorlarlarsa, onlara itaat etme. Onlarla dünyada örfe uygun geçin; ama bana yönelenin yoluna uy. Sonunda dönüşünüz banadır. Yapıp ettiklerinizi size haber vereceğim."},{"n":16,"t":"\"Oğulcuğum, şu bir gerçek ki, yaptığın, bir hardal dânesi ağırlığında olsa, bir kayanın bağrına veya göklere, yahut yerin bağrına konsa, Allah onu yine de ortaya getirir. Çünkü Allah Latif'tir, lütfu sınırsızdır; Habîr'dir, her şeyden haberdardır.\""},{"n":17,"t":"\"Yavrucuğum; namazı/duayı yerine getir, iyilik ve güzelliği belirlenene özendir, kötülük ve çirkinliği belirlenenden sakındır, başına gelene sabret. Çünkü bunu yapabilmek, zorlu/önemli işlerdendir.\""},{"n":18,"t":"\"Kibirlenerek insanlardan yüzünü çevirme, yeryüzünde kasılarak yürüme. Çünkü Allah, kurula kurula kendini övenlerin hiçbirini sevmez.\""},{"n":19,"t":"\"Yürüyüşünde doğal ol, sesini alçalt. Şu bir gerçek ki, seslerin en çirkini eşeklerin sesidir.\""},{"n":20,"t":"Görmediniz mi, Allah, göklerde ve yerde bulunan şeyleri sizin emrinize verdi ve görünür-görünmez nimetlerini üstünüze saçtı. İnsanlardan öylesi var ki, Allah uğrunda ilimsiz, kılavuzsuz ve aydınlatıcı bir kitaba dayanmaksızın mücadele eder."},{"n":21,"t":"Böylelerine, Allah'ın indirdiğine uyun dendiğinde şu cevabı verirler: \"Hayır, biz atalarımızı üzerinde bulduğumuz şeye uyarız.\" Peki, şeytan onları, alevli ateşin azabına çağırmış olsa da mı?"},{"n":22,"t":"Güzel düşünüp güzel davranarak yüzünü Allah'a teslim eden, en sağlam kulpa yapışmıştır. İş ve oluşların sonu Allah'a varır."},{"n":23,"t":"İnkâr edenin küfrü seni tasalandırmasın! Onların dönüşü bizedir; yapıp ettiklerini onlara haber vereceğiz. Kuşkusuz, Allah, göğüslerin içindekini bilmektedir."},{"n":24,"t":"Onları birazcık nimetlendiriyoruz. Sonunda hepsini şiddetli bir azaba süreceğiz."},{"n":25,"t":"Eğer onlara, \"Gökleri ve yeri kim yarattı?\" diye sorarsan yemin olsun, \"Allah\" derler. De ki: \"Hamt Allah'adır!\" Ama onların çokları bilmiyorlar."},{"n":26,"t":"Göklerde ne var, yerde ne varsa hepsi Allah'ındır. Kuşkusuz, Allah mutlak Ganî, mutlak Hamîd'dir."},{"n":27,"t":"Eğer yeryüzündeki ağaçlar kalem olsa, deniz de arkasında yedi deniz daha katılarak yardımcı olsa, Allah'ın kelimeleri tükenmez. Allah Azîz'dir, Hakîm'dir."},{"n":28,"t":"Sizin yaratılmanız da diriltilmeniz de bir tek canlınınki gibidir. Allah Semî'dir, Basîr'dir."},{"n":29,"t":"Görmedin mi, Allah geceyi gündüzün içine sokuyor, gündüzü de gecenin içine sokuyor. Güneş'i ve Ay'ı bir emre boyun eğdirmiş. Hepsi belirlenmiş bir süreye doğru akıp gidiyor. Kuşkusuz, Allah, yapmakta olduklarınızdan haberdardır."},{"n":30,"t":"Bu böyledir; çünkü Allah, Hakk'ın ta kendisidir. O'nun berisinde yalvarıp yakardıkları ise bâtıldır. Ve Allah Aliyy'dir, yüceliğine sınır yoktur; Kebîr'dir, büyüklüğüne sınır yoktur."},{"n":31,"t":"Size, ayetlerinden göstermek için, Allah'ın nimetleriyle gemilerin denizde akıp gidişini görmedin mi? Kuşkusuz, bunda gereğince sabreden, gereğince şükreden herkes için kesin ibretler vardır."},{"n":32,"t":"Kara bulutlar gibi dalga kendilerini kuşattığı zaman; Allah'a, dini O'na özgüleyerek yalvarırlar. Fakat onları karaya çıkarıp kurtarınca, içlerinden sadece bir kısmı doğru yolu tutar. Bizim ayetlerimize, gaddar nankörlerin tümünden başkası karşı çıkmaz."},{"n":33,"t":"Ey insanlar! Rabbinizden korkun! Herhangi bir şeyde babanın, evladı; evladın da babası yerine karşılık ödemeyeceği günden ürperin! Allah'ın vaadi haktır; dünya hayatı sizi sakın aldatmasın. O yaman aldatıcı, sakın sizi Allah ile aldatmasın!"},{"n":34,"t":"O kıyamet saatine ilişkin bilgi Allah katındadır. Yağmuru O yağdırır. O, rahimlerde olanı da bilir. Hiçbir benlik yarın ne kazanacağını bilmez. Ve hiçbir kimse hangi yerde öleceğini bilmez. Allah Alîm'dir, Habîr'dir."}],[{"n":1,"t":"Elif, Lâm, Mîm."},{"n":2,"t":"Kitap'ın indirilişidir bu. Kuşku, çelişme yok bunda. Âlemlerin Rabbi'ndendir bu."},{"n":3,"t":"Yoksa \"Onu uydurdu\" mu diyorlar?! Hayır, haktır o; senin Rabbindendir; senden önce kendilerine hiçbir uyarıcı gelmemiş bir toplumu uyarman içindir. Umulur ki, doğruya ve güzele kılavuzlanırlar."},{"n":4,"t":"Allah'tır ki gökleri, yeri ve ikisi arasındakileri altı günde yaratmış, sonra arş üzerinde egemenlik kurmuştur. O'nun dışındakilerden size ne bir dost vardır ne de bir şefaatçı. Hâlâ düşünüp ibret almayacak mısınız?"},{"n":5,"t":"İş ve oluşu gökten yere doğru çekip çevirir; sonra o O'na yükselip çıkar: Bir günde ki, süresi, sizin saymakta olduğunuz günlerden bin yıla denktir."},{"n":6,"t":"İşte budur Allah! Gaybı da görüneni de bilen O'dur. Azîz'dir o, Rahîm'dir."},{"n":7,"t":"O, odur ki, yarattığı her şeyi güzel yarattı. Ve insanın yaratılışına çamurdan başladı."},{"n":8,"t":"Sonra onun neslini bir üsareden, hor görülen bir sudan oluşturdu."},{"n":9,"t":"Sonra ona bir biçim verdi ve onun içine kendi ruhundan üfledi. Sizin için, işitme gücü, gözler ve gönüller vücuda getirdi. Ne kadar da az şükredersiniz!"},{"n":10,"t":"Şöyle dediler: \"Toprakta kaybolup gittiğimiz zaman mı, o zaman mı yeni bir yaratılış içinde olacağız!\" Gerçek şu ki, onlar her şeyden önce, Rablerinin huzuruna varmayı inkâr ediyorlar."},{"n":11,"t":"Söyle onlara: \"Size vekil edilen ölüm meleği canınızı alır, sonra doğrudan doğruya Rabbinize döndürülürsünüz.\""},{"n":12,"t":"Günahkârları, Rablerinin huzurunda başlarını eğmiş olarak şöyle derken bir görsen: \"Rabbimiz; gördük, duyduk, geri gönder bizi ki, barışa/hayra yönelik iyi iş yapalım. Artık kesin olarak inanıyoruz.\""},{"n":13,"t":"Biz dileseydik, her benliğe hidayetini elbette verirdik. Fakat benden şu yolda söz hak olmuştur: \"Yemin olsun, cehennemi tamamıyla cinlerden ve insanlardan dolduracağım.\""},{"n":14,"t":"\"Bu gününüzü unutmuş olmanın karşılığını tadın. Kuşkusuz, biz de sizi unuttuk. Yaptıklarınıza karşılık o uzun süreli azabı tadın!\""},{"n":15,"t":"Bizim ayetlerimize o kimseler inanır ki, onlarla kendilerine öğüt verildiğinde, secdelere kapanırlar ve hiç böbürlenmeyerek Rablerine hamt ile tespih ederler."},{"n":16,"t":"Yanları yataklarından uzaklaşır; korku ve ümitle Rablerine dua ederler. Kendilerine verdiğimiz rızıklardan da dağıtırlar."},{"n":17,"t":"Hiç kimse, yaptıklarına karşılık onlar için hangi göz aydınlığının saklandığını bilmez."},{"n":18,"t":"Hiç, bir mümin, bir sapık gibi olur mu? Hayır, eşit olmazlar!"},{"n":19,"t":"İman edip hayra/barışa yönelik işler yapanlara gelince, onlar için, yaptıklarına karşılık olarak barınacakları cennet konakları vardır."},{"n":20,"t":"Sapmış olanların varacakları yerse ateştir. Oradan her çıkmak istediklerinde, oraya geri çevrilirler. Ve şöyle denir onlara: \"Yalanlayıp durduğunuz ateş azabını tadıverin!\""},{"n":21,"t":"Belki dönerler diye, onlara o büyük azaptan ayrı olarak, o küçük azaptan da mutlaka tattıracağız."},{"n":22,"t":"Rabbinin ayetleri kendilerine hatırlatıldıktan sonra onlardan yüz çevirenden daha zalim kim vardır? Suçlulardan mutlaka intikam alacağız biz!"},{"n":23,"t":"Yemin olsun ki, Mûsa'ya kitabı vermiştik. Böyleyken sen ona kavuşacağından kuşkuda olma! Biz onu İsrailoğullarına bir kılavuz yapmıştık."},{"n":24,"t":"Sabrettikleri zaman içlerinden, bizim emrimizle doğru yola ileten önderler çıkarmıştık. Onlar bizim ayetlerimize gereğince inanıyorlardı."},{"n":25,"t":"Kuşkusuz, Rabbin, evet O, ihtilaf edip durdukları hususlarda onların arasını ayıracaktır."},{"n":26,"t":"Evlerinde-yurtlarında dolaşıp durdukları nice nesilleri, kendilerinden önce helâk etmiş olmamız onlara yol göstermedi mi? Kuşkusuz, bunda ibretler vardır. Hâlâ işitmiyorlar mı?"},{"n":27,"t":"Görmediler mi ki, biz, çorak toprağa suyu salıyoruz da onunla ekinler çıkarıyoruz; hem hayvanları yiyor ondan hem kendileri. Hâlâ görmüyorlar mı?"},{"n":28,"t":"Bir de soruyorlar: \"Eğer doğru sözlülerseniz, bu fetih ne zaman?\""},{"n":29,"t":"De ki: \"Fetih günü, küfre sapanlara imanları yarar sağlamayacaktır. Onlara göz açtırılmaz bile.\""},{"n":30,"t":"Artık onlardan yüz çevir ve bekle! Zaten onlar da bekliyorlar."}],[{"n":1,"t":"Ey Peygamber! Allah'tan kork ve küfre batmışlarla münafıklara boyun eğme! Kuşkusuz, Allah Alîm, ve Hakîm'dir."},{"n":2,"t":"Rabbinden sana vahyedilene uy! Allah, yapmakta olduklarınızdan en iyi biçimde haberdardır."},{"n":3,"t":"Allah'a dayanıp güven! Vekil olarak Allah yeter."},{"n":4,"t":"Allah, bir adamın göğüs boşluğunda iki kalp yaratmamıştır. Zıhar yaptığınız eşlerinizi sizin anneniz yapmamıştır, evlatlıklarınızı da sizin oğullarınız kılmamıştır. Bu konularda söylediğiniz sözler, ağızlarınızın bir lakırdısıdır. Allah, hakkı söyler ve O, gerçek yola kılavuzlar."},{"n":5,"t":"Evlatlıklarınızı öz babalarına nispet ederek çağırın! Böyle yapmanız Allah katında adalete daha uygundur. Eğer onların babalarını bilmiyorsanız, o takdirde onlar sizin din kardeşleriniz ve dostlarınızdır. Yanılarak işlediğiniz şeyde, üzerinize günah yoktur; fakat kalplerinizin kastetmiş oldukları müstesna. Ve Allah Gafûr ve Rahîm'dir."},{"n":6,"t":"O peygamber, müminlere öz benliklerinden daha dost, daha yakındır. Onun eşleri de o müminlerin anneleridir. Anne tarafından akraba olanlar da Allah'ın Kitabı'nda, birbirlerine diğer müminlerden ve muhacirlerden daha yakındırlar. Ancak yakın dostlarınız için örfe uygun bir vasiyette bulunmanız müstesnadır. Bu, Kitap'ta satırlara geçirilmiştir."},{"n":7,"t":"Biz, peygamberlerden mîsaklarını almıştık. Senden de mîsak aldık. Nûh'tan, İbrahim'den, Mûsa'dan, Meryem oğlu İsa'dan, bunların hepsinden kuvvetli bir sözleşmeyle mîsak aldık;"},{"n":8,"t":"Ki Allah, özüyle sözü bir olanlardan doğruluklarını sorsun. Küfre batmışlara ise korkunç bir azap hazırlamıştır."},{"n":9,"t":"Ey iman edenler, Allah'ın üzerinizdeki nimetini hatırlayın! Hani, üstünüze ordular gelmişti de biz onların üzerine bir rüzgâr ve sizin görmediğiniz ordular salmıştık. Allah, yapmakta olduklarınızı iyice görmektedir."},{"n":10,"t":"Hani, onlar, üst yanınızdan, alt tarafınızdan size saldırmıştı da gözler kaymış, yürekler gırtlaklara ulaşmıştı. Allah hakkında türlü zanlarda bulunuyordunuz."},{"n":11,"t":"İşte orada müminler belaya uğratılarak imtihan edilmişler ve şiddetli bir zelzeleyle sarsılmışlardı."},{"n":12,"t":"Münafıklarla, kalplerinde maraz olanlar şöyle diyorlardı: \"Allah ve resulü bize, bir aldanıştan başka bir şey vaat etmemiş.\""},{"n":13,"t":"Hani, onlardan bir grup şöyle demişti: \"Ey Yesrib halkı, duracak yeriniz yok, hemen geri dönün!\" İçlerinden bir grup da Peygamber'den izin istiyor: \"İnan olsun, evlerimiz kaygı duyulacak durumda.\" diyorlardı.\" Oysaki evleri kaygı duyulacak durumda değildi; sadece kaçmak istiyorlardı."},{"n":14,"t":"Eğer Medine'nin her yanından üzerlerine gelinseydi de onların kent içinde fitne çıkarmaları istenseydi, onu mutlaka yaparlardı; o konuda fazla gecikmezlerdi."},{"n":15,"t":"Yemin olsun ki, onlar daha önce, geri dönüp kaçmayacaklarına ilişkin Allah'a söz vermişlerdi. Ve Allah'a verilen söz sorumluluk gerektirirdi."},{"n":16,"t":"De ki: \"Eğer ölümden yahut öldürülmekten kaçıyorsanız, kaçmak size hiçbir yarar sağlamaz. Böyle bir durumda sadece azıcık/az bir süre nimetlendirilirsiniz.\""},{"n":17,"t":"De ki: \"Allah size bir kötülük murat eder yahut bir rahmet dilerse, Allah'la aranıza kim girebilir?\" Onlar kendileri için, Allah'tan başka ne bir dost bulabilirler ne de bir yardımcı."},{"n":18,"t":"Allah, içinizden hem tembellik edip hem de başkalarını geri bırakanları ve kardeşlerine, \"Hadi bize gelin!\" diyenleri biliyor. Zaten onlar savaşa/zora çok az gelirler."},{"n":19,"t":"Size karşı cimrilik/kıskançlık ederler. Korku geldiğinde onları sana bakar halde görürsün. Korku gittiğinde ise hayra karşı kıskançlık yüzünden sizi keskin dillerle yaralarlar. Ölümden üzerine baygınlık çökmüş biri gibidirler. Bunlar iman etmemişlerdir. Bu yüzden de Allah, amellerini boşa çıkarmıştır. Bunu yapmak Allah için çok kolaydır."},{"n":20,"t":"Düşman hiziplerin gitmediğini sanıyorlar. Düşman hizipler gelecek olsalar, bunlar isterler ki, Bedevî Araplar içinde bulunsunlar da sizinle ilgili haberleri sorsunlar. Şayet içinizde bulunsalardı, pek azı müstesna, savaşmayacaklardı."},{"n":21,"t":"Yemin olsun, Allah resulünde sizin için, Allah'ı ve âhiret gününü arzu edenlerle Allah'ı çok ananlara güzel bir örnek vardır."},{"n":22,"t":"Müminler, düşman hizipleri gördüklerinde şöyle demişlerdir: \"Allah'ın ve resulünün bize vaat ettiği işte budur. Ve Allah da resulü de doğru sözlüdür.\" Bu onların sadece iman ve teslimiyetlerini artırdı."},{"n":23,"t":"İnananlardan öyle erler vardır ki, Allah'a verdikleri sözde sadakatle dururlar. Onlardan bazısı adadığını yerine getirdi, bazısı da bekliyor. Sözlerini asla değişmediler."},{"n":24,"t":"Çünkü Allah, doğru sözlülere doğruluklarının karşılığını verecek. İkiyüzlülere de dilerse azap edecek. Belki de onlara tövbe nasip edecek. Allah Gafûr'dur, Rahîm'dir."},{"n":25,"t":"Allah, küfre sapanları öfkeleriyle yüz geri etti; hiçbir hayra ulaşamadılar. Allah, çarpışma sırasında müminler için yeterli oldu. Allah Kavî'dir, Azîz'dir."},{"n":26,"t":"Allah, Ehlikitap'tan onlara arka çıkanları, kulelerinden/kalelerinden indirdi, kalplerine korku saldı: Bir grubunu öldürüyordunuz, bir grubunu da esir ediyordunuz."},{"n":27,"t":"Onların topraklarını, yurtlarını, mallarını ve henüz ayak basmadığınız bir toprağı size miras kıldı. Allah, her şeye kadirdir."},{"n":28,"t":"Ey Peygamber, eşlerine şöyle söyle: \"Eğer şu iğreti dünya hayatını ve onun süsünü istiyorsanız, haydi gelin size boşanma bedellerinizi vereyim de sizi güzellikle serbest bırakayım.\""},{"n":29,"t":"\"Yok eğer Allah'ı, resulünü ve âhiret yurdunu istiyorsanız bilin ki, Allah sizin güzel düşünüp güzel hareket edenlerinize büyük bir ödül hazırlamıştır."},{"n":30,"t":"Ey peygamber hanımları! Sizden kim açık/kanıtlanmış bir edepsizlik yaparsa, kendisi için azap iki katına çıkarılır. Ve bu, Allah için çok kolaydır."},{"n":31,"t":"Sizden kim, Allah'a ve resulüne itaat eder, iyilik yaparsa, ona da ücretini iki kat olarak veririz. Kendisi için bol ve bereketli bir rızık da hazırlamışızdır."},{"n":32,"t":"Ey peygamber hanımları! Siz, kadınlardan herhangi biri gibi değilsiniz. Eğer korunup takvaya sarılıyorsanız sözü kırıtarak söylemeyin ki, kalbinde maruz bulunan biri ümide kapılmasın. Örfe uygun söz söyleyin."},{"n":33,"t":"Evlerinizde de vakarlı oturun. İlk cahiliye teşhirciliği gibi kendinizi teşhir etmeyin. Namazı/duayı yerine getirin, zekâtı verin, Allah'a ve resulüne itaat edin. Allah sizden kiri/lekeyi gidermek istiyor ey Ehlibeyt, sizi tam bir biçimde temizlemek istiyor."},{"n":34,"t":"Evlerinizde Allah'ın ayetlerinden ve hikmetten okunanları hatırlayın. Kuşkusuz, Allah Latîf'tir, Habîr'dir."},{"n":35,"t":"Allah şu kişiler için bir affediş ve büyük bir ödül hazırlamıştır: Müslüman erkekler, Müslüman kadınlar, mümin erkekler, mümin kadınlar, itaat eden erkekler, itaat eden kadınlar, özü-sözü doğru erkekler, özü-sözü doğru kadınlar, sabreden erkekler, sabreden kadınlar, Allah korkusuyla ürperen erkekler, Allah korkusuyla ürperen kadınlar, sadaka veren erkekler, sadaka veren kadınlar, oruç tutan erkekler, oruç tutan kadınlar, ırz ve iffetlerini koruyan erkekler, ırz ve iffetlerini koruyan kadınlar, Allah'ı çok anan erkekler, Allah'ı çok anan kadınlar."},{"n":36,"t":"Allah ve resulü bir işte hüküm verdiklerinde, inanmış bir erkekle inanmış bir kadının, işlerini kendi isteklerine göre belirleme hakları yoktur. Allah'a ve resulüne isyan eden, açık bir sapıklığa batıp gitmiş demektir."},{"n":37,"t":"Hani sen Allah'ın nimetlendirdiği, senin de lütufta bulunduğun kişiye \"Eşini yanında tut, Allah'tan kork!\" diyordun ama, Allah'ın açıklayacağı bir şeyi de içinde saklıyordun; insanlardan çekiniyordun. Oysaki kendisinden korkmana Allah daha layıktır. Zeyd o kadından ilişiğini kesince onu sana nikâhladık ki, evlatlıkları eşleriyle ilişkilerini kestiklerinde, müminler için o kadınlarla evlenmede bir güçlük olmasın. Zaten Allah'ın emri yerine getirilmiştir."},{"n":38,"t":"Allah'ın kendisine farz kıldığı şeyde peygambere hiçbir vebal yoktur. Daha önce gelip geçmişlerde de Allah'ın yolu-yöntemi buydu. Allah'ın emri, belirlenmiş bir kaderdir/ölçüdür."},{"n":39,"t":"Onlar ki Allah'ın mesajlarını tebliğ edip O'ndan korkarlar, Allah'tan gayrı hiç kimseden korkmazlar. Hesap sorucu olarak Allah yeter."},{"n":40,"t":"Muhammed, sizin erkeklerinizden hiçbirinin babası değildir; O, Allah'ın resulü ve nebilerin sonuncusudur. Allah herşeyi gereğince biliyor."},{"n":41,"t":"Ey iman edenler! Allah'ı çok anın!"},{"n":42,"t":"O'nu sabah-akşam tespih edin!"},{"n":43,"t":"O, odur ki sizi karanlıklardan aydınlığa çıkarsın diye size acıyor/destek veriyor. Melekleri de öyle yapıyor. Zaten O, inananlara karşı çok merhametlidir."},{"n":44,"t":"Kendisine kavuştukları gün onların esenlik dilekleri şöyledir: \"Selam!\" O, onlar için seçkin ve bereketli bir ödül hazırlamıştır."},{"n":45,"t":"Ey Peygamber! Hiç kuşkusuz, biz seni bir tanık bir müjdeci ve bir uyarıcı olarak gönderdik."},{"n":46,"t":"Ve Allah'ın izniyle bir davetçi, ışık saçan bir kandil olarak..."},{"n":47,"t":"Ve muştula inananlara: Kendilerine Allah'tan büyük bir lütuf vardır."},{"n":48,"t":"İnkârcılara, ikiyüzlülere itaat etme, onların ezalarına aldırma; Allah'a tevekkül et. Vekil olarak Allah yeter."},{"n":49,"t":"Ey iman edenler! Mümin kadınları nikâhlayıp da kendilerini, onlara dokunmadan boşarsanız, sizin belirleyeceğiniz bir iddet boyunca onları bekletme hakkınız yoktur. O halde, böyle durumlarda onları nimetlendirin ve kendilerini güzelce serbest bırakın."},{"n":50,"t":"Ey Peygamber! Biz sana şu hanımları helal kıldık: Mehirlerini verdiğin eşlerin, Allah'ın sana ganimet olarak verdiklerinden elinin altında bulunanlar, amcalarının, halalarının, dayılarının, teyzelerinin kızlarından seninle birlikte hicret edenler. Peygamber kendisiyle evlenmek istediğinde, kendisini Peygamber'e hibe eden mümin bir kadını da öteki müminlere değil, yalnız sana özgü olmak üzere helal kıldık. Onlara eşleri ve elleri altındakiler hakkında neler farz kıldığımızı biz biliriz. Sana bir zorluk olmasın diyedir bu... Allah Gafûr'dur, Rahîm'dir."},{"n":51,"t":"Onlardan dilediğini geriye bırakırsın, dilediğini yanına alırsın. Bir süre için uzaklaştığın hanımlarından dilediğini yanına almanda bir sakınca yoktur. Onların gözlerinin aydınlanmasında, tasalanmalarında ve kendilerine verdiğinle hepsinin hoşnut olmasında bu daha uygun bir yoldur. Allah sizin kalplerinizde olanı bilir. Allah Alîm'dir, Halîm'dir."},{"n":52,"t":"Bundan sonra sana artık başka kadınlar helal olmaz. Bunları, başka eşlerle değiştirmek de -onların güzellikleri hoşuna gitse bile - helal olmaz. Elinin sahip olabilecekleri müstesna. Allah her şey üzerinde bir Rakîb'dir, her şeyi gözetlemektedir."},{"n":53,"t":"Ey iman edenler! Size bir yemek için izin verilmedikçe Peygamber'in evlerine girmeyin. Vaktini bekleyip durmaksızın çağırıldığınızda girin, ancak yemeği yiyince hemen dağılın. Söze dalıp lafı koyulaştırmayın. Çünkü böyle davranmanız Peygamber'i rahatsız eder. Fakat o size bir şey söylemekten utanır. Allah ise hakkı dile getirmekten çekinmez. Peygamber'in eşlerinden bir şey istediğinizde, onlardan perde arkasından isteyin. Bu, hem sizin kalpleriniz hem de onların kalpleri için daha temiz bir yoldur. Allah'ın resulüne rahatsızlık vermeniz ve kendisinden sonra onun eşleriyle nikâhlanmanız, size helal kılınmamıştır. Böyle bir şey Allah katında büyük bir vebaldir."},{"n":54,"t":"Siz birşeyi açıklasanız da gizleseniz de Allah bunların tümünü bilmektedir."},{"n":55,"t":"Peygamber'in hanımlarına; babaları, oğulları, kardeşleri, erkek kardeşlerinin oğulları, kızkardeşlerinin oğulları, hizmetindeki kadınlar ve anlaşmalarıyla sahip olduklarından ötürü hiçbir günah yoktur. Allah'tan korkun, ey Peygamber hanımları! Kuşkusuz, Allah her şeye tanıklık etmektedir."},{"n":56,"t":"Şu bir gerçek ki, Allah ve melekleri, o Peygamber'e destek verirler/onun şanını yüceltirler. Ey inananlar! Siz de ona destek olun/onun şanını yüceltin ve ona içtenlikle selam verin."},{"n":57,"t":"Allah'ı ve resulünü incitenleri Allah dünyada da âhirette de lanetlemiştir. Onlar için, alçaltıcı bir azap da hazırlanmıştır."},{"n":58,"t":"Mümin erkeklerle mümin kadınları, yapmadıkları bir şeyden dolayı rahatsız edenler, bir iftira ve açık bir günah yüklenmişlerdir."},{"n":59,"t":"Ey Peygamber! Eşlerine, kızlarına ve müminlerin kadınlarına söyle, dış giysilerini üzerlerine alsınlar. Bu, onların tanınmaları ve incitilmemeleri için çok daha uygun bir yoldur. Allah Gafûr'dur, Rahîm'dir."},{"n":60,"t":"İkiyüzlüler, kalplerinde maraz bulunanlar, şehirde çirkin haberler yayanlar, bu yaptıklarına son vermezlerse, seni onların üzerine gitmeye elbette teşvik edeceğiz. Bundan sonra onlar, orada senin yakınında, çok az kalabilirler."},{"n":61,"t":"Lanetlenmiş hale gelirler. Rastlandıkları yerde enselenirler, öldürülür de öldürülürler."},{"n":62,"t":"Bu, Allah'ın daha önce gelip geçmişlede işleyen tavrı-tarzıdır. Allah'ın tavrında herhangi bir değişiklik asla bulamazsın."},{"n":63,"t":"İnsanlar sana kıyametin saatinden soruyorlar. De ki: \"Ona ilişkin bilgi Allah katındadır.\" Ne bilirsin, belki de o saat yakındır!"},{"n":64,"t":"Hiç kuşkusuz, Allah, inkârcıları lanetlemiş ve onlar için çılgın bir ateş hazırlamıştır."},{"n":65,"t":"Uzun süre kalacaklardır onun içinde. Ne bir dost bulacaklardır ne bir yardımcı."},{"n":66,"t":"Gün olur, yüzleri ateşin içinde evrilip çevrilir de şöyle derler: \"Vay başımıza! Keşke Allah'a itaat etseydik, keşke resule itaat etseydik.\""},{"n":67,"t":"Ve derler ki: \"Rabbimiz! Biz, efendilerimize, büyüklerimize itaat ettik de bizi yoldan saptırdılar.\""},{"n":68,"t":"\"Rabbimiz, onlara iki kat azap ver; onları büyük bir lanetle lanetle!\""},{"n":69,"t":"Ey iman edenler! Mûsa'ya eziyet edenler gibi olmayın! Allah, Mûsa'yı onların dediğinden uzak tutmuştur. O, Allah katında olumlu, itibarlı bir kul idi."},{"n":70,"t":"Ey iman edenler! Allah'tan sakının ve sağlam söz söyleyin!"},{"n":71,"t":"Ki Allah amellerinizi barışa/hayra yarayışlı kılsın, günahlarınızı affetsin. Allah'a ve O'nun resulüne itaat eden, büyük bir başarı elde etmiştir."},{"n":72,"t":"Biz emâneti göklere, yere, dağlara teklif ettik de onlar onu yüklenmekten kaçındılar, ondan ürktüler. İnsan ise çok zalim ve çok cahil olduğu halde onu yüklendi."},{"n":73,"t":"Bunun böyle olması, Allah'ın; ikiyüzlü erkeklerle ikiyüzlü kadınlara, şirke sapmış erkeklerle şirke sapmış kadınlara azap etmesi, mümin erkeklerle mümin kadınların tövbelerini kabul etmesi içindir. Allah Gafûr'dur, Rahîm'dir."}],[{"n":1,"t":"Hamt, göklerde ve yerde bulunanlar kendisine ait olan Allah'adır. Ölüm ötesi âlemde de hamt yalnız O'nadır. Hakîm'dir O, Habîr'dir."},{"n":2,"t":"Yerin içine gireni, oradan çıkanı, gökten ineni, oraya yükseleni o bilir. Rahîm'dir O, Gafûr'dur."},{"n":3,"t":"Küfre sapanlar şöyle dediler: \"Kıyamet saati bize gelmez!\" De ki: \"Hayır, öyle değil! Gaybı bilen Rabbime yemin olsun ki, o size mutlaka ve mutlaka gelecektir! Göklerde ve yerde zerre miktarı bir şey bile Rabbimden gizli kalmaz. Zerreden daha küçük veya daha büyük hiçbir istisna olmamak üzere, her şey apaçık bir Kitap'ta belirlenmiştir;"},{"n":4,"t":"Ki Allah, iman edip hayra ve barışa yönelik işler sergileyenleri ödüllendirsin. İşte bunlar için bir bağışlanma ve kutlu-bereketli bir rızık vardır.\""},{"n":5,"t":"Ayetlerimizi hükümsüz kılmak uğruna koşuşup duranlar var ya, onlar için pislikten, inletici bir azap vardır."},{"n":6,"t":"Kendilerine ilim verilenler, Rabbinden sana indirilenin, hakkın ta kendisi olduğunu, Hamîd ve Azîz olan Allah'ın yoluna kılavuzladığını görürler."},{"n":7,"t":"Küfre batanlar şöyle dedi: \"Dağılıp parçalandığınızda, kesinlikle yepyeni bir yaratılış içinde olacağınız yolunda, peygamberce haberler veren bir adamı size gösterelim mi?\""},{"n":8,"t":"\"Yalan düzüp Allah'a iftira mı ediyor, yoksa çıldırmış mı bu?\" Hayır, söyledikleri gibi değil! Gerçek şu ki, âhirete inanmayanlar, dönüşü olmayan bir sapıklık ve bir azap içindedirler."},{"n":9,"t":"Onlar, önlerinde ve arkalarında, gökten ve yerden neler var, görmediler mi? Dilesek onları yere batırırız, ya da üzerlerine gökten parçalar düşürürüz. Hiç kuşkusuz, bütün bunlarda Allah'a yönelen her kul için mutlak bir ibret vardır."},{"n":10,"t":"Yemin olsun, biz, Dâvud'a katımızdan bir lütufta bulunduk. \"Ey dağlar, onunla birlikte tespih edin ve ey kuşlar siz de.\" dedik. Ve onun için demiri yumuşattık."},{"n":11,"t":"Geniş ve uzun zırhlar yap! Dokumasında titiz davran! Siz de hayra ve barışa yönelik iş yapın. Kuşkusuz, ben, yaptıklarınızı görüyorum."},{"n":12,"t":"Süleyman için de sabah gidişi bir ay, akşam dönüşü bir ay olan rüzgârı görevlendirdik. Onun için erimiş katran/bakır kaynağını sel gibi akıttık. Cinlerden öylesi vardı ki, Rabbinin izniyle onun önünde iş yapardı. Onlardan hangisi buyruğumuzdan yan çizse, alevli ateş azabını kendisine tattırdık."},{"n":13,"t":"Onlar Süleyman için, mihraplardan/kalelerden, heykellerden, havuzlar gibi çanaklardan, yerinden kaldırılamaz kazanlardan ne dilerse yaparlardı. Ey Davûd ailesi, şükür olarak iş yapın! Kullarım içinden şükredenler o kadar az ki!"},{"n":14,"t":"Sonunda, Süleyman için ölüm hükmünü verdiğimizde, onun ölümünü, değneğini yiyen dâbbetül arzdan/ağaç kurtçuğundan başkası onlara göstermedi. Süleyman yere yığılınca, açıkça anlaşıldı ki, eğer cinler gaybı bilmiş olsalardı, o alçaltıcı azap içinde bekleyip durmazlardı."},{"n":15,"t":"Yemin olsun, Sebe' için kendi meskenlerinde bir ibret vardı. Sağ ve soldan iki bahçe. Rabbinizin rızkından yiyin de O'na şükredin. Tertemiz bir belde ve affeden bir Rab..."},{"n":16,"t":"Ne var ki onlar yüz çevirdiler; biz de üzerlerine Arim selini gönderdik. Onların iki bahçesini, buruk yemişli, acı ılgınlı, birazcık da sedir ağacı bulunan iki bahçeye çevirdik."},{"n":17,"t":"İşte böyle! Nankörlük ettikleri için onları cezalandırdık. Nankörden başkasına ceza verir miyiz hiç!"},{"n":18,"t":"Biz onlarla, içini bereketle doldurduğumuz kentler arasında, sırt-sırta vermiş kasabalar oluşturduk; Bunlar arasında gidiş-gelişler belirledik. \"Geceleri ve gündüzleri, güven içinde gezip dolaşın oralarda.\" dedik."},{"n":19,"t":"Ama onlar, tutup şöyle dediler: \"Rabbimiz, seferlerimizin arasını uzaklaştır!\" Böylece kendilerine zulmettiler de biz de onları efsaneler haline getirdik; hepsini darmadağın ettik. İşte bunda, gereğince sabreden, yeterince şükreden herkes için elbette ibretler vardır."},{"n":20,"t":"Yemin olsun, İblis onlarla ilgili sanısında isabet etti. İnananlardan bir grup dışındakiler ona uydular."},{"n":21,"t":"Oysaki onun, onlar üzerinde hiçbir sultası yoktu. Sadece biz; âhirete inananı, onun hakkında kuşkuya düşenden ayırmak için böyle yapıyorduk. Rabbin herşey üzerinde Hafiz'dir, kollar, korur, gözetir."},{"n":22,"t":"De ki: \"Allah dışındaki o bir şey sandıklarınızı çağırın/onlara yalvarın! Ama onlar, göklerde de yerde de zerre kadar bir şeye sahip olamazlar. O göklerde ve yerde onların ortaklığı da yoktur. Ve O'nun onlardan bir destekçisi de yoktur.\""},{"n":23,"t":"O'nun katında, bizzat kendisinin izin verdiği kimseden başkasının şefaatı/kendisinin izin verdiği kimseden başkası için şefaat yarar sağlamaz. Sonunda, kalplerinden korku giderilince: \"Rabbimiz ne dedi?\" derler. \"Hakkı söyledi, O'dur Aliyy, O'dur Kebîr.\""},{"n":24,"t":"De ki: \"Göklerden ve yerden sizi kim rızıklandırıyor?\" De ki: \"Allah! O halde biz yahut siz ya tam hidayet üzerindeyiz yahut açık bir sapıklık içinde.\""},{"n":25,"t":"De ki: \"Bizim işlediğimiz suçlardan siz sorumlu olmayacaksınız; biz de sizin yaptıklarınızdan sorguya çekilmeyeceğiz.\""},{"n":26,"t":"De ki: \"Rabbimiz hepimizi biraraya toplayacak, sonra da aramızı hak ile ayıracak. O'dur Fettâh, O'dur Alîm.\""},{"n":27,"t":"De ki: \"Ortaklar olarak O'nun yanına koymaya kalktıklarınızı bana gösterin! Hayır, iş sandığınız gibi değil! O, Allah'tır; Azîz'dir, Hakîm'dir.\""},{"n":28,"t":"Biz seni, bütün insanlara bir müjdeci ve uyarıcı olarak gönderdik, başka değil! Ama insanların çokları bilmiyorlar."},{"n":29,"t":"Diyorlar: \"Doğru sözlülerseniz, bu tehdit ne zaman?\""},{"n":30,"t":"De ki: \"Size bir gün vaat edilmiştir; ondan ne bir saat geri kalabirsiniz ne de ileri geçebilirsiniz.\""},{"n":31,"t":"Küfre sapanlar dedi ki: \"Biz, bu Kur'an'a da bundan öncekine de asla inanmayacağız!\" Ah, bir görsen o zalimleri Rableri huzurunda, tutuklanmış halde! Bir kısmı da bir kısmına söz atar durur. Basit görülüp horlananları, büyüklük taslayanlara şöyle derler: \"Siz olmasaydınız, vallahi biz inanacaktık!\""},{"n":32,"t":"Büyüklük taslayanları ise basit görülüp horlananlara şöyle derler: \"Hidayet size geldikten sonra, sizi ondan biz mi geri çevirdik? Hayır, siz kendiniz günahkârlardınız!\""},{"n":33,"t":"Bu kez, basit görülüp horlananlar büyüklük taslayanlara şöyle derler: \"Hayır, öyle değil!\" İşiniz gece gündüz düzenbazlıktı. Siz bize Allah'a nankörlük etmemizi, O'na eşler-ortaklar tutmamızı emrediyordunuz.\" Nihayet, azabı gördüklerinde, pişmanlığı içlerine gömerler. Biz ise inkârcıların boyunlarına bukağıları vurmuşuzdur. Yapıp ettiklerinden başka, neyin karşılığını görüyorlar ki!..."},{"n":34,"t":"Biz, hangi ülkeye bir uyarıcı göndermişsek, onun servet ve refahla şımaranları mutlaka şöyle demişlerdir: \"Biz, sizin elçilik yaptığınız şeyi inkâr ediyoruz!\""},{"n":35,"t":"Şunu da söylemişlerdir: \"Biz, malca da evlatça da çoğuz. Azaba uğratılacak olanlar, bizler değiliz.\""},{"n":36,"t":"De ki: \"Rabbim, dilediğine rızkı genişletip açar, dilediğine ölçülü verir/kısar. Fakat insanların çokları bilmiyorlar.\""},{"n":37,"t":"Sizi bize yaklaştırıp, katımızda size yakınlık sağlayacak olan, ne mallarınızdır ne de çocuklarınız. İman edip hayra ve barışa yönelik iş yapanlar müstesna. Onlara, yaptıklarının kat kat fazlası ödül vardır. Onlar, seçkin odalarda güven içindedirler."},{"n":38,"t":"Ayetlerimizi hükümsüz bırakmak için koşuşanlara gelince, onlar azabın içinde hazır bulundurulacaklardır."},{"n":39,"t":"De ki: \"Rabbim, kullarından dilediğine rızkı bolca-genişçe verir, dilediğine de kısarak verir. Bir şey infak ederseniz O, onun yerine başka bir şey lütfeder. Rızık verenlerin en hayırlısıdır O."},{"n":40,"t":"Gün olur, onların hepsini bir yere toplar, sonra meleklere sorar: \"Şunlar, sadece size mi kulluk/ibadet ediyorlardı?\""},{"n":41,"t":"Melekler derler ki: \"Tespih ederiz seni! Bizim Velî'miz sendin, onlar değil. Doğrusu şu ki, onlar cinlere tapıyorlardı. Onların çoğu cinlere iman etmekteydi.\""},{"n":42,"t":"Artık o gün, birinizin diğerine yarar sağlamaya da zarar vermeye de gücü yetmez. Zulme sapanlara şöyle deriz: \"O kendisini yalanlayıp durduğunuz ateş azabını tadın!\""},{"n":43,"t":"Ayetlerimiz açık-seçik kanıtlar halinde karşılarında okununca şöyle derler: \"Bu adam, atalarınızın kulluk/ibadet etmekte olduklarından sizi vazgeçirmek isteyen biriden başkası değil.\" Şunu da söylerler: \"Bu, düzenlenmş bir yalandan/iftiradan başka şey değildir.\" Hakkı inkâr edenler, o kendilerine geldiğinde şöyle demişlerdir: \"Açık bir büyüden başka şey değil bu!\""},{"n":44,"t":"Oysaki biz onlara, araştırıp ders alacakları kitaplar vermemiştik; daha önce kendilerine bir uyarıcı da göndermemiştik."},{"n":45,"t":"Onlardan öncekiler de yalanladılar. Üstelik bunlar, ötekilerine verdiklerimizin onda birine bile ulaşamadılar. Resullerimi yalanladılar. Peki, benim azabım nasıl oldu!?"},{"n":46,"t":"De ki: \"Size, bir tek şey öğütleyeceğim: Allah için ikişer ikişer, teker teker kalkın, sonra da iyice düşünün!\" Arkadaşınızda cinnetten eser yok! O, şiddetli bir azap öncesinde sizi uyaran bir kişiden başkası değil."},{"n":47,"t":"De ki: \"Ben sizden herhangi bir ücret istemedim; o sizin olsun. Benim ödülüm yalnız Allah'tandır. Ve O, her şey üzerinde bir Şehîd, gerçek bir tanık...\""},{"n":48,"t":"De ki: \"Benim Rabbim, gerçeği ortaya koyar. Gaybları en iyi bilen O'dur.\""},{"n":49,"t":"De ki: \"Hak geldi, artık bâtıl ortaya yeni bir şey çıkaramaz; eskiyi de geri getiremez.\""},{"n":50,"t":"De ki: \"Eğer saparsam, öz benliğim aleyhine saparım. Doğruyu ve güzeli bulursam bu, Rabbimin bana vahyettiği sayesindedir. Çünkü O, Semî'dir, Karîb'dir.\""},{"n":51,"t":"Bir görsen onları korku ve telaşa düştüklerinde! Artık kaçış-kurtuluş yok! Çok yakın bir yerden yakalanmışlardır."},{"n":52,"t":"\"Ona inandık!\" dediler. Ama nasıl mümkün olur onlar için imana ulaşmak o uzak yerden!"},{"n":53,"t":"Daha önce inkâr etmişlerdi onu. Gayba taş atıp duruyorlardı o uzak yerden."},{"n":54,"t":"Artık kendileriyle, iştahla arzuladıkları şey arasına engel konmuştur. Tıpkı daha önce benzerlerine yapıldığı gibi. Gerçek şu ki onlar, tutarsızlığa iten bir kuşku içindeydiler."}],[{"n":1,"t":"Hamt, Fâtır olan Allah'adır; gökleri ve yeri yaratan, melekleri ikişer, üçer, dörder kanatlı elçiler yapan O'dur. Yaratışta/yaratılmışlarda dilediğini artırır O. Hiç kuşkusuz, Allah her şeye gücü yetendir."},{"n":2,"t":"Allah'ın insanlar için açıp yaydığı rahmeti hiç kimse tutup kısamaz. Onun tutup kıstığını ise O'ndan sonra salıp açacak yoktur. Azîz'dir O, Hakîm'dir."},{"n":3,"t":"Ey insanlar, Allah'ın, üzerinizdeki nimetini anın! Allah'tan başka yaratıcı mı var? Sizi gökten ve yerden rızıklandırır. O'ndan başka ilah yoktur. Hal böyle iken nasıl oluyor da yüz geri çevriliyorsunuz?"},{"n":4,"t":"Eğer seni yalanlıyorlarsa, senden önceki resuller de yalanlanmıştır. Bütün işler ve oluşlar Allah'a döndürülür."},{"n":5,"t":"Ey insanlar, Allah'ın vaadi haktır! O halde iğreti dünya hayatı sizi sakın aldatmasın! O yaman aldatıcı, o çok gururlu, sizi sakın Allah ile aldatmasın."},{"n":6,"t":"Şu bir gerçek ki, şeytan sizin için bir düşmandır. O halde siz de onu düşman tutun. Hiç kuşkusuz, o kendi hizbini cehennem yâranından olmaları için çağırır durur."},{"n":7,"t":"Küfre sapanlar için şiddetli bir azap vardır. İman edip hayra ve barışa yönelik ameller işleyenlere gelince onlar için bir bağışlanma ve büyük bir ödül olacaktır."},{"n":8,"t":"Ya o kişi? Yaptıklarının kötülüğü kendisine allanıp pullanmış da onu güzel görüvermiş. Doğrusu şu: Allah dilediğini/dileyeni saptırır, dilediğini/dileyeni de doğruya ve güzele kılavuzlar. O halde canın onlar için üzüntülere dalmasın. Hiç kuşkusuz, Allah onların ürettiklerini/ortaya koydukları oyunları çok iyi bilmektedir."},{"n":9,"t":"Allah odur ki, rüzgârları gönderdi. Rüzgârlar bir bulut kaldırır. Derken onu ölü bir beldeye sevk ettik de ölümünden sonra toprağa onunla hayat verdik. İşte ölümünden sonra dirilme de böyledir."},{"n":10,"t":"Onur ve yücelik isteyen bilsin ki, onur ve yüceliğin tümü Allah'adır. Temiz ve güzel kelime O'na yükselir; hayra ve barışa yönelik amel de o kelimeyi yüceltir. Kötülükleri kuranlara/kötülükleri tuzak yapanlara gelince, onlar için şiddetli bir azap vardır. Ve böylelerinin tuzağı tarumar olur."},{"n":11,"t":"Allah sizi bir topraktan, sonra bir spermden yarattı; sonra sizi çiftler haline getirdi. O'nun ilmi dışında, bir dişi ne hamile olur ne de doğurur. Yaşayan bir varlığa daha çok ömür verilmesi de onun ömründen biraz azaltılması da mutlaka bir kitapta yazılıdır. Bu, Allah için gerçekten çok kolaydır."},{"n":12,"t":"İki deniz birbirine eşit olmaz. Bu tatlıdır, susuzluğu giderir, içimi hoş ve rahattır; şu tuzludur, acıdır. Ama hepsinden de taze et yersiniz; giyip takınacağınız bir süs çıkarırsınız. Allah'ın lütfundan nasip aramanız ve şükredebilmeniz için, gemilerin denizi yara yara gittiğini görürsün."},{"n":13,"t":"Allah, geceyi gündüzün içine sokar, gündüzü de gecenin içine sokar. Güneş'i ve Ay'ı buyruk altına almıştır. Her biri belirlenen bir süreye kadar akıp gidiyor. İşte Rabbiniz Allah bu; mülk ve yönetim O'nundur. Onun berisinden yakardıklarınız ise bir çekirdek zarına bile hükmedemezler."},{"n":14,"t":"Onlara çağırsanız, çağrınızı duymazlar. Duysalar da size cevap veremezler. Kıyamet günü de sizin onları ortak koştuğunuzu inkâr ederler. Hiç kimse sana, Habîr olan Allah'ın verdiği gibi haber veremez."},{"n":15,"t":"Ey insanlar, siz Allah'a yönelmiş yoksullarsınız! Allah ise mutlak Ganî, mutlak Hamîd'dir."},{"n":16,"t":"Dilerse sizi yok eder, yepyeni bir halk getirir."},{"n":17,"t":"Ve bu, Allah'a hiç de güç gelmez."},{"n":18,"t":"Hiçbir günahkâr, bir başkasının günahını yüklenmez. Yükü ağır gelen, onu taşımaya çağırsa bile, kendisinden hiçbir şey yüklenilmez. Akraba bile olsa... Sen ancak Rablerinden için için korkanları ve namazı/duayı yerine getirenleri uyarırsın. Arınıp temizlenen, kendi benliği için arınıp temizlenir. Dönüş Allah'adır."},{"n":19,"t":"Körle, gören bir olmaz!"},{"n":20,"t":"Karanlıklarla ışık da bir olmaz!"},{"n":21,"t":"Gölge ile sıcaklık da aynı değildir."},{"n":22,"t":"Diriler de eşit olmaz, ölüler de. Allah dilediğine/dileyene işittirir. Ama sen, kabirlerdekilere işittiremezsin!"},{"n":23,"t":"Sen sadece bir uyarıcısın!"},{"n":24,"t":"Şu bir gerçek ki, biz seni hak ile bir müjdeci ve uyarıcı olarak gönderdik. Hiçbir ümmet yoktur ki, içinden bir uyarıcı gelip geçmemiş olsun."},{"n":25,"t":"Seni yalanlıyorlarsa, onlardan öncekiler de yalanlamıştı. Resulleri onlara açık-seçik mesajlar, sayfalar ve aydınlatıcı kitap getirmişlerdi."},{"n":26,"t":"Sonra ben, inkâr edenleri yakaladım. Ama nasıl oldu benim azabım?!"},{"n":27,"t":"Görmedin mi, Allah, gökten bir su indirdi. Onunla, renkleri çeşit çeşit meyveler çıkardık. Dağlardan da yollar var; beyaz, kırmızı, değişik renklerde. Ve simsiyah yollar da var."},{"n":28,"t":"Aynı şekilde, insanlardan, hayvanlardan, davarlardan da çeşitli renklerde olanlar var. Kulları içinde Allah'tan ancak bilginler ürperir. Allah Azîz'dir, Gafûr'dur."},{"n":29,"t":"Allah'ın kitabını okuyanlar, namazı/duayı yerine getirenler, kendilerine verdiğimiz rızıklardan gizli ve açık infak edenler, asla batmayacak bir ticaret umabilirler."},{"n":30,"t":"Çünkü Allah onlara ücretlerini tam ödeyecek, lütfundan onlara artırma da yapacaktır. Gafûr'dur O, çok affeder; Şekûr'dur, şükredenlere mutlaka karşılık verir."},{"n":31,"t":"Kitap'tan sana vahyettiğimiz, kendinden öncekini tasdikleyici hakkın ta kendisidir. Allah, kullarından tam haberdardır, onları iyice görmektedir."},{"n":32,"t":"Sonra, kullarımız arasından seçtiklerimizi Kitap'a mirasçı kıldık. İçlerinden öz nefsine zulmeden var. Orta yolda gideni var. Allah'ın izniyle hayırlarda öne geçeni var. İşte bu, büyük lütfun ta kendisidir."},{"n":33,"t":"Adn cennetlerine girerler onlar, orada altından bilezikler ve inci takınırlar. Orada giysileri ise ipektir."},{"n":34,"t":"Şöyle derler: \"Hamt olsun, üzüntüyü bizden gideren Allah'a! Rabbimiz mutlak Gafûr, mutlak Şekûr'dur."},{"n":35,"t":"Lütfuyla bizi durulacak yurda kondurdu. Orada bize hiçbir yorgunluk dokunmaz. Orada bize hiçbir usanç da dokunmaz."},{"n":36,"t":"İnkâr edenlere de cehennem ateşi var. Ne haklarında hüküm verilir ki ölsünler ne de azapları hafifletilir. İşte böyle cezalandırırız tüm nankörleri biz."},{"n":37,"t":"Feryat edip dururlar orada: \"Rabbimiz, çıkar bizi de önceden yaptığımızdan başka şey yapalım. Barışa ve hayra yönelik iyi bir iş yapalım.\" Sizi biz, öğüt alanın öğüt alacağı bir süre ömürlendirmedik mi? Uyarıcı da geldi size. Hadi, tadın bakalım azabı! Zalimler için hiçbir yardımcı yok artık."},{"n":38,"t":"Allah, göklerin ve yerin gaybını bilendir/Âlim'dir. O, göğüslerin özündekini de çok iyi bilir."},{"n":39,"t":"Sizi yeryüzünde halefler yapan O'dur. Nankörlük edenin nankörlüğü kendi aleyhinedir. Kâfirlerin küfrü, Rableri katında öfkeden başka bir şey artırmaz. Kâfirlerin küfrü hüsran ve yıkımdan başka bir şey artırmaz."},{"n":40,"t":"De ki: \"Allah'ın berisinden yakardığınız şu ortaklarınızı gördünüz mü? Gösterin bana topraktan neyi yarattı onlar!\" Yoksa göklerde bir ortaklıkları mı var? Yoksa onlara bir kitap verdik de kendileri o kitaptan bir kanıt üzerinde midirler? Hayır, zalimler birbirlerine aldanıştan/aldatıştan başka hiçbir şey vaat etmezler."},{"n":41,"t":"Allah, gökleri ve yeri, yok olup gitmesinler diye tutuyor. Yemin olsun, eğer çöküp giderlerse, O'ndan başka hiç kimse onları tutamaz. Halîm'dir O, Gafûr'dur."},{"n":42,"t":"Yeminlerinin tüm gücüyle Allah'a ant içmişlerdi ki, eğer kendilerine bir uyarıcı gelirse, ümmetlerin herhangi birinden çok daha doğru bir gidiş üzere olacaklar. Fakat uyarıcı onlara gelince, bu onlara nefretle kaçıştan başka bir katkı sağlamadı."},{"n":43,"t":"Yeryüzünde kibirlendi ve kötülük tezgâhladılar. Oysaki tezgâhlanan kötülük, sahibinden başkasını kuşatmaz. Öncekilerin başına gelenlerden başkasını mı bekliyorlar? Allah'ın yol ve yönteminde değişme asla bulamazsın! Allah'ın yol ve yönteminde döneklik de bulamazsın!"},{"n":44,"t":"Yeryüzünde dolaşıp da kendilerinden öncekilerin sonlarının nasıl olduğunu görmediler mi? Onlar, kuvvet bakımından bunlardan daha zorluydular. Göklerde de yerde de Allah'ı âciz bırakacak hiçbir şey yoktur. Alîm'dir O, Kadîr'dir."},{"n":45,"t":"Eğer Allah, insanları, kazandıkları yüzünden hesaba çekseydi, yerkürenin sırtında hiçbir canlı bırakmazdı. Ne var ki, onları belirli bir süreye kadar, ecelleri gelinceye kadar erteliyor. Allah, kullarını iyice görmektedir."}],[{"n":1,"t":"Yâ, Sîn."},{"n":2,"t":"Yemin olsun o hikmetlerle dolu Kur'an'a ki,"},{"n":3,"t":"Hiç kuşkusuz, sen, gönderilen elçilerdensin;"},{"n":4,"t":"Dosdoğru bir yol üzerindesin."},{"n":5,"t":"Azîz ve Rahîm'in indirdiği üzeresin."},{"n":6,"t":"Babaları uyarılmamış, tam gaflet içinde bir toplumu uyarman için gönderildin."},{"n":7,"t":"Yemin olsun ki, onların çoğuna söz hak olmuştur, artık onlar iman etmezler."},{"n":8,"t":"Biz onların boyunlarına bukağılar geçirdik. Bukağılar çenelere dayanmıştır da bu yüzden onların kafaları yukarı kalkıktır."},{"n":9,"t":"Önlerine bir set, arkalarına da başka bir set çektik. Böylece onları kuşatıp sardık; artık onlar görmezler."},{"n":10,"t":"Sen ha uyarmışsın onları ha uyarmamışsın, fark etmez onlar için; inanmazlar."},{"n":11,"t":"Sen ancak o zikire/Kur'an'a uyan ve görmediği halde Rahman'dan korkan kimseyi uyarırsın. Böylesini, bir bağışlanma ve seçkin bir ödülle müjdele!"},{"n":12,"t":"Biz, yalnız biz, ölüleri diriltiriz ve onların önden gönderildiklerini de eserlerini de yazarız! Zaten biz her şeyi apaçık bir kütükte ayrıntılı olarak kaydetmişizdir."},{"n":13,"t":"Onlara o kent halkını örnek ver. Hani, elçiler gelmişti oraya."},{"n":14,"t":"Hani, biz onlara iki kişi göndermiştik, onları yalanlamışlardı. Bunun üzerine biz, üçüncü bir kişiyle destek vermiştik. Şöyle demişlerdi: \"Biz, size gönderilen elçileriz!\""},{"n":15,"t":"Kent halkı dedi ki: \"Siz, bizim gibi birer insandan başka şey değilsiniz. Rahman hiçbir şey indirmemiştir. Siz sadece yalan söylüyorsunuz.\""},{"n":16,"t":"Dediler: \"Rabbimiz biliyor ki, biz size gönderilmiş elçileriz.\""},{"n":17,"t":"\"Bize düşen, açık bir tebliğden başka şey değildir.\""},{"n":18,"t":"Dediler: \"Sizin yüzünüzden uğursuzlukla karşılaştık/biz sizi uğursuzluk sebebi saymaktayız. Eğer bu işe son vermezseniz, sizi mutlaka taşlayacağız. Ve bizden size acıklı bir azap kesinlikle dokunacaktır.\""},{"n":19,"t":"Dediler: \"Uğursuzluk kuşunuz sizinle beraberdir. Size öğüt verildi diye mi bütün bunlar? Hayır, siz savurganlığa, aşırılığa sapmış bir topluluksunuz.\""},{"n":20,"t":"Kentin öbür ucundan bir adam koşarak gelip şöyle dedi: \"Ey topluluk, bu elçilere uyun!\""},{"n":21,"t":"\"Sizden herhangi bir ücret istemeyelere uyun. Onlardır doğruyu ve güzeli bulanlar.\""},{"n":22,"t":"\"Beni yaratana ne diye kulluk etmeyecek mişim ben? Ve sizler de O'na döndürüleceksiniz.\""},{"n":23,"t":"\"O'ndan başka tanrılar mı edineyim ben? Eğer Rahman bana bir zorluk/zarar dilerse onların şefaati benden hiçbir şeyi savamaz; beni kurtaramazlar.\""},{"n":24,"t":"\"Bu durumda ben elbette ki açık bir sapıklığın içine düşerim.\""},{"n":25,"t":"\"Ben, sizin Rabbinize iman ettim, artık dinleyin beni!\""},{"n":26,"t":"\"Gir cennete!\" denildi. Dedi: \"Kavmim bir bilebilseydi?"},{"n":27,"t":"Ki Rabbim beni affetti; beni, ikram edilenlerden kıldı.\""},{"n":28,"t":"Biz onun ardından kavmi üzerine gökten bir ordu indirmedik, indirecek de değildik."},{"n":29,"t":"Olan, sadece korkunç titreşimli bir sesti. Ve bir anda söndüverdiler."},{"n":30,"t":"Yazık şu kullara! Kendilerine gelen her resulle mutlaka alay ederlerdi."},{"n":31,"t":"Görmediler mi, kendilerinde önce nice nesilleri helâk ettik. Onlar artık bir daha bunlara dönmeyecekler."},{"n":32,"t":"Ancak herkes toplandığında, onlar da huzurumuzda hazır bulundurulacaklar."},{"n":33,"t":"Ölü toprak onlar için bir mucizedir. Onu dirilttik, ondan dâne çıkardık; bak işte ondan yiyorlar."},{"n":34,"t":"Onda hurmalardan, üzümlerden bahçeler oluşturduk, ondan pınarlar fışkırttık;"},{"n":35,"t":"Ki onun ürününden ve ellerinin yapıp ettiğinden yesinler. Hâlâ şükretmiyorlar mı?"},{"n":36,"t":"Şanı yücedir o Allah'ın ki toprağın bitirdiklerinden, onların öz benliklerinden ve nice bilmediklerinden bütün çiftleri yaratmıştır."},{"n":37,"t":"Gece de onlar için bir mucizedir. Gündüzü ondan soyup alırız da onlar karanlığa gömülüverirler."},{"n":38,"t":"Güneş, kendine özgü bir durak noktasına/bir durma zamanına doğru akıp gidiyor. Azîz, Alîm olanın takdiridir bu."},{"n":39,"t":"Ay'a gelince, biz onun için de bir takım durak noktaları/birtakım evreler belirledik. Nihayet o, eski hurma sapının eğrilmişi gibi geri döner."},{"n":40,"t":"Güneş'in Ay'a ulaşıp çatması gerekmiyor. Gecenin de gündüzü geçmesi gerekmez. Her biri bir yörüngede yüzmektedir."},{"n":41,"t":"Zürriyetlerini o dopdolu gemilerde taşımamız da onlar için bir ayettir."},{"n":42,"t":"Onlar için gemilere benzer, binecekleri başka şeyler de yarattık."},{"n":43,"t":"Eğer dilersek onları boğarız. Bu durumda ne kendileri için feryat eden olur ne de kurtarılırlar."},{"n":44,"t":"Ancak bizden bir rahmet olarak bir süreye kadar daha nimetlensinler diye kurtarılırlar."},{"n":45,"t":"Onlara, \"Önünüzdekinden ve arkanızdakinden sakının ki, size merhamet edilebilsin!\" denildiğinde, hiç aldırmazlar."},{"n":46,"t":"Çünkü Rablerinin ayetlerinden kendilerine bir ayet gelince, ondan mutlaka yüz çevirmişlerdir."},{"n":47,"t":"Onlara, \"Allah'ın size lütfettiği rızıklardan dağıtın!\" dendiğinden, nankörlüğe sapanlar, iman edenlere şöyle derler: \"Allah'ın, dilediği takdirde yedirip doyuracağı kişiyi biz mi doyuracağız? Siz açık bir sapıklık içindesiniz, hepsi bu.\""},{"n":48,"t":"Bir de şöyle derler: \"Eğer doğru sözlüler iseniz, bu tehdit ne zaman?\""},{"n":49,"t":"Sadece korkunç titreşimli bir sesi bekliyorlar. Onlar çekişip dururlarken, o ses kendilerini enseleyecektir."},{"n":50,"t":"O zaman ne bir tavsiyede bulunmaya güçleri yetecek ne de ailelerine dönebilecekler."},{"n":51,"t":"Sûra üfürülmüştür! Bak, işte kabirlerden, Rablerine doğru akın akın gidiyorlar."},{"n":52,"t":"Şöyle diyecekler: \"Vay başımıza gelene! Kim kaldırdı bizi mezarımızdan? Rahman'ın vaat ettiği işte bu! Peygamberler doğru söylemişler.\""},{"n":53,"t":"Topu topu korkunç titreşimli bir tek ses. Ve bakmışsın, hepsi birden huzurumuzda divan durmaktadır."},{"n":54,"t":"O gün hiçbir canlıya, hiçbir şekilde haksızlık edilmez. Sizler, sadece yapıp ettiklerinizin karşılığı olarak cezalandırılırsınız."},{"n":55,"t":"O gün cennet halkı bir uğraş içinde eğlenip ferahlamaktadır."},{"n":56,"t":"Kendileri ve eşleri, gölgeliklerde, koltuklar üzerinde yaslanmışlardır."},{"n":57,"t":"Orada kendileri için meyveler var. İstedikleri her şey kendilerinin olacak."},{"n":58,"t":"Rahîm Rab'den bir de sözlü selam!"},{"n":59,"t":"Ey günahkârlar! Bugün şöyle ayrılın!"},{"n":60,"t":"Ey âdemoğulları! Ben size, \"Şeytana kulluk etmeyin, o sizin için açık bir düşmandır!\" demedim mi?"},{"n":61,"t":"\"Bana ibadet edin, dosdoğru yol budur!\" demedim mi?"},{"n":62,"t":"Yemin olsun, şeytan, içinizden birçok nesli saptırmıştı. Aklınızı hiç işletmiyor muydunuz?"},{"n":63,"t":"Alın size, tehdit edildiğiniz cehennem!"},{"n":64,"t":"İnkâr edip durmanız yüzünden dalın oraya bugün!"},{"n":65,"t":"O gün, ağızlarını mühürleyeceğiz. Bize elleri konuşacak, ayakları da kazanmış olduklarına tanıklık edecek."},{"n":66,"t":"Dilesek, gözlerini siler, onları elbette kör ederiz. O zaman yola koyulmak isterler ama nasıl görecekler?"},{"n":67,"t":"Dilesek, onları oldukları yerde hayvana çeviririz. O zaman ne ileri gitmeye güçleri yeter ne de geri dönebilirler."},{"n":68,"t":"Kimi uzun ömürlü kılarsak, onu yaratılışta gerisin geri çeviririz. Hâlâ akıllarını işletmiyorlar mı?"},{"n":69,"t":"Biz o peygambere şiir öğretmedik. Şiir ona yaraşmaz/layık olamaz da. Ona vahyedilen, bir öğütten ve apaçık bir Kur'an'dan başka şey değildir;"},{"n":70,"t":"Diri olanı uyarsın ve gerçeği örten nankörler/inkârcılar aleyhine söz hak olsun diye indirilmiştir."},{"n":71,"t":"Görmediler mi, ellerimizin yapıp ettiklerinden, kendileri için nice hayvanlar yarattık da onlar, bu hayvanlara sahip oluyorlar."},{"n":72,"t":"O hayvanları bunlara boyun eğdirdik. Onlardan binekleri vardır ve onlardan bir kısmını da yiyorlar."},{"n":73,"t":"O hayvanlarda bunlar için birçok yararlar var, içecekler var. Hâlâ şükretmiyorlar mı?"},{"n":74,"t":"Kendilerine yardım edilir ümidiyle Allah'tan başka ilahlar edindiler."},{"n":75,"t":"Oysaki, o ilahlar bunlara yardım edemezler. Tam aksine, bunlar, o ilahlara hizmet eden ordular durumundadır."},{"n":76,"t":"Artık onların sözü seni üzmesin! Biz onların sır olarak tuttuklarını da açıkladıklarını da biliyoruz."},{"n":77,"t":"Görmedi mi insan, kendisini bir spermden yarattığımızı! Bir de bize açık bir hasım kesilmiştir o."},{"n":78,"t":"Kendi yaratılışını unutmuş da bize örnek veriyor. Ve bir de şöyle diyor: \"Şu çürümüş kemiklere kim hayat verecek?\""},{"n":79,"t":"De ki: \"Onlara hayata verecek olan, onları ilk kez yaratandır. O, bütün yaratılmışları/her türlü yaratmayı çok iyi bilmektedir.\""},{"n":80,"t":"O size, o yeşil ağaçtan bir ateş oluşturdu da siz ondan tutuşturup duruyorsunuz."},{"n":81,"t":"Gökleri ve yeri yaratan, onların benzerini yaratmaya güç yetiremez mi? Elbette güç yetirir. Her şeyi bilen Alîm, sürekli yaratan Hallâk O'dur."},{"n":82,"t":"O, bir şeyi istediğinde, buyruğu sadece şunu söylemektir: \"Ol!\" Artık o, oluverir."},{"n":83,"t":"Her şeyin kaynağı/egemenliği elinde olan o yaratıcının şanı çok yücedir! Sonunda O'na döndürüleceksiniz."}],[{"n":1,"t":"Yemin olsun o saf bağlayıp dizilenlere/o saflar tutturup sıraya dizilenlere-o kanatlarını açıp toplayarak uçanlara,"},{"n":2,"t":"O haykırarak sevk edenlere/o göğüs gererek durduranlara,"},{"n":3,"t":"O Zikir okuyanlara,"},{"n":4,"t":"Ki sizin ilahınız hiç kuşkusuz bir ve tektir."},{"n":5,"t":"Göklerin, yerin ve bu ikisi arasındakilerin Rabbidir O; doğuların da Rabbidir O."},{"n":6,"t":"Biz o yakın göğü bir süsle, yıldızlarla süsleyip donattık."},{"n":7,"t":"Ve her türlü inatçı-âsi şeytandan koruduk."},{"n":8,"t":"Onlar ne kadar çırpınsalar da o yüce konseyi dinleyemezler. Ve her taraftan atışa tutulurlar;"},{"n":9,"t":"Kovulurlar. Ve onlar için, yakalarını bırakmayan bir azap vardır."},{"n":10,"t":"Yüce konseyden bir söz çalıp çarpan olabilirse de onun peşine hemen delici, alevli bir yıldız takılır."},{"n":11,"t":"Şimdi sor onlara: Yaratış ve yaratılış bakımından onlar mı daha güçlüdür, yoksa bizim yarattığımız şuurlular mı? Gerçek şu ki, biz onları bir cıvık çamurdan yarattık."},{"n":12,"t":"Ama sen şaşırdın, onlarsa alay ediyorlar."},{"n":13,"t":"Düşünüp taşınmaya çağrıldıklarında düşünmüyorlar."},{"n":14,"t":"Bir ayetle yüzyüze geldiklerinde, dudak büküp eğleniyorlar."},{"n":15,"t":"Şöyle dediler: \"Bu, apaçık bir büyüden başka şey değildir.\""},{"n":16,"t":"\"Öldüğümüz, toprak ve kemik haline geldiğimiz zaman mı? Biz gerçekten diriltilecek miyiz?\""},{"n":17,"t":"\"Önceki atalarımız da mı?\""},{"n":18,"t":"De ki: \"Evet! Ve, siz de! Aşağılanmış, ezilmiş olarak.\""},{"n":19,"t":"Müthiş bir komut sesidir O. Onlar öylece bakakalacaklar."},{"n":20,"t":"Şöyle derler: \"Vay başımıza! Din günüdür bu!\""},{"n":21,"t":"O yalanlayıp durduğunuz ayrım günüdür bu."},{"n":22,"t":"Toplayın o zulmedenleri; eşlerini de. O tapınıp durmuş olduklarını da toplayın:"},{"n":23,"t":"Allah'tan başka tapınmış olduklarını. Sürün onları cehennemin yoluna."},{"n":24,"t":"Durdurun onları, çünkü hepsi sorguya çekilecekler."},{"n":25,"t":"Neniz var da birbirinize yardım etmiyorsunuz?"},{"n":26,"t":"Edemezler! Bugün hepsi teslim bayrağını çekmiş durumdadır."},{"n":27,"t":"Birbirlerine dönerek bir şeyler sorup duruyorlar."},{"n":28,"t":"Dediler: \"Siz bize sağ taraftan geliyordunuz.\""},{"n":29,"t":"Ötekiler dediler: \"Hayır, siz zaten inanmıyordunuz?\""},{"n":30,"t":"\"Bizim size karşı bir sultamız yoktu. İşin esası şu ki siz azmış bir topluluktunuz.\""},{"n":31,"t":"\"Rabbimizin sözü üzerimize hak oldu. Tadacağımızı elbette tadacağız.\""},{"n":32,"t":"\"Sizi saptırıp azdırmıştık. Çünkü biz de sapıp azmış kişilerdik.\""},{"n":33,"t":"Onlar o gün azap içinde ortaklık kurmuşlardır."},{"n":34,"t":"İşte böyle yaparız biz suçlulara/günahkârlara."},{"n":35,"t":"Onlar, kendilerine, \"Allah'tan başka ilah yoktur\" dendiğinde, kibirleniyorlardı."},{"n":36,"t":"Ve şöyle diyorlardı: \"Mecnun bir şair yüzünden ilahlarımızı mı terk edeceğiz?\""},{"n":37,"t":"Hayır, öyle değil! O, hakkı getirmişti. Diğer peygamberleri de tasdik etmişti."},{"n":38,"t":"Yemin olsun, siz o acıklı azabı mutlaka tadacaksınız!"},{"n":39,"t":"Ve yalnız, yapıp ettiklerinizin karşılığıyla cezalandırılacaksınız."},{"n":40,"t":"Allah'ın içtenliğe erdirilmiş temiz kulları başkadır."},{"n":41,"t":"Onlar için belirlenmiş bir rızık vardır."},{"n":42,"t":"Çeşit çeşit meyveler vardır. İkramla karşılanan kişilerdir onlar."},{"n":43,"t":"Nimetlerle dolu cennetlerdedirler."},{"n":44,"t":"Karşılıklı koltuklar üzerindedirler."},{"n":45,"t":"Kaynaktan doldurulmuş kadehler dolandırılır çevrelerinde."},{"n":46,"t":"Bembeyaz, içenlere lezzet sunan kadehler."},{"n":47,"t":"Sersemletme/baş ağrısı yok onda. Sarhoş da olmazlar ondan."},{"n":48,"t":"Yanlarında, gözlerini onlara dikmiş, iri gözlü dilberler vardır."},{"n":49,"t":"Korunmuş yumurtalar gibidir onlar."},{"n":50,"t":"Birbirlerine dönüp bir şeyler sorarlar."},{"n":51,"t":"İçlerinden bir sözcü şöyle der: \"Benim yakın bir arkadaşım vardı.\""},{"n":52,"t":"Derdi ki: \"Sen gerçekten şunu tasdik edenlerden misin?\""},{"n":53,"t":"\"Biz, ölüp toprak ve kemik haline geldikten sonra, gerçekten cezalandırılacak mıyız?\""},{"n":54,"t":"Dedi: \"Siz de bir araştırır mısınız?\""},{"n":55,"t":"Araştırdı, nihayet onu cehennemin ta ortasında gördü."},{"n":56,"t":"Dedi: \"Vallahi, az kalsın sen beni de buralara düşürecektin.\""},{"n":57,"t":"\"Rabbimin nimeti olmasaydı, kesinlikle ben de şurada toplananlar arasına girmiş olacaktım.\""},{"n":58,"t":"\"Peki, biz artık ölmeyecek miyiz?\""},{"n":59,"t":"\"Sadece ilk ölümümüz; azaba da uğratılmayacağız, öyle mi?\""},{"n":60,"t":"Doğrusu bu, büyük başarının ta kendisidir."},{"n":61,"t":"Çalışanlar, böylesi için çalışsınlar."},{"n":62,"t":"Ödül ve ikram olarak, bu mu daha hayırlı yoksa zakkum ağacı mı?"},{"n":63,"t":"O ağaç ki, zalimler için onu bir fitne yaptık."},{"n":64,"t":"Cehennemin ta dibinden çıkan bir ağaçtır o."},{"n":65,"t":"Tomurcukları tıpkı şeytanların başlarıdır."},{"n":66,"t":"Onlar ondan mutlaka yiyecekler ve karınlarını onunla dolduracaklar."},{"n":67,"t":"Sonra onların, o yedikleri üzerine kaynar su karıştırılmış bir içecekleri vardır."},{"n":68,"t":"Sonra onların dönüşleri doğrudan doğruya cehennemedir."},{"n":69,"t":"Çünkü onlar, babalarını sapıtmış kişiler halinde bulmalarına rağmen,"},{"n":70,"t":"Kendileri de hâlâ onların eserleri ardınca koşturuyorlar."},{"n":71,"t":"Yemin olsun, daha önce ilk nesillerin çoğu da sapmıştı."},{"n":72,"t":"Yemin olsun, onların içlerinde uyarıcılar görevlendirmiştik."},{"n":73,"t":"Bir bak, nasıl oldu uyarılanların sonu!"},{"n":74,"t":"Ancak Allah'ın samimi, temiz kulları kurtuldu."},{"n":75,"t":"Yemin olsun, Nûh bize yakarmıştı da ne güzel karşılık vermiştik biz."},{"n":76,"t":"Ve kurtarmıştık onu da ailesini de o büyük sıkıntıdan."},{"n":77,"t":"Onun zürriyetini, evet onları kalıcılar yaptık."},{"n":78,"t":"Sonrakiler içinde, ona işaret eden bir şey bıraktık."},{"n":79,"t":"Selam olsun Nûh'a âlemler içinde!"},{"n":80,"t":"İşte böyle ödüllendiririz biz, güzel düşünüp güzel davrananları."},{"n":81,"t":"O, bizim inanan kullarımızdandı."},{"n":82,"t":"Sonra ötekileri boğuverdik."},{"n":83,"t":"Hiç kuşkusuz, İbrahim de onun grubundandı."},{"n":84,"t":"Rabbine, tertemiz bir kalple gelmişti."},{"n":85,"t":"Babasına ve toplumuna sormuştu: \"Siz neye kulluk/ibadet ediyorsunuz?\""},{"n":86,"t":"\"Allah'ın berisinden birtakım uydurma ilahları mı istiyorsunuz?\""},{"n":87,"t":"\"Âlemlerin Rabbi hakkında düşünceniz nedir?\""},{"n":88,"t":"Bu arada İbrahim yıldızlara bir göz attı,"},{"n":89,"t":"Şöyle dedi: \"Ben hastayım!\""},{"n":90,"t":"Bunun üzerine ondan gerisin geri kaçtılar."},{"n":91,"t":"O da onların ilahlarının yanına sokulup dedi: \"Bir şey yemez misiniz?\""},{"n":92,"t":"\"Neniz var ki, konuşmuyorsunuz!\""},{"n":93,"t":"İyice yanlarına sokulup sağ eliyle bir darbe indirdi."},{"n":94,"t":"Bir süre sonra, halkı koşarak İbrahim'e geldi."},{"n":95,"t":"İbrahim dedi: \"Elinizle yonttuğunuz şeylere mi tapıyorsunuz?\""},{"n":96,"t":"\"Oysaki sizi de yaptığınız şeyleri de Allah yaratmıştır.\""},{"n":97,"t":"Dediler: \"Şunun için bir bina yapın da bunu ateşin ortasına fırlatın!\""},{"n":98,"t":"Ona tuzak kurmak istediler ama, biz onları sefiller, reziller haline getirdik."},{"n":99,"t":"İbrahim dedi: \"Kuşkunuz olmasın ki ben Rabbime gideceğim, O bana kılavuzluk edecek.\""},{"n":100,"t":"\"Rabbim, bana iyilik/barış sevenlerden birini lütfet!\""},{"n":101,"t":"Bunun üzerine biz, İbrahim'e yumuşak huylu bir oğlan müjdeledik."},{"n":102,"t":"Çocuk onunla birlikte koşacak yaşa gelince, İbrahim dedi: \"Yavrucuğum, uykuda/düşte görüyorum ki ben seni boğazlıyorum. Bak bakalım sen ne görürsün/sen ne dersin?\" \"Babacığım, dedi, emredildiğin şeyi yap! Allah dilerse beni sabredenlerden bulacaksın.\""},{"n":103,"t":"Böylece ikisi de teslim olup İbrahim onu şakağı üzerine yatırınca,"},{"n":104,"t":"Biz şöyle seslendik: \"Ey İbrahim!\""},{"n":105,"t":"\"Sen rüyayı gerçekleştirdin. İşte biz, güzel düşünüp güzel davrananları böyle ödüllendiririz.\""},{"n":106,"t":"\"Bu, hiç kuşkusuz apaçık imtihanın ta kendisiydi.\""},{"n":107,"t":"Ve ona fidye olarak büyük bir kurbanlık verdik."},{"n":108,"t":"Sonra gelenler içinde onu hatırlatan bir şey bıraktık."},{"n":109,"t":"Selam olsun İbrahim'e!"},{"n":110,"t":"Böyle ödüllendiririz biz, güzellik sergileyenleri!"},{"n":111,"t":"O da bizim inanan kullarımızdandı."},{"n":112,"t":"Biz ona, hayrı ve barışı sevenlerden bir peygamber olan İshak'ı müjdeledik."},{"n":113,"t":"Ona da İshak'a da bereketler lütfettik. Onların zürriyetlerinden iyi düşünüp iyi davranan da var, öz benliğine açıkça zulmeden de var."},{"n":114,"t":"Yemin olsun, biz Mûsa ve Hârun'a da lütufta bulunduk."},{"n":115,"t":"Onları ve toplumlarını büyük sıkıntıdan kurtardık."},{"n":116,"t":"Onlara yardım ettik de galip gelenler kendileri oldular."},{"n":117,"t":"Onlara, açık-seçik bilgi sunan Kitap'ı verdik."},{"n":118,"t":"Her ikisini dosdoğru yola kılavuzladık."},{"n":119,"t":"Sonradan gelenler içinde, her ikisini hatırlatan bir şey bıraktık."},{"n":120,"t":"Selam olsun Mûsa'ya ve Hârun'a!"},{"n":121,"t":"Güzel düşünüp güzel davrananları biz böyle ödüllendiririz!"},{"n":122,"t":"O ikisi de bizim inanan kullarımızdandı."},{"n":123,"t":"İlyas da elbette ki peygamberlerdendi."},{"n":124,"t":"O da toplumuna şöyle demişti: \"Hâlâ korkup sakınmıyor musunuz?\""},{"n":125,"t":"\"Bal'e yalvarıp yakarıyor, yaratıcıların en güzelini bırakıyor musunuz?\""},{"n":126,"t":"\"Sizin de Rabbiniz, önceki atalarınızın da Rabbi olan Allah'ı terk mi ediyorsunuz?\""},{"n":127,"t":"Sonunda onu yalanladılar. Bu yüzden onlar mutlaka huzura getirileceklerdir."},{"n":128,"t":"Allah'ın samimi, seçkin kulları müstesna."},{"n":129,"t":"Sonrakiler içinde İlyas'ı hatırlatacak bir şey de bıraktık."},{"n":130,"t":"Selam olsun İlyas'a!"},{"n":131,"t":"Güzel düşünüp güzel davrananları böyle ödüllendiririz biz."},{"n":132,"t":"Bizim inanan kullarımızdandı o."},{"n":133,"t":"Hiç kuşkusuz, Lût da peygamberlerdendi."},{"n":134,"t":"Onu ve ailesini toptan kurtarmıştık biz."},{"n":135,"t":"Ancak terk edilenler içinde kalan kocakarı hariç."},{"n":136,"t":"Sonra ötekileri yerle bir ettik."},{"n":137,"t":"Kuşkusuz ki, siz onların yanından sabahları geçiyorsunuz."},{"n":138,"t":"Geceleyin de. Hâlâ aklınızı işletmeyecek misiniz?"},{"n":139,"t":"Yûnus da gönderilen elçilerdendi."},{"n":140,"t":"Hani o, dolu bir gemiye kaçmıştı."},{"n":141,"t":"Sonra kura çekti de kaybedenlerden oldu."},{"n":142,"t":"Derken, kendisini balık yutmuştu. O kendi kendini kınayıp duruyordu."},{"n":143,"t":"Eğer tespih edenlerden olmasaydı."},{"n":144,"t":"İnsanların diriltilecekleri güne kadar onun karnında kalacaktı."},{"n":145,"t":"Bir süre sonra onu, çıplak araziye attık. Hastalanmıştı."},{"n":146,"t":"Üzerine kabak cinsinden bir ağaç bitirdik."},{"n":147,"t":"Onu yüzbin kişiye yahut daha fazla olanlara elçi olarak gönderdik."},{"n":148,"t":"Onlar inandılar. Biz de onları bir vakte kadar nimetlendirdik."},{"n":149,"t":"Şimdi sor şunlara: \"Kızlar Rabbinin de oğlanlar onların mı?\""},{"n":150,"t":"Yoksa biz, melekleri, bunların tanıklık ettikleri bir sırada, dişiler olarak mı yarattık?"},{"n":151,"t":"Dikkat edin, onlar, iftiralarının bir eseri olarak mutlaka şöyle diyecekler:"},{"n":152,"t":"\"Allah doğurdu!\" Vallahi onlar yalancıdırlar."},{"n":153,"t":"Allah, kızları oğlanlara tercih mi etmiş?"},{"n":154,"t":"Ne oluyor size, o nasıl hüküm veriyorsunuz?"},{"n":155,"t":"Hâlâ düşünüp ibret almıyor musunuz?"},{"n":156,"t":"Yoksa apaçık bir kanıtınız mı var?"},{"n":157,"t":"Eğer doğru sözlülerseniz, hadi getirin kitabınızı!"},{"n":158,"t":"Allah'la cinler arasında bir nesep oluşturdular. Yemin olsun, cinler de bilmiştir kendilerinin Allah huzuruna mutlaka getirileceklerini/cinler de bilmiştir, bunların Allah'ın huzuruna mutlaka çıkarılacaklarını."},{"n":159,"t":"Allah arınmıştır bunların nitelemelerinden."},{"n":160,"t":"Allah'ın samimi, seçkin kulları, bunların yaptıklarından uzaktır."},{"n":161,"t":"Siz ve kulluk ettiğiniz şeyler,"},{"n":162,"t":"O'na karşı kimseyi fitneye düşüremezsiniz."},{"n":163,"t":"Cehenneme salınacak olan müstesna."},{"n":164,"t":"Bizim, istisnasız herbirimizin bilinen bir makamı vardır."},{"n":165,"t":"O saf saf dizilenler elbette biziz."},{"n":166,"t":"O durmadan tespih edenler elbette biziz."},{"n":167,"t":"O inkârcılar şunu da söylüyorlardı:"},{"n":168,"t":"\"Eğer katımızda öncekilere verilenlerden bir öğüt/bir düşündürücü olsaydı,"},{"n":169,"t":"Elbette biz de Allah'ın samimi kullarından olurduk.\""},{"n":170,"t":"Fakat ardından onu inkâr ettiler. Yakında bilecekler."},{"n":171,"t":"Yemin olsun, elçi olarak gönderilen kullarımız hakkında şu sözümüz hükümleşmişti:"},{"n":172,"t":"Onlar, yardım görenlerin ta kendileri olacaklar."},{"n":173,"t":"Ordularımız, galip gelenlerin ta kendileri olacaklar."},{"n":174,"t":"Bir vakte kadar onlardan yüz çevir!"},{"n":175,"t":"Gözün, üstlerinde olsun; yakında görecekler."},{"n":176,"t":"Azabımız gelsin diye acele mi ediyorlar?"},{"n":177,"t":"Azap, yurtlarına indiğinde, uyarılanların sabahı ne kötü olacaktır!"},{"n":178,"t":"Yüz çevir onlardan belli bir vakte kadar!"},{"n":179,"t":"Ve gör neler olacak. Onlar da görecekler."},{"n":180,"t":"Senin Rabbinin, o ululuk ve kudretin Rabbinin şanı yücedir onların verdiği sıfatlardan..."},{"n":181,"t":"Selam olsun tüm hak elçilerine!..."},{"n":182,"t":"Hamt olsun âlemlerin Rabbi Allah'a!..."}],[{"n":1,"t":"Sâd. Zikir/öğüt/uyarı dolu Kur'an'a yemin olsun ki,"},{"n":2,"t":"İş hiç de onların sandığı gibi değil! O küfre sapanlar bir gurur, ayrılık ve bütünden kopuş içindedirler."},{"n":3,"t":"Onlardan önce nice nesilleri helâk ettik biz, bağrıştılar onlar, fakat kurtuluş yoktu; geçmişti zaman."},{"n":4,"t":"Kendi içlerinden kendilerine bir uyarıcı geldi diye şaşıp kaldılar. Ve şöyle dedi bu nankörler: \"Bu adam yalanlar düzen bir büyücü...\""},{"n":5,"t":"\"İlahları bir tek tanrı mı yapmış? Bu, gerçekten hayret edilecek bir şey!\""},{"n":6,"t":"İçlerinden kodaman bir grup öne çıktı: \"Haydi, yürüyün! İlahlarınıza sahip çıkmada kararlı davranın! Gerçek şu ki, istenip beklenen şey budur.\""},{"n":7,"t":"\"Öteki millette işitmedik böyle bir şey. Bu bir uydurmadan başka şey değildir.\""},{"n":8,"t":"\"Öğüt ve uyarı, içimizden ona mı indirildi?\" Hayır, onlar benim zikrimden/Kur'an'ımdan kuşkulandılar. Hayır, onlar benim azabımı henüz tatmadılar."},{"n":9,"t":"Yoksa Azîz, Vahhâb olan Rabbinin rahmetinin hazineleri onların katında mı?"},{"n":10,"t":"Yoksa göklerin, yerin ve bu ikisi arasında bulunanların mülk ve saltanatı onların mı? Eğer öyleyse sebepler içinde yükselsinler."},{"n":11,"t":"Kabilelerden oluşmuş, sözüm ona bir ordudur bu; şurada bozguna uğratılacaktır."},{"n":12,"t":"Onlardan önce Nûh kavmi ve Âd da yalanlamıştı. Kazıklar sahibi Firavun da..."},{"n":13,"t":"Semûd, Lût kavmi, o sık ağaçları besleyen su kaynağının sahipleri Eykeliler de. İşte onlar da böyle hiziplerdi."},{"n":14,"t":"Bunların hepsi, resulleri yalanlamaktan başka bir şey yapmadılar. Sonunda azabım hak oldu."},{"n":15,"t":"Bunların beklediği de sadece, en küçük bir gecikmesi olmayan o müthiş titreşimli tek sestir."},{"n":16,"t":"Şöyle dediler: \"Rabbimiz, bizim payımızı/hesap defterimizi, hesap gününden önce çabucak ver!\""},{"n":17,"t":"Onların dediklerine sabret! O kuvvet sahibi kulumuz Davûd'u an! O, tespih nağmeleri döktüren bir kul idi."},{"n":18,"t":"Dağları onunla birlikte buyruk altına almıştık: Akşam-sabah birlikte tespih ederlerdi."},{"n":19,"t":"Kuşlar da toplu halde onunla beraberdi. Hepsi, onun tespih nağmelerine katılırdı."},{"n":20,"t":"Mülk ve yönetimini güçlendirmiştik. Kendisine hikmet ve hakla bâtılı ayıran söz etme yeteneği vermiştik."},{"n":21,"t":"Geldi mi sana, o çekişme hikâyesinin haberi? Hani, o hasımlar, duvarı aşarak mihraba ulaşmışlardı."},{"n":22,"t":"Davûd'un yanına girmişlerdi de onlardan korkmuştu. \"Korkma, dediler, biz iki davacıyız. Birimiz ötekinin hakkını çiğnedi. Şimdi sen, aramızda hak ile hükmet, adaletsizlik etme. Bizi yolun denge noktasına ilet.!"},{"n":23,"t":"\"Şu benim kardeşimdir. Kendisinin doksan dokuz koyunu var. Benimse bir tek koyunum var. Buna rağmen, onu da bana ver dedi ve tartışmada bana galip geldi.\""},{"n":24,"t":"Davûd dedi ki: \"Vallahi, senin bir tek koyununu kendi koyunlarına katmak istemekle sana zulmetmiş. Zaten ortaklardan birçoğu birbiri aleyhine haksızlık ve zulme sapar. İman edip hakka ve barışa yönelik işler yapanlar böyle değildir. Ama onlar da pek azdır.\" Davûd, kendisini imtihan ettiğimizi düşündü; hemen Rabbinden af diledi; rükû ederek yerlere eğildi ve Allah'a yöneldi."},{"n":25,"t":"Biz de ondan o günahı affettik. Katımızdan onun için bir yakınlık ve güzel bir gelecek var."},{"n":26,"t":"Ey Davûd, seni yeryüzünde bir halife yaptık. Artık insanlar arasında hakla hükmet; geçici hevese uyma ki, seni Allah yolundan saptırmasın. Allah yolundan sapanlar için, hesap gününü unutmuş olmaları yüzünden şiddetli bir azap vardır."},{"n":27,"t":"Biz şu göğü ve yeri ve ikisi arasındakileri boşuna yaratmadık. Böyle düşünmek, küfre sapanların sanısıdır. Vay hallerine o inkârcıların, ateş yüzünden!"},{"n":28,"t":"Yoksa biz, iman edip hakka ve barışa yönelik işler yapanları, yeryüzünde fesat çıkaranlarla aynı mı tutacağız? Yoksa takva sahiplerini, arsız sapıklar gibi mi yapacağız?"},{"n":29,"t":"Kutsal/bereketli bir Kitap bu; sana indirdik ki onu, ayetlerini derin derin düşünsünler ve öğüt alabilsin temiz özlüler."},{"n":30,"t":"Davûd'a Süleyman'ı armağan ettik. Ne güzel kul! Hep Allah'a sığınır, yakarırdı."},{"n":31,"t":"Akşam üstü kendisine, üç ayak üzerine basıp bir ayağını tırnak üstüne diken saf kan koşu atları sunulmuştu."},{"n":32,"t":"Dedi: \"Servet sevgisini, Rabbimi anmak için benimsedim.\" Nihayet Güneş perde ardına çekildi."},{"n":33,"t":"\"Geri getirin bana onları!\" dedi. Bacaklarını, boyunlarını sıvazlamaya başladı."},{"n":34,"t":"Yemin olsun ki biz, Süleyman'ı imtihan ettik, tahtının üstüne bir ceset bıraktık da o, tövbe ile Allah'a yöneldi."},{"n":35,"t":"Şöyle yakardı: \"Rabbim, affet beni! Benden sonra kimseye yaraşmayacak bir mülk/saltanat ver bana! Kuşkusuz sensin, evet sensin Vahhâb!"},{"n":36,"t":"Bunun üzerine, rüzgârı onun emrine verdik; onun emriyle onun istediği yere uysal uysal/tatlı tatlı akıp giderdi."},{"n":37,"t":"Şeytanları da onun emrine verdik. Hepsi bina ustası ve dalgıçtı."},{"n":38,"t":"Ve demirlerle birbirine bağlı diğerlerini..."},{"n":39,"t":"Bu, bizim lütfumuzdur; ister ver, ister elinde tut. Hesap yok..."},{"n":40,"t":"Ve gerçekten, katımızda onun bir yakınlığı ve güzel bir geleceği vardı."},{"n":41,"t":"Kulumuz Eyyûb'u da an! Hani, Rabbine şöyle seslenmişti: \"Şeytan bana bir yorgunluk ve azap dokundurdu.\""},{"n":42,"t":"\"Ayağını yere vur! İşte yıkanacak bir yer, işte içilecek soğuk bir su!...\" dedik."},{"n":43,"t":"Ona bizden bir rahmet ve özü temizlere bir hatırlatma olarak, ailesini ve beraberlerinde, benzerlerini bağışladık."},{"n":44,"t":"\"Eline bir demet sap al da onunla vur ve yeminine ters düşmüş olma!\" dedik. Biz onu sabırlı bulduk. Ne güzel kuldu o! Bize yönelen, yakaran biriydi o."},{"n":45,"t":"Güçlü-kuvvetli, bakış ve görüş sahibi kullarımız İbrahim, İshak ve Yakub'u da an!"},{"n":46,"t":"Biz onları, yurdu düşünme özellikleriyle yücelen tertemiz kullar yaptık."},{"n":47,"t":"Ve bizim katımızda onlar seçkin, hayırlı kimselerdendi."},{"n":48,"t":"İsmail'i, Elyese'i, Zülkifl'i de an! Hepsi seçkinlerdendi."},{"n":49,"t":"Bir hatırlatmadır bu! Korunup sakınanlar için elbette güzel bir gelecek vardır."},{"n":50,"t":"Kapıları kendilerine açılmış Adn cennetleri."},{"n":51,"t":"Orada, yaslanmış olarak birçok meyve ve içecek isterler."},{"n":52,"t":"Yanlarında, bakışlarını eşlerine yöneltmiş yaşıt dilberler vardır."},{"n":53,"t":"Hesap günü için size vaat edilen işte budur."},{"n":54,"t":"İşte bu, bizim verdiğimiz rızıktır elbette. Bitip tükenmesi yoktur onun."},{"n":55,"t":"Bu, budur! Azgınlara da kötü bir gelecek vardır elbette!"},{"n":56,"t":"İçine dalacakları cehennem! Ne kötü döşektir o!"},{"n":57,"t":"İşte burada! Hadi, tatsınlar onu: Kaynar su, kokuşmuş irin."},{"n":58,"t":"Ve o türden bir başkası daha: Çifter çifter."},{"n":59,"t":"Şöyle denilir: \"İşte sizinle birlikte direnişe geçen bir grup. 'Merhaba' yok onlara! Onlar ateşe salınıyorlar.\""},{"n":60,"t":"Dediler: \"Hayır, size merhaba yok. Onu siz önümüze çıkardınız. Ne kötü durak yeridir o!\""},{"n":61,"t":"Şöyle yakardılar: \"Rabbimiz, bunu bizim önümüze çıkaranın ateşteki azabını bir kat daha artır.\""},{"n":62,"t":"Şöyle dediler: \"Şer temsilcilerinden saydığımız adamları, acaba neden görmüyoruz?\""},{"n":63,"t":"\"Onları alaya alırdık; yoksa gözler onlardan kaydı mı?\""},{"n":64,"t":"İşte bu, kesin gerçektir. Ateş halkının çekişmesi gerçekleşecektir."},{"n":65,"t":"De ki: \"Ben, sadece bir uyarıcıyım. O Vâhid ve Kahhâr Allah'tan başka hiçbir ilah yoktur.\""},{"n":66,"t":"\"Göklerin, yerin ve bunlar arasındakilerin Rabbi'dir O. Azîz ve Gaffâr...\""},{"n":67,"t":"De ki: \"Büyük bir haberdir o.\""},{"n":68,"t":"\"Yüz çevirip duruyorsunuz ondan.\""},{"n":69,"t":"\"Onlar tartışırlarken, o yüce konsey hakkında benim hiçbir bilgim yoktu.\""},{"n":70,"t":"\"Bana, sadece açık bir uyarıcı olduğum vahyediliyor.\""},{"n":71,"t":"Hani, Rabbin meleklere şöyle demişti: \"Ben çamurdan bir insan yaratacağım.\""},{"n":72,"t":"\"Onu kıvama erdirip içine ruhumdan üflediğimde, önünde secde ederek eğilin!\""},{"n":73,"t":"Bunun üzerine meleklerin hepsi toptan secde etmişlerdi."},{"n":74,"t":"İblis etmemişti. O, kibre sapmış ve inkârcılardan olmuştu."},{"n":75,"t":"Allah dedi: \"Ey İblis, iki elimle yarattığıma secde etmekten seni alıkoyan neydi? Burnu büyüklük mü ettin, yoksa yücelenlerden mi oldun?\""},{"n":76,"t":"İblis dedi: \"Ben ondan hayırlıyım! Beni ateşten yarattın, onu çamurdan yarattın.\""},{"n":77,"t":"Buyurdu: \"Hadi, çık oradan! Sen kovulmuş birisin.\""},{"n":78,"t":"\"Din gününe kadar lanetim üzerinedir.\""},{"n":79,"t":"Dedi: \"Rabbim, o halde insanların diriltileceği güne kadar bana süre ver.\""},{"n":80,"t":"Buyurdu: \"Peki, süre verilenlerdensin.\""},{"n":81,"t":"\"O bilinen güne kadar.\""},{"n":82,"t":"Dedi: \"Kudret ve şerefine yemin olsun ki, onların tümünü azdıracağım.\""},{"n":83,"t":"\"İçlerinden sadece samimi, seçkin kullar dışta kalacaktır.\""},{"n":84,"t":"Buyurdu: \"İşte bu doğru! Ben de yalnız doğruyu söylerim.\""},{"n":85,"t":"\"Gerçek şu ki, ben cehennemi seninle ve onlardan sana uyanlarla tamamen dolduracağım.\""},{"n":86,"t":"De ki: \"Tebliğime karşılık sizden bir ücret istemiyorum. Ben size kendiliğimden/zorlamayla yükümlülük getirenlerden de değilim.\""},{"n":87,"t":"Bu, âlemler için bir Zikir'den başka şey değildir."},{"n":88,"t":"Yemin olsun, bir süre sonra onun haberini bileceksiniz."}],[{"n":1,"t":"Bu Kitap'ın indirilişi Azîz ve Hakîm olan Allah'tandır."},{"n":2,"t":"Emin ol, bu Kitap'ı biz sana hak olarak indirdik. O halde, dini yalnız ona özgüleyerek Allah'a ibadet et/O'nun için iş yapıp değer üret!"},{"n":3,"t":"Gözünüzü açıp kendinize gelin! Arı-duru din yalnız ve yalnız Allah'ındır! O'nun yanında birilerini daha veliler edinerek, \"Biz onlara, bizi Allah'a yaklaştırmaları dışında bir şey için kulluk etmiyoruz.\" diyenlere gelince, hiç kuşkusuz, Allah onlar arasında, tartışıp durdukları konuyla ilgili hükmü verecektir. Şu bir gerçek ki, Allah, yalancı ve nankör kişiyi iyiye ve güzele kılavuzlamaz."},{"n":4,"t":"Eğer Allah bir çocuk edinmek isteseydi, yaratmakta olduklarından dilediğini seçerdi. Böyle bir şeyden arınmıştır O. Allah'tır, Vahîd'dir, Kahhâr'dır O."},{"n":5,"t":"Gökleri ve yeri hak olarak yaratmıştır. Geceyi gündüzün üstüne çekip örtüyor; gündüzü de gecenin üstüne sarıp dürüyor. Güneş'i ve Ay'ı bir buyruğa boyun eğdirmiştir. Hepsi, belirlenmiş bir süreye kadar akar gider. Gözünüzü açın; Azîz'dir O, Gaffâr'dır."},{"n":6,"t":"Sizi bir tek canlıdan yarattı; sonra o canlıdan onun eşini vücuda getirdi. Ve sizin için davarlardan sekiz çift indirmiştir. Sizi annelerinizin karınlarında üç karanlık içinde, bir yaratıştan öbürüne geçirerek oluşturuyor. İşte Allah! Budur sizin Rabbiniz! Yalnız O'nundur mülk ve saltanat! İlah yoktur O'ndan başka! Hal böyle iken nasıl oluyor da gerçeğin tersine döndürülüyorsunuz?!"},{"n":7,"t":"Eğer nankörlüğe saparsanız şu bir gerçek ki, Allah size muhtaç olmayacak bir Ganî'dir. O, kulları için inkâr ve nankörlüğe razı olmaz. Eğer şükrederseniz bunu sizin için rızasına uygun bulur. Hiçbir günahkâr bir başkasının günahını yüklenmez. Sonunda dönüşünüz ancak Rabbinizedir. O size, işlemiş olduklarınızı haber verecektir. O, göğüslerin saklamakta olduklarını çok iyi bilir."},{"n":8,"t":"İnsana bir zarar/zorluk dokununca, Rabbine yönelerek O'na dua eder. Sonra ona bir nimet lütfettiğinde, önceden O'na yalvarmakta olduğunu unutur, O'nun yolundan saptırmak için Allah'a eşler, ortaklar isnat eder. De ki: \"Birazcık nimetlen küfrünle! Hiç kuşkusuz, sen, ateş halkındansın.\""},{"n":9,"t":"Böyle birisi; gece saatlerinde secde ederek, ayakta durarak ibadet eden, âhiretten korkan, Rabbinin rahmetini uman biri gibi midir? De ki: \"Hiç bilenlerle bilmeyenler eşit olur mu? Ancak gönül ve akıl sahipleri düşünüp ibret alır.\""},{"n":10,"t":"Tarafımdan söyle: \"Ey iman eden kullarım, Rabbinizden korkun! Bu dünya hayatında güzel düşünüp güzel davrananlara güzellik var. Allah'ın toprağı/yeryüzü geniştir. Sadece sabredenlere, ücretleri hesapsız ödenecektir.\""},{"n":11,"t":"De ki: \"Bana, dini yalnız Allah'a özgüleyerek, O'na ibadet etmem/O'nun için iş yapıp değer üretmem emredildi.\""},{"n":12,"t":"\"Ve bana, müslümanların ilki olmam emredildi.\""},{"n":13,"t":"De ki: \"Eğer Rabbime isyan edersem büyük bir günün azabından korkarım.\""},{"n":14,"t":"De ki: \"Ben, dinimi yalnız kendisine özgüleyerek, Allah'a ibadet ediyorum/O'nun için iş yapıp değer üretiyorum.\""},{"n":15,"t":"\"Siz O'nun dışında dilediğinize kulluk/ibadet edin.\" De ki: \"Hüsrana uğrayanlar, kıyamet günü hem kendilerini hem de ailelerini hüsrana atanlardır. Dikkat edin! Apaçık hüsranın ta kendisi işte budur.\""},{"n":16,"t":"Onların üstlerinde ateşten gölgeler, altlarından da gölgeler vardır. İşte Allah, kullarını bundan korkmaya çağırıyor. \"Ey kullarım, benden sakının!\""},{"n":17,"t":"Tâğuttan, ona kulluk etmekten kaçınıp Allah'a yönelenlere müjde var! Muştula kullarıma!"},{"n":18,"t":"Onlar ki, sözü dinler de onun en güzeline uyarlar. İşte bunlardan, Allah'ın kılavuzladıkları; işte bunlardır, akıl ve gönül sahipleri."},{"n":19,"t":"Üzerine azap sözü hak olanı, ateşe dalmış olanı sen mi kurtaracaksın?"},{"n":20,"t":"Hayır, kurtaramazsınız! Rablerinden sakınanlara gelince, onlar için üst üste bina edilmiş odalar var; altlarından ırmaklar akar. Allah'ın vaadidir bu, Allah vaadine ters düşmez."},{"n":21,"t":"Görmedin mi, Allah gökten bir su indirdi de onu toprak içindeki kaynaklara ulaştırdı. Sonra onunla çeşitli renklerde ekinler çıkarıyor. Sonra ekin kurur da sen onu sararmış görürsün. Sonra da onu kuru ufantı haline getirir. İşte bunda, akıl ve gönül sahipleri için mutlak bir ibret var."},{"n":22,"t":"Allah'ın, göğsünü İslam'a açtığı kimse, Rabbinden bir ışık üzerinde olmaz mı? Allah'ın zikrine/Kur'an'a karşı kalpleri katılaşmış olanlara yazıklar olsun! İşte onlardır, açık bir sapıklık içindekiler."},{"n":23,"t":"Allah, sözün/hadisin en güzelini, birbirine benzer iç içe ikili mânalar ifade eden bir Kitap halinde indirmiştir. Rablerinden korkanların ondan derileri ürperir. Sonra da hem derileri hem de kalpleri, Allah'ın zikri/Kur'an'ı karşısında yumuşar. Bu, Allah'ın kılavuzudur ki, onunla dilediğini/dileyeni hidayete erdirir. Allah'ın saptırdığına gelince, ona kılavuzluk edecek yoktur."},{"n":24,"t":"Zalimlere, \"Kazanmış olduğunuzu tadın!\" denildiğinde, kıyamet günü o kötü azaptan yüzünü kim koruyabilir?"},{"n":25,"t":"Onlardan öncekiler de yalanlamıştı. Fakat azap kendilerine, hiç farkında olmadıkları bir yerden geldi."},{"n":26,"t":"Allah; onlara dünyada rezilliği tattırdı. Âhiretin azabı ise elbette daha büyüktür. Bir bilselerdi!..."},{"n":27,"t":"Yemin olsun, biz bu Kur'an'da insanlara her türden örnekler verdik ki düşünüp öğüt alabilsinler."},{"n":28,"t":"Bunu, eğri-büğrüsü olmayan Arapça bir Kur'an olarak indirdik ki, korunup sakınabilsinler."},{"n":29,"t":"Allah; hakkında birbiriyle didişen ortakların bulunduğu bir adamla, bir tek ere teslim olan bir adamı örnek verdi. Örnek olarak bu ikisi eşit olur mu? Hamt, yalnız Allah'adır! Ama onların çokları bilmiyorlar."},{"n":30,"t":"Hiç kuşkusuz sen de öleceksin, onlar da ölecekler!"},{"n":31,"t":"Sonra siz, kıyamet günü Rabbinizin huzurunda davalaşacaksınız."},{"n":32,"t":"Allah hakkında yalan düzenden ve kendisine gelen doğruyu yalanlayandan daha zalim kim vardır? Cehennemde kâfirler için bir barınak yok mu?"},{"n":33,"t":"Doğruyu getirene ve onu tasdikleyene gelince, işte böyleleri, korunanların ta kendileridir."},{"n":34,"t":"Rableri katında onlar için diledikleri her şey vardır. İşte güzel düşünüp güzel davrananların ödülü budur."},{"n":35,"t":"Böylece, Allah onların yaptıklarının en kötülerini örtecek, ödüllerini, yaptıklarının en güzeliyle verecek."},{"n":36,"t":"Allah, kuluna Kâfi değil mi, yetmiyor mu? Seni, O'ndan başkalarıyla korkutuyorlar. Allah kimi saptırırsa artık ona kılavuzluk edecek yoktur."},{"n":37,"t":"Allah'ın kılavuzluk ettiğini ise saptıran olamaz. Allah Azîz ve intikam alıcı değil mi?"},{"n":38,"t":"Onlara, \"Gökleri ve yeri kim yarattı?\" diye sorsan, yemin olsun \"Allah!\" diyecekler. De onlara: \"Peki, Allah dışındaki yakardıklarınız hakkında ne diyorsunuz? Allah bana bir zarar vermek istese, O'nun vereceği zararı uzaklaştırabilirler mi? Yahut bana bir rahmet dilese, O'nun rahmetini tutabilirler mi?\" De ki: \"Bana Allah yeter! Tevekkül edenler O'na dayanıp güvenirler.\""},{"n":39,"t":"De ki: \"Ey toplumum! Yapabildiğinizi yapın; ben de kendi işimi yapacağım. Yakında bileceksiniz."},{"n":40,"t":"Kime geliyor rezil edici azap, kime iniyor bitip tükenmeyen azap?\""},{"n":41,"t":"Kuşkusuz, bu Kitap'ı biz sana insanlar için hak olarak indirdik. Artık kim doğru yolu seçerse kendi lehinedir; kim de saparsa kendi aleyhine sapmış olur. Sen onlar üzerine vekil değilsin."},{"n":42,"t":"Allah, canları, ölümleri sırasında alır, ölmeyenleri de uykuları sırasında. Sonra, haklarında ölüm hükmü verdiklerini alıkoyar; ötekileri, belirlenen bir süreye kadar salıverir. Bunda, iyice düşünen bir toplum için elbette ibretler vardır."},{"n":43,"t":"Yoksa Allah'ın berisinden şefaatçılar mı edindiler? De ki: \"Onlar hiçbir şeye sahip olmayan/hiçbir şeye gücü yetmeyen, aklını da işletmeyen varlıklar olsalar da mı?\""},{"n":44,"t":"De ki: \"Şefaat, tümden ve sadece Allah'ındır. Göklerin ve yerin mülkü/yönetimi O'nundur. Sonunda O'na döndürüleceksiniz.\""},{"n":45,"t":"Allah yalnız başına anıldığında, âhirete inanmayanların kalpleri nefretle ürperir; O'nun berisindeki, ilahlaştırılmış kişilerle birlikte anıldığında ise hemen müjdelenmiş gibi sevinirler."},{"n":46,"t":"De ki: \"Ey Allahım! Ey gökler ve yeri yaratan, ey görülmeyeni ve görüleni bilen! Sen hüküm vereceksin kulların arasında, ihtilaf ettikleri şeyleri hakkında.\""},{"n":47,"t":"Eğer yerdekilerin tamamı ve beraberinde bir o kadarı, zulmedenlerin olsa, kıyamet günü azabın kötülüğünden kurtulmak için tümünü mutlaka fidye verirlerdi. Çünkü hiç hesaba katmadıkları şeyler, Allah tarafından karşılarına çıkarılmıştır."},{"n":48,"t":"Kazanmış olduklarının çirkinlikleri, önlerinde belirlenmiş; alay edegeldikleri şey kendilerini sarıvermiştir."},{"n":49,"t":"İnsana bir zorluk/zarar dokunduğunda bize yalvarır-yakarır; sonra ona bizden bir nimet lütfettiğimizde şöyle der: \"Bu bir ilim sayesinde verildi bana!\" Hayır, öyle değil; o bir fitnedir ama onların çokları bilmiyorlar."},{"n":50,"t":"Onlardan öncekiler de bunu söylemişlerdi ama kazandıkları şeyler kendilerine hiçbir yarar sağlamamıştı."},{"n":51,"t":"Sonunda, kazanmış olduklarının çirkinlikleri yakalarına yapışmıştı. Şunların zulmedenlerine de kazandıklarının kötülükleri gelip çatacaktır. Ve onlar kimseyi âciz de bırakamayacaklar/onlar bunu etkisiz de bırakamazlar."},{"n":52,"t":"Bilmediler mi ki Allah, rızkı dilediğine açıp yayar da kısıp daraltır da. İman eden bir toplum için bunda elbette ibretler vardır."},{"n":53,"t":"De ki: \"Ey öz benlikleri aleyhine sınırı aşan/aşırı giden kullarım! Allah'ın rahmetinden ümit kesmeyin! Allah, günahları tümden affeder. Çünkü O, mutlak Gafûr, mutlak Rahîm'dir."},{"n":54,"t":"Azap yakanıza yapışmadan Rabbinize dönüp O'na teslim olun! Sonra size yardım edilmez."},{"n":55,"t":"Farkında olmadığınız bir sırada, azap ansızın karşınıza çıkmadan önce size Rabbinizden indirilenin en güzeline uyun!"},{"n":56,"t":"Benlik şöyle diyecektir o zaman: \"Allah'a karşı aşırı gitmem yüzünden başıma gelenlere bak! Alay edip duranlardan biriydim doğrusu!...\""},{"n":57,"t":"Yahut şöyle diyecektir: \"Allah bana kılavuzluk etseydi elbette ben de sakınanlardan olurdum!\""},{"n":58,"t":"Azabı gördüğünde şöyle de konuşacaktır: \"Bana bir kez daha imkân verilseydi de güzel düşünüp güzel davrananlardan olsaydım!\""},{"n":59,"t":"Hayır, olamaz! Ayetlerim sana geldi de onları hemen yalanlayıverdin; büyüklük tasladın ve kâfirlerden oldun."},{"n":60,"t":"Allah'a yalan isnat edenleri, kıyamet günü yüzleri simsiyah halde görürsün. Kibirliler için cehennemde bir barınak mı yok!"},{"n":61,"t":"Korunup sakınanları Allah, kendi başarıları yüzünden kurtarır. Ne kötülük dokunur onlara ne de kederlenirler."},{"n":62,"t":"Allah Haalik'tir, her şeyin yaratıcısıdır. Her şey üzerine Vekil olan da O'dur."},{"n":63,"t":"Göklerin ve yerin kilitleri/anahtarları O'nundur. Allah'ın ayetlerini inkâr edenler, hüsrana uğrayanların ta kendileridir."},{"n":64,"t":"De ki: \"Bana, Allah'tan başkasına kulluk etmemi mi emrediyorsunuz, ey cahiller?\""},{"n":65,"t":"Yemin olsun, sana da senden öncekilere de şu vahyedilmiştir: Eğer şirke saparsan amelin kesinlikle boşa çıkar ve mutlaka hüsrana düşenlerden olursun."},{"n":66,"t":"Başkasına değil, sadece Allah'a kulluk/ibadet et; şükredenlerden ol!"},{"n":67,"t":"Allah'ı, kadrine/şanına yaraşır şekilde tanıyamadılar. Oysaki kıyamet günü, yeryüzü tamamen O'nun avucudur/avucundadır; gökler de O'nun sağ elinde/kudretinde dürülmüş haldedir. Şanı yücedir O'nun; arınmıştır onların ortak koştuklarından."},{"n":68,"t":"Sûra üflenmiştir; Allah'ın dilediği kimseler dışında göklerde kim var, yerde kim varsa çarpılıp yere yıkılmıştır. Sonra sûra bir daha üflenmiştir. İşte hepsi ayağa kalkmış bakıyorlar."},{"n":69,"t":"Yeryüzü, Rabbinin nuruyla parıldamış, Kitap ortaya konmuş, peygamberler, tanıklar getirilip aralarında hakla hüküm verilmiştir. Onlar asla haksızlığa uğratılmazlar."},{"n":70,"t":"Herkesin yapıp ettiğinin karşılığı tam verilir. O, onların neler yaptıklarını daha iyi bilmektedir."},{"n":71,"t":"İnkâr edenler bölük bölük cehenneme sevk edilirler. Oraya geldiklerinde onun kapıları açılır ve cehennem bekçileri onlara şöyle derler: \"Size, içinizden resuller gelmedi mi ki, Rabbinizin ayetlerini karşınızda okusunlar ve sizi şu gününüze kavuşmanız hususunda uyarsınlar?\" Onlar: \"Evet, derler, geldi ama inkârcılar hakkında azap hükmü hak oldu.\""},{"n":72,"t":"Şöyle denilir: \"Girin cehennemin kapılarından! Orada uzun süre kalacaksınız. Büyüklük taslayanların barınağı ne de kötüymüş!\""},{"n":73,"t":"Rablerinden sakınanlar da bölükler halinde cennete sevk edilirler. Oraya geldiklerinde, cennet kapıları da kendilerine açıldığında, oranın bekçileri onlara şöyle derler: \"Selam size! Tertemizsiniz. Hadi girin şuraya, sürekli kalıcılar olarak!\""},{"n":74,"t":"Onlar da şöyle derler: \"Hamt olsun o Allah' a ki bize vaadini yerine getirdi, bizi yeryüzüne mirasçılar yaptı. İşte, cennetten istediğimiz yerde konaklıyoruz. İş yapıp değer üretenlerin ödülü ne de güzelmiş!\""},{"n":75,"t":"Melekleri de arşın çevresini kuşatarak Rablerinin hamdiyle tespih eder halde görürsün. Aralarında hakla hüküm verilmiştir. Nihayet şöyle denir: \"Hamt âlemlerin Rabbi'ne özgüdür!"}],[{"n":1,"t":"Hâ, Mîm."},{"n":2,"t":"Bu kitabın indirilişi, Azîz ve Alîm olan Allah'tandır."},{"n":3,"t":"Ğafir'dir, günahı affedendir. Tövbeyi kabul eden, azabı çetin, lütfu bol olandır O. İlah yoktur O'ndan gayrı. Yalnız O'nadır varış ve dönüş."},{"n":4,"t":"Allah'ın ayetleri hakkında, küfre sapmış olanlardan başkası çekişip didişmez. Onların beldelerde dolaşıp durmaları seni aldatmasın."},{"n":5,"t":"Onlardan önce Nûh kavmi de yalanlamıştı. Onların ardından gelen gruplar da... Her ümmet, kendi elçisini yakalamak kastıyla ona yöneldi. Hakkı/gerçeği batılla geçersiz kılmak/ortadan kaldırmak için mücadele verdiler. Ama ben onları yakaladım. Peki, azabım nasıl oldu?!"},{"n":6,"t":"İşte böyle! Rabbinin, nankörlüğe sapanlar hakkındaki, \"Onlar ateş yâranıdır\" sözü tam gerçekleşti."},{"n":7,"t":"Arşı yüklenip taşıyanlar ve onun çevresindeki şuurlular Rablerinin hamdi ile tespih ederler ve ona inanırlar. İman sahipleri için de şöyle af dilerler: \"Rabbimiz! Sen her şeyi rahmet ve ilim halinde kuşattın. Tövbe edip senin yoluna uymuş olanları bağışla. Ve onları cehenem azabından koru!\""},{"n":8,"t":"\"Ey Rabbimiz, onları kendilerine vaat etmiş olduğun Adn cennetlerine koy! Atalarından, eşlerinden, zürriyetlerinden barışa yönelenleri de. Azîz ve Hakîm olan, hiç kuşkusuz sensin, sen!\""},{"n":9,"t":"\"Koru onları kötülüklerden! O gün kötülüklerden koruduğuna mutlaka rahmet etmişsindir sen! İşte budur o en büyük kurtuluş ve eriş.\""},{"n":10,"t":"Küfre batmış olanlara şöyle haykırılır: \"Allah'ın öfkesi, sizin kendi benliklerinize öfkenizden elbette ki daha büyüktür. Hani, siz imana çağrılıyordunuz da inkâr ediyordunuz!\""},{"n":11,"t":"Dediler: \"Rabbimiz! Bizi iki kez öldürdün, iki kez dirilttin. Artık günahlarımızı itiraf ettik. Buradan çıkmak için bir yol daha var mı?\""},{"n":12,"t":"Bu halinizin sebebi şu: Allah'a, yalnız O'na çağrıldığınızda inkâr etmiştiniz. O'na ortak koşulduğunda ise iman ediyordunuz. Artık hüküm o en yüce, o en büyük olan Allah'ın..."},{"n":13,"t":"O odur ki size ayetlerini gösteriyor ve sizin için gökten bir rızık indiriyor. O'na yönelenden başkası öğüt alamaz."},{"n":14,"t":"Kâfirler hoşlanmasa da siz, dini yalnız O'na özgüleyerek, Allah'a dua edin!"},{"n":15,"t":"O Refî'dir, dereceleri yükseltendir; arşın sahibidir. Buluşma günü hakkında uyarmak için emrinden olan Rûh'u kullarından dilediğine indirir."},{"n":16,"t":"O gün onlar ortaya çıkarlar. Hiçbir şeyleri Allah'a gizli kalmaz. Kimindir bugün mülk/saltanat? O Vâhid ve Kahhâr olan Allah'ın!"},{"n":17,"t":"Bugün her benlik kazandığıyla cezalandırılır. Zulüm yok bugün! Allah, hesabı çabucak görür."},{"n":18,"t":"Onları, yaklaşan felaket günü hakkında uyar! Yürekler gırtlaklara dayanmıştır; yutkunurlar. Zalimlerin ne bir dostu vardır ne de sözü dinlenir bir şefaatçıları."},{"n":19,"t":"O bilir gözlerin hain bakışını ve göğüslerin sakladığını."},{"n":20,"t":"Allah, hak ile hükmeder! O'nun dışında yakardıkları ise hiçbir şeyle hükmedemezler. Allah'tır mutlak Semî', mutlak Basîr..."},{"n":21,"t":"Yeryüzünde gezip dolaşmadılar mı ki kendilerinden öncekilerin sonları nice olmuş görsünler? Onlar, hem kuvvetçe hem de yeryüzündeki eserler bakımından bunlardan daha zorlu idiler. Ama Allah onları günahları yüzünden yakaladı. Ve Allah'a karşı bir koruyanları da olmadı."},{"n":22,"t":"Sebep şuydu: Resulleri onlara açık-seçik mesajlar getirirdi de onlar inkâr ederlerdi. Sonunda Allah hepsini yakaladı. O çok güçlüdür, azabı da şiddetlidir."},{"n":23,"t":"Yemin olsun, Mûsa'yı da ayetlerimizle ve apaçık bir kanıtla göndermiştik."},{"n":24,"t":"Firavun'a, Hâmân'a ve Karun'a göndermiştik de onlar şöyle demişlerdi: \"Tam yalancı bir sihirbazdır bu!\""},{"n":25,"t":"Mûsa, katımızdan hakkı onlara getirince, şöyle dediler: \"Onunla beraber iman edenlerin erkek çocuklarını öldürün, kadınlarını hayata salın/kadınlarına uygunsuzca davranın/kadınlarının rahimlerini yoklayın!\" Ama inkârcıların tuzağı hep boşa çıkmıştır."},{"n":26,"t":"Firavun dedi ki: \"Bırakın, şu Mûsa'yı öldüreyim de Rabbine yalvarsın. Çünkü onun, dininizi değiştirmesinden yahut yeryüzünde fesat çıkarmasından korkuyorum.\""},{"n":27,"t":"Mûsa dedi: \"Ben, hesap gününe inanmayan her kibirliden, benim de Rabbim sizin de Rabbiniz olana sığındım.\""},{"n":28,"t":"Firavun hanedanından, imanını gizleyen bir adam şöyle konuştu: \"Rabbim Allah'tır, dediği için bir adamı öldürüyor musunuz? Üstelik size, Rabbinizden açık-seçik deliller de getirdi. Eğer yalancıysa yalancılığı kendi aleyhinedir. Eğer doğru sözlü ise size vaat ettiklerinden bir kısmı başınıza gelir. Kuşkusuz, Allah, haddi aşan yalancıları doğruya ulaştırmaz.\""},{"n":29,"t":"\"Ey toplumum, bugün bu toprakta, birbirine destek veren insanlar olarak mülk ve yönetim sizin. Peki, karşımıza dikildiği zaman Allah'ın azabından bizi kim kurtaracak?\" Firavun şöyle dedi: \"Ben size kendi fikrimden başkasını göstermem. Ve ben, aydınlık/doğruluk yolundan başkasına da kılavuzlamam.\""},{"n":30,"t":"İman etmiş olan bir adam dedi: \"Ey toplumum, sizin üzerinize, diğer topluluklarınki gibi bir günün gelmesinden korkuyorum;"},{"n":31,"t":"Nûh kavminin, Âd'ın, Semûd'un ve onların ardından gelenlerin serüvenleri gibi. Allah, kulları için zulüm istemiyor.\""},{"n":32,"t":"\"Ey toplumum, sizin adınıza o bağırıp-çağrışma gününden korkuyorum.\""},{"n":33,"t":"\"Bir gündür ki o, sırtınızı dönerek kaçmaya çalışırsınız fakat Allah'a karşı sizi koruyacak kimse olmaz. Allah'ın saptırdığının, yol göstereni yoktur.\""},{"n":34,"t":"Yemin olsun, daha önce Yûsuf da size açık-seçik mesajlar getirmişti de onun size getirdikleri hakkında hep kuşku duymuştunuz. Daha sonra o ölünce de şöyle demiştiniz: \"Allah ondan sonra bir daha asla resul göndermez.\" Allah, sınır tanımaz kuşkucuları işte böyle saptırır."},{"n":35,"t":"Kendilerine gelmiş bir kanıt olmaksızın Allah'ın ayetleri hakkında mücadele edenlerin durumu, hem Allah katında hem de inananların katında büyük bir öfke konusu olmuştur. Allah, tüm zorba, kibirli kalpler üzerine işte böyle mühür basıyor."},{"n":36,"t":"Firavun dedi ki: \"Ey Hâmân, sebeplere ulaşabilmem için bana yüksek bir kule yap!\""},{"n":37,"t":"\"Göklerin sebeplerine ulaşırsam, Mûsa'ın tanrısına, da ulaşırım. Ben onun yalancı biri olduğunu düşünüyorum.\" Firavun'a, yaptığı işin kötülüğü bu şekilde süslü gösterildi de yoldan saptırıldı. Firavun'un tuzağı hep kayıptadır."},{"n":38,"t":"O iman eden kişi dedi ki: \"Ey toplumum! Bana uyun, sizi doğru yola götüreyim.\""},{"n":39,"t":"\"Ey toplumum, şu iğreti dünya hayatı, geçici bir nimetlenmeden ibarettir. Âhiretse sürekli durulacak yurdun ta kendisidir.\""},{"n":40,"t":"\"Kötü bir iş yapan, sadece yaptığı kadarıyla cezalandırılır. Erkek ve kadından mümin olarak iyi bir iş yapana gelince, işte böyleleri cennete girerler ve orada hesapsız bir biçimde rızıklandırılırlar.\""},{"n":41,"t":"\"Ey toplumum! Sebep ne ki; ben sizi kurtuluşa çağırıyorum, siz beni ateşe çağırıyorsunuz.\""},{"n":42,"t":"\"Siz beni, Allah'a nankörlük etmeye ve hakkında hiçbir bilgim olmayan şeyi O'na ortak koşmaya çağırıyorsunuz. Bense sizi o Azîz ve Gaffâr olana davet ediyorum.\""},{"n":43,"t":"\"Sizin beni çağırdığınız şeye, ne dünyada ne de âhirette asla ve asla dua edilemez/onun dünyada ve âhirette çağrı hakkı yoktur. Dönüşümüz-varışımız Allah'adır. Aşırılığa sapanlarsa ateş halkının ta kendileridir.\""},{"n":44,"t":"\"Size söylemekte olduklarımı yakında hatırlayacaksınız. Ben işimi Allah'a havale ediyorum. Allah, kullarını iyice görmektedir.\""},{"n":45,"t":"Allah, o adamı ötekilerin kurdukları tuzakların kötülüklerinden korudu. Firavun ailesini de azabın en beteri kuşattı."},{"n":46,"t":"Sabah-akşam, ateşe arz olunurlar. Kıyamet koptuğu gün de şöyle denir: \"Firavun ailesini azabın en şiddetlisine sokun!\""},{"n":47,"t":"O vakit onlar ateş içinde çekişir dururlar. Horlanan takım, böbürlenen takıma şöyle der: \"Biz sizin uydularınız olmuştuk. Şimdi şu ateşin bir kısmını olsun bizden uzak tutabilir misiniz?\""},{"n":48,"t":"Böbürlenen takım şöyle konuşur: \"Gerçek şu ki, hepimiz ateşin içindeyiz. Allah, kullar arasında hüküm vermiş.\""},{"n":49,"t":"Ateştekiler, cehenem bekçilerine şöyle der: \"Rabbinize yakarın da azabı bizden bir gün olsun hafifletsin!\""},{"n":50,"t":"Bekçiler derler ki: \"Resulleriniz size açık-seçik mesajlar getirmezler miydi?\" Derler ki: \"Elbette getirirlerdi!\" Bekçiler: \"O halde yalvarın durun; inkârcıların yakarışları çıkmazda kalıp gitmiştir.\" diye cevap verirler."},{"n":51,"t":"Şu bir gerçek ki, biz, resullerimize ve iman edenlere, hem dünya hayatında hem de tanıkların ayağa kalkacakları gün mutlaka yardım edeceğiz."},{"n":52,"t":"O gün ileri sürdükleri özürleri, zalimlere yarar sağlamayacaktır. Lanet var onlar için ve yurtların en kötüsü onların."},{"n":53,"t":"Yemin olsun ki, Mûsa'ya o hak kılavuzu verdik ve İsrailoğullarını Kitap'a mirasçı kıldık."},{"n":54,"t":"Akıl ve gönül sahipleri için bir yol gösterici, bir hatırlatıcıdır o."},{"n":55,"t":"Öyleyse sabret! Kuşkun olmasın ki, Allah'ın vaadi haktır. Günahın için af dile. Akşam ve sabah, Rabbini överek tespih et!"},{"n":56,"t":"Kendilerine gelmiş hiçbir kanıt olmadan, Allah'ın ayetleri hakkında tartışıp duranlar var ya, onların göğüslerinde, asla ulaşamayacakları bir büyüklüğün kuruntusu vardır. Artık Allah'a sığın! O'dur Semî, O'dur Basîr."},{"n":57,"t":"Göklerin ve yerin yaratılışı/yarattıkları, insanların yaratılışından/insanlar âleminden elbette daha büyüktür. Ne var ki insanların çokları bilmiyorlar."},{"n":58,"t":"Körle gören, iman edip barışa/hayra yönelik işler yapanlarla kötülük üretenler bir olmaz. Ne kadar da az düşünüyorsunuz!"},{"n":59,"t":"O saat elbette gelecektir; kuşku yok bunda. Fakat insanların çokları inanmazlar."},{"n":60,"t":"Rabbiniz buyurmuştur ki: Dua edin bana, cevap vereyim size! Kibre saparak bana ibadetten uzaklaşanlar, aşağılanmış bir halde cehenneme gireceklerdir."},{"n":61,"t":"Allah, içinde dinlenesiniz diye sizin için geceyi yarattı. Gündüzü de aydınlık kıldı. Şu bir gerçek ki, Allah, insanlara her halde lütufkâr davranıyor fakat insanların çokları şükretmezler."},{"n":62,"t":"İşte o Allah'tır sizin Rabbiniz! Her şeyin yaratıcısıdır O. Tanrı yok O'ndan başka. Durum bu iken, nasıl oluyor da çevriliyorsunuz?"},{"n":63,"t":"Allah'ın ayetlerine kafa tutanlar, işte böyle döndürülürler."},{"n":64,"t":"Allah odur ki, yeryüzünü sizin için durulacak yer, göğü bir bina yaptı; sizi yaratıp donattı ve görünüşünüzü güzel yaptı, sizi temiz ve güzel nimetlerle rızıklandırdı. İşte bu Allah'tır sizin Rabbiniz! Âlemlerin Rabbi olan Allah ne kadar yücedir!"},{"n":65,"t":"Hayy O'dur! Tanrı yoktur O'ndan başka. Dini kendisine özgüleyerek dua edin O'na. Hamt olsun âlemlerin Rabbi'ne!"},{"n":66,"t":"De ki: \"Ben, Rabbimden bana açık-seçik ayetler gelince, sizin, Allah'ın berisinden yakardıklarınıza kulluk etmekten yasaklandım. Ben, âlemlerin Rabbi'ne teslim olmakla emrolundum.\""},{"n":67,"t":"O O'dur ki; sizi önce topraktan, sonra bir spermden, sonra bir embriyodan yarattı. Sonra sizi bebek olarak annelerinizin karnından çıkarıyor, sonra güçlü çağınıza ulaşasınız ve nihayet ihtiyarlar olasınız diye sizi yaşatıyor. İçinizden bir kısmı daha önce vefat ettiriliyor. Tüm bunlar, belirlenen bir süreye ulaşasınız ve aklınızı işletesiniz diyedir."},{"n":68,"t":"O O'dur ki, hem hayat veriyor hem öldürüyor. Bir iş ve oluşa hükmedince, ona sadece \"Ol!\" der; o hemen oluverir."},{"n":69,"t":"Bakmadın mı Allah'ın ayetleri hakkında tartışanlara, nasıl döndürülüyorlar!"},{"n":70,"t":"Kitap'ı ve resullerimiz aracılığıyla gönderdiğimizi yalayanlayanlar, yakında bilecekler!"},{"n":71,"t":"O zaman, boyunlarında bukağılar, zincirler, sürüklenecekler,"},{"n":72,"t":"Kaynar suyun içine. Sonra da ateşte yakılacaklar."},{"n":73,"t":"Sonra onlara şöyle denecek: \"Ortak koştuklarınız nerede?\""},{"n":74,"t":"\"Allah'ın berisinden taptıklarınız nerede?\" Diyecekler ki: \"Bizden uzaklaşıp kayboldular. Doğrusu biz, daha önce hiçbir şeye yakarmıyormuşuz.\" Allah, inkâr edenleri işte böyle saptırır."},{"n":75,"t":"Bütün bunlar, yeryüzünde haksız yere sevinç şımarıklığına düşmeniz, kasılıp kabarmanız yüzündendir."},{"n":76,"t":"Girin cehennemin kapılarından; uzun süre kalacaksınız içeride. Kibirlenenlerin barınağı ne de kötüymüş!"},{"n":77,"t":"Sen sabret! Çünkü Allah'ın vaadi haktır. Onları tehdit ettiğimiz şeyin bir kısmını belki sana gösteririz, belki de seni vefat ettiririz. Sonunda onlar bize döndürülecekler."},{"n":78,"t":"Yemin olsun, biz senden önce de resuller gönderdik. Onların bir kısmının hayat ve hatırasını sana anlattık, bir kısmının hayat ve hatırasından sana bahsetmedik. Hiçbir resulün, Allah'ın izni olmaksızın herhangi bir mucize getirmesi söz konusu olamaz. Allah'ın emri geldiğinde, hakla hükmedilir ve gerçeği hükümsüz kılmaya çalışanlar orada hüsrana uğrarlar."},{"n":79,"t":"Bir kısmından binek edinesiniz, bir kısmından yiyesiniz diye sizin için hayvanları yaratan, O Allah'tır."},{"n":80,"t":"O hayvanlarda sizin için daha nice faydalar vardır. Onları binek yaparak, gönüllerinizdeki arzuya ulaşırsınız. Hem onlar üzerinde hem gemiler üzerinde taşınırsınız."},{"n":81,"t":"Allah size ayetlerini gösteriyor. Allah'ın ayetlerinden hangisini inkâr ediyorsunuz?"},{"n":82,"t":"Yeryüzünde dolaşıp da kendilerinden öncekilerin sonu nice olmuş diye bakmıyorlar mı? Öncekiler bunlardan sayıca daha çok, kuvvetçe daha zorlu ve yeryüzündeki eserler bakımından daha üstün idiler. Ama kazanmış oldukları şeyler, kendilerine hiçbir yarar sağlamadı."},{"n":83,"t":"Resulleri onlara açık-seçik beyyineler getirdiklerinde, onlar, yanlarındaki bilgiyle sevinip övündüler. Ve alay edip durdukları şey kendilerini kuşatıverdi."},{"n":84,"t":"Hışmımızı gördüklerinde, \"Allah'a, yalnızca O'na inandık, O'na ortak koştuğumuz şeyleri inkâr ettik.\" dediler."},{"n":85,"t":"Ne var ki, şiddetimizi gördüklerinde, ettikleri iman kendilerine yarar sağlamadı. Allah'ın, kulları hakkında işleyip duran yolu-yöntemidir bu. İnkârcılar orada hüsrana uğradılar."}],[{"n":1,"t":"Hâ, Mîm."},{"n":2,"t":"Rahman ve Rahîm'den indirilmedir bu..."},{"n":3,"t":"Bilgi ile donanmış bir toplum için ayetleri, Arapça bir Kur'an halinde ayrıntılı kılınmış bir kitaptır bu."},{"n":4,"t":"Muştulayıcı ve uyarıcı olarak. Onların pek çoğu yüz çevirdi; kulak verip dinlemezler onlar."},{"n":5,"t":"Dediler ki: \"Bizi çağırdığı o şeye karşı kalplerimiz kılıflar içinde; kulaklarımızda bir ağırlık, seninle bizim aramızda da bir perde var. O halde, sen işini yap, muhakkak biz de işimizi yapacağız.\""},{"n":6,"t":"De ki: \"Ben sadece sizin gibi bir insanım. İlahınızın bir tek ilah olduğu bana vahyediliyor. O halde şaşıp sendelemeden O'na yönelin ve O'ndan af dileyin. Vay haline ortak koşanların!"},{"n":7,"t":"Onlar zekâtı vermezler. Ölüm sonrası hayatı inkâr edenler de onlardır."},{"n":8,"t":"İman edip hayra ve barışa yönelik işler yapanlara gelince, onlar için minnet altına sokmayan bir ödül vardır."},{"n":9,"t":"De ki: \"Siz, yerküreyi iki günde yaratana gerçekten nankörlük edip O'na ortaklar mı koşuyorsunuz? Âlemlerin Rabbi'dir O.\""},{"n":10,"t":"O, yeryüzüne, denge ve dayanıklık sağlayan dağları üstünden yerleştirdi. Onda bereketlere vücut verdi. Ve onda, azıklarını dört günde takdir edip düzenledi. İsteyip duranlar için eşit miktarda olmak üzere..."},{"n":11,"t":"Sonra buhar/duman halindeki göğe yöneldi de ona ve yerküreye şöyle seslendi: \"İsteyerek veya istemeyerek gelin!\" Onlar şöyle dediler: \"İsteyerek geldik!\""},{"n":12,"t":"Böylece onları, iki günde yedi gök halinde takdir edip her göğe kendi iş ve oluşunu vahyetti. Ve biz, arza en yakın göğü kandillerle ve bir korumayla donattık. İşler bunlar Azîz ve Alîm olanın takdiridir."},{"n":13,"t":"Yüz çevirirlerse şöyle de: \"Sizi, Âd ve Semûd'a çarpan yıldırıma benzer bir yıldırıma karşı uyarıyorum.\""},{"n":14,"t":"Hani, resuller onlara önlerinden, arkalarından gelerek şöyle demişlerdi: \"Allah'tan başkasına ibadet/kulluk etmeyin!\" Şöyle cevap vermişlerdi: \"Eğer Rabbimiz isteseydi, kesinlikle melekler indirirdi. Bu yüzden biz sizinle gönderileni tanımıyoruz.\""},{"n":15,"t":"Âd toplumu yeryüzünde haksız bir biçimde büyüklük tasladı da şöyle dediler: \"Bizden daha güçlü kim var?\" Onlar, kendilerini yaratan Allah'ın, evet O'nun, onlardan daha kuvvetli olduğunu görmediler mi? Bunlar, bizim ayetlerimize de karşı çıkıyorlardı."},{"n":16,"t":"Biz de onlara dünya hayatında zillet azabını tattırmak için o uğursuz günlerde üzerlerine dondurucu bir rüzgâr gönderdik. Âhiretin azabı elbette ki daha rezil edicidir. Üstelik onlar hiçbir yardım da görmeyeceklerdir."},{"n":17,"t":"Semûd'a gelince, biz onlara kılavuzluk ettik ama onlar körlüğü hidayete tercih ettiler. Bunun üzerine, kazandıkları yüzünden, alçaltıcı azabın yıldırımı onları yakaladı."},{"n":18,"t":"İnananları kurtardık, onlar korunuyorlardı."},{"n":19,"t":"Gün olur, Allah'ın düşmanları, düzenli bir biçimde bir araya toplanıp ateşe sürülürler."},{"n":20,"t":"Nihayet, oraya geldiklerinde kulakları, gözleri, derileri, yapıp-ettikleri hakkında onlar aleyhine tanıklık edecektir."},{"n":21,"t":"Derilerine: \"Aleyhimizde neden tanıklık ettiniz?\" derler. Derileri derler ki: \"O her şeyi konuşturan Allah konuşturdu bizi. Hani, sizi ilk seferinde de O yaratmıştı ya! Ve siz O'na döndürüleceksiniz.\""},{"n":22,"t":"Siz, işitme gücünüzün, gözlerinizin, derileriniz aleyhinize yapacağı tanıklıktan gizlenmiyordunuz. Tam aksine siz, yaptıklarınızdan birçoğunu Allah'ın bilmeyeceğini sanıyordunuz."},{"n":23,"t":"İşte, Rabbiniz hakkında beslediğiniz bu zannınız sizi mahvetti de hüsrana uğrayanlardan oldunuz."},{"n":24,"t":"Şimdi eğer dayanabilirlerse, barınakları ateştir. Yok eğer özür dileyip hoşnutluk sağlamak istiyorlarsa, özürleri kabul edilmeyecektir."},{"n":25,"t":"Biz onları birtakım yakınlarla/dostlarla çevreleyip sardık da onlar, önlerinde ve arkalarında ne varsa bunlara süslü gösterdiler. Kendilerinden önceki cin ve insan ümmetleri için hak olan söz, bunlar aleyhine de hak oldu. Çünkü bunlar, hüsrana uğrayanlardı."},{"n":26,"t":"İnkâr edenler dediler ki: \"Şu Kur'an'ı dinlemeyin! O okunurken yaygara koparın ki, galip gelesiniz.\""},{"n":27,"t":"Yemin olsun, o inkârcılara şiddetli bir azabı tattıracağız ve elbette ki onları, yapıp-ettiklerinin en kötüsüyle cezalandıracağız!"},{"n":28,"t":"İşte bu, Allah düşmanlarının cezası olan ateştir. Ayetlerimize karşı çıkmalarından ötürü, orada kendileri için uzun süreli kalış yeri vardır."},{"n":29,"t":"O küfre sapanlar şöyle diyecekler: \"Rabbimiz, cinlerden ve insanlardan bizi saptıranları bize göster ki, onları ayaklarımızın altına alalım da en aşağıda kalanlardan olsunlar.\""},{"n":30,"t":"Şu bir gerçek ki, \"Rabbimiz Allah'tır!\" deyip sonra hiç şaşmadan yol alanlar üzerine, melekler ha bire iner de şöyle derler: \"Korkmayın, üzülmeyin! Size vaat edilen cennetle sevinin.\""},{"n":31,"t":"\"Biz sizin, dünya hayatında da âhirette de dostlarınızız. Cennette sizin için nefislerinizin arzuladığı her şey var. Orada sizin için istediğiniz her şey var."},{"n":32,"t":"\"Gafûr ve Rahîm Allah'tan bir ikram olarak...\""},{"n":33,"t":"Allah'a çağırıp/yakarıp hayra ve barışa yönelik iş yapan ve \"Ben, Müslümanlardanım/Allah'a teslim olanlardanım\" diyen kimseden daha güzel sözlü kim vardır?!"},{"n":34,"t":"Güzellikle çirkinlik/iyilikle kötülük bir olmaz! Kötülüğü, en güzel tavırla sav! O zaman görürsün ki, seninle arasında düşmanlık bulunan kimse, sımsıcak bir dost gibi oluvermiştir."},{"n":35,"t":"Böyle bir tavra, sabredenlerden başkası ulaştırılmaz. Böyle bir tavra, büyük nasip sahibinden başkası ulaştırılmaz."},{"n":36,"t":"Eğer şeytandan gelen kötü bir dürtü seni dürtecek olursa hemen Allah'a sığın! Çünkü en iyi işiten O'dur, en iyi bilen O..."},{"n":37,"t":"Gece ve gündüz, Güneş ve Ay onun ayetlerindendir. Eğer sadece Allah'a kulluk/ibadet ediyorsanız, Güneş'e, Ay'a secde etmeyin; onları yaratan Allah'a secde edin!"},{"n":38,"t":"Eğer büyüklük taslarlarsa bilsinler ki, Rabbin katındakiler hiç usanmadan, gece ve gündüz O'nu tespih ederler."},{"n":39,"t":"Onun ayetlerinden biri de şudur: Sen toprağı boynu büklük/kurumuş görürsün. Fakat biz onun üzerine suyu indirdiğimizde, o titreşir ve kabarır. Onu dirilten, ölüleri de mutlaka diriltecektir. O, her şeye Kadîr'dir."},{"n":40,"t":"Ayetlerimiz hakkında eğri ile doğruyu birbirine katanlar, bize gizli kalmazlar. Şimdi, ateşin içine atılan mı hayırlıdır, kıyamet günü güven içinde gelen mi? Dilediğinizi yapın. O, yapıp ettiklerinizi iyice görmektedir."},{"n":41,"t":"Onlar, o zikiri/Kur'an'ı kendilerine geldiğinde inkâr ettiler. Halbuki o, eşsiz yücelikte bir Kitap'tır."},{"n":42,"t":"Bâtıl ona, ne önünden gelebilir ne de arkasından. Hakîm ve Hamîd Allah'tan bir indirmedir o."},{"n":43,"t":"Senin için söylenen, senden önceki resuller için söylenenden başka şey değildir. Hiç kuşkusuz, senin Rabbin hem çok affedicidir hem de acıklı bir azabın sahibidir."},{"n":44,"t":"Eğer biz onu yabancı dilde bir Kur'an yapsaydık, elbette şöyle diyeceklerdi: \"Ayetleri ayrıntılı kılınmalı değil miydi?/Arap'a yabancı dil mi?/ister yabancı dilde, ister Arapça!\" De ki: \"O, iman edenler için bir kılavuz, bir şifadır. İnanmayanlara gelince, onların kulaklarında bir ağırlık vardır. Ve Kur'an, onlar için bir körlüktür. Böylelerine, çok uzak bir mekândan seslenilmektedir.\""},{"n":45,"t":"Yemin olsun, biz Mûsâ'ya Kitap'ı vermiştik de onda ihtilafa düşülmüştü. Eğer Rabbinden bir söz öne geçmemiş olsaydı, aralarında iş mutlaka bitirilirdi. Onlar onun hakkında, işmizaz ettiren/kuşkuya düşüren bir tereddüt içindedirler."},{"n":46,"t":"Kim hayra ve barışa yönelik bir iş yaparsa kendi lehinedir. Kim de kötülük yaparsa kendi aleyhinedir. Rabbin, kullara asla zulmetmez."},{"n":47,"t":"Kıyamet saatine ilişkin bilgi, Allah'a bırakılır. Onun ilmi dışında ne meyveler kabuğundan çıkar ne de bir dişi gebe kalır veya doğurur. \"Ortaklarım nerede?\" diye seslendiği gün, şöyle diyeceklerdir: \"Bizden hiçbir tanık olmadığını sana arz ederiz.\""},{"n":48,"t":"Daha önce yakarıp durdukları, onlardan uzaklaşıp kaybolmuştur. Kaçacak hiçbir yerleri olmadığını anlamışlardır."},{"n":49,"t":"İnsan, hayır istemekten/hayır için dua etmekten bıkıp usanmaz. Kendisine bir şey dokunmaya görsün; hemen ümidini keser, yıkılır."},{"n":50,"t":"Eğer kendisine dokunan bir zorluktan/zarardan sonra bizden bir rahmet tattırsak, yemin olsun, şöyle diyecektir: \"Bu benim hakkım! Kıyametin kopacağını da sanmıyorum. Rabbime döndürülmüş olsam da şüphesiz, O'nun katında benim için şaşmaz güzellikler vardır.\" Yemin olsun, biz o nankörlük edenlere, yapıp ettiklerini haber vereceğiz. Yemin olsun, o çetin azabı onlara tattıracağız!"},{"n":51,"t":"İnsana nimet verdiğimizde yüz çevirir, yan yatar. Kendisine şer dokununca, hemen duaya koyulur."},{"n":52,"t":"De ki: \"Söyleyin bakalım, o Kur'an Allah katından ise, siz de onu inkâr ettinizse/onun üstünü örttünüzse, dönüşü olmayan kopukluğa düşenden daha sapık kim vardır?\""},{"n":53,"t":"Onlara ayetlerimizi ufuklarda ve öz benliklerinin içinde göstereceğiz. Ta ki, onun hak olduğu kendilerine ayan-beyan belli olsun. Kendisinin her şey üzerinde bir tanık oluşu, senin Rabbine yetmez mi?"},{"n":54,"t":"Dikkat edin, onlar Rablerine kavuşma konusunda bir şüphe içindedirler. Gözünüzü açın! Allah Muhît'tir, her şeyi çepeçevre kuşatmıştır."}],[{"n":1,"t":"Ha, Mîm."},{"n":2,"t":"Ayn, Sîn, Kaf."},{"n":3,"t":"İşte böyle vahyeder sana ve senden öncekilere Azîz ve Hakîm olan Allah!"},{"n":4,"t":"Göklerdeki ve yerdeki her şey O'nundur. Öylesine yüce, öylesine büyüktür O!"},{"n":5,"t":"Gökler, üstlerinden çatlayacak gibi titreşiyor. Melekler de Rablerinin hamdiyle tespih ediyorlar ve yeryüzündekiler için af diliyorlar. Gözünüzü açıp kendinize gelin! Allah'tır ancak hep affeden, hep merhamet eden."},{"n":6,"t":"O'nun berisinden veliler edinenlere gelince, onlar üzerine gözcü de Allah'tır. Sen değilsin onlara vekil."},{"n":7,"t":"İşte böyle! Biz sana Arapça bir Kur'an vahyettik ki, ülke ve medeniyetlerin anasını ve çevresindekileri uyarasın. Ve toplama günü konusunda da uyarıda bulunasın. Hiç kuşku yok o günde. Bir bölük cennettedir, bir bölük ateşte."},{"n":8,"t":"Eğer Allah dileseydi onları bir tek ümmet elbette yapıverirdi. Fakat O, dilediği kişiyi/dileyeni rahmetine sokar. Zalimlere gelince, onlar için ne bir dost vardır ne de bir yardımcı."},{"n":9,"t":"Yoksa O'ndan başka veliler mi edindiler? Allah! O'dur gerçek dost. Ölüleri O diriltir. O herşeye güç yetirir."},{"n":10,"t":"Hakkında ihtilafa düştüğünüz herhangi bir şeyin hükmü Allah'a aittir. İşte bu Allah'tır benim Rabbim! Yalnız O'na güvenip dayandım ben, yalnız O'na yönelirim ben!"},{"n":11,"t":"Gökleri ve yeri ortaya çıkarandır, Fâtır'dır O. Size, benliklerinizden eşler yapmıştır; davarlardan da çiftler. Bu tarz içinde üretiyor sizi. O'nun benzeri gibi bir şey yoktur. Gereğince işiten, gereğince görendir O."},{"n":12,"t":"Göklerin ve yerin kilitleri/anahtarları O'nundur. Rızkı, dilediğine açıp bol bol verir. Kısarak, ölçüyle de verir. Gerçek şu ki, O herşeyi en iyi biçimde bilmektedir."},{"n":13,"t":"Sizin için, dinden, Nûh'a önerdiğini, sana vahyettiğini, İbrahim'e, Mûsa'ya ve İsa'ya önerdiğimizi şöyle diyerek kanunlaştırdı: \"Dini dosdoğru tutun; onda bölünüp fırkalara ayrılmayın!\" Onları çağırdığın bu tutum, şirke bulaşanlara çok ağır gelmiştir. Allah, dilediğini kendisi için seçer ve hakka yönelenleri kendisine iletir."},{"n":14,"t":"Onlar, kendilerine ilim geldikten sonra, sadece aralarındaki hırs, çekememezlik ve azgınlık yüzünden fırkalara bölündüler. Eğer Rabbinden, belirlenmiş bir süreye kadar tehir konusunda bir söz öne geçmiş olmasaydı, aralarında iş mutlaka bitirilirdi. Dini tevarüs eden o Kitap varisleri de onun hakkında, işmizaz ettiren/kuşkuya düşüren bir tereddüt içindedirler."},{"n":15,"t":"İşte bunun için sen çağrıda bulun/dua et ve emrolunduğun gibi dosdoğru yürü. Onların boş arzularına uyma ve şöyle de: \"Allah'ın Kitap'tan indirdiğine inandım. Aranızda adaleti sağlamakla emrolundum. Allah'tır, bizim de Rabbimiz, sizin de Rabbiniz. Bizim amellerimiz bize, sizin amellerinizin size. Bizimle sizin aranızda delil yok. Allah bizi biraraya toplayacaktır/aramızı bulacaktır. Dönüş O'nadır.\""},{"n":16,"t":"Kabul edilişinin ardından Allah hakkında tartışmaya girenlerin delilleri Rableri katında geçersizdir. Bunların üzerlerine öfke, kendilerine şiddetli bir azap vardır."},{"n":17,"t":"Gerçeğe ilişkin Kitap'ı ve adalet ölçüsünü indiren o Allah'tır. Nereden bileceksin, belki de kıyamet saati çok yakındır."},{"n":18,"t":"Kıyamete inanmayanlar onun çabuk gelmesini isterler. İnananlar ise ondan korkuyla titrerler ve onun hak olduğunu bilirler. Dikkat edin, o saat/kıyamet hakkında tartışıp duranlar, dönüşü olmayan bir sapıklığın tam içindedirler."},{"n":19,"t":"Allah, kullarına çok lütufkârdır; dilediğini rızıklandırır. O'dur en güçlü, O'dur en yüce..."},{"n":20,"t":"Âhiret ekini isteyenin o ekinini artırırız; dünya ekini isteyene de ondan veririz. Ama böylesi için âhirette bir nasip yoktur."},{"n":21,"t":"Yoksa onların, dinden, Allah'ın izin vermediği şeyi kendileri için yasalaştıran ortakları mı var? Kesin ayrıma ilişkin söz olmasaydı, aralarında hüküm mutlaka verilirdi. O zalimler var ya, onlar için acıklı bir azap öngörülmüştür."},{"n":22,"t":"Kazandıkları, tepelerine inerken o zalimlerin korkudan titrediklerini göreceksin. İman edip hayra ve barışa yönelik işler yapanlarsa cennetlerin bahçelerindedir. Rableri katında kendileri için, diledikleri herşey vardır. İşte budur o büyük lütuf."},{"n":23,"t":"Allah'ın, iman edip hayra ve barışa yönelik iyi işler yapanlara müjdelediği, işte budur. De ki: \"Ben, buna karşılık sizden, yakın akrabamı/Ehlibeytimi sevmeniz dışında bir ücret istemiyorum.\" Kim bir iyilik/güzellik üretirse onun için, o ürettiğine bir güzellik daha ekleriz. Çünkü Allah Gafûr'dur, çok affeder; Şekûr'dur, iyiliğe karşılık verir/teşekkür eder."},{"n":24,"t":"Yoksa, \"Yalan düzüp Allah'a iftira etti\" mi diyorlar? Allah dilerse senin kalbini mühürler; bâtılı mahveder ve hakkı kendi sözleriyle gerçekleştirir. Kuşkusuz, O, göğüslerin özündekini çok iyi bilir."},{"n":25,"t":"Kullarından tövbeyi kabul eden O'dur. Çirkinlikleri/kötülükleri affeden O, yapıp ettiklerinizi bilen O..."},{"n":26,"t":"İman edip barışa/hayra yönelik işler yapanların dualarını O cevaplıyor, lütfundan onlara fazlasını O veriyor. İnkârcılara da şiddetli bir azap var."},{"n":27,"t":"Eğer Allah, kulları için rızkı yayıp döşeseydi, yeryüzünde mutlaka azarlardı. Ama O, dilediğince ölçülü olarak indiriyor. Çünkü O, kullarından gereğince haberdardır, onları iyice görmektedir."},{"n":28,"t":"O odur ki, kulları umutlarını kestikten sonra yağmuru indirir ve rahmetini yayar. Velî'dir O, Hamîd'dir."},{"n":29,"t":"Gökleri ve yeri ve bu ikisi içinde yaydığı canlıları yaratması da O'nun ayetlerindendir. O, dilediği zamanda onları bir araya getirmeye kadirdir."},{"n":30,"t":"Size gelip çatan her musibet ellerinizin kazandığı yüzündendir. Allah birçoklarını da affediyor."},{"n":31,"t":"Siz yeryüzünde âciz bırakıcılar değilsiniz. Sizin Allah'tan başka ne bir dostunuz vardır ne de bir yardımcınız."},{"n":32,"t":"Denizde o dağlar gibi akıp giden gemiler de O'nun ayetlerindendir."},{"n":33,"t":"Dilerse rüzgârı durdurur da o akıp giden gemiler denizin sırtında donmuş gibi kalırlar. Gereğince sabreden, gereğince şükreden herkes için bütün bunlarda elbette ki ibretler vardır."},{"n":34,"t":"Yahut onları, içindekilerin kazançları yüzünden mahveder. Ama birçoğunu affediyor;"},{"n":35,"t":"Ki ayetlerimiz hakkında tartışıp duranlar kendileri için kaçacak bir yer olmadığını bilsinler."},{"n":36,"t":"Size verilen şeyler, şu iğreti hayatın nimetidir. İnanıp Rablerine tevekkül edenler için Allah katında bulunan ise daha hayırlı, daha kalıcıdır."},{"n":37,"t":"Onlar, günahın büyüklerinden ve tüm iğrençliklerinden uzak dururlar. Öfkelendikleri zamansa, affedenler onlar olur."},{"n":38,"t":"Rablerinin çağrısına cevabı öne çıkarırlar, namazı kılarlar. İşleri, aralarında bir şûra/danışmadır. Kendilerine verdiğimiz rızıklardan da infak ederler."},{"n":39,"t":"Kendilerine zulüm ve haksızlık gelip çattığında, yardımlaşırlar."},{"n":40,"t":"Bir kötülüğün cezası, tıpkısı bir kötülüktür. Fakat affedip barışmayı esas alanın ücretini bizzat Allah verir. O, zalimleri hiç sevmez."},{"n":41,"t":"Zulme uğratılışı ardından kendini savunana gelince, böyleleri aleyhine yol aranamaz."},{"n":42,"t":"Aleyhlerine yol aranacak olan şu kişilerdir ki, insanlara zulmederler ve yeryüzünde haksız yere taşkınlıklar sergilerler/saldırılarda bulunurlar. İşte böyleleri için acıklı bir azap vardır."},{"n":43,"t":"Sabredip bağışlayan bilsin ki, bu, işlerin en zorlularındandır."},{"n":44,"t":"Allah'ın saptırdığına, O'ndan başka dost yoktur. Zalimlerin, azapla yüz yüze geldiklerinde, \"Geri dönüşe bir yol yok mu?\" diye söylendiklerini göreceksin."},{"n":45,"t":"Ve göreceksin onları, zilletten ezilip büzülmüş halde ürkek bakışlarla bakarken, ateşe salınırlar. İnananlar şöyle derler: \"Gerçek hüsrana uğrayanlar, kıyamet günü hem kendilerini hem de ailelerini perişan edenlerdir. Dikkat edin, zalimler, sürüp gidecek bir azabın içindedir.\""},{"n":46,"t":"Onların Allah'tan başka kendilerine yardım edecek velileri yoktur. Allah'ın saptırdığı kimse için artık hiçbir yol yoktur."},{"n":47,"t":"Ertelenmesine Allah'tan izin çıkmayacak gün gelmeden önce, Rabbinizin çağrısına uyun. O gün, sığınacak yeriniz olmayacak; yaptıklarınızı inkârınız da mümkün olmayacak."},{"n":48,"t":"Yüz çevirirlerse, biz seni onlar üzerine bekçi göndermemişiz. Sana düşen, tebliğden başka bir şey değildir. Biz insana, bizden bir rahmet tattırdığımızda, onunla sevinip şımarır. Kendi ellerinin hazırladığından bir kötülük başlarına sarılınca, bakarsın insan, alabildiğine nankörleşmiştir."},{"n":49,"t":"Göklerin ve yerin mülkü/yönetimi Allah'ındır. Dilediğini yaratır. Dilediğine kız evlat bağışlar, dilediğine erkek evlatlar armağan eder."},{"n":50,"t":"Yahut onları erkekler ve dişiler halinde çift verir. Dilediğini de kısır yapar. O'dur bilen, O'dur güç yetiren."},{"n":51,"t":"Allah, bir insanla ancak vahiy yoluyla yahut perde arkasından konuşur; yahut da bir resul gönderir de kendi izniyle dilediğini vahyeder. Yüceler yücesi O'dur; hüküm ve hikmet sahibi O'dur."},{"n":52,"t":"İşte böylece sana da emrimizden bir ruh vahyettik. Sen, kitap nedir, iman nedir bilmezdin. Fakat biz onu, kullarımızdan dilediğimizi kendisiyle kılavuzladığımız bir nur yaptık. Hiç kuşkusuz, sen, dosdoğru bir yola kılavuzluk etmektesin."},{"n":53,"t":"Göklerde ve yerdeki her şeyin sahibi olan Allah'ın yoludur o. Gözünüzü açın, bütün iş ve oluşlar Allah'a varır!"}],[{"n":1,"t":"Hâ, Mîm!"},{"n":2,"t":"O ayan-beyan konuşan Kitap'a yemin olsun ki,"},{"n":3,"t":"Biz onu akıl erdiresiniz diye Arapça bir Kur'an yaptık."},{"n":4,"t":"Ve o, bizim katımızdaki ana Kitap'ta çok yüce, çok hikmetlidir."},{"n":5,"t":"Siz, haddi aşanlardan/zulme sapanlardan oluşan bir toplumsunuz diye, o zikri/Kur'an'ı sizden uzak mı tutalım?"},{"n":6,"t":"Biz, öncekiler için de nice peygamberler gönderdik."},{"n":7,"t":"Onlara bir peygamber geldiğinde mutlaka onunla alay ediyorlardı."},{"n":8,"t":"Biz, gücü-kuvveti onlardan daha üstün olanları da helâk etmişizdir. Öncekilerin örneği geçti."},{"n":9,"t":"Yemin olsun, eğer onlara, \"Gökleri ve yeri kim yarattı?\" diye sorsan, kesinlikle şöyle diyeceklerdir: \"Onları, Azîz ve Alîm olan yarattı!\""},{"n":10,"t":"O, yerküreyi size bir beşik yaptı. Ve onda sizler için yollar oluşturdu ki, varacağınız yere varabilesiniz."},{"n":11,"t":"Gökten bir ölçüye bağlı olarak/bir kaderle su indirmiştir O. O suyla biz ölü bir beldeyi hayata kavuşturduk. İşte siz de böyle çıkarılacaksınız."},{"n":12,"t":"Çiftlerin hepsini O yarattı. Ve sizin için gemilerden, hayvanlardan bindiğiniz şeylere imkân verdi,"},{"n":13,"t":"Bunu yaptınız ki, onların sırtlarına kurulasınız, sonra oralara yerleştiğinizde Rabbinizin nimetini anıp şöyle diyesiniz: \"Şanı yücedir O'nun ki, bunu bizim hizmetimize verdi. Yoksa biz buna güç yetiremezlik.\""},{"n":14,"t":"\"Ve gerçekten biz, halden hale geçerek Rabbimize mutlaka döneceğiz.\""},{"n":15,"t":"Kullarından O'na bir pay çıkardılar/bir parça isnat ettiler. Hiç kuşkusuz, insan apaçık bir nankördür."},{"n":16,"t":"Yoksa Allah, yarattıklarından kızları kendine ayırdı da oğullarla seçkinleşmeyi size mi bıraktı?"},{"n":17,"t":"Onlardan biri, O Rahman'a isnad ettiği kız çocuğuyla müjdelendiğinde, yüzü simsiyah kesilir; kederinden yutkunup durur."},{"n":18,"t":"Süs içinde yetiştirilip de çekişmede/tartışmada belirgin bir kanıt ortaya koyamayan kimseyi mi Allah'a isnad ediyorlar?"},{"n":19,"t":"Rahman'ın kulları olan melekleri, dişiler saydılar. Onların yaratılışına tanık mıydılar? Tanıklıkları yazılacak ve sorguya çekilecekler."},{"n":20,"t":"Bir de dediler ki: \"Rahman dileseydi, onlara tapınmazdık.\" Bu konuda hiçbir bilgileri yoktur. Sadece saçmalıyorlar."},{"n":21,"t":"Yoksa onlara bundan önce bir kitap verdik de ona mı yapışmaktadırlar?"},{"n":22,"t":"Hayır, sadece şunu söylemişlerdir: \"Biz atalarımızı bir ümmet/bir din üzerinde bulduk; onların eserlerini izleyerek biz de doğruya ve güzele varacağız.\""},{"n":23,"t":"İşte böyle! Senden önce de hangi kente bir uyarıcı göndermişsek oranın servetle şımarmış kodamanları mutlaka şöyle demişlerdir: \"Biz atalarımızı bir ümmet/bir din üzerinde bulduk; onların eserlerine uyarak yol alacağız.\""},{"n":24,"t":"Uyarıcı dedi: \"Peki, ben size, atalarınızı üzerinde bulduğunuz şeyden daha iyi yol göstereni getirmiş olsam da mı?\" Dediler: \"Doğrusu, biz seninle gönderilen şeyi tanımıyoruz.\""},{"n":25,"t":"Bunun üzerine onlardan öc aldık. Bir bak, nice olmuştur o yalanlayanların sonu!"},{"n":26,"t":"Bir zaman İbrahim, babasına ve toplumuna şöyle demişti: \"Ben, sizin taptıklarınızdan uzağım.\""},{"n":27,"t":"\"Yalnız beni yaratana kulluk ederim. Bana, O kılavuzluk edecektir.\""},{"n":28,"t":"O, sözünü, kendinden sonra yaşayacak bir mesaj yaptı ki, insanlar hakka dönebilsinler."},{"n":29,"t":"Ben, şunlar ve atalarını, kendilerine hak ve açık kanıtlı resul gelinceye kadar nimetlendirdim."},{"n":30,"t":"Ne var ki, hak kendilerine geldiğinde şöyle dediler: \"Bu bir büyü, biz bunu inkâr ediyoruz!\""},{"n":31,"t":"Ve dediler: \"Şu Kur'an, iki kent içinden büyük bir adama indirilmeli değil miydi?\""},{"n":32,"t":"Rabbinin rahmetini onlar mı bölüştürüyorlar? Dünya hayatında onların geçimliklerini aralarında biz paylaştırdık. Ve onların kimini kimine derecelerle üstün kıldık ki, bazısı bazısını tutup çalıştırsın. Rabbinin rahmeti, onların derleyip topladıklarından daha hayırlıdır."},{"n":33,"t":"Eğer insanlar tek bir ümmet/ küfürde birleşen tek bir toplum haline gelmeyecek olsalardı, o Rahman'a nankörlük edenlerin evlerine gümüşten tavanlar ve üzerlerinde yükselecekleri merdivenler yapardık."},{"n":34,"t":"Evlerine kapılar, üzerlerinde yan yatacakları koltuklar yapardık;"},{"n":35,"t":"Her yanda süsler oluştururduk. İşte bütün bunlar, şu iğreti dünya hayatının nimetidir. Rabbinin katındaki âhiret ise takva sahipleri içindir."},{"n":36,"t":"Kim Rahman'ın Zikri'ni görmezlikten gelip ondan uzaklaşırsa biz ona bir şeytanı musallat ederiz de o ona can yoldaşı olur."},{"n":37,"t":"Bu şeytanlar onları yoldan saptırırlar. Onlarsa kendilerinin hâlâ hidayet üzere olduklarını sanırlar."},{"n":38,"t":"Sonunda bize geldiğinde, şeytan, yoldaşına şöyle der: \"Keşke aramızda iki doğu arası kadar uzaklık olsaydı. Ne kötü yoldaşmışsın sen!\""},{"n":39,"t":"Bugün hiçbir şey işinize yaramayacaktır. Çünkü zulme sapmışsınız. Azapta ortaklık kuracaksınız."},{"n":40,"t":"Sen şimdi sağırlara söz mü duyuracaksın; yoksa körlere, apaçık sapıklığa dalmışlara kılavuzluk mu edeceksin?!"},{"n":41,"t":"Ya biz, seni alıp götürdükten sonra onlardan öc alırız;"},{"n":42,"t":"Yahut da onlara yönelttiğimiz tehdidi sana gösteririz. Biz onlarla başa çıkacak güçteyiz."},{"n":43,"t":"Sen, sana vahyedilene sımsıkı sarıl! Hiç kuşkusuz, sen, dosdoğru bir yol üzerindesin."},{"n":44,"t":"Gerçek şu: Bu Kur'an sana ve toplumuna elbette ki bir hatırlatıcı/bir düşündürücü/bir şeref/bir öğüttür. Bundan sorumlu tutulacaksınız."},{"n":45,"t":"Senden önce gönderdiğimiz resullerimize sor: Rahman'dan başka ibadet edilecek tanrılar yapmış mıyız?"},{"n":46,"t":"Yemin olsun, Mûsa'yı ayetlerimizle Firavun'a ve onun üst düzey adamlarına gönderdik de onlara dedi ki: \"Ben âlemlerin Rabbi'nin resulüyüm.\""},{"n":47,"t":"Mûsa onlara ayetlerimizi getirdiğinde onlar bu ayetlere gülüyorlardı."},{"n":48,"t":"Onlara gösterdiğimiz her bir ayet, kardeşinden/öncekinden mutlaka daha büyüktü. Belki dönerler diye onları azapla yakaladık."},{"n":49,"t":"Dediler ki: \"Ey büyücü! Sana verdiği söz aşkına, Rabbine bizim için bir yakarıver; biz artık doğru yola gireceğiz.\""},{"n":50,"t":"Fakat kendilerinden azabı kaldırdığımızda hemen yan çizmeye başladılar."},{"n":51,"t":"Firavun, toplumu içinde haykırıp şöyle dedi: \"Ey toplumum! Mısır'ın mülk ve yönetimi benim değil mi? İşte şu nehirler benim altımdan akıyor. Görmüyor musunuz?\""},{"n":52,"t":"\"Yoksa ben şu zavallı, şu meramını anlatamayacak adamdan hayırlı değil miyim?\""},{"n":53,"t":"\"Ona altın bilezikler atılmalı, yanında-hizmetinde melekler bulunmalı değil miydi?\""},{"n":54,"t":"İşte toplumunu böyle küçümsedi, onlar da ona itaat ettiler. Çünkü onlar yoldan sapmış bir toplum idiler."},{"n":55,"t":"Onlar bizi bu şekilde öfkelendirince, biz de onlardan öc aldık; hepsini suya gömüverdik."},{"n":56,"t":"Onları, sonra gelecekler için eski bir örnek yaptık."},{"n":57,"t":"Meryem'in oğlu, bir örnek olarak ortaya konunca, senin toplumun buna karşı hemen bağırıp çağırmaya başladı."},{"n":58,"t":"Dediler ki: \"Bizim tanrılarımız mı hayırlı, o mu?\" Bunu sana sadece çekişme olsun diye örnek verdiler. Çekişmeyi seven bir toplumdur onlar."},{"n":59,"t":"Meryem'in oğlu, kendisine nimet verdiğimiz ve İsrailoğullarına örnek yaptığımız bir kuldu."},{"n":60,"t":"Eğer dileseydik, içinizden, yeryüzünde size halef olacak melekler vücuda getirirdik."},{"n":61,"t":"Hiç kuşkusuz o, kıyamet saati için bir bilgidir. O halde sakın o saat hakkında şüpheye düşmeyin; bana uyun. Dosdoğru yol budur."},{"n":62,"t":"Sakın şeytan sizi geri çevirmesin. O, sizin için açık bir düşmandır."},{"n":63,"t":"İsa, açık-seçik kanıtlarla geldiğinde şöyle demişti: \"Ben size hikmet getirdim ve tartışıp durduğunuz şeylerin bir kısmını size açıklayayım diye geldim. O halde, Allah'tan sakının ve bana itaat edin!\""},{"n":64,"t":"\"Kuşkusuz, Allah hem benim Rabbimdir hem sizin Rabbinizdir. O halde O'na ibadet edin! İşte bu, dosdoğru bir yoldur.\""},{"n":65,"t":"Böyle iken, aralarından çıkan hizipler ihtilafa düştüler. Korkunç bir günün azabından vay haline o zulmedenlerin!"},{"n":66,"t":"Hiç farkında olmadıkları bir sırada o saatin birdenbire kendilerine gelmesinden başka neyi bekliyorlar?"},{"n":67,"t":"Dostlar o gün birbirine düşman kesilirler. Ancak takvaya sarılanlar böyle değildir."},{"n":68,"t":"Ey kullarım! Bugün size korku yok; sizler tasalanmayacaksınız da!"},{"n":69,"t":"Ayetlerimize inanan ve Müslüman/ teslim olan kimselerdir onlar!"},{"n":70,"t":"Cennete girin! Siz ve eşleriniz ikramlarla ağırlanacaksınız."},{"n":71,"t":"Çevrelerinde altın tepsiler, kadehler dolaştırılır. Orada, nefislerin arzu duyacağı, gözlerin zevkleneceği her şey vardır. Ve siz orada sürekli kalacaksınız."},{"n":72,"t":"İşte size, yapıp ettiklerinize karşılık mirasçı kılındığınız cennet!"},{"n":73,"t":"Orada sizin için pek çok meyve var. Onlardan yiyeceksiniz."},{"n":74,"t":"Suçlular ise cehennem azabının içinde uzun süre sürekli kalacaklardır."},{"n":75,"t":"Azapları hafifletilmeyecektir; onun içinde ümitsiz kalacaklardır."},{"n":76,"t":"Biz onlara zulmetmedik; onlar zalimlerin ta kendileriydi."},{"n":77,"t":"Şöyle seslenecekler: \"Ey Mâlik! Rabbin işimizi bitirversin.\" O şöyle diyecek: \"Bekleyeceksiniz!\""},{"n":78,"t":"Yemin olsun, size hakkı getirdik ama çoğunuz haktan tiksiniyorsunuz."},{"n":79,"t":"Yoksa bir iş ve oluşta kesin karara mı vardılar? Kuşkusuz, biz de kesin kararlıyız."},{"n":80,"t":"Yoksa onların sırlarını, fısıltılarını duymadığımızı mı sanıyorlar? Hayır, öyle değil; elçilerimiz yanlarında yazıp duruyorlar."},{"n":81,"t":"De ki: \"Eğer Rahman'ın bir çocuğu olsaydı, ona kulluk edenlerin ilki ben olurdum.\""},{"n":82,"t":"Göklerin ve yerin Rabbi, arşın Rabbi onların nitelendirmelerinden arınmıştır, yücedir."},{"n":83,"t":"Bırak onları, kendilerine vaat edilen günlerine kavuşuncaya değin dalıp gitsinler; oynayıp oyalansınlar!"},{"n":84,"t":"Göklerde ilah olan da O, yerde ilah olan da O. O'dur Hakîm, O'dur Alîm."},{"n":85,"t":"Göklerin, yerin ve bunlar arasındakilerin mülkü/yönetimi kendine ait olan o Allah'ın şanı yücedir. Kıyamet saatine ilişkin bilgi O'nun katındadır. Siz de O'na döndürüleceksiniz."},{"n":86,"t":"O'nun berisinden yakardıkları, şefaate sahip olamaz! Hakka tanık olanlar müstesna. Onlar, ilimden nasiplenmekteler."},{"n":87,"t":"Kendilerini kim yarattı diye onlara sorsan, yemin olsun, \"Allah!\" diyeceklerdir. Peki, nasıl döndürülüyorlar!\""},{"n":88,"t":"Onun \"Ey Rabbim\" deyişine yemin olsun ki, bunlar iman etmez bir topluluktur."},{"n":89,"t":"Artık sen onlara aldırma, \"Selam!\" deyiver. Yakında bilecekler."}],[{"n":1,"t":"Hâ, Mîm."},{"n":2,"t":"O ayan-beyan gösteren Kitap'a yemin olsun ki,"},{"n":3,"t":"Biz onu kutlu/bereketli bir gecede indirdik. Hiç kuşkusuz, biz uyarıcılarız."},{"n":4,"t":"Hikmetlerle dolu her iş ve oluş o gecede ayırt edilir,"},{"n":5,"t":"Katımızdan bir emir olarak. Hiç kuşkusuz biz, resuller göndeririz,"},{"n":6,"t":"Senin Rabbinden bir rahmet olarak. Hiç kuşkusuz O, gereğince duyan, gereğince bilendir."},{"n":7,"t":"Göklerin, yerin ve bunlar arasındakilerin Rabbidir O, eğer görürcesine biliyor iseniz."},{"n":8,"t":"Tanrı yoktur O'ndan başka! Diriltir ve öldürür. Sizin de Rabbinizdir O, önceki atalarınızın da Rabbidir,"},{"n":9,"t":"İş, onların sandığı gibi değil! Bir kuşku içinde oynayıp oyalanmaktadırlar."},{"n":10,"t":"Artık sen göğün açıkça izlenen bir duman getireceği günü gözle."},{"n":11,"t":"İnsanları kuşatıp sarar. İnletici bir azaptır bu."},{"n":12,"t":"\"Ey Rabbimiz, kaldır bizden bu azabı. Biz gerçekten müminleriz.\""},{"n":13,"t":"Nerede onlarda öğüt almak? Yemin olsun, delillerle açıklayan bir resul gelmişti onlara."},{"n":14,"t":"Ama ondan yüz çevirdiler ve şöyle dediler: \"Eğitilmiş bir mecnun!\""},{"n":15,"t":"Biz azabı biraz kaldırırız; siz eski halinize tekrar dönersiniz."},{"n":16,"t":"Gün gelir, en büyük vuruşla vururuz biz. Şu bir gerçek ki, intikam da alırız biz!"},{"n":17,"t":"Kudretimize yemin olsun ki, onlardan önce Firavun'un kavmini de ince bir imtihana çektik de, asil ve onurlu bir resul geldi onlara."},{"n":18,"t":"Şöyle sesleniyordu: \"Ey Allah'ın kulları, bana gelin! Çünkü ben sizin için güvenilir bir resulüm.\""},{"n":19,"t":"\"Allah'a karşı ululuk taslamayın! Ben size apaçık bir kanıt getirmekteyim.\""},{"n":20,"t":"Ben, beni taşlamanızdan/ kovmanızdan, benim de Rabbim sizin de Rabbiniz olana sığındım."},{"n":21,"t":"\"Bana inanmadınızsa bari benden uzak durun!\""},{"n":22,"t":"Sonra Rabbine, \"Bunlar suç işleyen bir topluluktur.\" diye yakardı."},{"n":23,"t":"Bunun üzerine, Allah buyurdu: \"O halde kullarımı geceleyin yola çıkar, çünkü takip edileceksiniz.\""},{"n":24,"t":"\"Denizi açık bırak, çünkü onlar, boğulmaya mahkûm edilmiş bir ordudur.\""},{"n":25,"t":"Geriye nice bahçeler, nice pınarlar bıraktılar."},{"n":26,"t":"Nice ekinler, nice seçkin makamlar."},{"n":27,"t":"İçinde zevk sürdükleri nice nimetler."},{"n":28,"t":"İşte böyle! Onlara başka bir toplumu mirasçı kıldık."},{"n":29,"t":"Gök de ağlamadı onlar için yer de. Yüzlerine bakılmadı bile!"},{"n":30,"t":"Yemin olsun, İsrailoğullarını, rezil edici bir azaptan kurtardık."},{"n":31,"t":"Firavun'dan kurtardık. Firavun, haddi aşanların büyüklük taslayanlarından biriydi."},{"n":32,"t":"Yemin olsun, biz onları bir ilim sayesinde âlemlere üstün kılmıştık."},{"n":33,"t":"Onlara, içinde açık bir imtihan bulunan ayetler vermiştik."},{"n":34,"t":"Şimdi, şunlar tutmuş diyorlar ki:"},{"n":35,"t":"\"İlk ölümümüzden başkası yok! Biz diriltilecek filan değiliz!\""},{"n":36,"t":"\"Eğer doğru sözlülerseniz, atalarımızı geri getirin!\""},{"n":37,"t":"Onlar mı hayırlı yoksa Tübba' halkıyla onlardan önce gelenler mi? Onları helâk ettik; çünkü onlar, suç işlemiş insanlardı."},{"n":38,"t":"Biz gökleri, yeri ve bunlar arasındakileri eğlenmek için yaratmadık."},{"n":39,"t":"İkisini de, sadece gerçeği göstermek üzere yarattık. Ama onların çokları bilmiyorlar."},{"n":40,"t":"Hiç kuşkusuz, ayrım günü, hepsinin buluşma zamanıdır/buluşma yeridir."},{"n":41,"t":"Bir gündür ki o, dostun dosta yararı olmaz. Onlara yardım da edilmez."},{"n":42,"t":"Allah'ın rahmet ettiği kimse müstesna. Allah Azîz'dir, Rahîm'dir."},{"n":43,"t":"Şu bir gerçek ki zakkum ağacı,"},{"n":44,"t":"Suçluların yemeğidir."},{"n":45,"t":"Erimiş maden misali, karınlarda kaynar."},{"n":46,"t":"Sıcak suyun kaynaması gibi..."},{"n":47,"t":"\"Tutun onu, cehennemin tam ortasına götürün!\""},{"n":48,"t":"\"Sonra başının üstüne, kaynar su azabından dökün!\""},{"n":49,"t":"\"Tat bakalım! Hani sen onurluydun, seçkindin.\""},{"n":50,"t":"\"İşte budur o kuşkulanıp durduğunuz şey.\""},{"n":51,"t":"Korunup sakınanlar, güvenli bir makamdadır;"},{"n":52,"t":"Bahçelerde, pınar başlarında."},{"n":53,"t":"İnce ipekten, parlak atlastan giymiş olarak, karşılıklı oturmaktadırlar."},{"n":54,"t":"İşte böyle! Onları iri gözlü hurilerle de eşleştirmişizdir."},{"n":55,"t":"Orada, güvenli bir biçimde her türlü meyveyi isterler."},{"n":56,"t":"Orada, ilk ölüm dışında ölüm tatmazlar. Allah onları cehennem azabından korumuştur."},{"n":57,"t":"Rabbinden bir lütuf olarak böyledir. İşte budur o büyük başarı."},{"n":58,"t":"Biz o Kur'an'ı senin dilinle/senin diline kolaylaştırdık ki, düşünüp öğüt alabilsinler."},{"n":59,"t":"Artık, beklemeye geç! Çünkü onlar da beklemekteler."}],[{"n":1,"t":"Hâ, Mîm."},{"n":2,"t":"Azîz ve Hakîm olan Allah'tan Kitap'ın indirilişidir bu..."},{"n":3,"t":"Kuşkusuz, göklerde ve yerde, iman sahipleri için sayısız ayetler vardır."},{"n":4,"t":"Sizin yaratılışınızda ve türetip yaydığı canlılarda, iyice ve kesinlikle inanan bir topluluk için ayetler/ kanıtlar vardır."},{"n":5,"t":"Geceyle gündüzün birbiri ardınca gelişinde, Allah'ın gökten bir rızık indirip de onunla yerküreyi ölümünden sonra hayata kavuşturmasında, rüzgârların herbir yana sevkedilişinde de aklını çalıştıran bir topluluk için izler, işaretler vardır."},{"n":6,"t":"İşte bunlar, Allah'ın ayetleridir ki, onları sana hak olarak okuyoruz. Hal böyle iken Allah'tan ve onun ayetlerinden sonra hangi hadise/söze inanıyorlar?!"},{"n":7,"t":"Yazıklar ve azaplar olsun günaha batmış her yalancı iftiracıya,"},{"n":8,"t":"Ki Allah'ın ayetlerinin kendisine okunuşunu dinler, sonra böbürlenmiş olarak inadında devam eder. Sanki hiç duymamıştır onları. Artık acıklı bir azapla muştula böylesini."},{"n":9,"t":"Ayetlerimizden bir şeyin bilgisine ulaşınca, alaya aldı onu. İşte onlar içindir horlayıp yere batıran bir azap."},{"n":10,"t":"Arkalarından cehennem! Kazanmış oldukları da Allah dışında edindikleri veliler de onlara hiçbir yarar sağlamayacaktır. Çok büyük bir azap vardır onlar için."},{"n":11,"t":"İyiye ve güzele bir kılavuzdur bu! Rablerinin ayetlerini inkâr edenler için, korkunç bir pislik azabı öngörülmüştür."},{"n":12,"t":"Allah size denizi boyun eğdirdi ki, içinde gemiler O'nun emriyle akıp gitsin, lütfundan istekte bulunasınız ve şükredebilesiniz."},{"n":13,"t":"Göklerde ne var, yerde ne varsa tümünü, O'ndan bir lütuf olarak size boyun eğdirmiştir. Bunda, derin derin düşünen bir topluluk için elbette ibretler vardır."},{"n":14,"t":"İman edenlere söyle: Allah'ın günlerinin geleceğini ummayanları bağışlasınlar/hoşgörsünler ki O, bir toplumun kendi elleriyle kazandıklarının karşılığını versin."},{"n":15,"t":"Kim hayra ve barışa yönelik bir iş yaparsa kendi lehinedir. Kötülük yapan da kendi aleyhine yapmış olur. Sonunda Rabbinize döndürülürsünüz."},{"n":16,"t":"Yemin olsun, biz, İsrailoğullarına Kitap'ı, hükmetme gücünü, peygamberliği verdik, onları temiz yiyeceklerden rızıklandırdık ve kendilerini âlemler üzerine imtiyazlı kıldık."},{"n":17,"t":"Onlara, iş ve yönetime ilişkin açık-seçik belgeler verdik. Onlar, kendilerine ilim geldikten sonra, aralarındaki azgınlık ve kıskançlık yüzünden ihtilafa düştüler. Hiç kuşkusuz, Rabbin, onlar arasında, tartışıp durdukları şeyle ilgili olarak kıyamet günü hüküm verecektir."},{"n":18,"t":"Daha sonra seni, iş ve yönetimde bir şerîat/bir yol-yöntem üzerine koyduk. Artık ona uy! Bilmeyenlerin keyifleri ardınca gitme!"},{"n":19,"t":"Kuşkun olmasın ki onlar, Allah karşısında sana hiçbir yarar sağlayamazlar/Allah'tan gelecek hiçbir şeyi senden uzaklaştıramazlar. Zalimler birbirlerinin dostlarıdır; Allah ise takvaya sarılanların Velî'sidir."},{"n":20,"t":"Bu Kur'an, insanların kalp gözlerini açacak ışıklardan oluşur. Gereğince inanan bir toplum için de bir kılavuz ve bir rahmettir o."},{"n":21,"t":"Yoksa o kötülükleri işleyenler; kendilerini, iman edip hayra ve barışa yönelik işler yapanlarla bir tutacağımızı, hayatları ve ölümleri eşit olacak mı sandılar? Ne kötü hüküm veriyorlar!"},{"n":22,"t":"Ve Allah, gökleri ve yeri hak olarak yarattı. Ta ki her benlik, kazancının karşılığıyla, hiç kimse zulme uğratılmaksızın, yüz yüze getirilsin."},{"n":23,"t":"Kendisinin ilahı olarak kendi duygu ve arzusunu almış kişiyi gördün mü? Allah onu bir ilim üzerine saptırmış, kulağı ve kalbi üzerine mühür basmış, gözünün üstüne de bir perde çekmiştir. Allah'tan sonra ona kim kılavuzluk edecektir. Hâlâ düşünüp ibret almıyor musunuz?"},{"n":24,"t":"Dediler ki: \"Şu dünya hayatımızdan başkası yok. Ölüyoruz, diriliyoruz. Bizi zamandan başkası helâk etmiyor.\" Onların bu konuda hiçbir bilgisi yoktur. Sadece sanıda bulunuyorlar."},{"n":25,"t":"Ayetlerimiz, karşılarında açık-seçik mesajlar halinde okunduğunda, delilleri sadece şöyle demek olmuştur: \"Doğru sözlüler iseniz atalarımızı getirin.\""},{"n":26,"t":"De ki: \"Sizi Allah yaşatıyor; sonra sizi öldürecek, sonra da o hakkında hiç kuşku bulunmayan kıyamet gününde biraraya getirecek. Ama insanların çokları bilmiyorlar.\""},{"n":27,"t":"Göklerin ve yerin mülkü/saltanatı Allah'ındır. Kıyamet kopunca, işte o gün, gerçekleri hükümsüz kılanlar hüsrana uğrayacaklardır."},{"n":28,"t":"O gün tüm ümmetleri, toplanıp diz çökmüş görürsün. Her ümmet kendi kitabına davet edilir. Bugün, yapıp-ettiklerinizin karşılığıyla yüzyüze getireleceksiniz."},{"n":29,"t":"Bu bizim kitabımız, karşınızda gerçeği söylüyor. Çünkü biz, yapıp-ettiklerinizin kopyasını çıkarıyorduk/yaptıklarınızı kaydediyorduk."},{"n":30,"t":"İman edip hayra ve barışa yönelik işler yapanların durumu şu: Rableri onları rahmetine sokacaktır. İşte açık zafer budur."},{"n":31,"t":"İnkâr ve nankörlüğe sapmış olanlara gelince, onlara şöyle denecek: \"Ayetlerimiz karşınızda okunurdu ama siz büyüklük taslardınız, suç işleyen bir toplum oldunuz, öyle değil mi?\""},{"n":32,"t":"Hani, size, \"Hiç kuşkusuz, Allah'ın vaadi haktır, kıyamet saatinde de şüphe yoktur\" dendiğinde, siz şöyle demiştiniz: \"Saat nedir, bilmiyoruz. Sadece bir şeyler var sanıyoruz; kesin bir bilgimiz olmadığı için inanmıyoruz.\""},{"n":33,"t":"Yaptıklarının kötülükleri karşılarına dikilmiş, alay edip durdukları şey kendilerini kuşatıvermiştir."},{"n":34,"t":"Şöyle denilir: \"Unutuyoruz sizi bugün! Tıpkı sizin, bugününüze kavuşmayı unuttuğunuz gibi. İşte böyle! Sığınağınız ateştir; hiçbir yardımcınız da olmayacaktır.\""},{"n":35,"t":"Bunun sebebi şudur: \"Siz, Allah'ın ayetlerini eğlence aracı yaptınız, dünya hayatı sizi aldattı/gurura itti. Bugün ateşten çıkarılmayacaklar, özür dilemeleri de kabul edilmeyecek.\""},{"n":36,"t":"Hamt; göklerin Rabbi, yerin Rabbi, âlemlerin Rabbi olan Allah'adır!"},{"n":37,"t":"Göklerde ve yerde ululuk/büyüklük O'nundur! Azîz'dir O, Hakîm'dir."}],[{"n":1,"t":"Hâ, Mîm."},{"n":2,"t":"Hikmeti sınırsız, kudreti sonsuz Allah'tan, Kitap'ın indirilişidir bu..."},{"n":3,"t":"Gökleri ve yeri ve ikisi arasındakileri hak olarak ve belirlenmiş bir süre için yarattık biz. Küfre batanlarsa uyarılmış oldukları şeyden yüz çevirmektedirler."},{"n":4,"t":"De ki: \"Allah dışında yakarmakta olduklarınızı gördünüz mü? Gösterin bana, yerden neyi yarattılar onlar? Yoksa göklerde bir ortaklıkları mı var? Eğer doğru sözlü kişiler iseniz bundan önceki bir kitap, yahut bir bilgi kalıntısı getirin bana!\""},{"n":5,"t":"Kıyamet gününe kadar kendisine cevap vermeyecek birilerine, Allah'ın berisinden yalvarıp durandan daha sapık kim vardır? Ve o yalvardıkları, onların yakarışından habersizdirler."},{"n":6,"t":"İnsanlar haşredilmek üzere toplandıklarında, o taptıkları onlara düşman olurlar; onların ibadetlerini de inkâr ederler."},{"n":7,"t":"Herşeyi ayan-beyan gösteren ayetlerimiz onlara okunduğunda, kendilerine gelmiş olan hakkı inkâr edenler şöyle derler: \"Açık bir büyüdür bu!\""},{"n":8,"t":"Yahut da şöyle diyorlar: \"Uyduruyor onu!\" De ki: \"Eğer uydursaydım onu, hiçbir şeye sahip olamazdınız Allah'tan kurtarmak için beni. İçine gömüldüğünüz yaygarayı en iyi bilen O'dur. Benimle sizin aranızda tanık olarak O yeter. Çok affedici, çok merhametlidir O.\""},{"n":9,"t":"De ki: \"Ben, resuller içinden bir türedi değilim! Bana ve size ne yapılacağını da bilmiyorum. Bana vahyedilenden başkasına da uymam! Ve ben, açıkça uyaran bir elçiden başkası da değilim.\""},{"n":10,"t":"De ki: \"Hiç düşündünüz mü? Eğer bu, Allah katından ise ve siz onu tanımamışsanız, İsrailoğullarından bir tanık da onun benzerine tanıklık edip inandığı halde, siz böbürlenmişseniz haliniz nice olur! Allah, zalimler topluluğuna kılavuzluk etmez.\""},{"n":11,"t":"İnkâr edenler, inananlara şöyle derler: \"Eğer bu, hayırlı bir şey olsaydı, bunlar ona inanmakta bizi geçemezlerdi.\" Bununla umduklarını bulamayınca şöyle diyecekler: \"Bu, eski bir uydurmadır.\""},{"n":12,"t":"Halbuki ondan önce, bir önder ve bir rahmet olarak Mûsa'nın kitabı var! Bu Kur'an da öncekileri tasdikleyen bir kitaptır. Zulmedenleri uyarsın, güzel davrananlara müjde olsun diye Arap dilindedir."},{"n":13,"t":"\"Rabbimiz Allah'tır\" deyip, sonra da dosdoğru yol alanlar var ya, onlar için hiçbir korku yoktur; onlar tasalanmayacaklardır da..."},{"n":14,"t":"Cennet halkıdır onlar. Yapıp ettiklerine karşılık olarak sürekli kalacaklardır orada."},{"n":15,"t":"Biz insana, anne-babasına çok iyi davranmasını önerdik. Annesi onu zahmetle taşıdı, zahmetle doğurdu. Taşınması ve sütten kesilmesi otuz aydır. Nihayet, yiğitlik çağına gelip kırk yıla erdiğinde şöyle der: \"Rabbim; beni, bana ve ebeveynime verdiğin nimete şükretmeye, hoşnut olacağın iyi bir iş yapmaya yönelt! Soyum içinde, benim için barışı gerçekleştir. Sana yöneldim ben, sana teslim olanlardanım ben!\""},{"n":16,"t":"Bunlar, cennet halkı arasında o kimselerdir ki, yaptıklarının en güzelini kabul ederiz, çirkinliklerini görmezlikten geliriz. Bu onlara verilmiş olan şaşmaz vaattir."},{"n":17,"t":"Birisi de ana-babasına: \"Yazık size, benden önce bir yığın nesil gelip geçtiği halde, siz bana, benim diriltileceğimi mi söylüyorsunuz?\" dedi. Onlarsa Allah'a sığınarak, \"Yazıklar olsun; inansana, Allah'ın vaadi haktır\" diye vahlanınca o şöyle dedi: \"Bu, öncekilerin masallarından başkası değil!\""},{"n":18,"t":"İşte bunlar, kendilerinden önce gelip geçmiş cin ve insan ümmetleri içinde, üzerlerine azap hak olanlardır. Hiç kuşkusuz, onlar, hüsrana uğrayanlardır."},{"n":19,"t":"Her birinin, yapıp ettiklerinden dereceleri vardır. Amellerinin karşılığı eksiksiz verilecektir, hiçbir haksızlığa uğratılmayacaklardır."},{"n":20,"t":"Gün olur, inkâr edenler ateşe arz edilirler. Onlara denir ki: \"İyiliklerinizi/nimetlerinizi, o iğreti dünya hayatınızda silip süpürdünüz, onlarla zevklenip eğlendiniz. Bugünse alçaltıcı azapla cezalandırılacaksınız. Çünkü siz, yeryüzünde haksız yere büyüklük tasladınız ve gerçeğe ters düştünüz.\""},{"n":21,"t":"Âd kavminin kardeşini de an! O, kendinden önce ve sonra uyarıcıların gelip geçtiği Ahkaf'ta, toplumunu şöyle uyarmıştı: \"Allah'tan başkasına kulluk/ibadet etmeyin! Gerçek şu ki, ben sizin büyük bir günün azabına uğramanızdan korkuyorum.\""},{"n":22,"t":"Dediler: \"Sen bizi, tanrılarımızdan yüz geri etmek için mi geldin? Eğer doğru sözlülerden isen, bizi tehdit ettiğin şeyi ortaya getir.\""},{"n":23,"t":"Dedi: \"İlim, ancak Allah katındadır. Ben size, bana vahyedileni tebliğ ediyorum. Fakat sizin, cahillik edip duran bir toplum olduğunuzu görüyorum.\""},{"n":24,"t":"Nihayet onu, vadilerine doğru gelen geniş bir bulut halinde görünce: \"Ha, dediler, bu bize yağmur getirecek bir bulut!\" Hayır, o, aceleden istediğiniz şeyin ta kendisi. Bir rüzgâr ki, içinde acıklı bir azap var."},{"n":25,"t":"Rabbinin emriyle her şeyi yerle bir edecek. Sonunda o hale geldiler ki, konutlarından başka hiçbir şey görünmüyordu. Suçlular topluluğunu işte böyle cezalandırırız biz."},{"n":26,"t":"Yemin olsun, onlara, size vermediğimiz imkân ve kudreti vermiştik. Onlar için işitme gücü, gözler ve gönüller oluşturmuştuk. Fakat, işitme güçleri de gözleri de gönülleri de kendilerine hiçbir yarar sağlamadı/kendilerinden hiçbir şeyi uzaklaştıramadı; çünkü ayetlerimize karşı direniyorlardı. Ve alaya aldıkları şey, onları kuşatıp sardı."},{"n":27,"t":"Yemin olsun, sizi çevreleyen kentleri/medeniyetleri de helâk ettik. Belki dönerler diye ayetleri değişik biçimlerde sıralayıp durmuştuk."},{"n":28,"t":"Allah'ın yanında yakınlık sağlamak için edindikleri ilahlar, onlara yardım etseydi ya! Tam aksine, onlardan uzaklaşıp kayboldular. Bu, onların yalanları, uydurup durduklarıydı."},{"n":29,"t":"Bir zaman, cinlerden bir topluluğu, Kur'an'ı dinlemeleri için sana yöneltmiştik. Onu dinlemeye hazır hale geldiklerinde: \"Susup dinleyin!\" dediler. Dinleme bitirilince de uyarıcılar olarak kendi toplumlarına döndüler."},{"n":30,"t":"Dediler ki: \"Ey toplumumuz! Biz; Mûsa'dan sonra indirilen, kendinden öncekini doğrulayan, hakka ve dosdoğru yola ileten bir Kitap dinledik.\""},{"n":31,"t":"\"Ey toplumumuz! Allah'ın davetçisine uyun, ona iman edin ki Allah, günahlarınızdan bir kısmını bağışlasın ve sizi acıklı bir azaptan korusun!\""},{"n":32,"t":"Allah'ın davetçisine uymayan, yeryüzünde hiç kimseyle yarışamaz/hiç kimseyi âciz bırakamaz. Böylesinin, Allah dışında/Allah'ın davetçisi dışında evliyası da olmaz. Böyleleri apaçık bir sapıklık içindedir."},{"n":33,"t":"Görmediler mi ki; gökleri ve yeri yaratan, bunları yaratmakla yorgunluğa düşmeyen Allah, ölüleri diriltmeye de kadirdir. Evet, O her şeye kadirdir."},{"n":34,"t":"Gün gelir, o inkâr edenler, ateşe arz edilir. \"Bu gerçek değil miymiş?\" diye sorulur. \"Elbette! Rabbimize yemin ederiz, gerçekmiş!\" derler. Allah buyurur: \"O halde, inkâr ettiğinizden ötürü tadın azabı!\""},{"n":35,"t":"Artık, resullerin azim sahibi olanlarının sabrettiği gibi sabret! O inkârcılar için acele etme! Tehdit edildikleri azabı gördükleri gün, gündüzün sadece bir saati kadar yaşamış gibi olurlar. Bir duyurudur bu. Sapmışlar topluluğundan başka kim helâk edilir!"}],[{"n":1,"t":"Küfre saplanıp Allah'ın yolundan alıkoyanların yapıp ettiklerini O, boşa çıkarmıştır."},{"n":2,"t":"İman edip barışa/hayra yönelik işler yapanlar ve Muhammed'e indirilene -ki o onların Rablerinden bir haktır- inanmış olanlara gelince, Allah onların çirkin davranışlarını örtmüş ve gönüllerini barışa yöneltmiştir."},{"n":3,"t":"Bu böyledir; çünkü küfre batanlar boş ve tutarsıza uymuşlardır. İman edenler ise Rablerinden gelen hakka uymuşlardır. İşte Allah, insanlara kendi durumlarını bu şekilde örnekleyerek anlatır."},{"n":4,"t":"Küfre batmışlarla burun buruna geldiğinizde, boyunlar vurulur. Nihayet onları bastırıp sindirdiğinizde, antlaşma bağını sıkı bağlayın. Artık bundan sonrası ya bir bağışlama ya bir fidyedir. Nihayet, harp, ağırlıklarını yere bırakır. İşte böyle! Eğer Allah dileseydi, onlardan öc alırdı. Ama kiminizi kiminizle denemek için böyledir. Allah yolunda öldürülenlerin amelleri asla göz ardı edilmeyecektir."},{"n":5,"t":"Onları doğruya/iyiye/güzele kılavuzlayacak ve kalpleri ıslah edecektir/ barışa yöneltecektir."},{"n":6,"t":"Ve onları, kendilerine tanımlamış olduğu o cennete koyacaktır."},{"n":7,"t":"Ey iman sahipleri! Eğer siz Allah'a yardım ederseniz, Allah da size yardım eder ve ayaklarınızı sağlam bastırır."},{"n":8,"t":"Küfre sapanlara gelince, kayıp ve yıkım onlara! Yapıp ettiklerini boşa çıkardı onların."},{"n":9,"t":"Bu böyledir; çünkü onlar Allah'ın indirdiğini tiksindirici bulmuşlardır, Allah da onların tüm amellerini boşa çıkarmıştır."},{"n":10,"t":"Onlar yeryüzünde dolaşıp da kendilerinden öncekilerin sonlarının nasıl olduğuna bir bakmıyorlar mı? Allah onları yerle bir etmiştir. Şu inkâr edenlere de onlara yapılanın aynısı yapılacaktır."},{"n":11,"t":"Bu böyledir; çünkü Allah, iman edenlerin Mevlâ'sıdır. Küfre sapanların ise Mevlâ'sı yoktur."},{"n":12,"t":"Şu bir gerçek ki, Allah, iman edip barışa/hayra yönelik işler yapanları, altlarından ırmaklar akan cennetlere koyacaktır. Küfre sapanlarsa zevk edip eğlenmeye bakarlar; davarların yediği gibi yer-içerler. Varacakları yer ateştir onların."},{"n":13,"t":"Seni yerinden çıkaran o kentinden çok daha kuvvetlice nice kentler vardı ki, biz hepsini helâk ettik; hiçbir yardımcıları olmadı."},{"n":14,"t":"Rabbinden açık bir kanıt üzere olan, amelinin çirkinliği kendisine süslü gösterilip de boş arzularına uyanlara benzer mi?"},{"n":15,"t":"Sakınanlara vaat olunan cennetin durumu şöyledir: Orada, bozulmayan sudan ırmaklar; tadı bozulmayan sütten nehirler, içenlere lezzet sunan bir şaraptan nehirler, süzme bir baldan oluşan nehirler var. Ve orada kendileri için her türlü meyvenin yanında, Rablerinden bir de bağışlanma var. Bu nimetler içindekiyle, uzun süre ateşte kalıp da içirildiği sıcak su tarafından bağırsakları parçalanan kimse aynı olur mu?"},{"n":16,"t":"İçlerinden bir kısmı seni dinler, sonra senin yanından çıktıklarında, kendilerine ilim verilmiş olanlara şöyle sorarlar: \"Az önce ne söyledi?\" İşte bunlar, Allah'ın, kalplerine mühür bastığı kimselerdir, boş arzularının ardına düşmüşlerdir."},{"n":17,"t":"Kılavuzlarını bulmuş olanlara gelince, Allah onların hidayetini artırmış ve korunma imkânlarını kendilerine vermiştir."},{"n":18,"t":"Kıyametin ansızın tepelerine inmesinden başka neyi bekliyorlar? Onun belirtileri zaten gelmiştir. O onlara gelip çatınca, ibret almaları neye yarar?!"},{"n":19,"t":"Allah'tan başka tanrı olmadığını kuşkusuzca bil! Hem kendi günahın için hem de mümin erkeklerle mümin kadınlar için af dile. Allah sizin, dönüp dolaşacağınız yeri de varıp ulaşacağınız yeri de bilir."},{"n":20,"t":"İman edenler derler ki: \"Bir sure indirilseydi olmaz mıydı?\" Fakat hükmü kesinleşmiş bir sure indirilip de içinde savaş da anılınca, kalplerinde maraz olanların, ölüm baygınlığına tutulmuş bir bakışla sana baktıklarını görürsün. Onlara uygun olan da odur."},{"n":21,"t":"İtaat ve güzel bir söz! İş budur. İş ciddileşince, Allah'a verdikleri söze sadık olsalardı kendileri için daha iyi olurdu."},{"n":22,"t":"Demek iş başına gelecek olsanız/savaştan geri kalacak olsanız, ülkede fesat çıkarıp rahimleri parçalayacaksınız."},{"n":23,"t":"İşte bunlardır, Allah'ın kendilerine lanet edip kulaklarını sağır, gözlerini de kör ettiği kimseler..."},{"n":24,"t":"Peki bunlar, Kur'an'ın anlamını inceden inceye düşünmüyorlar mı? Yoksa kalpler üzerinde o kalplerin kilitleri mi var?"},{"n":25,"t":"Hidayet kendilerine açıkça belli olduktan sonra arkalarına dönenlere şeytan fit vermiş, sonu gelmez arzuların/ümitlerin ardına takmıştır onları."},{"n":26,"t":"Bu şundandır: Bunlar, Allah'ın indirdiğinden tiksinenlere, \"Bazı işlerde size itaat edeceğiz.\" demişlerdi. Fakat Allah onların gizlediklerini biliyor."},{"n":27,"t":"Melekler onların yüzlerine ve sırtlarına vurarak canlarını alacakları zaman, bakalım nasıl olacak?!"},{"n":28,"t":"Olacak olan budur! Çünkü onlar, Allah'ı öfkelendiren şeylerin peşine düştüler, O'nun hoşnutluğundan tiksindiler; sonunda Allah bütün amellerini boşa çıkardı."},{"n":29,"t":"Yoksa o kalplerinde maraz olanlar, Allah kendilerinin şiddetli kinlerini hiçbir zaman ortaya çıkarmayacak mı sandılar?"},{"n":30,"t":"Dileseydik onları sana mutlaka gösterirdik de sen onları yüzlerinden kesinlikle tanırdın. Zaten sen onları, sözlerinin tarzından da tanırsın. Allah tüm yaptıklarınızı biliyor."},{"n":31,"t":"Yemin olsun, içinizden gayret gösterip didinenlerle sabredenleri bilinceye kadar, sizi belalarla imtihan edeceğiz. Haberlerinizi de eleyip tarayacağız."},{"n":32,"t":"Nankörlüğe sapıp Allah yolundan alıkoyanlar ve hidayet kendilerine tam bir şekilde belli olduktan sonra resule kafa tutanlar, Allah'a hiçbir şekilde zarar veremezler. O, onların amellerini işe yaramaz hale getirecektir."},{"n":33,"t":"Ey iman edenler! Allah'a itaat edin; resule de itaat edin! Amellerinizi işe yaramaz hale getirmeyin."},{"n":34,"t":"İnkâr edip Allah yolundan döndüren, sonra da küfre saplanmış olarak ölenler yok mu, Allah onları asla affetmeyecektir."},{"n":35,"t":"Gevşemeyin, üstün durumda olduğunuz halde antlaşmaya davet etmeyin! Allah sizinledir; amellerinizi asla yitirmeyecektir."},{"n":36,"t":"Şu iğreti dünya hayatı, sadece bir oyun ve eğlencedir. Eğer iman eder korunursanız, Allah, ödüllerinizi verecek ve sizden mallarınızı istemeyecektir."},{"n":37,"t":"Eğer onları isteyip bunun için sizi zorlasaydı, cimrilik ederdiniz, böylece Allah şiddetli kinlerinizi ortaya çıkarırdı."},{"n":38,"t":"İşte sizler, Allah yolunda harcamaya çağırılan insanlarsınız. Ama bir kısmınız cimrilik ediyor. Oysaki, cimrilik eden kendi aleyhine cimrileşmiş olur. Allah Ganî'dir; yoksul olan sizlersiniz. Eğer yüz çevirirseniz, Allah yerinize başka bir toplum getirir. Ve onlar, sizin benzerleriniz olmazlar."}],[{"n":1,"t":"Şu bir gerçek ki, biz sana apaçık bir fetih nasip ettik."},{"n":2,"t":"Ki Allah senin günahından geçmiş olanı da gelecek olanı da bağışlasın, nimetini senin üzerinde tamamlasın ve seni dosdoğru bir yola kılavuzlasın."},{"n":3,"t":"Ve Allah sana onur ve kudret dolu bir yardımla destek verecektir."},{"n":4,"t":"O odur ki, müminlerin gönüllerine, imanları beraberinde iman geliştirsinler diye, mutluluk ve huzur indirdi. Yalnız Allah'ındır göklerin ve yerin orduları. Alîm'dir Allah, Hakîm'dir."},{"n":5,"t":"İnanmış erkekleri ve inanmış kadınları, altlarından ırmaklar akan cennetlere sokması içindir bu. Sürekli kalıcıdırlar orada. Ve onların çirkin davranışlarını örtüp gizlemesi içindir. İşte bu, Allah katında çok büyük bir kurtuluş ve eriştir."},{"n":6,"t":"Ve Allah hakkında kötü sanılar besleyen erkek münafıklarla kadın münafıklara ve erkek putperestlerle kadın putperestlere, o kötülük girdabı başlarına dönesilere azap etsin diyedir bu. Allah onlara öfkelenmiş, onları lanetlemiş ve kendilerine cehennem hazırlamıştır. Kötü bir varış yeridir o."},{"n":7,"t":"Yalnız Allah'ındır göklerin ve yerin orduları. Azîz'dir Allah, Hakîm'dir."},{"n":8,"t":"Şu bir gerçek ki, biz seni, bir tanık, bir müjdeleyici ve bir uyarıcı olarak gönderdik."},{"n":9,"t":"Allah'a ve resulüne inanasınız, O'nu destekleyesiniz, O'nu yüce bilesiniz ve sabah-akşam O'nu tespih edesiniz diye."},{"n":10,"t":"O seninle el tutuşup sözleşenler var ya, onlar gerçekte Allah ile bey'atleşiyorlar. Allah'ın eli onların ellerinin üstündedir. Kim ahdi bozar, döneklik ederse kendi aleyhine döneklik etmiş olur. Ve kim Allah'a verdiği sözde vefalı davranırsa, Allah ona büyük bir ödül verecektir."},{"n":11,"t":"Bedevilerden, geri bırakılmış olanlar sana şöyle diyecekler: \"Bizleri, mallarımız ve ailelerimiz oyaladı. O halde bizim için Allah'tan af dile.\" Onlar, kalplerinde olmayan şeyi dilleriyle söylüyorlar. De ki: \"Allah size bir zarar dilerse, yahut bir yarar murat ederse, O'nun sizin için dilediğine kim engel olabilir?\" Doğrusu şu ki, Allah, sizin yaptıklarınızdan haberdardır."},{"n":12,"t":"Siz sanmıştınız ki, resul de müminler de ailelerine bir daha asla dönmeyecekler. Bu düşünce kalplerinizde süslendi de çirkin bir sanıya saplandınız ve mahvolmuş bir topluluk haline geldiniz."},{"n":13,"t":"Kim Allah'a ve resulüne iman etmezse bilsin ki biz, inkârcılar için alevli bir ateş hazırladık."},{"n":14,"t":"Göklerin ve yerin mülkü Allah'ındır! Dilediğini affeder, dilediğine azap eder. Allah Gafûr'dur, Rahîm'dir."},{"n":15,"t":"Geri bırakılanlar, ganimetleri almak üzere gittiğiniz zaman şöyle diyecekler: \"İzin verin, biz de size uyalım!\" Onlar Allah'ın kelamını değiştirmek istiyorlar. De ki: \"Bize asla uyamazsınız! Allah önceden de böyle buyurmuştu.\" Bu kez şöyle diyecekler: \"Hayır, siz bizi kıskanıyorsunuz.\" İşin doğrusu şu ki, onlar çok az anlıyorlar/onlar, az bir kısmı hariç, anlamıyorlar."},{"n":16,"t":"Bedevilerden, geri bırakılmış olanlara de ki: \"Siz yakında çok zorlu savaş veren bir kavimle çarpışmaya çağrılacaksınız. Ya onlarla çarpışırsınız, yahut onlar Müslüman olurlar. Eğer itaat ederseniz, Allah size güzel bir ödül verecektir. Yok eğer önceden döndüğünüz gibi yüz çevirirseniz, Allah sizi acıklı bir azapla cezalandırır.\""},{"n":17,"t":"Köre zorlama yoktur, topala zorlama yoktur, hastaya da zorlama yoktur. Kim Allah'a ve resulüne itaat ederse, Allah onu altından ırmaklar akan cennetlere koyar. Kim de yüz çevirirse, Allah onu acıklı bir azapla cezalandırır."},{"n":18,"t":"Yemin olsun, Allah müminlerden, o ağacın altında sana bey'at ettikleri sırada hoşnut olmuştur. Onların gönüllerindekini bilmiş, üzerlerine huzur ve sükûn indirmiş ve kendilerine yakın bir fetih nasip etmiştir."},{"n":19,"t":"Alacakları birçok ganimetler de nasip etmiştir. Allah Azîz'dir, Hakîm'dir."},{"n":20,"t":"Allah size, elde edeceğiniz birçok ganimetler vaat etti. Şunu da size aceleden verdi ve insanların ellerini de sizden uzak tuttu ki bu, inananlara bir ibret olsun ve Allah sizi dosdoğru yola kılavuzlasın."},{"n":21,"t":"Sizin güç yetireceğiniz başka ganimetler de vardır. Allah onları kuşatmış bulunuyor. Allah, her şey üzerinde Kadîr'dir."},{"n":22,"t":"Eğer küfredenler sizinle savaşsalardı, sırtlarını dönüp kaçacaklardı. Sonra, bir dost da bir yardımcı da bulamazlardı."},{"n":23,"t":"Bu, Allah'ın öteden beri işleyip duran yolu-yöntemidir. Allah'ın yol ve yönteminde hiçbir değişme bulamazsın."},{"n":24,"t":"O odur ki, sizi onlarla galip getirdikten sonra Mekke'nin göbeğinde onların ellerini sizden, sizin ellerinizi de onlardan uzak tuttu. Allah, yapmakta olduklarınızı iyice görmektedir."},{"n":25,"t":"Onlar o kişilerdir ki, küfre sapıp sizi Mescid-i Haram'dan geri çevirdiler, bekletilen kurbanlık hediyelerin, yerlerine ulaşmasına engel oldular. Eğer kendilerini tanımadığınız için çiğneyeceğiniz ve bu bilgisizlik yüzünden üzüntü ve kınayışla karşılaşacağınız inanmış erkeklerle inanmış kadınlar olmasaydı, iş başka türlü olurdu. Böyle olması, Allah'ın, dilediğini rahmetine sokması içindir. Onlar birbirlerinden ayrılmış olsalardı, inkâra sapanları acıklı bir azapla cezalandırırdık."},{"n":26,"t":"İnkâr edenler, kalplerine öfkeli taassubu, o cahiliye taassubunu yerleştirmişlerdi. Allah ise huzur ve mutluluğunu resulünün, inananların üstüne indirmişti. Onları, takva kelimesine bağlı tutmuştu. Zaten onlar buna layık ve ehil idiler. Allah her şeyi çok iyi bilmektedir."},{"n":27,"t":"Yemin olsun ki Allah, resulüne o rüyayı hak olarak doğru çıkarmıştır. Allah dilerse, başlarınızı tıraş etmiş, saçlarınızı kısaltmış olarak güven içinde, korku duymadan Mescid-i Haram'a mutlaka gireceksiniz. Allah, sizin bilmediğinizi bildi de bundan önce size yakın bir fetih nasip etti."},{"n":28,"t":"O, resulünü hidayet ve hak dinle gönderdi ki, o dini tüm dinlere üstün kılsın. Tanık olarak Allah yeter!"},{"n":29,"t":"Muhammed, Allah'ın resulüdür. Onunla beraber olanlar, inkârcılara karşı çok çetin, kendi aralarında çok sevecendirler/çok merhametlidirler. Sen onları rükû eder, secdeye kapanır halde görürsün. Allah'tan bir lütuf ve hoşnutluk ister dururlar. Görünüşlerine gelince, yüzlerinde secde eseri/izi vardır. Bu onların Tevrat'taki nitelikleri. İncil'deki nitelikleri de şöyle: Tıpkı bir ekin ki filizini çıkarmış, o filizi kuvvetlendirmiş. Filiz kalınlaştı, gövdesi üzerine dikildi. Ziraatçıları da imrendirir/hayran bırakır bu ekin. Allah böyle yapar ki, onlar sayesinde, inkâr edenleri öfkelendirsin. Allah onlardan iman edip barışa/hayra yönelik işler yapanlara bir bağışlanma ve büyük bir ödül vaat etmiştir."}],[{"n":1,"t":"Ey iman edenler! Allah'ın ve resulünün önüne geçmeyin! Allah'tan korkun! Allah gerçekten çok iyi duyan ve gereğince bilendir."},{"n":2,"t":"Ey iman edenler! Seslerinizi o Peygamber'in sesinin üstüne yükseltmeyin! Kiminizin kiminize bağırarak konuştuğu gibi, onun huzurunda sözü yükseltmeyin! Yoksa siz hiç farkında olmadan amelleriniz eriyip gider."},{"n":3,"t":"Allah resulünün huzurunda seslerini alçaltanlar var ya, onlar Allah'ın, gönüllerini takva için imtihan ettiği kişilerdir. Bir bağışlanma vardır onlar için, bir büyük ödül vardır."},{"n":4,"t":"Odalarının arkasından sana seslenenlere gelince, onların çoğu aklını çalıştırmamaktadır."},{"n":5,"t":"Eğer onlar, sen yanlarına çıkıncaya dek sabretmiş olsalardı, kendileri için elbette daha hayırlı olurdu. Allah Gafûr'dur, Rahîm'dir."},{"n":6,"t":"Ey iman sahipleri! Özü-sözü bozuk birisi size bir haber getirdiğinde, hemen araştırıp inceleyin/delil arayın! Yoksa bilgisizlikle bir topluluğu suçlar da yapmış olduğunuza pişmanlık duyar hale gelirsiniz."},{"n":7,"t":"Bilin ki, Allah'ın resulü içinizdedir. Eğer o çoğu işte size uysaydı, gerçekten zorlukla karşılaşır, sıkıntıya düşerdiniz. Ama Allah, imanı size sevdirmiş ve onu gönüllerinizde süslemiştir. Ve size küfrü, öz-söz bozukluğunu, isyanı çirkin göstermiştir. Rüşte ermiş olanlar işte bunlardır;"},{"n":8,"t":"Allah'tan bir lütuf ve nimet olarak. Alîm'dir Allah, Hakîm'dir."},{"n":9,"t":"Müminlerden iki zümre çarpışırlarsa, onların aralarında hemen barışı kurun! Eğer onlardan biri öteki aleyhine sınır tanımazlık edip saldırırsa, azgınlık edenle, Allah'ın emrine dönünceye kadar savaşın. Eğer vazgeçerse, yine ikisi arasını adalet ve dürüstlükle sulh edin. Kuşkusuz, Allah adalette titiz davrananları sever."},{"n":10,"t":"Şu bir gerçek ki, müminler sadece kardeştirler. O halde kardeşleriniz arasında barışı sağlayın ve Allah'tan sakının ki, size merhamet edilebilsin."},{"n":11,"t":"Ey inananlar! Bir topluluk başka bir toplulukla alay etmesin! Olabilir ki, alay ettikleri topluluk kendilerinden hayırlıdır. Kadınlar da başka kadınlarla alay etmesinler. Alay ettikleri, kendilerinden hayırlı olabilir. Öz benliklerinizi ayıplamayın/kendi nefislerinizde ayıplar aramayın; birbirinize lakaplar yakıştırmayın. İmandan sonra sapıklıkla adlanmak ne kötü şeydir! Kim ki tövbe etmez, işte böyleleri zalimlerdir."},{"n":12,"t":"Ey iman edenler! Zandan çok sakının! Çünkü zannın bir kısmı günahtır. Sinsi casuslar gibi ayıp aramayın! Gıybet ederek biriniz ötekini arkasından çekiştirmesin! Sizden biri, ölmüş kardeşinin etini yemek ister mi? Bakın bundan iğrendiniz. Allah'tan sakının! Hiç kuşkusuz, Allah tövbeleri çok kabul eden, rahmeti sonsuz olandır."},{"n":13,"t":"Ey insanlar! Biz sizi, bir erkekle bir dişiden yarattık. Ve örfler yoluyla tanışıp kaynaşasınız diye sizi milletlere, boylara ayırdık. Hiç kuşkusuz, Allah katında en seçkininiz, sakınılması gereken şeylerden en çok sakınanınızdır. Allah her şeyi bilir, her şeyden haberdardır."},{"n":14,"t":"Bedeviler: \"İman ettik.\" dediler. De ki: \"Siz iman etmediniz. Ancak 'Müslüman' olduk deyin. İman sizin kalplerinize girmemiştir. Eğer Allah'a ve resulüne itaat ederseniz Allah, yapıp ettiklerinizden hiçbir şey eksiltmez. Çünkü Allah Gafûr'dur, Rahîm'dir.\""},{"n":15,"t":"Müminler ancak şu kimselerdir ki, Allah'a ve resulüne iman ederler; sonra hiçbir kuşkuya düşmezler ve mallarıyla, canlarıyla Allah yolunda didinirler. İşte bunlardır, özü-sözü birbirine uyanlar."},{"n":16,"t":"De ki: \"Siz Allah'a dininizi mi öğretiyorsunuz? Oysaki Allah, gökte ne var, yerde ne var hepsini bilir. Allah her şeyi çok iyi bilmektedir.\""},{"n":17,"t":"İslam'a girmelerini senin başına kakıyorlar. De ki: \"İslamınızı benim başıma kakmayın! Aksine, eğer özü-sözü doğru insanlarsanız, sizi imana kılavuzladığı için Allah hepinizi minnet borcu altına sokar.\""},{"n":18,"t":"Şu bir gerçek ki, Allah göklerin ve yerin gaybını bilir. Allah, yaptıklarınızı iyice görmektedir."}],[{"n":1,"t":"Kaf. Şanı yüce, ilahî cömertlikle dolu Kur'an'a yemin olsun ki,"},{"n":2,"t":"İş sanıldığı gibi değil! Kendilerine içlerinden bir uyarıcı geldi diye şaştılar da şöyle dediler o küfre batanlar: \"Acayip şey bu!\""},{"n":3,"t":"Ölünce mi, biz toprak olunca mı? Çok uzak bir dönüştür bu.\""},{"n":4,"t":"Toprağın onlardan neyi eksilttiğini pek iyi bilmişizdir biz. Her şeyi saklayıp koruyan bir Kitap var katımızda."},{"n":5,"t":"Hayır, hayır! Onlar, hak kendilerine geldiğinde, onu yalanladılar. Şimdi perişan mı perişan bir durum içindedirler."},{"n":6,"t":"Bakmadılar mı üstlerindeki göğe ki nasıl kurduk onu, nasıl süsleyip nakışladık?! Yırtığı, çatlağı da yoktur onun."},{"n":7,"t":"Yeryüzünü de biz uzatıp yaydık; denge noktaları yerleştirdik ona ve bitirdik onda, bakanları hayran bırakan her türlü çifti."},{"n":8,"t":"İbretle bakılası, gönüller açıcı şeyler olarak; hakka yönelen her kula öğüt olarak."},{"n":9,"t":"Gökten, kutlu ve bereketli bir su indirdik de onunla bahçeler yeşerttik, hasatlanacak daneler yetiştirdik."},{"n":10,"t":"Yüksek yüksek hurma ağaçları büyüttük. Birbirine girmiş kümeler halinde tomurcukları vardır onların."},{"n":11,"t":"Kullara rızık olsun diye. Ve o suyla ölü bir beldeye hayat verdik. İşte böyledir topraktan fışkırış."},{"n":12,"t":"Onlardan önce Nûh kavmi, Ress halkı, Semûd kavmi yalanlamıştı."},{"n":13,"t":"Âd, Firavun ve Lût'un halkı da..."},{"n":14,"t":"Eykeliler, Tübba' kavmi de. Hepsi resulleri yalanladı da duyurulan azap hak oldu."},{"n":15,"t":"İlk yarıştan âciz kalıp yorulmuş muyduk? Hayır, yeni bir yaratıştan kuşku içinde olan onlardır."},{"n":16,"t":"Yemin olsun ki, insanı biz yarattık. Nefsinin ona neler fısıldadığını da biz biliriz. Biz ona, şah damarından daha yakınız."},{"n":17,"t":"Sağında ve solunda oturmuş iki görevli, kayıt yapmaktadır."},{"n":18,"t":"Bir söz sarfetmeye dursun, yanındaki gözcü hemen zaptediverir."},{"n":19,"t":"Ölüm sarhoşluğu hak olarak geldi. İşte bu, senin kaçıp durduğun şeydir."},{"n":20,"t":"Ve sûra üflendi. İşte bu, geleceği vaat edilen gündür."},{"n":21,"t":"Her benlik, yanında bir güdücü, bir de tanık olduğu halde gelir."},{"n":22,"t":"Yemin olsun, sen bundan gaflet içindeydin. Ama perdeni üstünden kaldırıverdik. Bugün gözün keskin mi keskin."},{"n":23,"t":"Yoldaşı şöyle der: \"İşte yanımdaki, hazır!\""},{"n":24,"t":"Siz, ikiniz! Tüm nankörleri, inatçıları cehenneme atın!"},{"n":25,"t":"Durmadan hayrı engelleyeni, azgını, işkilciyi..."},{"n":26,"t":"O ki, Allah'ın yanına başka bir ilah koydu. Artık atın onu, o şiddetli azabın içine!"},{"n":27,"t":"Yoldaşı dedi ki: \"Rabbimiz, onu ben azdırmadım. Onun kendisi, dönüşü olmayan bir sapıklık içindeydi.\""},{"n":28,"t":"Allah buyurdu: \"Huzurumda çekişmeyin! Ben size uyarıyı çok önceden göndermiştim.\""},{"n":29,"t":"\"Benim huzurumda söz değiştirilmez ve ben kullara asla zulmetmem.\""},{"n":30,"t":"O gün cehenneme: \"Doldun mu?\" deriz. O ise: \"Daha yok mu?\" der."},{"n":31,"t":"Ve cennet, takva sahiplerine yaklaştırılmıştır; hiç uzak değildir."},{"n":32,"t":"İşte size vaat edilen budur. Allah'a sürekli yönelen, korunması gerekeni koruyan herkese..."},{"n":33,"t":"Görmediği halde Rahman'dan ürperen ve Allah'a yönelik bir kalp getiren herkese..."},{"n":34,"t":"Esenlikle girin oraya! Sonsuzlaşma günüdür bu."},{"n":35,"t":"Orada onlar için istedikleri her şey var. Katımızda ise dahası da var."},{"n":36,"t":"Onlardan önce nice nesilleri helâk ettik ki, vuruş ve tutuşları bunlardan daha zorluydu. Ülkelerde delikler açmışlardı/beldelerde kaçacak delik aradılar/beldeleri boydan boya dolaştılar. Var mı bir kaçacak yer?"},{"n":37,"t":"Hiç kuşkusuz, bunda, kalbi olan yahut tam bir tanık olarak kulak veren için mutlak bir öğüt vardır."},{"n":38,"t":"Yemin olsun, biz gökleri, yeri ve bunlar arasındakileri altı günde yarattık. Ve bize hiçbir yorgunluk dokunmadı."},{"n":39,"t":"Artık onların söylediklerine sabret ve Güneş'in doğuşundan önce de batışından önce de Rabbinin hamdiyle tespih et!"},{"n":40,"t":"Gecenin bir kısmında ve secdelerin arkalarından O'nu tespih et!"},{"n":41,"t":"Haykıranın çok yakın bir yerden sesleneceği günü dinle!"},{"n":42,"t":"O gün o müthiş sesi hak olarak dinleyecekler. Ortaya çıkış/diriliş günüdür bu."},{"n":43,"t":"Biz, evet biz hayat veriyoruz, biz öldürüyoruz. Ve dönüş yalnız bizedir."},{"n":44,"t":"O gün, yer çatır çatır yarılıp onlardan çabucak uzaklaşır. Bu yalnız bizim için kolay olan bir haşretmedir."},{"n":45,"t":"Biz onların neler söylediklerini çok iyi biliyoruz. Sen onların üstüne bir zorba değilsin. O halde, benim tehdidimden korkanlara sadece Kur'an'la öğüt ver."}],[{"n":1,"t":"O tozutup savuranlara/o kırıp un-ufak edenlere,"},{"n":2,"t":"O ağırlık taşıyanlara,"},{"n":3,"t":"O kolayca akıp gidenlere/o rahatça yüzenlere,"},{"n":4,"t":"O iş ve oluşu bölüştürenlere yemin olsun ki,"},{"n":5,"t":"Hiç kuşkusuz, o size vaat olunan kesinlikle doğrudur."},{"n":6,"t":"Ve din, şaşmaz bir olgudur."},{"n":7,"t":"Yemin olsun o ahenkli yollar taşıyan göğe,"},{"n":8,"t":"Ki siz gerçekten tartışmalarla dolu bir söz içindesiniz."},{"n":9,"t":"Yüzgeri çevrilen onun yüzünden çevrilir."},{"n":10,"t":"Kahrolsun o düzenbaz yalancılar,"},{"n":11,"t":"Ki onlar bir sersemlik içinde ne yaptıklarından habersizdirler."},{"n":12,"t":"Sorarlar: \"Ne zaman o din günü?\""},{"n":13,"t":"O gün onlar ateş üzerinde deneme ve elemeye tâbi tutulacaklardır."},{"n":14,"t":"Tadın imtihan ve ıstırabınızı. İşte budur o çarçabuk gelmesini istediğiniz!"},{"n":15,"t":"Şu da bir gerçek ki, sakınıp korunanlar bahçelerde ve pınar başlarındadır;"},{"n":16,"t":"Rablerinin kendilerine verdiğini almış kişiler olarak. Doğrusu, onlar bundan önce de iyilik ve güzellik sergilemekteydiler."},{"n":17,"t":"Gecenin pek azında uyumaktaydılar."},{"n":18,"t":"Seher vakitlerinde af dilemekteydi onlar."},{"n":19,"t":"İhtiyaç sahibi için, yoksul için bir hak vardı mallarında onların."},{"n":20,"t":"Yeryüzünde ayetler vardır görürcesine bilenler için."},{"n":21,"t":"Benliklerimizin içinde de. Hâlâ bakıp görmeyecek misiniz?"},{"n":22,"t":"Sizin, rızkınız da göktedir, tehdit edildiğiniz şey de."},{"n":23,"t":"Göğün ve yerin Rabbine yemin olsun ki, o tıpkı sizin konuşabildiğiniz gibi kesin bir gerçektir."},{"n":24,"t":"Geldi mi sana İbrahim'in ikram edilen konuklarının haberi?"},{"n":25,"t":"Hani, İbrahim'in yanına girmişlerdi de \"Selam!\" demişlerdi. İbrahim: \"Selam! Tanınmayan bir topluluk bu.\" demişti."},{"n":26,"t":"Hemen ailesinin yanına gitti; semiz bir dana getirdi."},{"n":27,"t":"Danayı misafirlerin önüne sürdü. \"Yemez misiniz?\" dedi."},{"n":28,"t":"O arada, içine bunlardan bir kuşku düştü. \"Korkma!\" dediler. Ve ona bilgin bir oğlan müjdelediler."},{"n":29,"t":"Derken, karısı bir çığlık içinde döndü; yüzüne vurarak şöyle dedi: \"Ben, doğurma yaşını geçmiş bir kocakarıyım!\""},{"n":30,"t":"Dediler ki: \"Rabbin öyle buyurmuştur. Hüküm ve hikmet sahibi O'dur, en iyisini bilen de O'dur."},{"n":31,"t":"İbrahim sordu: \"Amacınız ne, ey elçiler?\""},{"n":32,"t":"Dediler: \"Biz, suçlulardan oluşan bir topluma gönderildik.\""},{"n":33,"t":"\"Üzerlerine çamurdan taş atalım diye.\""},{"n":34,"t":"\"Rabbin katında, sınır tanımazlar için işaretlenmiş taşlar.\""},{"n":35,"t":"Orada, müminlerden kim varsa çıkardık."},{"n":36,"t":"Artık orada, bir ev dışında, müslümanlardan/Allah'a teslim olanlardan hiç kimse bulamıyorduk."},{"n":37,"t":"Acıklı azaptan korkanlar için orada bir işaret bıraktık;"},{"n":38,"t":"Mûsa'da da. Biz onu açık bir kanıtla Firavun'a gönderdik."},{"n":39,"t":"O tüm gücüyle/tüm seçkin adamlarıyla birlikte yüz çevirdi ve şöyle dedi: \"Bir büyücü yahut mecnun.\""},{"n":40,"t":"Bunun üzerine, onu da ordusunu da yakalayıp suyun ortasına fırlattık. Kendi kendini kınayıp duruyordu."},{"n":41,"t":"Âd kavminde de bir ibret var. Onlar üzerine, her şeyi yerinden söken rüzgârı göndermiştik."},{"n":42,"t":"Üzerinden geçtiği her şeyi kül haline getirmeden bırakmıyordu."},{"n":43,"t":"Semûd'da da bir ibret var. Onlara şöyle denmişti: \"Bir vakte kadar yiyip içip eğlenin.\""},{"n":44,"t":"Daha sonra onlar, Rablerinin emrine kafa tuttular da gözleri baka baka yıldırım kendilerini yakaladı."},{"n":45,"t":"Ne kalkıp kaçabildiler ne de kendilerine yardım eden oldu."},{"n":46,"t":"Daha önce de Nûh kavmini batırmıştık. Çünkü onlar da doğruluktan ayrılmış bir topluluktu."},{"n":47,"t":"Göğe gelince, onu biz ellerimizle kurduk. Hiç kuşkusuz, biz, genişleticileriz."},{"n":48,"t":"Yeri de biz döşedik. Ne güzel döşeyicileriz!"},{"n":49,"t":"Herşeyden iki çift yarattık ki düşünüp anlayabilesiniz."},{"n":50,"t":"O halde Allah'a kaçın/sığının! Ben size O'ndan gelmiş açıklayıcı bir uyarıcıyım."},{"n":51,"t":"Allah'ın yanına başka bir ilah koymayın! Ben size O'ndan gelmiş açıklayıcı bir uyarıcıyım."},{"n":52,"t":"İşte böyle! Onlardan önce herhangi bir resul geldiğinde, mutlaka şöyle dediler: \"Ya büyücüdür ya deli.\""},{"n":53,"t":"Bunu aralarında vasiyetleştiler mi? Hayır, azıp sapmış bir topluluk bunlar."},{"n":54,"t":"Artık onlardan yüz çevir. Sen bu yüzden kınanmayacaksın."},{"n":55,"t":"Hatırlat/öğüt ver; çünkü hatırlatıp öğüt vermek müminlere yarar sağlar."},{"n":56,"t":"Ben, cinleri ve insanları bana ibadet etmeleri/benim için iş yapıp değer üretmeleri dışında bir şey için yaratmadım."},{"n":57,"t":"Ben onlardan rızık istemiyorum. Beni yedirip doyurmalarını da istemiyorum."},{"n":58,"t":"Hiç kuşkusuz, Allah Rezzâk'tır, bol bol rızık verir. Kuvvet sahibidir, Metîn'dir, güçlü ve dayanıklıdır."},{"n":59,"t":"Şu bir gerçek ki, zulmedenlerin, tıpkı arkadaşlarının günahları gibi günahları vardır. O halde acele etmesinler."},{"n":60,"t":"O vaat edildikleri günlerinden dolayı vay kâfirlerin haline!"}],[{"n":1,"t":"Yemin olsun Tûra,"},{"n":2,"t":"Satır satır yazılmış Kitap'a,"},{"n":3,"t":"Ki açılıp yayılmış ince deri üzerine yazılmıştır."},{"n":4,"t":"Yemin olsun düzenli bir biçimde bakılan o eve,"},{"n":5,"t":"Yemin olsun yükseltilmiş tavana,"},{"n":6,"t":"Yemin olsun o alevlerle kaynatılıp köpürtülmüş denize,"},{"n":7,"t":"Ki hiç kuşkusuz, senin Rabbinin azabı meydana gelecektir."},{"n":8,"t":"Ona engel olacak hiçbir şey yoktur."},{"n":9,"t":"O gün gök bir çalkanışla çalkanır."},{"n":10,"t":"Ve dağlar bir yürüyüşle yürür."},{"n":11,"t":"Vay hallerine o gün, yalanlayanların,"},{"n":12,"t":"Ki onlar bir batağa dalmış oynamaktadırlar."},{"n":13,"t":"O gün cehenneme bir kakılışla kakılırlar."},{"n":14,"t":"\"İşte budur yalanlayıp durduğunuz ateş!\""},{"n":15,"t":"\"Bu da mı büyü?! Yoksa siz mi görmüyordunuz?\""},{"n":16,"t":"\"Dalın ona! Artık ister sabredin ister sabretmeyin. Sizin için hepsi birdir. Siz ancak yapıp ettiğiniz şeylerin karşılığıyla yüzyüze geleceksiniz.\""},{"n":17,"t":"Korunup sakınanlar; cennetler, nimetler içindedir."},{"n":18,"t":"Rablerinin kendilerine verdikleriyle keyif çatarlar. Rableri onları cehennem azabından korumuştur."},{"n":19,"t":"\"Yapıp ettiklerinizin karşılığı olarak afiyetle yiyin, için;"},{"n":20,"t":"Art arda dizilmiş koltuklar üzerinde yaslanmış olarak.\" Ve biz onları parlak, iri gözlü hurilerle eşleştirmişizdir."},{"n":21,"t":"İman edip zürriyetleri de imanda kendilerine uyanların, soy-soplarını da kendilerine katmışızdır. Ve kendi amellerinden kendilerinin hiçbir şeyini eksiltmemişizdir. Her kişi, kazandığı karşılığında bir rehindir."},{"n":22,"t":"Biz onlara canlarının çektiği meyveden ve etten ikram ettik."},{"n":23,"t":"Orada bir kadeh tokuştururlar ki, içinde ne bir boş laf var ne de günaha sokuş."},{"n":24,"t":"Çevrelerinde, kendilerine özgülenmiş genç uşaklar dolaşır; sanki sedeflerinde saklı inciler."},{"n":25,"t":"Birbirlerine dönüp soruşurlar. Ve derler:"},{"n":26,"t":"\"Daha önce biz, ailemiz içinde endişe ile ürperiyorduk.\""},{"n":27,"t":"\"Allah bize lütufta bulundu ve bizi o iliklere işleyen azaptan korudu.\""},{"n":28,"t":"\"Biz önceden O'na yakarıyorduk. Çünkü O'dur Berr, cömertçe iyilik eden; O'dur rahmeti sınırsız olan.\""},{"n":29,"t":"Artık hatırlat, öğüt ver! Rabbinin nimetine yemin olsun ki, sen ne kâhinsin ne de cin çarpmış."},{"n":30,"t":"Yoksa şöyle mi diyorlar: \"O bir şairdir. Zamanın ölüm getiren felaketine çarpılmasını bekliyoruz.\""},{"n":31,"t":"De ki: \"Bekleyin! Doğrusu sizinle beraber ben de bekleyenlerdenim.\""},{"n":32,"t":"Acaba bunu onlara hayalleri mi emrediyor yoksa bunlar azmış bir topluluk mu?"},{"n":33,"t":"Yoksa, \"Onu uydurdu\" mu diyorlar! Hayır, iman etmiyorlar."},{"n":34,"t":"Eğer doğru sözlü iseler, onun benzeri bir hadis/söz getirsinler."},{"n":35,"t":"Yoksa onlar hiçbir şeysiz mi yaratıldılar? Yoksa bizzat kendileri mi yaratıcıdır?"},{"n":36,"t":"Yoksa gökleri ve yeri onlar mı yarattı? Hayır, onlar gerekli bilgiye ulaşamıyorlar!"},{"n":37,"t":"Yoksa Rabbinin hazineleri onların yanında mı? Yoksa güç ve egemenlik sahibi onlar mı?"},{"n":38,"t":"Yoksa onlara özgü bir merdiven var da onun üzerinde mi dinliyorlar? Eğer böyleyse, dinleyenleri açık bir kanıt getirsin."},{"n":39,"t":"Yoksa kızlar O'na, oğullar size mi?"},{"n":40,"t":"Yoksa sen onlardan bir ücret istiyorsun da bir borç yüzünden onlar, yük altına mı giriyorlar?"},{"n":41,"t":"Yoksa gayb yanlarında da yazıp duruyorlar mı?"},{"n":42,"t":"Yoksa bir tuzak mı kurmak istiyorlar? Doğrusu şu ki, o inkâr edenlerin kendileri tuzağa yakalanmışlardır."},{"n":43,"t":"Yoksa Allah'tan başka bir ilahları mı var? Uzaktır Allah, onların ortak koştuklarından."},{"n":44,"t":"Gökten bir parçanın düştüğünü görseler şöyle derler: \"Üstüste yığılmış bulutlar!\""},{"n":45,"t":"Bayılıp yere serilecekleri günlerine kavuşuncaya kadar bırak onları!"},{"n":46,"t":"O gün, tuzakları kendilerine bir yarar sağlamayacak; onlara yardım da edilmeyecek!"},{"n":47,"t":"Zulmedenler için bundan başka bir azap da vardır. Fakat onların çokları bilmiyorlar."},{"n":48,"t":"Rabbinin hükmüne sabret! Kuşkusuz, sen bizim gözlerimizin önündesin. Kalktığında, Rabbinin hamdiyle tespih et!"},{"n":49,"t":"Gecenin bir bölümünde ve yıldızların ardından da O'nu tespih et!"}],[{"n":1,"t":"Yemin olsun inip çıktığı zaman yıldıza/fışkırıp çıktığı zaman çimene/süzülüp aktığı zaman Ülker Yıldızı'na/aşağı indiği zaman o parçalar halinde ağır ağır gelene,"},{"n":2,"t":"Ki arkadaşınız ne saptı ne de azdı."},{"n":3,"t":"O; kuruntudan, keyfinden konuşmuyor."},{"n":4,"t":"İndirilmiş bir vahiyden başkası değildir o."},{"n":5,"t":"Kuvvetleri çok müthiş olan belletip öğretti onu ona."},{"n":6,"t":"Akıl, güzellik ve güç sahibidir. Doğrulup dikildi."},{"n":7,"t":"En yüksek ufuktadır o."},{"n":8,"t":"Sonra iyice yaklaştı ve sarktı,"},{"n":9,"t":"İki yayın beraberliği gibi, belki ondan da yakındı."},{"n":10,"t":"Böylece vahyetti kuluna vahyettiğini."},{"n":11,"t":"Kalp yalanlamadı gördüğünü."},{"n":12,"t":"Onun gördüğü şey hakkında kuşkuya düşüp onunla çekişiyor musunuz?"},{"n":13,"t":"Yemin olsun ki onu bir başka inişte de görmüştü."},{"n":14,"t":"Son sınır ağacı, Sidretül Münteha yanında."},{"n":15,"t":"O ağacın yanındadır sığınılacak bahçe."},{"n":16,"t":"O vakit kuşatıp sarıyordu Sidre'yi kuşatıp saran,"},{"n":17,"t":"Göz ne kayıp şaştı ne azıp haddi aştı."},{"n":18,"t":"Yemin olsun ki Rabbinin en büyük ayetlerinden bir kısmını gördü."},{"n":19,"t":"Gördünüz mü Uzza'yı, Lât'ı."},{"n":20,"t":"Ve ötekini, üçüncüsü olan Menât'ı."},{"n":21,"t":"Erkek size, dişi Allah'a mı?"},{"n":22,"t":"İşte bu, insafsız bir bölüştürme."},{"n":23,"t":"Bunlar, sizin ve atalarınızın taktığı isimlerden başka şeyler değildir. Onlar hakkında Allah bir kanıt indirmemiştir. Onlar, sadece sanıya, bir de nefislerin hoşlandığı şeylere uyuyorlar. Yemin olsun, onlara hidayet Rablerinden gelmiştir."},{"n":24,"t":"İnsan için, her özleyip hayal ettiği var mı acaba?"},{"n":25,"t":"Sonrası da öncesi de/âhiret de dünya da Allah'ındır."},{"n":26,"t":"Göklerde nice melekler var ki, şefaatler hiçbir işe yaramaz. Allah'ın, dilediği ve hoşnut olduğu kimseler için izin vermesinden sonraki durum müstesna."},{"n":27,"t":"O âhirete inanmayanlar, meleklere mutlaka dişilerin adlarını takarlar."},{"n":28,"t":"Onların bu konuda hiçbir bilgisi yoktur. Yalnızca sanıya uyuyorlar. Sanı ise haktan hiçbir şey kazandırmaz."},{"n":29,"t":"Bizim zikrimizden/Kur'an'ımızdan yüz çeviren ve iğreti dünya hayatından başka bir şey istemeyen kimseden, sen de yüz çevir."},{"n":30,"t":"Onların, ilimden ulaşacakları şey işte budur. Kuşkusuz, yolundan sapmış olanı Rabbin çok iyi bilir. Hidayet üzere yürüyeni de en iyi O bilir."},{"n":31,"t":"Göklerde ne var yerde ne varsa Allah'ındır. Bu, Allah'ın; yaptıklarıyla kötülük sergileyenleri cezalandırması, güzel davranıp güzel düşünenleri de güzellikle ödüllendirmesi içindir."},{"n":32,"t":"Öyle kişilerdir ki onlar, günahın büyüklerinden ve iğrençliklerden çekinip kaçınırlar. Bazı küçük sürçmeler hariç. Hiç kuşkusuz, senin Rabbin affı geniş olandır. Sizi en iyi bilen O'dur: Hem sizi topraktan oluşturduğu zaman hem de annelerinizin karınlarında ceninler halinde bulunduğunuz zaman. O halde kendi kendinizi temize çıkmış göstermeyin; kimin sakındığını en iyi bilen O'dur."},{"n":33,"t":"O yüz geri döneni gördün mü?"},{"n":34,"t":"Azıcık verdi, sona inatla sıkıca tuttu."},{"n":35,"t":"Gaybın bilgisi onun yanında da o mu görüyor?"},{"n":36,"t":"Yoksa haber verilmedi mi ona, Mûsa'nın sayfalarındakiler?"},{"n":37,"t":"Ve o çok vefalı İbrahim'in sayfalarındakiler..."},{"n":38,"t":"Gerçek şu ki, hiçbir günahkâr bir başka günahkârın yükünü sırtlamaz."},{"n":39,"t":"Gerçek şu ki, insan için çalışıp didindiğinden başkası yoktur."},{"n":40,"t":"Ve onun çalışıp didinmesi yakında görülecektir."},{"n":41,"t":"Sonra karşılığı kendisine hiç eksiksiz verilecektir."},{"n":42,"t":"Hiç kuşkusuz, son varış Rabbinedir."},{"n":43,"t":"Hiç kuşkusuz, güldüren de O'dur, ağlatan da..."},{"n":44,"t":"Hiç kuşkusuz, öldüren de O'dur, dirilten de..."},{"n":45,"t":"Hiç kuşkusuz, iki çifti, erkeği ve dişiyi yaratan O'dur;"},{"n":46,"t":"Meni halinde atıldığı zaman bir spermden..."},{"n":47,"t":"Hiç kuşkusuz, o ikinci oluşum da O'nun işidir."},{"n":48,"t":"Hiç kuşkusuz, zenginlik veren de O'dur, nimete boğan da..."},{"n":49,"t":"Hiç kuşkusuz, Şi'ra yıldızının/şuurlanmanın Rabbi de O'dur."},{"n":50,"t":"Hiç kuşkusuz, daha önceden gelmiş olan Âd'ı helâk etti."},{"n":51,"t":"Semûd'u da. Böylece geriye bir şey bırakmadı."},{"n":52,"t":"Daha önce de Nûh kavmini. Çünkü onlar, evet onlar zulmettiler, azdılar."},{"n":53,"t":"Altı üstüne gelmiş kentleri de yere geçirdi O."},{"n":54,"t":"Sarıp doladı onlara, sarıp doladığını."},{"n":55,"t":"Peki, Rabbinin nimetlerinden hangisinde kuşkuya düşüyorsun?"},{"n":56,"t":"Bu da ilk uyarıcılar gibi bir uyarıcıdır."},{"n":57,"t":"Yaklaşmakta/yaklaşacak olan yaklaştı."},{"n":58,"t":"Onu Allah'tan başka kaldıracak/uzaklaştıracak yok."},{"n":59,"t":"Şimdi siz bu sözden mi hayrete düşüyorsunuz?"},{"n":60,"t":"Gülüyorsunuz, ağlamıyorsunuz."},{"n":61,"t":"Ve siz, kibirlenip kafa tutarak sersemce somurtuyorsunuz."},{"n":62,"t":"Artık Allah için secdeye kapanın, ibadet edin/iş yapıp değer üretin!"}],[{"n":1,"t":"Saat yaklaştı, Ay yarıldı."},{"n":2,"t":"Bir ayet-alâmet görseler yüz çeviriyorlar ve şöyle diyorlar: \"Sürüp giden bir büyüdür bu!\""},{"n":3,"t":"Yalanladılar; kendi heves ve kuruntularına uydular. Oysaki her iş ve oluş karara, ölçüye ve düzene bağlanmıştır."},{"n":4,"t":"Yemin olsun ki, onlara haberlerden, içinde ihtar, sakındırma ve tehdit bulunanı gelmiştir."},{"n":5,"t":"Doruk noktaya çıkmış, isabeti tartışmasız bir hikmettir o. Ama uyarılar yarar sağlamıyor."},{"n":6,"t":"O halde yüz çevir onlardan sen de; o çağırıcının alışılmadık/ürpertirci şeye çağırdığı günde,"},{"n":7,"t":"Kaymış olarak gözleri, çıkarlar kabirlerden. Sanki çekirgelerdir, çıvgın mı çıvgın!"},{"n":8,"t":"Boyunları büküktür çağıranın önünde. Derler ki o küfre saplananlar: \"Çok zorlu bir gün bu!\""},{"n":9,"t":"Onlardan önce Nûh kavmi yalanlamıştı. Yalanladılar kulumuzu ve \"Mecnundur bu!\" dediler. Ve durduruldu kulumuz."},{"n":10,"t":"Bunun üzerine yakardı Rabbine, \"Yenilgiye uğradım işte, yardım et!\" diye..."},{"n":11,"t":"Biz de açtık gök kapılarını seller gibi akan bir su ile."},{"n":12,"t":"Ve yardık/fışkırttık yeryüzünü pınar pınar. Sonunda kesin ölçülere bağlanmış bir oluş üzere birleşti sular."},{"n":13,"t":"Ve taşıdık onu levhalar ve çivilerden oluşturulan şey üstünde."},{"n":14,"t":"Akıp gidiyordu gözlerimizin önünde, bir ödül olarak nankörlüğe uğratılan kişi için."},{"n":15,"t":"Yemin olsun ki, biz onu bir ibret ve işaret olarak arkaya bıraktık. Yok mu araştırıp öğüt alacak?"},{"n":16,"t":"Nasılmış benim azabım ve uyarılarım!"},{"n":17,"t":"Yemin olsun ki, biz, Kur'an'ı öğüt ve ibret için kolaylaştırdık. Fakat düşünen mi var?!"},{"n":18,"t":"Âd da yalanlamıştı. Ama nasıl oldu azabım ve uyarılarım!"},{"n":19,"t":"Biz onların üzerine uğursuzluğu kesiksiz bir günde, dondurucu/uğultulu bir kasırga gönderdik."},{"n":20,"t":"İnsanları, köklerinden sökülmüş hurma kütükleri gibi kaldırıp atıyordu."},{"n":21,"t":"Nasılmış benim azabım ve uyarılarım!"},{"n":22,"t":"Yemin olsun ki, biz, Kur'an'ı öğüt ve ibret için kolaylaştırdık. Fakat düşünen mi var?"},{"n":23,"t":"Semûd da uyarıları yalanlamıştı."},{"n":24,"t":"Şöyle demişlerdi: \"İçimizden bir tek insana mı uyacağız? Vallahi böyle bir durumda biz, sapıklık ve çılgınlık içine düşeriz.\""},{"n":25,"t":"\"Aramızdan öğüt ona mı verildi? Hayır, o yalancı küstahın biridir.\""},{"n":26,"t":"Yarın bilecekler, kimmiş yalancı küstah!"},{"n":27,"t":"Bir imtihan aracı olarak kendilerine dişi deveyi göndereceğiz. Artık gözetle onları ve sabret!"},{"n":28,"t":"Suyun, aralarında bölüştürüleceğini onlara bildir. Her su alış/içiş nöbetledir/içilecek her miktar hazırlanmıştır."},{"n":29,"t":"Arkadaşlarını çağırdılar, o da hançerini kapıp deveyi boğazladı."},{"n":30,"t":"Nasılmış benim azabım ve uyarılarım!"},{"n":31,"t":"Biz, onlar üzerine bir tek ses gönderdik de ağılcının serptiği kuru ot gibi kırılıp ufalandılar."},{"n":32,"t":"Yemin olsun ki, biz, Kur'an'ı öğüt ve ibret için kolaylaştırdık. Fakat düşünen mi var?!"},{"n":33,"t":"Lût kavmi de uyarıları yalanladı."},{"n":34,"t":"Biz de üzerlerine çakıl taşları fırlatan bir rüzgâr gönderdik. Sadece Lût'un ailesini, seher vakti kurtarmıştık,"},{"n":35,"t":"Katımızdan bir nimet olarak. Şükredeni işte böyle ödüllendiririz biz."},{"n":36,"t":"Yemin olsun, Lût onları bizim yakalayışımız hakkında uyarmıştı da onlar, uyarılarla ilgili olarak kuşkulanıp çekişmişlerdi."},{"n":37,"t":"Yemin olsun, Lût'un misafirlerinden nefislerini tatmin etmek istemişlerdi de onların gözlerini silme kör etmiştik. Hadi, tadın azabımı ve uyarılarımı?"},{"n":38,"t":"Yemin olsun, sabahleyin erkenden, kararlı ve oturaklı bir azap yakaladı onları."},{"n":39,"t":"Hadi, tadın azabımı ve uyarılarımı!"},{"n":40,"t":"Yemin olsun ki, biz, Kur'an'ı öğüt ve ibret için kolaylaştırdık. Fakat düşünen mi var?!"},{"n":41,"t":"Yemin olsun, Firavun hanedanına da uyarılar gelmişti."},{"n":42,"t":"Ayetlerimizin tümünü yalanladılar da biz de onları onurlu ve güçlü birine yaraşır bir yakalayışla yakaladık."},{"n":43,"t":"Sizin kâfirleriniz, ötekilerden hayırlı mı? Yoksa zübürlerinde/kutsallaştırılmış hizip kitaplarında sizin için bir beraat/dokunulmazlık mı var?"},{"n":44,"t":"Yoksa, \"Biz, yardımlaşan/yenilmez bir topluluğuz\" mu diyorlar?"},{"n":45,"t":"O topluluk, bozguna uğratılacak ve arkalarını dönüp kaçacaklar."},{"n":46,"t":"Hayır, buluşma zamanları kıyamet saatidir. Ne korkunç, ne acıdır o saat!"},{"n":47,"t":"Kuşkusuz, suçlular, şaşkınlık ve çılgınlık içindedir."},{"n":48,"t":"O gün yüzleri üstüne ateşe sürüklenirler. \"Cehennemin dokunuşunu tadın bakalım!\""},{"n":49,"t":"Şu bir gerçek ki, biz herşeyi bir ölçüye göre/bir kaderle yarattık."},{"n":50,"t":"Emrimiz bir tektir, bir göz kırpma gibidir."},{"n":51,"t":"Yemin olsun, biz sizin benzerlerinizi hep yok ettik. Fakat düşünen mi var?"},{"n":52,"t":"Onların yapmış oldukları her şey defterlerdedir."},{"n":53,"t":"Küçük-büyük tümü, satır satır yazılmıştır."},{"n":54,"t":"Korunup sakınanlar; bahçelerde, nehir kıyılarındadır."},{"n":55,"t":"Güçlü bir padişahın/bir Melîk'in katında, özü-sözü birlere has oturma yerlerinde..."}],[{"n":1,"t":"O Rahman,"},{"n":2,"t":"O öğretti Kur'an'ı,"},{"n":3,"t":"O yarattı insanı,"},{"n":4,"t":"O belletti ona beyanı."},{"n":5,"t":"Güneş ve Ay. Hesaba bağlıdır herbirinin her şeyi."},{"n":6,"t":"Çimen/yıldız ve ağaç secde ediyorlar."},{"n":7,"t":"Ve gök. Yükseltti onu. Ve koydu şaşmaz ölçüyü, mizanı."},{"n":8,"t":"Azgınlık etmeyin ölçü ve tartıda, saptırmayın mizanı."},{"n":9,"t":"Ölçüyü titizlikle, adaletle koruyun ve hüsrana araç yapmayın mizanı."},{"n":10,"t":"Ve yerküre. Koydu onu toprakta yaşayacak yaratıklar için."},{"n":11,"t":"Bir meyve var onda. Ve salkımlarla donatılmış hurma ağaçları."},{"n":12,"t":"Çimli ve samanlı dâne ve hoş kokulu otlar vardır."},{"n":13,"t":"Bu böyle iken, Rabbinizin nimetlerinden hangisini yalanlıyorsunuz?"},{"n":14,"t":"İnsanı, pişirilmiş çamur gibi kuru bir balçıktan yarattı."},{"n":15,"t":"Cini de ateşin dumansızından yarattı."},{"n":16,"t":"Rabbinizin nimetlerinden hangisini yalanlıyorsunuz?"},{"n":17,"t":"İki doğunun Rabbi de O'dur, iki batının Rabbi de."},{"n":18,"t":"Rabbinizin nimetlerinden hangisini yalanlıyorsunuz?"},{"n":19,"t":"Salmıştır iki denizi; buluşup kucaklaşıyorlar."},{"n":20,"t":"Bir ayırıcı var aralarında; kendi sınırlarını aşmıyorlar."},{"n":21,"t":"Rabbinizin nimetlerinden hangisini yalanlıyorsunuz?"},{"n":22,"t":"Çıkıyor onlardan inci ile mercan."},{"n":23,"t":"Peki Rabbinizin nimetlerinden hangisini sayarsınız yalan?"},{"n":24,"t":"Denizde koca dağlar gibi akıp giden o görkemli gemiler de O'nundur."},{"n":25,"t":"Rabbinizin nimetlerinden hangisini yalanlıyorsunuz?"},{"n":26,"t":"Yer üzerinde bulunan herkes yok olacaktır."},{"n":27,"t":"Sadece o bağış ve celal sahibi Rabbinin yüzü kalacaktır."},{"n":28,"t":"Peki, Rabbinizin nimetlerinden hangisini yalanlıyorsunuz?"},{"n":29,"t":"Göklerde ve yerde kim varsa O'ndan ister. O, her an yeni bir iş ve oluştadır."},{"n":30,"t":"Rabbinizin nimetlerinden hangisini yalanlıyorsunuz?"},{"n":31,"t":"Ey ağırlıklı ve onurlu iki toplum/ey insan ve cin toplulukları! Sizinle de meşgul olacağız."},{"n":32,"t":"Rabbinizin nimetlerinden hangisini yalanlıyorsunuz?"},{"n":33,"t":"Ey cin ve insan toplulukları! Göklerin ve yerin bucaklarından/köşelerinden geçip gitmeye gücünüz yeterse, hadi geçin gidin. Bilgi ve güç dışında bir şeyle geçip gidemezsiniz!"},{"n":34,"t":"Rabbinizin nimetlerinden hangisini yalanlıyorsunuz?"},{"n":35,"t":"İkinizin de üzerine ateşten bir alev ve erimiş bakır/duman gönderilir de başarılı olamazsınız."},{"n":36,"t":"Rabbinizin nimetlerinden hangisini yalanlıyorsunuz?"},{"n":37,"t":"Gök yarılarak, eriyip kızarmış yağ/kırmızıya boyanmış deri gibi bir gül haline geldiği zaman,"},{"n":38,"t":"Rabbinizin nimetlerinden hangisini sayacaksınız yalan?"},{"n":39,"t":"O gün günahlarından ne cin sorguya çekilir ne de insan."},{"n":40,"t":"Rabbinizin nimetlerinden hangisini sayacaksınız yalan?"},{"n":41,"t":"Suçlular, yüzlerinden tanınır da yakalanırlar perçemlerinden ve ayaklarından."},{"n":42,"t":"Rabbinizin nimetlerinden hangisini sayacaksınız yalan?"},{"n":43,"t":"İşte bu, günahkârların yalanlayıp durdukları cehennemdir."},{"n":44,"t":"Onlar, onunla kaynar su arasında dolaşırlar."},{"n":45,"t":"Rabbinizin nimetlerinden hangisini yalanlıyorsunuz?"},{"n":46,"t":"Rabbinin makamından korkan kimseye iki cennet var."},{"n":47,"t":"Rabbinizin nimetlerinden hangisini sayabilirsiniz yalan?"},{"n":48,"t":"İkisi de çeşit çeşit ağaçlarla/bitkilerle doludur."},{"n":49,"t":"Rabbinizin nimetlerinden hangisini yalanlıyorsunuz?"},{"n":50,"t":"O cennetlerde iki nehir var, kaynayıp akan."},{"n":51,"t":"Rabbinizin nimetlerinden hangisini sayarsınız yalan?"},{"n":52,"t":"O cennetlerde iki çift var her meyvadan."},{"n":53,"t":"Rabbinizin nimetlerinden hangisini sayarsınız yalan?"},{"n":54,"t":"Astarları atlastan döşeklere yaslanırlar. İki cennetin meyveleri elle alınacak kadar yakındır."},{"n":55,"t":"Rabbinizin nimetlerinden hangisini yalanlıyorsunuz?"},{"n":56,"t":"O cennetlerde, bakışlarını eşlerine dikmiş öyle dilberler vardır ki, daha önce onları ne cin kirletmiştir ne de insan."},{"n":57,"t":"Rabbinizin nimetlerinden hangisini sayarsınız yalan?"},{"n":58,"t":"Sanki yakut onlar, sanki mercan..."},{"n":59,"t":"Rabbinizin nimetlerinden hangisini sayarsınız yalan?"},{"n":60,"t":"İhsanın karşılığı sadece ihsan..."},{"n":61,"t":"Rabbinizin nimetlerinden hangisini sayarsınız yalan?"},{"n":62,"t":"İkisinden başka, iki cennet daha var."},{"n":63,"t":"Rabbinizin nimetlerinden hangisini yalanlıyorsunuz?"},{"n":64,"t":"İkisi de yeşil mi yeşil..."},{"n":65,"t":"Rabbinizin nimetlerinden hangisini sayarsınız yalan?"},{"n":66,"t":"İkisinde de iki kaynak var, sürekli fışkıran."},{"n":67,"t":"Rabbinizin nimetlerinden hangisini sayarsınız yalan?"},{"n":68,"t":"İkisinde de meyve, hurma ve nar var."},{"n":69,"t":"Rabbinizin nimetlerinden hangisini sayarsınız yalan?"},{"n":70,"t":"İçlerinde iyi mi iyi, güzel mi güzel hanımlar var."},{"n":71,"t":"Rabbinizin nimetlerinden hangisini sayarsınız yalan?"},{"n":72,"t":"Çadırlar içinde bekletilen huriler var."},{"n":73,"t":"Rabbinizin nimetlerinden hangisini sayarsınız yalan?"},{"n":74,"t":"Daha önce onları ne cin kirletmiştir ne de insan."},{"n":75,"t":"Rabbinizin nimetlerinden hangisini sayarsınız yalan?"},{"n":76,"t":"Yeşil yastıklarda, emsalsiz döşekler üzerinde yatarlar yan."},{"n":77,"t":"Rabbinizin nimetlerinden hangisini sayarsınız yalan?"},{"n":78,"t":"İkram ve kudret sahibi Rabbinin ismi öyle yüce ki..."}],[{"n":1,"t":"O beklenen müthiş olay olduğunda,"},{"n":2,"t":"Yoktur onun oluşunu yalanlayacak."},{"n":3,"t":"Kimini alçaltır, kimini yükseltir."},{"n":4,"t":"Yerküre bir sarsılışla sarsıldığında,"},{"n":5,"t":"Dağlar bir serpilişle serpildiğinde,"},{"n":6,"t":"Hepsi un-ufak olup dağılmıştır."},{"n":7,"t":"Ve sizler, üç çift/sınıf oluvermişsinizdir."},{"n":8,"t":"İşte uğur ve mutluluk yâranı. Nedir uğur ve mutluluk yâranı?"},{"n":9,"t":"İşte şomluk ve bunalım yâranı. Nedir şomluk ve bunalım yâranı?"},{"n":10,"t":"Ve oluşta önde gidenler, yarışta önde gidenler..."},{"n":11,"t":"İşte onlardır yaklaştırılanlar."},{"n":12,"t":"Nimetlerle dolu bahçelerdedirler."},{"n":13,"t":"Büyük kısmı öncekilerden,"},{"n":14,"t":"Az bir kısmı da sonrakilerden."},{"n":15,"t":"Süslü, nakışlı tahtlar üzerinde,"},{"n":16,"t":"Onlar üstünde karşılıklı yan gelip yaslanırlar."},{"n":17,"t":"Gencecik uşaklar dolanır çevrelerinde. Sürekli hizmete adanmışlardır."},{"n":18,"t":"Sürahiler, ibrikler ve öz kaynağından içkilerle doldurulmuş kadehler eşliğinde."},{"n":19,"t":"Ne başları döner ondan ne de akılları karışır."},{"n":20,"t":"Ve meyveler, gönüllerince seçtiklerinden."},{"n":21,"t":"Ve kuş eti iştahlarınca beğendiklerinden."},{"n":22,"t":"Ve genç kadınlar, iri ve siyah gözlü."},{"n":23,"t":"Titizlikle korunan inciler misali;"},{"n":24,"t":"Yaptıklarına karşılık olarak."},{"n":25,"t":"Ne boş bir laf işitirler orada ne de günaha sokacak bir şey."},{"n":26,"t":"Sadece \"Selam, selam!\" denir."},{"n":27,"t":"Uğur ve mutluluk yâranı. Nedir uğur ve mutluluk yâranı?"},{"n":28,"t":"Dikensiz kirazlar,"},{"n":29,"t":"Meyve dizili muz ağaçları,"},{"n":30,"t":"Uzayan gölgeler,"},{"n":31,"t":"Akıp dökülen sular,"},{"n":32,"t":"Birçok meyveler arasındadırlar."},{"n":33,"t":"Ne tükenir ne yasaklanır."},{"n":34,"t":"Yükseğe yerleştirilmiş döşekler içinde."},{"n":35,"t":"Biz kadınları da güzel bir biçimde yeniden yaratmış,"},{"n":36,"t":"Hepsini bakireler yapmışızdır,"},{"n":37,"t":"Yaşıt cilveli dilberler halinde,"},{"n":38,"t":"Uğur ve mutluluk yâranı için."},{"n":39,"t":"Bir bölümü öncekilerden."},{"n":40,"t":"Bir bölümü de sonrakilerden."},{"n":41,"t":"Ve şomluk ve uğursuzluk yâranı. Nedir şomluk ve uğursuzluk yâranı?"},{"n":42,"t":"İliklere işleyen bir ateş ve kaynar su içinde,"},{"n":43,"t":"Simsiyah bir gölge altındadırlar."},{"n":44,"t":"Ne serindir ne de cömert."},{"n":45,"t":"Çünkü şomluk yâranı, bundan önce servet ve refahla şımaranlardı."},{"n":46,"t":"O büyük günah üzerinde ısrar edip dururlardı."},{"n":47,"t":"Ve şöyle derlerdi: \"Ölünce mi, toprak ve kemik haline gelince mi, sahi o zaman mı yeniden diriltileceğiz?\""},{"n":48,"t":"\"Önceki atalarımız da mı?\""},{"n":49,"t":"De ki: \"Öncekiler de sonrakiler de.\""},{"n":50,"t":"Bilinen bir günün buluşma vakti/buluşma yerinde mutlaka bir araya getirileceklerdir."},{"n":51,"t":"Ve siz de ey sapık yalanlayıcılar!"},{"n":52,"t":"Zakkumdan bir ağaçtan mutlaka yiyeceksiniz/yiyecekler."},{"n":53,"t":"Karınları dolduracaklar ondan,"},{"n":54,"t":"Üzerine içecekler kaynar sudan,"},{"n":55,"t":"Susuzluktan çıkmış develerin içişi gibi içecekler."},{"n":56,"t":"Din gününde ağırlanışları böyledir."},{"n":57,"t":"Sizi biz yarattık, biz! Tasdik etseydiniz olmaz mıydı?"},{"n":58,"t":"Akıttığınız meniyi gördünüz mü?"},{"n":59,"t":"Siz mi yaratıyorsunuz onu, yoksa yaratıcılar bizler miyiz?"},{"n":60,"t":"Ölümü aranızda biz takdir ettik. Biz önüne geçilecekler değiliz."},{"n":61,"t":"Yerinize diğer benzerlerinizi getireceğiz ve sizi bilemeyeceğiniz bir şekilde yeniden oluşturacağız."},{"n":62,"t":"Yemin olsun, ilk yaratışı/yaratılışı bildiniz. Peki düşünüp ibret alsanız olmaz mı?"},{"n":63,"t":"Ekmekte olduğunuzu gördünüz mü?"},{"n":64,"t":"Siz mi bitiriyorsunuz onu, yoksa bitirenler bizler miyiz?"},{"n":65,"t":"Dileseydik, onu kuru bir çöl haline getirirdik de başlardınız şu şekilde gevelemeye:"},{"n":66,"t":"\"Vallahi, kayba uğrayıp borçlandık.\""},{"n":67,"t":"\"Doğrusu mahrum bırakıldık biz.\""},{"n":68,"t":"Şu içmekte olduğunuz suya baktınız mı?"},{"n":69,"t":"Buluttan onu siz mi indirdiniz, yoksa indirenler bizler miyiz?"},{"n":70,"t":"Dileseydik, onu tuzlu yapıverirdik. Peki şükretmeniz gerekmez mi?"},{"n":71,"t":"Çakıp çakıp çıkardığınız o ateşi gördünüz mü?"},{"n":72,"t":"Onun ağacını siz mi yarattınız yoksa yaratıp oluşturan bizler miyiz?"},{"n":73,"t":"Biz onu hem bir ibret hem de çöl yolcularına bir nimet kıldık."},{"n":74,"t":"O halde o yüce Rabbinin adını tespih et!"},{"n":75,"t":"İş onların sandığı gibi değil! Yıldızların doğup batma, kayıp düşme noktalarına yemin ediyorum."},{"n":76,"t":"Ve eğer bilirseniz, gerçekten büyük bir yemindir bu."},{"n":77,"t":"O, kesinlikle şerefli bir Kur'an'dır."},{"n":78,"t":"Titizlikle saklanan bir Kitap'tadır."},{"n":79,"t":"Ona, arındırılmışlardan başkası dokunmaz."},{"n":80,"t":"Âlemlerin Rabbi'nden indirilmiştir."},{"n":81,"t":"Şimdi siz, bu sözü mü kirletip küçümseyeceksiniz/bu sözle mi alttan alıp gevşek davranacaksınız/bu sözle mi yağcılık edeceksiniz?"},{"n":82,"t":"Rızkınızı, yalanlamanızdan ibaret mi kılıyorsunuz?"},{"n":83,"t":"Ya o canın boğaza gelip dayandığı zaman!"},{"n":84,"t":"İşte o zaman siz bakakalırsınız!"},{"n":85,"t":"Biz ona sizden daha yakınız, ama siz görmezsiniz."},{"n":86,"t":"Madem ceza görmeyecek kişilersiniz,"},{"n":87,"t":"Eğer doğru sözlülerseniz, onu geri çevirsenize."},{"n":88,"t":"Eğer o, yaklaştırılanlardan ise;"},{"n":89,"t":"Rahatlık, güzel rızık ve nimetlerle dolu cennet var ona."},{"n":90,"t":"Eğer kutlu, uğurlu kişilerdense,"},{"n":91,"t":"\"Selam sana kutlu ve uğurlu kişilerden!\" denir ona."},{"n":92,"t":"Eğer yalanlayan sapıklardansa;"},{"n":93,"t":"Kaynar sudan bir ziyafet,"},{"n":94,"t":"Ve cehenneme salıverilme var ona."},{"n":95,"t":"İşte budur, o tartışmasız, o kesin gerçek!"},{"n":96,"t":"Artık, o yüce Rabbinin adını tespih et!"}],[{"n":1,"t":"Göklerde ve yerdeki her şey Allah'ı tespih etmektedir. Azîz'dir O, Hakîm'dir."},{"n":2,"t":"Göklerin ve yerin mülkü ve yönetimi O'nundur; diriltir, öldürür. Her şey üzerinde kudret sahibidir O."},{"n":3,"t":"Evvel'dir O, başlangıcı yoktur; Âhir'dir O, sonu yoktur; Zâhir'dir O, her şeyde belirir; Bâtın'dır O, gözlerden gizlenmiştir. Her şeyi en güzel biçimde bilendir o."},{"n":4,"t":"O, odur ki, göklerle yeri altı günde yarattı, sonra arş üzerinde egemenlik kurdu. Yere gireni ve ondan çıkanı, gökten ineni ve onda yükseleni bilir. O, nerede olursanız olun sizinle beraberdir. Allah, işleyip üretmekte olduklarınızı en iyi şekilde görmektedir."},{"n":5,"t":"Göklerin de yerin de mülkü ve yönetimi O'nundur. İşler ve oluşlar Allah'a döndürülür."},{"n":6,"t":"Geceyi gündüzün içine sokar O; gündüzü de gecenin içine sokar. Göğüslerin sakladıklarını çok iyi bilendir O."},{"n":7,"t":"Allah'a resulüne iman edin; sizi üzerinde buyruk sahibi yaptığı şeylerden başkalarına bol bol verin! İçinizden iman eden ve infakta bulunanlar için çok büyük bir ödül vardır."},{"n":8,"t":"İman sahipleri iseniz size ne oluyor da Allah'a güvenmiyorsunuz? Oysaki Resul sizi Rabbinize inanmaya çağırıyor, sizden kuvvetli bir söz de almıştır."},{"n":9,"t":"O, odur ki, sizi karanlıklardan aydınlığa çıkarsın diye kulu üzerine, gerçeği apaçık gösteren ayetler indiriyor. Allah size karşı gerçekten çok şefkatli, çok merhametlidir."},{"n":10,"t":"Allah yolunda harcama yapmanıza engel ne var ki?.. Göklerin ve yerin mirası zaten Allah'ındır. Sizin, Fetih'ten önce infakta bulunan ve çarpışmaya gireniniz, bunu yapmayanlarla aynı değildir. Onlar, derece yönünden Fetih'ten sonra infakta bulunup çarpışmaya girenlerden çok daha üstündür. Allah hepsine güzellik vaat etmiştir. Allah, işleyip ürettiklerinizi en iyi biçimde haber almaktadır."},{"n":11,"t":"Allah'a kim güzel bir borç verecek ki, O onun verdiğini kat kat artırsın. Böyle birisi için onur verici bir ödül de vardır."},{"n":12,"t":"Gün olur, mümin erkeklerle mümin kadınları, ışıkları önlerinde ve sağ yanlarında koşar görürsün. Şöyle denilir: \"Bugün size, altlarından ırmaklar akan cennetler müjdeleniyor. Sürekli kalıcısınız içlerinde.\" İşte büyük başarının ta kendisidir bu."},{"n":13,"t":"O gün ikiyüzlü erkeklerle ikiyüzlü kadınlar, iman edenlere şöyle derler: \"Bize bakın da ışığınızdan bir parça alalım.\" Şöyle denir onlara: \"Arkanıza dönün de bir ışık arayın.\" Nihayet aralarına kapısı olan bir sur çekilir. İçinde rahmet vardır onun. Dış tarafı ise azap."},{"n":14,"t":"Onlara seslenirler: \"Biz sizinle değil miydik?\" Derler ki: \"Evet, bizimleydiniz. Ancak siz kendinizi yaktınız, bekleyip durdunuz, şüphe ettiniz, hayal ve kuruntular/hurafeler/anlamını bilmeden okuyuşlar sizi aldattı; nihayet Allah'ın emri geldi. O yaman aldatıcı, sizi Allah ile aldattı.\""},{"n":15,"t":"Bugün artık ne sizden fidye alınır ne de küfre sapanlardan. Varacağınız yer ateştir. Odur sizin mevlânız. Ne kötü dönüş yeridir o!"},{"n":16,"t":"İnananlar için hâlâ vakti gelmedi mi ki, kalpleri Allah'ın zikri/Kur'an'ı ve Hak'tan inen için ürpersin de daha önce kendilerine kitap verilmiş, sonra üzerlerinden uzun zaman geçmiş de kalpleri kaskatı kesilmiş kimseler gibi olmasınlar. Onların çoğu yoldan çıkmıştır."},{"n":17,"t":"Bilin ki Allah, toprağa ölümünden sonra hayat verir. Ayetleri size açık-seçik bildiriyoruz ki, aklınızı işletebilesiniz."},{"n":18,"t":"Şu bir gerçek: Sadaka veren erkeklerle sadaka veren kadınlar, bir de Allah'a güzelce borç verenler için karşılıklar kat kat yapılır. Onlar için, onur verici bir ödül de vardır."},{"n":19,"t":"Allah'a ve resulüne inananlar var ya, özü-sözü doğru kişiler onlardır. Rableri katında tanık olanlar/şehitlik mertebesine erenler de onlardır. Onların ödülleri ve ışıkları vardır. Küfre sapıp ayetlerimizi yalanlayanlara gelince, onlar cehennemin dostu olacaklardır."},{"n":20,"t":"Bilin ki, şu iğreti dünya hayatı bir oyun ve eğlenceden, bir süsten, aranızda bir övünmeden, mallarda ve evlatlarda çoğalma yarışından başka şey değildir. Bir yağmur misali ki, çıkardığı bitkiler çiftçilerin hoşuna gider. Ama biraz sonra o ot kurur, sapsarı kesildiğini görürsün. Nihayet bir ot ufantısı haline gelir. Âhirette şiddetli bir azap var, Allah'tan bir af ve hoşnutluk da var. Dünya hayatı bir aldanış/gurur aracından başka şey değildir."},{"n":21,"t":"Rabbinizden bir affa ve Allah ile resulüne inananlar için hazırlanmış bulunan, eni de yerle göğün eni kadar olan bir cennete doğru yarışarak koşun. Bu, Allah'ın dilediğine vereceği bir lütuftur. Allah, o büyük lütfun sahibidir."},{"n":22,"t":"Yeryüzünde ve kendi benliklerinizde meydana gelen hiçbir musibet yoktur ki, biz onu yaratmadan önce bir Kitap'ta belirlenmiş olmasın. Bu, Allah için çok kolaydır."},{"n":23,"t":"Böyle yapılmıştır ki, elinizden çıkana üzülüp ümitsizliğe düşmeyesiniz ve Allah'ın size verdiğiyle sevinip şımarmayasınız. Çünkü Allah, kendini beğenip övünenlerin hiçbirini sevmez."},{"n":24,"t":"Onlar; cimrilik eden, insanlara da cimriliği emreden kişilerdir. Yüz çeviren bilsin ki, Allah Ganî'dir, Hamîd'dir."},{"n":25,"t":"Yemin olsun, biz, resullerimizi açık-seçik delillerle gönderdik ve onlarla birlikte Kitap'ı ve ölçüyü de indirdik ki, insanlar adaleti ayakta tutsunlar/adaletle doğrulsunlar. Ve demiri de indirdik. Onda zorlu bir kuvvet ve insanlar için birçok yarar vardır. Allah bu sayede, kendisine ve resullerine, gayba inanarak kimin yardım edeceğini bilecektir. Allah Kavî'dir, Azîz'dir."},{"n":26,"t":"Yemin olsun, Nûh'u ve İbrahim'i de resul olarak gönderdik. Peygamberliği ve Kitap'ı bunların soyları arasına koyduk. O soylardan bir kısmı hidayete ermiştir. Ama onlardan çoğu, yoldan çıkmış olanlardır."},{"n":27,"t":"Sonra onların eserleri üzere, resullerimizi art arda gönderdik. Meryem'in oğlu İsa'yı da onların ardınca gönderdik. Ona İncil'i verdik; ona uyanların gönüllerine şefkat ve merhamet koyduk. Bir bid'at olarak ortaya çıkardıkları ruhbaniyeti, onlar üzerine biz yazmamıştık. Allah'ın rızasını kazanmak için ortaya çıkardılar. Ama ona gerektiği şekilde saygılı olmadılar. Onların, iman edenlerine ödüllerini verdik. Onlardan çoğu yoldan çıkmış olanlardır."},{"n":28,"t":"Ey iman edenler! Allah'tan korkun ve onun resulüne inanın ki size rahmetinden iki nasip versin: Size, kendisiyle yol açacağınız bir ışık lütfetsin ve sizi affetsin. Allah Gafûr'dur, Rahîm'dir."},{"n":29,"t":"Böylece, Ehlikitap, Allah'ın lütfundan hiçbir şeyi kotarma gücünde olmadıklarını bilsinler. Lütuf, Allah'ın elindedir; onu dilediğine verir. Allah, büyük lütfun sahibidir."}],[{"n":1,"t":"Allah, kocası hakkında seninle tartışan ve Allah'a şikâyette bulunan kadının sözünü işitmiştir. Allah, ikinizin karşılıklı konuşmasını işitir. Çünkü Allah en iyi işiten, en iyi görendir."},{"n":2,"t":"İçinizden, kadınlarına zıhar edenlerin, o kadınlar anneleri değildir. Onların anneleri ancak kendilerini doğuran kadınlardır. Böyleleri, kabul edilemez bir söz ve boş bir lakırdı sarf ediyorlar. Bununla birlikte Allah, gerçekten çok affedici, çok bağışlayıcıdır."},{"n":3,"t":"Kadınlarına zıhar edip sonra sarf etmiş oldukları söze geri dönenler, ilişkiye girmelerinden önce, özgürlüğünü yitirmiş bir benliği özgürlüğüne kavuşturacaklardır. İşte size yöneltilen öğüt budur. Allah, yapıp etmekte olduklarınızdan gereğince haberdardır."},{"n":4,"t":"Özgürlüğe kavuşturma imkânını bulamayan, ilişkiye girmelerinden önce, aralıksız iki ay oruç tutacaktır. Buna da gücü yetmeyen, altmış yoksulu doyuracaktır. Bütün bunlar Allah'a ve resulüne inanasınız diyedir. Ve işte bunlar, Allah'ın sınırlarıdır. Küfre sapanlara korkunç bir azap vardır."},{"n":5,"t":"Allah'a ve resulüne karşı gelenler, kendilerinden öncekilerin çarpılıp tepelendikleri gibi çarpılıp tepeleneceklerdir. Biz, gerçekleri apaçık gösteren ayetler indirmişizdir. Küfre sapanlar için, rezil edici bir azap vardır."},{"n":6,"t":"Gün olur, Allah onların hepsini diriltir ve yapıp ettiklerini onlara haber verir. Allah onu iyice sayıp zaptetmiştir, onlarsa unutmuşlardır. Allah, her şey üzerinde tam bir tanıktır."},{"n":7,"t":"Görmez misin ki Allah, göklerde olanları da yeryüzünde olanları da bilir. Üç kişi, aralarında fısıldaşmaya görsün, dördüncüleri O'dur; beş kişi fısıldaşmaya görsün altıncıları O'dur. Bundan az da olsalar çok da olsalar, O mutlaka onlarla beraberdir; nerede bulunurlarsa bulunsunlar. Sonra onlara, yapıp ettiklerini kıyamet günü haber verecektir. Allah her şeyi bilmektedir."},{"n":8,"t":"Görmedin mi şu fısıldaşmaktan yasaklananları ki, biraz sonra, yasaklanmış oldukları şeye dönüyorlar ve günah, düşmanlık, peygambere isyan konusunda fısıldaşıyorlar. Sana geldiklerinde, seni Allah'ın selamlamadığı biçimde selamlıyorlar. Kendi içlerinde ise şöyle diyorlar: \"Söylediğimiz şey yüzünden Allah bize azap etse ya!\" Cehennem yeter onlara. Girecekler oraya. Ne kötü dönüş yeridir o!"},{"n":9,"t":"Ey iman edenler! Aranızda fısıldaştığınız zaman, günah, düşmanlık ve resule isyan hususlarında fısıldaşmayın; hayırda erginlik/dürüstlük ve takva konusunda fısıldaşın. Huzurunda haşredileceğiniz Allah'tan sakının!"},{"n":10,"t":"Fısıltı, inananları kederlendirmek için ancak şeytandan gelir. Bununla birlikte o, Allah'ın izni olmadıkça inananlara hiçbir zarar veremez. Müminler sadece Allah'a güvenip dayansınlar!"},{"n":11,"t":"Ey iman edenler! Size, \"Meclislerde yer açın!\" dendiğinde, yer açın ki, Allah da sizin için genişlik sağlasın. \"Kalkın!\" dendiğinde de kalkın ki, Allah, içinizden inananlarla kendilerine ilim verilmiş olanların derecelerini yükseltsin. Allah, yaptıklarınızdan haberdardır."},{"n":12,"t":"Ey iman edenler! Resulle gizlice konuşacağınız zaman, bu gizli konuşmanızdan önce bir sadaka verin! Bu, sizin için daha hayırlı ve daha temizdir. Eğer bu imkânı bulamazsanız bilin ki, Allah Gafûr'dur, Rahîm'dir."},{"n":13,"t":"Gizli konuşmanızdan önce, sadakalar vermekten ürperdiniz mi? Çünkü yapmadınız. Allah size tövbe nasip etti. Artık namazı/duayı yerine getirin, zekâtı verin, Allah'a ve resulüne itaat edin. Allah, yaptıklarınızdan haberdardır."},{"n":14,"t":"Allah'ın kendilerine öfkelendiği bir kavmi dost edinenleri görmedin mi? Onlar ne sizdendirler ne de onlardan. Bilip durdukları halde yalana yemin ediyorlar."},{"n":15,"t":"Allah, onlar için şiddetli bir azap hazırlamıştır. Ne kötüdür onların yapmakta oldukları!"},{"n":16,"t":"Yeminlerini kalkan edinip Allah'ın yolundan alıkoydular. Küçük düşürücü bir azap var onlar için."},{"n":17,"t":"Onların malları da çocukları da kendilerine, Allah'a karşı hiçbir şey sağlamaz. Ateş halkıdır onlar. Uzun süre kalacaklardır orada."},{"n":18,"t":"Allah onları tekrar dirilttiği gün, size yemin ettikleri gibi O'na da yemin edecekler ve bir şey yaptıklarını sanacaklar. Dikkat edin, onlar yalancıların ta kendileridir."},{"n":19,"t":"Şeytan onları kuşattı da Allah'ın zikrini/Kur'an'ını onlara unutturdu. İşte bunlar şeytanın hizbidir. Dikkat edin! Şeytanın hizbi hüsrana uğrayanların ta kendileridir."},{"n":20,"t":"Allah'a ve resulüne kafa tutanlar en aşağılık kişiler arasındadırlar."},{"n":21,"t":"Allah, \"Ben ve resullerim mutlaka galip geleceğiz!\" diye yazmıştır. Allah çok güçlüdür, Azîz'dir."},{"n":22,"t":"Allah'a ve âhiret gününe inanan bir topluluğun, Allah'a ve resulüne karşı çıkanlarla sevgiye dayalı bir dostluk kurduğunu göremezsin. Bunlar onların ister babaları olsun, ister çocukları olsun, ister kardeşleri olsun, ister akrabaları olsun. Allah onların kalplerine imanı yazmış ve onları kendisinden bir ruhla desteklemiştir. Onları, altlarından ırmaklar akan cennetlere koyacaktır; sürekli kalacaklardır orada. Allah onlardan hoşnut olmuştur, onlar da Allah'tan hoşnut olmuşlardır. Allah'ın hizbi işte bunlardır. Dikkat edin, Allah'ın hizbi, başarıya ulaşanların ta kendileridir!"}],[{"n":1,"t":"Göklerde ne var, yerde ne varsa Allah'ı tespih etmiştir. Azîz'dir O, Hakîm'dir."},{"n":2,"t":"Ehlikitap'tan küfre sapanları, ilk toplanma gününde yurtlarından O çıkardı. Siz onların çıkacaklarını sanmamıştınız; onlarsa kalelerinin kendilerini Allah'tan koruyacağını zannetmişlerdi. Ama Allah onlara hiç ummadıkları yerden geldi, yüreklerine korku saldı; kendi evlerini kendi elleriyle ve iman sahiplerinin elleriyle tahrip ediyorlardı. Artık ibret alın, ey gözleri olanlar!"},{"n":3,"t":"Eğer Allah onlar üzerine sürgünü yazmamış olsaydı, onlara mutlaka dünyada azap ederdi. Âhirette de onlara ateş azabı vardır."},{"n":4,"t":"Çünkü onlar, Allah'a ve resulüne kafa tuttular. Kim Allah'a kafa tutarsa, bilsin ki Allah'ın azabı çok çetindir."},{"n":5,"t":"Bir hurma ağacını kestiniz, yahut onu kökleri üzerine dikili bıraktınızsa, bu Allah'ın izniyledir; yoldan çıkmışları rezil etmesi içindir."},{"n":6,"t":"Allah'ın onlardan resulüne aktardığı ganimetlere gelince, siz onun için ne at bindiniz ne deve sürdünüz; ama Allah, resullerini dilediği kimselerin üzerine salar. Allah her şeyi yapmakta sonsuz kudret sahibidir."},{"n":7,"t":"Allah'ın, kentler halkından resulüne zahmetsizce aktardığı mal ve nimetler şunlar içindir: Allah, Peygamber, yakınlar, yetimler, yoksullar, yolda kalmışlar. Bu böyle düzenlenmiştir ki, o mal ve nimetler sizden yalnız zengin olanlar arasında dönüp duran bir kudret aracı olmasın. Resul size ne verdiyse onu alın; sizi neden yasakladıysa ona son verin ve Allah'tan korkun. Hiç kuşkusuz, Allah'ın azabı çok şiddetlidir."},{"n":8,"t":"Sözü edilen o mallar, göçmen yoksullar içindir. Onlar ki, yurtlarından çıkarılıp mallarından yoksun bırakılmışlardır; Allah'tan bir lütuf ve bir hoşnutluk peşindedirler; Allah'a ve resulüne yardım ederler. İşte onlardır, özü-sözü doğru olanlar."},{"n":9,"t":"Onlardan önce yurda konmuş ve imana sarılmış olanlar, kendilerine hicret edenleri severler. Onlara verilenlerden ötürü göğüslerinde bir ihtiyaç duymazlar. Kendilerinin ihtiyaçları olsa bile, ötekileri kendi nefslerine tercih ederler. Nefsinin cimriliğinden/doymazlığından korunanlar, kurtuluşa erenlerin ta kendileridir."},{"n":10,"t":"Onlardan sonra gelenler de şöyle derler: \"Rabbimiz! Bizi ve bizden önce iman etmiş kardeşlerimizi affet; kalplerimizde, inananlara karşı bir düşmanlık bırakma! Rabbimiz, sen çok şefkatli, çok merhametlisin!\""},{"n":11,"t":"Görmedin mi o ikiyüzlülüğe sapanları ki, Ehlikitap'tan inkâra giden dostlarına şöyle diyorlar: \"Eğer toprağınızdan çıkarılırsanız, yemin olsun sizinle birlikte biz de çıkacağız. Sizinle ilgili olarak hiçbir zaman kimseye boyun eğmeyeceğiz. Eğer sizinle savaşılırsa mutlaka size yardım edeceğiz.\" Allah tanıktır ki onlar kesinlikle yalancıdırlar."},{"n":12,"t":"Eğer çıkarılsalar onlarla beraber çıkmazlar; eğer savaşa maruz bırakılsalar onlara yardım etmezler; yardım etmeye kalksalar da mutlaka arkalarını dönüp kaçarlar. Sonunda kendilerine de yardım edilmez."},{"n":13,"t":"Onların gönüllerinde, korku bakımından siz, Allah'tan daha zorlusunuz. Bu böyledir, çünkü onlar anlamayan bir topluluktur."},{"n":14,"t":"Onlar sizinle toplu halde değil ancak müstahkem kaleler içinde yahut duvarlar arasından savaşabilirler. Onların kendi aralarındaki problemleri/çıkmazları çetindir/ciddidir. Sen onları birlik/beraberlik halinde sanıyorsun, oysaki onların kalpleri darmadağınık/parça parçadır. Böyledir; çünkü onlar akıllarını işletmeyen bir topluluktur."},{"n":15,"t":"Kendilerinden biraz önce günahlarının vebalini tadanlara benziyorlar. Acı bir azap var onlara..."},{"n":16,"t":"Durumları, şeytanın durumuna benziyor. Hani, şeytan insana, \"Küfret/inkâr et!\" der, insan küfür ve inkâra sapınca da şöyle konuşur: \"Vallahi ben senden uzağım; ben, âlemlerin Rabbi olan Allah'tan korkarım!\""},{"n":17,"t":"Bu yüzden ikisinin de sonu, içinde sürekli kalacakları ateşe girmek oldu. Zalimlerin cezası işte budur."},{"n":18,"t":"Ey iman edenler! Allah'tan korkun! Ve her benlik, yarın için önden ne gönderdiğine bir baksın. Allah, yapmakta olduklarınızdan haberdardır."},{"n":19,"t":"O kimseler gibi olmayın ki, Allah'ı unuttular da Allah da onlara öz benliklerini unutturdu. Yoldan çıkmışların ta kendileridir onlar."},{"n":20,"t":"Ateşin dostlarıyla cennetin dostları bir olmaz. Cennetin dostları, kurtuluşu/zaferi elde edenlerin ta kendileridir."},{"n":21,"t":"Eğer biz bu Kur'an'ı bir dağın üzerine indirseydik, her halde sen onu Allah korkusundan huşû ile boynunu bükmüş, çatlayıp yarılmış görürdün. Biz benzetmeleri insanlar için yapıyoruz ki, inceden inceye düşünebilsinler."},{"n":22,"t":"Öyle Allah ki O, tanrı yok O'ndan başka. Gaybı da görünen âlemi de bilen O! Rahman O, Rahîm O."},{"n":23,"t":"Öyle Allah ki O, ilah yok O'ndan gayrı! Melik, Kuddûs, Selâm, Mümin, Müheymin, Azîz, Cebbâr, Mütekebbir. Allah, onların ortak koşmalarından yücedir, arınmıştır."},{"n":24,"t":"Allah'tır O! Haalik, Bâri', Musavvir'dir O! En güzel isimler/Esmâül Hüsna O'nundur. Göklerde ne var, yerde ne varsa O'nu tespih eder. Azîz'dir O, Hakîm'dir."}],[{"n":1,"t":"Ey iman edenler! Benim de düşmanım, sizin de düşmanınız olanları dostlar/tutamaklar edinmeyin. Onlar, size gelen hakkı inkâr ettikleri halde, siz onlara sevgi sunuyorsunuz. Onlar, Rabbiniz olan Allah'a inandınız diye Peygamber'i de sizi de yurdunuzdan çıkarıyorlar. Eğer siz benim yolumda cihat etmek, benim rızamı kazanmak için çıktınızsa, nasıl oluyor da onlara sevgide gizlilik yapıyorsunuz? Ben sizin gizlediğinizi de açıkladığınızı da çok iyi bilirim. İçinizden kim bunu yaparsa, düz yolun ortasında sapmış olur."},{"n":2,"t":"Eğer sizi ele geçirirlerse size düşman olurlar; ellerini ve dillerini size kötülükle uzatırlar. Zaten inkâr etmenizi istemişlerdir."},{"n":3,"t":"Kıyamet gününde ne hısımlarınızın ne de çocuklarınızın size hiçbir yararı olmaz. O, sizi birbirinizden ayıracaktır. Allah, işleyip ürettiklerinizi açık açık görmektedir."},{"n":4,"t":"İbrahim'le, beraberinde olanlarda sizin için çok güzel bir örnek vardır. Hani, onlar toplumlarına şöyle demişlerdi: \"Biz sizden de Allah dışındaki kulluk ettiklerinizden de uzağız. Sizi tanımıyoruz. Sizinle bizim aramızda, siz Allah'a, yalnız Allah'a inanıncaya kadar, sürekli düşmanlık ve nefret olacaktır.\" Ancak İbrahim babasına şöyle demişti: \"Senin için hep af dileyeceğim ama Allah'tan sana gelecek şeyi geri çevirme gücüm yoktur. Ey Rabbimiz! Yalnız sana güveniyoruz, yalnız sana yöneliyoruz! Dönüş yalnız sanadır!\""},{"n":5,"t":"\"Ey Rabbimiz! Bizi, küfre sapanlar için bir fitne/imtihan aracı yapma! Bağışla bizi ey Rabbimiz! Sen, yalnız sen sonsuz kudretin, sonsuz hikmetin sahibisin.\""},{"n":6,"t":"Yemin olsun, onlarda sizin için, Allah'ı ve âhiret gününü arzu edenlere çok güzel bir örnek vardır. Kim yüz çevirirse şunu bilsin ki, Allah, sınırsız zengindir; tüm övgülerin sahibidir."},{"n":7,"t":"Olabilir ki Allah sizinle, onlardan düşman olduklarınız arasına bir sevgi koyar. Allah'ın gücü herşeye yeter. Allah çok bağışlayan, çok esirgeyendir."},{"n":8,"t":"Allah sizi, din hakkında sizinle savaşmayan ve sizi yurtlarınızdan çıkarmayan kimselere iyilik etmekten, onlara adaletli davranmaktan men etmez. Allah, adaleti ayakta tutanları sever."},{"n":9,"t":"Allah sizi; ancak din hakkında sizinle savaşan, sizi yurtlarınızdan çıkaran, çıkarılmanıza yardım eden kimselerle dost olmaktan yasaklar. Böyleleriyle dost olanlar, zalimlerin ta kendileridir."},{"n":10,"t":"Ey iman sahipleri! Mümin kadınlar hicret ederek size geldiklerinde onları imtihan edin. Allah onların imanlarını daha iyi bilir ya! Eğer onların mümin hanımlar olduklarını anlarsanız, onları kâfirlere döndürmeyin. Ne bu mümin kadınlar o kâfirlere helaldir ne de o kâfirler bunlara helaldir. Bu kadınlar için harcadıklarını o kâfirlere geri verin. Mehirlerini kendilerine verdiğiniz takdirde, bu kadınları nikâhlamanızda sizin için bir sakınca yoktur. Kâfirlerin iffet ve nikâhlarına yapışmayın. Kâfirlere gitmeyi yeğleyen kadınlar için harcadıklarınızı onlardan geri isteyin; onlar da size gelen mümin kadınlar için harcadıklarını geri istesinler. Bu, Allah'ın hepinize buyruğudur. Aranızda hüküm veriyor. Allah Alîm'dir, Hakîm'dir."},{"n":11,"t":"Eğer, kâfirler tarafına geçmiş eşleriniz yüzünden birşeyleriniz inkârcılara gider, sonra da onlardan size kaçan kadınlar yüzünden ödeme sırası size gelirse, eşleri gitmiş olan müminlere, harcadıkları miktarı verin. Kendisine inandığınız Allah'tan korkun."},{"n":12,"t":"Ey Peygamber! İnanmış kadınlar sana gelip Allah'a hiçbir şeyi ortak koşmamak, hırsızlık yapmamak, zina etmemek, çocuklarını öldürmemek, elleriyle ayakları arasında bir iftira uydurup getirmemek, hayır ve marufta sana isyan etmemek hususunda sana biat ederlerse, onların biatlarını kabul et ve onlar için Allah'tan af dile. Şüphesiz, Allah Çok Bağışlayıcı'dır, Rahmân'dır/çok merhametlidir."},{"n":13,"t":"Ey iman edenler! Allah'ın kendilerine gazap ettiği bir toplulukla dostluk kurmayın! Çünkü bunlar âhiretten ümitlerini kesmişlerdir. Tıpkı, kabir halkından olan inkârcıların, ümitlerini kestikleri gibi..."}],[{"n":1,"t":"Göklerde ne var, yerde ne varsa Allah'ı tespih etmiştir. Azîz'dir O, Hakîm'dir."},{"n":2,"t":"Ey iman sahipleri! Yapmayacağınız şeyi neden söylüyorsunuz?"},{"n":3,"t":"Yapmayacağınız şeyi söylemeniz, Allah katında büyük bir günahtır."},{"n":4,"t":"Allah kendi yolunda, duvarları birbirine perçinlenmiş bir bina gibi, saf bağlıyarak çarpışanları sever."},{"n":5,"t":"Hani, Mûsa, toplumuna şöyle demişti: \"Ey toplumum! Benim size gönderilen Allah elçisi olduğumu bilip durduğunuz halde, beni neden incitiyorsunuz?\" Onlar bozulup sapınca Allah da onların kalplerini eğriltti. Çünkü Allah, sapıklardan oluşmuş bir topluluğu doğruya ve güzele kılavuzlamaz."},{"n":6,"t":"Meryem oğlu İsa'nın da şöyle dediğini hatırla: \"Ey İsrailoğulları! Ben size Allah'ın elçisiyim. Benden önce Tevrat'ı doğrulayıcı ve benden sonra gelecek Ahmet adında bir elçiyi müjdeleyici olarak gönderildim.\" Fakat İsa'nın müjdelediği elçi onlara apaçık deliller getirdiğinde: \"Bu, katıksız bir büyüdür!\" dediler."},{"n":7,"t":"İslam'a/Allah'a teslim olmaya çağrılıp durduğu halde, yalanlar düzerek Allah'a iftira edenden daha zalim kim vardır? Allah, zulme bulaşmış kişiler topluluğunu doğruya ve güzele iletmez."},{"n":8,"t":"İstiyorlar ki, ağızlarıyla Allah'ın nurunu söndürsünler. Ama Allah, küfre batanlar hoş görmeseler de nurunu tamamlayacaktır."},{"n":9,"t":"Resulünü hidayet ve hak dini getirmek üzere o gönderdi ki, ortak koşanlar hoşlanmasa bile, onu tüm dinlerden üstün kılsın."},{"n":10,"t":"Ey iman sahipleri! Dikkatlerinizi, sizi korkunç bir azaptan kurtaracak bir ticarete çekeyim mi:"},{"n":11,"t":"Allah'a ve onun resulüne inanır, Allah yolunda mallarınız ve canlarınızla didinirsiniz. İşte bu, sizin için en hayırlısıdır; eğer bilirseniz."},{"n":12,"t":"Günahlarınızı affeder ve sizi, altından nehirler akan bahçelere, sürekli cennetlerdeki temiz-bereketli barınaklara yerleştirir. İşte bu en büyük başarıdır."},{"n":13,"t":"Seveceğiniz daha başka şeyler de var: Allah'tan bir yardım, çok yakın bir fetih... İman sahiplerine müjde ver!"},{"n":14,"t":"Ey iman sahipleri! Allah'ın yardımcıları olun! Hani, Meryem oğlu İsa, havarilere: \"Allah'a gidişte benim yardımcılarım kimdir?\" demişti de, havariler: \"Biz, Allah'ın yardımcılarıyız!\" cevabını vermişlerdi. Bunun ardından, İsrailoğullarından bir zümre iman etmiş, bir zümre de küfre sapmıştı. Nihayet biz, iman sahiplerini düşmanlarına karşı güçlendirdik de onlar üstün geldiler."}],[{"n":1,"t":"Göklerdekiler ve yerdekiler o Melik, o Kuddûs, o Azîz, o Hakîm Allah'ı tespih ediyor."},{"n":2,"t":"O Allah'tır ki, ümmîlere içlerinden bir resul göndermiştir de o, onlara Allah'ın ayetlerini okur, onları arıtıp temizler, onlara Kitap'ı ve hikmeti öğretir. Onlar bundan önce tam bir sapıklık içine gömülmüşlerdi."},{"n":3,"t":"O resulü, ümmîlerden olup da henüz onlara katılmamış bulunan başka kimselere de gönderdi. O'dur Azîz, O'dur Hakîm."},{"n":4,"t":"İşte bu, Allah'ın lütfudur ki, onu dilediğine verir. Allah, büyük lütfun sahibidir."},{"n":5,"t":"Sırtlarına Tevrat yükletilip de sonra onu taşımayanların durumu, kutsal kitap parçaları taşıyan eşeğin durumuna benzer. Allah'ın ayetlerini yalanlayan topluluğun vücut verdiği örnek ne kötüdür! Allah, zulme sapmış bir topluluğu doğruya ve güzele ulaştırmaz."},{"n":6,"t":"De ki: \"Ey Yahudiler! Eğer insanlar arasında yalnız kendinizin Allah'ın dostları olduğunu sanıyorsanız, buna gerçekten inanıyorsanız, hadi ölümü isteyin!\""},{"n":7,"t":"Ama onlar, ellerinin üretip önden gönderdikleri yüzünden ölümü asla temenni edemezler. Allah, zalimleri bilmektedir."},{"n":8,"t":"Şunu da söyle: \"O kaçmakta olduğunuz ölüm, işte o, size mutlaka ulaşacaktır. Sonra, görülmeyeni de görüleni de bilene döndürüleceksiniz. O, size yapıp etmiş olduklarınızı haber verecektir.\""},{"n":9,"t":"Ey inananlar! Cuma günü, namaz/dua için çağrı yapıldığında, Allah'ı anmaya/Allah'ın Zikri'ne koşun! Alış-verişi bırakın! Eğer bilirseniz bu sizin için daha hayırlıdır."},{"n":10,"t":"Namaz/dua yerine getirilince hemen yeryüzüne dağılın ve Allah'ın lütfundan nasibinizi arayın! Allah'ı çok anın ki, kurtuluşa erebilesiniz."},{"n":11,"t":"Bir ticaret yahut oyun-eğlence görür görmez, dağılıp ona yöneldiler de seni ayaküstü bıraktılar. Onlara de ki: \"Allah katında bulunan, eğlenceden de ticaretten de hayırlıdır! Ve Allah, rızık verenlerin en hayırlısıdır.\""}],[{"n":1,"t":"Münafıklar sana geldiklerinde: \"Senin kesinlikle Allah'ın elçisi olduğuna tanıklık ederiz.\" derler. Senin kesinlikle O'nun elçisi olduğunu Allah zaten biliyor. Ve Allah tanıklık eder ki, münafıklar kesinlikle yalancıdırlar."},{"n":2,"t":"Yeminlerini bir kalkan edinip Allah'ın yolundan alıkoydular. Onların yapmakta oldukları ne kötüdür!"},{"n":3,"t":"Bu durumun sebebi şudur: Onlar iman ettiler, sonra küfre saptılar da kalpleri üzerine mühür basıldı. Artık onlar incelikleri anlamazlar."},{"n":4,"t":"Onları gördüğünde gövdeleri hoşuna gider. Bir şey konuşsalar sözlerine kulak verirsin. Onlar birbirine dayandırılmış keresteler/Hint kumaşı giydirilmiş kütük parçaları gibidirler. Her bağırtıyı aleyhlerinde zannederler. Düşmandır onlar; sakın onlardan! Allah onları kahretsin! Nasıl da aldatıp döndürülüyorlar!"},{"n":5,"t":"Onlara, \"Hadi gelin, Allah resulü sizin için af dilesin!\" dendiğinde kafalarını öteye çevirirler. Ve sen onların böbürlenmiş bir halde dönüp gittiklerini görürsün."},{"n":6,"t":"Sen onlar için ha af dilemişsin ha dilememişsin. Aleyhlerindeki sonuç aynı kalacaktır. Allah onları asla affetmeyecektir. Çünkü Allah, sapıklar topluluğunu doğruya ve güzele iletmez."},{"n":7,"t":"Onlar: \"Allah resulünün yanındakilere infak edip bir şey vermeyin ki dağılıp gitsinler!\" diyen kişilerdir. Oysaki göklerin ve yerin hazineleri, Allah'ın tekelindedir. Ama münafıklar bunu anlamazlar."},{"n":8,"t":"Şöyle derler: \"Eğer Medine'ye dönersek, yemin olsun ki, itibarlı ve baskın olan, ezik ve zayıf olanı oradan çıkaracaktır!\" Güç ve itibar Allah'a, onun resulüne ve iman sahiplerine özgüdür. Ama münafıklar bunu bilmezler."},{"n":9,"t":"Ey iman edenler! Mallarınız ve çocuklarınız, sizi, Allah'ı anmaktan/Allah'ın zikri olan Kur'an'dan alıkoymasın! Böyle bir şey yapanlar, hüsrana uğramışların ta kendileridir."},{"n":10,"t":"Sizden birine ölüm gelip de, \"Ey Rabbim, yakın bir süreye kadar beni geciktirseydin de içtenliğimi belgelemek için birşeyler vererek iyilik ve barış sevenler olsaydım!\" demesinden önce, size rızık olarak verdiklerimizden dağıtın."},{"n":11,"t":"Allah, süresi gelmiş olan bir canı geriye asla bırakmaz! Ve Allah, yapıp etmekte olduklarınızı çok iyi haber almaktadır."}],[{"n":1,"t":"Göklerdekiler ve yerdekiler Allah'ı tespih ediyor. O'nundur mülk ve yönetim; O'nun içindir tüm övgüler. Her şeye gücü yetendir O."},{"n":2,"t":"O'dur sizi yaratan! Sizin bir kısmınız küfre sapmıştır, bir kısmınız iman etmiştir. Ve Allah, işleyip ürettiklerinizi çok iyi görmektedir."},{"n":3,"t":"Gökleri ve yeri hak olarak yarattı; sizi biçimlendirdi ve görünüşlerinizi güzel yaptı. Yalnız O'nadır dönüş."},{"n":4,"t":"O bilir, göklerde ne var, yerde ne var! Ve bilir sizin gizlediklerinizi de açıkladıklarınızı da. Allah, göğüslerin özünü çok iyi bilir."},{"n":5,"t":"Sizden önce küfre sapanların haberleri gelmedi mi size? Onlar, yapıp ettiklerinin vebalini tattılar. Ve onlar için korkunç bir azap vardır."},{"n":6,"t":"Bu böyledir. Çünkü resulleri onlara apaçık deliller getirip dururken onlar: \"Bir insan mı bize kılavuzluk edecek?!\" deyip küfre saptılar ve yüz çevirdiler. Ve Allah hiçbir şeye muhtaç olmadığını gösterdi. Allah, sınırsız zenginliğin, sonsuz övgülerin sahibidir."},{"n":7,"t":"Küfre sapanlar asla diriltilmeyeceklerini sandılar. De ki: \"Rabbime yemin ederim ki, sandığınız gibi değil! Yemin olsun ki, mutlaka diriltileceksiniz; yine Yemin olsun ki, yaptıklarınız size mutlaka haber verilecektir. Ve bu, Allah için çok kolaydır.\""},{"n":8,"t":"Artık Allah'a, onun resulüne ve size indirdiğimiz nura inanın. Allah, yapmakta olduklarınızı iyiden iyiye haber almaktadır."},{"n":9,"t":"\"Toplanma günü\" için sizi bir araya getirdiği gün, karşılıklı aldatış ve aldanışların ortaya çıktığı gündür. Kim Allah'a iman eder, barışa/hayra yönelik bir iş yaparsa Allah onun çirkinliklerini örter ve kendisini altından nehirler akan cennetlere, içlerinde sürekli kalmak üzere yerleştirir. İşte büyük başarı budur."},{"n":10,"t":"Küfre sapıp ayetlerimizi yalanlayanlara gelince, işte bunlar, içinde uzun süre kalacakları ateşin dostlarıdır. Ne kötü dönüş yeridir orası!"},{"n":11,"t":"Allah'ın izni olmadıkça hiçbir musibet gelip çatmaz. Kim Allah'a inanırsa Allah O'nun kalbini doğruya ve güzele kılavuzlar. Ve Allah her şeyi en iyi biçimde bilmektedir."},{"n":12,"t":"Allah'a itaat edin, resule de itaat edin. Eğer yüz çevirirseniz resulümüze düşen, apaçık bir tebliğden başkası değildir."},{"n":13,"t":"Allah! İlah yok O'ndan başka! Yalnız Allah'a güvenip dayanır iman sahipleri."},{"n":14,"t":"Ey iman edenler! Şu bir gerçek ki, eşlerinizin ve evlatlarınızın içinden size bir düşman vardır; onlara karşı dikkatli olun! Eğer affeder, ellerini tutar, hatalarını görmezden gelirseniz, kuşkusuz, Allah da affedici, merhamet edici olur."},{"n":15,"t":"Şu da bir gerçek ki, mallarınız ve çocuklarınız bir imtihan aracıdır. Allah'a gelince, onun katında büyük bir ödül vardır."},{"n":16,"t":"O halde, gücünüz ölçüsünde Allah'tan sakının, dinleyin, itaat edin. Ve benlikleriniz için bir hayır olarak infakta bulunun. Nefsinin cimrilik ve doymazlığından korunanlar, kurtuluşa erenlerin ta kendileridir."},{"n":17,"t":"Eğer Allah'a gönül hoşluğuyla bir şey borç verirseniz O, onu sizin için katlayarak artırır ve sizin hatalarınızı bağışlar. Allah Şekûr'dur, şükredenlere karşılık verir; Halîm'dir, yumuşak ve merhametli davranır."},{"n":18,"t":"Görünmeyen ve görünen âlemleri bilendir O; Azîz'dir, Hakîm'dir."}],[{"n":1,"t":"Ey Peygamber! Kadınları boşadığınız zaman iddetlerine doğru boşayın ve iddeti iyi sayın! Rabbiniz olan Allah'tan sakının! Onları evlerinden çıkarmayın; onlar da çıkmasınlar. Apaçık ve belgeli bir yüzsüzlük yapmaları durumu müstesna. İşte bunlar Allah'ın sınırlarıdır. Allah'ın sınırlarını çiğneyen kendi benliğine zulmetmiş olur. Bilemezsin, belki Allah bundan sonra yeni bir iş/oluş ortaya çıkarır."},{"n":2,"t":"Sürelerini doldurma noktasına geldiklerinde o kadınları ya örfün gerektirdiği biçimde tutun yahut da yine örfün gerektirdiği şartlarla onlardan ayrılın. İçinizden adalet sahibi iki kişiyi de tanık tutun. Tanıklığı Allah için tam bir biçimde yapın. Allah'a ve âhiret gününe inanan kişiye işte bu şekilde öğüt verilmektedir. Kim Allah'tan sakınırsa, Allah ona bir çıkış yolu nasip eder."},{"n":3,"t":"Ve onu hiç beklemediği yönden rızıklandırır. Kim Allah'a dayanıp güvenirse O, ona yeter! Hiç kuşkusuz, Allah, emrini yerine getirecektir. Allah her şey için bir ölçü/bir kader belirlemiştir."},{"n":4,"t":"Âdetten kesilen kadınlarınızın iddet bekleme sürelerinde kuşkuya düşerseniz, onların iddetleri üç aydır. Hiç âdet görmemiş kadınların süreleri de böyledir. Gebe olan kadınların süreleri ise yüklerini bırakmalarına kadardır. Kim Allah'tan sakınırsa, O ona işinde bir kolaylık nasip eder."},{"n":5,"t":"İşte bu, Allah'ın size indirmiş olduğu emridir. Kim Allah'tan sakınırsa O, onun çirkinliklerini örter ve onun ödülünü büyütür."},{"n":6,"t":"Onları, gücünüz ölçüsünde, oturduğunuz yerin bir kısmında oturtun. Onları sıkıntıya sokmak için kendilerine zarar verme yoluna gitmeyin. Eğer hamile iseler, yüklerini bırakıncaya kadar nafakasını verin. Sizin hesabınıza emziriyorlarsa, ücretlerini de verin. Aranızda örfe uygun biçimde konuşup anlaşın. Eğer zorlanırsanız, o zaman çocuğu, baba hesabına başka bir kadın emzirecektir."},{"n":7,"t":"Geniş imkâna sahip olan bu geniş imkânından harcasın. Rızkı kendisine ölçü ile verilmiş olan da Allah'ın kendisine verdiğinden infak etsin. Allah hiçbir benliği, kendisine verdiği şey dışında yükümlü tutmaz. Allah, bir güçlükten sonra bir kolaylık yaratacaktır."},{"n":8,"t":"Nice kentler vardı ki, azgınlık edip Rabbinin ve onun resullerinin emrinden çıktılar da biz onları çok zorlu bir hesaba çektik ve onlara, görülmemiş bir azapla azap ettik."},{"n":9,"t":"Böylece onlar, yaptıklarının vebalini tattılar ve işlerinin sonu hüsran oldu."},{"n":10,"t":"Allah onlar için şiddetli bir azap hazırladı. Artık Allah'tan korkun, ey iman etmiş akıl ve gönül sahipleri! Allah size bir Zikir/bir uyarıcı/bir düşündürücü indirmiştir."},{"n":11,"t":"Bir elçi indirmiştir ki, iman edip barışa/hayra yönelik işler sergileyenleri, karanlıklardan nura çıkarmak için Allah'ın ayetlerini açık-seçik okur. Allah'a inanıp barışa/hayra yönelik bir iş yapanı Allah, altlarından ırmaklar akan cennetlere koyacaktır. Böyleleri, orada sürekli kalacaklardır. Allah böylesi için rızkı gerçekten güzelleştirmiştir."},{"n":12,"t":"Allah O'dur ki, yedi göğü ve yerden de onların benzerini yaratmıştır. Emir/iş ve oluş onlar arasında sürekli iner ki, Allah'ın her şeye kadir olduğunu ve Allah'ın bilgi bakımından her şeyi kuşattığını bilesiniz."}],[{"n":1,"t":"Ey Peygamber! Allah'ın sana helal kıldığı şeyi, eşlerinin hoşnutluğunu isteyerek neden haramlaştırıyorsun? Allah Gafûr'dur, Rahîm'dir."},{"n":2,"t":"Allah size, yeminlerinizi çözmeyi farz kılmıştır. Ve Allah, sizin Mevlâ'nızdır. Alîm'dir O, her şeyi bilir; Hakîm'dir O, hikmetleri sonsuzdur."},{"n":3,"t":"Hani, Peygamber, eşlerinden birine bir sözü gizlice söylemişti. Sonra eşi bu sözü duyurup Allah da onu Peygamber'e bildirince, Peygamber sözün bir kısmını açıklamış, bir kısmından vazgeçmişti. Peygamber, sözü eşine bildirdiğinde o: \"Bunu sana kim haber verdi?\" demişti. Peygamber de: \"O her şeyi bilen, her şeyden haberi olan bana bildirdi.\" diye cevaplamıştı."},{"n":4,"t":"Eğer ikiniz, ey hanımlar, Allah'a tövbe ederseniz ne iyi, çünkü kalpleriniz kaydı; yok eğer Peygamber'e karşı dayanışmaya girerseniz hiç kuşkusuz bizzat Allah, onun destekçisidir. Cebrail'le iman sahiplerinin iyilik severleri/ barışçıları da. Bütün bunlardan sonra melekler de ona arka çıkarlar."},{"n":5,"t":"O sizi boşarsa, kim bilir belki de Rabbi ona sizin yerinize sizden daha hayırlı eşler nasip eder: Allah'a teslim olan, iman sahibi, gönülden bağlı, tövbe etmesini seven, ibadete düşkün, yolculuk edebilen dullar ve bâkireler."},{"n":6,"t":"Ey iman sahipleri! Kendilerinizi ve ailelerinizi öyle bir ateşten koruyun ki, yakıtı insanlarla taşlardır. O ateşin başında çok katı, çok sert melekler vardır. Onlar, kendilerine emir verdiği konuda Allah'a isyan etmezler ve emredildikleri şeyi yaparlar."},{"n":7,"t":"Ey küfre sapanlar! Özür dilemeyin bugün! Çünkü siz yapıp ettiklerinizin karşılığı olarak cezalandırılıyorsunuz."},{"n":8,"t":"Ey iman edenler! Etkili öğüt veren bir tövbe ile Allah'a yönelin. Umulur ki Rabbiniz, çirkinliklerinizi ve günahlarınızı örter ve sizi altlarından ırmaklar akan cennetlere yerleştirir. O gün Allah, peygamberi ve onunla birlikte inananları utandırmayacaktır. Onların ışığı önlerinden ve sağ yanlarından koşup gelir. Şöyle derler: \"Ey Rabbimiz! Işığımızı tamamla ve bizi bağışla! Sen her şeye Kadîr'sin, her şeye gücün yeter.\""},{"n":9,"t":"Ey Peygamber! Küfre sapanlarla ve münafıklarla mücadele et ve onlara karşı sert davran! Varacakları yer cehennemdir onların. Ne kötü dönüş yeridir o!"},{"n":10,"t":"Allah, küfre sapanlarla ilgili olarak Nûh'un karısı ile Lût'un karısını örnek verdi. Bu ikisi, kullarımızdan iki barışçı kulun nikâhı altında idiler, onlara hıyanet ettiler de eşleri, Allah'tan onlara gelecek olanı hiçbir şeyle geri çeviremediler. Şöyle dendi onlara: \"Girin ateşe diğer gireceklerle birlikte!\""},{"n":11,"t":"Allah, iman edenlerle ilgili olarak da Firavun'un karısını örnek verdi. Hani, o şöyle demişti: \"Ey Rabbim! Benim için katında, cennette bir barınak yap; beni, Firavun'dan, onun yapıp ettiğinden kurtar; beni zulme sapmış topluluktan da kurtar.\""},{"n":12,"t":"Ve Allah, ırzını bir kale gibi koruyan İmran kızı Meryem'i de örnek verdi. Biz onun içine ruhumuzdan üfledik. Ve o, Rabbinin kelimelerini ve kitaplarını tasdikledi de içten bağlananlardan oldu."}],[{"n":1,"t":"Mülk ve yönetim elinde bulunan o Allah ne yücedir! O, her şeye Kadîr'dir."},{"n":2,"t":"Hanginizin daha güzel iş yapacağını belirlemek için sizi imtihana çekmek üzere ölümü ve hayatı yaratan O'dur. Azîz'dir O, Gafûr'dur."},{"n":3,"t":"Birbiriyle uyum ve ahenk içinde yedi gökleri yaratan da O'dur. O Rahman'ın yaratışında/yarattıklarında herhangi bir uyuşmazlık, aykırılık, çelişme göremezsin. Bir kez daha bak! Bir çatlaklık, bir uyuşmazlık görüyor musun?"},{"n":4,"t":"Sonra bakışı iki kez daha döndür. Bakış sana, bitkin ve gözü arkada kalmış/umudunu kesmiş olarak geri dönecektir."},{"n":5,"t":"Yemin olsun ki, biz en yakın göğü kandillerle süsledik ve onları şeytanlara ateş taneleri yaptık. O şeytanlar için çılgın ateş azabını da hazırladık."},{"n":6,"t":"Ve Rablerine karşı nankörlük edenler için cehennem azabı vardır. Ne kötü bir dönüş yeridir o!"},{"n":7,"t":"Onun içine atıldıklarında, onun derinden gelen sesini işitirler. Feveran etmektedir o."},{"n":8,"t":"Öfkesinden çatlayacak hale gelir. İçine bir güruh atıldıkça, onun bekçileri bunlara sorarlar: \"Size hiçbir uyarıcı gelmedi mi?\""},{"n":9,"t":"Derler ki: \"Gelmedi olur mu? Bize uyarıcı geldi. Fakat biz yalanladık. Ve: 'Allah bir şey indirmemiştir, siz büyük bir sapıklık içindesiniz, başka değil!' şeklinde konuştuk.\""},{"n":10,"t":"Ve derler ki: \"Eğer söz dinleseydik yahut aklımızı çalıştırsaydık şu çılgın ateşin dostları arasında olmazdık.\""},{"n":11,"t":"Günahlarını işte böyle itiraf ettiler. Çılgın ateşin halkına böyle kahır yaraşır."},{"n":12,"t":"Görmedikleri halde Rablerinden ürperenlere gelince, onlar için bir bağışlanma ve büyük bir ödül vardır."},{"n":13,"t":"Sözünüzü ister gizleyin ister onu açıklayın; şu bir gerçek ki O, göğüslerin özünü çok iyi bilir."},{"n":14,"t":"Yaratmış olan bilmez mi/Allah, yarattığı kimseyi bilmez mi? Latîf'tir O, Habîr'dir."},{"n":15,"t":"O, yeri sizin için boyun eğer yaptı. Haydi, onun omuzlarında yürüyün ve Allah'ın rızıklarından yiyin. Dönüş O'nadır."},{"n":16,"t":"O göktekinin, sizi yere batırmayacağından emin misiniz? O zaman yer aniden çalkalanmaya başlar."},{"n":17,"t":"O göktekinin, çakıl taşları taşıyan bir rüzgârı üzerinize salmayacağından emin misiniz? O zaman bileceksiniz nasılmış uyarım!"},{"n":18,"t":"Yemin olsun, onlardan öncekiler de yalanlamışlardı. Ama nasıl olmuştu benim azabım?!"},{"n":19,"t":"Üstlerinde kanat çırpan, kanatlarını aça-kapa uçan kuşları görmediler mi? Onları Rahmân'dan başkası tutmuyor. Şüphesiz O, her şeyi görmektedir."},{"n":20,"t":"Rahman'a karşı/Rahman'dan başka size yardım edecek ordunuz kimdir? İnkârcılar bir aldanış/gurur içindeler; hepsi bu!"},{"n":21,"t":"Peki, O, rızkını tutarsa kim var sizi rızıklandıracak? Hayır, bir azgınlık ve nefret içinde inat etmekteler."},{"n":22,"t":"Peki, yüzüstü kapanarak yürüyen mi daha düzgün gider yoksa dosdoğru yol üzerinde dik ve düzgün yürüyen mi?"},{"n":23,"t":"De ki: \"Sizi oluşturan O'dur. O size, işitme gücü, gözler ve gönüller verdi. Ne kadar da az şükrediyorsunuz!\""},{"n":24,"t":"De ki: \"Sizi, yeryüzünde yaratıp yayan O'dur. O'nun huzurunda haşredileceksiniz.\""},{"n":25,"t":"Derler ki: \"Eğer doğru sözlülerseniz, bu vaat de zaman?\""},{"n":26,"t":"De ki: \"Bilgi Allah'ın katındadır. Bana gelince, ben ancak açıkça uyaran biriyim.\""},{"n":27,"t":"Onu yakından gördüklerinde, inkâr edenlerin yüzleri kötüleşti. Şöyle denildi: \"O habire çağırıp durduğunuz şey budur.\""},{"n":28,"t":"De ki: \"Söyleyin bakalım: Eğer Allah beni ve benimle beraber olanları mahvetse yahut bize acısa, peki kâfirleri acıklı bir azaptan kim kurtaracak?\""},{"n":29,"t":"De ki: \"Rahman'dır O, O'na inandık biz ve yalnız O'na güvendik. Yakında bileceksiniz kimmiş apaçık sapıklığın içinde.\""},{"n":30,"t":"Şunu da söyle: \"Bir sabah suyunuz çekiliverse, kim getirecek fışkırıp akan bir su size?\""}],[{"n":1,"t":"Nûn! Yemin olsun kaleme ve satır satır yazdıklarına!"},{"n":2,"t":"Ki sen, cin tasallutuna uğramış değilsin; Rabbinin nimeti sayesinde,"},{"n":3,"t":"Senin için kesintisiz bir ödül var."},{"n":4,"t":"Ve gerçekten sen, çok büyük bir ahlak üzerindesin."},{"n":5,"t":"Yakında göreceksin, onlar da görecekler,"},{"n":6,"t":"Hanginizmiş fitneye tutulan, deliren!"},{"n":7,"t":"Senin Rabbin, evet O'dur kendi yolundan kimin saptığını en iyi bilen. Ve O'dur kimin doğruya ve güzele kılavuzlandığını en iyi bilen."},{"n":8,"t":"O halde, yalanlayanlara itaat etme!"},{"n":9,"t":"İstediler ki sen, alttan alıp gevşek davranasın/yağcılık edesin de onlar da yağcılık etsinler/yumuşaklık göstersinler."},{"n":10,"t":"Şunların hiçbirine eğilme, uyma: Çok yemin eden, bayağı-alçak,"},{"n":11,"t":"Alaycı/gammaz, koğuculuk için dolaşıp duran,"},{"n":12,"t":"Hayrı engelleyen, sınır tanımaz-saldırgan, günaha batmış,"},{"n":13,"t":"Kaba/obur, bütün bunlardan sonra da soyu bozuk, kötülükle damgalı."},{"n":14,"t":"Mal ve oğullar sahibi olmuş da ne olmuş?"},{"n":15,"t":"Ayetlerimiz ona okunduğunda şöyle der: \"Daha öncekilerin masalları!\""},{"n":16,"t":"Yakında biz onun hortumu üzerine damga basacağız/burnunu sürteceğiz."},{"n":17,"t":"Biz onları, o bahçe sahiplerini belalandırdığımız gibi belalandırdık. Hani, onlar sabaha çıktıklarında, bahçeyi mutlaka kesip biçeceklerine yemin etmişlerdi."},{"n":18,"t":"Hiçbir istisna tanımıyorlardı."},{"n":19,"t":"Ama onlar uyumaktayken, Rabbinden gelen bir dolaşıcı bahçeyi dolaştı da,"},{"n":20,"t":"O, simsiyah kesiliverdi."},{"n":21,"t":"Sabaha çıktıklarında birbirlerine seslendiler:"},{"n":22,"t":"\"Hadi, eğer biçecekseniz ekininize erken gidin.\""},{"n":23,"t":"Yola koyuldular. Aralarında fısıldaşıyorlardı:"},{"n":24,"t":"\"Hey! Bugün oraya bir yoksul girip yanınıza gelmesin!\""},{"n":25,"t":"Sadece engellemeye, şiddete güçleri yeten kişiler olarak erkenden vardılar."},{"n":26,"t":"Fakat bahçeyi görünce: \"Yahu, biz yanlış gelmişiz.\" dediler!"},{"n":27,"t":"\"Hayır, hayır! Biz mahrum edilenleriz.\""},{"n":28,"t":"Ortancaları/ılımlı olanı şöyle dedi: \"Ben size söylemedim mi? Tespih etseydiniz ya!\""},{"n":29,"t":"O zaman dediler ki: \"Tespih ederiz seni, ey Rabbimiz! Gerçekten biz zalimler olduk.\""},{"n":30,"t":"Bunun üzerine birbirlerini kınamaya başladılar."},{"n":31,"t":"\"Yazıklar olsun bize, dediler, biz gerçekten azgınlarmışız!\""},{"n":32,"t":"\"Umarız, Rabbimiz bize onun yerine daha hayırlısını verir. Biz de her şeyimizle Rabbimize yöneliriz.\""},{"n":33,"t":"İşte böyledir azap! Âhiretin azabı ise gerçekten çok daha büyüktür. Bir bilselerdi!"},{"n":34,"t":"Takva sahipleri için, Rableri katında nimetlerle dolu cennetler vardır."},{"n":35,"t":"Biz, Müslümanları/Allah'a teslim olanları, suçlular gibi yapar mıyız?"},{"n":36,"t":"Neniz var sizin, nasıl hüküm veriyorsunuz?"},{"n":37,"t":"Yoksa sizin bir kitabınız var da ondan ders mi görüyorsunuz?"},{"n":38,"t":"Onda, keyfinize uyan her şeyi rahatça buluyorsunuz."},{"n":39,"t":"Yoksa sizin lehinize üzerimizde kıyamete kadar uzanacak yeminler mi var da siz ne hükmederseniz oluverecek!"},{"n":40,"t":"Sor onlara: \"Böyle bir şeye hangisi kefil?\""},{"n":41,"t":"Yoksa kendilerinin ortakları mı var? Eğer doğru sözlüler iseler, çığırıversinler ortaklarını!"},{"n":42,"t":"Baldırın çıplak kalacağı, secdelere çağrılacakları gün, onu da yapamayacaklar."},{"n":43,"t":"Gözleri yere eğilmiş, benliklerini zillet kaplamıştır. Onlar, sapasağlam oldukları zaman da secde etmeye çağrılıyorlardı."},{"n":44,"t":"Bu sözü yalanlayanla beni baş başa bırak. Onları, bilmedikleri yerden yakalayacağız."},{"n":45,"t":"Süre tanıyorum onlara. Tuzağım gerçekten zorludur benim."},{"n":46,"t":"Bir ücret mi istiyorsun kendilerinden de onlar, bir borç altında eziliyorlar!"},{"n":47,"t":"Yoksa gayb, yanlarında da onlar mı yazıyorlar?"},{"n":48,"t":"Artık, Rabbinin hüküm vermesi için sabret! Balığın dostu Yûnus gibi olma! Hani o, öfkelendirilmiş bir halde yakarmıştı."},{"n":49,"t":"Eğer ona, Rabbinden bir nimet ulaşmasaydı, horlanmış bir halde cascavlak bir yere atılırdı."},{"n":50,"t":"Fakat Rabbi onu seçilip yüceltti ve barışseverlerden yaptı."},{"n":51,"t":"O küfre sapanlar, Zikir'i/Kur'an'ı işittiklerinde az kalsın gözleriyle seni devireceklerdi. \"Bu tam bir cinlidir.\" diyorlardı."},{"n":52,"t":"Oysaki o Zikir/Kur'an âlemler için bir öğütten başka şey değildir."}],[{"n":1,"t":"el-Hâkka/geleceği kuşkusuz olan şey!"},{"n":2,"t":"Nedir o hâkka?"},{"n":3,"t":"O hâkkanın niteliğini sana bildiren nedir?"},{"n":4,"t":"Semûd ve Âd kâriayı/başa çarpan olayı yalanlamıştı."},{"n":5,"t":"Bunun üzerine Semûd, bir doğal felaket ile helâk edildi."},{"n":6,"t":"Âd ise gürleyen sesle gelen rüzgârlı bir fırtınayla mahvedildi."},{"n":7,"t":"Onu, onların üzerine yedi gece-sekiz gün hiç ara vermeden saldı. Topluluğu orada yerlere serilmiş görürsün. İçleri boşaltılmış hurma kütükleri gibidirler."},{"n":8,"t":"Onlardan geri kalan bir şey görüyor musun?"},{"n":9,"t":"Firavun da ondan öncekiler de altı üstüne gelmiş kentlerde aynı hataya vücut verdiler."},{"n":10,"t":"Rablerinin resulüne isyan ettiler de O da onları, şiddeti arttıkça artan bir yakalayışla yakaladı."},{"n":11,"t":"Su azıp köpürdüğünde, biz sizi o akıp gidende taşıdık,"},{"n":12,"t":"Ki onu size bir hatırlatıcı/düşündürücü yapalım ve kavrayabilen kulak kavrasın."},{"n":13,"t":"Sûra bir üfleyişle üflendiğinde,"},{"n":14,"t":"Yer ve dağlar yükletilip birbirine bir çarpılışla parça parça edildiğinde,"},{"n":15,"t":"İşte o gün, olması gereken olmuştur."},{"n":16,"t":"Gök yarılmıştır. O gün o, lime lime sarkmıştır."},{"n":17,"t":"Melek de onun kenarlarındadır. Rabbinin arşını, o gün onların üstündeki sekiz taşır."},{"n":18,"t":"O gün arz olunursunuz; hiçbir saklınız-gizliniz kalmaz."},{"n":19,"t":"Öz kitabı sağından verilen: \"İşte kitabım, okuyun!\" der."},{"n":20,"t":"\"Kendi hesabıma kavuşacağımı sezmiştim zaten.\""},{"n":21,"t":"Artık o, hoşnutluk veren bir yaşayış içindedir."},{"n":22,"t":"Yüksek bir bahçe içindedir."},{"n":23,"t":"Meyveleri/devşirilecekleri yakındır."},{"n":24,"t":"Geçmiş günlerde sunduklarınızın karşılığı olarak afiyetle yiyin, için."},{"n":25,"t":"Öz kitabı sol taraftan verilene gelince o şöyle der: \"Ah, ne olurdu, bana kitabım verilmeseydi!\""},{"n":26,"t":"\"Hesabımın ne olduğunu hiç bilmemiş olsaydım.\""},{"n":27,"t":"\"Ah, ne olurdu, iş bitmiş olsaydı!\""},{"n":28,"t":"\"Hiçbir işime yaramadı malım.\""},{"n":29,"t":"\"Sökülüp gitti benden saltanatım.\""},{"n":30,"t":"\"Tutun onu, derhal bağlayın onu!\""},{"n":31,"t":"\"Sonra cehenneme sallayın onu!\""},{"n":32,"t":"\"Sonra, boyu yetmiş arşın olan bir zincirde yollayın onu!\""},{"n":33,"t":"\"Çünkü o, yüce Allah'a inanmıyordu.\""},{"n":34,"t":"\"Yoksulu doyurmaya özendirmiyordu.\""},{"n":35,"t":"\"Bugün onun için burada bir sıcak dost yoktur.\""},{"n":36,"t":"\"Yıkananların atık sularından başka yemek de yoktur.\""},{"n":37,"t":"\"Ki o atık suyu sadece günahkârlar yer.\""},{"n":38,"t":"Hayır, sandıkları gibi değil! Yemin ederim gördüklerinize,"},{"n":39,"t":"Ve görmediklerinize!"},{"n":40,"t":"Ki o, çok soylu bir elçinin sözüdür."},{"n":41,"t":"Bir şairin sözü değildir o. Ne kadar da az inanıyorsunuz?"},{"n":42,"t":"Bir kâhinin sözü de değildir o. Ne kadar da az araştırıp düşünüyorsunuz?"},{"n":43,"t":"Âlemlerin Rabbi'nden bir indiriştir o."},{"n":44,"t":"Eğer bazı lafları bizim sözlerimiz diye ortaya sürseydi,"},{"n":45,"t":"Yemin olsun, ondan sağ elini koparırdık."},{"n":46,"t":"Sonra ondan can damarını mutlaka keserdik."},{"n":47,"t":"Sizin hiçbiriniz ona siper de olamazdınız."},{"n":48,"t":"Gerçek şu ki o, sakınanlar için tam bir uyarıcı ve düşündürücüdür."},{"n":49,"t":"Ve biz, içinizden onu yalanlayanların bulunduğunu kesinlikle biliyoruz."},{"n":50,"t":"Ve o, gerçeği örten nankörler/inkârcılar için tam bir hasrettir."},{"n":51,"t":"Ve o, kesin bilginin tam gerçeğidir."},{"n":52,"t":"Hadi artık, yüce Rabbinin adını tespih et!"}],[{"n":1,"t":"Soran birisi, geleceği kuşkusuz azabı sordu."},{"n":2,"t":"Küfre sapanlar içindir o. Yoktur onu savacak."},{"n":3,"t":"Yükselme boyutlarının/derecelerinin sahibi Allah'tandır o."},{"n":4,"t":"Melekler ve Rûh, miktarı elli bin yıl olan bir günde yükselirler O'na."},{"n":5,"t":"Artık güzel bir sabırla sabret!"},{"n":6,"t":"Onlar onu çok uzak görüyorlar."},{"n":7,"t":"Biz ise onu çok yakın görüyoruz."},{"n":8,"t":"O gün gök, erimiş bir maden gibi olur."},{"n":9,"t":"Dağlar, atılmış, renkli yün gibi olur."},{"n":10,"t":"En yakın dostlar birbirlerinin halini sormaz/bir dost bir dostundan bir şey isteyemez."},{"n":11,"t":"Birbirlerine gösterilirler. Suçlu, o günün azabından kurtulmak için oğullarını fidye vermeyi bile ister."},{"n":12,"t":"Eşini, kardeşini,"},{"n":13,"t":"Kendisini kucaklayıp barındıran ailesini."},{"n":14,"t":"Ve yeryüzündeki insanların tümünü fidye verip kendisini kurtarmayı ister."},{"n":15,"t":"Hayır, hayır! O, alevlenen bir ateştir."},{"n":16,"t":"Yakar-kavurur deriyi/koparıp götürür kolu-bacağı."},{"n":17,"t":"Çağırır, sırtını dönüp uzaklaşanı,"},{"n":18,"t":"Toplayıp kasada yığanı/depolayanı."},{"n":19,"t":"İşin gereği şu ki insan; aceleci/hırslı/sabırsız/ tahammülsüz yaratılmıştır."},{"n":20,"t":"Kendisine kötülük/hoşnutsuzluk dokununca basar bağırır."},{"n":21,"t":"Kendisine hayır ve nimet ulaşınca ondan başkalarının yararlanmasına engel olur."},{"n":22,"t":"Namazlarını/dualarını yerine getirenler müstesna."},{"n":23,"t":"Bunlar, namazlarında/dualarında süreklidirler."},{"n":24,"t":"Bunların mallarında belirli bir hak vardır:"},{"n":25,"t":"Yoksul ve yoksun için."},{"n":26,"t":"Bunlar, din gününü içtenlikle doğrularlar."},{"n":27,"t":"Bunlar, yalnız Rablerinin azabından ürperirler."},{"n":28,"t":"Gerçekten de Rablerinin azabı emin olunmayacak bir azaptır."},{"n":29,"t":"Bunlar, cinsiyet organlarını titizlikle korurlar."},{"n":30,"t":"Ancak onlar, eşleriyle, akitlerinin sahip olduğu şeyler konusunda kınanamazlar."},{"n":31,"t":"Kim bunun ötesini isterse, işte böyleleri sınırı aşanların ta kendileridir."},{"n":32,"t":"Bunlar, kendilerindeki emanetlere ve ahitlerine sadık kalırlar."},{"n":33,"t":"Bunlar, tanıklıklarını tam yaparlar."},{"n":34,"t":"Ve bunlar, namazlarını/dualarını korurlar."},{"n":35,"t":"İşte bunlar cennetlerde ikram göreceklerdir."},{"n":36,"t":"O nankörlere ne oluyor ki, sana doğru, o yandan, bu yandan boyunlarını uzatarak geliyorlar;"},{"n":37,"t":"Sağdan ve soldan parçalar halinde."},{"n":38,"t":"Onlardan herbiri nimet bahçesine konulacağını mı umuyor?"},{"n":39,"t":"Hayır, ummasınlar! Gerçek şu ki biz onları, bildikleri şeyden yarattık."},{"n":40,"t":"İş, onların sandığı gibi değil! Doğuların ve batıların Rabbine yemin olsun ki, biz gerçekten gücü yetenleriz;"},{"n":41,"t":"Onları kendilerinden daha üstün olanlarla değiştirmeye... Ve biz önüne geçilebilecekler değiliz."},{"n":42,"t":"Bırak onları! Dalsınlar, oynasınlar kendileri için belirlenen günlerine ulaşıncaya kadar."},{"n":43,"t":"O gün, kabirlerden fırlayarak çıkarlar. Dikilmiş putlara doğru akın akın gider gibidirler."},{"n":44,"t":"Gözleri yere eğik; bir zillet kuşatmıştır onları. İşte bu gündür onlara vaat edilmiş olan."}],[{"n":1,"t":"Biz, Nûh'u, \"Toplumunu, kendilerine korkunç bir azap gelmeden önce uyar!\" diye kavmine gönderdik."},{"n":2,"t":"O dedi ki: \"Ey toplumum! Hiç kuşkunuz olmasın, ben sizin için apaçık bir uyarıcıyım.\""},{"n":3,"t":"\"O halde, Allah'a ibadet edin! O'ndan korkun! Ve bana itaat edin ki,"},{"n":4,"t":"Allah, günahlarınızı affetsin ve sizi belirli bir süreye kadar ertelesin. Çünkü Allah'ın eceli geldiğinde ertelenmez. Bir bilebilseydiniz!\""},{"n":5,"t":"Nûh şöyle yakardı: \"Ey Rabbim! Ben toplumuma gece ve gündüz çağrıda bulundum.\""},{"n":6,"t":"\"Fakat çağrım, onların kaçışlarını artırmaktan başka bir işe yaramadı.\""},{"n":7,"t":"\"Ben onları, sen kendilerini affedesin diye çağırdıkça, parmaklarını kulaklarına tıkadılar, elbiseleriyle sarılıp sarmalandılar, inat ve ısrar ettiler ve kibirlendikçe kibirlendiler.\""},{"n":8,"t":"\"Sonra onları daha açık bir biçimde çağırdım.\""},{"n":9,"t":"\"Daha sonra bir başka duyuru yönelttim. Ve onları gizli gizli de çağırdım.\""},{"n":10,"t":"Ve şöyle dedim: \"Rabbinizden af dileyin! O, bağışlamayı çok sevendir.\""},{"n":11,"t":"\"Göğü üzerinize bol bol yağmur taşıyıcı olarak gönderir.\""},{"n":12,"t":"\"Sizi, mallar ve oğullarla güçlendirir, size yeşil bahçeler lütfeder. Ve sizin için nehirler akıtır.\""},{"n":13,"t":"Size ne oluyor da Allah için bir azamet/ağırlık ummuyorsunuz?"},{"n":14,"t":"\"O ki, sizi halden hale/evreden evreye geçirerek yarattı.\""},{"n":15,"t":"\"Görmediniz mi, Allah yedi göğü ahenkli bir bütün olarak nasıl yarattı?\""},{"n":16,"t":"\"Ve Ay'ı, bunlar içinde bir nur yaptı ve Güneş'i bir kandil haline getirdi.\""},{"n":17,"t":"\"Ve Allah sizi bir bitki olarak yerden bitirdi.\""},{"n":18,"t":"\"Sonra sizi yere geri gönderiyor ve sonra bir çıkarışla tekrar çıkarıyor.\""},{"n":19,"t":"\"Allah size yeryüzünü bir yaygı yaptı,"},{"n":20,"t":"Ki ondan geniş yollar edinip de yürüyesiniz.\""},{"n":21,"t":"Nûh dedi ki: \"Rabbim! Onlar bana isyan ettiler de malı ve çocuğu kendisine hüsrandan başka bir artış getirmeyen kişiye uydular.\""},{"n":22,"t":"\"Çok büyük hileler sergilediler/çok büyük tuzaklar kurdular.\""},{"n":23,"t":"Dediler ki: \"İlahlarınızı sakın bırakmayın! Ved'di, Süva'ı asla bırakmayın! Yeğus'u, Yeuk'u, Nesr'i de bırakmayın!\""},{"n":24,"t":"\"Çoklarını saptırdılar. Sen de o zalimler için şaşkınlıktan başka bir şeyi artırma.\""},{"n":25,"t":"Hataları yüzündendir ki boğuldular, ateşe atıldılar. Kendileri için, Allah dışında yardımcılar bulamadılar."},{"n":26,"t":"Nûh şöyle yakardı: \"Rabbim! Yeryüzünde, kâfirlerden yurt tutacak/gezip dolaşacak hiç kimse bırakma!\""},{"n":27,"t":"\"Çünkü eğer sen onları bırakırsan, kullarını saptırırlar ve kötülük üreten nankörden başkasını doğurmazlar.\""},{"n":28,"t":"\"Rabbim! Beni, anne-babamı, inanmış olarak evime gireni, tüm inanmış erkekleri ve inanmış kadınları affet! Zalimlerin de sadece helâk ve perişanlığını artır!\""}],[{"n":1,"t":"De ki: \"Cinlerden bir topluluğun dinleyip şunu söyledikleri bana vahyolundu: 'Gerçekten biz, hayranlık verici bir Kur'an dinledik.\""},{"n":2,"t":"\"Doğruya ve hayra kılavuzluyor. Biz de inandık ona. Artık Rabbimize hiç kimseyi asla ortak koşmayacağız.\""},{"n":3,"t":"\"Rabbimizin adı/kudreti/işi/gayreti çok yücedir. O, ne bir dişi dost edinmiştir ne de bir çocuk.\""},{"n":4,"t":"\"Doğrusu, bizim beyinsiz, Allah hakkında saçma lakırdı ediyormuş.\""},{"n":5,"t":"\"Biz sanmıştık ki, ne insanlar ne de cinler Allah hakkında asla yalan söylemezler.\""},{"n":6,"t":"\"Gerçek şu ki, insanlardan bazı erkekler, cinlerden bazı erkeklere/cinlerin şerrinden bazı erkeklere sığınırlardı da onların şımarıklık ve azgınlığını artırırlardı.\""},{"n":7,"t":"\"Onlar, tıpkı sizin sandığınız gibi, Allah'ın hiç kimseyi asla diriltmeyeceğini/peygamber göndermeyeceğini sanmışlardı.\""},{"n":8,"t":"\"Biz göğe gerçekten dokunduk da onu titiz ve güçlü bekçilerle ve kayıp giden ışınlarla/alevlerle doldurulmuş bulduk.\""},{"n":9,"t":"\"Biz eskiden, onun, dinlemek için oturulan yerlerinde otururduk. Ama şu anda kim dinlemeye kalksa kendisini gözetleyen bir alev/ışık bulur.\""},{"n":10,"t":"\"Doğrusu, bilmiyoruz, yeryüzündeki şuurlulara şer mi istendi, yoksa Rableri onlar için doğru ve güzel olanı mı istemiştir.\""},{"n":11,"t":"\"Şu da bir gerçek ki, bizden hayra yönelenler/barışçılar vardır; ama bizden, başka türlü olanlar da vardır. Dilim dilim yollar olmuşuz biz.\""},{"n":12,"t":"\"Ve biz şunu sezdik: \"Biz yeryüzünde Allah'ı asla âciz bırakamayız; kaçarak da onu âciz bırakamayız.\""},{"n":13,"t":"\"Biz, doğruya ve güzele kılavuzlayanı dinleyince, ona inandık. Rabbine inanan kişi ne hakkının eksik verilmesinden korkar ne de tecavüze uğrayıp kuşatılmaktan.\""},{"n":14,"t":"\"Nihayet, bizden Allah'a teslim olanlar da var, haksızlığa sapıp çizgiden çıkanlar da var. Allah'a teslim olanlar, işte onlar, doğruyu ve hayrı aramışlardır."},{"n":15,"t":"\"Haksızlığa sapanlar ise cehenneme odun olmuşlardır.\""},{"n":16,"t":"Eğer yolda, kıvamında yürüselerdi, onları bol bir su ile suvarırdık,"},{"n":17,"t":"Ki onları, onun içinde imtihan edelim. Kim Rabbinin zikrinden/Kur'an'dan yüz çevirirse Rabbi onu, gittikçe yükselen bir azaba sokar."},{"n":18,"t":"Hiç kuşkusuz, mescitler/secdeler Allah içindir. O halde, Allah ile birlikte bir başkasına yakarmayın/Allah'ın yanında bir başkası için çağrıda bulunmayın."},{"n":19,"t":"Allah'ın kulu kalkmış O'na yakarırken, onlar onun üzerine keçeleşir gibi üşüşüyorlardı."},{"n":20,"t":"De ki: \"Ben ancak Rabbime yakarırım/çağırırım. Ve hiç kimseyi O'na ortak koşmam.\""},{"n":21,"t":"De ki: \"Ben size zarar verme gücüne de ışık ve aydınlık verme gücüne de sahip değilim.\""},{"n":22,"t":"De ki: \"Allah'tan beni hiç kimse kurtaramaz ve O'nun dışında bir sığınak da asla bulamam!\""},{"n":23,"t":"\"Ancak Allah'tan bir tebliğ ve O'nun mesajlarından bir şeyler sunabilirim.\" Allah'a ve O'nun resulüne isyan edenler için cehennem ateşi vardır. Uzun süre orada kalacaklardır."},{"n":24,"t":"Sonunda, onlar kendilerine vaat edileni gördüklerinde, yardımcı bakımından daha zayıf kim, sayı bakımından daha az kim, bileceklerdir."},{"n":25,"t":"De ki: \"Bilmiyorum, size vaat edilen şey yakın mıdır yoksa Rabbim onun için uzun bir süre mi koyacaktır?\""},{"n":26,"t":"Gaybı bilendir O. Gaybı konusunda hiç kimseyi yardımcı yapmıyor."},{"n":27,"t":"Seçtiği bir elçi müstesna. Çünkü O, resulünün önünden ve arkasından gözetleyiciler yürütür."},{"n":28,"t":"Ki onların, Rablerinin elçiliklerini hedefine tam ulaştırdıklarını bilsin. Allah, onların katında bulunan şeyleri kuşatmış ve her şeyi inceden inceye sayıya bağlamıştır."}],[{"n":1,"t":"Ey giysisine bürünüp yatan!"},{"n":2,"t":"Geceleyin kalk! Kısa bir süre hariç,"},{"n":3,"t":"Gecenin yarısını ayakta ol yahut bundan biraz eksilt!"},{"n":4,"t":"Yahut buna biraz ekle! Ve Kur'an'ı ağır ağır, düşüne düşüne oku!"},{"n":5,"t":"Doğrusu, biz senin üzerine ağır bir söz bırakacağız."},{"n":6,"t":"Şu bir gerçek ki, yeni bir oluşa koyulmak üzere geceleyin kalkan, yer tutma bakımından daha güçlü, söz bakımından daha etkilidir."},{"n":7,"t":"Kuşkusuz, gündüz boyu senin için uzun bir dolaşma/yoğun bir uğraş vardır."},{"n":8,"t":"Rabbinin adını an ve tüm benliğinle O'na yönel!"},{"n":9,"t":"Doğunun ve batının Rabbidir O. Tanrı yoktur O'ndan başka. O'nu vekil et!"},{"n":10,"t":"Onların söylediklerine sabret! Ve güzelce ayrıl onlardan."},{"n":11,"t":"Benimle, o nimete boğulmuş yalanlayıcıları baş başa bırak! Birazcık süre tanı onlara."},{"n":12,"t":"Bizim yanımızda bukağılar var, cehennem var!"},{"n":13,"t":"Boğazdan zor geçen bir yiyecek, korkunç bir azap var,"},{"n":14,"t":"O günde ki yer ve dağlar sarsılır ve dağlar eriyip akan bir kum yığınına dönüşür."},{"n":15,"t":"Biz size, üstünüze tanık olan bir resul gönderdik. Tıpkı Firavun'a bir resul gönderdiğimiz gibi."},{"n":16,"t":"Ama Firavun, resule isyan etti de biz onu korkunç bir tutuşla tutuverdik."},{"n":17,"t":"Eğer inkâr ve nankörlüğe saparsanız, çocukları ak saçlı ihtiyarlara çeviren o günden nasıl korunacaksınız?"},{"n":18,"t":"Gök bile o yüzden parçalanır. O'nun vaadi gerçekleşmiştir."},{"n":19,"t":"Bu, bir öğüt verici, düşündürücüdür. Dileyen, Rabbine doğru, bir yol edinir."},{"n":20,"t":"Hiç kuşkun olmasın, Rabbin senin durumunu biliyor. Gecenin üçte ikisinden daha azını, yarısını, üçte birini ayakta geçiriyorsun. Seninle beraber olanlardan bir grup da öyle. Allah, geceyi de gündüzü de ölçüye bağlamıştır. Sizin onu kuşatamayacağınızı bildi de size tövbe nasip etti. O halde Kur'an'dan, kolay geleni okuyun. Sizden hastalar olacağını bildi. Bir kısmının yeryüzünde dolaşıp Allah'ın lütfundan bir şeyler isteyeceklerini, diğer bir kısmının da Allah yolunda çarpışacaklarını bildi. O halde Kur'an'dan, kolay geleni okuyun! Namazı/duayı yerine getirin! Zekâtı verin. Güzel bir ödünçle Allah'a ödünç verin! Öz benlikleriniz için önden gönderdiğiniz iyiliğin, Allah katında hayrını daha çok, ödülünü daha büyük olarak bulacaksınız. Allah'tan af dileyin. Hiç kuşkusuz, Allah çok affedici, çok esirgeyicidir."}],[{"n":1,"t":"Ey giysisine bürünüp kenara çekilen!"},{"n":2,"t":"Kalk da uyar!"},{"n":3,"t":"Rabbinin yüceliğini duyur!"},{"n":4,"t":"Temizle giysilerini!"},{"n":5,"t":"Uzaklaştır kendinden pisliği!"},{"n":6,"t":"Çok bularak başa kakma yaptığın iyiliği!"},{"n":7,"t":"Ve yalnız Rabbin için dayanıklı kıl benliği!"},{"n":8,"t":"O boruya üfürüldüğünde,"},{"n":9,"t":"İşte o gün çok zorlu, çok çetin bir gündür."},{"n":10,"t":"Küfre batmışlar için hiç de kolay değildir."},{"n":11,"t":"Benimle, yarattığım kişiyi baş başa bırak!"},{"n":12,"t":"Hesapsız bir mal verdim ona."},{"n":13,"t":"Göz doyurucu oğullar verdim."},{"n":14,"t":"Alabildiğine imkânlar döşedim onun için."},{"n":15,"t":"Tüm bunlardan sonra hırs ile daha da artırmamı istiyor."},{"n":16,"t":"Hayır, iş sanıldığı gibi değil! O, bizim ayetlerimize karşı bir inatçı kesildi."},{"n":17,"t":"Ben onu dik bir yola süreceğim."},{"n":18,"t":"Derin derin düşündü o; ölçtü-biçti."},{"n":19,"t":"Kahrolası, nasıl bir ölçü kullandı!"},{"n":20,"t":"Bir kez daha kahrolası, nasıl bir ölçü kullandı?!"},{"n":21,"t":"Sonra baktı."},{"n":22,"t":"Sonra yüzünü buruşturdu, kaşlarını çattı."},{"n":23,"t":"Sonra arkasını döndü ve böbürlendi."},{"n":24,"t":"Şöyle dedi: \"Bu, rivayet edilerek gelen bir büyüden başka şey değil.\""},{"n":25,"t":"\"İnsan sözünden başka bir şey değil bu.\""},{"n":26,"t":"Onu sekara fırlatacağım."},{"n":27,"t":"Bilir misin nedir sekar?"},{"n":28,"t":"Ortada bir şey bırakmaz, hiçbir şeyi görmezlik etmez o."},{"n":29,"t":"İnsan için tablolar/levhalar/ekranlar sunandır o/deriyi yakıp kavurandır o."},{"n":30,"t":"Üzerinde ondokuz vardır onun."},{"n":31,"t":"Biz, cehennem yârânını hep melekler yaptık. Ve biz, onların sayılarını da küfre sapanlar için bir imtihandan başka şey yapmadık. Ta ki, kendilerine kitap verilenler iyice ve apaçık bilsinler. İman etmiş olanların imanı artsın. Kendilerine kitap verilmiş olanlarla iman sahipleri kuşkuya düşmesin. Kalplerinde hastalık olanlarla küfre sapmış bulunanlar da; \"Allah bununla neyi örneklendirmek istiyor?\" desinler. İşte böyle. Allah, dilediğini/dileyeni saptırır, dilediğini/dileyeni de doğruya ve güzele kılavuzlar. Rabbinin ordularını ancak O bilir. Bu, insan için bir öğüt verici ve düşündürücüden başka şey değildir."},{"n":32,"t":"Hayır, sandıkları gibi değil! Yemin olsun Ay'a,"},{"n":33,"t":"Yemin olsun geceye, sırtını döndüğünde;"},{"n":34,"t":"Yemin olsun sabaha, ağarıp ışıdığında,"},{"n":35,"t":"Ki o gerçekten en büyüklerden biridir."},{"n":36,"t":"İnsan için bir uyarıcıdır."},{"n":37,"t":"Sizden, öne geçmek yahut arkaya kalmak/erken davranmak yahut gecikmek isteyen için."},{"n":38,"t":"Her benlik kendi kazandığının bir karşılığıdır."},{"n":39,"t":"Uğur ve bereket yârânı müstesna."},{"n":40,"t":"Bahçelerdedirler. Birbirlerine soruyorlar,"},{"n":41,"t":"Suçlular hakkında:"},{"n":42,"t":"\"Sizi sekara sürükleyen nedir?\""},{"n":43,"t":"Cevap verdiler: \"Namazı/duayı yerine getirenlerden değildik.\""},{"n":44,"t":"\"Yoksulu yedirip doyurmuyorduk.\""},{"n":45,"t":"\"Boş lakırdılara dalanlarla dalar giderdik.\""},{"n":46,"t":"\"Din gününü yalanlıyorduk.\""},{"n":47,"t":"\"Nihayet, tartışılmaz ve karşı çıkılmaz bilgi önümüze dikildi.\""},{"n":48,"t":"Artık yarar sağlamaz onlara şefaatçilerin şefaati."},{"n":49,"t":"Ne oluyor onlara da öğüt verip düşündüren şeyden yüz çeviriyorlar?"},{"n":50,"t":"Sağa-sola kaçışan yaban eşekleri gibidirler,"},{"n":51,"t":"Arslandan ürkmüşlerdir."},{"n":52,"t":"İçlerinden her kişi de istiyor ki, kendisine açılıp saçılmış sayfalar verilsin."},{"n":53,"t":"Hayır, öyle şey olmaz! Doğrusu şu ki, âhiretten korkmuyorlar."},{"n":54,"t":"Hayır, iş, sandıkları gibi değil! O bir öğüt verici/bir düşündürücüdür."},{"n":55,"t":"Dileyen düşünür onu, öğüt alır."},{"n":56,"t":"Ve onlar, Allah'ın dilediği dışında, öğüt alamazlar. Sakındırmaya ve affetmeye ehil olan O'dur."}],[{"n":1,"t":"Hayır, öyle değil! Kıyamet gününe yemin ederim ki,"},{"n":2,"t":"Öyle değil! Kendisini ısrarla kınayan benliğe de yemin ederim."},{"n":3,"t":"İnsan, kendisinin kemiklerini asla bir araya toplamayacağımızı mı sanıyor?"},{"n":4,"t":"Hayır, sandığı gibi değil! Biz onun parmak uçlarını da tam bir biçimde düzenlemeye gücü yetenleriz."},{"n":5,"t":"Fakat insan kendi önünde rezillik sergilemeyi ister."},{"n":6,"t":"\"Kıyamet günü nerede/ne zaman?\" diye sorar."},{"n":7,"t":"Göz şimşek çaktığında,"},{"n":8,"t":"Ay tutulduğunda,"},{"n":9,"t":"Ve Güneş'le Ay biraraya getirildiğinde,"},{"n":10,"t":"Der ki insan o gün: \"Kaçılacak yer nerede?\""},{"n":11,"t":"Hayır, yok sığınacak yer!"},{"n":12,"t":"Varılıp durulacak yer Rabbinin huzurudur o gün."},{"n":13,"t":"Haber verilir insana o gün önden gönderdiği de arkaya bıraktığı da."},{"n":14,"t":"Gerçek şu ki insan, öz benliği üzerine yönelmiş keskin ve derin bir bakıştır;"},{"n":15,"t":"Dökse de ortaya tüm mazeretlerini."},{"n":16,"t":"Onu aceleye getiresin diye dilini onunla hareketlendirme!"},{"n":17,"t":"Onu toplamak ve okumak bize düşer."},{"n":18,"t":"O halde, biz onu okuduğumuzda, sen onun okunuşunu izle."},{"n":19,"t":"Sonra onu açıklamak da bizim işimiz olacaktır."},{"n":20,"t":"Hayır, hayır! Siz hemencecik geleni seversiniz."},{"n":21,"t":"Ve sonradan geleceği terk edersiniz."},{"n":22,"t":"Yüzler vardır o gün parıltılı,"},{"n":23,"t":"Rabbine doğru bakan."},{"n":24,"t":"Ve yüzler vardır o gün, asık/buruk,"},{"n":25,"t":"Kendisine, bel kıracak bir hesap yöneleceğini sezinler."},{"n":26,"t":"İş, onların sandığı gibi değil! Can, köprücüklere dayandığında,"},{"n":27,"t":"\"Kim var okuyup üfleyecek?\" denilir!"},{"n":28,"t":"Sezinlemiştir ki odur ayrılık."},{"n":29,"t":"Dolaşmıştır el-ayak/kol-bacak."},{"n":30,"t":"Rabbine doğrudur o gün sevkiyat."},{"n":31,"t":"Ne tasdik etti ne sadaka verdi ne namaz kıldı/dua etti."},{"n":32,"t":"Tam aksine, yalanladı, gerisin geri döndü."},{"n":33,"t":"Sonra da çalım sata sat ailesine gitti."},{"n":34,"t":"Çok uygundur sana bu bela, çok uygun!"},{"n":35,"t":"Evet, çok uygundur sana bu bela, çok uygun!"},{"n":36,"t":"İnsan, başıboş bırakılacağını mı sanıyor?"},{"n":37,"t":"O, dökülen meniden bir sperm değil miydi?"},{"n":38,"t":"Sonra o, bir çiğnem et oldu da Allah onu yarattı, ardından düzgün bir şekle ulaştırdı."},{"n":39,"t":"Nihayet ondan iki çifti, erkeği ve dişiyi vücuda getirdi."},{"n":40,"t":"Peki bunu yapan, ölüyü diriltmeye güç yetiremez mi?"}],[{"n":1,"t":"İnsan üzerinden, henüz anılan bir şey olmadığı bir süre geçmedi mi zamandan?"},{"n":2,"t":"Doğrusu, biz insanı karışım olan bir spermden yarattık. Halden hale geçiririz onu. Sonunda onu işitici, görücü yaptık."},{"n":3,"t":"Biz onu yola kılavuzladık. Artık ya şükredici olur ya nankör."},{"n":4,"t":"Biz, nankörler için zincirler, bukağılar ve kızgın bir ateş hazırladık."},{"n":5,"t":"İyilere gelince, onlar, karışımı kâfur olan bir kadehten içerler."},{"n":6,"t":"Bir kaynak ki, Allah'ın kulları ondan içerler ve onu fışkırtarak akıtırlar."},{"n":7,"t":"Onlar verdikleri sözü tam bir biçimde yerine getirirler ve kötülüğü salgın olan bir günden korkarlar."},{"n":8,"t":"Yoksula, yetime ve esire, yemeği severek yedirirler."},{"n":9,"t":"\"Biz size yalnız ve yalnız Allah rızası için yediriyoruz. Sizden bir karşılık da bir teşekkür de istemiyoruz;"},{"n":10,"t":"Çünkü biz, asık suratlı, sert bir gün yüzünden Rabbimizden korkarız.\" derler."},{"n":11,"t":"Allah da onları o gününün şerrinden korumuş ve kendilerini bir parlaklığa, bir sevince ulaştırmıştır."},{"n":12,"t":"Sabretmelerine karşılık olarak da onları bir bahçe ve ipekle ödüllendirmiştir."},{"n":13,"t":"Koltuklar üzerine yaslanarak otururlar orada. Ne bir güneş görürler orada ne de kavurucu bir soğuk..."},{"n":14,"t":"Bahçenin gölgeleri üzerlerine eğilmiştir. Ve bahçenin meyveleri iyice yaklaştırılmıştır."},{"n":15,"t":"Çevrelerinde, gümüşten ve billurdan kaplar dolaştırılır. Kupalardır onlar."},{"n":16,"t":"Gümüşten kupalar ki, tam diledikleri ölçüde belirlemişlerdir onları."},{"n":17,"t":"Orada kendilerine karışımı zencefil olan bir kadehten içirilir."},{"n":18,"t":"Bir pınar ki, orada, selsebil diye anılır."},{"n":19,"t":"Dolaşır çevrelerinde, sürekli görevlendirilmiş gençler. Görseydin onları, dizilmiş inciler sanırdın."},{"n":20,"t":"Oraya baktığında, nereye göz atsan büyük bir nimet, büyük bir mülk ve yönetim görürsün."},{"n":21,"t":"Üzerlerinde yeşil-ince ipeklerle, sırmalı, kalın ipeklerden giysiler vardır. Gümüşten bileziklerle süslenmişlerdir. Ve Rableri onlara tertemiz bir içki ikram etmiştir."},{"n":22,"t":"İşte bu size bir ödüldür. Ve sizin gayretiniz şükranla karşılanmıştır."},{"n":23,"t":"Biz indirdik o Kur'an'ı sana parça parça, biz!"},{"n":24,"t":"O halde, Rabbinin hükmü karşısında sabret ve onların günahkârlarına da nankörlerine de boyun eğme."},{"n":25,"t":"Rabbinin adını sabahtan da akşamdan da an!"},{"n":26,"t":"Gecenin bir kısmında da O'na secde et! Ve geceleyin O'nu uzunca tespih et/uzun bir gece boyu O'nu tespih et!"},{"n":27,"t":"Bunlar, hemen gelecek olanı seviyorlar da ötelerindeki zorlu bir günü ihmal ediyorlar."},{"n":28,"t":"Biz yarattık onları ve kuvvetli yaptık bağlarını/eklemlerini. Dilediğimizde benzerleri ile değiştiririz onları."},{"n":29,"t":"İşte bu, bir hatırlatıcı ve düşündürücüdür. Dileyen, Rabbine doğru, bir yol edinir."},{"n":30,"t":"Allah dilemedikçe siz dileyemezsiniz. Allah Alîm'dir, Hakîm'dir."},{"n":31,"t":"Dilediğini/dileyeni rahmetinin içine sokar. Zalimlere gelince, onlar için korkunç bir azap hazırlamıştır."}],[{"n":1,"t":"Yemin olsun, o art arda gönderilenlere/meleklere/rüzgârlara/vahyin bölümlerine/kalplere inen doğuşlara,"},{"n":2,"t":"Esip de büküp devirenlere,"},{"n":3,"t":"Dağıtıp yayanlara/diriltip harekete getirenlere,"},{"n":4,"t":"Gerektiği şekilde ayıranlara,"},{"n":5,"t":"Öğüt ulaştıranlara/Kur'an'ı ulaştıranlara,"},{"n":6,"t":"Özür yahut uyarı için,"},{"n":7,"t":"Ki size duyurulmuş olan mutlaka gerçekleşecektir."},{"n":8,"t":"Yıldızlar silinip süpürüldüğünde,"},{"n":9,"t":"Gök yarıldığında,"},{"n":10,"t":"Dağlar un-ufak edilip savrulduğunda,"},{"n":11,"t":"Resuller vakte bağlandığında,"},{"n":12,"t":"Hangi gün için vakte bağlandılar?"},{"n":13,"t":"Ayrım ve hüküm günü için."},{"n":14,"t":"Ayrım ve hüküm gününü sana bildiren nedir?"},{"n":15,"t":"Yalanlayanların vay haline o gün!"},{"n":16,"t":"Öncekileri helâk etmedik mi?"},{"n":17,"t":"Sonra, geriden gelenleri de onların peşlerine takarız."},{"n":18,"t":"Biz, suçlulara işte böyle yaparız."},{"n":19,"t":"Yalanlayanların o gün vay haline!"},{"n":20,"t":"Sizi basit bir sudan yaratmadık mı?"},{"n":21,"t":"Onu dayanıklı karargâhta tuttuk."},{"n":22,"t":"Bilinen bir ölçüye/süreye kadar."},{"n":23,"t":"Bir ölçüyle yaptık. Ne güzel ölçü koyanlarız biz!"},{"n":24,"t":"Vay başına o gün, yalanlayanların!"},{"n":25,"t":"Yeri, bir toplanma zemini yapmadık mı?"},{"n":26,"t":"Diriler bakımından da ölüler bakımından da."},{"n":27,"t":"Orada oturaklı, başını yücelere kaldırmış dağlar oluşturduk. Ve size tatlı bir su içirdik."},{"n":28,"t":"Vay haline o gün, yalanlayanların!"},{"n":29,"t":"Haydi, yalanlamakta olduğunuz şeye gidin!"},{"n":30,"t":"Haydi, üç çatallı gölgeye gidin!"},{"n":31,"t":"Ne gölgelendirir ne alevden korur."},{"n":32,"t":"Gerçekten o, köşke benzer kıvılcımlar saçar."},{"n":33,"t":"O kıvılcım sanki sarımtırak bir halat/bir deve kervanı/bakırdan bir ip gibidir."},{"n":34,"t":"Vay haline o gün, yalanlayanların!"},{"n":35,"t":"Konuşamayacakları gündür bu!"},{"n":36,"t":"İzin verilmez ki onlara özür dilesinler."},{"n":37,"t":"Vay haline o gün, yalanlayanların!"},{"n":38,"t":"Ayırma günüdür bu! Sizinle öncekileri bir yere topladık."},{"n":39,"t":"Eğer bir hileniz/bir tuzağınız varsa, hadi hile yapıp tuzak kurun bana!"},{"n":40,"t":"Vay haline o gün, yalanlayanların!"},{"n":41,"t":"Takvaya sarılanlar gölgeler altında, su kaynaklarındadır."},{"n":42,"t":"Canlarının çektiği meyvelerle yanyanadırlar."},{"n":43,"t":"\"Yapıp ürettiklerinize karşılık olarak afiyetle yiyip için.\""},{"n":44,"t":"İşte böyle ödüllendiririz biz, güzellikler sergileyenleri!"},{"n":45,"t":"Vay haline o gün, yalanlayanların!"},{"n":46,"t":"Yiyin ve birazcık nimetlenin. Suçlularsınız siz."},{"n":47,"t":"Vay haline o gün, yalanlayanların!"},{"n":48,"t":"Onlara, \"rukû' edin!\" dendiğinde rukû etmezler."},{"n":49,"t":"Vay haline o gün, yalanlayanların."},{"n":50,"t":"Artık bundan sonra hangi hadise/söze iman edecekler?"}],[{"n":1,"t":"Hangi şeyden sorup duruyorlar birbirlerine?"},{"n":2,"t":"O büyük haberden mi?"},{"n":3,"t":"Ki onda tartışma içindedirler."},{"n":4,"t":"Hayır, sandıkları gibi değil! Yakında bilecekler."},{"n":5,"t":"Hayır, hayır! Düşündükleri gibi değil, yakında bilecekler."},{"n":6,"t":"Biz bu yeryüzünü bir beşik yapmadık mı?"},{"n":7,"t":"Dağları birer kazık yapmadık mı?"},{"n":8,"t":"Sizleri çiftler olarak yarattık."},{"n":9,"t":"Sizin uykunuzu bir dinlenme/bir rahatlama/bir tür ölüm yaptık."},{"n":10,"t":"Geceyi bir giysi yaptık."},{"n":11,"t":"Gündüzü, geçim için çalışma zamanı yaptık."},{"n":12,"t":"Üstünüzde yedi sağlam/aşınmaz kurduk."},{"n":13,"t":"Bir de parıl parıl parlayan kandil yerleştirdik."},{"n":14,"t":"Sıkarak su çıkaranlardan şarıl şarıl bir su indirdik,"},{"n":15,"t":"Ki çıkaralım onlardan dâneler ve otlar;"},{"n":16,"t":"Ve iç içe girmiş bağlar-bahçeler."},{"n":17,"t":"Hiç kuşkusuz, o ayırma ve hüküm günü kesin olarak belirlenmiştir."},{"n":18,"t":"Sûra üfürüldüğü gün, bölükler halinde geleceksiniz."},{"n":19,"t":"Gök açılmış, kapı kapı oluvermiştir."},{"n":20,"t":"Dağlar yürütülmüş, bir serap oluvermiştir."},{"n":21,"t":"Cehennem, bir gözetleme yeri olmuştur."},{"n":22,"t":"Azgınlar için bir barınak."},{"n":23,"t":"Devirlerce kalacaklardır içinde."},{"n":24,"t":"Ne bir serinlik tadacaklar ne de bir içecek."},{"n":25,"t":"Sadece kaynar su, atık su,"},{"n":26,"t":"Çok uygun bir karşılık olarak."},{"n":27,"t":"Doğrusu onlar böyle bir hesap ummuyorlardı."},{"n":28,"t":"Ayetlerimizi pervasızca yalanlamışlardı."},{"n":29,"t":"Oysaki biz, her şeyi iyiden iyiye sayıp kitaplaştırmıştık."},{"n":30,"t":"\"Hadi, tadıverin! Size azaptan başka bir şey asla artırmayacağız.\""},{"n":31,"t":"Takva sahipleri için bir kurtuluş ve bir zafer vardır."},{"n":32,"t":"Sulak bahçeler, bağlar, üzümler,"},{"n":33,"t":"Göğüsleri turunç gibi yaşıtlar,"},{"n":34,"t":"Dopdolu kadehler vardır."},{"n":35,"t":"Orada ne bir boş söz duyarlar ne de bir yalan."},{"n":36,"t":"Rabbinden bir ödül, tam kıvamında bir bağış."},{"n":37,"t":"Göklerin, yerin ve bu ikisi arasındakilerin Rabbidir O! Rahman'dır. O'nun huzurunda söze cüret edemezler."},{"n":38,"t":"O gün, Rûh ve melekler saf bağlayıp kıyama geçerler. Rahman'ın izin verdiği dışındakiler konuşamazlar. O izin verilen, doğruyu söyler."},{"n":39,"t":"İşte budur hak olan gün! Artık dileyen, Rabbine varacak bir yol tutsun!"},{"n":40,"t":"Biz sizi yakın bir azap ile uyardık. Bir gündedir ki o, kişi kendi ellerinin önden gönderdiğine bakar ve küfre sapan şöyle der: \"Keşke toprak olsaydım!\""}],[{"n":1,"t":"Yemin olsun, çekip koparanlara/yay çekenlere/kuyudan su çekenlere/bağsız-bekçisiz koşan atlara/ayrılık yüzünden hasret çekenlere/daldırıp daldırıp çıkaranlara,"},{"n":2,"t":"Yemin olsun, rahatça, incitmeden çekenlere/düğümü hünerle çözenlere/bir yerden bir yere gidenlere/coşkuyla iç çekenlere,"},{"n":3,"t":"Yemin olsun, boşlukta yahut suda yüzüp gidenlere,"},{"n":4,"t":"Derken öne geçip yarışı kazananlara,"},{"n":5,"t":"Bir iş ve oluşu çekip çevirenlere,"},{"n":6,"t":"Ki o gün şiddetle sarsacak olan saracaktır."},{"n":7,"t":"Onu, ardısıra gelen izleyecektir."},{"n":8,"t":"Bazı kalpler o gün kaygıdan titreyecektir."},{"n":9,"t":"Onların gözleri yerlere eğilecektir."},{"n":10,"t":"\"Biz gerçekten bu çukurda eski halimize döndürülecek miyiz?\" diyorlar."},{"n":11,"t":"\"Un-ufak kemikler haline geldikten sonra, öyle mi!\""},{"n":12,"t":"\"Hüsran dolu bir dönüştür bu öyleyse!\" diye konuştular."},{"n":13,"t":"Oysaki o, sert bir komut sesinden ibarettir."},{"n":14,"t":"Bir anda hepsi uyanıp ortaya geliverir."},{"n":15,"t":"Ulaştı mı sana Mûsa'nın haberi?"},{"n":16,"t":"Hani, Rabbi ona, kutsal vadide, Tuva'da seslenmişti:"},{"n":17,"t":"\"Firavun'a git! İyice azdı o.\""},{"n":18,"t":"\"De ki ona: 'Arınıp temizlenmeye ne dersin?\""},{"n":19,"t":"\"Seni Rabbine kılavuzlayayım da gönülden ürperesin!\""},{"n":20,"t":"Derken, ona o en büyük mucizeyi gösterdi."},{"n":21,"t":"Ama o yalanladı, isyan etti."},{"n":22,"t":"Sonra, sırtını döndü; koşuyordu."},{"n":23,"t":"Derken, bir araya toplayıp bağırdı."},{"n":24,"t":"Dedi ki: \"Ben sizin en yüce rabbinizim.\""},{"n":25,"t":"Bunun üzerine Allah, onu sonraya ve önceye ibret olmak üzere bir ceza ile çarptı."},{"n":26,"t":"Kuşkusuz, bunda, içine ürperti düşen için tam bir ibret vardır."},{"n":27,"t":"Siz mi daha zorsunuz yaratılışça, gök mü?"},{"n":28,"t":"Onu O yapıp kurdu. Onun boyunu yükseltti; ardından ona ahenk ve düzen verdi."},{"n":29,"t":"Gecesini kararttı, kuşluğunu ortaya çıkardı."},{"n":30,"t":"Bundan sonra da yeri yayıp deve kuşu yumurtası biçiminde yuvarlattı."},{"n":31,"t":"Ondan suyunu, otlağını çıkardı."},{"n":32,"t":"Dağları, demir atmış gibi oturttu;"},{"n":33,"t":"Sizin için ve hayvanlarınız için bir geçim aracı olarak."},{"n":34,"t":"O güç yetmez büyük felaket geldiğinde,"},{"n":35,"t":"O gün insan, uğrunda gayret sarfettiği şeyi hatırlar."},{"n":36,"t":"Gören kişi için cehennem apaçık ortaya çıkarılmıştır."},{"n":37,"t":"Artık azmış olan,"},{"n":38,"t":"Ve iğreti hayatı yeğlemiş olan için,"},{"n":39,"t":"Cehennem, barınağın ta kendisidir."},{"n":40,"t":"Rabbinin yüceliğinden korkup nefsini boş heveslerden yasaklanmış olan içinse,"},{"n":41,"t":"Cennet, barınağın ta kendisidir."},{"n":42,"t":"O saatten soruyorlar sana, \"gelip demir atması ne zaman?\" diye."},{"n":43,"t":"Nerede sende, onu hatırlatacak şey!"},{"n":44,"t":"Ona ilişkin bilginin sonu Rabbine varır."},{"n":45,"t":"Sen sadece, ondan korkanları uyaransın."},{"n":46,"t":"Onu gördükleri gün onlar, dünyada sanki bir akşam veya onun kuşluk vaktinden başka kalmamışa dönerler."}],[{"n":1,"t":"Yüzünü ekşitti ve öteye döndü;"},{"n":2,"t":"Yanına kör adam geldi diye."},{"n":3,"t":"Nereden bilirsin, belki de o arınıp temizlenecek."},{"n":4,"t":"Belki de düşünüp taşınacak da öğüt kendisine yarayacak."},{"n":5,"t":"O, kendisini her türlü ihtiyacın üstünde görene gelince,"},{"n":6,"t":"Ki sen ona yöneliyorsun;"},{"n":7,"t":"Sana ne onun arınmasından!"},{"n":8,"t":"O, koşarak sana gelen var ya;"},{"n":9,"t":"Odur içine ürperti düşen."},{"n":10,"t":"Sen ona aldırmazlık ediyorsun."},{"n":11,"t":"Hayır, hiç de öyle değil! O, bir düşündürücüdür."},{"n":12,"t":"Dileyen onu düşünüp öğüt alır."},{"n":13,"t":"Kutsanan-bereketli sayfalardadır o."},{"n":14,"t":"Yüceltilen, tertemiz sayfalarda,"},{"n":15,"t":"Yazıcıların ellerinde;"},{"n":16,"t":"Ak-pak, mübarek yazıcıların."},{"n":17,"t":"Kahrolası insan, ne kadar da nankördür!"},{"n":18,"t":"Hangi şeyden yarattı onu?"},{"n":19,"t":"Bir spermden! Yarattı onu, ölçülendirip biçimlendirdi onu."},{"n":20,"t":"Sonra, yolu kolaylaştırdı ona,"},{"n":21,"t":"Sonra öldürdü onu, kabre koydurdu onu."},{"n":22,"t":"Sonra dilediği zaman diriltip ortaya çıkardı onu."},{"n":23,"t":"Hayır, hayır! O, O'nun kendisine emrettiğini hiç yerine getirmedi."},{"n":24,"t":"Hadi, bakıversin insan, kendi yiyeceğine!"},{"n":25,"t":"Biz suyu döktük de döktük."},{"n":26,"t":"Sonra yeryüzünü yardık da yardık."},{"n":27,"t":"Ardından orada dâneler bitirdik."},{"n":28,"t":"Üzümler, yoncalar,"},{"n":29,"t":"Zeytinlikler, hurmalıklar,"},{"n":30,"t":"Gür çimenli, bol ağaçlı bahçeler,"},{"n":31,"t":"Meyve, otlak/sebze."},{"n":32,"t":"Sizin ve hayvanlarınızın yararına."},{"n":33,"t":"Şiddetle çarpanın çıkardığı korkunç ses geldiğinde,"},{"n":34,"t":"Bir gün ki o, kişi öz kardeşinden kaçar,"},{"n":35,"t":"Öz annesinden, öz babasından,"},{"n":36,"t":"Eşinden, oğullarından."},{"n":37,"t":"O gün onlardan her kişinin kendisine yetecek bir uğraşı vardır."},{"n":38,"t":"Yüzler vardır o gün, pırıl pırıl,"},{"n":39,"t":"Gülen, müjdelerle parıldayan."},{"n":40,"t":"Ve yüzler vardır o gün toza-toprağa bulanmış."},{"n":41,"t":"Tozu-toprağı da bir is bürümüştür."},{"n":42,"t":"İşte bunlardır küfre sapanlar, kötülüğe batanlar."}],[{"n":1,"t":"Güneş büzülüp dürüldüğünde,"},{"n":2,"t":"Yıldızlar ışıklarını yitirdiğinde,"},{"n":3,"t":"Dağlar yürütüldüğünde,"},{"n":4,"t":"O bakmaya kıyılmayan develer kendi hallerine bırakıldığında,"},{"n":5,"t":"Vahşi hayvanlar bir araya toplandığında,"},{"n":6,"t":"Denizler kaynatıldığında,"},{"n":7,"t":"Benlikler çiftleştirildiğinde,"},{"n":8,"t":"O diri diri gömülen kız çocuğuna sorulduğunda,"},{"n":9,"t":"Hangi günah yüzünden öldürüldü diye!"},{"n":10,"t":"Sayfalar açılıp göz önüne konduğunda,"},{"n":11,"t":"Göğün örtüsü soyulup indirildiğinde,"},{"n":12,"t":"Cehennem kızıştırıldığında,"},{"n":13,"t":"Cennet yaklaştırıldığında,"},{"n":14,"t":"Her benlik, önceden ne hazırlamışsa bilmiş olacaktır."},{"n":15,"t":"Hayır, iş onların sandığı gibi değil! Yemin olsun o sinip gizlenenlere,"},{"n":16,"t":"Akıp akıp giderek yuvasına girenlere,"},{"n":17,"t":"Beriye geldiği ve geriye döndüğü zaman geceye,"},{"n":18,"t":"Ve soluyarak açıldığı zaman sabaha,"},{"n":19,"t":"Ki o, çok değerli bir elçinin sözüdür."},{"n":20,"t":"Çok güçlüdür o elçi, Arş sahibinin katında saygındır."},{"n":21,"t":"İtaat edilir orada kendisine, emindir."},{"n":22,"t":"Ve arkadaşınız bir cin çarpmış değildir."},{"n":23,"t":"Yemin olsun ki, onu apaçık ufukta gördü."},{"n":24,"t":"O, gayb konusunda cimri değildir."},{"n":25,"t":"Ve o, kovulmuş şeytanın sözü değildir."},{"n":26,"t":"Hal böyle iken nereye gidiyorsunuz?"},{"n":27,"t":"O, âlemlere bir öğütten başka şey değildir."},{"n":28,"t":"İçinizden, dosdoğru yürümek isteyen için."},{"n":29,"t":"Âlemlerin Rabbi olan Allah dilemedikçe, siz dileyemezsiniz!"}],[{"n":1,"t":"Gök çatlayıp yarıldığı zaman,"},{"n":2,"t":"Yıldızlar dökülüp saçıldığı zaman,"},{"n":3,"t":"Denizler fışkırtıldığı zaman,"},{"n":4,"t":"Kabirler deşildiği zaman,"},{"n":5,"t":"Benlik, bilmiş olacaktır önden gönderdiğini de arkaya bıraktığını da."},{"n":6,"t":"Ey insan! O sonsuz cömertliğin sahibi Kerîm Rabbine karşı seni aldatıp gururlu kılan nedir?!"},{"n":7,"t":"Rabbin ki seni yarattı, düzgün hale koydu, en güzel ölçülerle şekillendirdi."},{"n":8,"t":"Dilediği herhangi bir biçimde seni oluşturdu."},{"n":9,"t":"Hayır, iş sanıldığı gibi değil! Siz dini yalanlıyorsunuz."},{"n":10,"t":"Ve şu kuşkusuz ki, sizin üzerinizde koruyucular-bekçiler var."},{"n":11,"t":"Çok değerli yazıcılar,"},{"n":12,"t":"Bilirler yapmakta olduğunuzu."},{"n":13,"t":"Şu da kuşkusuz: İyiler tam bir nimet içindedir,"},{"n":14,"t":"Kötülerse cehennemin ta ortasında."},{"n":15,"t":"Din günü girerler oraya."},{"n":16,"t":"Onlar ondan, görülmeyecek şekilde uzaklaşmış değillerdir."},{"n":17,"t":"Din gününün ne olduğunu sana bildiren nedir?"},{"n":18,"t":"Evet, din gününün ne olduğunu sana bildiren nedir?"},{"n":19,"t":"Bir gündür ki o, bir benlik bir başka benlik için hiçbir şeye güç yetiremez. O gün, buyruk yalnız Allah'ındır!"}],[{"n":1,"t":"Azap ve kaygu, tartıda ve ölçüde hile yapanlara olsun;"},{"n":2,"t":"Ki onlar insanlardan alırken ölçüyü tam yaparlar,"},{"n":3,"t":"Onlara vermek üzere tartıp ölçtükleri zaman, eksiltmeye giderler."},{"n":4,"t":"Peki, bunlar kendilerinin diriltileceğini sanmıyorlar mı?"},{"n":5,"t":"Çok büyük bir gün için."},{"n":6,"t":"Bir gün ki, insanlar, âlemlerin Rabbi huzurunda kıyama geçerler."},{"n":7,"t":"Hayır, iş düşündükleri gibi değil! Rezilliğe batmışların kitabı, karanlık ve pis bir çukurun, Siccîn'in ta içindedir."},{"n":8,"t":"Siccîn'in ne olduğunu sana gösteren nedir?"},{"n":9,"t":"Rakamlandırılmış bir kitaptır o."},{"n":10,"t":"Vay haline o gün, yalanlayanların!"},{"n":11,"t":"Onlar ki din gününü yalanlarlar."},{"n":12,"t":"Onu ancak her şımarıp azmış, günaha batmış olan yalanlar."},{"n":13,"t":"Ayetlerimiz ona okunduğunda, \"Daha öncekilerin efsaneleri!\" deyiverir."},{"n":14,"t":"İşin esası o değil! Onların kazanmakta oldukları, kalplerinin üstünde pas oluşturmuştur."},{"n":15,"t":"Hayır! Onlar o gün Rablerine karşı tam bir şekilde perdelenmişlerdir."},{"n":16,"t":"Sonra onlar mutlaka cehenneme dalacaklardır."},{"n":17,"t":"Sonra da: \"İşte budur, o yalanlamakta olduğunuz şey!\" denilecektir."},{"n":18,"t":"Hayır, sandıkları gibi değil! İyilik sergileyenlerin kitabı İlliyyûn'da, en yüce burçlardadır."},{"n":19,"t":"İlliyyûn'un ne olduğunu sana anlatan nedir?"},{"n":20,"t":"Rakamlanmış bir kitaptır o."},{"n":21,"t":"Yaklaştırılmış olanlar tanıklık ederler ona."},{"n":22,"t":"İyilik sergileyenler büyük bir nimetin tam içindedir."},{"n":23,"t":"Koltuklar üzerinde seyre dalarlar."},{"n":24,"t":"Yüzlerinde nimetin sevinç parıltısını izlersin."},{"n":25,"t":"Katıksız, damgalı bir içecekten içirilirler,"},{"n":26,"t":"Ki sonu bir misktir. İşte, yarışanlar böyle bir şey için yarışsınlar!"},{"n":27,"t":"Onun katkısı Tesnîm'den; en yüce, en seçkin olandandır."},{"n":28,"t":"Bir kaynak ki, iyice yaklaştırılmış olanlar içerler ondan."},{"n":29,"t":"Şu bir gerçek ki, suça batmış olanlar, iman sahiplerine gülerlerdi."},{"n":30,"t":"Onların yanlarından geçerken birbirlerine kaş-göz işareti yaparlardı."},{"n":31,"t":"Ailelerine döndüklerinde, gülüp eğlenmeye koyulurlardı."},{"n":32,"t":"İnananları gördüklerinde: \"Şunlar var ya! Şaşkın, sapık bunlar!\" derlerdi."},{"n":33,"t":"Oysaki kendileri, inananlar üzerine bekçi gönderilmemişti."},{"n":34,"t":"İşte bugün, iman sahipleri, küfre batmışlara gülüyorlar."},{"n":35,"t":"Koltuklar üzerinde seyrediyorlar."},{"n":36,"t":"Nankör kâfirler, yapmış olduklarıyla ödüllendirildiler mi?"}],[{"n":1,"t":"Gök yarılıp parçalandığı,"},{"n":2,"t":"Ve Rabbini dinleyip de hakkın belirişine araç kılındığı zaman!"},{"n":3,"t":"Ve yer uzatıldığı,"},{"n":4,"t":"Ve içindekini atıp boşaldığı,"},{"n":5,"t":"Ve Rabbini dinleyip de hakkın belirişine araç kılındığı zaman!"},{"n":6,"t":"Ey insan, sen Rabbine varmak için çok didinecek, sonunda O'na kavuşacaksın!"},{"n":7,"t":"O zaman kitabı sağdan verilen,"},{"n":8,"t":"Kolay bir hesapla hesaba çekilecek,"},{"n":9,"t":"Ve sevinçli olarak ailesine dönecektir."},{"n":10,"t":"Kitabı arka tarafından verilen,"},{"n":11,"t":"Bir ölüm çağıracak,"},{"n":12,"t":"Ve korkunç ateşe girecektir."},{"n":13,"t":"O, ailesi içinde sevinçli idi."},{"n":14,"t":"Daha düşkün bir konuma asla geçmeyeceğini sanmıştı."},{"n":15,"t":"Hayır! Rabbi onu iyice görmekteydi."},{"n":16,"t":"İş, sandıkları gibi değil! Yemin ederim akşamın kızıllığına,"},{"n":17,"t":"Geceye ve derlediğine,"},{"n":18,"t":"Toparlandığı zaman Ay'a,"},{"n":19,"t":"Ki siz boyuttan boyuta/halden hale mutlaka geçeceksiniz."},{"n":20,"t":"Peki onlara ne oluyor da iman etmiyorlar?!"},{"n":21,"t":"Karşılarında Kur'an okunduğu zaman secde etmiyorlar."},{"n":22,"t":"Tam aksine, o küfre sapanlar yalanlıyorlar."},{"n":23,"t":"Allah, içlerinde sakladıklarını çok iyi biliyor."},{"n":24,"t":"O halde, onlara acıklı bir azap muştula!"},{"n":25,"t":"İman edip hayra ve barışa yönelik işler yapanlar müstesnadır. Onlar için kesintisiz bir ödül vardır."}],[{"n":1,"t":"Yemin olsun o burçlarla dolu göğe,"},{"n":2,"t":"O vaat olunan güne,"},{"n":3,"t":"Tanıklık edene, tanıklık edilene/seyredene, seyredilene,"},{"n":4,"t":"Ki gebertildi o hendekçi grup/o kamçıları hendek gibi iz bırakan herifler,"},{"n":5,"t":"O tutuşturulan ateşin adamları,"},{"n":6,"t":"Onlar onun başında oturmuşlardı."},{"n":7,"t":"Ve hepsi, müminlere yaptıklarını seyrediyorlardı."},{"n":8,"t":"Onlardan sadece, Azîz ve Hamîd Allah'a iman ettikleri için öc alıyorlardı."},{"n":9,"t":"O Allah ki, göklerin ve yerin mülkü kendisinindir. Allah her şeye tanıktır."},{"n":10,"t":"Şu bir gerçek ki, inanan erkeklerle inanan kadınlara işkence edip sonra da tövbe etmemiş olanlar için, cehennem azabı vardır. Onlar için yangın azabı da vardır."},{"n":11,"t":"İman edip hayra ve barışa yönelik işler yapanlara gelince onlar için, altlarından ırmaklar akan cennetler vardır. Büyük başarı işte budur."},{"n":12,"t":"Hiç kuşkusuz, Rabbinin yakalayışı/çarpışı çok şiddetlidir."},{"n":13,"t":"İlk yaratan da O'dur, tekrar yaratan da O'dur!!"},{"n":14,"t":"Gafûr O'dur, Vedûd O!"},{"n":15,"t":"Arşın sahibidir; Mecîd'dir, şanı yüce olandır!"},{"n":16,"t":"İstediğini hemen yapandır."},{"n":17,"t":"Geldi mi sana orduların haberi?"},{"n":18,"t":"Yani Firavun ve Semûd'un?"},{"n":19,"t":"Gerçek şu ki, inkâr edenler bir yalanlama içindedirler."},{"n":20,"t":"Allah ise onları arkalarından kuşatmış bulunuyor."},{"n":21,"t":"İş onların iddialarının aksinedir! O, çok yüce bir Kur'an'dır."},{"n":22,"t":"Korunmuş bir levhadadır / Levh-i Mahfuz'dadır."}],[{"n":1,"t":"Yemin olsun göğe ve Târık'a; o, gece gelene/o, tokmak gibi vurana/o, çıkıverip de yürek hoplatana."},{"n":2,"t":"Nereden bileceksin sen nedir Târık?"},{"n":3,"t":"Parlayan, ışığıyla karanlığı delen yıldızdır o."},{"n":4,"t":"Hiçbir benlik yoktur ki, üzerinde bir koruyucu/bir gözetleyici bulunmasın."},{"n":5,"t":"İnsan, neden yaratılmış olduğuna bir baksın!"},{"n":6,"t":"Fırlayan bir suyun bir parçacağından yaratıldı o."},{"n":7,"t":"Bel ile kaburgalar arasından çıkar o su."},{"n":8,"t":"O Allah, o insanı tekrar hayata döndürmeye elbette kadirdir."},{"n":9,"t":"Sırların/gizlilerin yoklanıp ortaya çıkarılacağı gün,"},{"n":10,"t":"Artık onun için ne bir kuvvet vardır ne de bir yardımcı."},{"n":11,"t":"Yemin olsun o, dönüşle/döndürümle dolu göğe,"},{"n":12,"t":"Çatlayışlarla/yarılışlarla dolu yere de yemin olsun,"},{"n":13,"t":"Ki o, tam bir biçimde ayırt eden bir sözdür;"},{"n":14,"t":"Şaka değildir o."},{"n":15,"t":"Onlar ha bire tuzak kuruyorlar/oyun çeviriyorlar."},{"n":16,"t":"Ben de tuzak kuruyorum."},{"n":17,"t":"O halde, o küfre batmışlara mühlet ver, süre tanı onlara birazcık..."}],[{"n":1,"t":"Rabbinin o Al'a, o yüce adını tespih et!"},{"n":2,"t":"O ki yarattı, düzene koydu,"},{"n":3,"t":"O ki miktarını, şeklini belirledi, yolunu çizip aydınlattı."},{"n":4,"t":"O ki otlağı çıkardı,"},{"n":5,"t":"Sonra da onu sellerin sürüklediği morarmış bir atık haline getirdi."},{"n":6,"t":"Seni/sana okutacağız da artık unutmayacaksın."},{"n":7,"t":"Allah'ın dilediği müstesna. O, açıklananı da gizleneni de bilir."},{"n":8,"t":"Sana, en kolay olanı kolaylaştıracağız."},{"n":9,"t":"Eğer hatırlatmak yarar sağlarsa hatırlat/öğüt ver!"},{"n":10,"t":"İçine ürperti düşen, öğüt alacaktır."},{"n":11,"t":"İçi kararmış bedbaht ise ondan kaçınacaktır."},{"n":12,"t":"En büyük ateşe girer o."},{"n":13,"t":"Sonra orada ne ölür ne de hayat bulur."},{"n":14,"t":"Benliğini arındıran/zekât veren, kurtuluşa gerçekten ermiştir."},{"n":15,"t":"Rabbinin adını anmış, namaz kılmıştır/dua etmiştir o."},{"n":16,"t":"Doğrusu şu ki, siz şu iğreti hayatı yeğliyorsunuz."},{"n":17,"t":"Oysaki sonraki hayat daha mutlu, daha kalıcıdır."},{"n":18,"t":"Hiç kuşkusuz, bu Kur'an, ilk sayfalarda da elbette vardır."},{"n":19,"t":"İbrahim'in ve Mûsa'nın sayfalarında."}],[{"n":1,"t":"Geldi mi sana Ğaşiye'nin/her şeyi her yandan sarıp kaplayacak olanın haberi!"},{"n":2,"t":"Yüzler vardır o gün zilletle öne eğilmiştir."},{"n":3,"t":"Çalışmış, boşa yorulmuştur."},{"n":4,"t":"Kızışmış bir ateşe dalarlar."},{"n":5,"t":"Ateşimsi bir kaynaktan sulanırlar."},{"n":6,"t":"Yırtıcı bir dikenden başka yemek yoktur onlar için."},{"n":7,"t":"Ne semirtir ne açlıktan kurtarır."},{"n":8,"t":"Yüzler de vardır o gün, nimetlerle mutlu."},{"n":9,"t":"Emek ve gayreti yüzünden hoşnuttur."},{"n":10,"t":"Yüksek bir bahçededir;"},{"n":11,"t":"Hiçbir boş söz işitmez orada,"},{"n":12,"t":"Akıp duran bir pınar vardır orada,"},{"n":13,"t":"Yüksek sedirler vardır orada,"},{"n":14,"t":"Hizmete sunulmuş kadehler,"},{"n":15,"t":"Sıra sıra dizilmiş yastıklar,"},{"n":16,"t":"Serilmiş seçme döşekler."},{"n":17,"t":"Bakmıyorlar mı o deveye, nasıl yaratıldı!"},{"n":18,"t":"Ve göğe ki, nasıl yükseltildi!"},{"n":19,"t":"Ve dağlara ki, nasıl dikildi!"},{"n":20,"t":"Ve yere, nasıl yayılıp döşendi!"},{"n":21,"t":"Artık uyar/düşündür! Çünkü sen bir uyarıcı/düşündürücüsün."},{"n":22,"t":"Üzerlerine musallat bir despot değilsin."},{"n":23,"t":"Tersine giden, nankörlük eden başka."},{"n":24,"t":"Allah, böylesine en büyük azapla azap edecektir."},{"n":25,"t":"Hiç kuşkusuz, onların dönüşleri bizedir."},{"n":26,"t":"Bunun ardından, hesapları da bizim elimizde olacaktır."}],[{"n":1,"t":"Yemin olsun tan yerinin ağırma vaktine,"},{"n":2,"t":"On geceye,"},{"n":3,"t":"Çifte ve teke,"},{"n":4,"t":"Yola koyulduğu zaman geceye."},{"n":5,"t":"Nasıl, bunlarda akıl sahibi için bir yemin var mı?"},{"n":6,"t":"Görmedin mi ne yaptı Rabbin Âd kavmine?"},{"n":7,"t":"Sütunlarla dolu İrem'e,"},{"n":8,"t":"Ki beldeler içinde onun benzeri yaratılmamıştı."},{"n":9,"t":"Ve ne yaptı vadide kayaları oyan Semûd kavmine?"},{"n":10,"t":"Ve kazıklar sahibi Firavun'a."},{"n":11,"t":"Bunlar, ülkelerde azıp zulmetmişlerdi."},{"n":12,"t":"Ve oralarda bozgunu çoğaltmışlardı."},{"n":13,"t":"Bu yüzden Rabbin, üzerlerine azap kamçısını yağdırıverdi."},{"n":14,"t":"Çünkü Rabbin tam gözetleme yerindedir/tam bir biçimde gözetlemektedir."},{"n":15,"t":"İnsan böyledir; Rabbi kendisini deneyip de ona cömert davranır, nimet yağdırırsa: \"Rabbim bana ikramda bulundu!\" der."},{"n":16,"t":"Ama Rabbi onu sıkıntıya uğratıp rızkını ölçüye bağlarsa: \"Rabbim bana ihanet etti!\" der."},{"n":17,"t":"Doğrusu şu ki, siz yetime ikramda bulunmuyorsunuz."},{"n":18,"t":"Yoksulun doyurulmasını teşvik etmiyorsunuz."},{"n":19,"t":"Mirası derleyip toplayıp yiyorsunuz."},{"n":20,"t":"Malı, devşirip depolatacak bir sevgiyle seviyorsunuz."},{"n":21,"t":"İş böyle gitmeyecektir! Yer birbirine çarpılıp dümdüz hale getirildiğinde,"},{"n":22,"t":"Rabbin gelip melekler saf saf dizildiğinde,"},{"n":23,"t":"O gün cehennem de getirilir. İşte o gün düşünüp anlar insan. Ama düşünüp hatırlamanın ona ne yararı var!"},{"n":24,"t":"Der ki: \"Keşke şu hayatım için önder bir şeyler gönderseydim.\""},{"n":25,"t":"O gün hiç kimse O'nun azabı gibi azap edemez."},{"n":26,"t":"Ve hiç kimse O'nun vurduğu bağ gibi bağ vuramaz."},{"n":27,"t":"Ey sükûna kavuşmuş benlik!"},{"n":28,"t":"Dön Rabbine, razı etmiş ve razı edilmiş olarak!"},{"n":29,"t":"Gir kullarımın arasına!"},{"n":30,"t":"Gir cennetime!"}],[{"n":1,"t":"Yemin ederim bu kente ki, iş onların sandığı gibi değildir!"},{"n":2,"t":"Sen bu kente mahremsin/bu kente gireceksin."},{"n":3,"t":"Ve doğurana ve doğurduğuna da yemin olsun ki,"},{"n":4,"t":"Biz insanı gerçekten bir sıkıntı ve zorluk içinde yarattık."},{"n":5,"t":"O sanıyor mu ki, hiç kimse ona asla güç yetiremeyecektir!"},{"n":6,"t":"\"Yığınlarla mal telef ettim!\" diyor."},{"n":7,"t":"Hiç kimsenin kendisini görmediğini mi sanıyor?"},{"n":8,"t":"Biz ona vermedik mi iki göz,"},{"n":9,"t":"Bir dil, iki dudak?"},{"n":10,"t":"Kılavuzladık onu iki tepeye."},{"n":11,"t":"Akabeye, sarp yokuşa atılamadı o."},{"n":12,"t":"Sarp yokuşun ne olduğunu sana bildiren nedir?"},{"n":13,"t":"Özgürlüğü zincirlenenin bağını çözmektir o."},{"n":14,"t":"Yahut da açlık ve perişanlık gününde doyurmaktır o,"},{"n":15,"t":"Yakındaki bir yetimi,"},{"n":16,"t":"Yahut ezilmiş-boynu bükük bir yoksulu."},{"n":17,"t":"Sonra da iman eden ve birbirlerine sabrı öneren, merhameti öneren kişilerden olmaktır o."},{"n":18,"t":"İşte böyleleridir uğur ve bereket dostları."},{"n":19,"t":"Bizim ayetlerimizi tanımayanlara gelince bunlar; şomluk, uğursuzluk yâranıdır."},{"n":20,"t":"Bunların üzerine, kilitlenecek bir ateş gelecektir."}],[{"n":1,"t":"Yemin olsun Güneş'e ve ışığının parladığı kuşluk vaktine,"},{"n":2,"t":"Onu izlediğinde Ay'a,"},{"n":3,"t":"Onu iyice açtığı vakit gündüze,"},{"n":4,"t":"Ve onu sarıp sarmaladığı zaman geceye."},{"n":5,"t":"Göğe ve onu kurana,"},{"n":6,"t":"Yere ve onu döşeyene."},{"n":7,"t":"Nefse ve onu düzgün bir biçimde şekillendirene."},{"n":8,"t":"Ardından da ona bozukluğunu ve takvasını ilham edene ki,"},{"n":9,"t":"Benliği temizleyip arındıran, gerçekten kurtulmuştur."},{"n":10,"t":"Onu kirletip örtense kayba uğramıştır."},{"n":11,"t":"Semûd kavmi, azgınlığı yüzünden yalanladı."},{"n":12,"t":"En haydutları ortaya fırladığı zaman,"},{"n":13,"t":"Allah'ın elçisi onlara şöyle demişti: \"Allah'ın devesini ve onun su içme hakkını koruyun.\""},{"n":14,"t":"Fakat elçiye inanmadılar da deveyi devirip boğazladılar. Bunun üzerine, Rableri onların günahlarını kendi başlarına geçirdi de o yurdu dümdüz etti."},{"n":15,"t":"Allah, işin sonundan korkacak değil ya!"}],[{"n":1,"t":"Yemin olsun bürüyüp örttüğü zaman geceye,"},{"n":2,"t":"Ve parıldadığı zaman gündüze,"},{"n":3,"t":"Yemin olsun erkeği de dişiyi de yaratana,"},{"n":4,"t":"Ki sizin emek ve gayretiniz mutlaka dağınık ve parça parçadır."},{"n":5,"t":"Kim verir ve sakınırsa,"},{"n":6,"t":"Ve güzeli doğrularsa,"},{"n":7,"t":"Biz ona, en kolay olanı kolaylayacağız."},{"n":8,"t":"Ama kim cimriliğe sapar ve kendisini tüm ihtiyaçların üstünde görür,"},{"n":9,"t":"Ve güzelliği yalanlarsa,"},{"n":10,"t":"Biz onu, en zor olana sevk edeceğiz."},{"n":11,"t":"Aşağı yuvarlandığında malı onu kurtarmayacaktır."},{"n":12,"t":"Yemin olsun, doğruya ve güzele kılavuzlamak sadece bizim işimizdir."},{"n":13,"t":"Sonrası da öncesi de sadece bizimdir."},{"n":14,"t":"Ben sizi, köpürerek yanan bir ateşe karşı uyardım."},{"n":15,"t":"Şiddete çok düşkün bedbahttan başkası girmez ona."},{"n":16,"t":"Yalanlamış, sırtını dönmüştü o."},{"n":17,"t":"İyice sakınan da ondan uzak tutulur."},{"n":18,"t":"O ki, temizlenip arınsın diye malını verir."},{"n":19,"t":"Onun katında hiç kimsenin, karşılığı verilecek bir nimeti yoktur/hiç kimsenin ona, karşılık olarak verilecek bir nimeti yoktur."},{"n":20,"t":"Yüceler yücesi Rabbinin yüzünü özleyip istemek için veren hariç."},{"n":21,"t":"Yakında mutlaka hoşnut olacaktır."}],[{"n":1,"t":"Yemin olsun kuşluk vaktine,"},{"n":2,"t":"Gelip oturduğu vakit geceye ki,"},{"n":3,"t":"Rabbin seni terk etmedi, sana darılmadı da."},{"n":4,"t":"Sonrası/âhiret/gelecek senin için öncesinden/dünyadan/geçmişten elbette ki daha mutlu-kutlu olacaktır."},{"n":5,"t":"Rabbin sana verecek de sen hoşnut olacaksın!"},{"n":6,"t":"O seni bir yetim olarak bulup da barınağa kavuşturmadı mı?"},{"n":7,"t":"Seni şaşırmış olarak bulup da kılavuzluğunu üstlenmedi mi?"},{"n":8,"t":"Seni aile geçindirme zorluğu içinde bulup da zengin etmedi mi?"},{"n":9,"t":"O halde, yetimi örseleme!"},{"n":10,"t":"Yoksulu/bir şey isteyeni azarlama!"},{"n":11,"t":"Ve Rabbinin nimetini söz ve fiillerinle dile getir!"}],[{"n":1,"t":"Açıp genişletmedik mi senin göğsünü!"},{"n":2,"t":"İndirmedik mi üzerinden ağır yükünü!"},{"n":3,"t":"Ki o, belini çatırdatmıştı senin."},{"n":4,"t":"Ve yüceltmedik mi senin şanını!"},{"n":5,"t":"Demek ki, zorluğun yanında bir kolaylık mutlaka var!"},{"n":6,"t":"Zorluğun yanında bir kolaylık muhakkak var!"},{"n":7,"t":"O halde, bir iş ve oluştan boşalır boşalmaz yeni bir işe koyulup yorul!"},{"n":8,"t":"Ve yalnız Rabbine yönelip doğrul!"}],[{"n":1,"t":"Yemin olsun incire, zeytine,"},{"n":2,"t":"Tûr-i Sîna'ya,"},{"n":3,"t":"Ve şu güvenli kente ki,"},{"n":4,"t":"Biz insanı, gerçekten en güzel bir biçimde yarattık."},{"n":5,"t":"Sonra da onu düşüklerin en düşüğüne/aşağıların en aşağısına çevirip attık."},{"n":6,"t":"İman edip hayra ve barışa yönelik iş üretenler müstesna. Bunlar için kesintisiz bir ödül vardır."},{"n":7,"t":"Böyle iken dini sana ne yalanlatır?"},{"n":8,"t":"Allah, yargıçların en güzel hüküm vereni değil mi?"}],[{"n":1,"t":"Yaratan Rabbinin adıyla oku/çağır!"},{"n":2,"t":"İnsanı, embriyodan/ilişip yapışan bir sudan/sevgi ve ilgiden/husûmetten yarattı."},{"n":3,"t":"Oku! Rabbin Ekrem'dir/en büyük cömertliğin sahibidir."},{"n":4,"t":"O'dur kalemle öğreten!"},{"n":5,"t":"İnsana bilmediğini öğretti."},{"n":6,"t":"İş, sanıldığı gibi değil! İnsan gerçekten azar:"},{"n":7,"t":"Kendisini her türlü ihtiyacın üstünde görmüştür."},{"n":8,"t":"Oysaki, dönüş yalnız Rabbinedir!"},{"n":9,"t":"Gördün mü o yasaklayanı,"},{"n":10,"t":"Bir kulu namaz kılarken/dua ederken;"},{"n":11,"t":"Gördün mü! Ya o iyilik ve doğruluk üzere ise?!"},{"n":12,"t":"Ya o, takvayı emrediyorsa!"},{"n":13,"t":"Gördün mü! Ya şu yalanlamış, sırt dönmüşse!"},{"n":14,"t":"Bilmedi mi ki Allah gerçekten görür!"},{"n":15,"t":"İş, sandığı gibi değil! Eğer vazgeçmezse yemin olsun, o alnı mutlaka tutup sürteceğiz!"},{"n":16,"t":"O yalancı, o günahkâr alnı."},{"n":17,"t":"Hadi çağırsın derneğini/kurultayını!"},{"n":18,"t":"Biz de çağıracağız zebanileri!"},{"n":19,"t":"Sakın, sakın! Ona boyun eğme; secde et ve yaklaş!"}],[{"n":1,"t":"Biz onu Kadir Gecesi'nde indirdik."},{"n":2,"t":"Kadir Gecesi'nin niteliğini sana gösteren nedir?"},{"n":3,"t":"Kadir Gecesi bin aydan daha hayırlıdır!"},{"n":4,"t":"Melekler ve Rûh, Rablerinin izniyle o gecede her iş için iner de iner!"},{"n":5,"t":"Bir esenlik ve huzur vardır; sürüp gider o, tan yeri ağarıncaya kadar!"}],[{"n":1,"t":"Ehlikitap'tan küfre sapanlarla müşrikler, kendilerine beyyine/açık kanıt gelinceye kadar çözülüp ayrılacak değillerdi."},{"n":2,"t":"Allah tarafından gönderilen, tertemiz sayfalar okuyan bir resul gelinceye dek."},{"n":3,"t":"O sayfalar içindedir dosdoğru-eskimez kitaplar."},{"n":4,"t":"Kitap verilmiş olanlar, kendilerine beyyine/açık delil geldikten sonradır ki parçalanıp bölündüler."},{"n":5,"t":"Oysaki onlara, dini yalnız O'na özgüleyerek, dosdoğru yürüyen kişiler halinde sadece Allah'a ibadet etmeleri, namazı/duayı yerine getirmeleri, zekâtı vermeleri emredilmişti. İşte budur doğru, eskimez ve aşınmaz din."},{"n":6,"t":"Ehlikitap'ın küfre sapanlarıyla müşrikler, içinde sürekli kalıcılar olarak cehennem ateşindedirler. İşte onlardır yaratılmışların en şerlisi."},{"n":7,"t":"İman edip hayra ve barışa yönelik fiiller sergileyenlere gelince, işte onlardır yaratılmışların en hayırlısı."},{"n":8,"t":"Onların, Rableri katındaki ödülleri, altlarından ırmaklar akan Adn cennetleri/temiz-bereketli bahçelerdir. Sürekli kalacaklardır orada. Allah onlardan razı olmuştur, onlar da O'ndan razı olmuşlardır. İşte bu, içi ürpererek Rabbine saygı duyan kişi içindir."}],[{"n":1,"t":"Yerküre, o sarsıntıyla sarsıldığı zaman,"},{"n":2,"t":"Ve toprak, ağırlıklarını çıkardığı zaman,"},{"n":3,"t":"Ve insan: \"Ne oluyor buna?\" dediği zaman,"},{"n":4,"t":"İşte o gün yerküre, tüm haberlerini söyler/anlatır."},{"n":5,"t":"Çünkü Rabbin ona vahyetmiştir."},{"n":6,"t":"O gün insanlar, yapıp ettikleri kendilerine gösterilsin diye kümeler halinde ortaya fırlayacaklardır."},{"n":7,"t":"Artık, kim bir zerre miktarı hayır üretmişse onu görür."},{"n":8,"t":"Ve kim bir zerre miktarı şer üretmişse onu görür."}],[{"n":1,"t":"Yemin olsun soluyuşlarıyla ses çıkararak koşanlara/nefes nefese saldıranlara,"},{"n":2,"t":"Çakıp çakıp ateş çıkaranlara,"},{"n":3,"t":"Sabahleyin akın edenlere/baskın yapıp toprak fethedenlere,"},{"n":4,"t":"Derken, onunla toz duman çıkaranlara,"},{"n":5,"t":"Derken, onunla bir topluluğun ortasına dalanlara ki,"},{"n":6,"t":"İnsan, Rabbine karşı gerçekten çok nankördür!"},{"n":7,"t":"Ve kendisi de buna iyiden iyiye tanıktır."},{"n":8,"t":"O, mal ve servet arzusu yüzünden alabildiğine katıdır."},{"n":9,"t":"Bilmez mi ki o, kabirler içindekiler dışarı fırlatıldığında,"},{"n":10,"t":"Göğüslerin içindekiler derlenip toplandığında,"},{"n":11,"t":"Hiç kuşkusuz, o gün, Rableri onlardan iyice haberdar olacaktır."}],[{"n":1,"t":"O Kaaria, o şiddetli ses çıkararak çarpan."},{"n":2,"t":"Nedir Kaaria?"},{"n":3,"t":"Kaaria'nın ne olduğunu sana bildiren nedir?"},{"n":4,"t":"O gün insanlar, çırpınarak yayılmış pervaneler gibi olurlar."},{"n":5,"t":"Dağlar, didilmiş renkli yün gibi olur."},{"n":6,"t":"İşte o gün, tartıları ağır basan kişi,"},{"n":7,"t":"Evet o kişi, hoşnutluk verici bir yaşayış içindedir."},{"n":8,"t":"Tartıları hafif çekeninse,"},{"n":9,"t":"Anası, Hâviye'dir."},{"n":10,"t":"Onun ne olduğunu sana bildiren nedir?"},{"n":11,"t":"Kızışmış bir ateştir o!"}],[{"n":1,"t":"Aldatıp oyaladı o çokluk yarışı sizleri,"},{"n":2,"t":"Öyle ki, ziyaret edip saydınız kabirleri."},{"n":3,"t":"Ama iş öyle değil; yakında bileceksiniz!"},{"n":4,"t":"Hayır, hayır! İş öyle değil! Yakında bileceksiniz."},{"n":5,"t":"İş, sizin bildiğiniz gibi değil! Ne olurdu, şaşmaz ve aldatmaz bir bilgiyle bilseydiniz!"},{"n":6,"t":"Yemin olsun, o cehennemi mutlaka göreceksiniz!"},{"n":7,"t":"Yine yemin olsun, onu gözünüzle apaçık göreceksiniz!"},{"n":8,"t":"Sonra o gün, nimetten kesinlikle sorguya çekileceksiniz!"}],[{"n":1,"t":"Yemin olsun zamana/çağa/gündüzün iki ucuna/sabah namazına/ikindi vaktine/Asrısaadet'e ki,"},{"n":2,"t":"İnsan, gerçekten tam bir hüsran içindedir!"},{"n":3,"t":"İnanıp hayra ve barışa yönelik işler yapanlar, birbirlerine hakkı önerenler, birbirlerine sabrı önerenler müstesnadır."}],[{"n":1,"t":"Yazıklar olsun arkadan çekiştirenlerin, kaş göz işareti yapıp alay edenlerin tümüne!"},{"n":2,"t":"O ki, mal biriktirdi, onu saydı da saydı,"},{"n":3,"t":"Sanır ki, malı sonsuzlaştıracaktır kendisini."},{"n":4,"t":"Hayır, iş, sandığı gibi değil! Yemin olsun ki fırlatılıp atılacaktır o kırıp geçirene, yalayıp yutana/Hutame'ye."},{"n":5,"t":"Hutame'nin ne olduğunu sana öğreten nedir?"},{"n":6,"t":"Allah'ın, tutuşturulmuş ateşidir o,"},{"n":7,"t":"Ki tırmanıp işler yüreklere."},{"n":8,"t":"O, onların üzerine kilitlenecektir."},{"n":9,"t":"Uzatılmış sütunlar arasında..."}],[{"n":1,"t":"Görmedin mi ne yaptı Rabbin fil yâranına!"},{"n":2,"t":"Tuzaklarını boşa çıkarmadı mı onların?"},{"n":3,"t":"Gönderdi üzerlerine sürüler halinde kuş,"},{"n":4,"t":"Atıyorlardı onlara kurumuş çamurdan damgalı taş."},{"n":5,"t":"Nihayet, onları yenik ekin yaprağına çevirdi."}],[{"n":1,"t":"Kureyş'i alıştırıp ısındırdığı için,"},{"n":2,"t":"Onları kış ve yaz yolculuğuna alıştırdığı için,"},{"n":3,"t":"Bu evin Rabbine ibadet etsinler!"},{"n":4,"t":"O ki, onları doyurup kurtardı açlıktan ve kendilerini güvene çıkardı korkudan."}],[{"n":1,"t":"Gördün mü o, dini yalan sayanı?"},{"n":2,"t":"İşte odur yetimi itip kakan;"},{"n":3,"t":"Yoksulu doyurmayı özendirmez o."},{"n":4,"t":"Vay haline o namaz kılanların/dua edenlerin ki,"},{"n":5,"t":"Namazlarından/dualarından gaflet içindedir onlar!"},{"n":6,"t":"Riyaya sapandır onlar/gösteriş yaparlar."},{"n":7,"t":"Ve onlar, kamu hakkına/yardıma/zekâta/iyiliğe engel olurlar."}],[{"n":1,"t":"Hiç kuşkusuz, biz verdik sana Kevser'i/iyilik, bereket, mutluluk, güzellik, soy ve aydınlığın tükenmezini."},{"n":2,"t":"O halde, sen de Rabbin için namaz kıl/dua et ve göğsünü gererek dimdik dur/sağ elini sol elinin üzerine koyup kıyam et/namazı vakti girer girmez kıl/kavrayışını bilgi ile derinleştir/eti yenecek hayvan kes!"},{"n":3,"t":"Kuşkun olmasın ki, ebter/soyu kesik, seni kötüleyenin ta kendisidir!"}],[{"n":1,"t":"De ki: \"Ey nankör kâfirler!"},{"n":2,"t":"Kulluk etmem sizin kulluk ettiğinize."},{"n":3,"t":"Siz de ibadet etmezsiniz benim ibadet ettiğime."},{"n":4,"t":"Kul değilim sizin taptığınıza,"},{"n":5,"t":"Ve ibadet edenler değilsiniz benim ibadet ettiğime."},{"n":6,"t":"Sizin dininiz size, benim dinim bana!\""}],[{"n":1,"t":"Allah'ın yardımı ve fetih geldiğinde,"},{"n":2,"t":"Ve insanları kitleler halinde Allah'ın dinine girerken gördüğünde,"},{"n":3,"t":"Tespih et Rabbini O'na hamt ile! Ve O'ndan af dile! Çünkü O, Tevvâb'dır, günahları affeder sınırsız bir şekilde."}],[{"n":1,"t":"Elleri kurusun Ebru Leheb'in; zaten kurudu ya!"},{"n":2,"t":"Ne malı kurtardı onu ne de kazandığı."},{"n":3,"t":"Alevli bir ateşe yaslanacaktır o;"},{"n":4,"t":"Karısı da,"},{"n":5,"t":"Odun hamalı olarak. Gerdanında bir ip olacaktır onun, en sağlam fitillisinden..."}],[{"n":1,"t":"De ki: O, Allah'tır; Ahad'dır, tektir!"},{"n":2,"t":"Allah'tır; Samed'dir/tüm ihtiyaçların, niyetlerin, övgülerin, yakarışların yöneldiği tek kuvvettir!"},{"n":3,"t":"Ne doğurmuştur O, ne doğurulmuştur!"},{"n":4,"t":"Hiç kimse O'nun dengi ve benzeri olmamıştır, olamaz!"}],[{"n":1,"t":"De ki: \"Yarılan karanlıktan çıkan sabahın Rabbine/yarılışlardan fışkıran oluşun Rabbine sığınırım!"},{"n":2,"t":"Yarattıklarının şerrinden,"},{"n":3,"t":"Çöktüğü zaman karanlığın/gelip çattığı zaman göz perdelenmesinin/tutulduğu zaman Ay'ın/battığı zaman Güneş'in/taştığı zaman şehvetin/soktuğu zaman yılanın/ümit kırdığı zaman musibetin şerrinden!"},{"n":4,"t":"Düğümlere üfleyip tüküren üfürükçülerin şerrinden!"},{"n":5,"t":"Kıskandığı zaman hasetçinin şerrinden...\""}],[{"n":1,"t":"De ki: \"İnsanların Rabbine sığınırım!"},{"n":2,"t":"İnsanların yöneticisine, yönlendiricisine,"},{"n":3,"t":"İnsanların ilahına;"},{"n":4,"t":"Kıvrılıp kıvrılıp saklanan, sinip sinip gizlenen vesvesenin/o sinsi, o aldatıcı şeytanın şerrinden,"},{"n":5,"t":"İnsanların göğüslerine kuşkular, kuruntular sokar o;"},{"n":6,"t":"Cinlerden de insanlardan da olur o!\""}]];
